const $ = (id) => document.getElementById(id);

// ---- Debug log ---------------------------------------------------------
// v177: ring buffer for diagnosing "chapter X keeps failing to synthesize"
// reports. Every interesting step in the GitHub fetch → background queue →
// synthesis pipeline writes an entry here. Settings → "View debug log"
// surfaces the buffer in a modal with Copy/Download/Clear actions. The
// failures banner also gets a direct link so the user can go straight
// from "2 chapters failed" to "why."
//
// Cap intentionally generous (1000 entries, FIFO drop) — a typical 50-
// chapter import + retries fits comfortably, and most entries are short
// strings. Data field accepts any JSON-serializable value (objects get
// pretty-printed when rendered).
const _DEBUG_LOG_CAP = 1000;
const _debugLog = [];
function _dlog(category, message, data) {
  // ISO timestamp is sortable + copy/pasteable into bug reports.
  const entry = {
    t: new Date().toISOString(),
    cat: category || "general",
    msg: String(message || ""),
  };
  // v225.tn74 (#556): stamp the UI mode on every entry. Mode-gated
  // features behave differently in Simple / Standard / Author, and
  // bug reports were missing this context — e.g. "tap a flag does
  // nothing" diagnosed differently if the user was in Standard
  // (where the feature might not be wired) vs. Author (where it
  // should be active). Read via getUIMode() if available; fall
  // back to "?" so the dlog never throws.
  try {
    if (typeof getUIMode === "function") {
      entry.mode = getUIMode();
    }
  } catch {
    entry.mode = "?";
  }
  if (data !== undefined) entry.data = data;
  _debugLog.push(entry);
  // FIFO drop when over the cap. Splice from the front so the most
  // recent context (where the failure actually surfaced) is always
  // preserved at the tail of the buffer.
  if (_debugLog.length > _DEBUG_LOG_CAP) {
    _debugLog.splice(0, _debugLog.length - _DEBUG_LOG_CAP);
  }
  // Mirror to console at info level so developers debugging in DevTools
  // can correlate timestamps. Skip when data is undefined to avoid the
  // "[object Object]" noise on bare messages.
  try {
    if (data !== undefined) {
      console.info(`[dlog/${entry.cat}] ${entry.msg}`, data);
    } else {
      console.info(`[dlog/${entry.cat}] ${entry.msg}`);
    }
  } catch {}
}

// v225v4.45 (#709 follow-up): layout probe. Capture viewport + bounding
// rects + computed visibility for every element that contributes to
// phone bottom-stack / status-banner layout. Two-Android-phone bug
// (#709) shows tag row + player + sync banner + a mystery × stacked
// when a library card opens — but existing dlogs don't capture layout,
// so we couldn't see which CSS rule was misbehaving. This probe runs
// once after loadClip's first paint, plus on-demand from the Force
// Update / Push Debug button so it picks up any later state.
//
// IMPORTANT: read getBoundingClientRect() lazily inside a try/catch —
// if an element is hidden via [hidden] attr the rect is all zeros (not
// an error), but a missing element returns null from getElementById and
// would NPE on .getBoundingClientRect(). Belt-and-suspenders.
function _dlogLayoutProbe(label) {
  try {
    const probe = {
      label: label || "load",
      // Viewport + DPR. visualViewport is what the WebView ACTUALLY
      // paints into (excluding system bars on Android); innerHeight is
      // the layout viewport. Bug is likely in the gap between the two.
      viewport: {
        innerWidth: window.innerWidth,
        innerHeight: window.innerHeight,
        outerWidth: window.outerWidth,
        outerHeight: window.outerHeight,
        devicePixelRatio: window.devicePixelRatio,
        vv: window.visualViewport
          ? {
              w: Math.round(window.visualViewport.width),
              h: Math.round(window.visualViewport.height),
              ot: Math.round(window.visualViewport.offsetTop),
              ol: Math.round(window.visualViewport.offsetLeft),
              scale: window.visualViewport.scale,
            }
          : null,
        // CSS safe-area-inset-bottom (Android gesture bar / iOS home
        // indicator). Read from a probe div with env() so we get the
        // resolved pixel value. Falls back to root padding if no probe.
        safeBottom: (() => {
          try {
            const d = document.createElement("div");
            d.style.cssText =
              "position:fixed;left:0;bottom:0;height:env(safe-area-inset-bottom,0px);visibility:hidden;";
            document.body.appendChild(d);
            const h = d.getBoundingClientRect().height;
            d.remove();
            return Math.round(h);
          } catch {
            return -1;
          }
        })(),
      },
      // body data-* drives every CSS gate (mode, clip loaded, drawer
      // open, ebook kind, etc.). A wrong attr = wrong selector wins.
      body: {
        dataset: { ...(document.body.dataset || {}) },
        classes: document.body.className,
      },
    };

    // Per-element snapshot. Order = visual stack from top to bottom on
    // phone. Adding new fixed-position elements? Add them here too.
    const ids = [
      "phone-header",
      "status",
      "mini-player",
      "reading-view",
      "player-card",
      "phone-tag-row",
      "phone-pullup",
      "phone-pullup-scrim",
      "phone-menu",
      "phone-menu-scrim",
      "bookmark-editor",
      "annotate-palette",
      "first-clip-tour",
    ];
    probe.elements = {};
    for (const id of ids) {
      const el = document.getElementById(id);
      if (!el) {
        probe.elements[id] = "missing";
        continue;
      }
      const r = el.getBoundingClientRect();
      const cs = window.getComputedStyle(el);
      probe.elements[id] = {
        rect: {
          t: Math.round(r.top),
          l: Math.round(r.left),
          r: Math.round(r.right),
          b: Math.round(r.bottom),
          w: Math.round(r.width),
          h: Math.round(r.height),
        },
        display: cs.display,
        visibility: cs.visibility,
        opacity: cs.opacity,
        position: cs.position,
        zIndex: cs.zIndex,
        // padding-bottom matters on #reading-view because text needs
        // clearance for the tag row + player. If this is 0, that's the
        // bug.
        paddingBottom: cs.paddingBottom,
        hidden: el.hasAttribute("hidden"),
        ariaHidden: el.getAttribute("aria-hidden"),
        // Trim classList to first ~6 entries to keep log compact.
        classes: (el.className || "").toString().split(/\s+/).slice(0, 8).join(" "),
      };
    }

    // Overlap detection. For each pair of visible elements, see if
    // their rects intersect. This is the "self-diagnosing" payload —
    // the rogue × stacking the player will show up here as a pair.
    const visible = Object.entries(probe.elements)
      .filter(
        ([, v]) =>
          v &&
          typeof v === "object" &&
          v.display !== "none" &&
          v.visibility !== "hidden" &&
          parseFloat(v.opacity || "1") > 0.01 &&
          !v.hidden &&
          v.rect.w > 0 &&
          v.rect.h > 0,
      );
    probe.overlaps = [];
    for (let i = 0; i < visible.length; i++) {
      for (let j = i + 1; j < visible.length; j++) {
        const [aId, a] = visible[i];
        const [bId, b] = visible[j];
        const ar = a.rect;
        const br = b.rect;
        const overlaps =
          ar.l < br.r && br.l < ar.r && ar.t < br.b && br.t < ar.b;
        if (overlaps) {
          probe.overlaps.push(`${aId} ∩ ${bId}`);
        }
      }
    }

    _dlog("layout", "probe", probe);
  } catch (e) {
    // Never let the probe break loadClip. Log the failure so we know
    // the instrumentation itself misfired.
    try {
      _dlog("layout", "probe-error", { err: String(e && e.message) });
    } catch {}
  }
}

// v225eg (#624): cross-frame dlog bridge for the manual's walkthrough
// engine (§10 Tutorials). The manual.html iframe wtlog() helper
// postMessages diagnostic entries here; we re-emit them through the
// main _dlog so the standard download-debug-log path includes them.
// Also sweep any localStorage breadcrumbs the iframe parked there
// (works even if postMessage was blocked, e.g. parsed-section phone
// viewer where the script never gets a parent frame).
try {
  window.addEventListener("message", (e) => {
    const m = e && e.data;
    if (!m || m.type !== "tutorial-dlog" || !m.entry) return;
    const entry = m.entry;
    _dlog(
      entry.category || "tutorial",
      entry.message || "",
      entry.data || undefined,
    );
  });
  // Sweep breadcrumbs from previous opens.
  const TUT_KEY = "narrative.tutorialLog";
  const breadcrumbs = JSON.parse(localStorage.getItem(TUT_KEY) || "[]");
  if (Array.isArray(breadcrumbs) && breadcrumbs.length) {
    for (const entry of breadcrumbs) {
      if (!entry) continue;
      _dlog(
        (entry.category || "tutorial") + ":crumb",
        entry.message || "",
        entry.data || undefined,
      );
    }
    try { localStorage.removeItem(TUT_KEY); } catch {}
  }
} catch (e) {
  console.warn("[tutorial-dlog bridge] setup failed:", e);
}

// ---- API key (X-Narrative-Key) -----------------------------------------
// When the server is started with NARRATIVE_KEY set (typical for the public
// tunnel), every /api/* request needs an X-Narrative-Key header that matches.
// We wrap window.fetch once so the rest of the app doesn't have to think
// about it: stored key gets attached automatically, and a 401 triggers a
// single prompt + retry.
const API_KEY_STORAGE = "narrative.apiKey";

function getApiKey() {
  try { return localStorage.getItem(API_KEY_STORAGE) || ""; } catch { return ""; }
}
function setApiKey(key) {
  try {
    if (key) localStorage.setItem(API_KEY_STORAGE, key);
    else localStorage.removeItem(API_KEY_STORAGE);
  } catch {}
}

// v4.108 (2FA): the "2FA-passed" session token. Issued by /api/2fa/verify
// after a valid code, sent as X-Narrative-2FA on every /api/* request so a
// 2FA-enrolled tenant isn't re-prompted each call ("remember this device").
// Server-signed + expiring; storing it client-side only grants the holder
// what they already authenticated for.
const TOTP_TOKEN_STORAGE = "narrative.2faToken";

function getTotpToken() {
  try { return localStorage.getItem(TOTP_TOKEN_STORAGE) || ""; } catch { return ""; }
}
function setTotpToken(token) {
  try {
    if (token) localStorage.setItem(TOTP_TOKEN_STORAGE, token);
    else localStorage.removeItem(TOTP_TOKEN_STORAGE);
  } catch {}
}

// v4.51 (#562 follow-up): prompt for the API key via a real <dialog>
// element instead of window.prompt(). Tauri WebView2 on Windows
// silently suppresses window.prompt() — the dialog never opens and
// the call returns null. Switch key then looked broken: confirm()
// fires, page reloads, fetch wrapper 401s, _promptForApiKey() returns
// null with no UI, no key is stored, /api/voices stays in retry loop
// forever. A real <dialog> works in every webview we ship to.
//
// Returns a Promise that resolves with the trimmed key string, or
// null if the user cancelled / hit Esc. Re-entrant: concurrent 401s
// share the same in-flight promise so we never stack prompts.
let _keyPromptInFlight = null;
function _promptForApiKey() {
  if (_keyPromptInFlight) return _keyPromptInFlight;

  const dlg = document.getElementById("key-prompt-dialog");
  if (!dlg || typeof dlg.showModal !== "function") {
    // Fallback: dialog markup missing or <dialog> unsupported.
    // window.prompt works on regular browsers — just not in Tauri
    // WebView2 — so we still try it as a last resort.
    try {
      const k = window.prompt(
        "Paste your X-Narrative-Key value:",
        getApiKey()
      );
      if (k && k.trim()) {
        setApiKey(k.trim());
        return Promise.resolve(k.trim());
      }
    } catch {}
    return Promise.resolve(null);
  }

  _keyPromptInFlight = new Promise((resolve) => {
    const input = document.getElementById("key-prompt-input");
    const cancelBtn = document.getElementById("key-prompt-cancel");
    const form = dlg.querySelector("form");

    if (input) input.value = getApiKey() || "";

    let settled = false;
    const finish = (key) => {
      if (settled) return;
      settled = true;
      _keyPromptInFlight = null;
      try { dlg.close(); } catch {}
      resolve(key);
    };

    const onCancel = (e) => {
      e.preventDefault();
      finish(null);
    };
    const onSubmit = (e) => {
      const k = (input && input.value || "").trim();
      if (k) {
        setApiKey(k);
        finish(k);
      } else {
        // Empty submit treated as cancel — caller will re-prompt on
        // the next 401 if they need another shot.
        finish(null);
      }
    };
    const onClose = () => {
      // Esc key closes the native dialog without firing submit. We
      // resolve here so the caller always gets a verdict.
      finish(null);
    };

    cancelBtn && cancelBtn.addEventListener("click", onCancel, { once: true });
    form && form.addEventListener("submit", onSubmit, { once: true });
    dlg.addEventListener("close", onClose, { once: true });

    try {
      dlg.showModal();
      if (input) {
        // requestAnimationFrame so the field is painted before focus,
        // otherwise some webviews skip the autofocus.
        requestAnimationFrame(() => {
          try { input.focus(); input.select(); } catch {}
        });
      }
    } catch (e) {
      console.warn("[key-prompt] showModal failed:", e);
      _keyPromptInFlight = null;
      resolve(null);
    }
  });

  return _keyPromptInFlight;
}

// v4.108 (2FA): prompt for a 6-digit authenticator code (or a recovery
// code) when the server answers `2fa_required`. Mirrors _promptForApiKey:
// a real <dialog> (Tauri-safe), re-entrant so concurrent 2fa_required
// responses share one prompt. Resolves to the trimmed code, or null on
// cancel/Esc.
let _totpPromptInFlight = null;
function _promptForTotpCode() {
  if (_totpPromptInFlight) return _totpPromptInFlight;

  const dlg = document.getElementById("totp-prompt-dialog");
  if (!dlg || typeof dlg.showModal !== "function") {
    try {
      const c = window.prompt("Enter your two-step verification code:");
      return Promise.resolve(c && c.trim() ? c.trim() : null);
    } catch {}
    return Promise.resolve(null);
  }

  _totpPromptInFlight = new Promise((resolve) => {
    const input = document.getElementById("totp-prompt-input");
    const cancelBtn = document.getElementById("totp-prompt-cancel");
    const errEl = document.getElementById("totp-prompt-error");
    const form = dlg.querySelector("form");

    if (input) input.value = "";
    if (errEl) errEl.hidden = true;

    let settled = false;
    const finish = (code) => {
      if (settled) return;
      settled = true;
      _totpPromptInFlight = null;
      try { dlg.close(); } catch {}
      resolve(code);
    };
    const onCancel = (e) => { e.preventDefault(); finish(null); };
    const onSubmit = (e) => {
      const c = (input && input.value || "").trim();
      finish(c || null);
    };
    const onClose = () => finish(null);

    cancelBtn && cancelBtn.addEventListener("click", onCancel, { once: true });
    form && form.addEventListener("submit", onSubmit, { once: true });
    dlg.addEventListener("close", onClose, { once: true });

    try {
      dlg.showModal();
      if (input) requestAnimationFrame(() => { try { input.focus(); } catch {} });
    } catch (e) {
      console.warn("[totp-prompt] showModal failed:", e);
      _totpPromptInFlight = null;
      resolve(null);
    }
  });

  return _totpPromptInFlight;
}

// v225v4.27 (#704): when the page is loaded from the Tauri desktop
// shell, the window origin is tauri://localhost (Linux/macOS) or
// https://tauri.localhost (Windows). Relative URLs like /api/foo
// would resolve against THAT origin and 404, because the API only
// lives at narrative-alpha.fly.dev. So in Tauri context we rewrite
// /api/* to the absolute Fly URL. The PWA at narrative-alpha.fly.dev
// is same-origin — API_ORIGIN stays empty and fetch behavior is
// unchanged.
//
// Detection: __TAURI_INTERNALS__ is the canonical Tauri v2 global,
// injected before any user JS runs. Belt-and-suspenders, also check
// the location protocol for `tauri:` and the host for `tauri.` in
// case some future build doesn't expose the global (Tauri does not
// guarantee that with withGlobalTauri: false, even though the
// internals always seem to land).
const API_ORIGIN = (() => {
  try {
    if (typeof window === "undefined") return "";
    if (window.__TAURI_INTERNALS__) return "https://narrative-alpha.fly.dev";
    const loc = window.location || {};
    if (loc.protocol === "tauri:") return "https://narrative-alpha.fly.dev";
    if (typeof loc.hostname === "string" && /\btauri\.localhost$/.test(loc.hostname)) {
      return "https://narrative-alpha.fly.dev";
    }
  } catch {}
  return "";
})();

// v225v4.28 (#706): native menu bridge. Rust dispatches a CustomEvent
// `narrative:menu` with detail.action when a menu item fires; this
// listener routes those actions to existing app affordances. Web users
// never see the event — only the Tauri shell ships a native menu —
// so the listener is a no-op outside Tauri.
window.addEventListener("narrative:menu", (e) => {
  const action = (e && e.detail && e.detail.action) || "";
  const click = (sel) => {
    const el = typeof sel === "string" ? document.querySelector(sel) : sel;
    if (el && typeof el.click === "function") {
      el.click();
      return true;
    }
    return false;
  };
  switch (action) {
    case "new":
      click("#clear-btn");
      break;
    case "reload":
      try { window.location.reload(); } catch {}
      break;
    case "force-update":
      click("#settings-trigger") ||
        click('button[data-action="open-settings"]');
      // Settings dialog opens asynchronously; defer the inner click
      // by one frame so the Force-update button has rendered.
      setTimeout(() => click("#settings-force-update"), 250);
      break;
    case "book-view":
      click("#book-view-toggle");
      break;
    case "manual":
      click('a[href="/manual.html"]');
      break;
    case "whats-new":
      click('a[href="/whats-new.html"]');
      break;
    case "about":
      try {
        const v =
          (document.getElementById("settings-version-tag") || {}).textContent ||
          "";
        window.alert(
          "Narrative " + v + "\n\nWrite. Listen. Revise.\n\nThe writer's audiobook tool."
        );
      } catch {}
      break;
    default:
      try { console.warn("narrative:menu unknown action", action); } catch {}
  }
});

// v225v4.29 (#707): updater feedback. The Rust side fires CustomEvents
// in response to Help → Check for updates… and the startup poll. Keeping
// the flow Rust-driven means we never have to ship the Tauri updater JS
// SDK alongside the bundler-less webview.
//
// v0.1.4 (#868): blocking alert("Update available...") replaced with a
// non-modal top-of-window progress banner that updates in real time as
// the .exe downloads. The Rust side fires:
//   - narrative:update-available  → show banner
//   - narrative:update-progress   → update bar + % text (throttled to 1%)
//   - narrative:update-installing → swap copy to "Installing — restart…"
//   - narrative:update-error      → tear banner down + alert the error
// `update-none` keeps the alert() because that path is only reached via
// the manual "Check for updates…" menu item, where the user is explicitly
// expecting a confirmation that they're up to date.
function _updateBannerEnsure() {
  let banner = document.getElementById("update-banner");
  if (banner) return banner;
  banner = document.createElement("div");
  banner.id = "update-banner";
  banner.style.cssText =
    "position:fixed;top:0;left:0;right:0;background:var(--bg-card,#141a30);" +
    "color:var(--fg,#e7ecff);padding:10px 16px;z-index:99999;font-size:14px;" +
    "display:flex;align-items:center;gap:12px;border-bottom:1px solid var(--accent,#7c9cff);" +
    "box-shadow:0 2px 8px rgba(0,0,0,0.35);font-family:inherit;";
  banner.innerHTML =
    '<span id="update-banner-text" style="flex:0 0 auto;font-weight:600">Update available</span>' +
    '<div style="flex:1;height:6px;background:rgba(255,255,255,0.15);border-radius:3px;overflow:hidden">' +
    '<div id="update-banner-bar" style="height:100%;background:var(--accent,#7c9cff);width:0%;transition:width 0.25s"></div>' +
    "</div>" +
    '<span id="update-banner-pct" style="flex:0 0 auto;font-variant-numeric:tabular-nums;color:var(--fg-dim,#97a0c9);min-width:5em;text-align:right">0%</span>';
  document.body.appendChild(banner);
  return banner;
}
window.addEventListener("narrative:update-available", (e) => {
  const ver = (e && e.detail && e.detail.version) || "(unknown)";
  _updateBannerEnsure();
  const text = document.getElementById("update-banner-text");
  if (text) text.textContent = "Update v" + ver + " — downloading…";
});
window.addEventListener("narrative:update-progress", (e) => {
  _updateBannerEnsure();
  const d = (e && e.detail) || {};
  const pct = d.pct != null ? d.pct : 0;
  const bar = document.getElementById("update-banner-bar");
  const pctEl = document.getElementById("update-banner-pct");
  if (bar) bar.style.width = pct + "%";
  if (pctEl) {
    if (d.total) {
      const dlKB = Math.floor((d.downloaded || 0) / 1024);
      const totalKB = Math.floor(d.total / 1024);
      pctEl.textContent = pct + "% · " + dlKB + " / " + totalKB + " KB";
    } else {
      pctEl.textContent = pct + "%";
    }
  }
});
window.addEventListener("narrative:update-installing", () => {
  _updateBannerEnsure();
  const text = document.getElementById("update-banner-text");
  const pctEl = document.getElementById("update-banner-pct");
  const bar = document.getElementById("update-banner-bar");
  if (text) text.textContent = "Installing — Narrative will restart…";
  if (pctEl) pctEl.textContent = "";
  if (bar) bar.style.width = "100%";
});
window.addEventListener("narrative:update-none", () => {
  try {
    window.alert("You're on the latest version of Narrative.");
  } catch {}
});
window.addEventListener("narrative:update-error", (e) => {
  const msg = (e && e.detail && e.detail.msg) || "Unknown error";
  const banner = document.getElementById("update-banner");
  if (banner) banner.remove();
  try {
    window.alert("Update failed.\n\n" + msg);
  } catch {}
});

// v225v4.33: bookmark drawer toggle. Clicking the 🔖 Bookmarks chip in
// the player action row flips a body data attribute that the CSS uses
// to slide the fixed-bottom drawer up. Escape closes; clicking the
// chip again toggles. We intentionally don't use a scrim — the drawer
// is non-modal so the user can keep listening / editing the textarea
// while it's open.
(() => {
  const setOpen = (open) => {
    document.body.dataset.bookmarksDrawerOpen = open ? "1" : "0";
    const toggle = document.getElementById("bookmarks-drawer-toggle");
    if (toggle) toggle.setAttribute("aria-expanded", open ? "true" : "false");
  };
  const toggle = () => {
    const isOpen = document.body.dataset.bookmarksDrawerOpen === "1";
    setOpen(!isOpen);
  };
  // v225v4.40: dlog instrumentation. The v4.38 head-click-to-close
   // wasn't working in practice; add tracing on all three drawer
   // click paths so the debug log shows exactly what's firing (or
   // not firing) on the next reproduction.
  const _dl = (event, extras) => {
    try {
      if (typeof window._dlog === "function") {
        window._dlog("bookmark", "drawer", event, extras || {});
      }
    } catch {}
  };
  const onReady = () => {
    const toggleBtn = document.getElementById("bookmarks-drawer-toggle");
    const closeBtn = document.getElementById("bookmarks-drawer-close");
    const head = document.getElementById("bookmarks-drawer-head");
    _dl("init", {
      toggleBtn: !!toggleBtn,
      closeBtn: !!closeBtn,
      head: !!head,
    });
    if (toggleBtn) {
      toggleBtn.addEventListener("click", () => {
        _dl("toggle-clicked", {
          wasOpen: document.body.dataset.bookmarksDrawerOpen === "1",
        });
        toggle();
      });
    }
    if (closeBtn) {
      closeBtn.addEventListener("click", () => {
        _dl("close-btn-clicked", {});
        setOpen(false);
      });
    }
    // v225v4.38: tapping anywhere in the header bar closes the drawer,
    // not just the × button. The × keeps its own handler for clarity
    // but event bubbling means a click on the title text → the head →
    // setOpen(false) too.
    if (head) {
      head.addEventListener("click", (e) => {
        _dl("head-clicked", {
          target: (e.target && e.target.tagName) || "?",
          targetId: (e.target && e.target.id) || "",
          wasOpen: document.body.dataset.bookmarksDrawerOpen === "1",
        });
        setOpen(false);
      });
    }
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && document.body.dataset.bookmarksDrawerOpen === "1") {
        _dl("escape-key", {});
        setOpen(false);
      }
    });
  };
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", onReady, { once: true });
  } else {
    onReady();
  }
})();

(() => {
  const origFetch = window.fetch.bind(window);
  window.fetch = async (input, options) => {
    options = options ? { ...options } : {};
    let url =
      typeof input === "string"
        ? input
        : input && typeof input.url === "string"
        ? input.url
        : "";
    const isApi = url.startsWith("/api/");

    // v225v4.27 (#704): rewrite the URL to the absolute Fly origin
    // when running in Tauri. Done before any header logic so the
    // request actually reaches the auth middleware. Re-form Request
    // objects if the caller passed one, since you can't mutate
    // input.url in place.
    if (isApi && API_ORIGIN) {
      const absoluteUrl = API_ORIGIN + url;
      if (typeof input === "string") {
        input = absoluteUrl;
      } else if (input && typeof input.url === "string") {
        input = new Request(absoluteUrl, input);
      }
      url = absoluteUrl;
    }

    if (isApi) {
      const key = getApiKey();
      if (key) {
        const h = new Headers(options.headers || {});
        h.set("X-Narrative-Key", key);
        options.headers = h;
      }
      // v4.108 (2FA): attach the "2FA-passed" token if we have one. The
      // server only requires it for 2FA-enrolled tenants; harmless
      // otherwise, so we always send it when present.
      const totpTok = getTotpToken();
      if (totpTok) {
        const h = new Headers(options.headers || {});
        h.set("X-Narrative-2FA", totpTok);
        options.headers = h;
      }
    }

    let res = await origFetch(input, options);

    if (isApi && res.status === 401) {
      // v4.108 (2FA): a 401 here is either a key problem OR a 2FA
      // challenge. Peek the body (via a clone so `res` stays readable)
      // to tell them apart.
      let detail = "";
      try { detail = ((await res.clone().json()) || {}).detail || ""; } catch {}

      if (detail === "2fa_required") {
        // The key is fine; this tenant has 2FA on and we lack (or have a
        // stale) token. Prompt for a code, verify it, store the token,
        // retry the original request with the header.
        const code = await _promptForTotpCode();
        if (code) {
          try {
            const vres = await origFetch(
              (API_ORIGIN || "") + "/api/2fa/verify",
              {
                method: "POST",
                headers: {
                  "Content-Type": "application/json",
                  "X-Narrative-Key": getApiKey(),
                },
                body: JSON.stringify({ code }),
              },
            );
            if (vres.ok) {
              const { token } = await vres.json();
              if (token) {
                setTotpToken(token);
                const h = new Headers(options.headers || {});
                h.set("X-Narrative-2FA", token);
                options.headers = h;
                res = await origFetch(input, options);
              }
            } else {
              let d = `HTTP ${vres.status}`;
              try { d = (await vres.json()).detail || d; } catch {}
              if (typeof setStatus === "function") {
                setStatus(`Two-step verification failed: ${d}`, true);
              }
            }
          } catch (e) {
            if (typeof setStatus === "function") {
              setStatus(`Two-step verification error: ${e.message}`, true);
            }
          }
        }
        return res;
      }

      // v4.52: before opening a NEW prompt, check whether the stored
      // key changed since we sent this request. Concurrent 401s with
      // a slow Fly cold-start cause this: fast requests trigger ONE
      // dialog, user pastes, fast retries succeed; then a slow request
      // finally 401s and would normally pop a SECOND dialog (user
      // already pasted, key is in localStorage) just to click OK
      // again. By comparing what we SENT vs what's stored NOW, we can
      // silently retry on stale-send and only prompt on a real 401.
      const sentKey =
        options && options.headers
          ? new Headers(options.headers).get("X-Narrative-Key") || ""
          : "";
      const currentKey = getApiKey();
      if (currentKey && currentKey !== sentKey) {
        const h = new Headers(options.headers || {});
        h.set("X-Narrative-Key", currentKey);
        options.headers = h;
        res = await origFetch(input, options);
      } else {
        // v4.51: _promptForApiKey is async — await the dialog.
        const newKey = await _promptForApiKey();
        if (newKey) {
          const h = new Headers(options.headers || {});
          h.set("X-Narrative-Key", newKey);
          options.headers = h;
          res = await origFetch(input, options);
        }
      }
    }
    return res;
  };
})();

