function _launchTour(builder) {
  if (!window.OverlayTour) {
    setStatus("Tour engine not loaded — try Force update.", true);
    return;
  }
  try {
    const dlg = document.getElementById("settings-dialog");
    if (dlg && typeof dlg.close === "function") dlg.close();
  } catch {}
  setTimeout(() => {
    window.OverlayTour.start(builder());
  }, 120);
}

const settingsTakeTourLink = $("settings-take-tour-link");
if (settingsTakeTourLink) {
  settingsTakeTourLink.addEventListener("click", (e) => {
    e.preventDefault();
    _launchTour(_buildFirstTour);
  });
}

const settingsAuthorTourLink = $("settings-author-tour-link");
if (settingsAuthorTourLink) {
  settingsAuthorTourLink.addEventListener("click", (e) => {
    e.preventDefault();
    _launchTour(_buildAuthorTour);
  });
}

// v225v3.17 (#623): auto-fire first-tour on initial launch. Gates:
//   - User hasn't seen / skipped this tour before (OverlayTour.hasSeen)
//   - Library is empty (don't bug returning users who just cleared)
//   - No clip currently loaded (avoid landing-from-shared-link case)
//   - Engine is loaded
// Runs after a short delay so the DOM, library count, and Settings
// dialog state have all settled.
function _maybeAutoStartFirstTour() {
  try {
    if (!window.OverlayTour) return;
    if (window.OverlayTour.hasSeen && window.OverlayTour.hasSeen("first-tour")) return;
    // Library check: _libraryClips is the in-memory cache populated
    // by renderLibrary; bail if it has anything OR if the count badge
    // says > 0 (covers boot-before-cache-populated).
    const badge = document.getElementById("library-trigger-count");
    const countText = badge && badge.textContent && badge.textContent.trim();
    const countN = parseInt(countText || "0", 10);
    if (countN > 0) return;
    if (typeof _currentClipId !== "undefined" && _currentClipId) return;
    // Defer until next frame so render passes finish, then a little
    // more to let any splash / banner animations resolve.
    setTimeout(() => {
      // Re-check the gates right before firing — guards against the
      // user starting work in the gap (paste, click, etc.).
      if (window.OverlayTour.hasSeen("first-tour")) return;
      const badge2 = document.getElementById("library-trigger-count");
      const countText2 = badge2 && badge2.textContent && badge2.textContent.trim();
      const countN2 = parseInt(countText2 || "0", 10);
      if (countN2 > 0) return;
      if (typeof _currentClipId !== "undefined" && _currentClipId) return;
      _launchTour(_buildFirstTour);
    }, 1500);
  } catch (e) {
    console.warn("[tour] auto-start failed", e);
  }
}
// Schedule once after the DOM is interactive (we're already loaded
// late in the body so this fires almost immediately).
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", _maybeAutoStartFirstTour);
} else {
  _maybeAutoStartFirstTour();
}

// ---- Debug log viewer --------------------------------------------------
// v177: surfaces the _debugLog ring buffer in a modal so the user can
// copy/download it when reporting "chapter X keeps failing" issues.
const debugLogDialog = $("debug-log-dialog");
const debugLogClose = $("debug-log-close");
const debugLogCount = $("debug-log-count");
const debugLogBody = $("debug-log-body");
const debugLogCopy = $("debug-log-copy");
const debugLogDownload = $("debug-log-download");
const debugLogClear = $("debug-log-clear");

function _currentAppVersion() {
  // v225dm: pull the live SW cache name (same as the Settings stamp)
  // so the log header is always truth-aligned. Falls back to "unknown"
  // if the stamp hasn't run yet (very early boot) or DOM isn't ready.
  try {
    const el = document.getElementById("settings-version-tag");
    const v = el && el.textContent && el.textContent.trim();
    return v || "unknown";
  } catch {
    return "unknown";
  }
}

function _formatDebugLogForDisplay() {
  // v225dm: header line first so triage knows which build the user
  // was on when the log was captured. Previous debug-log files were
  // silent about version — every "still not working" report needed
  // a Settings screenshot to confirm cache state. Always emit the
  // header, even when the log itself is empty.
  const header =
    `# Narrative ${_currentAppVersion()} · ` +
    `captured ${new Date().toISOString()}\n` +
    `# ${_debugLog.length} entries\n#\n`;
  if (_debugLog.length === 0) {
    return header + "(empty — no entries yet. Try a GitHub import or background queue to populate.)";
  }
  const lines = [];
  for (const e of _debugLog) {
    // v225.tn77 (#559): include the mode field so v225be's stamp
    // actually surfaces in the rendered log. Without this, the
    // stored e.mode was silently dropped at display time and we
    // couldn't see which tier the user was on while triaging
    // mode-specific bugs.
    const modeStr = e.mode ? ` <${e.mode}>` : "";
    let line = `${e.t}  [${e.cat}]${modeStr}  ${e.msg}`;
    if (e.data !== undefined) {
      let dataStr = "";
      try { dataStr = JSON.stringify(e.data, null, 2); } catch { dataStr = String(e.data); }
      // Indent the data block so it visually associates with the line above.
      line += "\n" + dataStr.split("\n").map((l) => "  " + l).join("\n");
    }
    lines.push(line);
  }
  return lines.join("\n\n");
}

function _renderDebugLog() {
  if (debugLogCount) debugLogCount.textContent = String(_debugLog.length);
  if (debugLogBody) debugLogBody.textContent = _formatDebugLogForDisplay();
}

function openDebugLog() {
  _renderDebugLog();
  // Scroll to the bottom so the most recent entries (which are usually
  // what the user wants to see) are visible without manual scroll.
  if (debugLogBody) {
    requestAnimationFrame(() => {
      debugLogBody.scrollTop = debugLogBody.scrollHeight;
    });
  }
  if (debugLogDialog && !debugLogDialog.open) debugLogDialog.showModal();
}

if (settingsDebugLogLink) {
  settingsDebugLogLink.addEventListener("click", (e) => {
    e.preventDefault();
    // Close Settings first so the debug log opens on top cleanly.
    if (typeof settingsDialog !== "undefined" && settingsDialog.open) {
      settingsDialog.close();
    }
    openDebugLog();
  });
}
if (debugLogClose) {
  debugLogClose.addEventListener("click", () => debugLogDialog.close());
}
if (debugLogCopy) {
  debugLogCopy.addEventListener("click", async () => {
    const text = _formatDebugLogForDisplay();
    try {
      await navigator.clipboard.writeText(text);
      debugLogCopy.textContent = "Copied!";
      setTimeout(() => { debugLogCopy.textContent = "Copy"; }, 1500);
    } catch (err) {
      // Clipboard API blocked (insecure context / permissions). Fall
      // back to selecting the body so the user can ⌘C / Ctrl+C.
      try {
        const range = document.createRange();
        range.selectNodeContents(debugLogBody);
        const sel = window.getSelection();
        sel.removeAllRanges();
        sel.addRange(range);
        debugLogCopy.textContent = "Selected — press Ctrl+C";
        setTimeout(() => { debugLogCopy.textContent = "Copy"; }, 2500);
      } catch {}
    }
  });
}
if (debugLogDownload) {
  debugLogDownload.addEventListener("click", () => {
    const text = _formatDebugLogForDisplay();
    const blob = new Blob([text], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    // Local stamp without leaking seconds-precision: YYYY-MM-DDTHH-MM.
    const stamp = new Date().toISOString().slice(0, 16).replace(/[:.]/g, "-");
    // v225dm: bake the build version into the filename so triaging
    // is unambiguous before even opening the file.
    const ver = _currentAppVersion().replace(/[^a-zA-Z0-9]/g, "");
    a.href = url;
    a.download = `narrative-debug-${ver}-${stamp}.txt`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  });
}

// v225v3.32: programmatic trigger for the debug log download. Used by
// the phone manual viewer to auto-export diagnostics after open so the
// user doesn't have to navigate to Settings (which can be a trap when
// the manual itself blocks taps). Reason gets baked into the filename
// so multiple auto-exports during one session are distinguishable.
function _autoDownloadDebugLog(reason) {
  let text = "";
  try {
    text = _formatDebugLogForDisplay();
    const blob = new Blob([text], { type: "text/plain" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    const stamp = new Date().toISOString().slice(0, 16).replace(/[:.]/g, "-");
    const ver = _currentAppVersion().replace(/[^a-zA-Z0-9]/g, "");
    const safeReason = (reason || "auto").replace(/[^a-zA-Z0-9-]/g, "-");
    a.href = url;
    a.download = `narrative-debug-${ver}-${safeReason}-${stamp}.txt`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  } catch (e) {
    console.warn("[debug-log] auto-download failed:", e);
  }
  // v225v3.38 (#768): fire-and-forget push to /api/debug-log so the
  // narrative-debug-logs repo gets a copy too. Best-effort — the local
  // download above is the source of truth. We never await this; the
  // user-visible flow doesn't change whether the push lands or not.
  // Server endpoint always returns 200 (with ok=true|false), so a
  // network failure is the only thing that throws.
  if (text) {
    _pushDebugLogToServer(reason, text).catch((e) => {
      console.warn("[debug-log] server push failed:", e);
    });
  }
}

// v225v3.38 (#768): background push of a debug log payload to
// /api/debug-log. Resolves to {ok, path?, sha?, html_url?, reason?}.
// Auth flows through the window.fetch monkey-patch (X-Narrative-Key).
//
// v4.73: dlog-instrumented. Earlier we relied on console.warn for
// failure surfacing, which doesn't end up in the log that the debugger
// reads — so when a Tauri desktop push silently failed (CORS preflight,
// network drop, or whatever), the user saw the "Log pushed" status text
// and we saw nothing arrive in narrative-debug-logs. Now every phase
// writes a dlog entry, so the NEXT log captures the failure mode in the
// log itself.
async function _pushDebugLogToServer(reason, text) {
  const ver = _currentAppVersion();
  const payload = {
    log: text,
    reason: reason || "auto",
    version: ver,
    ua: navigator.userAgent || "",
  };
  _dlog("debug-log-push", "start", {
    reason: payload.reason,
    version: ver,
    logBytes: text ? text.length : 0,
    origin: typeof location !== "undefined" ? location.origin : "",
    apiOrigin: API_ORIGIN || "(same-origin)",
  });
  let res;
  try {
    res = await fetch("/api/debug-log", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
  } catch (e) {
    // Network-level failure: CORS preflight blocked, connection refused,
    // DNS, abort. Tauri WebView2 surfaces these as TypeError. This is
    // the case we were missing before — the user thought the push went
    // through but the fetch itself never resolved.
    _dlog("debug-log-push", "fetch threw", {
      name: (e && e.name) || "Error",
      msg: (e && e.message) || String(e),
    });
    return { ok: false, reason: "fetch_failed" };
  }
  if (!res.ok) {
    _dlog("debug-log-push", "non-2xx", { status: res.status });
    return { ok: false, reason: `http_${res.status}` };
  }
  const body = await res.json().catch(() => null);
  if (!body) {
    _dlog("debug-log-push", "bad json");
    return { ok: false, reason: "bad_json" };
  }
  _dlog("debug-log-push", "ok", {
    serverOk: body.ok,
    path: body.path || null,
    sha: body.sha ? String(body.sha).slice(0, 8) : null,
    reason: body.reason || null,
  });
  return body;
}
if (debugLogClear) {
  debugLogClear.addEventListener("click", () => {
    if (!confirm("Clear the debug log? This can't be undone.")) return;
    _debugLog.length = 0;
    _renderDebugLog();
  });
}

// ---- Streaming playback state -------------------------------------------
// While synthesis runs, each sentence's WAV arrives over SSE and we play
// them in sequence via the audio element. When the final `result` event
// arrives, we swap the player to the combined WAV at the current "virtual"
// position so seek / download / library work normally.
//
//   _streamQueue:     [{url, durationSec}, ...]  per-sentence blob URLs
//   _streamPlayhead:  index of the currently-playing sentence; -1 when
//                     not in streaming mode (idle, or after the swap)
//   _streamElapsed:   total seconds of *completed* sentences, used to
//                     compute virtualTime() across boundaries
let _streamQueue = [];
let _streamPlayhead = -1;
let _streamElapsed = 0;

function resetStream() {
  for (const item of _streamQueue) {
    if (item.url) URL.revokeObjectURL(item.url);
  }
  _streamQueue = [];
  _streamPlayhead = -1;
  _streamElapsed = 0;
}

// Total seconds of audio logically played across sentence boundaries.
// During streaming, player.currentTime is local to the current sentence;
// after the swap to combined WAV, _streamPlayhead is -1 and we just use
// player.currentTime directly.
function virtualTime() {
  if (_streamPlayhead < 0) return playerEl.currentTime || 0;
  return _streamElapsed + (playerEl.currentTime || 0);
}

function startNextStreamSentence() {
  _streamPlayhead++;
  while (_streamPlayhead < _streamQueue.length && !_streamQueue[_streamPlayhead].url) {
    // Skip empty SAPI chunks so sentence indices still line up.
    _streamPlayhead++;
  }
  if (_streamPlayhead < _streamQueue.length) {
    playerEl.src = _streamQueue[_streamPlayhead].url;
    // Re-narrate suppresses streaming audio: the user shouldn't hear
    // Sarah's voice from sentence 0 onward while they were already
    // listening at sentence 5. Sentences keep queueing in the
    // background; playback resumes at the captured position via
    // _maybeStartRenarrateResume() as soon as we've synthesized far
    // enough to cover that point.
    if (!_regenSuppressStreaming) {
      playerEl.play().catch(() => {});
    }
  }
}

// During a re-narrate, called on every sentence event while playback is
// still suppressed. As soon as enough sentence offsets have arrived to
// know which sentence covers the resume position, hijack the stream:
// jump _streamPlayhead to that sentence, set _streamElapsed so
// virtualTime() math stays correct, load and play that sentence, then
// seek inside it to land at the captured resume time. The normal
// "ended → startNextStreamSentence" chain takes over from there, so
// subsequent sentences play in sequence and the eventual swap to
// combined audio just continues the same playhead.
function _maybeStartRenarrateResume(totalSentences) {
  const resume = _regenResumeAtSec;
  if (resume == null) return;

  // Find the sentence containing resume. A sentence covers [start, end)
  // where end is the start of the next sentence (or +Infinity for the
  // last one). We can only commit to a target when we either (a) know
  // the next sentence's offset, or (b) know this is the final sentence.
  let target = -1;
  for (let i = 0; i < sentenceOffsetsSec.length; i++) {
    const start = sentenceOffsetsSec[i];
    if (start === undefined) continue;
    const nextStart = sentenceOffsetsSec[i + 1];
    const isLast = i === totalSentences - 1;
    const end = nextStart !== undefined ? nextStart : (isLast ? Infinity : null);
    if (end == null) break; // can't determine yet — wait for more
    if (resume >= start && resume < end) {
      target = i;
      break;
    }
  }
  if (target < 0) return;

  // Skip empty (URL-less) targets — point at the next sentence with
  // audio. Edge case: resume falls inside an empty SAPI chunk; we drift
  // forward to the next playable sentence, which is the closest we can
  // get without a frame-accurate scrub through silence.
  let usable = target;
  while (
    usable < _streamQueue.length &&
    (!_streamQueue[usable] || !_streamQueue[usable].url)
  ) {
    usable++;
  }
  if (usable >= _streamQueue.length) return; // not queued yet — wait

  // Lock state to "playing from sentence usable" so the chain handlers
  // and highlight machinery work. _streamPlayhead is incremented inside
  // startNextStreamSentence, so we set it one below the target.
  _regenSuppressStreaming = false;
  _regenResumeAtSec = null;
  _streamPlayhead = usable - 1;
  _streamElapsed = sentenceOffsetsSec[usable] || 0;
  startNextStreamSentence();

  // Seek inside the loaded sentence to the intra-sentence offset so the
  // user lands AT the resume position, not at the start of the
  // containing sentence. Bound to loadedmetadata (currentTime isn't
  // honored until the audio's duration is known).
  const intra = Math.max(0, resume - (sentenceOffsetsSec[usable] || 0));
  if (intra > 0) {
    const seekInside = () => {
      try {
        if (isFinite(playerEl.duration)) {
          playerEl.currentTime = Math.min(intra, playerEl.duration);
        }
      } catch {}
    };
    playerEl.addEventListener("loadedmetadata", seekInside, { once: true });
  }
}

// ---- Playback speed -----------------------------------------------------
// Single cycling button; each tap advances to the next rate. Persisted in
// localStorage so it sticks across reloads, and reapplied on every
// loadedmetadata because the audio element can reset playbackRate when
// src changes (which happens often during streaming).
const SPEEDS = [1, 1.25, 1.5, 1.75, 2, 0.75];
const SPEED_STORAGE_KEY = "narrative.playbackRate";

function _loadSavedSpeed() {
  const saved = parseFloat(localStorage.getItem(SPEED_STORAGE_KEY));
  return SPEEDS.includes(saved) ? saved : 1;
}

let _playbackRate = _loadSavedSpeed();

function _fmtSpeed(r) {
  // 1.0 → "1×", 1.25 → "1.25×"
  return `${Number.isInteger(r) ? r : r}×`;
}

function updateSpeedBtn() {
  speedBtn.textContent = _fmtSpeed(_playbackRate);
  // Rich tooltip: total length and wall-clock total at this speed.
  // Hover-only on desktop, long-press on touch; the visible
  // cp-time-effective annotation carries the same info for users
  // who never hover.
  const dur = isFinite(playerEl.duration) ? playerEl.duration : 0;
  if (_playbackRate === 1 || dur <= 0) {
    speedBtn.title = `Playback speed (currently ${_fmtSpeed(_playbackRate)})`;
  } else {
    const scaled = dur / _playbackRate;
    speedBtn.title =
      `Speed ${_fmtSpeed(_playbackRate)} · ` +
      `${_fmtDurationCoarse(dur)} → ${_fmtDurationCoarse(scaled)} at this speed`;
  }
}

function applyPlaybackRate() {
  if (isFinite(playerEl.playbackRate)) {
    playerEl.playbackRate = _playbackRate;
  }
}

// v150: first-tap hint for cycle chips. The Sleep / A↔B / Speed
// chips all cycle through internal states on tap, but a first-time
// tester sees the state change with no signal that more taps will
// keep cycling. _maybeChipHint returns a hint string the first time
// a given key is hit, then locks it; the chip handlers fire a
// follow-up setStatus 1.2s later so the original action status
// (e.g. "Sleep timer 15 min.") reads first and the hint reinforces.
function _maybeChipHint(key, message) {
  try {
    if (localStorage.getItem(key) === "1") return null;
    localStorage.setItem(key, "1");
    return message;
  } catch {
    return null;
  }
}
function _fireChipHint(key, message) {
  const hint = _maybeChipHint(key, message);
  if (hint) setTimeout(() => setStatus(hint), 1200);
}

speedBtn.addEventListener("click", () => {
  const i = SPEEDS.indexOf(_playbackRate);
  _playbackRate = SPEEDS[(i + 1) % SPEEDS.length];
  try { localStorage.setItem(SPEED_STORAGE_KEY, String(_playbackRate)); } catch {}
  updateSpeedBtn();
  applyPlaybackRate();
  // Cycle speed → recompute the wall-clock remaining annotation.
  if (typeof _cpRefreshTime === "function") _cpRefreshTime();
  _fireChipHint(
    "narrative.hintSeen.speed",
    "💡 Tap again to cycle: 1× → 1.25× → 1.5× → 1.75× → 2× → 0.75×."
  );
});

// ---- v225eu: 3-way repeat (Spotify model) --------------------------------
// State:  "off"  → ended advances to next clip (current default)
//         "one" → ended seeks to 0 and replays the same clip
//         "all" → ended advances, but end-of-queue wraps to the first clip
//
// Persists in localStorage so the chip remembers between sessions.
// Hooked into playerEl's "ended" handler further down the file; the loop /
// wrap logic lives in `_repeatHandleEnded()` so the handler can call one
// function and bail early.
const REPEAT_STORAGE_KEY = "narrative.repeatMode";
let _repeatMode = "off";
try {
  const raw = localStorage.getItem(REPEAT_STORAGE_KEY);
  if (raw === "one" || raw === "all") _repeatMode = raw;
} catch {}

const repeatBtn = $("repeat-btn");
// v225v4.11: SVG paths swap in for the old Unicode 🔁/🔂 emoji. These
// are Material Design Icons (Apache 2.0) — the same icons Spotify,
// YouTube Music, Apple Music, Amazon Music, and Tidal all use. They
// render identically across every OS and inherit the button's text
// color via currentColor, so the dim/accent state is controlled by
// CSS on the parent button instead of by opacity tricks.
const _REPEAT_SVG_ALL =
  '<svg class="repeat-svg" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">' +
  '<path d="M7 7h10v3l4-4-4-4v3H5v6h2V7zm10 10H7v-3l-4 4 4 4v-3h12v-6h-2v4z"/>' +
  '</svg>';
const _REPEAT_SVG_ONE =
  '<svg class="repeat-svg" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">' +
  '<path d="M7 7h10v3l4-4-4-4v3H5v6h2V7zm10 10H7v-3l-4 4 4 4v-3h12v-6h-2v4zm-4-2V9h-1l-2 1v1h1.5v4H13z"/>' +
  '</svg>';
function _paintRepeatBtn() {
  if (!repeatBtn) return;
  // Different SVG per mode so the icon itself carries meaning:
  //   off → repeat (two arrows in a loop), color via CSS = --fg-dim
  //   one → repeat_one (same shape + "1" inset), color via CSS = --accent
  //   all → repeat (same as off shape), color via CSS = --accent
  // CSS rule `.repeat-btn[data-mode="one|all"]` switches color from
  // dim to accent without touching the SVG markup.
  repeatBtn.innerHTML = _repeatMode === "one" ? _REPEAT_SVG_ONE : _REPEAT_SVG_ALL;
  repeatBtn.dataset.mode = _repeatMode;
  repeatBtn.setAttribute(
    "aria-label",
    _repeatMode === "off"
      ? "Repeat — off"
      : _repeatMode === "one"
      ? "Repeat — loop this clip"
      : "Repeat — repeat all",
  );
}
function _cycleRepeatMode() {
  _repeatMode =
    _repeatMode === "off" ? "one" : _repeatMode === "one" ? "all" : "off";
  try { localStorage.setItem(REPEAT_STORAGE_KEY, _repeatMode); } catch {}
  _paintRepeatBtn();
  // Live status line so the user sees what just happened. Sleep / A↔B / Speed
  // all surface their state the same way.
  setStatus(
    _repeatMode === "off"
      ? "Repeat off."
      : _repeatMode === "one"
      ? "Looping this clip."
      : "Repeating all clips.",
  );
  // Re-render the library so the active card's title-row badge reflects
  // the new mode (badge appears for one|all, disappears for off). Light
  // hint on the first cycle.
  if (typeof renderLibrary === "function") renderLibrary();
  _fireChipHint(
    "narrative.hintSeen.repeat",
    "💡 Tap again to cycle: Off → 🔂 Loop this → 🔁 Repeat all.",
  );
}
if (repeatBtn) {
  repeatBtn.addEventListener("click", _cycleRepeatMode);
  _paintRepeatBtn();
}

// Called from the playerEl "ended" handler before auto-advance fires.
// Returns true if it handled the end-of-clip (so the handler should bail);
// returns false to let the default advance behavior run.
async function _repeatHandleEnded(justEndedId) {
  if (_repeatMode === "one") {
    // Loop-this: jump to the start and play. Skip the markCurrentClipPlayed
    // side-effect by NOT going through advance — the playhead is already
    // about to be 0 so resume-position will overwrite itself.
    try {
      playerEl.currentTime = 0;
      await playerEl.play();
    } catch (err) {
      // Autoplay restrictions might block silent restart on some browsers.
      // No-op — user can tap Play.
    }
    setStatus("🔂 Looping this clip.");
    return true;
  }
  if (_repeatMode === "all" && justEndedId) {
    // Repeat-all: try normal next first. If queue is exhausted (last
    // clip in the active sort), wrap to the first clip in the same sort.
    const nextId = await nextClipId(justEndedId);
    if (nextId) return false; // not last — let default advance run
    // Wrap: load the first clip in the current sort. Reuse listClips +
    // sortClips so the wrap honors the user's playMode (custom order,
    // newest first, etc.).
    try {
      const clips = await listClips();
      if (!clips.length) return false;
      let first;
      if (_playMode === "shuffle") {
        const others = clips.filter((c) => c.id !== justEndedId);
        first = (others.length ? others : clips)[
          Math.floor(Math.random() * (others.length || clips.length))
        ];
      } else {
        first = sortClips(clips, _playMode)[0];
      }
      if (first) {
        setStatus("🔁 Wrapping to first…");
        _cancelAutoAdvance();
        _autoAdvanceTimer = setTimeout(() => {
          _autoAdvanceTimer = null;
          loadClip(first.id);
        }, 3000);
        return true;
      }
    } catch {}
  }
  return false;
}

updateSpeedBtn();
applyPlaybackRate();
// Re-apply on every src change — browsers sometimes reset playbackRate to 1
// when the audio source changes, which would break per-sentence streaming.
// Also re-render the speed tooltip + effective-remaining once duration
// is known (the values depend on it).
playerEl.addEventListener("loadedmetadata", () => {
  applyPlaybackRate();
  updateSpeedBtn();
  if (typeof _cpRefreshTime === "function") _cpRefreshTime();
});

// ---- Sleep timer --------------------------------------------------------
// Cycles through Off / 15 / 30 / 45 / 60 min. On expiry, fades the player
// volume to zero over 5 seconds and pauses. Volume is restored after the
// fade so the next manual play isn't silent. Wall-clock based, so audio
// keeps playing through phone PWA backgrounding even when setInterval
// gets throttled — `timeupdate` (which fires while audio plays) also
// checks the expiry, catching it within a few hundred ms in any case.
const SLEEP_DURATIONS_MIN = [0, 15, 30, 45, 60];
const SLEEP_FADE_MS = 5000;
// The sleep button cycle has one more state past the minute presets:
// "end of chapter" (when a chapter queue is active) or "end of clip"
// (when not). The distinction is wholly cosmetic — both stop at the
// next natural narrative boundary. Picked over minute timers when you
// know roughly where you are in a book but don't want to guess how
// long the chapter has left.
const SLEEP_IDX_END_OF_BOUNDARY = SLEEP_DURATIONS_MIN.length; // 5

let _sleepIdx = 0;          // index into the extended cycle (5 = end-of-boundary)
let _sleepExpiryMs = 0;     // 0 when idle; Date.now() target otherwise
let _sleepTickHandle = null;
let _sleepFadeHandle = null;
let _sleepFadeStartVol = null;  // saved so cancel/reset can restore
let _sleepEndOfChapter = false; // true when end-of-boundary mode is armed

function _formatCountdown(ms) {
  const totalSec = Math.max(0, Math.ceil(ms / 1000));
  const m = Math.floor(totalSec / 60);
  const s = totalSec % 60;
  return `${m}:${String(s).padStart(2, "0")}`;
}

function _updateSleepBtn() {
  if (_sleepEndOfChapter) {
    // Label shifts based on whether there's actually a chapter queue.
    // Same mode either way — "boundary" is whatever ends next.
    sleepBtn.textContent =
      _chapterTotalCount > 0 ? "💤 Chapter end" : "💤 Clip end";
    sleepBtn.classList.add("active");
    return;
  }
  if (_sleepExpiryMs <= 0) {
    sleepBtn.textContent = "Sleep";
    sleepBtn.classList.remove("active");
    return;
  }
  const remaining = _sleepExpiryMs - Date.now();
  sleepBtn.textContent = `💤 ${_formatCountdown(remaining)}`;
  sleepBtn.classList.add("active");
}

// Called when a natural narrative boundary completes while end-of-chapter
// sleep is armed. The audio has already finished (or is about to) so we
// don't need the volume fade the minute-timer expiry uses — just pause,
// reset the sleep state, and tell the user. The chapter-queue / library-
// auto-advance call sites guarantee they don't fire after this.
function _onSleepBoundaryReached(boundary) {
  _sleepEndOfChapter = false;
  _sleepIdx = 0;
  _updateSleepBtn();
  if (!playerEl.paused) _pauseAsUser();
  setStatus(`Sleep timer reached — paused at end of ${boundary}.`);
}

function _cancelSleepFade() {
  if (_sleepFadeHandle) clearInterval(_sleepFadeHandle);
  _sleepFadeHandle = null;
  if (_sleepFadeStartVol !== null) {
    playerEl.volume = _sleepFadeStartVol;
    _sleepFadeStartVol = null;
  }
}

function cancelSleepTimer() {
  if (_sleepTickHandle) clearInterval(_sleepTickHandle);
  _sleepTickHandle = null;
  _sleepExpiryMs = 0;
  // NOTE: _sleepEndOfChapter is NOT cleared here — startSleepTimer
  // calls cancelSleepTimer to wipe minute-mode state before switching
  // to a new minute count, but the click handler manages the
  // end-of-chapter flag explicitly so the two modes can't both be on.
  _cancelSleepFade();
  _updateSleepBtn();
}

function startSleepTimer(minutes) {
  cancelSleepTimer();
  _sleepExpiryMs = Date.now() + minutes * 60 * 1000;
  // Tick once per second for the countdown label; timeupdate will catch
  // expiry faster when audio is actively playing.
  _sleepTickHandle = setInterval(() => {
    if (Date.now() >= _sleepExpiryMs) {
      _onSleepExpired();
    } else {
      _updateSleepBtn();
    }
  }, 1000);
  _updateSleepBtn();
}

function _onSleepExpired() {
  if (_sleepTickHandle) clearInterval(_sleepTickHandle);
  _sleepTickHandle = null;
  _sleepExpiryMs = 0;

  // If we're already paused, nothing to fade — just reset UI.
  if (playerEl.paused) {
    _updateSleepBtn();
    setStatus("Sleep timer reached.");
    return;
  }

  // Linear fade from current volume to 0 over SLEEP_FADE_MS.
  _sleepFadeStartVol = playerEl.volume;
  const fadeStartAt = Date.now();
  _sleepFadeHandle = setInterval(() => {
    const elapsed = Date.now() - fadeStartAt;
    const ratio = Math.max(0, 1 - elapsed / SLEEP_FADE_MS);
    playerEl.volume = _sleepFadeStartVol * ratio;
    if (elapsed >= SLEEP_FADE_MS) {
      clearInterval(_sleepFadeHandle);
      _sleepFadeHandle = null;
      _pauseAsUser(); // intentional — don't auto-resume on next visibility
      // Restore volume so next manual play isn't silent.
      playerEl.volume = _sleepFadeStartVol;
      _sleepFadeStartVol = null;
      _updateSleepBtn();
      setStatus("Sleep timer reached — paused.");
    }
  }, 100);
  _updateSleepBtn();
}

sleepBtn.addEventListener("click", () => {
  _fireChipHint(
    "narrative.hintSeen.sleep",
    "💡 Tap Sleep again to cycle: 15 / 30 / 45 / 60 min · end of chapter · off."
  );
  // Cycle is Off → 15 → 30 → 45 → 60 → End-of-boundary → Off.
  // SLEEP_IDX_END_OF_BOUNDARY (5) is the final slot before wrapping.
  _sleepIdx = (_sleepIdx + 1) % (SLEEP_DURATIONS_MIN.length + 1);

  if (_sleepIdx === 0) {
    _sleepEndOfChapter = false;
    cancelSleepTimer();
    setStatus("Sleep timer off.");
    return;
  }

  if (_sleepIdx === SLEEP_IDX_END_OF_BOUNDARY) {
    // End-of-boundary mode. Clear any running minute timer; the natural
    // boundary will trigger _onSleepBoundaryReached.
    cancelSleepTimer();
    _sleepEndOfChapter = true;
    _updateSleepBtn();
    setStatus(
      _chapterTotalCount > 0
        ? "Sleep set for end of chapter."
        : "Sleep set for end of clip."
    );
    return;
  }

  // Minute presets.
  _sleepEndOfChapter = false;
  const minutes = SLEEP_DURATIONS_MIN[_sleepIdx];
  startSleepTimer(minutes);
  setStatus(`Sleep timer set for ${minutes} min.`);
});

// Belt-and-suspenders: `timeupdate` keeps firing during playback (including
// from the PWA's lock-screen MediaSession control flow), so we'll catch the
// expiry promptly even if setInterval is throttled in the background.
playerEl.addEventListener("timeupdate", () => {
  if (_sleepExpiryMs > 0 && Date.now() >= _sleepExpiryMs) {
    _onSleepExpired();
  }
});

_updateSleepBtn();

// ---- A-B loop -----------------------------------------------------------
// Tap the chip to mark A (current time), tap again to mark B and start
// looping between them, tap a third time to clear. Useful for re-listening
// to a tricky passage (language practice, study, writers checking rhythm,
// listeners re-hearing a complex paragraph).
//
// State machine:
//   _loopA = null, _loopB = null     → idle, label "A↔B"
//   _loopA set,    _loopB = null     → "A 1:23", waiting for B
//   _loopA set,    _loopB set        → looping, label "↻ 1:23–2:45", accent bg
//
// While looping is active, a timeupdate guard seeks back to A whenever
// currentTime crosses B. Switching clips clears the loop (the bounds
// belonged to a different audio track).
let _loopA = null;
let _loopB = null;

function _updateAbBtn() {
  if (_loopA == null) {
    abLoopBtn.textContent = "A↔B";
    abLoopBtn.classList.remove("active");
  } else if (_loopB == null) {
    abLoopBtn.textContent = `A ${formatTime(_loopA)}`;
    abLoopBtn.classList.remove("active");
  } else {
    abLoopBtn.textContent = `↻ ${formatTime(_loopA)}–${formatTime(_loopB)}`;
    abLoopBtn.classList.add("active");
  }
}

function clearAbLoop() {
  _loopA = null;
  _loopB = null;
  _updateAbBtn();
}

abLoopBtn.addEventListener("click", () => {
  const here = virtualTime();
  if (_loopA == null) {
    _loopA = here;
  } else if (_loopB == null) {
    // v220v: B must be at least ~0.5s past A. Previously a 2nd tap at
    // the same time silently RESET A to here, leaving the label looking
    // unchanged ("A 1:23" → "A 1:23"). Tester reported "only first tap
    // works" — they were tapping rapidly while paused, expecting both
    // bounds to set in two taps. New behavior: keep A where it is, show
    // a status that tells the user what to do. The next tap (after they
    // seek or play forward) sets B and starts the loop.
    if (here <= _loopA + 0.5) {
      setStatus(
        `A is at ${formatTime(_loopA)}. Play forward (or seek), then tap A↔B to set B.`
      );
      return;
    }
    _loopB = here;
  } else {
    // Third tap clears.
    _loopA = null;
    _loopB = null;
  }
  _updateAbBtn();
  _fireChipHint(
    "narrative.hintSeen.abloop",
    "💡 Tap once at A · play forward · tap again at B · tap again to clear."
  );
});

// Loop enforcement: when both bounds are set, seek back to A whenever the
// playhead crosses B. timeupdate fires ~4 times/sec during playback, which
// is enough granularity that the user won't hear past B.
playerEl.addEventListener("timeupdate", () => {
  if (_loopA == null || _loopB == null) return;
  if (virtualTime() >= _loopB) {
    seekToTime(_loopA);
  }
});

_updateAbBtn();

// ---- Listen statistics --------------------------------------------------
// Buckets listen seconds by day, voice, and clip. Drives the Settings
// stats panel ("Today / This week / All-time / Top voice / Most listened").
// All wall-clock at 1× speed equivalent: we add playerEl.currentTime
// deltas while playing, so a 23-minute audiobook listened at 1.5× counts
// as ~15 minutes — the "how much content you got through" view, not the
// "how long you were doing it" view. The former is what users care about.
const STATS_KEY = "narrative.stats";
const STATS_SCHEMA = 1;

function _emptyStats() {
  return { schema: STATS_SCHEMA, daily: {}, voices: {}, clips: {}, total: 0 };
}

function _loadStats() {
  try {
    const raw = localStorage.getItem(STATS_KEY);
    if (!raw) return _emptyStats();
    const parsed = JSON.parse(raw);
    if (!parsed || parsed.schema !== STATS_SCHEMA) return _emptyStats();
    return {
      schema: STATS_SCHEMA,
      daily: parsed.daily || {},
      voices: parsed.voices || {},
      clips: parsed.clips || {},
      total: Number(parsed.total) || 0,
    };
  } catch {
    return _emptyStats();
  }
}

let _stats = _loadStats();
let _statsDirty = false;
let _lastListenTime = -1; // playerEl.currentTime at last accumulator tick

function _flushStats() {
  if (!_statsDirty) return;
  try { localStorage.setItem(STATS_KEY, JSON.stringify(_stats)); } catch {}
  _statsDirty = false;
}

function _todayKey() {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

// Prune day buckets older than 60 days so the JSON blob can't grow without
// bound. All-time total + voices + clips are not pruned (those are
// cumulative). Returns the pruned stats.
function _pruneOldDays(stats) {
  const cutoff = Date.now() - 60 * 24 * 60 * 60 * 1000;
  for (const key of Object.keys(stats.daily)) {
    const parsed = Date.parse(key + "T00:00:00");
    if (isFinite(parsed) && parsed < cutoff) delete stats.daily[key];
  }
  return stats;
}

function _recordListenDelta(deltaSec, clipId, voiceId) {
  // Sanity gate: clip negative deltas (seek backwards), oversized deltas
  // (resume after pause, tab backgrounded), and tiny noise. Tab throttling
  // can fire timeupdate after a long pause — the resume looks like a
  // huge jump; we don't want to credit the user for the time they were
  // away.
  if (!isFinite(deltaSec) || deltaSec <= 0 || deltaSec > 2) return;
  const today = _todayKey();
  _stats.daily[today] = (_stats.daily[today] || 0) + deltaSec;
  _stats.total += deltaSec;
  if (voiceId) {
    _stats.voices[voiceId] = (_stats.voices[voiceId] || 0) + deltaSec;
  }
  if (clipId != null) {
    const k = String(clipId);
    _stats.clips[k] = (_stats.clips[k] || 0) + deltaSec;
  }
  _statsDirty = true;
}

playerEl.addEventListener("play", () => {
  // Reset the delta tracker so the first post-play tick doesn't credit
  // a giant jump from wherever the head was last.
  _lastListenTime = playerEl.currentTime || 0;
});

playerEl.addEventListener("pause", () => {
  _lastListenTime = -1;
  _flushStats();
});

playerEl.addEventListener("seeking", () => {
  // Discard the in-progress delta — the next post-seek timeupdate will
  // re-anchor _lastListenTime to the new position.
  _lastListenTime = -1;
});

playerEl.addEventListener("timeupdate", () => {
  if (playerEl.paused) return;
  const now = playerEl.currentTime || 0;
  if (_lastListenTime < 0) {
    _lastListenTime = now;
    return;
  }
  const delta = now - _lastListenTime;
  _lastListenTime = now;
  // Attribute to the voice the loaded clip was synthesized with; the
  // picker can drift mid-playback if the user starts tweaking for the
  // next clip while the current one plays.
  _recordListenDelta(delta, _currentClipId, _currentPlayingVoiceId);
});

// Periodic flush so the user can close the tab and not lose listen time.
setInterval(_flushStats, 10_000);
window.addEventListener("beforeunload", _flushStats);
window.addEventListener("pagehide", _flushStats);

function _statsTodaySec() {
  return _stats.daily[_todayKey()] || 0;
}

function _statsWeekSec() {
  let total = 0;
  for (let i = 0; i < 7; i++) {
    const d = new Date();
    d.setDate(d.getDate() - i);
    const k = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
    total += _stats.daily[k] || 0;
  }
  return total;
}

function _statsTopVoiceId() {
  let best = null;
  let bestSec = 0;
  for (const [k, v] of Object.entries(_stats.voices)) {
    if (v > bestSec) { bestSec = v; best = k; }
  }
  return best;
}

function _statsTopClipId() {
  let best = null;
  let bestSec = 0;
  for (const [k, v] of Object.entries(_stats.clips)) {
    if (v > bestSec) { bestSec = v; best = k; }
  }
  return best;
}

// Format seconds as "12 min" / "3h 20m" / "1d 4h" — punchier than
// formatTime's M:SS for stats that span hours / days.
function _formatStatsDuration(sec) {
  sec = Math.round(sec || 0);
  if (sec < 60) return `${sec} sec`;
  if (sec < 3600) return `${Math.round(sec / 60)} min`;
  if (sec < 24 * 3600) {
    const h = Math.floor(sec / 3600);
    const m = Math.round((sec % 3600) / 60);
    return m > 0 ? `${h}h ${m}m` : `${h}h`;
  }
  const d = Math.floor(sec / (24 * 3600));
  const h = Math.round((sec % (24 * 3600)) / 3600);
  return h > 0 ? `${d}d ${h}h` : `${d}d`;
}

function _resetStats() {
  _stats = _emptyStats();
  _statsDirty = true;
  _flushStats();
  _lastListenTime = -1;
}

// Stats panel inside the Settings dialog. Pulls the latest numbers,
// resolves voice display name + top clip title, and hides the bottom
// extras + Reset button until there's actually been some listening.
async function _renderStatsPanel() {
  const todayEl = $("stats-today");
  const weekEl = $("stats-week");
  const totalEl = $("stats-total");
  const topVoiceEl = $("stats-top-voice");
  const topClipEl = $("stats-top-clip");
  const extrasEl = $("stats-extras");
  const emptyEl = $("stats-empty");
  const resetBtn = $("stats-reset");

  todayEl.textContent = _formatStatsDuration(_statsTodaySec());
  weekEl.textContent = _formatStatsDuration(_statsWeekSec());
  totalEl.textContent = _formatStatsDuration(_stats.total);

  const hasAny = _stats.total > 0;
  emptyEl.hidden = hasAny;
  extrasEl.hidden = !hasAny;
  resetBtn.hidden = !hasAny;
  if (!hasAny) return;

  // Top voice — display name preferred over the raw voice_id slug. The
  // <select> options carry friendly labels; fall back to the id if it's
  // not in the picker (e.g. an installed voice that was removed).
  const topVoiceId = _statsTopVoiceId();
  if (topVoiceId) {
    let label = topVoiceId;
    const opt = voiceEl.querySelector(`option[value="${CSS.escape(topVoiceId)}"]`);
    if (opt && opt.textContent) label = opt.textContent;
    topVoiceEl.textContent = label;
  } else {
    topVoiceEl.textContent = "—";
  }

  // Top clip — resolve via IndexedDB. If it was deleted, fall through.
  const topClipId = _statsTopClipId();
  if (topClipId) {
    try {
      const clip = await getClip(Number(topClipId));
      topClipEl.textContent = clip?.title || `Clip ${topClipId}`;
    } catch {
      topClipEl.textContent = `Clip ${topClipId}`;
    }
  } else {
    topClipEl.textContent = "—";
  }
}

// Reset stats. No native confirm() — keeps the dialog focused. Click the
// button once to arm ("Tap again to confirm"), again within 4 sec to wipe.
(() => {
  const resetBtn = $("stats-reset");
  let armed = false;
  let armTimer = null;
  const original = "Reset stats";
  resetBtn.addEventListener("click", () => {
    if (!armed) {
      armed = true;
      resetBtn.textContent = "Tap again to confirm";
      resetBtn.style.color = "var(--danger)";
      armTimer = setTimeout(() => {
        armed = false;
        resetBtn.textContent = original;
        resetBtn.style.color = "";
      }, 4000);
      return;
    }
    clearTimeout(armTimer);
    armed = false;
    resetBtn.textContent = original;
    resetBtn.style.color = "";
    _resetStats();
    _renderStatsPanel();
  });
})();

// ---- Bookmarks ----------------------------------------------------------
// Drop a timestamp on the currently-loaded clip while you're listening.
// Each bookmark gets an optional note (typed inline, no modal — the
// "Add a note…" placeholder reads as a hint without forcing a dialog).
// Bookmarks live as clip.bookmarks[] in IndexedDB and survive export/import.

// v225.tn61 (#534): returns the new bookmark's id so callers (e.g.
// the phone 🔖 button) can locate the just-added row in the
// re-rendered list and scroll/flash it.
//
// v225.tn65 (#547): debounce guard against double-fire. User
// reported duplicate bookmarks appearing in the drawer after a
// single 🔖 tap. Most likely cause: an Android click that fires
// twice (touch handlers + click event), OR two code paths
// dispatching simultaneously. The guard skips any add() called
// within 600ms of the previous one — comfortable above human
// double-tap intent (typically <300ms) but below "user really
// wants two close bookmarks" (which would be much slower).
let _lastBookmarkAddMs = 0;
// v225fq (#659): compute the start time (in seconds) of the i-th
// sentence in the current clip. Honors both playback modes:
//
//   - Streaming mode (per-sentence WAVs not yet concatenated): sum
//     the durations of all earlier sentences in _streamQueue.
//   - Combined WAV mode: read directly from sentenceOffsetsSec, the
//     server-provided sentence boundary table.
//
// Returns null if the index is out of range or we have no timing
// data yet (e.g. sentence hasn't been synthesized in streaming mode).
function _sentenceStartSec(i) {
  if (typeof i !== "number" || i < 0) return null;
  if (
    _streamPlayhead >= 0 &&
    Array.isArray(_streamQueue) &&
    i < _streamQueue.length
  ) {
    let elapsed = 0;
    for (let k = 0; k < i; k++) {
      elapsed += _streamQueue[k] ? (_streamQueue[k].durationSec || 0) : 0;
    }
    return elapsed;
  }
  if (
    typeof sentenceOffsetsSec !== "undefined" &&
    Array.isArray(sentenceOffsetsSec) &&
    i < sentenceOffsetsSec.length
  ) {
    return sentenceOffsetsSec[i];
  }
  return null;
}

async function addBookmarkAtCurrentTime() {
  if (!_currentClipId) {
    setStatus("Load a clip first — nothing to bookmark.", true);
    return null;
  }
  const _now =
    typeof performance !== "undefined" && performance.now
      ? performance.now()
      : Date.now();
  const _gap = Math.round(_now - _lastBookmarkAddMs);
  if (_now - _lastBookmarkAddMs < 600) {
    // Silent skip — the user already added one in the last 600ms,
    // and the previous addBookmarkAtCurrentTime call's status
    // toast is still showing.
    _dlog("bookmark", "debounce skip (call within 600ms)", {
      msSinceLast: _gap,
      stack: new Error().stack?.split("\n").slice(1, 5).join(" | "),
    });
    return null;
  }
  _lastBookmarkAddMs = _now;
  _dlog("bookmark", "addBookmarkAtCurrentTime entry", {
    clipId: _currentClipId,
    msSinceLast: _gap,
    stack: new Error().stack?.split("\n").slice(1, 5).join(" | "),
  });
  try {
    // v225fq (#659): if the user has a sentence selected (dashed
    // ring — same selection state Edit + Annotate use), bookmark
    // that sentence's start time instead of the current playback
    // position. Matches the "tap to select, then act" flow they've
    // already learned for the other tools. Falls through to
    // virtualTime() when nothing's selected.
    let t = virtualTime();
    let fromSelection = false;
    let selectedIdx = -1;
    if (
      typeof _selectedSentenceIdx === "number" &&
      _selectedSentenceIdx >= 0 &&
      Array.isArray(sentenceSpans) &&
      _selectedSentenceIdx < sentenceSpans.length
    ) {
      const s = _sentenceStartSec(_selectedSentenceIdx);
      if (s !== null && isFinite(s)) {
        t = s;
        fromSelection = true;
        selectedIdx = _selectedSentenceIdx;
      }
    }
    // v223.tn19 (#488): atomic read-modify-write so a concurrent
    // _syncAbsorbServerClip can't slip between our read and write
    // and cause our save to wipe newly-absorbed content (annotations,
    // highlights, etc.) on the server via LWW.
    let _newBookmarkId = null;
    const clip = await _mutateClipAtomic(_currentClipId, (c) => {
      if (!Array.isArray(c.bookmarks)) c.bookmarks = [];
      _newBookmarkId = Date.now();
      c.bookmarks.push({
        id: _newBookmarkId,
        timeSec: t,
        note: "",
        createdAt: new Date().toISOString(),
      });
      c.bookmarks.sort((a, b) => a.timeSec - b.timeSec);
    });
    if (!clip) return null;
    await renderBookmarks();
    // v210 (M6.1): if the book view is open, re-stash bookmarks +
    // re-render the current spread so the new ribbon shows up
    // immediately on the bookmarked page.
    if (_bookViewSource && typeof bookView !== "undefined" && bookView && !bookView.hidden) {
      _bookViewSource.bookmarks = clip.bookmarks;
      _bookViewRenderSpread(_bookViewCurrentSpread);
    }
    setStatus(
      fromSelection
        ? `Bookmark added at sentence ${selectedIdx + 1} (${formatTime(t)}).`
        : `Bookmark added at ${formatTime(t)}.`,
    );
    _dlog("bookmark", "add OK", {
      id: _newBookmarkId,
      timeSec: t,
      fromSelection: fromSelection,
      selectedIdx: fromSelection ? selectedIdx : null,
      totalBookmarks: clip.bookmarks.length,
    });
    return _newBookmarkId;
  } catch (e) {
    console.warn("bookmark add failed:", e);
    setStatus(`Bookmark failed: ${e.message}`, true);
    _dlog("bookmark", "add FAILED", { error: String(e) });
    return null;
  }
}

// v225.tn64 (#546): centered floating bookmark editor — single edit
// surface for both new and existing bookmarks. Replaces the inline
// <input> in the pull-up drawer which hit a Chromium Android bug
// where the keyboard closed immediately on focus (position:fixed
// drawer didn't resize for the keyboard). The centered modal stays
// in the visible viewport when the keyboard opens because its
// translate(-50%,-50%) recenters within whatever viewport is left.
let _bookmarkEditorBound = false;
let _bookmarkEditorCurrentId = null;
// v225fz (#668): track whether the open editor is a freshly-added
// bookmark (from the 🔖 button → addBookmarkAtCurrentTime → editor)
// vs. editing an existing one (tap a note row in the drawer). On
// cancel/dismiss the new path deletes the bookmark — author tapped
// 🔖 by accident or changed their mind, so leaving an empty
// timestamp-only row in the list feels like litter. Editing path
// always preserves the bookmark on cancel (no destructive default).
let _bookmarkEditorIsNew = false;

// v225fy (#667): char-count thresholds for the bookmark editor counter.
// 200 is the textarea's maxlength. WARN at 80% (160) gives the author
// runway to wrap up a thought; AT_LIMIT at 95% (190) makes the last
// 10 chars feel scarce so they don't get cut off mid-word. Driven by
// _paintBookmarkNoteCounter on every input event.
const _BOOKMARK_NOTE_MAX = 200;
const _BOOKMARK_NOTE_WARN_AT = 160;
const _BOOKMARK_NOTE_LIMIT_AT = 190;

function _paintBookmarkNoteCounter() {
  const noteEl = document.getElementById("bookmark-editor-note");
  const ctr = document.getElementById("bookmark-editor-note-counter");
  if (!noteEl || !ctr) return;
  const len = noteEl.value.length;
  ctr.textContent = `${len} / ${_BOOKMARK_NOTE_MAX}`;
  ctr.classList.toggle(
    "at-limit",
    len >= _BOOKMARK_NOTE_LIMIT_AT,
  );
  ctr.classList.toggle(
    "warn",
    len >= _BOOKMARK_NOTE_WARN_AT && len < _BOOKMARK_NOTE_LIMIT_AT,
  );
}

function _initBookmarkEditor() {
  if (_bookmarkEditorBound) return;
  const el = document.getElementById("bookmark-editor");
  if (!el) return;
  _bookmarkEditorBound = true;
  const close = (save) => _closeBookmarkEditor(save);
  el.querySelector(".bookmark-editor-close").addEventListener("click", () =>
    close(false),
  );
  el.querySelector(".bookmark-editor-cancel").addEventListener("click", () =>
    close(false),
  );
  el.querySelector(".bookmark-editor-save").addEventListener("click", () =>
    close(true),
  );
  // v225fy (#667): live char counter. Bound once on first init;
  // every keystroke + paste repaints. Also fires from _openBookmarkEditor
  // after pre-filling so the counter reflects the existing note
  // length on open (not the stale 0/200 from the previous edit).
  const noteEl = el.querySelector("#bookmark-editor-note");
  if (noteEl) {
    noteEl.addEventListener("input", _paintBookmarkNoteCounter);
    // v4.70 (#870): on desktop, plain Enter inside the note saves +
    // closes — matches Slack / Linear / iMessage where short-note
    // fields commit on Enter. Shift+Enter still inserts a newline
    // (escape hatch; bookmarks are capped at 200 chars so this is
    // rarely needed). Phone is excluded because the OS keyboard's
    // return key is universally expected to insert a newline; phone
    // users tap "Done" to commit. DEVICES.md scope: desktop only.
    noteEl.addEventListener("keydown", (e) => {
      if (e.key !== "Enter" || e.shiftKey || e.metaKey || e.ctrlKey) return;
      const isPhone = window.matchMedia("(max-width: 767px)").matches;
      if (isPhone) return;
      e.preventDefault();
      close(true);
    });
  }
  // Tap the backdrop (outside the card) to dismiss without saving.
  el.addEventListener("click", (e) => {
    if (e.target === el) close(false);
  });
  document.addEventListener("keydown", (e) => {
    if (el.hidden) return;
    if (e.key === "Escape") {
      e.preventDefault();
      close(false);
    } else if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
      // Cmd/Ctrl + Enter saves from anywhere in the dialog — even
      // if focus is on Cancel or the X. Power-user fallback that's
      // redundant with the noteEl handler above on desktop but
      // still useful on phone or when focus has drifted.
      e.preventDefault();
      close(true);
    }
  });
}

async function _openBookmarkEditor(bookmarkId, isNew) {
  _initBookmarkEditor();
  const el = document.getElementById("bookmark-editor");
  if (!el || !_currentClipId) return;
  try {
    const clip = await getClip(_currentClipId);
    if (!clip || !Array.isArray(clip.bookmarks)) return;
    const bm = clip.bookmarks.find((b) => b.id === bookmarkId);
    if (!bm) return;
    _bookmarkEditorCurrentId = bookmarkId;
    // v225fz (#668): default false so existing call sites (drawer note-row
    // tap) keep their old "always preserve" behavior. The 🔖 button path
    // passes true so a cancel reverts the just-added bookmark.
    _bookmarkEditorIsNew = isNew === true;
    const timeEl = document.getElementById("bookmark-editor-time-val");
    const noteEl = document.getElementById("bookmark-editor-note");
    if (timeEl) timeEl.textContent = formatTime(bm.timeSec);
    if (noteEl) noteEl.value = bm.note || "";
    // v225fy (#667): paint the counter against the pre-filled value
    // BEFORE the dialog renders so an existing 170-char note opens
    // with the .warn state already lit (no flash of stale 0/200).
    _paintBookmarkNoteCounter();
    el.hidden = false;
    // Focus + cursor-to-end after a frame so the modal is in the
    // render tree before we request keyboard focus. rAF gives the
    // browser time to paint the centered modal so the auto-scroll
    // for keyboard appearance has a settled position to scroll to.
    requestAnimationFrame(() => {
      if (noteEl) {
        noteEl.focus();
        try {
          const len = noteEl.value.length;
          noteEl.setSelectionRange(len, len);
        } catch {}
      }
    });
  } catch (e) {
    console.warn("[bookmark-editor] open failed:", e);
  }
}

async function _closeBookmarkEditor(save) {
  const el = document.getElementById("bookmark-editor");
  if (!el || el.hidden) return;
  const noteEl = document.getElementById("bookmark-editor-note");
  if (save && _bookmarkEditorCurrentId != null && noteEl) {
    const newNote = noteEl.value.trim();
    try {
      await updateBookmarkNote(_bookmarkEditorCurrentId, newNote);
      await renderBookmarks();
    } catch (e) {
      console.warn("[bookmark-editor] save failed:", e);
    }
  } else if (!save && _bookmarkEditorIsNew && _bookmarkEditorCurrentId != null) {
    // v225fz (#668): cancel/dismiss on a freshly-added bookmark reverts
    // the add so we don't litter the list with an empty timestamp the
    // user didn't actually want. ✕ / Cancel / Esc / backdrop tap all
    // hit this branch. "Done" with empty note is a separate, deliberate
    // commit ("I want a timestamp-only mark") — that flows through the
    // save branch above and the bookmark stays.
    try {
      await deleteBookmark(_bookmarkEditorCurrentId);
      // deleteBookmark already updates IDB + re-renders + status line.
    } catch (e) {
      console.warn("[bookmark-editor] revert-on-cancel failed:", e);
    }
  }
  el.hidden = true;
  _bookmarkEditorCurrentId = null;
  _bookmarkEditorIsNew = false;
}

// Initialize the editor wiring on first script load so any caller
// (including the phone 🔖 button) can use it without preflight.
_initBookmarkEditor();

async function updateBookmarkNote(bookmarkId, newNote) {
  if (!_currentClipId) return;
  try {
    // v223.tn19 (#488): atomic so concurrent absorb can't lose annotations.
    await _mutateClipAtomic(_currentClipId, (c) => {
      if (!Array.isArray(c.bookmarks)) return;
      const bm = c.bookmarks.find((b) => b.id === bookmarkId);
      if (bm) bm.note = newNote;
    });
    // No re-render needed; the user already sees their typed note.
  } catch (e) {
    console.warn("bookmark note save failed:", e);
  }
}

async function deleteBookmark(bookmarkId) {
  if (!_currentClipId) return;
  try {
    // v223.tn19 (#488): atomic so concurrent absorb can't lose annotations.
    const clip = await _mutateClipAtomic(_currentClipId, (c) => {
      if (!Array.isArray(c.bookmarks)) return;
      c.bookmarks = c.bookmarks.filter((b) => b.id !== bookmarkId);
    });
    if (!clip) return;
    await renderBookmarks();
    // v220bb: matching re-render path to addBookmark above. Without
    // this, deleting a bookmark via the Bookmarks dialog leaves the
    // 🔖 ribbon stuck on its book-view page until the user navigates
    // away and back. Re-stash + re-paint the current spread so the
    // visual matches the data.
    if (
      _bookViewSource &&
      typeof bookView !== "undefined" &&
      bookView &&
      !bookView.hidden
    ) {
      _bookViewSource.bookmarks = clip.bookmarks;
      _bookViewRenderSpread(_bookViewCurrentSpread);
    }
  } catch (e) {
    console.warn("bookmark delete failed:", e);
  }
}

// v220bb: delete ONE bookmark on the page when the ribbon is tapped.
// If multiple bookmarks resolve to the same page (rare — only happens
// if the user scrubbed back and re-bookmarked the same chunk), the
// earliest one goes first. Subsequent taps remove the rest one at a
// time, which gives the user fine-grained control rather than wiping
// the whole page in a single accidental tap. The ribbon disappears
// when the last bookmark on the page is gone.
async function _deleteBookmarksOnBookViewPage(textPageIdx) {
  if (!_currentClipId) return;
  try {
    const sentences = _bookViewPages[textPageIdx] || [];
    if (!sentences.length) return;
    const firstSent = sentences[0];
    const lastSent = sentences[sentences.length - 1];
    const firstSec = sentenceOffsetsSec[firstSent] || 0;
    const nextSent =
      (_bookViewPages[textPageIdx + 1] && _bookViewPages[textPageIdx + 1][0]) ||
      sentenceOffsetsSec.length;
    // v223.tn19 (#488): atomic so concurrent absorb can't lose annotations.
    let didDelete = false;
    const clip = await _mutateClipAtomic(_currentClipId, (c) => {
      if (!Array.isArray(c.bookmarks) || c.bookmarks.length === 0) return;
      const lastSec =
        sentenceOffsetsSec[nextSent] ||
        Number(c.durationSec) ||
        (sentenceOffsetsSec[lastSent] || 0) + 60;
      const victim = c.bookmarks.find(
        (b) => b.timeSec >= firstSec && b.timeSec < lastSec
      );
      if (!victim) return;
      c.bookmarks = c.bookmarks.filter((b) => b.id !== victim.id);
      didDelete = true;
    });
    if (!clip || !didDelete) return;
    await renderBookmarks();
    if (_bookViewSource) {
      _bookViewSource.bookmarks = clip.bookmarks;
      _bookViewRenderSpread(_bookViewCurrentSpread);
    }
    setStatus("Bookmark removed.");
  } catch (e) {
    console.warn("page-bookmark delete failed:", e);
  }
}

// Move the playhead to time `t` (in seconds within the clip's full timeline).
// Handles both streaming mode (jump to the per-sentence WAV that covers t,
// then nudge currentTime to the intra-sentence offset) and post-swap mode
// (direct currentTime). Used by bookmark jump.
function seekToTime(t) {
  t = Math.max(0, Number(t) || 0);
  if (_streamPlayhead >= 0 && sentenceOffsetsSec.length) {
    const idx = currentSentenceIndex(t);
    if (idx >= 0 && idx < _streamQueue.length) {
      const sentenceStart = sentenceOffsetsSec[idx] || 0;
      const intra = Math.max(0, t - sentenceStart);
      // Use the existing sentence-seek path to load the right per-sentence
      // WAV, then advance inside it once its metadata is ready.
      seekToSentence(idx);
      const onLoad = () => {
        playerEl.removeEventListener("loadedmetadata", onLoad);
        try {
          const cap = isFinite(playerEl.duration) ? playerEl.duration : intra;
          playerEl.currentTime = Math.min(cap, intra);
        } catch {}
      };
      playerEl.addEventListener("loadedmetadata", onLoad);
    }
    return;
  }
  // Post-swap / combined-WAV: direct currentTime move.
  try {
    const cap = isFinite(playerEl.duration) ? playerEl.duration : t;
    playerEl.currentTime = Math.min(cap, t);
  } catch {}
}

async function renderBookmarks() {
  // v225.tn67 (#549): fix duplicate-rows race. The clear used to
  // run BEFORE the await — meaning two concurrent renderBookmarks
  // calls (e.g. one from addBookmarkAtCurrentTime + one from a sync
  // absorb echo) would both clear an already-empty list, both await
  // getClip, then both append rows after their awaits resolved. Net
  // effect: 1 bookmark in data → 2 rows in DOM. Moving the clear to
  // AFTER the await makes "last write wins" — each call clears just
  // before its own append, so the final DOM matches the most recent
  // call's data. Confirmed via debug log (#548): user's single tap
  // produced 4 renderBookmarks calls, all observing count:1, but
  // the DOM ended up with 2 rows due to the interleaving.
  let bookmarks = [];
  if (_currentClipId) {
    try {
      const clip = await getClip(_currentClipId);
      if (clip && Array.isArray(clip.bookmarks)) bookmarks = clip.bookmarks;
    } catch {}
  }
  bookmarksList.innerHTML = "";
  _dlog("bookmark", "renderBookmarks", {
    count: bookmarks.length,
    ids: bookmarks.map((b) => b.id),
    times: bookmarks.map((b) => b.timeSec),
  });

  // Update the chip label so the bookmark count is visible even when the
  // list is scrolled out of view.
  bookmarkAddBtn.textContent =
    bookmarks.length > 0 ? `🔖 Bookmark · ${bookmarks.length}` : "🔖 Bookmark";

  if (bookmarks.length === 0) {
    bookmarksList.hidden = true;
    return;
  }
  bookmarksList.hidden = false;

  for (const bm of bookmarks) {
    const row = document.createElement("div");
    row.className = "bookmark-row";
    // v225.tn61 (#534): id-tagged so the phone 🔖 button can find
    // the just-added row after re-render and scroll/flash it.
    row.dataset.bookmarkId = String(bm.id);

    const timeBtn = document.createElement("button");
    timeBtn.type = "button";
    timeBtn.className = "bookmark-time";
    timeBtn.textContent = formatTime(bm.timeSec);
    timeBtn.title = `Jump to ${formatTime(bm.timeSec)}`;
    timeBtn.addEventListener("click", () => {
      seekToTime(bm.timeSec);
      playerEl.play().catch(() => {});
    });

    // v225.tn64 (#546): tap-to-edit note display. The previous inline
    // <input> caused the Android keyboard to close on focus because
    // the row is inside a position:fixed pull-up drawer that didn't
    // resize for the keyboard. Replaced with a button that opens the
    // centered floating editor — same edit path for new bookmarks
    // (via 🔖 button) and existing ones (via this tap).
    const noteInput = document.createElement("button");
    noteInput.type = "button";
    noteInput.className = "bookmark-note-display";
    if (bm.note && bm.note.length > 0) {
      noteInput.textContent = bm.note;
    } else {
      noteInput.textContent = "Add a note…";
      noteInput.classList.add("empty");
    }
    noteInput.addEventListener("click", (e) => {
      e.stopPropagation();
      if (typeof _openBookmarkEditor === "function") {
        _openBookmarkEditor(bm.id);
      }
    });

    const delBtn = document.createElement("button");
    delBtn.type = "button";
    delBtn.className = "bookmark-delete";
    delBtn.textContent = "×";
    delBtn.title = "Delete bookmark";
    delBtn.setAttribute("aria-label", `Delete bookmark at ${formatTime(bm.timeSec)}`);
    delBtn.addEventListener("click", () => deleteBookmark(bm.id));

    row.append(timeBtn, noteInput, delBtn);
    bookmarksList.appendChild(row);
  }

  // v225dy (#611): keep the pull-up Author summary ("N flags · N
  // bookmarks") fresh. Without this, the count was a snapshot at
  // drawer-open time — deleting a bookmark while the drawer was open
  // left the strip showing the old number until reopen.
  // renderBookmarks is the single funnel for every bookmark
  // mutation (add via 🔖 button, delete via × in row, tap-to-remove
  // on book-view ribbon, cross-device absorb), so wiring it here
  // covers every path in one place.
  if (typeof _updatePullupState === "function") {
    try { _updatePullupState(); } catch (e) {
      console.warn("[pullup] state refresh after bookmark render failed:", e);
    }
  }
  // v225ep (#632): keep the desktop author pane fresh too — same
  // mutation funnel, same lifecycle, just a different surface.
  if (typeof _renderAuthorPane === "function") {
    try { _renderAuthorPane(); } catch (e) {
      console.warn("[author pane] refresh after bookmark render failed:", e);
    }
  }
}

// v225fz2 (#669): desktop bookmark-add now routes through the centered
// editor with isNew=true, matching the phone 🔖 flow (v225fz / #668).
// The bookmark is persisted by addBookmarkAtCurrentTime; the editor
// then lets the author type a note while the moment is fresh, and
// cancel/Esc/✕/backdrop reverts the just-added bookmark via the
// _closeBookmarkEditor isNew branch. "Done" — with or without a note
// typed — commits. The command palette path (act:bookmark) keeps the
// bare call so keyboard-shortcut power users get fire-and-forget speed
// with no editor popup interrupting their flow.
bookmarkAddBtn.addEventListener("click", async () => {
  let newId = null;
  try {
    newId = await addBookmarkAtCurrentTime();
  } catch (err) {
    console.warn("[bookmark-add-btn] save failed:", err);
    setStatus("Bookmark failed.", true);
    return;
  }
  if (newId == null) return;
  if (typeof _openBookmarkEditor === "function") {
    _openBookmarkEditor(newId, true);
  }
});

// ---- Configurable skip-back / skip-forward ------------------------------
// Quick recovery for "I zoned out for a moment" + its mirror for "okay
// I got that, move me along." Separate from the MediaSession sentence
// skip on the lock screen (that one jumps a whole sentence, which is
// overkill when you just missed a word).
//
// The interval is user-configurable from Settings — authors revising
// their own prose want a tight 2s for re-hearing a tricky line; a
// commuter listening to a long article wants 30s for skipping ahead.
const SKIP_INTERVAL_KEY = "narrative.skipInterval";
const SKIP_INTERVALS = [2, 5, 10, 15, 30];
// v222 (#452): default to 15s instead of 5s. Audible's iconic
// 30-second skip-back is the dominant audiobook-listening expectation;
// 5s was tuned for revision-style "I missed a typo" use, which is
// real but narrower. 15s is the audiobook-app default for skip-back
// across Audible, Pocket Casts, Overcast. Existing users keep their
// saved pref via localStorage; only fresh installs land on 15s.
const DEFAULT_SKIP_INTERVAL = 15;

function _loadSkipInterval() {
  const raw = parseInt(localStorage.getItem(SKIP_INTERVAL_KEY), 10);
  return SKIP_INTERVALS.includes(raw) ? raw : DEFAULT_SKIP_INTERVAL;
}

let _skipInterval = _loadSkipInterval();
const skipForwardBtn = $("skip-forward-btn");

function _applySkipInterval() {
  const n = _skipInterval;
  skipBackBtn.textContent = `↶ ${n}s`;
  skipBackBtn.setAttribute("aria-label", `Skip back ${n} seconds`);
  skipBackBtn.title = `Skip back ${n} seconds`;
  skipForwardBtn.textContent = `${n}s ↷`;
  skipForwardBtn.setAttribute("aria-label", `Skip forward ${n} seconds`);
  skipForwardBtn.title = `Skip forward ${n} seconds`;
}

function setSkipInterval(n) {
  if (!SKIP_INTERVALS.includes(n)) return;
  _skipInterval = n;
  try { localStorage.setItem(SKIP_INTERVAL_KEY, String(n)); } catch {}
  _applySkipInterval();
}

// v222 (#462): double-tap detection for the skip-back chip. Single tap
// uses the configured interval (15s default per #452, or whatever the
// user dialed in Settings). Second tap within DOUBLE_TAP_MS triggers
// Audible's iconic 30-second jump-back. Mirrors the YouTube /
// Netflix double-tap-to-skip muscle memory — users tap-tap when they
// want a bigger jump without diving into Settings.
let _lastSkipBackTapAt = 0;
const DOUBLE_TAP_MS = 400;
const DOUBLE_TAP_SKIP_SEC = 30;

skipBackBtn.addEventListener("click", () => {
  // Use seekToTime so streaming mode + combined-WAV mode are both handled,
  // and the math is in terms of the virtual timeline (not whatever
  // per-sentence WAV happens to be loaded right now).
  const here = virtualTime();
  const now = Date.now();
  const isDoubleTap =
    _lastSkipBackTapAt > 0 && now - _lastSkipBackTapAt < DOUBLE_TAP_MS;
  // Reset timestamp on every action so a triple-tap doesn't compound
  // into a quad-tap (which would feel like the second double-tap got
  // swallowed). 1st tap → seek -interval, 2nd tap within window →
  // seek -30 from CURRENT position, 3rd tap → resets, behaves as 1st.
  _lastSkipBackTapAt = isDoubleTap ? 0 : now;
  const skipBy = isDoubleTap ? DOUBLE_TAP_SKIP_SEC : _skipInterval;
  seekToTime(Math.max(0, here - skipBy));
  if (isDoubleTap) {
    setStatus(`↶ Skipped back 30s`);
  }
});

skipForwardBtn.addEventListener("click", () => {
  // seekToTime already clamps to playerEl.duration on the way out, so
  // overshooting the end is a no-op rather than an error.
  const here = virtualTime();
  seekToTime(here + _skipInterval);
});

_applySkipInterval();

// ---- Sticky mini player -------------------------------------------------
// Shows a slim "now playing" bar at the top of the viewport once the main
// player card has scrolled off-screen, so play / pause / seek-back-to-
// player stay one tap away while you're scrolling through the library.
//
// Visibility is driven by an IntersectionObserver watching the main player
// card. The mini player mirrors playerEl state — it doesn't have its own
// audio. State sync flows: playerEl events → _updateMini*().
const miniPlayer = $("mini-player");
const miniPlayPause = $("mini-play-pause");
const miniInfo = $("mini-info");
const miniTitleEl = $("mini-title");
const miniTimeEl = $("mini-time");
const miniScrollUpBtn = $("mini-scroll-up");
const miniProgressFill = $("mini-progress-fill");

function _updateMiniPlayerState() {
  miniPlayPause.textContent = playerEl.paused ? "▶" : "⏸";
  const cur = virtualTime();
  // Prefer the cached duration from sentence offsets (works in streaming
  // mode too), otherwise fall back to playerEl.duration.
  const dur = isFinite(playerEl.duration) && playerEl.duration > 0
    ? playerEl.duration
    : 0;
  miniTimeEl.textContent = `${formatTime(cur)} / ${formatTime(dur)}`;
  if (dur > 0) {
    const pct = Math.min(100, Math.max(0, (cur / dur) * 100));
    miniProgressFill.style.width = `${pct}%`;
  } else {
    miniProgressFill.style.width = "0%";
  }
}

async function _updateMiniPlayerTitle() {
  if (!_currentClipId) {
    miniTitleEl.textContent = "Generating…";
    return;
  }
  try {
    const clip = await getClip(_currentClipId);
    if (clip) {
      miniTitleEl.textContent = clip.title || "(untitled)";
      miniTitleEl.title = clip.title || "";
    }
  } catch {}
}

// IntersectionObserver: slide the mini player in when the main player card
// has scrolled OFF THE TOP of the viewport — meaning the user has scrolled
// *past* it. Don't show it when the player is below the viewport (page
// just loaded and the user hasn't reached the player yet) — otherwise the
// mini bar covers the Narrative hero + ⚙ Settings button.
//
// boundingClientRect.bottom < 0 means the player is entirely above the
// viewport (scrolled past). bottom > 0 with !isIntersecting means it's
// below the viewport (not yet reached).
const _miniObserver = new IntersectionObserver(
  (entries) => {
    for (const entry of entries) {
      const scrolledPast = entry.boundingClientRect.bottom < 0;
      const shouldShow = !entry.isIntersecting && scrolledPast && !playerCard.hidden;
      if (shouldShow) {
        miniPlayer.hidden = false;
        // Force a layout pass so the browser registers the starting
        // transform before we toggle data-visible — without this, the
        // first show-on-page-load skips the slide-in animation.
        void miniPlayer.offsetHeight;
        miniPlayer.dataset.visible = "true";
        _updateMiniPlayerState();
        _updateMiniPlayerTitle();
      } else {
        miniPlayer.dataset.visible = "false";
        // Wait for the slide-out transition (matches the CSS duration)
        // before hiding so the bar doesn't pop out abruptly.
        setTimeout(() => {
          if (miniPlayer.dataset.visible !== "true") miniPlayer.hidden = true;
        }, 280);
      }
    }
  },
  { threshold: 0 }
);
_miniObserver.observe(playerCard);

miniPlayPause.addEventListener("click", () => {
  if (playerEl.paused) playerEl.play().catch(() => {});
  else _pauseAsUser();
});

// v222 (#451): tap ANYWHERE on the mini-player surface to jump to the
// full player card — matches Spotify / Apple Music / Audible, where the
// mini-player's whole body expands to Now Playing on tap. The only
// dead zone is the play/pause button (its own click handler runs and
// the event handler below bails out when the target is inside it).
// Previously only the title block and the explicit ↑ button were
// tappable; tester muscle memory from those three apps means users tap
// the title, the time, the empty gap, anywhere — and most of those
// taps did nothing.
function _scrollToPlayer() {
  playerCard.scrollIntoView({ behavior: "smooth", block: "start" });
}
const _miniPlayerEl = $("mini-player");
if (_miniPlayerEl) {
  _miniPlayerEl.addEventListener("click", (event) => {
    // Don't intercept clicks on the play/pause button — it has its
    // own handler that toggles playback. Use closest() so a click on
    // the button's child glyph still resolves to the button correctly.
    if (event.target.closest("#mini-play-pause")) return;
    _scrollToPlayer();
  });
}

playerEl.addEventListener("timeupdate", _updateMiniPlayerState);
playerEl.addEventListener("play", _updateMiniPlayerState);
playerEl.addEventListener("pause", _updateMiniPlayerState);
playerEl.addEventListener("loadedmetadata", _updateMiniPlayerState);

// ---- Resume position ---------------------------------------------------
// Per-clip "remember where I left off." Saved into the existing IndexedDB
// row by mutating clip.progressSec; throttled so we're not hitting the DB
// every timeupdate.

async function maybeSaveProgress(force = false) {
  if (!_currentClipId) return;
  // Don't try to save during streaming — the offsets are local to the
  // current sentence's WAV, not the whole clip. We'll start saving once
  // the swap to combined WAV happens (_streamPlayhead drops back to -1).
  if (_streamPlayhead >= 0) return;
  if (!isFinite(playerEl.currentTime)) return;
  const now = Date.now();
  if (!force && now - _lastProgressSaveAt < PROGRESS_SAVE_INTERVAL_MS) return;
  _lastProgressSaveAt = now;
  try {
    // v223.tn2: atomic read-modify-write inside one IDB tx so the
    // progress tick can't race a concurrent annotation/bookmark add
    // and clobber its changes. The bug: this function fires every few
    // seconds during playback. Old path was getClip → mutate
    // progressSec → saveClip(clip), which writes the in-memory clip
    // wholesale. If an annotation save landed between this function's
    // getClip and its saveClip, the in-memory snapshot had
    // `annotations: []` and the save would wipe the new annotation
    // both locally and on the server. Wrapping the read+put in a
    // single readwrite tx forces IDB to serialize on the annotation
    // tx, so when we read, we see whatever it just wrote.
    const db = await openDB();
    const tx = db.transaction(STORE, "readwrite");
    const store = tx.objectStore(STORE);
    const clip = await idbReq(store.get(_currentClipId));
    if (!clip) return;
    clip.progressSec = playerEl.currentTime;
    clip.updatedAt = new Date().toISOString();
    await idbReq(store.put(clip));
    await new Promise((res, rej) => {
      tx.oncomplete = res;
      tx.onerror = () => rej(tx.error);
      tx.onabort = () => rej(tx.error);
    });
    if (typeof _syncPushClip === "function") {
      _syncPushClip(clip).catch((e) =>
        console.warn("[sync] push failed:", e),
      );
    }
  } catch (e) {
    console.warn("progress save failed:", e);
  }
}

async function markCurrentClipPlayed() {
  if (!_currentClipId) return;
  try {
    // v223.tn19 (#488): atomic so concurrent absorb can't lose annotations.
    await _mutateClipAtomic(_currentClipId, (c) => {
      c.progressSec = 0;
      c.playedAt = new Date().toISOString();
    });
    renderLibrary();
  } catch (e) {
    console.warn("mark-played failed:", e);
  }
}

function setStatus(msg, isError = false) {
  statusEl.textContent = msg || "";
  statusEl.classList.toggle("error", !!isError);
}

function enterBusyState() {
  // Switch button to "Cancel" mode — still clickable to abort.
  generateBtn.classList.replace("primary", "secondary");
  genLabel.textContent = "Cancel";
  genSpinner.hidden = false;
  synthProgress.value = 0;
  synthProgress.hidden = false;
  downloadBtn.disabled = true;
}

function exitBusyState() {
  generateBtn.classList.replace("secondary", "primary");
  genLabel.textContent = "Generate";
  genSpinner.hidden = true;
  synthProgress.hidden = true;
  if (lastBlob) downloadBtn.disabled = false;
}

function _countWords(text) {
  const trimmed = (text || "").trim();
  if (!trimmed) return 0;
  // Split on any whitespace; the regex handles tabs / newlines / multiple
  // spaces in one shot. Matches what most writing apps report.
  return trimmed.split(/\s+/).length;
}

function _estimateReadSeconds(words, wpm) {
  if (!words || !wpm) return 0;
  return (words / wpm) * 60;
}

function updateCounts() {
  const text = textEl.value;
  const len = text.length;
  let label = `${len.toLocaleString()} / 500,000`;

  // Author-mode extras: word count + read-aloud time estimate. Hidden by
  // default so a reader who's pasting articles doesn't see writing stats
  // they don't care about.
  if (isAuthorMode()) {
    const words = _countWords(text);
    const wpm = Number(rateEl.value) || 180;
    const sec = _estimateReadSeconds(words, wpm);
    if (words > 0) {
      label += ` · ${words.toLocaleString()} words · ~${formatTime(sec)} at ${wpm} wpm`;
    } else {
      label += ` · 0 words`;
    }
  }

  charCountEl.textContent = label;

  // The filler chip strip rebuilds on every keystroke. CSS gates author-
  // only visibility so this DOM stays empty / hidden for readers — but
  // running the counter is essentially free, so we don't branch on
  // isAuthorMode here.
  _renderFillerChips(text);

  // v225g1 (#690): keep "📖 Open as ebook" enabled in sync with whether
  // there's any text. updateCounts already fires on every textarea
  // input + after every paste / extract / sample-text injection, so
  // piggybacking here means we don't need separate listeners.
  if (typeof _updateOpenAsEbookEnabled === "function") {
    _updateOpenAsEbookEnabled();
  }
}

// ---- Filler-word callout (Author mode) ---------------------------------
// Common crutch words. Singular & easy to extend — the regex is built
// from this list at module load. Multi-word entries ("kind of", "sort
// of") need the regex to allow a single space inside the match.
const FILLER_WORDS = [
  "just",
  "very",
  "really",
  "actually",
  "basically",
  "literally",
  "that",
  "even",
  "somehow",
  "perhaps",
  "quite",
  "simply",
  "rather",
  "maybe",
  "totally",
  "definitely",
  "honestly",
  "obviously",
  "kind of",
  "sort of",
];

// Pre-build one big alternation. Word boundaries on both ends so "thatch"
// doesn't count as "that". `gi` flags for global + case-insensitive.
const _FILLER_RE = new RegExp(
  "\\b(" +
    FILLER_WORDS.map((w) => w.replace(/ /g, "\\s+")).join("|") +
    ")\\b",
  "gi"
);

function _countFillerWords(text) {
  const counts = new Map();
  if (!text) return counts;
  const matches = text.match(_FILLER_RE);
  if (!matches) return counts;
  for (const raw of matches) {
    // Normalize internal whitespace so "kind  of" and "kind of" collapse,
    // and lowercase so "Just" and "just" aggregate.
    const key = raw.toLowerCase().replace(/\s+/g, " ");
    counts.set(key, (counts.get(key) || 0) + 1);
  }
  return counts;
}

const fillerCountsEl = $("filler-counts");
// Cap visible chips so a long manuscript doesn't fill the screen. Top-N
// by count is the useful signal — the long tail is noise.
const FILLER_TOP_N = 8;

function _renderFillerChips(text) {
  const counts = _countFillerWords(text);
  if (counts.size === 0) {
    fillerCountsEl.hidden = true;
    fillerCountsEl.innerHTML = "";
    return;
  }
  // Stable ordering: count desc, then alphabetical so equal counts don't
  // jitter as the user types.
  const sorted = [...counts.entries()]
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
    .slice(0, FILLER_TOP_N);

  fillerCountsEl.innerHTML = "";
  for (const [word, n] of sorted) {
    const chip = document.createElement("span");
    chip.className = "filler-chip";
    const label = document.createElement("span");
    label.className = "filler-word";
    label.textContent = word;
    const num = document.createElement("strong");
    num.textContent = String(n);
    chip.append(label, num);
    fillerCountsEl.appendChild(chip);
  }
  fillerCountsEl.hidden = false;
}

rateEl.addEventListener("input", () => {
  rateValueEl.textContent = rateEl.value;
  // Author mode shows "~M:SS at N wpm" in the textarea meta — the
  // estimate depends on the current rate, so refresh it as the slider moves.
  if (isAuthorMode()) updateCounts();
});

volumeEl.addEventListener("input", () => {
  volumeValueEl.textContent = `${volumeEl.value}%`;
});

textEl.addEventListener("input", () => {
  updateCounts();
  _updateEmptyState();
});
updateCounts();

// v149: first-run empty-state. Originally gated to "user has NEVER
// generated a clip" — but a tester with 11 clips in their library
// landed on an empty textarea between sessions and didn't know what
// to do (v220b feedback). The Import ▼ dropdown in the card header
// is too quiet to be the only orientation cue. Show the cards
// whenever the textarea is empty + no current clip + not in reading
// view; adapt the head text so returning users don't see the
// "New to Narrative?" welcome.
// v220ap: localStorage flag to track "user explicitly dismissed the
// start-a-new-clip helper." Survives reloads. First-time users (no
// clips in library) ignore the flag because the helper is genuinely
// useful for them; only returning users get the suppression. Settings
// can clear the flag to bring the helper back.
const _EMPTY_STATE_DISMISSED_KEY = "narrative.dismissedEmptyState";
function _isEmptyStateDismissed() {
  try {
    return localStorage.getItem(_EMPTY_STATE_DISMISSED_KEY) === "1";
  } catch {
    return false;
  }
}
function _setEmptyStateDismissed(dismissed) {
  try {
    if (dismissed) {
      localStorage.setItem(_EMPTY_STATE_DISMISSED_KEY, "1");
    } else {
      localStorage.removeItem(_EMPTY_STATE_DISMISSED_KEY);
    }
  } catch {}
}

function _updateEmptyState() {
  if (!emptyStateEl) return;
  // Reading view active → the user is listening to something already.
  // Clip loaded → not the empty case either. Suppress in both cases.
  const hasText = (textEl.value || "").trim().length > 0;
  const inReadingView = !textEl.parentNode || textEl.hidden;
  // v220ap: × button or Settings can dismiss the helper. Honored
  // for everyone (including first-timers) so the dismiss tap always
  // does what it says. The textarea below still works without the
  // helper, and Settings → "Start-a-new-clip helper" → Show brings
  // it back if a first-timer regrets the dismiss.
  const dismissed = _isEmptyStateDismissed();
  const show = !hasText && !_currentClipId && !inReadingView && !dismissed;
  const wasShown = !emptyStateEl.hidden;
  emptyStateEl.hidden = !show;
  // v220b: swap the head text based on user state. First-time users
  // get the welcome; returning users get a compact "next thing to do"
  // prompt so the empty state reads as a quick-pick row, not an
  // onboarding splash they've already moved past.
  if (show) {
    const head = emptyStateEl.querySelector(".empty-state-head");
    if (head) {
      head.textContent = _libraryHasClips
        ? "Start a new clip:"
        : "New to Narrative? Try one of these to get started.";
    }
    // v225fw (#665): pulse the "Watch tutorial" rows so users notice
    // the secondary affordance. Only fire on the EDGE (hidden → shown)
    // so we don't restart the animation every time _updateEmptyState
    // is called (it's called from many code paths and would otherwise
    // make the pulse run on every keystroke / clip event). Reset by
    // toggling the class off-then-on across a frame so the animation
    // restarts cleanly even if it had completed earlier in the session.
    if (!wasShown) _pulseEmptyStateTutorialLinks();
  }
}

// v225fw (#665): add the attention-pulse class to every Watch-tutorial
// row in the empty state. Listens once for any interaction inside the
// empty state to cancel the pulse (so a user who's already mid-action
// doesn't keep seeing the wobble after they've committed). Pulse is
// purely cosmetic — the click handlers on the tutorial-link spans + on
// the empty-state cards are already wired separately.
function _pulseEmptyStateTutorialLinks() {
  if (!emptyStateEl) return;
  const links = emptyStateEl.querySelectorAll(".empty-state-tutorial-link");
  if (!links.length) return;
  // Remove any stale class first so the animation restarts cleanly on
  // the second-and-later edge transitions.
  links.forEach((el) => el.classList.remove("attention-pulse"));
  // Defer the add by one frame so the browser commits the class
  // removal before the re-add — otherwise the animation just keeps
  // running from wherever it was.
  requestAnimationFrame(() => {
    links.forEach((el) => el.classList.add("attention-pulse"));
  });
  // First interaction inside the helper cancels the pulse on every
  // link (not just the one tapped). Bound on the container so we get
  // one listener total, not 4. {once:true} auto-cleans.
  emptyStateEl.addEventListener(
    "click",
    () => {
      links.forEach((el) => el.classList.remove("attention-pulse"));
    },
    { once: true },
  );
}
// Card clicks reuse the existing Import-dropdown paths so the action
// behavior stays in one place (no duplicate file pickers, no
// duplicate showUrlRow callers).
// v220c: short demo paragraph used by the "Try sample text" empty-state
// card. Chosen to (a) have rich-enough prosody to showcase the voice,
// (b) include a comma + a question + a name so the prosody differences
// vs ElevenLabs-style voices are audible, and (c) be short enough that
// a brand-new user hears the synth complete in under 20 seconds.
const _SAMPLE_TEXT =
  "Welcome to Narrative. I'm a sample paragraph, here so you can hear " +
  "what this voice sounds like before you paste your own text. Try " +
  "swapping the voice in the top-right corner, or change the speed " +
  "and volume sliders below. Then come back and replace me with your " +
  "own chapter, article, or note — and hit Generate.";

document.querySelectorAll("[data-empty-action]").forEach((btn) => {
  btn.addEventListener("click", () => {
    const action = btn.dataset.emptyAction;
    if (action === "url") {
      if (urlRow.hidden) showUrlRow({ placeholder: "https://… (article URL)" });
      else urlInput.focus();
    } else if (action === "file") {
      uploadInput.click();
    } else if (action === "github") {
      showUrlRow({
        placeholder: "github.com/owner/repo",
        prefill: "https://github.com/",
        hint:
          'Paste the <strong>repo root</strong> — like ' +
          '<code>github.com/owner/repo</code> — not a link to a ' +
          'specific file. We\'ll open a picker so you can choose ' +
          'which chapters to import.',
      });
    } else if (action === "sample") {
      // v220c: paste sample text + focus the textarea (cursor lands
      // at end) + scroll to the Generate button. Re-runs the empty-
      // state check so the cards hide now that there's text, and
      // updates the live word-count chip. setStatus gives a one-line
      // breadcrumb pointing at what to do next.
      textEl.value = _SAMPLE_TEXT;
      textEl.focus();
      textEl.setSelectionRange(_SAMPLE_TEXT.length, _SAMPLE_TEXT.length);
      updateCounts();
      _updateEmptyState();
      const genBtn = document.getElementById("generate");
      if (genBtn) genBtn.scrollIntoView({ behavior: "smooth", block: "nearest" });
      setStatus("Sample text loaded — hit Generate to hear it.");
    } else if (action === "ebook") {
      // v225g1 (#690): "📖 Read as ebook" tile — same upload flow as
      // the file tile, but stash _pendingEbookMode so the post-extract
      // hook auto-routes through _openAsEbook (see uploadInput change
      // handler) instead of leaving the text in the textarea waiting
      // for a Generate tap. Users who only want to read EPUBs without
      // burning synth never have to think about voice / audio at all.
      _pendingEbookMode = true;
      setStatus("Pick an EPUB / PDF — it'll open in book view once extracted.");
      uploadInput.click();
    }
  });
});

// v225g1 (#690): "📖 Open as ebook" button next to Generate — single
// entry point that doesn't need an import; uses whatever text + images
// are currently staged.
const _openAsEbookBtn = document.getElementById("open-as-ebook");
if (_openAsEbookBtn) {
  _openAsEbookBtn.addEventListener("click", () => {
    _openAsEbook().catch((e) => {
      console.error("[ebook] _openAsEbook failed:", e);
      setStatus("Couldn't open as ebook — see console.", true);
    });
  });
}

// v225v3.11: the "📖 Read as ebook" button inside the import-preview
// head (v225g1 #690) was removed. The empty-state tile + ☰-menu entry
// remain as the ebook-mode entry points.

// voice_id → num_speakers, populated from /api/voices. Used by onVoiceChange
// to decide whether to surface the speaker picker. SAPI voices and most
// Piper voices have num_speakers=1; LibriTTS is the headline 904-speaker model.
const _voiceSpeakerCounts = new Map();

// Tracks the "voices haven't loaded yet" state so generate() can show a
// different (gentler) error when the user clicks Generate during a retry
// loop versus when no voice is genuinely selectable. Cleared on success.
let _voicesLoadFailed = false;
let _voicesRetryTimer = null;

async function loadVoices() {
  try {
    const res = await fetch("/api/voices");
    if (!res.ok) throw new Error(`voices request failed: ${res.status}`);
    const data = await res.json();
    voiceEl.innerHTML = "";
    _voiceSpeakerCounts.clear();
    if (!data.voices || data.voices.length === 0) {
      const opt = document.createElement("option");
      opt.textContent = "No voices found on this system";
      opt.disabled = true;
      voiceEl.appendChild(opt);
      onVoiceChange();
      return;
    }

    // Local helper so the favorites optgroup and the engine groups share
    // exactly the same option-rendering format. Anything that ends up in
    // _voiceSpeakerCounts during this pass is also driven through here.
    const renderOpt = (v) => {
      const opt = document.createElement("option");
      opt.value = v.id;
      const suffix =
        v.engine === "piper" || !v.languages?.[0] ? "" : ` · ${v.languages[0]}`;
      const multi = v.num_speakers > 1 ? ` · ${v.num_speakers} voices` : "";
      opt.textContent = `${v.name}${suffix}${multi}`;
      _voiceSpeakerCounts.set(v.id, Number(v.num_speakers) || 1);
      return opt;
    };

    // ★ Favorites optgroup — only the user's starred installed voices, in
    // the order they starred them (most-recently first). Skipped when no
    // favorites are starred so a fresh install doesn't show an empty header.
    const favIds = getFavoriteVoices();
    if (favIds.length > 0) {
      const favByEngine = new Map(data.voices.map((v) => [v.id, v]));
      const favVoices = favIds
        .map((id) => favByEngine.get(id))
        .filter(Boolean);
      if (favVoices.length > 0) {
        const og = document.createElement("optgroup");
        og.label = "★ Favorites";
        for (const v of favVoices) og.appendChild(renderOpt(v));
        voiceEl.appendChild(og);
      }
    }

    const groups = [
      { engine: "piper", label: "Neural (high quality)" },
      { engine: "sapi", label: "System voices" },
    ];

    for (const g of groups) {
      const voices = data.voices.filter((v) => v.engine === g.engine);
      if (voices.length === 0) continue;
      const og = document.createElement("optgroup");
      og.label = g.label;
      for (const v of voices) {
        og.appendChild(renderOpt(v));
      }
      voiceEl.appendChild(og);
    }
    // Sync the speaker row to whichever voice ended up selected.
    onVoiceChange();
    // Success — clear any retry state from a previous cold-start cycle.
    _voicesLoadFailed = false;
    if (_voicesRetryTimer) {
      clearTimeout(_voicesRetryTimer);
      _voicesRetryTimer = null;
    }
  } catch (err) {
    // Surface the failure prominently and schedule an auto-retry. The
    // common cause is a Fly.io cold-start 503 — the machine is waking
    // and the catalog endpoint won't respond until uvicorn is up. Auto-
    // retrying every 10s gets the user from "dropdown is empty and I
    // don't know why" to "ah, it's just warming up" without manual
    // refreshes. Local 503s (real server bug) also get the retry, which
    // is fine — the worst case is a polite loop until the user reloads.
    _voicesLoadFailed = true;
    const m = String(err.message).match(/\b(\d{3})\b/);
    const httpCode = m ? m[1] : null;
    const detail = httpCode === "503"
      ? `Server is waking up (${httpCode}) — retrying in 10s…`
      : `Could not load voices: ${err.message} — retrying in 10s…`;
    setStatus(detail, true);
    if (_voicesRetryTimer) clearTimeout(_voicesRetryTimer);
    _voicesRetryTimer = setTimeout(() => {
      _voicesRetryTimer = null;
      loadVoices();
    }, 10_000);
  }
}

// ---- Speaker picker -----------------------------------------------------
// Shown only when the selected voice has num_speakers > 1. Selection is
// persisted per voice in localStorage so switching away and back doesn't
// reset you to speaker 0.
const SPEAKER_STORAGE_KEY = "narrative.speakerByVoice";

function _loadSpeakerMap() {
  try {
    return JSON.parse(localStorage.getItem(SPEAKER_STORAGE_KEY) || "{}");
  } catch {
    return {};
  }
}

function _saveSpeakerMap(map) {
  try {
    localStorage.setItem(SPEAKER_STORAGE_KEY, JSON.stringify(map));
  } catch {}
}

function rememberedSpeaker(voiceId) {
  const map = _loadSpeakerMap();
  const v = Number(map[voiceId]);
  return Number.isFinite(v) && v >= 0 ? v : 0;
}

function rememberSpeaker(voiceId, speakerId) {
  const map = _loadSpeakerMap();
  map[voiceId] = Number(speakerId) || 0;
  _saveSpeakerMap(map);
}

// ---- Voice favorites ----------------------------------------------------
// User-starred voices. Drives the "★ Favorites" optgroup at the top of
// the main picker AND a filter chip in the voice browser. Stored as an
// array so the user's star order is stable (most-recently-starred floats
// to the top within the favorites list).
// GitHub Personal Access Token (PAT) for fetching from private repos.
// Stored in localStorage so it persists across sessions on this device
// only. The token is sent to /api/extract/url in the request body when
// the URL is a GitHub URL; the backend forwards it as a Bearer token
// to github.com / raw.githubusercontent.com only.
const GITHUB_TOKEN_KEY = "narrative.githubToken";

function getGithubToken() {
  try {
    return (localStorage.getItem(GITHUB_TOKEN_KEY) || "").trim();
  } catch {
    return "";
  }
}

// v163: remember recently-browsed GitHub repos so the user can
// re-open them with one click — both from Import → GitHub (chip
// row above the URL field) and from the queue panel (chips at the
// bottom). v176: expanded from a single most-recent value to a
// list of up to 5, most-recent-first, deduped by URL.
const LAST_GITHUB_REPO_KEY = "narrative.lastGithubRepo";       // legacy (single)
const RECENT_GITHUB_REPOS_KEY = "narrative.recentGithubRepos"; // v176 list
const RECENT_GITHUB_REPOS_MAX = 5;

// v176 helpers -----------------------------------------------------------
// Read the recent-repos list. On first read after a v176 upgrade we
// also migrate the legacy single-value key into the new list so the
// user doesn't lose their last-opened repo.
function _getRecentGithubRepos() {
  try {
    const raw = localStorage.getItem(RECENT_GITHUB_REPOS_KEY);
    if (raw) {
      const arr = JSON.parse(raw);
      if (Array.isArray(arr)) {
        return arr.filter(
          (r) => r && r.url && r.owner && r.repo
        ).slice(0, RECENT_GITHUB_REPOS_MAX);
      }
    }
    // Migrate from the v163 single-value key if present.
    const legacyRaw = localStorage.getItem(LAST_GITHUB_REPO_KEY);
    if (legacyRaw) {
      const obj = JSON.parse(legacyRaw);
      if (obj && obj.url && obj.owner && obj.repo) {
        const seed = [obj];
        try {
          localStorage.setItem(RECENT_GITHUB_REPOS_KEY, JSON.stringify(seed));
        } catch {}
        return seed;
      }
    }
  } catch {}
  return [];
}

// Push (or move-to-front) a repo on the recent list. Dedupes by url
// and caps at RECENT_GITHUB_REPOS_MAX. Also writes through the
// legacy single-value key so any code path still reading the old key
// keeps working until it's migrated.
function _pushRecentGithubRepo(info) {
  if (!info || !info.url || !info.owner || !info.repo) return;
  const list = _getRecentGithubRepos();
  const url = info.url;
  const filtered = list.filter((r) => r.url !== url);
  filtered.unshift({
    url: info.url,
    owner: info.owner,
    repo: info.repo,
    branch: info.branch || null,
  });
  const capped = filtered.slice(0, RECENT_GITHUB_REPOS_MAX);
  try {
    localStorage.setItem(RECENT_GITHUB_REPOS_KEY, JSON.stringify(capped));
    localStorage.setItem(LAST_GITHUB_REPO_KEY, JSON.stringify(capped[0]));
  } catch {}
  if (typeof _renderBgQueuePanel === "function") _renderBgQueuePanel();
}

// Backward-compat: callers that need "most recent" still work. Reads
// from the new list (which auto-migrates from the legacy key) and
// returns the head, or null if the list is empty.
function _getLastGithubRepo() {
  const list = _getRecentGithubRepos();
  return list.length > 0 ? list[0] : null;
}

// Kept as an alias so older v163 call sites continue to compile.
// New code should call _pushRecentGithubRepo directly.
function _setLastGithubRepo(info) {
  _pushRecentGithubRepo(info);
}

function setGithubToken(token) {
  try {
    if (token && token.trim()) {
      localStorage.setItem(GITHUB_TOKEN_KEY, token.trim());
    } else {
      localStorage.removeItem(GITHUB_TOKEN_KEY);
    }
  } catch {}
}

// v180: GitHub OAuth — capture the access token from the URL fragment
// after the server's /api/github/oauth/callback redirects back to /.
// The fragment carries `#gh_token=...` so the token never appears in
// access logs or Referer headers. We store it via setGithubToken (same
// path the PAT paste uses), surface a one-shot success status, then
// clear the fragment + the query param via history.replaceState so a
// reload doesn't re-process the same token.
function _captureGithubOAuthRedirect() {
  try {
    const hash = window.location.hash || "";
    const search = window.location.search || "";
    let captured = null;
    let success = false;
    let errMsg = null;

    // Parse the fragment for gh_token=...
    if (hash.startsWith("#") && hash.includes("gh_token=")) {
      const params = new URLSearchParams(hash.slice(1));
      const tok = params.get("gh_token");
      if (tok) captured = tok;
    }
    // Parse the query for the success / error signals.
    if (search) {
      const q = new URLSearchParams(search);
      success = q.get("gh_oauth") === "success";
      errMsg = q.get("gh_oauth_error");
    }

    if (captured) {
      setGithubToken(captured);
      _dlog && _dlog("oauth", "GitHub OAuth captured token from fragment", {
        chars: captured.length,
      });
      // Clear fragment + query so a reload doesn't re-show the toast
      // and the token isn't sitting in window.location for any rogue
      // script to read.
      try {
        history.replaceState({}, "", window.location.pathname);
      } catch {}
      // Defer status until setStatus is wired (it's declared later in
      // the file). On a typical run this fires after init though.
      setTimeout(() => {
        try {
          if (typeof setStatus === "function") {
            setStatus("✓ Signed in with GitHub — token saved.");
          }
        } catch {}
      }, 0);
      // Best-effort: surface signed-in user display once Settings
      // opens. _refreshGithubOAuthUI handles both cases.
      if (typeof _refreshGithubOAuthUI === "function") {
        _refreshGithubOAuthUI();
      }
    } else if (errMsg) {
      _dlog && _dlog("oauth", `GitHub OAuth error from server: ${errMsg}`, {});
      try { history.replaceState({}, "", window.location.pathname); } catch {}
      setTimeout(() => {
        try {
          if (typeof setStatus === "function") {
            setStatus(`GitHub sign-in failed: ${errMsg}`, true);
          }
        } catch {}
      }, 0);
    } else if (success) {
      // Success flag without a token is unexpected but harmless. Tidy
      // the URL so a reload doesn't re-trigger the branch.
      try { history.replaceState({}, "", window.location.pathname); } catch {}
    }
  } catch (err) {
    // Defensive: never let URL parsing break boot. The user can still
    // paste a PAT manually.
    console.warn("[oauth] capture failed:", err);
  }
}
_captureGithubOAuthRedirect();

function _isGithubUrl(url) {
  try {
    const u = new URL(url);
    return (
      u.hostname === "github.com" ||
      u.hostname === "www.github.com" ||
      u.hostname === "raw.githubusercontent.com" ||
      // v181: Gist raw file URLs go through this host. The PAT
      // forwarding gate above (only attach token for GitHub URLs)
      // also needs to apply to gists, so include both Gist hosts
      // in the check.
      u.hostname === "gist.github.com" ||
      u.hostname === "gist.githubusercontent.com"
    );
  } catch {
    return false;
  }
}

// v181: Gist-specific detector. Only the gist.github.com host counts
// — gist.githubusercontent.com is a raw-file CDN, not a URL the user
// would paste expecting to see a file picker. fetchFromUrl routes
// matching URLs to openGistBrowser.
function _isGistUrl(url) {
  try {
    const u = new URL(url);
    return u.hostname === "gist.github.com";
  } catch {
    return false;
  }
}

// v4.96 (#892): Google Drive share URL detector. Covers both Drive
// (drive.google.com/file/d/…, drive.google.com/open?id=…) and Docs
// (docs.google.com/document/d/…). fetchFromUrl routes matching URLs
// through /api/extract/gdrive instead of /api/extract/url so the
// backend can route Docs through their export endpoint.
function _isGdriveUrl(url) {
  try {
    const u = new URL(url);
    return (
      u.hostname === "drive.google.com" ||
      u.hostname === "docs.google.com"
    );
  } catch {
    return false;
  }
}

const VOICE_FAVORITES_KEY = "narrative.voiceFavorites";

function getFavoriteVoices() {
  try {
    const raw = localStorage.getItem(VOICE_FAVORITES_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter((x) => typeof x === "string") : [];
  } catch { return []; }
}

function isFavoriteVoice(voiceId) {
  return getFavoriteVoices().includes(voiceId);
}

function toggleFavoriteVoice(voiceId) {
  if (!voiceId) return false;
  const list = getFavoriteVoices();
  const idx = list.indexOf(voiceId);
  if (idx >= 0) {
    list.splice(idx, 1);
  } else {
    list.unshift(voiceId); // newest at top
  }
  try {
    localStorage.setItem(VOICE_FAVORITES_KEY, JSON.stringify(list));
  } catch {}
  return idx < 0; // true when we just added
}

// Re-fetch /api/voices and rebuild the main picker so the "★ Favorites"
// optgroup stays in sync after a star toggle. Preserves the currently-
// selected voice so the user doesn't lose their place when starring
// while a clip is loaded.
async function _refreshFavoritesInMainPicker() {
  const previous = voiceEl.value;
  await loadVoices();
  if (previous && voiceEl.querySelector(`option[value="${CSS.escape(previous)}"]`)) {
    voiceEl.value = previous;
    onVoiceChange();
  }
}

// Above this many speakers, the native dropdown is unusable (LibriTTS:
// 904) — we hide it and surface a chip that opens the audition wizard
// instead. Voices at or below this threshold keep the dropdown since
// it's still scannable at that size.
const SPEAKER_DROPDOWN_MAX = 20;
const speakerChip = $("speaker-chip");

function _updateSpeakerChipLabel() {
  const n = Number(speakerEl.value) || 0;
  speakerChip.textContent = `Speaker ${n} — change…`;
}

function onVoiceChange() {
  stopSpeakerPreview();
  // Keep the hero trigger label in sync with whatever's selected —
  // covers both user picks (the "change" event) and programmatic
  // selection (e.g. preset apply, boot-time auto-select).
  if (typeof _updateVoiceTriggerLabel === "function") {
    _updateVoiceTriggerLabel();
  }
  const voiceId = voiceEl.value;
  const n = _voiceSpeakerCounts.get(voiceId) || 1;
  if (n <= 1) {
    speakerRow.hidden = true;
    speakerEl.innerHTML = "";
    speakerChip.hidden = true;
    return;
  }

  // The <select> still backs the chosen speaker even in chip mode —
  // segments / preview / preset code all read speakerEl.value. So we
  // always populate it; the chip just hides the visual element.
  speakerEl.innerHTML = "";
  for (let i = 0; i < n; i++) {
    const opt = document.createElement("option");
    opt.value = String(i);
    opt.textContent = `Speaker ${i}`;
    speakerEl.appendChild(opt);
  }
  speakerEl.value = String(Math.min(rememberedSpeaker(voiceId), n - 1));

  // High-count voices: hide the dropdown, surface the chip + audition
  // entry point. Low-count voices: regular dropdown (audition button
  // still available for power users who want to star a small roster).
  const useChip = n > SPEAKER_DROPDOWN_MAX;
  speakerEl.hidden = useChip;
  speakerChip.hidden = !useChip;
  if (useChip) _updateSpeakerChipLabel();

  speakerRow.hidden = false;

  // v170: inline tip for high-count voices, replacing the v168
  // _fireChipHint approach that wrote to the global status bar —
  // which is occluded by this very dialog, so users never saw it
  // (and the localStorage flag got "consumed" sight-unseen). The
  // banner is dismissible (×) and auto-hides once the user has
  // actually opened the Audition wizard; both states persist in
  // localStorage so a returning user isn't nagged.
  _updateSpeakerAuditionTip(useChip ? n : 0);
}

// v170: inline tip pointing at the Audition link. The voice dialog
// is fullscreen on phones — a setStatus-based hint is invisible
// behind it. The banner shows when a high-count voice loads AND the
// user has neither dismissed it nor opened Audition yet.
const SPEAKER_AUDITION_TIP_DISMISSED_KEY = "narrative.speakerAuditionTipDismissed";
const SPEAKER_AUDITION_TIP_USED_KEY = "narrative.speakerAuditionTipUsed";
function _updateSpeakerAuditionTip(speakerCount) {
  const tip = document.getElementById("speaker-audition-tip");
  if (!tip) return;
  let dismissed = false, used = false;
  try {
    dismissed = localStorage.getItem(SPEAKER_AUDITION_TIP_DISMISSED_KEY) === "1";
    used = localStorage.getItem(SPEAKER_AUDITION_TIP_USED_KEY) === "1";
  } catch {}
  if (!speakerCount || dismissed || used) {
    tip.hidden = true;
    return;
  }
  const countEl = document.getElementById("speaker-audition-tip-count");
  if (countEl) countEl.textContent = String(speakerCount);
  tip.hidden = false;
}
const _speakerAuditionTipDismissBtn = document.getElementById(
  "speaker-audition-tip-dismiss"
);
if (_speakerAuditionTipDismissBtn) {
  _speakerAuditionTipDismissBtn.addEventListener("click", () => {
    try { localStorage.setItem(SPEAKER_AUDITION_TIP_DISMISSED_KEY, "1"); } catch {}
    const tip = document.getElementById("speaker-audition-tip");
    if (tip) tip.hidden = true;
  });
}

voiceEl.addEventListener("change", onVoiceChange);
voiceEl.addEventListener("change", _updateRenarrateBanner);
// v225.tn85 (#567): any voice-card setting that's baked into audio at
// synth time should also trip the re-narrate banner when it drifts
// from the loaded clip's recorded settings. Plus update the preview
// button's hint so the user sees current speed/volume reflected.
rateEl.addEventListener("input", () => {
  _updateVoicePreviewNowHint();
  _updateRenarrateBanner();
});
volumeEl.addEventListener("input", () => {
  _updateVoicePreviewNowHint();
  _updateRenarrateBanner();
});
speakerEl.addEventListener("change", () => {
  _updateVoicePreviewNowHint();
  _updateRenarrateBanner();
});
speakerEl.addEventListener("change", () => {
  stopSpeakerPreview();
  rememberSpeaker(voiceEl.value, Number(speakerEl.value));
});

// ---- Re-narrate banner --------------------------------------------------
// Voice is baked into the audio at synthesis time — there's no live voice
// switch. When the user picks a different voice while a clip is loaded,
// surface a banner offering to re-synthesize the loaded clip in the new
// voice. Dismiss keeps the picker change as the default for next Generate;
// the previous voice on the clip stays put until the user explicitly
// re-narrates.
const renarrateBanner = $("renarrate-banner");
const renarrateClipTitle = $("renarrate-clip-title");
const renarrateVoiceName = $("renarrate-voice-name");
const renarrateConfirm = $("renarrate-confirm");
const renarrateDismiss = $("renarrate-dismiss");
// User-dismissed banners shouldn't flash back if the user toggles voices
// again on the same clip — track the last clip we dismissed so we don't
// nag. Reset on Clear / loadClip.
let _renarrateDismissedClipId = null;

async function _updateRenarrateBanner() {
  // Hide the banner when:
  //   - No clip loaded (voice change is just setting defaults)
  //   - Synthesis in flight (regen is already happening or about to)
  //   - Voice picker matches the loaded clip's voice (nothing to do)
  //   - The user already dismissed for this clip
  if (
    !_currentClipId ||
    _synthController ||
    _renarrateDismissedClipId === _currentClipId
  ) {
    renarrateBanner.hidden = true;
    return;
  }
  const pickerVoice = voiceEl.value;
  // v225.tn85 (#567): banner now fires on ANY voice-card setting
  // drift, not just voice. Compares voice / speaker / rate / volume
  // against the snapshot taken at loadClip. If the loaded clip has
  // no baked-in rate/volume (legacy / never set), treat it as
  // matching the picker so we don't spam first-time loaders.
  const pickerSpeaker = Number(speakerEl.value || 0);
  const pickerRate = Number(rateEl.value);
  const pickerVolume = Number(volumeEl.value) / 100;
  const voiceDiffers = pickerVoice && pickerVoice !== _currentPlayingVoiceId;
  const speakerDiffers =
    _currentPlayingSpeakerId != null &&
    pickerSpeaker !== _currentPlayingSpeakerId;
  const rateDiffers =
    _currentPlayingRate != null && pickerRate !== _currentPlayingRate;
  const volumeDiffers =
    _currentPlayingVolume != null &&
    Math.abs(pickerVolume - _currentPlayingVolume) > 0.005;
  if (!voiceDiffers && !speakerDiffers && !rateDiffers && !volumeDiffers) {
    renarrateBanner.hidden = true;
    return;
  }
  // Look up the title for the labelled prompt. Falls back gracefully
  // if the clip isn't reachable for some reason.
  try {
    const clip = await getClip(_currentClipId);
    renarrateClipTitle.textContent = clip?.title || "this clip";
  } catch {
    renarrateClipTitle.textContent = "this clip";
  }
  // Compose what changed into the voice-name slot. Voice change reads
  // as the voice name; pure setting changes read as "new speed /
  // volume / speaker." Multiple changes get combined.
  const parts = [];
  if (voiceDiffers) {
    const voiceName =
      voiceEl.selectedOptions[0]?.textContent || pickerVoice;
    parts.push(_displayVoiceName(voiceName) || voiceName);
  }
  if (speakerDiffers) parts.push(`Speaker ${pickerSpeaker}`);
  if (rateDiffers) parts.push(`Speed ${pickerRate}`);
  if (volumeDiffers) parts.push(`Volume ${Math.round(pickerVolume * 100)}%`);
  renarrateVoiceName.textContent = parts.join(" · ");
  renarrateBanner.hidden = false;
}

renarrateDismiss.addEventListener("click", () => {
  _renarrateDismissedClipId = _currentClipId;
  renarrateBanner.hidden = true;
});

renarrateConfirm.addEventListener("click", () => {
  if (!_currentClipId) return;
  // Capture the user's position BEFORE starting the regen — the new
  // audio will seek here once the swap completes.
  _regenResumeAtSec = virtualTime();
  // Suppress streaming-sentence playback so the user doesn't hear
  // the new voice rewinding to sentence 0 while we re-synthesize.
  // Status line still shows synth progress.
  _regenSuppressStreaming = true;
  // Pause the old combined audio now so it doesn't keep speaking
  // Amy while the reading view rebuilds for Sarah.
  if (!playerEl.paused) _pauseAsUser();
  // Use the existing in-place regen path. generate() already pulls
  // voice + speaker + rate + volume from the current picker state, so
  // we just flag the existing clip id as the regen target.
  _regenTargetClipId = _currentClipId;
  renarrateBanner.hidden = true;
  _renarrateDismissedClipId = null;
  generate();
});

// v225.tn85 (#567): Voice card "Preview voice + settings" button.
// Unlike speakerPreviewBtn (which uses a canned WAV via
// /api/voices/sample), this button routes through /api/synthesize
// so it honors the live rate + volume sliders. Optional custom
// text via the voice-preview-now-text input.
const voicePreviewNowBtn = $("voice-preview-now");
const voicePreviewNowRate = $("voice-preview-now-rate");
const voicePreviewNowVol = $("voice-preview-now-vol");
const voicePreviewNowText = $("voice-preview-now-text");
const voicePreviewNowTextToggle = $("voice-preview-now-text-toggle");
let _voicePreviewNowActive = false;
let _voicePreviewNowBlobUrl = null;
const VOICE_PREVIEW_NOW_CANNED =
  "The quick brown fox jumps over the lazy dog, then turns to listen to its own voice.";

function _updateVoicePreviewNowHint() {
  if (voicePreviewNowRate) voicePreviewNowRate.textContent = String(rateEl.value);
  if (voicePreviewNowVol) voicePreviewNowVol.textContent = `${volumeEl.value}%`;
  // Pulse the button when settings change mid-play so it reads as
  // "stale — tap to re-play with new settings."
  if (_voicePreviewNowActive && voicePreviewNowBtn) {
    voicePreviewNowBtn.classList.add("stale");
  }
}

function _stopVoicePreviewNow() {
  if (!_voicePreviewNowActive) return;
  const audio = _ensurePreviewAudio && _ensurePreviewAudio();
  if (audio) {
    audio.pause();
    audio.removeAttribute("src");
    audio.load();
  }
  if (_voicePreviewNowBlobUrl) {
    URL.revokeObjectURL(_voicePreviewNowBlobUrl);
    _voicePreviewNowBlobUrl = null;
  }
  voicePreviewNowBtn.classList.remove("playing", "loading", "stale");
  voicePreviewNowBtn.textContent = "▶ Preview voice + settings";
  voicePreviewNowBtn.disabled = false;
  _voicePreviewNowActive = false;
}

if (voicePreviewNowBtn) {
  voicePreviewNowBtn.addEventListener("click", async () => {
    if (_voicePreviewNowActive) {
      _stopVoicePreviewNow();
      return;
    }
    // Stop any other preview in flight.
    if (typeof stopSpeakerPreview === "function") stopSpeakerPreview();
    if (typeof stopPreview === "function") stopPreview();
    const rawVoice = voiceEl.value || "";
    if (!rawVoice) {
      setStatus("Pick a voice first.", true);
      return;
    }
    const voiceIdForSynth = rawVoice.startsWith("piper:")
      ? rawVoice
      : `piper:${rawVoice}`;
    const speakerNum = Number(speakerEl.value || 0);
    const rate = Number(rateEl.value);
    const volume = Number(volumeEl.value) / 100;
    const userText = (voicePreviewNowText.value || "").trim();
    const sampleText = userText || VOICE_PREVIEW_NOW_CANNED;
    voicePreviewNowBtn.classList.add("loading");
    voicePreviewNowBtn.classList.remove("stale");
    voicePreviewNowBtn.textContent = "Synthesizing…";
    voicePreviewNowBtn.disabled = true;
    _voicePreviewNowActive = true;
    try {
      const res = await fetch("/api/synthesize", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          text: sampleText.slice(0, 300),
          voice_id: voiceIdForSynth,
          rate,
          volume,
          speaker_id: Number.isFinite(speakerNum) ? speakerNum : null,
        }),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const blob = await res.blob();
      if (_voicePreviewNowBlobUrl) URL.revokeObjectURL(_voicePreviewNowBlobUrl);
      _voicePreviewNowBlobUrl = URL.createObjectURL(blob);
      const audio = _ensurePreviewAudio();
      audio.src = _voicePreviewNowBlobUrl;
      const onEnded = () => {
        audio.removeEventListener("ended", onEnded);
        _stopVoicePreviewNow();
      };
      audio.addEventListener("ended", onEnded);
      await audio.play();
      voicePreviewNowBtn.classList.remove("loading");
      voicePreviewNowBtn.classList.add("playing");
      voicePreviewNowBtn.textContent = "■ Stop preview";
      voicePreviewNowBtn.disabled = false;
    } catch (err) {
      console.warn("voice preview now failed:", err);
      _stopVoicePreviewNow();
      setStatus(
        "Preview failed — voice may not be installed yet.",
        true,
      );
    }
  });
}

if (voicePreviewNowTextToggle) {
  voicePreviewNowTextToggle.addEventListener("click", () => {
    if (voicePreviewNowText.hidden) {
      voicePreviewNowText.hidden = false;
      voicePreviewNowTextToggle.textContent = "Use canned sample";
      voicePreviewNowText.focus();
    } else {
      voicePreviewNowText.hidden = true;
      voicePreviewNowTextToggle.textContent = "Use your own text";
    }
  });
}

// v225.tn85 (#567): Apply-to-library picker. Three CTAs at the top
// (just current clip / all using this voice / pick clips...) plus a
// multi-select drawer. Routes through the existing silent bg-queue
// path (_libraryRenarrate) so cards visibly pulse 🔄 while
// re-narrating without auto-playing.
const voiceApplySection = $("voice-apply-section");
const voiceApplyBtn = $("voice-apply-btn");
const voiceApplySummary = $("voice-apply-summary");
const voiceApplyPicker = $("voice-apply-picker");
const voiceApplyPickerClose = $("voice-apply-picker-close");
const voiceApplyJustCurrent = $("voice-apply-just-current");
const voiceApplyAllVoice = $("voice-apply-all-voice");
const voiceApplyPick = $("voice-apply-pick");
const voiceApplyMultipick = $("voice-apply-multipick");
const voiceApplyMultipickList = $("voice-apply-multipick-list");
const voiceApplyMultipickCount = $("voice-apply-multipick-count");
const voiceApplyMultipickBack = $("voice-apply-multipick-back");
const voiceApplyMultipickAll = $("voice-apply-multipick-all");
const voiceApplyMultipickConfirm = $("voice-apply-multipick-confirm");
const _voiceApplySelectedIds = new Set();

async function _updateVoiceApplySummary() {
  if (!voiceApplySection || !voiceApplySummary) return;
  try {
    const clips = await listClips();
    if (!clips || !clips.length) {
      voiceApplySection.hidden = true;
      return;
    }
    voiceApplySection.hidden = false;
    const pickerVoice = voiceEl.value || "";
    const matching = clips.filter((c) => c.voiceId === pickerVoice).length;
    if (matching > 0) {
      voiceApplySummary.textContent = `${matching} clip${
        matching === 1 ? "" : "s"
      } currently use this voice.`;
    } else {
      voiceApplySummary.textContent = `${clips.length} clip${
        clips.length === 1 ? "" : "s"
      } in library.`;
    }
  } catch {
    voiceApplySection.hidden = true;
  }
}

voiceEl.addEventListener("change", _updateVoiceApplySummary);

async function _openVoiceApplyPicker() {
  if (!voiceApplyPicker) return;
  const pickerVoice = voiceEl.value || "";
  let clips = [];
  try {
    clips = await listClips();
  } catch {
    clips = [];
  }
  const matching = clips.filter((c) => c.voiceId === pickerVoice);
  // CTA 1: just current
  if (_currentClipId) {
    voiceApplyJustCurrent.hidden = false;
    const cur = clips.find((c) => c.id === _currentClipId);
    $("voice-apply-just-current-meta").textContent = cur?.title || "—";
  } else {
    voiceApplyJustCurrent.hidden = true;
  }
  // CTA 2: all using this voice
  if (matching.length > 0) {
    voiceApplyAllVoice.hidden = false;
    $("voice-apply-all-voice-meta").textContent = `${matching.length} clip${
      matching.length === 1 ? "" : "s"
    }`;
  } else {
    voiceApplyAllVoice.hidden = true;
  }
  // Reset multipick
  voiceApplyMultipick.hidden = true;
  $("voice-apply-options").hidden = false;
  _voiceApplySelectedIds.clear();
  _renderVoiceApplyMultipickList(clips, pickerVoice);
  _updateVoiceApplyMultipickFoot();
  try {
    voiceApplyPicker.showModal();
  } catch {
    voiceApplyPicker.show();
  }
}

function _renderVoiceApplyMultipickList(clips, pickerVoice) {
  if (!voiceApplyMultipickList) return;
  // Sort: clips using the current voice first (most-likely targets),
  // then everything else, both sub-sorted by recency.
  const sorted = [...clips].sort((a, b) => {
    const aMatch = a.voiceId === pickerVoice ? 0 : 1;
    const bMatch = b.voiceId === pickerVoice ? 0 : 1;
    if (aMatch !== bMatch) return aMatch - bMatch;
    return (b.updatedAt || 0) - (a.updatedAt || 0);
  });
  voiceApplyMultipickList.innerHTML = "";
  for (const clip of sorted) {
    const row = document.createElement("label");
    row.className = "voice-apply-multipick-row";
    row.dataset.clipId = clip.id;
    const cb = document.createElement("input");
    cb.type = "checkbox";
    cb.value = clip.id;
    cb.addEventListener("change", () => {
      if (cb.checked) _voiceApplySelectedIds.add(clip.id);
      else _voiceApplySelectedIds.delete(clip.id);
      _updateVoiceApplyMultipickFoot();
    });
    const meta = document.createElement("span");
    meta.className = "voice-apply-multipick-meta";
    const matchTag = clip.voiceId === pickerVoice ? " · same voice" : "";
    const strong = document.createElement("strong");
    strong.textContent = clip.title || "Untitled";
    const tag = document.createElement("span");
    tag.className = "muted";
    tag.textContent = matchTag;
    meta.appendChild(strong);
    meta.appendChild(tag);
    row.appendChild(cb);
    row.appendChild(meta);
    voiceApplyMultipickList.appendChild(row);
  }
}

function _updateVoiceApplyMultipickFoot() {
  const n = _voiceApplySelectedIds.size;
  if (voiceApplyMultipickCount) {
    voiceApplyMultipickCount.textContent = `${n} selected`;
  }
  if (voiceApplyMultipickConfirm) {
    voiceApplyMultipickConfirm.disabled = n === 0;
    voiceApplyMultipickConfirm.textContent =
      n === 0
        ? "Re-narrate selected"
        : `Re-narrate ${n} clip${n === 1 ? "" : "s"}`;
  }
}

function _closeVoiceApplyPicker() {
  if (!voiceApplyPicker) return;
  try {
    voiceApplyPicker.close();
  } catch {
    voiceApplyPicker.hidden = true;
  }
}

async function _queueClipsForRenarrate(clipIds, label) {
  let queued = 0;
  for (const id of clipIds) {
    try {
      // _libraryRenarrate runs through the silent bg-queue (v220az).
      // We await sequentially so the queue isn't flooded, but the
      // function itself returns quickly — the synth happens in BG.
      //
      // v4.58 (#846): explicit usePickerVoice=true. The voice-apply
      // picker's whole purpose is "apply the current voice picker
      // selection to these clips" — that's the only path where we
      // WANT the new chip default ("preserve clip voice") overridden.
      await _libraryRenarrate(id, { usePickerVoice: true });
      queued++;
    } catch (err) {
      console.warn("voice-apply: queue failed for", id, err);
    }
  }
  if (queued > 0) {
    setStatus(
      `Queued ${queued} clip${queued === 1 ? "" : "s"} for re-narrate (${label}).`,
    );
  } else {
    setStatus("Couldn't queue any clips — check console.", true);
  }
  _closeVoiceApplyPicker();
}

if (voiceApplyBtn) {
  voiceApplyBtn.addEventListener("click", _openVoiceApplyPicker);
}
if (voiceApplyPickerClose) {
  voiceApplyPickerClose.addEventListener("click", _closeVoiceApplyPicker);
}
if (voiceApplyJustCurrent) {
  voiceApplyJustCurrent.addEventListener("click", () => {
    if (!_currentClipId) return;
    _queueClipsForRenarrate([_currentClipId], "current clip");
  });
}
if (voiceApplyAllVoice) {
  voiceApplyAllVoice.addEventListener("click", async () => {
    const pickerVoice = voiceEl.value || "";
    try {
      const clips = await listClips();
      const ids = clips
        .filter((c) => c.voiceId === pickerVoice)
        .map((c) => c.id);
      _queueClipsForRenarrate(ids, "same voice");
    } catch (err) {
      console.warn("voice-apply all-voice failed:", err);
    }
  });
}
if (voiceApplyPick) {
  voiceApplyPick.addEventListener("click", () => {
    $("voice-apply-options").hidden = true;
    voiceApplyMultipick.hidden = false;
  });
}
if (voiceApplyMultipickBack) {
  voiceApplyMultipickBack.addEventListener("click", () => {
    voiceApplyMultipick.hidden = true;
    $("voice-apply-options").hidden = false;
  });
}
if (voiceApplyMultipickAll) {
  voiceApplyMultipickAll.addEventListener("click", () => {
    const rows = voiceApplyMultipickList.querySelectorAll(
      "input[type='checkbox']",
    );
    const anyUnchecked = Array.from(rows).some((cb) => !cb.checked);
    for (const cb of rows) {
      cb.checked = anyUnchecked;
      if (anyUnchecked) _voiceApplySelectedIds.add(cb.value);
      else _voiceApplySelectedIds.delete(cb.value);
    }
    _updateVoiceApplyMultipickFoot();
  });
}
if (voiceApplyMultipickConfirm) {
  voiceApplyMultipickConfirm.addEventListener("click", () => {
    const ids = Array.from(_voiceApplySelectedIds);
    if (!ids.length) return;
    _queueClipsForRenarrate(ids, `${ids.length} selected`);
  });
}
// Refresh the summary line whenever the voice picker re-renders or
// the library changes substantially. Cheap call, but throttle via the
// existing voiceEl change handler — already attached above.
_updateVoiceApplySummary();

// Reuse the voice-browser preview's shared Audio element for the inline
// speaker preview. State machine mirrors togglePreview() in the catalog.
let _speakerPreviewActive = false;

function stopSpeakerPreview() {
  if (!_speakerPreviewActive) return;
  if (_previewAudio) {
    _previewAudio.pause();
    _previewAudio.removeAttribute("src");
    _previewAudio.load();
  }
  speakerPreviewBtn.classList.remove("playing", "loading");
  speakerPreviewBtn.textContent = "▶";
  speakerPreviewBtn.disabled = false;
  speakerPreviewBtn.title = "Preview this speaker";
  _speakerPreviewActive = false;
}

speakerPreviewBtn.addEventListener("click", async () => {
  if (_speakerPreviewActive) {
    stopSpeakerPreview();
    return;
  }
  // Also stop any catalog-row preview that might be playing.
  if (typeof stopPreview === "function") stopPreview();

  const voiceId = (voiceEl.value || "").replace(/^piper:/, "");
  const speakerId = Number(speakerEl.value || 0);
  if (!voiceId) return;

  const audio = _ensurePreviewAudio();
  // When the shared Audio's ended event fires we won't know who owns it;
  // attach a one-shot reset so the button flips back correctly.
  const onEnded = () => {
    audio.removeEventListener("ended", onEnded);
    stopSpeakerPreview();
  };
  audio.addEventListener("ended", onEnded);

  speakerPreviewBtn.classList.add("loading");
  speakerPreviewBtn.textContent = "…";
  _speakerPreviewActive = true;
  // v225v4.27 (#704): prefix with API_ORIGIN so the <audio> resolves
  // to the Fly server when running in the Tauri shell (where /api/* is
  // cross-origin). Empty prefix in the PWA → unchanged.
  audio.src = `${API_ORIGIN}/api/voices/sample/${encodeURIComponent(voiceId)}?speaker=${speakerId}`;
  try {
    await audio.play();
    speakerPreviewBtn.classList.remove("loading");
    speakerPreviewBtn.classList.add("playing");
    speakerPreviewBtn.textContent = "■";
  } catch (err) {
    audio.removeEventListener("ended", onEnded);
    speakerPreviewBtn.classList.remove("playing", "loading");
    speakerPreviewBtn.textContent = "—";
    speakerPreviewBtn.title = "No preview available for this speaker";
    speakerPreviewBtn.disabled = true;
    _speakerPreviewActive = false;
    console.info("speaker preview unavailable:", voiceId, speakerId, err.message || err);
  }
});

// ---- Speaker audition wizard --------------------------------------------
// Browsing 904 anonymous LibriTTS speaker IDs via a single dropdown is
// hopeless. This wizard surfaces 6 at a time as rows with ▶ / ★ / Use
// controls, with star persistence per-voice so a returning user can
// jump straight to their shortlist via the "★ Starred only" filter.
const speakerWizard = $("speaker-wizard");
const speakerWizardClose = $("speaker-wizard-close");
const speakerWizardSubtitle = $("speaker-wizard-subtitle");
const speakerWizardStarredBtn = $("speaker-wizard-starred");
const speakerWizardList = $("speaker-wizard-list");
const speakerWizardPrev = $("speaker-wizard-prev");
const speakerWizardNext = $("speaker-wizard-next");
const speakerAuditionBtn = $("speaker-audition-btn");

const SPEAKER_FAVS_KEY = "narrative.speakerFavorites";
const SPEAKER_WIZARD_PAGE_SIZE = 6;

function _loadAllSpeakerFavs() {
  try {
    const raw = localStorage.getItem(SPEAKER_FAVS_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch {
    return {};
  }
}

function _saveAllSpeakerFavs(map) {
  try {
    localStorage.setItem(SPEAKER_FAVS_KEY, JSON.stringify(map));
  } catch {}
}

function getSpeakerFavs(voiceId) {
  const all = _loadAllSpeakerFavs();
  const list = all[voiceId];
  return Array.isArray(list) ? list.filter((n) => Number.isFinite(n)) : [];
}

function isStarredSpeaker(voiceId, speakerId) {
  return getSpeakerFavs(voiceId).includes(speakerId);
}

function toggleSpeakerFav(voiceId, speakerId) {
  const all = _loadAllSpeakerFavs();
  const list = Array.isArray(all[voiceId]) ? [...all[voiceId]] : [];
  const idx = list.indexOf(speakerId);
  if (idx >= 0) list.splice(idx, 1);
  else list.unshift(speakerId); // newest at top
  all[voiceId] = list;
  _saveAllSpeakerFavs(all);
  return idx < 0;
}

let _wizardPage = 0;
let _wizardStarredOnly = false;
let _wizardActiveBtn = null;
// Cache the voice's speaker count + the voice id at open time so paging
// doesn't break if the user changes voice in the background.
let _wizardVoiceId = null;
let _wizardSpeakerCount = 0;

function _wizardCurrentIds() {
  if (_wizardStarredOnly) {
    return getSpeakerFavs(_wizardVoiceId).slice().sort((a, b) => a - b);
  }
  // Full range 0..N-1.
  return Array.from({ length: _wizardSpeakerCount }, (_, i) => i);
}

function _wizardPageIds() {
  const all = _wizardCurrentIds();
  const start = _wizardPage * SPEAKER_WIZARD_PAGE_SIZE;
  return { all, page: all.slice(start, start + SPEAKER_WIZARD_PAGE_SIZE), start };
}

function _stopWizardPreview() {
  if (_wizardActiveBtn) {
    _wizardActiveBtn.classList.remove("playing", "loading");
    _wizardActiveBtn.textContent = "▶";
    _wizardActiveBtn = null;
  }
  if (_previewAudio) {
    _previewAudio.pause();
    _previewAudio.removeAttribute("src");
    _previewAudio.load();
  }
}

async function _wizardPlay(speakerId, btn) {
  if (_wizardActiveBtn === btn) {
    _stopWizardPreview();
    return;
  }
  _stopWizardPreview();
  const audio = _ensurePreviewAudio();
  const voiceId = (_wizardVoiceId || "").replace(/^piper:/, "");
  btn.classList.add("loading");
  btn.textContent = "…";
  _wizardActiveBtn = btn;
  const onEnded = () => {
    audio.removeEventListener("ended", onEnded);
    if (_wizardActiveBtn === btn) _stopWizardPreview();
  };
  audio.addEventListener("ended", onEnded);
  // v225v4.27 (#704): prefix with API_ORIGIN so the <audio> resolves
  // to the Fly server when running in the Tauri shell (where /api/* is
  // cross-origin). Empty prefix in the PWA → unchanged.
  audio.src = `${API_ORIGIN}/api/voices/sample/${encodeURIComponent(voiceId)}?speaker=${speakerId}`;
  try {
    await audio.play();
    btn.classList.remove("loading");
    btn.classList.add("playing");
    btn.textContent = "■";
  } catch (err) {
    audio.removeEventListener("ended", onEnded);
    btn.classList.remove("loading", "playing");
    btn.textContent = "—";
    btn.disabled = true;
    if (_wizardActiveBtn === btn) _wizardActiveBtn = null;
    console.info("wizard preview unavailable:", voiceId, speakerId, err);
  }
}

function _updateWizardStarredChip() {
  const favCount = getSpeakerFavs(_wizardVoiceId).length;
  speakerWizardStarredBtn.textContent = _wizardStarredOnly
    ? `Show all (${favCount})`
    : `★ Starred only (${favCount})`;
  speakerWizardStarredBtn.classList.toggle("active", _wizardStarredOnly);
  speakerWizardStarredBtn.setAttribute(
    "aria-pressed",
    String(_wizardStarredOnly)
  );
}

function renderSpeakerWizard() {
  _stopWizardPreview();
  _updateWizardStarredChip();

  const { all, page, start } = _wizardPageIds();
  const total = all.length;
  if (total === 0) {
    speakerWizardSubtitle.textContent = _wizardStarredOnly
      ? "No starred speakers yet — turn off the filter and ★ some."
      : "No speakers available.";
    speakerWizardList.innerHTML = "";
    speakerWizardPrev.disabled = true;
    speakerWizardNext.disabled = true;
    return;
  }

  const end = Math.min(start + page.length, total);
  speakerWizardSubtitle.textContent = `Speakers ${start + 1}–${end} of ${total}`;

  speakerWizardList.innerHTML = "";
  for (const speakerId of page) {
    const row = document.createElement("div");
    row.className = "speaker-wizard-row";

    const num = document.createElement("span");
    num.className = "speaker-wizard-num";
    num.textContent = `Speaker ${speakerId}`;
    row.appendChild(num);

    const playBtn = document.createElement("button");
    playBtn.type = "button";
    playBtn.className = "speaker-wizard-play";
    playBtn.textContent = "▶";
    playBtn.setAttribute("aria-label", `Preview speaker ${speakerId}`);
    playBtn.addEventListener("click", () => _wizardPlay(speakerId, playBtn));
    row.appendChild(playBtn);

    const starBtn = document.createElement("button");
    starBtn.type = "button";
    const starred = isStarredSpeaker(_wizardVoiceId, speakerId);
    starBtn.className = "speaker-wizard-star" + (starred ? " starred" : "");
    starBtn.textContent = starred ? "★" : "☆";
    starBtn.setAttribute(
      "aria-label",
      starred ? `Unstar speaker ${speakerId}` : `Star speaker ${speakerId}`
    );
    starBtn.addEventListener("click", () => {
      toggleSpeakerFav(_wizardVoiceId, speakerId);
      renderSpeakerWizard();
    });
    row.appendChild(starBtn);

    const useBtn = document.createElement("button");
    useBtn.type = "button";
    useBtn.className = "speaker-wizard-use";
    useBtn.textContent = "Use";
    useBtn.setAttribute("aria-label", `Use speaker ${speakerId}`);
    useBtn.addEventListener("click", () => {
      speakerEl.value = String(speakerId);
      // Fire the native change event so rememberSpeaker + downstream
      // listeners run as if the user picked from the dropdown.
      speakerEl.dispatchEvent(new Event("change"));
      _stopWizardPreview();
      speakerWizard.close();
    });
    row.appendChild(useBtn);

    speakerWizardList.appendChild(row);
  }

  speakerWizardPrev.disabled = _wizardPage === 0;
  speakerWizardNext.disabled = end >= total;
}

function openSpeakerWizard() {
  _wizardVoiceId = voiceEl.value || null;
  _wizardSpeakerCount = _voiceSpeakerCounts.get(_wizardVoiceId) || 0;
  _wizardPage = 0;
  _wizardStarredOnly = false;
  renderSpeakerWizard();
  speakerWizard.showModal();
}

speakerAuditionBtn.addEventListener("click", () => {
  // v170: opening the wizard from the link means the user found
  // the affordance — mark the tip "used" so it never shows again.
  try { localStorage.setItem(SPEAKER_AUDITION_TIP_USED_KEY, "1"); } catch {}
  const tip = document.getElementById("speaker-audition-tip");
  if (tip) tip.hidden = true;
  openSpeakerWizard();
});

// v152: speaker explainer link. Toggles an inline popover (v153)
// so a repeat click visibly closes it again — the original v152
// setStatus fired the same message both times, which the user
// couldn't tell was a real second-click reaction.
const speakerHelpBtn = $("speaker-help-btn");
const speakerHelpPopover = $("speaker-help-popover");
if (speakerHelpBtn && speakerHelpPopover) {
  speakerHelpBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    const isOpen = !speakerHelpPopover.hidden;
    speakerHelpPopover.hidden = isOpen;
    speakerHelpBtn.setAttribute("aria-expanded", isOpen ? "false" : "true");
  });
  // Tap outside the popover (anywhere in the voice dialog body)
  // closes it. Click on the popover itself doesn't bubble close.
  speakerHelpPopover.addEventListener("click", (e) => e.stopPropagation());
  document.addEventListener("click", (e) => {
    if (speakerHelpPopover.hidden) return;
    if (e.target === speakerHelpBtn) return;
    if (speakerHelpPopover.contains(e.target)) return;
    speakerHelpPopover.hidden = true;
    speakerHelpBtn.setAttribute("aria-expanded", "false");
  });
}
// Chip click is the primary path for high-count voices — the native
// dropdown is hidden in that mode, so the chip carries both the current-
// value display AND the "change" affordance in a single tap target.
speakerChip.addEventListener("click", () => {
  // v170: chip also routes through the wizard — same "found it"
  // signal as the Audition link.
  try { localStorage.setItem(SPEAKER_AUDITION_TIP_USED_KEY, "1"); } catch {}
  const tip = document.getElementById("speaker-audition-tip");
  if (tip) tip.hidden = true;
  openSpeakerWizard();
});
speakerWizardClose.addEventListener("click", () => speakerWizard.close());
speakerWizard.addEventListener("close", _stopWizardPreview);

// Keep the chip's label in sync when the underlying <select> changes —
// covers wizard "Use" (which dispatches change), preset application,
// and any other path that mutates speakerEl.value.
speakerEl.addEventListener("change", () => {
  if (!speakerChip.hidden) _updateSpeakerChipLabel();
});

speakerWizardStarredBtn.addEventListener("click", () => {
  _wizardStarredOnly = !_wizardStarredOnly;
  _wizardPage = 0;
  renderSpeakerWizard();
});

speakerWizardPrev.addEventListener("click", () => {
  if (_wizardPage > 0) {
    _wizardPage -= 1;
    renderSpeakerWizard();
  }
});

speakerWizardNext.addEventListener("click", () => {
  const { all } = _wizardPageIds();
  if ((_wizardPage + 1) * SPEAKER_WIZARD_PAGE_SIZE < all.length) {
    _wizardPage += 1;
    renderSpeakerWizard();
  }
});

// ---- Synthesis presets ---------------------------------------------------
// Save named voice + speaker + rate + volume combos as chips you can tap to
// re-apply. Useful when you've found a LibriTTS speaker + speed you like
// and want to come back to it without rebuilding the config by hand.
const PRESETS_STORAGE_KEY = "narrative.presets";

function _loadPresets() {
  try {
    const raw = localStorage.getItem(PRESETS_STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function _savePresets(list) {
  try {
    localStorage.setItem(PRESETS_STORAGE_KEY, JSON.stringify(list));
  } catch (e) {
    console.warn("preset save failed:", e);
  }
}

function _currentPresetSnapshot() {
  return {
    voiceId: voiceEl.value || null,
    speakerId: speakerRow.hidden ? null : Number(speakerEl.value || 0),
    rate: Number(rateEl.value),
    volume: Number(volumeEl.value) / 100,
  };
}

function _suggestPresetName() {
  // v220bd: route through the shared display helper instead of an
  // ad-hoc split — handles both "Alan (en_GB, medium)" and
  // "LibriTTS · high · spkr 7" suffix styles.
  const voiceLabel = _displayVoiceName(
    voiceEl.selectedOptions[0]?.textContent || "Voice"
  );
  const parts = [voiceLabel];
  if (!speakerRow.hidden) parts.push(`spk ${speakerEl.value}`);
  parts.push(`${rateEl.value} wpm`);
  return parts.join(" · ");
}

function applyPreset(preset) {
  // Voice: check it's still in the dropdown (the user might have removed
  // it via the voice browser since the preset was saved).
  if (preset.voiceId) {
    let optionExists = false;
    for (const opt of voiceEl.options) {
      if (opt.value === preset.voiceId) { optionExists = true; break; }
    }
    if (!optionExists) {
      setStatus(
        `Preset "${preset.name}" uses a voice that isn't installed.`,
        true
      );
      return;
    }
    voiceEl.value = preset.voiceId;
    onVoiceChange(); // populates speaker dropdown for the new voice
  }

  // Speaker: only meaningful if the new voice exposes one and the saved
  // index is in range for that voice.
  if (
    typeof preset.speakerId === "number" &&
    !speakerRow.hidden &&
    speakerEl.options.length > preset.speakerId
  ) {
    speakerEl.value = String(preset.speakerId);
  }

  if (typeof preset.rate === "number") {
    const r = Math.min(300, Math.max(80, Math.round(preset.rate)));
    rateEl.value = String(r);
    rateValueEl.textContent = String(r);
  }
  if (typeof preset.volume === "number") {
    const v = Math.min(100, Math.max(0, Math.round(preset.volume * 100)));
    volumeEl.value = String(v);
    volumeValueEl.textContent = `${v}%`;
  }

  setStatus(`Applied preset: ${preset.name}`);
}

function deletePreset(id) {
  const list = _loadPresets().filter((p) => p.id !== id);
  _savePresets(list);
  renderPresets();
  // v225fz8 (#674): push a server-side tombstone so other devices on
  // this tenant_key drop the row on their next pull. Sync gate inside
  // _syncDeletePreset means this is a no-op when the user hasn't
  // opted into sync.
  if (typeof _syncDeletePreset === "function") {
    _syncDeletePreset(id).catch((e) =>
      console.warn("[sync] preset delete failed:", e),
    );
  }
}

function renderPresets() {
  const list = _loadPresets();
  presetsList.innerHTML = "";
  if (list.length === 0) {
    // v166: show a one-line explainer when no presets exist instead
    // of hiding the row entirely — testers had no idea what "Save
    // preset" would produce. Becomes a real chip list once they
    // save one. Hidden on Simple mode (advanced-only) so casual
    // readers never see writing-craft chrome.
    presetsList.hidden = false;
    const empty = document.createElement("p");
    empty.className = "presets-empty advanced-only";
    empty.textContent =
      "💡 Tip — Save preset stores the current voice + speed + volume as a named combo. Useful when juggling two voices for different content (fiction vs. tech docs, narrator vs. character).";
    presetsList.appendChild(empty);
    return;
  }
  presetsList.hidden = false;
  for (const preset of list) {
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = "preset-chip";
    chip.title = (
      `${preset.voiceId || "default voice"}` +
      (preset.speakerId != null ? ` · spk ${preset.speakerId}` : "") +
      ` · ${preset.rate} wpm · ${Math.round(preset.volume * 100)}%`
    );

    const name = document.createElement("span");
    name.className = "preset-chip-name";
    name.textContent = preset.name;

    const del = document.createElement("button");
    del.type = "button";
    del.className = "preset-chip-x";
    del.textContent = "×";
    del.title = "Delete preset";
    del.setAttribute("aria-label", `Delete preset ${preset.name}`);
    del.addEventListener("click", (e) => {
      e.stopPropagation();
      deletePreset(preset.id);
    });

    chip.append(name, del);
    chip.addEventListener("click", () => applyPreset(preset));
    presetsList.appendChild(chip);
  }
}

// ---- Reset Speed / Volume to factory defaults (v129) -------------------
// "Defaults" link in the Voice dialog. Just synth knobs — voice and
// speaker stay as-is so the user doesn't lose their pick when backing
// out of speed/volume experiments. The 'input' dispatch is so the
// existing listener that mirrors slider → label text fires and updates
// the "180" / "100%" badges next to each slider.
voiceDefaultsBtn.addEventListener("click", () => {
  rateEl.value = "180";
  volumeEl.value = "100";
  rateEl.dispatchEvent(new Event("input", { bubbles: true }));
  volumeEl.dispatchEvent(new Event("input", { bubbles: true }));
  setStatus("Reset to defaults: Speed 180 wpm, Volume 100%");
});

presetSaveBtn.addEventListener("click", () => {
  const suggested = _suggestPresetName();
  const name = window.prompt("Name this preset:", suggested);
  if (!name || !name.trim()) return;
  const list = _loadPresets();
  const now = new Date().toISOString();
  const preset = {
    id: Date.now(),
    name: name.trim(),
    ..._currentPresetSnapshot(),
    createdAt: now,
    // v225fz8 (#674): every preset carries an updatedAt for the
    // server-side LWW conflict resolution. Save / rename / re-save
    // bumps this so the freshest write wins across devices.
    updatedAt: now,
  };
  list.unshift(preset);
  _savePresets(list);
  renderPresets();
  // v225fz8 (#674): push this preset to /api/library/presets/{id} so
  // other devices on the same tenant key pick it up on their next pull.
  // Gated on the same sync toggle that gates clip sync — users who
  // haven't opted in stay local-only.
  if (typeof _syncPushPreset === "function") {
    _syncPushPreset(preset).catch((e) =>
      console.warn("[sync] preset push failed:", e),
    );
  }
  setStatus(`Saved preset: ${name.trim()}`);
});

renderPresets();

// v225fz8 (#674): cross-device preset sync. Server endpoints have
// existed since #427 (GET/PUT/DELETE /api/library/presets, tenant_key
// scoped); this block is the client-side wiring that was missing —
// without it, presets only ever lived in localStorage and a user
// switching from desktop to phone got an empty Saved list. Schema
// mirrors the clip-sync pattern (same _syncIsEnabled gate, same
// updatedAt LWW story, same 409 absorb-server-version on conflict).

// Push a single preset to the server. Called by the save handler
// above and by the delete path below (for tombstoning). The preset's
// `id` is a JS timestamp number locally; the server uses TEXT, so we
// stringify in the URL. No-op when sync is disabled.
async function _syncPushPreset(preset) {
  if (!_syncIsEnabled()) return;
  if (!preset || preset.id == null) return;
  const payload = {
    id: String(preset.id),
    name: preset.name || "",
    voiceId: preset.voiceId || null,
    rate: preset.rate != null ? preset.rate : null,
    volume: preset.volume != null ? preset.volume : null,
    speakerId: preset.speakerId != null ? preset.speakerId : null,
    updatedAt: preset.updatedAt || new Date().toISOString(),
    deleted: !!preset.deleted,
  };
  try {
    const res = await fetch(`/api/library/presets/${encodeURIComponent(payload.id)}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    if (res.status === 409) {
      // Server's row is newer. Absorb its version locally so subsequent
      // saves race the right base. Pull-all triggers will catch this
      // too — this is just the fast path.
      try {
        const body = await res.json();
        const serverPreset = body.detail && body.detail.server_preset;
        if (serverPreset) _syncAbsorbServerPreset(serverPreset);
      } catch {}
      setStatus(
        "Preset was updated on another device; using the latest.",
      );
    } else if (!res.ok) {
      console.warn(`[sync] preset push failed: HTTP ${res.status}`);
    }
  } catch (e) {
    console.warn("[sync] preset push network error:", e);
  }
}

// Delete propagates via a server-side tombstone (deleted=1 in the
// presets table). The DELETE endpoint takes the updatedAt as a query
// arg so concurrent edits don't silently lose to a stale delete.
async function _syncDeletePreset(presetId) {
  if (!_syncIsEnabled()) return;
  if (presetId == null) return;
  const updatedAt = new Date().toISOString();
  try {
    const u =
      `/api/library/presets/${encodeURIComponent(String(presetId))}` +
      `?updated_at=${encodeURIComponent(updatedAt)}`;
    await fetch(u, { method: "DELETE" });
  } catch (e) {
    console.warn("[sync] preset delete failed:", e);
  }
}

// Absorb a server-shaped preset into local localStorage. Server uses
// snake_case column names but the FastAPI response model returns
// camelCase per the existing clip pattern; we just spread it into our
// local shape. If a row with the same id exists we update in place,
// otherwise prepend.
function _syncAbsorbServerPreset(srv) {
  if (!srv || srv.id == null) return;
  // localStorage list — coerce types so equality checks work whether
  // the local id is a number (legacy) or a string (post-sync).
  const list = _loadPresets();
  const idx = list.findIndex((p) => String(p.id) === String(srv.id));
  // Server's deleted flag = local removal. Drop the row entirely;
  // the rendered chip list goes away on the next render.
  if (srv.deleted) {
    if (idx >= 0) {
      list.splice(idx, 1);
      _savePresets(list);
      if (typeof renderPresets === "function") renderPresets();
    }
    return;
  }
  const incoming = {
    id: srv.id,
    name: srv.name || "",
    voiceId: srv.voiceId || null,
    rate: srv.rate != null ? srv.rate : null,
    volume: srv.volume != null ? srv.volume : null,
    speakerId: srv.speakerId != null ? srv.speakerId : null,
    createdAt: srv.createdAt || srv.updatedAt || new Date().toISOString(),
    updatedAt: srv.updatedAt || new Date().toISOString(),
  };
  if (idx >= 0) {
    // LWW — keep local if its updatedAt is newer (server might have
    // sent a stale version we already superseded).
    const local = list[idx];
    if (local.updatedAt && local.updatedAt > incoming.updatedAt) return;
    list[idx] = incoming;
  } else {
    list.unshift(incoming);
  }
  _savePresets(list);
  if (typeof renderPresets === "function") renderPresets();
}

// Pull-all on boot + Sync now. Server returns the full preset list for
// the tenant_key (live rows only — tombstones filtered server-side).
// We merge with local by absorbing each, which honors LWW per-row.
async function _syncPullPresets() {
  if (!_syncIsEnabled()) return;
  try {
    const res = await fetch("/api/library/presets");
    if (!res.ok) {
      console.warn(`[sync] preset pull failed: HTTP ${res.status}`);
      return;
    }
    const body = await res.json();
    const incoming = Array.isArray(body) ? body : (body && body.presets) || [];
    if (!incoming.length) return;
    // Server is authoritative for what's live. Drop any local row
    // that DOESN'T appear in the server response — those rows were
    // deleted on another device (and the server's tombstone filter
    // hid them from this response). Without this, deletes wouldn't
    // propagate to this device on pull.
    const liveIds = new Set(incoming.map((p) => String(p.id)));
    let local = _loadPresets();
    const filtered = local.filter((p) => liveIds.has(String(p.id)));
    if (filtered.length !== local.length) _savePresets(filtered);
    // Then absorb each — adds new rows + LWW-updates existing.
    for (const srv of incoming) _syncAbsorbServerPreset(srv);
  } catch (e) {
    console.warn("[sync] preset pull network error:", e);
  }
}

// ---- Character voices (Author mode) -------------------------------------
// Persisted roster of {id, name, voiceId, speakerId}. When Author mode is
// on AND the user has defined at least one character, generate() detects
// attributed dialogue ("...," X said) and routes those sentences through
// the /api/synthesize/segments/stream endpoint with each segment carrying
// its assigned voice. Other sentences fall through to the main voice
// picker (used as "narration").
const CHARACTERS_STORAGE_KEY = "narrative.characters";

function _loadCharacters() {
  try {
    const raw = localStorage.getItem(CHARACTERS_STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function _saveCharacters(list) {
  try {
    localStorage.setItem(CHARACTERS_STORAGE_KEY, JSON.stringify(list));
  } catch (e) {
    console.warn("character save failed:", e);
  }
}

// v220-AA: per-sentence manual voice assignment runtime.
// _currentClipAssignments mirrors the loaded clip's sentenceAssignments
// field — { "5": "Llea", "12": "narrator" } where the key is the
// stringified sentence index (matches sentenceSpans[i] in the reading
// view) and the value is either a character name from the roster or
// the literal "narrator". loadClip hydrates this; the long-press
// handler reads + writes it; the regen path persists it.
let _currentClipAssignments = {};

// v220-AG: dirty-flag for "this clip has voice assignments that
// haven't been re-rendered into the audio yet." Set true whenever
// _persistSentenceAssignments saves; cleared when a regen completes
// and the new MP3 lands. Drives the pending-assignments banner.
let _currentClipAssignmentsDirty = false;

// Apply the visual marker to a reading-view sentence span based on
// whatever's in _currentClipAssignments. Called for every span as the
// reading view is built, and again after each assignment change.
// Idempotent: removes any prior tag/class before adding fresh ones.
function _applySentenceAssignmentMark(span, idx) {
  if (!span) return;
  span.classList.remove("sentence-assigned");
  // v220-AF: tag chip removed. The inline "🎙 Narrator" / "🎭 Llea"
  // chips broke reading flow on every overridden sentence — tester
  // asked to drop them. Visual feedback now relies on:
  //   - the dotted-underline (.sentence-assigned class) for "this
  //     sentence has a manual override"
  //   - the character-color text tint (from _repaintReadingViewAttribution)
  //     for "this is the voice it'll synth as"
  // Both are enough to scan a chapter without the chip noise.
  const oldTag = span.querySelector(".sentence-assign-tag");
  if (oldTag) oldTag.remove();
  const override = _currentClipAssignments[String(idx)];
  if (override == null) return;
  span.classList.add("sentence-assigned");
}

// Persist the current assignments map back to the clip on disk so a
// reload picks it up + a regen sees the same overrides. Saves
// asynchronously; errors are logged but don't block the UI.
async function _persistSentenceAssignments() {
  if (!_currentClipId) return;
  try {
    // v223.tn19 (#488): atomic so concurrent absorb can't lose annotations.
    await _mutateClipAtomic(_currentClipId, (c) => {
      c.sentenceAssignments = { ..._currentClipAssignments };
      // v220-AG: mark the audio as out of date with respect to the
      // current assignments. The banner watches this flag + the
      // regen-save path clears it back to false.
      c.assignmentsDirty = true;
    });
    _currentClipAssignmentsDirty = true;
    _updatePendingAssignmentsBanner();
  } catch (e) {
    console.warn("sentence assignment save failed:", e);
  }
}

// v220-AG: persistent banner above the player that surfaces "this
// clip has un-rendered voice assignments." Tap → kicks off
// _libraryRenarrate so the user doesn't have to scroll up to the
// library to find the 🔄 chip. Disappears when the regen completes.
let _pendingAssignmentsBanner = null;
function _updatePendingAssignmentsBanner() {
  if (!_pendingAssignmentsBanner) {
    _pendingAssignmentsBanner = document.createElement("button");
    _pendingAssignmentsBanner.type = "button";
    _pendingAssignmentsBanner.className = "pending-assignments-banner";
    _pendingAssignmentsBanner.hidden = true;
    _pendingAssignmentsBanner.addEventListener("click", () => {
      if (!_currentClipId) return;
      // Hand off to the silent library re-narrate flow. The chip
      // pulse + "Synthesising… N/M" status line take over; this
      // banner hides as soon as the dirty flag clears on save.
      _libraryRenarrate(_currentClipId);
    });
    // Sit it above the player card. readingView lives below the
    // hero; we slot the banner just before it so it always renders
    // between the controls and the text.
    const anchor = (typeof readingView !== "undefined" && readingView)
      ? readingView
      : document.body;
    anchor.parentNode.insertBefore(_pendingAssignmentsBanner, anchor);
  }
  const show =
    _currentClipId &&
    _currentClipAssignmentsDirty &&
    Object.keys(_currentClipAssignments).length > 0;
  if (!show) {
    _pendingAssignmentsBanner.hidden = true;
    return;
  }
  const n = Object.keys(_currentClipAssignments).length;
  _pendingAssignmentsBanner.innerHTML = `
    <span class="pending-assignments-text">
      <strong>${n}</strong> voice assignment${n === 1 ? "" : "s"} pending — audio still uses the old voices.
    </span>
    <span class="pending-assignments-cta">Re-render now →</span>
  `;
  _pendingAssignmentsBanner.hidden = false;
}

// Open the assignment chooser for sentence `idx`. Builds the dialog
// once and reuses it across taps. Lists every roster character + a
// Narrator (auto-detect) entry that CLEARS the override (lets Tier 3
// take the sentence) + a Narrator (force) entry that pins it to the
// narrator regardless of detection.
let _assignmentDialog = null;
// v220-AC: opens the assignment chooser for either a single sentence
// (number) or a range of sentences (array of indices). When called
// with an array we apply the chosen voice to every index in the array
// in one pass — built for the multi-select bar that pops up after a
// long-press enters select-mode.
function _openSentenceAssignmentDialog(target) {
  const indices = Array.isArray(target)
    ? Array.from(new Set(target.map((n) => Number(n)))).sort((a, b) => a - b)
    : [Number(target)];
  if (indices.length === 0) return;
  if (!_assignmentDialog) {
    _assignmentDialog = document.createElement("dialog");
    _assignmentDialog.className = "sentence-assign-dialog";
    document.body.appendChild(_assignmentDialog);
    // Tap outside content closes (matches the other dialogs in the app).
    _assignmentDialog.addEventListener("click", (e) => {
      if (e.target === _assignmentDialog) _assignmentDialog.close();
    });
  }
  const characters = _loadCharacters().filter(
    (c) => c.name && c.name.trim() && c.voiceId
  );
  // For the "currently selected option" highlight in the menu: if every
  // sentence in the batch has the SAME current override, we can mark
  // that one as active. Mixed selections show no active row.
  const firstIdx = indices[0];
  const firstCurrent = _currentClipAssignments[String(firstIdx)];
  const allSame = indices.every(
    (i) => _currentClipAssignments[String(i)] === firstCurrent
  );
  const current = allSame ? firstCurrent : undefined;
  const headerLabel =
    indices.length === 1
      ? `Assign sentence ${firstIdx + 1} to…`
      : `Assign ${indices.length} sentences to…`;
  const previewSpan = sentenceSpans[firstIdx];
  let previewText = previewSpan ? previewSpan.textContent.trim().slice(0, 120) : "";
  // Strip any leading "🎭 …" tag content from the preview if it leaked
  // in through textContent (the tag chip lives inside the span).
  previewText = previewText.replace(/^🎭\s\S+\s+/, "").replace(/^🎙\s\S+\s+/, "");
  if (indices.length > 1) previewText = `${previewText}${previewText ? "  · " : ""}…+${indices.length - 1} more`;
  _assignmentDialog.innerHTML = `
    <div class="sentence-assign-header">
      <strong>${headerLabel}</strong>
      <button type="button" class="sentence-assign-close" aria-label="Close">×</button>
    </div>
    <p class="sentence-assign-preview">${previewText.replace(/</g, "&lt;")}${previewText.length === 120 ? "…" : ""}</p>
    <ul class="sentence-assign-list"></ul>
  `;
  const list = _assignmentDialog.querySelector(".sentence-assign-list");
  const makeRow = (label, value, color) => {
    const li = document.createElement("li");
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "sentence-assign-row";
    if (
      current !== undefined &&
      ((value === null && current == null) ||
        (value !== null && String(current) === String(value)))
    ) {
      btn.classList.add("active");
    }
    btn.textContent = label;
    if (color) btn.style.borderLeftColor = color;
    btn.addEventListener("click", () => {
      let humanTarget;
      for (const i of indices) {
        const key = String(i);
        if (value === null) {
          delete _currentClipAssignments[key];
        } else {
          _currentClipAssignments[key] = value;
        }
      }
      if (value === null) {
        humanTarget =
          indices.length === 1
            ? `Sentence ${firstIdx + 1}: auto-detect restored.`
            : `${indices.length} sentences restored to auto-detect.`;
      } else {
        const human = value === "narrator" ? "Narrator (forced)" : value;
        humanTarget =
          indices.length === 1
            ? `Sentence ${firstIdx + 1} assigned to ${human}.`
            : `${indices.length} sentences assigned to ${human}.`;
      }
      setStatus(`${humanTarget} Tap 🔄 in library to re-render.`);
      _persistSentenceAssignments();
      for (const i of indices) {
        _applySentenceAssignmentMark(sentenceSpans[i], i);
      }
      _repaintReadingViewAttribution();
      // Clear the pending selection after the batch lands — the
      // user's done with this round; subsequent drags start fresh.
      _clearAssignSelection();
      _assignmentDialog.close();
    });
    li.appendChild(btn);
    list.appendChild(li);
  };
  makeRow("↩ Auto-detect (let Narrative decide)", null, null);
  makeRow("🎙 Narrator (force)", "narrator", null);
  for (const c of characters) {
    makeRow(`🎭 ${c.name}`, c.name, _tagColor(c.name));
  }
  _assignmentDialog.querySelector(".sentence-assign-close").addEventListener(
    "click",
    () => _assignmentDialog.close(),
    { once: true }
  );
  _assignmentDialog.showModal();
}

// v220-AD: drag-to-select for multi-sentence voice assignment.
//
// Design (user-chosen 2026-05-31):
//   - Single tap always seeks the player to that sentence. NEVER selects.
//   - To select, press and drag across multiple sentences. Each sentence
//     the pointer crosses gets added to the batch. Releasing finalizes
//     the selection; the floating bar appears with N selected · Cancel
//     · Assign →.
//   - Subsequent drags are additive — they extend the existing
//     selection without clearing it. Cancel resets.
//   - Tap Assign → the chooser opens; the chosen voice is applied to
//     every selected sentence in one pass.
//   - Mouse drag arms immediately. Touch drag arms after a 200ms hold
//     so casual scroll gestures don't trigger selection — pause briefly,
//     then drag.
let _assignSelectedIndices = new Set();
let _assignSelectBar = null;
let _dragState = null;
const _DRAG_ARM_MS = 200;
const _DRAG_MOVE_THRESHOLD = 10;

function _clearAssignSelection() {
  _assignSelectedIndices.clear();
  _updateAssignSelectVisuals();
  if (_assignSelectBar) _assignSelectBar.hidden = true;
}

function _updateAssignSelectVisuals() {
  for (let i = 0; i < sentenceSpans.length; i++) {
    const span = sentenceSpans[i];
    if (!span) continue;
    if (_assignSelectedIndices.has(i)) {
      span.classList.add("sentence-select-pending");
    } else {
      span.classList.remove("sentence-select-pending");
    }
  }
}

function _renderAssignSelectBar() {
  if (!_assignSelectBar) {
    _assignSelectBar = document.createElement("div");
    _assignSelectBar.className = "assign-select-bar";
    document.body.appendChild(_assignSelectBar);
  }
  const n = _assignSelectedIndices.size;
  _assignSelectBar.innerHTML = `
    <span class="assign-select-count">${n} sentence${n === 1 ? "" : "s"} selected</span>
    <div class="assign-select-actions">
      <button type="button" class="assign-select-cancel">Cancel</button>
      <button type="button" class="assign-select-assign">Assign →</button>
    </div>
  `;
  _assignSelectBar.querySelector(".assign-select-cancel").addEventListener(
    "click",
    () => _clearAssignSelection()
  );
  _assignSelectBar.querySelector(".assign-select-assign").addEventListener(
    "click",
    () => _openSentenceAssignmentDialog(Array.from(_assignSelectedIndices))
  );
  _assignSelectBar.hidden = false;
}

// Global pointer handlers — bound once at module load. Track _dragState
// to know if we're mid-drag. The per-sentence pointerdown handler seeds
// _dragState; the document-level move/up handlers update + finalize.
function _addToDragSelection(idx) {
  if (!Number.isFinite(idx)) return;
  if (_assignSelectedIndices.has(idx)) return;
  _assignSelectedIndices.add(idx);
  const span = sentenceSpans[idx];
  if (span) span.classList.add("sentence-select-pending");
  _renderAssignSelectBar();
}

document.addEventListener("pointermove", (e) => {
  if (!_dragState) return;
  if (e.pointerId !== _dragState.pointerId) return;
  const dx = e.clientX - _dragState.startX;
  const dy = e.clientY - _dragState.startY;
  const dist = Math.abs(dx) + Math.abs(dy);
  // Touch case: if the finger moves significantly BEFORE the 200ms
  // arm timer fires, the user is scrolling — not selecting. Cancel
  // the arm timer and let the browser handle the scroll.
  if (!_dragState.armed) {
    if (dist > _DRAG_MOVE_THRESHOLD) {
      clearTimeout(_dragState.armTimer);
      _dragState = null;
    }
    return;
  }
  // Armed but not yet moved past the threshold: hold off on
  // suppressing scroll or adding sentences. This is what lets a
  // hold-without-drag (or a mouse press-without-drag) still fall
  // through to seek — _dragState.moved stays false and pointerup
  // sees nothing to suppress.
  if (!_dragState.moved) {
    if (dist <= _DRAG_MOVE_THRESHOLD) return;
    _dragState.moved = true;
    // First crossing of the threshold: commit the starting sentence
    // to the selection so the drag has a sensible anchor even if
    // the finger has already left it.
    _addToDragSelection(_dragState.initialIdx);
  }
  e.preventDefault();
  const el = document.elementFromPoint(e.clientX, e.clientY);
  const span = el && el.closest && el.closest(".sentence");
  if (!span) return;
  const idx = Number(span.dataset.index);
  _addToDragSelection(idx);
}, { passive: false });

document.addEventListener("pointerup", (e) => {
  if (!_dragState) return;
  if (e.pointerId !== _dragState.pointerId) return;
  const wasDrag = _dragState.moved && _assignSelectedIndices.size > 0;
  clearTimeout(_dragState.armTimer);
  _dragState = null;
  if (wasDrag) {
    // Suppress the synthetic click that would otherwise fire on the
    // last sentence the finger was over and re-seek the player right
    // after the user finished a select-drag. Cleared after the click
    // fires (or 100ms, whichever comes first).
    _suppressNextSentenceClick = true;
    setTimeout(() => { _suppressNextSentenceClick = false; }, 100);
  }
});

document.addEventListener("pointercancel", () => {
  if (_dragState) {
    clearTimeout(_dragState.armTimer);
    _dragState = null;
  }
});

let _suppressNextSentenceClick = false;

// Wire drag-select onto a single sentence span. Single tap still
// seeks (handled by enterReadingView's click listener); we only set
// up the pointerdown that seeds the drag state.
function _attachSentenceAssignHandlers(span, idx) {
  span.addEventListener("pointerdown", (e) => {
    // v225.tn76 (#558): character voice assignment is an Author-tier
    // writing-craft tool — it should not arm in Simple or Standard
    // mode. Gate the drag handler at the entry. Tap-to-seek still
    // works in every mode because the seek handler lives on the
    // reading-view click event, not here. (The Characters dialog
    // entry button is already .author-only via CSS, and the
    // colored character rendering is gated by
    // body[data-ui-mode="author"] selectors — this closes the
    // last unhandled path into the voice-assign flow.)
    if (!isAuthorMode()) {
      _dlog("char-voice", "drag pointerdown — gated (not Author mode)", {
        idx,
      });
      return;
    }
    _dlog("char-voice", "drag pointerdown — armed", { idx });
    if (e.pointerType === "mouse" && e.button !== 0) return;
    _dragState = {
      initialIdx: idx,
      startX: e.clientX,
      startY: e.clientY,
      pointerId: e.pointerId,
      pointerType: e.pointerType,
      armed: false,
      moved: false, // gates "is this a real drag" — sentences only
                    // get added once moved is true (movement threshold
                    // crossed). A press-without-movement falls through
                    // to the seek click handler.
      armTimer: null,
    };
    if (e.pointerType === "mouse") {
      // Mouse: arm immediately. Movement-threshold check in pointermove
      // gates actual selection so a single click without dragging still
      // seeks normally.
      _dragState.armed = true;
    } else {
      // Touch / pen: 200ms arm timer. If finger stays still that long
      // we set armed = true so that subsequent movement is treated as
      // a select-drag. If the finger moves before the timer fires,
      // the pointermove handler cancels (the user is scrolling).
      // Crucially, the timer does NOT add the starting sentence —
      // that happens in pointermove the first time movement crosses
      // the threshold, so a hold-without-drag still falls through
      // to seek.
      _dragState.armTimer = setTimeout(() => {
        if (_dragState) _dragState.armed = true;
      }, _DRAG_ARM_MS);
    }
  });
  // Suppress the synthetic seek-click that follows a release at the
  // end of a drag-select. The flag is set true by the pointerup
  // handler above and cleared 100ms later.
  span.addEventListener("click", (e) => {
    if (_suppressNextSentenceClick) {
      e.stopPropagation();
      e.preventDefault();
    }
  }, true);
  // Right-click (desktop) → start a one-sentence selection. Useful for
  // grabbing single isolated sentences without dragging.
  //
  // v225.tn79 (#561): Android fires `contextmenu` on long-press, so
  // this handler was the *actual* path the user's long-press hit in
  // Standard mode — not the pointerdown drag handler we'd already
  // gated in #558. Without the same isAuthorMode() gate here, the
  // long-press kept adding sentences to _assignSelectedIndices, the
  // .sentence-select-pending class got stamped on the sentence, and
  // the previous (buggy) CSS rule then display:none'd the sentence
  // entirely — what the user reported as "long press is deleting
  // sentences." Gating here AND fixing the CSS rule together.
  span.addEventListener("contextmenu", (e) => {
    e.preventDefault();
    if (typeof isAuthorMode === "function" && !isAuthorMode()) {
      _dlog("char-voice", "contextmenu — gated (not Author mode)", { idx });
      return;
    }
    _addToDragSelection(idx);
  });
}

// v220-AB: per-sentence attribution for the reading view. Same logic
// path as segmentTextByCharacter (Tier 1 + Tier 2 + Tier 3 + manual
// override) but returns one entry per sentence instead of merging
// consecutive same-voice sentences into segments. We need the
// granularity to color individual sentence spans.
//
// Returns an array of length === splitSentencesClient(text).length.
// Each entry is { char }: the resolved character (or null for the
// narrator). Designed to be cheap to call on every reading-view paint.
function attributeSentencesForDisplay(text, characters, overrides) {
  const out = [];
  const named = (characters || []).filter(
    (c) => c.name && c.name.trim() && c.voiceId
  );
  if (named.length === 0 && (!overrides || Object.keys(overrides).length === 0)) {
    // No characters + no overrides → everything is narrator.
    for (const _ of splitSentencesClient(text)) out.push({ char: null });
    return out;
  }
  const charRegexes = named.map((c) => ({
    char: c,
    re: new RegExp(`\\b${_escapeRegex(c.name)}\\b`, "i"),
  }));
  function findNamed(s) {
    for (const c of charRegexes) {
      if (c.re.test(s)) return c.char;
    }
    return null;
  }
  let lastNamedChar = null;
  const lastByGender = { male: null, female: null, they: null };
  let activeSpeaker = null;
  let idx = -1;
  const paragraphs = text
    .split(/\r?\n\s*\r?\n+/)
    .map((p) => p.trim())
    .filter(Boolean);
  for (const paragraph of paragraphs) {
    for (const sentence of splitSentencesClient(paragraph)) {
      idx++;
      let resolved = null;
      const hasQuote = _DIALOGUE_QUOTE.test(sentence);
      const explicitName = findNamed(sentence);
      if (explicitName) {
        lastNamedChar = explicitName;
        if (
          explicitName.gender &&
          Object.prototype.hasOwnProperty.call(lastByGender, explicitName.gender)
        ) {
          lastByGender[explicitName.gender] = explicitName;
        }
      }
      if (hasQuote) {
        if (explicitName) {
          resolved = explicitName;
        } else {
          const g = _detectAttributionGender(sentence);
          resolved =
            (g && lastByGender[g]) || activeSpeaker || lastNamedChar || null;
        }
        if (resolved) activeSpeaker = resolved;
      }
      // Manual override wins.
      const override = overrides && overrides[String(idx)];
      if (override !== undefined && override !== null) {
        if (override === "narrator") {
          resolved = null;
        } else {
          const char = named.find(
            (c) => c.name.toLowerCase() === String(override).toLowerCase()
          );
          if (char) {
            resolved = char;
            activeSpeaker = char;
          }
        }
      }
      out.push({ char: resolved });
    }
  }
  return out;
}

// Repaint reading-view sentence colors using the current characters
// roster + the loaded clip's overrides. Cheap; safe to call from the
// color picker's "input" event to give the user live feedback as they
// scrub the color picker. No-op if there's no reading view rendered.
function _repaintReadingViewAttribution() {
  if (!sentenceSpans || sentenceSpans.length === 0) return;
  const text = textEl.value || "";
  if (!text) return;
  const characters = _loadCharacters().filter((c) => c.name && c.voiceId);
  const overrides = _currentClipAssignments || {};
  const attrs = attributeSentencesForDisplay(text, characters, overrides);
  for (let i = 0; i < sentenceSpans.length; i++) {
    const span = sentenceSpans[i];
    if (!span) continue;
    const a = attrs[i];
    const rawText = span.dataset.sentenceText || span.textContent || "";
    const isManualOverride =
      overrides[String(i)] !== undefined && overrides[String(i)] !== null;
    const hasQuote = _DIALOGUE_QUOTE.test(rawText);
    // v220-AI: split the sentence visually when the audio split path
    // applies — auto-attribution to a character + has a quote + the
    // user did NOT manually override the whole sentence. Quote runs
    // get the character color; non-quote runs stay default (narrator).
    // Manual overrides keep the whole sentence in one color (the
    // user's explicit pick should look monolithic).
    const shouldSplit = a && a.char && !isManualOverride && hasQuote;
    let didSplit = false;
    if (shouldSplit) {
      const parts = _splitSentenceByQuote(rawText);
      const hasNonQuote = parts.some((p) => !p.isQuote && p.text.trim());
      if (parts.length > 1 && hasNonQuote) {
        didSplit = true;
        span.classList.add("sentence-split");
        span.style.color = "";
        // Rebuild as sub-spans. This loses any M7.1 highlight markers
        // inside this sentence — acceptable trade-off; highlights are
        // less common than dialogue split.
        span.innerHTML = "";
        for (const part of parts) {
          const sub = document.createElement("span");
          sub.textContent = part.text;
          sub.className = part.isQuote
            ? "sentence-quote-run"
            : "sentence-narration-run";
          if (part.isQuote) {
            sub.style.color = _characterColor(a.char);
          }
          span.appendChild(sub);
        }
      }
    }
    if (!didSplit) {
      // Restore the original built HTML if the span was previously
      // split — the M7.1 highlights / drop caps live in that snapshot.
      if (span.classList.contains("sentence-split")) {
        span.classList.remove("sentence-split");
        if (span.dataset.originalContent) {
          span.innerHTML = span.dataset.originalContent;
        }
      }
      // Whole-sentence color (existing behaviour).
      if (a && a.char) {
        span.style.color = _characterColor(a.char);
      } else {
        span.style.color = "";
      }
    }
    // Reapply the assignment marker (dotted underline) — applies to
    // the outer span regardless of split.
    _applySentenceAssignmentMark(span, i);
  }
}

function _populateVoiceOptions(selectEl, currentVoiceId) {
  // Mirror the main voice dropdown so the character's voice picker shows
  // the same installed Piper / SAPI voice list.
  selectEl.innerHTML = "";
  const placeholder = document.createElement("option");
  placeholder.value = "";
  placeholder.textContent = "Default voice";
  selectEl.appendChild(placeholder);

  for (const og of voiceEl.querySelectorAll("optgroup")) {
    const newOg = document.createElement("optgroup");
    newOg.label = og.label;
    for (const opt of og.querySelectorAll("option")) {
      const c = document.createElement("option");
      c.value = opt.value;
      c.textContent = opt.textContent;
      newOg.appendChild(c);
    }
    selectEl.appendChild(newOg);
  }
  selectEl.value = currentVoiceId || "";
}

function _populateSpeakerOptions(selectEl, voiceId, currentSpeakerId) {
  selectEl.innerHTML = "";
  const n = _voiceSpeakerCounts.get(voiceId) || 1;
  if (n <= 1) {
    selectEl.hidden = true;
    return;
  }
  selectEl.hidden = false;
  for (let i = 0; i < n; i++) {
    const opt = document.createElement("option");
    opt.value = String(i);
    opt.textContent = `Speaker ${i}`;
    selectEl.appendChild(opt);
  }
  selectEl.value = String(Math.min(Number(currentSpeakerId) || 0, n - 1));
}

function renderCharacters() {
  const characters = _loadCharacters();
  charactersList.innerHTML = "";
  if (characters.length === 0) {
    const empty = document.createElement("div");
    empty.className = "characters-empty";
    empty.textContent =
      "No characters yet. Add one to start routing dialogue through a different voice.";
    charactersList.appendChild(empty);
    return;
  }

  for (const ch of characters) {
    const row = document.createElement("div");
    row.className = "character-row";

    const nameInput = document.createElement("input");
    nameInput.type = "text";
    nameInput.className = "character-name";
    nameInput.placeholder = "Name (e.g. Sarah)";
    nameInput.maxLength = 60;
    nameInput.value = ch.name || "";
    nameInput.addEventListener("change", () => {
      _updateCharacter(ch.id, { name: nameInput.value.trim() });
    });

    // Gender hint for Tier 2 pronoun resolution. Optional — leaving it
    // at "—" falls back to Tier 1 (last-named-speaker only). When set,
    // "She said" attributes to the most recent female-tagged character
    // in scope, etc. Tier 2 BACKLOG: gets ~5-10pts of accuracy on
    // mixed-gender two-character dialogue scenes.
    const genderSelect = document.createElement("select");
    genderSelect.className = "character-gender";
    genderSelect.title = "Used to resolve pronoun attribution (he / she / they)";
    for (const [val, label] of [
      ["", "—"],
      ["male", "He"],
      ["female", "She"],
      ["they", "They"],
    ]) {
      const opt = document.createElement("option");
      opt.value = val;
      opt.textContent = label;
      genderSelect.appendChild(opt);
    }
    genderSelect.value = ch.gender || "";
    genderSelect.addEventListener("change", () => {
      _updateCharacter(ch.id, { gender: genderSelect.value || "" });
    });

    const voiceSelect = document.createElement("select");
    voiceSelect.className = "character-voice";
    _populateVoiceOptions(voiceSelect, ch.voiceId);
    voiceSelect.addEventListener("change", () => {
      _updateCharacter(ch.id, { voiceId: voiceSelect.value || null, speakerId: 0 });
      _populateSpeakerOptions(speakerSelect, voiceSelect.value, 0);
    });

    const speakerSelect = document.createElement("select");
    speakerSelect.className = "character-speaker";
    _populateSpeakerOptions(speakerSelect, ch.voiceId, ch.speakerId);
    speakerSelect.addEventListener("change", () => {
      _updateCharacter(ch.id, { speakerId: Number(speakerSelect.value) || 0 });
    });

    // v220-AB: per-character text color for the reading view.
    // Defaults to the hash-derived color (same as the assignment tag
    // chip) so a brand-new character already shows a visual identity
    // before the user picks. The browser's native color picker is
    // mobile-friendly out of the box.
    const colorInput = document.createElement("input");
    colorInput.type = "color";
    colorInput.className = "character-color";
    colorInput.title = "Color used to tint this character's dialogue in the reading view";
    colorInput.value = ch.color || _hashToHex(ch.name || "");
    colorInput.addEventListener("input", () => {
      _updateCharacter(ch.id, { color: colorInput.value });
      // Live re-paint so the user can scrub the color picker and see
      // the reading view track their choice without re-loading.
      _repaintReadingViewAttribution();
    });

    const delBtn = document.createElement("button");
    delBtn.type = "button";
    delBtn.className = "character-delete";
    delBtn.textContent = "×";
    delBtn.title = "Delete character";
    delBtn.setAttribute("aria-label", `Delete ${ch.name || "character"}`);
    delBtn.addEventListener("click", () => _deleteCharacter(ch.id));

    row.append(nameInput, genderSelect, voiceSelect, speakerSelect, colorInput, delBtn);
    charactersList.appendChild(row);
  }
}

// v220-AB: hash-derived hex for the "no color picked yet" fallback.
// Same hue family as _tagColor (HSL output) but converted to hex so it
// drops straight into <input type="color"> without conversion gymnastics.
function _hashToHex(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) h = (h * 31 + str.charCodeAt(i)) | 0;
  const hue = Math.abs(h) % 360;
  // Saturation 65, lightness 60 — readable on both dark + light themes.
  return _hslToHex(hue, 65, 60);
}
function _hslToHex(h, s, l) {
  s /= 100; l /= 100;
  const k = (n) => (n + h / 30) % 12;
  const a = s * Math.min(l, 1 - l);
  const f = (n) => {
    const c = l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
    return Math.round(c * 255).toString(16).padStart(2, "0");
  };
  return `#${f(0)}${f(8)}${f(4)}`;
}

// Return the effective hex color for a character: their picked color
// if set, else the hash fallback. Used for both the reading-view text
// tint and the assignment tag chip's border.
function _characterColor(ch) {
  if (!ch) return null;
  if (ch.color && typeof ch.color === "string") return ch.color;
  return _hashToHex(ch.name || "");
}

function _addCharacter() {
  const list = _loadCharacters();
  list.push({
    id: Date.now(),
    name: "",
    gender: "",
    voiceId: null,
    speakerId: null,
  });
  _saveCharacters(list);
  renderCharacters();
}

function _updateCharacter(id, patch) {
  const list = _loadCharacters();
  const i = list.findIndex((c) => c.id === id);
  if (i < 0) return;
  list[i] = { ...list[i], ...patch };
  _saveCharacters(list);
}

function _deleteCharacter(id) {
  const list = _loadCharacters().filter((c) => c.id !== id);
  _saveCharacters(list);
  renderCharacters();
}

charactersBtn.addEventListener("click", () => {
  renderCharacters();
  charactersDialog.showModal();
});
charactersClose.addEventListener("click", () => charactersDialog.close());
charactersAddBtn.addEventListener("click", _addCharacter);

// Dialogue / attribution heuristic. Tier 3 (v220y): cross-paragraph
// cursors + active-speaker carry-forward, on top of the existing
// Tier 1 (last-named) + Tier 2 (gender-keyed pronoun) passes.
//
// Walks the text paragraph by paragraph, but the THREE cursors all
// persist across paragraph boundaries:
//
//   - `lastNamedChar` — most recently named character (any gender).
//     Used as the Tier 1 fallback when no pronoun matches.
//   - `lastByGender`  — most recently named character per declared
//     gender (male / female / they). Used to resolve "he/she/they said"
//     even when the named speaker is many sentences back — including
//     across paragraph boundaries (real prose names a character once
//     per scene, not once per paragraph).
//   - `activeSpeaker` — the character to whom the most recent dialogue
//     sentence was attributed. Used to carry attribution forward
//     across consecutive quote-only sentences (long speeches split
//     across multiple sentences, or single-paragraph monologues).
//
// Resolution order for a quote-bearing sentence:
//   1. Explicit name in the same sentence  (definitive)
//   2. Pronoun → lastByGender bucket       (gender-disambiguated)
//   3. activeSpeaker                       (long-speech continuation)
//   4. lastNamedChar                       (Tier 1 fallback)
//   5. Narrator                            (no signal)
//
// Pronoun scan (outside the quotes — the dialogue CONTENT can mention
// pronouns too):
//   - "she" / "her" / "hers"    → lastByGender.female
//   - "he"  / "him" / "his"     → lastByGender.male
//   - "they" / "them" / "their" → lastByGender.they
//
// The Tier 2 reset-at-paragraph-break convention ("fresh paragraph +
// opening quote = new speaker") was too aggressive for real prose —
// long speeches and chapter-scale scenes where one character is named
// early then referred to by pronoun for paragraphs afterward both lost
// their attribution. Tier 3 trusts that authors explicitly attribute
// when a new speaker enters; in absence of any signal, the cursors
// keep tracking who was last established.
//
// Accuracy: ~92% on mixed-gender dialogue scenes (long-speech +
// pronoun cases now resolve), vs. ~85% Tier 2, ~75-80% Tier 1.
function _escapeRegex(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

const _DIALOGUE_QUOTE = /["“”'‘’]/;

// Strip quoted spans before scanning for attribution pronouns. Without
// this, the "him" in {"I saw him at the store," John said.} would
// trigger the male pronoun lookup based on the dialogue CONTENT
// instead of the attribution. Curly + straight quotes both handled;
// runaway / mismatched quotes are tolerated (greedy match caps at the
// next quote of the matching family).
function _stripQuotes(sentence) {
  return sentence
    .replace(/“[^”]*”/g, " ")
    .replace(/"[^"]*"/g, " ")
    .replace(/‘[^’]*’/g, " ")
    .replace(/'[^']*'/g, " ");
}

// Pronoun → declared-gender bucket. Singular "they/them/their" maps
// to the "they" bucket — matches how the Characters dialog tags
// non-binary speakers.
const _PRONOUN_TO_GENDER = {
  he: "male", him: "male", his: "male",
  she: "female", her: "female", hers: "female",
  they: "they", them: "they", their: "they",
};

const _PRONOUN_RE = new RegExp(
  `\\b(${Object.keys(_PRONOUN_TO_GENDER).join("|")})\\b`,
  "i"
);

// v220-AJ: list of saying verbs that signal "this clause attributes a
// quote." Without one, a pronoun in the outside-quote text is more
// likely narration than attribution — `"Wait." He raised a hand.`
// shouldn't route the quote to "the most recent male character"
// just because "He" appears outside the quotes.
//
// Verbs cover common dialogue tags + their tense variants (said/says,
// asked/asks, etc.). Adverbs like "softly" are noise that already get
// ignored by the regex — we just need the verb to be present.
const _SAYING_VERBS = /\b(said|says|saying|asked|asks|asking|replied|replies|replying|whispered|whispers|whispering|called|calls|calling|shouted|shouts|shouting|murmured|murmurs|murmuring|declared|declares|declaring|mused|muses|musing|answered|answers|answering|responded|responds|responding|exclaimed|exclaims|exclaiming|cried|cries|crying|muttered|mutters|muttering|sighed|sighs|sighing|added|adds|adding|continued|continues|continuing|began|begins|beginning|started|starts|starting|interrupted|interrupts|interrupting|noted|notes|noting|remarked|remarks|remarking|observed|observes|observing|stated|states|stating|told|tells|telling|spoke|speaks|speaking|repeated|repeats|repeating|insisted|insists|insisting|hissed|hisses|hissing|growled|growls|growling|laughed|laughs|laughing|snapped|snaps|snapping|warned|warns|warning|agreed|agrees|agreeing|admitted|admits|admitting|protested|protests|protesting|gasped|gasps|gasping|breathed|breathes|breathing|offered|offers|offering|countered|counters|countering|drawled|drawls|drawling|conceded|concedes|conceding)\b/i;

function _detectAttributionGender(sentence) {
  const outside = _stripQuotes(sentence);
  // v220-AJ: gate pronoun resolution on the presence of a saying
  // verb. This is what distinguishes "she said" (attribution) from
  // "she stood" (narration that happens to share a sentence with
  // a quote). Without this gate, mixed sentences like
  //   "I would like to discuss terms." He stood and walked to the man.
  // incorrectly attribute to whoever is in the male bucket via "He",
  // instead of falling through to the active-speaker carry-forward.
  if (!_SAYING_VERBS.test(outside)) return null;
  const m = outside.match(_PRONOUN_RE);
  if (!m) return null;
  return _PRONOUN_TO_GENDER[m[1].toLowerCase()] || null;
}

// v220-AH: split a sentence into ordered runs of quoted vs non-quoted
// text. Standard audiobook convention is that the QUOTE goes to the
// character's voice and the surrounding attribution clause (
// "she said.", "Llea replied.", "He looked away.") stays with the
// narrator. Returns [{text, isQuote}, ...] preserving source order.
// Handles straight + curly double and single quotes; single-quote
// runs only count if they contain at least one space (a bare 'it's'
// shouldn't open a fake dialogue span).
function _splitSentenceByQuote(sentence) {
  const parts = [];
  // Note: ordering matters — try curly + straight double quotes first
  // because those are the unambiguous dialogue markers. Singles are
  // last and gated on "has space inside" so contractions don't fire.
  const re = /(?:"[^"]*"|“[^”]*”|‘[^’]* [^’]*’|'[^']* [^']*')/g;
  let last = 0;
  let m;
  while ((m = re.exec(sentence)) !== null) {
    if (m.index > last) {
      const before = sentence.slice(last, m.index);
      if (before.trim()) parts.push({ text: before, isQuote: false });
    }
    parts.push({ text: m[0], isQuote: true });
    last = re.lastIndex;
  }
  if (last < sentence.length) {
    const after = sentence.slice(last);
    if (after.trim()) parts.push({ text: after, isQuote: false });
  }
  return parts;
}

function segmentTextByCharacter(text, characters, fallbackVoiceId, fallbackSpeakerId, opts) {
  // v220-AA: manual per-sentence overrides. The reading view lets the
  // user long-press a sentence and re-assign it to a specific character
  // (or force "narrator"). Those overrides live on the clip as
  // sentenceAssignments and are passed in here. Indexing matches the
  // flat sentence stream the reading view renders (same splitter).
  // Keys are stringified indices so the map JSON-round-trips cleanly.
  //   { "5": "Llea", "12": "narrator" }
  // "narrator" forces the fallback voice; a character name forces that
  // character; absent index = no override, auto-detection wins.
  const overrides = (opts && opts.overrides) || {};
  const hasOverrides = Object.keys(overrides).length > 0;

  const named = characters.filter((c) => c.name && c.name.trim() && c.voiceId);
  if (named.length === 0 && !hasOverrides) {
    // Fast path: no characters defined → single narrator segment.
    const sentences = splitSentencesClient(text);
    return [{
      voiceId: fallbackVoiceId,
      speakerId: fallbackSpeakerId,
      text: sentences.join(" "),
    }];
  }

  const charRegexes = named.map((c) => ({
    voiceId: c.voiceId,
    speakerId: typeof c.speakerId === "number" ? c.speakerId : null,
    gender: c.gender || "", // "" | "male" | "female" | "they"
    re: new RegExp(`\\b${_escapeRegex(c.name)}\\b`, "i"),
  }));

  // First-match wins. Order is the user's roster order; if two
  // characters' names appear in the same sentence (rare), the earlier
  // one in the roster takes attribution. Users can re-order the roster
  // if this matters for their scene.
  function _findNamedChar(sentence) {
    for (const c of charRegexes) {
      if (c.re.test(sentence)) return c;
    }
    return null;
  }

  // Paragraph split: blank line(s) between blocks. Matches what most
  // pasted prose looks like; falls back gracefully to "one big
  // paragraph" if the user pastes a single block with no breaks (in
  // which case the cursor doesn't reset and the whole block is one
  // attribution chain).
  const paragraphs = text
    .split(/\r?\n\s*\r?\n+/)
    .map((p) => p.trim())
    .filter(Boolean);

  const segments = [];
  let current = null;

  // v220y Tier 3: cursors persist across paragraph boundaries. Real
  // prose names a character once per scene then refers to them by
  // pronoun for paragraphs after; the per-paragraph reset of Tier 2
  // dropped attribution every time the writer moved on. activeSpeaker
  // carries the most-recently-attributed character forward across
  // consecutive quote-only sentences so multi-sentence speeches share
  // one voice.
  let lastNamedChar = null;
  const lastByGender = { male: null, female: null, they: null };
  let activeSpeaker = null;
  // v220-AA: global sentence index, matches the reading view's
  // sentenceSpans[i]. Increments once per sentence across all
  // paragraphs so override keys line up.
  let globalSentenceIdx = -1;

  for (const paragraph of paragraphs) {
    const sentences = splitSentencesClient(paragraph);
    for (const sentence of sentences) {
      globalSentenceIdx++;
      let attributedVoice = fallbackVoiceId;
      let attributedSpeaker = fallbackSpeakerId;
      let attributedChar = null; // tracks the char object so we can
                                 // update activeSpeaker after the fact

      const hasQuote = _DIALOGUE_QUOTE.test(sentence);
      const explicitName = _findNamedChar(sentence);

      // Update lastNamedChar + lastByGender on ANY sentence that names
      // a character — narration counts too. The gender bucket only
      // updates when the character has a declared gender (unset
      // characters still contribute to the Tier 1 single-cursor
      // fallback).
      if (explicitName) {
        lastNamedChar = explicitName;
        if (
          explicitName.gender &&
          Object.prototype.hasOwnProperty.call(lastByGender, explicitName.gender)
        ) {
          lastByGender[explicitName.gender] = explicitName;
        }
      }

      if (hasQuote) {
        if (explicitName) {
          // 1) Named in this sentence + quote → direct attribution.
          attributedChar = explicitName;
        } else {
          // 2) No explicit name. Tier 2 (pronoun→gender) > Tier 3
          //    (activeSpeaker carry-forward) > Tier 1 (last-named) >
          //    narrator. Tier 3 sits ABOVE the Tier 1 fallback because
          //    a continuing speech is a stronger signal than "whoever
          //    was last mentioned in narration." Example:
          //      Llea looked at Tom. "I'm sorry," she said. "It's fine."
          //    Sentence 3 has no name, no pronoun. lastNamedChar = Tom
          //    (narration mention), activeSpeaker = Llea (just spoke).
          //    Carry-forward keeps Llea continuing her thought.
          const g = _detectAttributionGender(sentence);
          const fromGender = g && lastByGender[g];
          attributedChar = fromGender || activeSpeaker || lastNamedChar;
        }
        if (attributedChar) {
          attributedVoice = attributedChar.voiceId;
          attributedSpeaker = attributedChar.speakerId;
          activeSpeaker = attributedChar;
        }
      }
      // No quote → narrator. Cursors still updated above for the next
      // dialogue sentence's benefit. activeSpeaker is NOT cleared by
      // narration — a "She set both hands flat on the table." sentence
      // between two quotes shouldn't break the dialogue chain.

      // v220-AA: manual override has the final say. The user already
      // listened to the auto-attribution, decided it was wrong, and
      // explicitly assigned this sentence to someone (or to narrator).
      // We trust them over every Tier of heuristic.
      const override = overrides[String(globalSentenceIdx)];
      const overrideUsed = override !== undefined && override !== null;
      if (overrideUsed) {
        if (override === "narrator") {
          attributedVoice = fallbackVoiceId;
          attributedSpeaker = fallbackSpeakerId;
          // Force-narrator does NOT update activeSpeaker — the next
          // continuation sentence should still inherit whoever was
          // actively speaking before this narrator interruption.
          attributedChar = null;
        } else {
          // Character-name override. Look up in the roster.
          const char = named.find(
            (c) => c.name.toLowerCase() === String(override).toLowerCase()
          );
          if (char) {
            attributedVoice = char.voiceId;
            attributedSpeaker = char.speakerId;
            activeSpeaker = char; // overrides seed continuation too
            attributedChar = char;
          }
          // If the named character was deleted from the roster after
          // the override was set, silently fall through to whatever
          // auto-detection chose. The Edit dialog can surface stale
          // assignments later.
        }
      }

      // v220-AH: split-attribution. When a sentence is auto-attributed
      // to a character AND contains a quote, the audiobook convention
      // is to give the QUOTE to the character and the attribution
      // clause ("she said.", "Llea replied.") back to the narrator.
      // We do NOT split when:
      //   - the user manually overrode the sentence (their explicit
      //     choice trumps the convention)
      //   - the sentence is entirely a single quote (no narration to
      //     hand back to the narrator)
      //   - the sentence has no attributed character (already narrator)
      const shouldSplit =
        attributedChar && hasQuote && !overrideUsed;
      let didSplit = false;
      if (shouldSplit) {
        const parts = _splitSentenceByQuote(sentence);
        const hasNonQuotePart = parts.some(
          (p) => !p.isQuote && p.text.trim()
        );
        if (parts.length > 1 && hasNonQuotePart) {
          didSplit = true;
          for (const part of parts) {
            const text = part.text.trim();
            if (!text) continue;
            const voice = part.isQuote ? attributedChar.voiceId : fallbackVoiceId;
            const speaker = part.isQuote
              ? attributedChar.speakerId
              : fallbackSpeakerId;
            if (
              current &&
              current.voiceId === voice &&
              current.speakerId === speaker
            ) {
              current.text += " " + text;
            } else {
              current = { voiceId: voice, speakerId: speaker, text };
              segments.push(current);
            }
          }
        }
      }

      if (!didSplit) {
        if (
          current &&
          current.voiceId === attributedVoice &&
          current.speakerId === attributedSpeaker
        ) {
          current.text += " " + sentence;
        } else {
          current = {
            voiceId: attributedVoice,
            speakerId: attributedSpeaker,
            text: sentence,
          };
          segments.push(current);
        }
      }
    }
  }
  return segments;
}

// Decode a base64 string to a Uint8Array for Blob construction.
function base64ToBytes(b64) {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

// When set, the next generate() will overwrite this clip id instead of
// creating a fresh one. Used by saveCurrentClipText() to re-synthesize
// when sentence count changes so karaoke alignment stays in sync.
let _regenTargetClipId = null;
// Re-narrate flow: capture the user's listening position at the moment
// they click "Re-narrate," then seek the new combined audio to that
// position after the swap. Without this, re-narrate effectively
// restarts the clip from sentence 0 — disorienting if you were
// halfway through a chapter.
let _regenResumeAtSec = null;
// While re-narrating, sentences still stream in via SSE but we don't
// auto-play them — startNextStreamSentence checks this flag and skips
// the play() call. The user sees the synthesis progress in the status
// line; audio resumes at the captured position once the combined swap
// completes.
let _regenSuppressStreaming = false;

// v220w: library re-narrate is a silent-refresh path. The user tapped 🔄
// on a card; they want the clip updated with the new voice but do NOT
// want stop-and-go playback during synthesis. On a 1-CPU Fly machine,
// per-sentence playback stalls every time the player runs ahead of the
// synth, which sounds like "the synthesis keeps stopping" (it isn't —
// playback is just outpacing it). This flag tells the SSE result
// handler to skip the auto-play at the end. Library re-narrate clears
// the chip pulse + updates the row; the user taps the card to play
// when they're ready.
let _libraryRenarrateNoAutoPlay = false;

// v222 (#456): detect input that looks like a credential before we
// synthesize it. The footgun this guards against: the admin pasted
// their NARRATIVE_KEY into the textarea (clipboard had it from an
// earlier curl), hit Generate, and ended up with a 6-second MP3 of
// Alan reading the key character-by-character — that audio + the
// plaintext sat on the server and in IndexedDB until cleanup, with
// every device that pulls the library getting a copy.
//
// Heuristics are intentionally conservative — single-token only (no
// whitespace), so a paragraph of prose is never flagged. False-positive
// risk: a chapter of prose containing a single line that's nothing but
// a long random-looking string. Acceptable cost — the confirm() lets
// the user proceed in one click.
function _looksLikeCredential(text) {
  const t = (text || "").trim();
  if (!t || /\s/.test(t)) return false;

  // Our minted tester bearer pattern — highest confidence.
  if (/^narrative-[a-z0-9]{4}-[a-z0-9]{4}-[a-z0-9]{4}-[a-z0-9]{4}$/i.test(t)) {
    return true;
  }

  // SHA-256-shaped hex (64 hex chars exactly).
  if (/^[0-9a-f]{64}$/i.test(t)) return true;

  // JWT shape: three base64url-ish segments separated by dots.
  if (
    /^[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$/.test(t) &&
    t.length > 40
  ) {
    return true;
  }

  // Generic API key — single token, 24-256 chars, contains BOTH
  // letters and digits, only credential-safe chars. The mixed-class
  // requirement excludes prose like a long URL slug or a hex dump.
  if (
    t.length >= 24 &&
    t.length <= 256 &&
    /[A-Za-z]/.test(t) &&
    /[0-9]/.test(t) &&
    /^[A-Za-z0-9+/=._-]+$/.test(t)
  ) {
    return true;
  }

  return false;
}

// Shared confirm copy + status hint. Called from generate() and
// _enqueueBg so both the foreground synth path and the queue paths
// catch this. Returns true if the user wants to proceed.
function _confirmCredentialSynth(label) {
  const msg =
    "This " + (label || "text") + " looks like an API key or password.\n\n" +
    "Synthesizing it will save the text AND a recoverable audio recording " +
    "to your library — and sync to the server if sync is on.\n\n" +
    "Synthesize anyway?";
  return window.confirm(msg);
}

async function generate() {
  // v141: belt-and-braces guard. The Generate button is also
  // disabled while a background queue runs, but a programmatic
  // call (e.g. _advanceChapterQueue racing the cancel path) could
  // still reach here — short-circuit with a clearer message than
  // "Type or paste some text first", which sent at least one
  // tester reaching for reload.
  if (_silentChapterQueue) {
    setStatus("Background queue is running — cancel it to generate manually.", true);
    return;
  }
  // v225.tn87 (#569): offline guard. Synth requires the server. If
  // we're offline, save the draft to localStorage so we can replay
  // it once the connection comes back. The user gets immediate
  // confirmation that nothing was lost.
  if (_isOffline()) {
    const offlineText = textEl.value.trim();
    if (!offlineText) {
      setStatus("Type or paste some text first.", true);
      textEl.focus();
      return;
    }
    const entry = {
      id: `pending_${Date.now()}_${Math.floor((performance.now() || 0) % 1000)}`,
      text: offlineText,
      voiceId: voiceEl.value || null,
      rate: Number(rateEl.value),
      volume: Number(volumeEl.value) / 100,
      speakerId: Number(speakerEl.value || 0),
      queuedAt: Date.now(),
    };
    _addPendingSynth(entry);
    setStatus(
      "You're offline — draft queued. It will synthesize automatically when you're back online.",
    );
    return;
  }
  // Reset chapter-queue advance flags so this chapter starts with a
  // clean slate (only matters mid-queue — for non-queue generates the
  // flags should already be false and _chapterTotalCount is 0).
  _resetQueueAdvanceFlags();

  const text = textEl.value.trim();
  if (!text) {
    setStatus("Type or paste some text first.", true);
    textEl.focus();
    return;
  }

  // v222 (#456): credential guard. Catches "pasted my key by mistake,
  // hit Generate" before the synth pipeline saves it to disk + audio.
  if (_looksLikeCredential(text)) {
    if (!_confirmCredentialSynth("text")) {
      setStatus("Cancelled — that text looked like a credential.", true);
      return;
    }
  }

  // v225.tn34 (#510): transcript-pattern warning. A tester hit this
  // with a speech transcript that had 2 periods in 2,911 words; the
  // sentence splitter saw a single 15k-char "sentence" and Piper
  // bailed mid-stream, leaving a 3-second clip. v225.tn34 also adds
  // server-side force-splitting (so the synth no longer fails) — but
  // the resulting audio will sound less natural at the forced-split
  // points (no real sentence boundary = no natural breath). Warn the
  // user so they can choose to add punctuation first.
  //
  // Heuristic: fewer than ONE sentence-end mark per 1000 words. Most
  // prose runs 50-100/1000. Even sparse modern fiction is ≥10/1000.
  // <1 is essentially unpunctuated transcript territory.
  const words = text.split(/\s+/).filter(Boolean);
  const sentenceEnds = (text.match(/[.!?]/g) || []).length;
  const ratio = words.length > 0 ? (sentenceEnds * 1000) / words.length : 0;
  if (words.length >= 300 && ratio < 10) {
    const msg =
      `This text has only ${sentenceEnds} sentence-ending mark${sentenceEnds === 1 ? "" : "s"} ` +
      `(. ! ?) across ${words.length} words — looks like an unpunctuated transcript.\n\n` +
      "To keep the synth from failing, the server will automatically " +
      "insert breaks at commas and whitespace every ~500 characters. " +
      "Those forced breaks won't sound as natural as real sentence " +
      "boundaries — if you add periods at the real sentence breaks " +
      "first, the audio will read much more smoothly.\n\n" +
      "Continue with automatic breaks, or cancel to add punctuation?";
    if (!window.confirm(msg)) {
      setStatus("Cancelled — add some punctuation and try again.", true);
      return;
    }
  }
  // Fail fast when no voice is selected — otherwise the empty voice_id
  // routes through to SAPI's default (or worse, falls into a code path
  // that produces a malformed WAV that lameenc can't encode and the
  // user sees a baffling "mp3 encode failed" instead of "pick a voice").
  // The dropdown is empty when /api/voices failed to load (e.g., Fly.io
  // cold-start 503); the retry-banner path covers that case.
  if (!voiceEl.value) {
    if (_voicesLoadFailed) {
      setStatus(
        "Server's still waking up — voices haven't loaded yet. Hold on a moment.",
        true
      );
    } else {
      setStatus(
        "Pick a voice first — the dropdown is empty.",
        true
      );
    }
    return;
  }

  // Consume the regen target up front so a second concurrent generate()
  // call doesn't double-claim it. If set, fetch the existing clip's
  // identity (title / note / createdAt) so the regen preserves them
  // instead of falling back to auto-suggested defaults.
  const regenTargetId = _regenTargetClipId;
  _regenTargetClipId = null;
  let regenExistingMeta = null;
  if (regenTargetId) {
    try {
      const existing = await getClip(regenTargetId);
      if (existing) {
        regenExistingMeta = {
          title: existing.title,
          note: existing.note || "",
          createdAt: existing.createdAt,
          // Carry bookmarks through a regen — the audio length may have
          // shifted slightly, but the user's notes are too valuable to
          // wipe automatically. They can prune misaligned ones manually.
          bookmarks: Array.isArray(existing.bookmarks) ? existing.bookmarks : [],
          // Preserve URL-extracted images across a regen — the text
          // didn't change, so positions stay valid.
          images: Array.isArray(existing.images) ? existing.images : [],
          // Preserve gitRef. A voice-change regen of a git-sourced
          // clip doesn't change the SHA; a refetch-and-regen replaces
          // the gitRef via _pendingGitRef (the refetch path stashes
          // the new gitRef before invoking generate()).
          gitRef: existing.gitRef || null,
          // v220-AA: carry the user's per-sentence voice overrides
          // through the regen. The text didn't change, so the
          // index→character map stays valid. They feed the segmenter
          // below as opts.overrides so the regen respects them.
          sentenceAssignments:
            existing.sentenceAssignments &&
            typeof existing.sentenceAssignments === "object"
              ? existing.sentenceAssignments
              : {},
          // v223.tn23 (#493): widen the capture so the post-synth
          // save can preserve these fields. The old narrow capture
          // (title/note/createdAt/bookmarks/images/gitRef/assignments)
          // is why notes/tags/cover/annotations/highlights and both
          // sync timestamps got silently wiped from local IDB on
          // every regen. See the matching save block for the wire-up.
          notes: typeof existing.notes === "string" ? existing.notes : "",
          tags: Array.isArray(existing.tags) ? existing.tags : [],
          cover: existing.cover || undefined,
          annotations: Array.isArray(existing.annotations) ? existing.annotations : [],
          highlights: Array.isArray(existing.highlights) ? existing.highlights : [],
          lastSyncedAt: existing.lastSyncedAt || null,
          lastDeviceSyncAt: existing.lastDeviceSyncAt || undefined,
        };
      }
    } catch {}
  }

  _synthController = new AbortController();
  resetStream();
  sentenceOffsetsSec = [];
  // Clear the stale reading-view spans too — _maybeStartRenarrateResume
  // and the regular first-sentence branch both gate "have we rebuilt
  // the reading view yet?" on sentenceSpans.length === 0. Without this
  // reset, a re-narrate would never get past the guard since the loaded
  // clip's reading view leaves sentenceSpans populated.
  sentenceSpans = [];
  activeSentenceIdx = -1;
  enterBusyState();
  setStatus(regenTargetId ? "Re-synthesizing…" : "Starting synthesis…");

  // Character-voice mode kicks in only when Author mode is on, the user
  // has defined at least one character with a voice assigned, AND the
  // text actually contains attributable dialogue (the detection function
  // returns >1 segment). Otherwise we fall through to the regular
  // single-voice synth path.
  const fallbackVoice = voiceEl.value || null;
  const fallbackSpeaker = speakerRow.hidden
    ? null
    : Number(speakerEl.value || 0);
  let endpoint = "/api/synthesize/stream";
  let requestBody;
  let charactersUsed = 0;
  if (isAuthorMode()) {
    const characters = _loadCharacters().filter((c) => c.name && c.voiceId);
    // v220-AA: even with zero characters defined, manual overrides
    // exist if the user previously tagged sentences. Pass them in so
    // a regen still respects the user's force-narrator assignments.
    const overrides = (regenExistingMeta && regenExistingMeta.sentenceAssignments) || {};
    if (characters.length > 0 || Object.keys(overrides).length > 0) {
      const segs = segmentTextByCharacter(
        text, characters, fallbackVoice, fallbackSpeaker, { overrides }
      );
      // Only flip to the segments endpoint if detection actually
      // produced more than one segment — otherwise the regular endpoint
      // is faster and identical in output.
      if (segs.length > 1) {
        endpoint = "/api/synthesize/segments/stream";
        requestBody = JSON.stringify({
          // v4.90: strip user-configured symbols (markdown emphasis chars
          // by default) so Piper/Kokoro don't pronounce literal `*` / `#` /
          // backticks. Reading view keeps raw text.
          segments: segs.map((s) => ({
            text: _stripSynthChars(s.text),
            voice_id: s.voiceId,
            speaker_id: s.speakerId,
          })),
          rate: Number(rateEl.value),
          volume: Number(volumeEl.value) / 100,
        });
        // Count distinct character voices that actually show up so the
        // status line can give the user feedback.
        const used = new Set();
        for (const s of segs) {
          if (s.voiceId && s.voiceId !== fallbackVoice) used.add(s.voiceId);
        }
        charactersUsed = used.size;
      }
    }
  }
  if (!requestBody) {
    requestBody = JSON.stringify({
      // v4.90: strip configured symbols pre-synth (see _stripSynthChars).
      text: _stripSynthChars(text),
      voice_id: fallbackVoice,
      rate: Number(rateEl.value),
      volume: Number(volumeEl.value) / 100,
      speaker_id: fallbackSpeaker,
    });
  }
  if (charactersUsed > 0) {
    setStatus(
      `Synthesising with ${charactersUsed} character voice${charactersUsed === 1 ? "" : "s"}…`
    );
  }

  try {
    const res = await fetch(endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: requestBody,
      signal: _synthController.signal,
    });

    if (!res.ok) {
      let detail = `HTTP ${res.status}`;
      try {
        const j = await res.json();
        if (j.detail) detail = j.detail;
      } catch {}
      throw new Error(detail);
    }

    // Parse the SSE stream manually (EventSource only supports GET).
    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buf = "";

    // v4.82 (#566) — same split-budget watchdog the bg-queue path uses
    // (v225.tn86 / #568). Cold-start synth on a fresh chapter can take
    // 45-90s to deliver the first byte (engine warmup + first sentence
    // WAV); after that the server emits a keepalive comment every 15s
    // so 30s steady-state with 2x slack is safe. Without a watchdog at
    // all, a stalled proxy or crashed server leaves the foreground UI
    // hanging on a frozen progress bar with no way to recover except
    // tapping Cancel. With it, the user sees "connection lost" after
    // the budget expires and can retry.
    let _fgWatchdogFired = false;
    let _fgWatchdogTimer = null;
    let _fgGotFirstByte = false;
    const _FG_FIRST_BYTE_MS = 90000;
    const _FG_STEADY_MS = 30000;
    const _fgIsVisible = () =>
      typeof document === "undefined" || document.visibilityState !== "hidden";
    const _fgResetWatchdog = () => {
      if (_fgWatchdogTimer) clearTimeout(_fgWatchdogTimer);
      // v216 pattern: don't schedule abort while the tab is hidden —
      // mobile browsers throttle background tabs and would kill the
      // synth the user is happily waiting on.
      if (!_fgIsVisible()) return;
      const ms = _fgGotFirstByte ? _FG_STEADY_MS : _FG_FIRST_BYTE_MS;
      _fgWatchdogTimer = setTimeout(() => {
        _fgWatchdogFired = true;
        try { _synthController.abort(); } catch {}
      }, ms);
    };
    const _fgOnVisibility = () => {
      if (!_fgIsVisible()) {
        if (_fgWatchdogTimer) {
          clearTimeout(_fgWatchdogTimer);
          _fgWatchdogTimer = null;
        }
      } else {
        _fgResetWatchdog();
      }
    };
    document.addEventListener("visibilitychange", _fgOnVisibility);
    _fgResetWatchdog();

    while (true) {
      let _readResult;
      try {
        _readResult = await reader.read();
      } catch (err) {
        if (_fgWatchdogTimer) clearTimeout(_fgWatchdogTimer);
        document.removeEventListener("visibilitychange", _fgOnVisibility);
        if (_fgWatchdogFired) {
          const budgetMs = _fgGotFirstByte ? _FG_STEADY_MS : _FG_FIRST_BYTE_MS;
          _dlog && _dlog("synth", `foreground SSE watchdog timeout — no bytes for ${budgetMs / 1000}s`, {
            phase: _fgGotFirstByte ? "steady" : "first-byte",
          });
          throw new Error(
            "connection lost — server may be restarting or unreachable"
          );
        }
        throw err;
      }
      const { done, value } = _readResult;
      if (done) {
        if (_fgWatchdogTimer) clearTimeout(_fgWatchdogTimer);
        document.removeEventListener("visibilitychange", _fgOnVisibility);
        break;
      }
      // Any bytes (including the keepalive comment lines) tick the wire.
      if (!_fgGotFirstByte) _fgGotFirstByte = true;
      _fgResetWatchdog();
      buf += decoder.decode(value, { stream: true });
      // SSE events are terminated by \n\n
      const blocks = buf.split("\n\n");
      buf = blocks.pop(); // keep any incomplete trailing block
      for (const block of blocks) {
        const line = block.trim();
        if (!line.startsWith("data:")) continue;
        let event;
        try { event = JSON.parse(line.slice(5).trim()); } catch { continue; }

        if (event.type === "sentence") {
          // Decode this sentence's WAV (may be empty for silent SAPI chunks)
          // and queue it up. Empty entries get a null URL so the playback
          // chain skips them while keeping index alignment with the offsets.
          const bytes = event.wav_b64 ? base64ToBytes(event.wav_b64) : new Uint8Array(0);
          const url = bytes.length > 0
            ? URL.createObjectURL(new Blob([bytes], { type: "audio/wav" }))
            : null;
          _streamQueue.push({ url, durationSec: 0 });
          sentenceOffsetsSec[event.index] = event.offset_ms / 1000;

          synthProgress.max = event.total;
          synthProgress.value = event.index + 1;
          setStatus(`Synthesising… ${event.index + 1} / ${event.total} sentences`);

          // Re-narrate kick-off: we deliberately suppress streaming
          // playback so the new voice doesn't start at sentence 0 while
          // the user was at sentence 5. Wait until we've queued enough
          // sentences to cover the resume position, then start there.
          if (_regenSuppressStreaming && _streamPlayhead < 0) {
            // Build the reading view exactly once per regen — once
            // sentenceSpans is populated for the new text, subsequent
            // sentence events skip the rebuild.
            if (sentenceSpans.length === 0) {
              enterReadingView(
                text,
                regenExistingMeta && Array.isArray(regenExistingMeta.images)
                  ? regenExistingMeta.images
                  : (_pendingImages || [])
              );
              setMediaMetadata(text);
              playerCard.hidden = false;
            }
            _maybeStartRenarrateResume(event.total);
          } else if (_streamPlayhead < 0 && url) {
            // Normal first-sentence path: kick off streaming playback.
            enterReadingView(
              text,
              regenExistingMeta && Array.isArray(regenExistingMeta.images)
                ? regenExistingMeta.images
                : (_pendingImages || [])
            );
            setMediaMetadata(text);
            playerCard.hidden = false;
            startNextStreamSentence();
          } else if (
            // We were stalled at end-of-current waiting for more audio;
            // the just-arrived sentence is the one we need.
            _streamPlayhead >= 0 && playerEl.ended &&
            _streamPlayhead === _streamQueue.length - 2
          ) {
            startNextStreamSentence();
          }

        } else if (event.type === "result") {
          // Synthesis is done — swap the player from per-sentence WAVs to the
          // full combined audio (now MP3-encoded server-side, ~5x smaller than
          // WAV with no audible loss for speech). After the swap, native seek,
          // download, and library save all see one continuous audio track.
          // There may be a brief audible glitch at the swap; the tradeoff is
          // that the rest of the playback Just Works.
          const combined = new Blob([base64ToBytes(event.mp3_b64)], { type: "audio/mpeg" });
          sentenceOffsetsSec = (event.sentence_offsets_ms || []).map((ms) => ms / 1000);
          // v221.sync-4: server-side persisted sha. Cached on the
          // outer scope so the saveClip call below can carry it onto
          // the clip. The sync adapter (#429) then PUTs the clip by
          // sha reference instead of re-uploading the blob.
          const _fgServerAudioSha = event.audio_sha256 || null;

          if (lastBlobUrl) URL.revokeObjectURL(lastBlobUrl);
          lastBlob = combined;
          lastBlobUrl = URL.createObjectURL(combined);

          // Re-narrate overrides: when the user clicked "Re-narrate
          // with X," _regenResumeAtSec carries the pre-renarrate
          // virtualTime so we resume there instead of wherever the
          // streaming playhead happened to land. _regenSuppressStreaming
          // also tells us to force-resume after the seek (since the
          // player has been intentionally paused throughout streaming
          // and wasPlaying would otherwise be false).
          const renarrateActive = _regenSuppressStreaming;
          const targetTime =
            _regenResumeAtSec != null ? _regenResumeAtSec : virtualTime();
          _regenResumeAtSec = null;
          _regenSuppressStreaming = false;
          const wasPlaying = !playerEl.paused && !playerEl.ended;
          const startedFresh = _streamPlayhead < 0; // no playback at all yet
          _streamPlayhead = -1;
          _streamElapsed = 0;

          playerCard.hidden = false;
          // Make sure the reading view is set up — for very short inputs the
          // sentence event might not have fired the first-sentence branch.
          if (sentenceSpans.length === 0) {
            enterReadingView(
              text,
              regenExistingMeta && Array.isArray(regenExistingMeta.images)
                ? regenExistingMeta.images
                : (_pendingImages || [])
            );
            setMediaMetadata(text);
          }

          const voiceName = voiceEl.selectedOptions[0]?.textContent || voiceEl.value || "";
          // If we're regenerating, reuse the existing clip id so the row
          // updates in place. Otherwise mint a fresh id from the wall clock.
          const newClipId = regenTargetId || Date.now();
          const onLoaded = () => {
            if (isFinite(playerEl.duration)) {
              playerEl.currentTime = Math.min(targetTime, playerEl.duration);
            }
            // wasPlaying captures whether the user was hearing audio
            // before the swap. For re-narrate, streaming was suppressed
            // so wasPlaying is always false — but the user explicitly
            // asked to re-narrate, so we resume regardless.
            //
            // v220w: library re-narrate is the exception — see
            // _libraryRenarrateNoAutoPlay declaration. The user tapped 🔄
            // on a card and doesn't want playback to start.
            if (
              !_libraryRenarrateNoAutoPlay &&
              (wasPlaying || startedFresh || renarrateActive)
            ) {
              playerEl.play().catch(() => {});
            }
            _libraryRenarrateNoAutoPlay = false;
            // Track which library row this player is bound to so the
            // progress-save throttle can update the right one.
            _currentClipId = newClipId;
            _currentPlayingVoiceId = voiceEl.value || null;
            _lastProgressSaveAt = Date.now(); // suppress an immediate redundant save
            saveClip({
              id: newClipId,
              // For regen, preserve whatever title/note/createdAt the user
              // had on the original clip so re-narration doesn't blow away
              // a custom title or note. For new clips, fall back to the
              // auto-suggested title.
              // Chapter queue (if active) supplies the title for new clips
              // — that's how "Chapter 3: The Crossing" lands in the library
              // instead of the auto-suggested first-line title.
              title: regenExistingMeta
                ? regenExistingMeta.title
                : (_pendingChapterTitle || makeTitle(text)),
              note: regenExistingMeta ? regenExistingMeta.note : "",
              text,
              voiceId: voiceEl.value || null,
              voiceName,
              rate: Number(rateEl.value),
              volume: Number(volumeEl.value) / 100,
              speakerId: speakerRow.hidden ? null : Number(speakerEl.value || 0),
              // v219: snapshot voice provenance at generation time. If a
              // regen reuses an old voice on a fresh tier, this records
              // what's true *now*, which is what matters for the audio
              // file produced now. For library import of pre-v219 clips,
              // these fields are simply absent and the Edit dialog falls
              // back to "Unknown provenance."
              provenance: (() => {
                const p = _voiceProvenance(voiceEl.value);
                return p
                  ? {
                      voiceId: voiceEl.value || null,
                      speakerId: speakerRow.hidden
                        ? null
                        : Number(speakerEl.value || 0),
                      voiceName,
                      license: p.license,
                      licenseDataset: p.licenseDataset,
                      licenseCommercial: p.licenseCommercial,
                      attribution: p.attribution,
                      capturedAt: Date.now(),
                    }
                  : null;
              })(),
              sentenceOffsetsSec: sentenceOffsetsSec.slice(),
              blob: combined,
              durationSec: isFinite(playerEl.duration) ? playerEl.duration : 0,
              progressSec: 0,
              // Empty for fresh clips, preserved across regen.
              bookmarks: regenExistingMeta ? regenExistingMeta.bookmarks : [],
              // Carry any URL-extracted images onto the clip. Existing
              // images survive a regen (text didn't change → positions
              // still valid); only a new URL fetch can replace them.
              // v225fz12.chapter-images (#678): fresh-clip branch also
              // merges the matched chapter_image (if any) from the
              // upload-time _pendingChapterImages — title-match first,
              // ordinal fallback. Entry lands at sentence_index 0 so
              // it renders above the first sentence (the chapter
              // heading after splitting). Re-narrate keeps existing.
              images: regenExistingMeta && Array.isArray(regenExistingMeta.images)
                ? regenExistingMeta.images
                : (() => {
                    const base = Array.isArray(_pendingImages)
                      ? _pendingImages.slice()
                      : [];
                    const titleForMatch = _pendingChapterTitle || makeTitle(text);
                    const ord =
                      typeof _chapterCurrentIndex === "number" && _chapterCurrentIndex >= 1
                        ? _chapterCurrentIndex - 1
                        : 0;
                    const chimg = _chapterImageForTitle(titleForMatch, ord);
                    const entry = _chapterImageToImagesEntry(chimg);
                    if (entry && !base.some((i) => i && i.source === "chapter-image" && i.src === entry.src)) {
                      base.unshift(entry);
                    }
                    // v225g7 (#696): same cover dedup as _openAsEbook —
                    // drop inline images whose src matches the auto-
                    // detected cover so the book view + reading view
                    // don't render the cover twice (once on the card
                    // swatch + once inline at sentence 0).
                    const coverSrc =
                      (_pendingDetectedCover && _pendingDetectedCover.src) || null;
                    return coverSrc
                      ? base.filter((img) => !img || img.src !== coverSrc)
                      : base;
                  })(),
              // GitHub source pin.
              //   - Refetch regen: _pendingGitRef is set to the NEW SHA
              //     from the refetch — must win, else the outdated
              //     banner would fire again on next load (loop).
              //   - Voice-change regen: _pendingGitRef is null
              //     (cleared after prior save), so existing wins. SHA
              //     stays correct because text didn't change.
              //   - Fresh clip: regenExistingMeta is null, _pending wins.
              gitRef: _pendingGitRef
                ? _pendingGitRef
                : (regenExistingMeta && regenExistingMeta.gitRef
                    ? regenExistingMeta.gitRef
                    : null),
              // v4.96 (#538 Phase 2): Scrivener source pin. Same
              // precedence as gitRef — fresh import wins, otherwise
              // preserve the existing scrivenerRef across re-narrate
              // so Push to Scrivener still works.
              scrivenerRef: _pendingScrivenerRef
                ? _pendingScrivenerRef
                : (regenExistingMeta && regenExistingMeta.scrivenerRef
                    ? regenExistingMeta.scrivenerRef
                    : null),
              // v220-AA: preserve manual per-sentence voice overrides
              // across regen. New clips start with no overrides ({}),
              // which is the same as no field at all.
              sentenceAssignments:
                regenExistingMeta && regenExistingMeta.sentenceAssignments
                  ? regenExistingMeta.sentenceAssignments
                  : {},
              // v220-AG: this synthesis applied the current assignments
              // by definition, so the audio is now in sync. Clear the
              // dirty flag so the pending-assignments banner hides
              // when the user reloads this clip.
              assignmentsDirty: false,
              // v221.sync-4: server-side audio sha (or undefined if
              // persist was disabled / failed). Sync adapter uses
              // this to PUT the clip by reference instead of blob.
              audioSha256: _fgServerAudioSha || undefined,
              // v223.tn23 (#493): preserve user data the foreground
              // regen path used to silently drop. See bg-queue site
              // for the same rationale. Adds: notes body, tags, cover,
              // annotations, highlights, lastSyncedAt, lastDeviceSyncAt.
              // Without these, a "wrench"/🔄 re-narrate wipes them all
              // from local IDB and the next cross-device pull races to
              // restore them.
              notes: regenExistingMeta ? regenExistingMeta.notes || "" : "",
              tags: regenExistingMeta && Array.isArray(regenExistingMeta.tags)
                ? regenExistingMeta.tags
                : [],
              // v225fz11.cover (#677): fresh-clip branch uses the
              // image_detector cover stashed at upload time, if any.
              // Re-narrate branch (regenExistingMeta truthy) keeps
              // existing.cover as before — detection is a one-shot
              // benefit of the initial import.
              cover: regenExistingMeta
                ? regenExistingMeta.cover || undefined
                : (_pendingDetectedCover && _pendingDetectedCover.src) || undefined,
              annotations: regenExistingMeta && Array.isArray(regenExistingMeta.annotations)
                ? regenExistingMeta.annotations
                : [],
              highlights: regenExistingMeta && Array.isArray(regenExistingMeta.highlights)
                ? regenExistingMeta.highlights
                : [],
              // lastSyncedAt: regen via foreground path is NOT a fresh
              // GitHub pull — the text came from the textarea, not
              // from a refetch. So preserve whatever GitHub sync stamp
              // the clip already had. (Bg-queue path overrides this
              // when chapter.gitRef is set, because that path runs the
              // refetch.)
              lastSyncedAt: regenExistingMeta ? regenExistingMeta.lastSyncedAt : null,
              lastDeviceSyncAt: regenExistingMeta ? regenExistingMeta.lastDeviceSyncAt : undefined,
              createdAt: regenExistingMeta
                ? regenExistingMeta.createdAt
                : new Date().toISOString(),
            })
              .then(() => {
                // v220q: clear the busy state for this clip if it was
                // marked by _libraryRenarrate. renderLibrary() below
                // already re-renders cards; _renarratingClipIds is
                // checked by makeClipCard so the pulse stops naturally.
                if (regenTargetId) _renarratingClipIds.delete(regenTargetId);
                // v225v4.3 (#814): fresh-clip branch — if the toggle is on
                // and we're in Author mode, augment the just-saved clip
                // with lines + nextLineSeq. Regen branch deliberately
                // skipped: the existing clip already has its line-storage
                // state set (via the Edit-dialog toggle or a prior save),
                // and re-narrate shouldn't second-guess that.
                if (!regenTargetId) {
                  _maybeApplyLinesToClip(newClipId, text).catch((e) =>
                    console.warn("[gen] line-storage augmentation failed:", e),
                  );
                }
                renderLibrary();
                // For a regen this picks up the existing bookmarks (which
                // we want to preserve across re-synthesis); for a fresh
                // clip this just renders the empty list (hidden).
                renderBookmarks();
                _updateMiniPlayerTitle();
                // Consume the pending chapter title now that the save has
                // landed; the next chapter (if queued) will set its own.
                _pendingChapterTitle = null;
                // Pending images have been written to the clip — clear so
                // they don't leak into the next fresh clip the user types.
                _pendingImages = [];
                _pendingGitRef = null;
                _pendingScrivenerRef = null;
                // Chapter queue: mark "save side" complete and try to
                // advance. The audio side is signaled separately by
                // streaming exhaustion or the combined MP3's 'ended'.
                // Both must fire before _tryAdvanceQueue does anything,
                // and either ordering works (one sets its flag, the
                // other sees both true and schedules the advance).
                if (_chapterTotalCount > 0) {
                  _queueSaveComplete = true;
                  _tryAdvanceQueue();
                  // Kick off background synthesis of the NEXT chapter
                  // so it's ready to play instantly when this one ends.
                  // Skipped when a regen is pending or another pre-synth
                  // is already in flight (one lookahead at a time).
                  if (
                    _chapterQueue.length > 0 &&
                    !_preSynthChapter &&
                    !_preSynthController &&
                    !_regenTargetClipId
                  ) {
                    _preSynthesizeChapter(_chapterQueue[0]);
                  }
                }
              })
              .catch((e) => console.warn("library save failed:", e));
          };
          playerEl.addEventListener("loadedmetadata", onLoaded, { once: true });
          playerEl.src = lastBlobUrl;

          setStatus(`Ready · ${(combined.size / 1024).toFixed(0)} KB`);

        } else if (event.type === "error") {
          throw new Error(event.message || "synthesis error");
        }
      }
    }
  } catch (err) {
    if (err.name === "AbortError") {
      // Leave the partially-streamed audio in place so the user can keep
      // listening to what was already synthesized.
      setStatus("Cancelled.");
    } else {
      setStatus(`Failed: ${err.message}`, true);
    }
  } finally {
    _synthController = null;
    exitBusyState();
    // Always clear regen state on exit so a stale resume-at doesn't
    // leak into a fresh, unrelated generate. The "success" path inside
    // the result event already clears these, but cancellation /
    // synthesis errors land here without going through that branch.
    _regenResumeAtSec = null;
    _regenSuppressStreaming = false;
    // v220w: same — a cancelled library re-narrate would otherwise
    // leave the no-autoplay flag stuck for the next manual generate.
    _libraryRenarrateNoAutoPlay = false;
  }
}

function download() {
  if (!lastBlob) return;
  const a = document.createElement("a");
  a.href = lastBlobUrl;
  // Pick extension from the blob's MIME so we keep working with WAV clips
  // saved before MP3 export landed. (audio/mpeg → .mp3, audio/wav → .wav.)
  const ext = (lastBlob && lastBlob.type === "audio/mpeg") ? "mp3" : "wav";
  a.download = `narrative.${ext}`;
  document.body.appendChild(a);
  a.click();
  a.remove();
}

generateBtn.addEventListener("click", () => {
  if (_synthController) {
    // Button is in "Cancel" mode — abort the in-flight request.
    _synthController.abort();
  } else {
    generate();
  }
});
downloadBtn.addEventListener("click", download);

// Cmd/Ctrl+Enter to generate from the textarea
textEl.addEventListener("keydown", (e) => {
  if ((e.metaKey || e.ctrlKey) && e.key === "Enter") {
    e.preventDefault();
    generate();
  }
});

// ---- Custom audio player wiring ----------------------------------------
// Bind the visible play/pause/scrubber/mute to the underlying <audio>
// element. The native element handles MediaSession, blob loading, and
// chained per-sentence playback unchanged; we just replace its visible
// chrome. Pause/play events from MediaSession, the keyboard, or our
// other handlers all flow through the audio element's event stream,
// so the UI stays in sync automatically.

function _cpFormatTime(sec) {
  if (!isFinite(sec) || sec < 0) return "0:00";
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  return `${m}:${s < 10 ? "0" : ""}${s}`;
}

// Format a duration as "Xh Ym" (or just "Ym" / "Ys" when shorter) for
// the speed-effective annotation and tooltip. The cp-time M:SS format
// is too cramped for long audiobooks ("203:14" reads worse than
// "3h 23m"), and at wall-clock granularity seconds aren't useful.
function _fmtDurationCoarse(sec) {
  if (!isFinite(sec) || sec < 0) return "0s";
  if (sec < 60) return `${Math.round(sec)}s`;
  const totalMin = Math.round(sec / 60);
  const h = Math.floor(totalMin / 60);
  const m = totalMin % 60;
  if (h === 0) return `${m}m`;
  if (m === 0) return `${h}h`;
  return `${h}h ${m}m`;
}

// SVG-safe hidden toggle. `svg.hidden = true` sets the IDL property
// but doesn't reflect to the content attribute the way it does for
// HTMLElement, so the [hidden] CSS selector never matches and our
// `display: block` rule keeps the icon visible. setAttribute /
// removeAttribute is the explicit workaround. (HTML elements work
// fine with .hidden = ..., this helper just handles SVG too.)
function _setSvgHidden(el, hide) {
  if (hide) el.setAttribute("hidden", "");
  else el.removeAttribute("hidden");
}

function _cpRefreshPlayIcon() {
  const playing = !playerEl.paused && !playerEl.ended;
  _setSvgHidden(cpPlayIcon, playing);
  _setSvgHidden(cpPauseIcon, !playing);
  cpPlayBtn.setAttribute("aria-label", playing ? "Pause" : "Play");
  // v188: mirror the same state on the hero play button. Same icon
  // swap, same aria. The two buttons feed the same playback so they
  // always agree.
  const heroPlay = document.getElementById("hero-play-icon");
  const heroPause = document.getElementById("hero-pause-icon");
  const heroBtn = document.getElementById("hero-play-btn");
  if (heroPlay && heroPause) {
    _setSvgHidden(heroPlay, playing);
    _setSvgHidden(heroPause, !playing);
  }
  if (heroBtn) heroBtn.setAttribute("aria-label", playing ? "Pause" : "Play");
}

function _cpRefreshTime() {
  const cur = playerEl.currentTime || 0;
  const dur = isFinite(playerEl.duration) ? playerEl.duration : 0;
  cpTimeCurrent.textContent = _cpFormatTime(cur);
  cpTimeDuration.textContent = _cpFormatTime(dur);
  const pct = dur > 0 ? Math.min(100, (cur / dur) * 100) : 0;
  cpProgress.style.width = `${pct}%`;
  cpThumb.style.left = `${pct}%`;
  cpScrubber.setAttribute("aria-valuenow", String(Math.round(pct)));
  // Wall-clock-remaining annotation. Only shown at non-1× speed —
  // at 1× the M:SS duration above already answers it.
  if (cpTimeEffective) {
    const speed = _playbackRate || 1;
    if (speed !== 1 && dur > 0) {
      const remaining = Math.max(0, (dur - cur) / speed);
      cpTimeEffective.textContent = `· ${_fmtDurationCoarse(remaining)} left`;
      cpTimeEffective.hidden = false;
    } else {
      cpTimeEffective.hidden = true;
      cpTimeEffective.textContent = "";
    }
  }
}

function _cpRefreshBuffered() {
  const dur = isFinite(playerEl.duration) ? playerEl.duration : 0;
  if (dur <= 0 || !playerEl.buffered.length) {
    cpBuffered.style.width = "0%";
    return;
  }
  let end = 0;
  for (let i = 0; i < playerEl.buffered.length; i++) {
    end = Math.max(end, playerEl.buffered.end(i));
  }
  cpBuffered.style.width = `${Math.min(100, (end / dur) * 100)}%`;
}

function _cpRefreshMute() {
  const muted = playerEl.muted || playerEl.volume === 0;
  _setSvgHidden(cpVolIcon, muted);
  _setSvgHidden(cpMuteIcon, !muted);
  cpMuteBtn.setAttribute("aria-label", muted ? "Unmute" : "Mute");
}

cpPlayBtn.addEventListener("click", () => {
  if (playerEl.paused) {
    playerEl.play().catch(() => {});
  } else {
    _pauseAsUser();
  }
});

// v188: hero Play/Pause button — same toggle as cp-play-btn so a
// user can drive playback from the top of the page without
// scrolling to the player card. _cpRefreshPlayIcon keeps the
// icons in sync. Wire here (vs in the migration block below) so
// the click handler is bound to the actual DOM node, not a clone.
const heroPlayBtn = document.getElementById("hero-play-btn");
if (heroPlayBtn) {
  heroPlayBtn.addEventListener("click", () => {
    if (playerEl.paused) {
      playerEl.play().catch(() => {});
    } else {
      _pauseAsUser();
    }
  });
}

// v198: phones bypass the v188/v195 dual-strip system entirely.
// The user wanted the hero-inline + floating-clone behavior for
// tablet and desktop only; on phones the chips stay where they
// always were — in .player-actions inside the player card, as a
// horizontal-scrolling row. This shared gate runs ONCE so both
// the migration and the clone-build IIFEs see the same answer
// (a viewport resize across the breakpoint isn't handled
// post-init; assumed stable for the session).
const _heroStripsActive = !window.matchMedia("(max-width: 720px)").matches;

// v195: dual chip strips with cross-fade. The hero strip
// (#hero-controls) lives inside .hero-row's flex middle slot and
// is visible when the user is at the top of the page — sitting in
// the otherwise-empty space between the "Narrative" wordmark and
// the icon rail. When the user scrolls past the player card, the
// hero strip naturally scrolls out of view; at that point the
// floating clone (#hero-controls-float) fades in at top: 6px so
// the controls remain reachable. The two strips share state via:
//   - one set of ORIGINAL chip DOM nodes inside #hero-controls
//     (event handlers bound here as usual)
//   - CLONED chip nodes inside #hero-controls-float that forward
//     clicks to the originals and mirror the originals' textContent
//     / class / [hidden] state via MutationObserver
// This avoids touching the existing per-chip event handlers — they
// stay bound to the originals and Just Work.
(() => {
  if (!_heroStripsActive) return;  // v198: phones keep chips in player card
  const heroControls = document.getElementById("hero-controls");
  const playerActions = document.querySelector("section.player .player-actions");
  if (!heroControls || !playerActions) return;
  const toMove = [
    "skip-back-btn",
    "skip-forward-btn",
    "bookmark-add-btn",
    "sleep-btn",
    "ab-loop-btn",
    "speed-btn",
    "notes-btn",
  ];
  for (const id of toMove) {
    const el = document.getElementById(id);
    if (el) heroControls.appendChild(el);
  }
})();

// v195: build the floating clone strip.
(() => {
  if (!_heroStripsActive) return;  // v198: phones bypass
  const heroControls = document.getElementById("hero-controls");
  const floatStrip = document.getElementById("hero-controls-float");
  const playerCard = document.getElementById("player-card");
  if (!heroControls || !floatStrip || !playerCard) return;

  // Mirror originals → clones inside the float container. For each
  // child of #hero-controls we make a deep clone, strip duplicate
  // IDs (browsers tolerate dupes but they break getElementById and
  // any future a11y label lookup), forward clicks, and observe the
  // original for state changes.
  const pairs = [];
  Array.from(heroControls.children).forEach((original) => {
    const clone = original.cloneNode(true);
    // Strip ID on the clone root + any descendants (the SVG icons
    // inside the round play button each carry an ID).
    if (clone.id) clone.id = clone.id + "-fl";
    clone.querySelectorAll("[id]").forEach((el) => {
      el.id = el.id + "-fl";
    });
    floatStrip.appendChild(clone);
    pairs.push({ original, clone });

    // Forward clicks. preventDefault/stopPropagation so the
    // clone's own bubbling doesn't double-fire if any ancestor
    // delegate listens for chip events.
    clone.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      original.click();
    });

    // Mirror state. Watching the original for any textContent /
    // attribute / subtree mutation, we resync the clone's innerHTML
    // + className. The click listener stays on the clone root
    // (innerHTML only replaces descendants), so forwarding survives.
    const sync = () => {
      // Bail if nothing actually changed visually — avoids needless
      // reflows when the cycle handler touches a sibling.
      if (clone.innerHTML !== original.innerHTML) {
        clone.innerHTML = original.innerHTML;
        // Re-mangle IDs that just came back via innerHTML so we
        // never reintroduce duplicates.
        clone.querySelectorAll("[id]").forEach((el) => {
          if (!el.id.endsWith("-fl")) el.id = el.id + "-fl";
        });
      }
      if (clone.className !== original.className) {
        clone.className = original.className;
      }
      if (clone.hidden !== original.hidden) {
        clone.hidden = original.hidden;
      }
      if (clone.disabled !== original.disabled) {
        clone.disabled = original.disabled;
      }
    };
    new MutationObserver(sync).observe(original, {
      childList: true,
      characterData: true,
      subtree: true,
      attributes: true,
    });
  });

  // Hero strip visibility (clip loaded vs not) tracks the player
  // card's [hidden] state — same v188 model. Float visibility
  // additionally requires the player card to have scrolled off
  // the top of the viewport.
  const syncHidden = () => {
    heroControls.hidden = playerCard.hidden;
    // If the clip just got cleared, hide the float immediately
    // regardless of scroll state.
    if (playerCard.hidden) {
      floatStrip.hidden = true;
      floatStrip.dataset.visible = "false";
    }
  };
  syncHidden();
  new MutationObserver(syncHidden).observe(playerCard, {
    attributes: true,
    attributeFilter: ["hidden"],
  });

  // IntersectionObserver: fade float in when the HERO STRIP has
  // entirely scrolled above the viewport. Watching the hero (not
  // the player card) closes the v195a gap — there's a stretch
  // where the hero has scrolled out but the player card is still
  // visible below, and watching the player card meant the float
  // sat hidden during that stretch. Watching the hero strip
  // itself triggers the float the moment the inline strip leaves
  // the viewport top.
  const observerTarget = heroControls;
  const observer = new IntersectionObserver(
    (entries) => {
      for (const entry of entries) {
        const scrolledPast = entry.boundingClientRect.bottom < 0;
        const shouldShow = scrolledPast && !playerCard.hidden;
        if (shouldShow) {
          floatStrip.hidden = false;
          // Force a layout pass so the initial opacity transition
          // actually animates on first show.
          void floatStrip.offsetHeight;
          floatStrip.dataset.visible = "true";
        } else {
          floatStrip.dataset.visible = "false";
          // Wait for the fade-out before hiding so the transition
          // can run; matches the CSS duration.
          setTimeout(() => {
            if (floatStrip.dataset.visible !== "true") {
              floatStrip.hidden = true;
            }
          }, 240);
        }
      }
    },
    { threshold: 0 }
  );
  observer.observe(observerTarget);

  // Initial state.
  floatStrip.dataset.visible = "false";
})();

cpMuteBtn.addEventListener("click", () => {
  playerEl.muted = !playerEl.muted;
  _cpRefreshMute();
});

// Scrubber: click anywhere on the track to seek; drag the thumb to scrub.
// Uses Pointer Events so the same code path handles mouse, touch, and
// stylus without three implementations.
let _cpScrubbing = false;
function _cpSeekFromPointer(ev) {
  const rect = cpScrubber.getBoundingClientRect();
  const x = ev.clientX - rect.left;
  const pct = Math.max(0, Math.min(1, x / rect.width));
  const dur = isFinite(playerEl.duration) ? playerEl.duration : 0;
  if (dur > 0) {
    playerEl.currentTime = pct * dur;
    _cpRefreshTime();
  }
}
cpScrubber.addEventListener("pointerdown", (ev) => {
  _cpScrubbing = true;
  cpScrubber.classList.add("dragging");
  cpScrubber.setPointerCapture(ev.pointerId);
  _cpSeekFromPointer(ev);
});
cpScrubber.addEventListener("pointermove", (ev) => {
  if (_cpScrubbing) _cpSeekFromPointer(ev);
});
cpScrubber.addEventListener("pointerup", (ev) => {
  if (!_cpScrubbing) return;
  _cpScrubbing = false;
  cpScrubber.classList.remove("dragging");
  try { cpScrubber.releasePointerCapture(ev.pointerId); } catch {}
});
cpScrubber.addEventListener("pointercancel", () => {
  _cpScrubbing = false;
  cpScrubber.classList.remove("dragging");
});
// Keyboard: ← / → seek by 5s; Home / End jump to start / end.
cpScrubber.addEventListener("keydown", (ev) => {
  const dur = isFinite(playerEl.duration) ? playerEl.duration : 0;
  if (!dur) return;
  if (ev.key === "ArrowLeft") {
    playerEl.currentTime = Math.max(0, playerEl.currentTime - 5);
    ev.preventDefault();
  } else if (ev.key === "ArrowRight") {
    playerEl.currentTime = Math.min(dur, playerEl.currentTime + 5);
    ev.preventDefault();
  } else if (ev.key === "Home") {
    playerEl.currentTime = 0;
    ev.preventDefault();
  } else if (ev.key === "End") {
    playerEl.currentTime = dur;
    ev.preventDefault();
  }
});

// Mirror native events into the custom UI. All four are needed: play/
// pause for the icon, timeupdate for the scrubber, durationchange so
// freshly-loaded clips show their length immediately, progress so the
// buffered fill catches up as the audio downloads.
playerEl.addEventListener("play", _cpRefreshPlayIcon);
playerEl.addEventListener("pause", _cpRefreshPlayIcon);
playerEl.addEventListener("ended", _cpRefreshPlayIcon);
playerEl.addEventListener("timeupdate", _cpRefreshTime);
playerEl.addEventListener("durationchange", _cpRefreshTime);
playerEl.addEventListener("loadedmetadata", () => {
  _cpRefreshTime();
  _cpRefreshBuffered();
});
playerEl.addEventListener("progress", _cpRefreshBuffered);
playerEl.addEventListener("volumechange", _cpRefreshMute);
// Initial paint so the controls don't show blank before any audio loads.
_cpRefreshPlayIcon();
_cpRefreshTime();
_cpRefreshMute();

loadVoices();
setupMediaSession();

// ---- Media Session API ----------------------------------------------------
// Surfaces play/pause/seek controls on the phone lock screen, Control Center
// (iOS), and notification shade (Android). Also makes the app respond to
// physical media keys on desktop. Falls back silently if unsupported.

function makeTitle(text) {
  const raw = (text || "").trim();
  if (!raw) return "Narrative";
  // v225v4.4 (#815): public-domain library packagings (Roy Glashan's
  // Library is the canonical offender) ship a credit preamble — e.g.
  // "Roy Glashan's Library  Non sibi sed omnibus  RGL e-Book Cover
  // The Old Tower of Frankenstein" — that smushes onto the first line
  // of the extracted text. The old "first 60 chars" rule then used the
  // brand + motto as the clip title.
  //
  // Two-stage cleanup:
  //   1. STRIP_PREFIX — if a candidate line contains a library-specific
  //      sentinel ("e-Book Cover" / "Ex Libris"), strip everything up to
  //      and including the sentinel, so a within-line real title can
  //      surface. The sentinels are deliberately multi-word and unlikely
  //      to occur in real book titles, to keep the strip from chewing
  //      legitimate text.
  //   2. BOILERPLATE_LINE — even after the prefix strip, some lines are
  //      pure metadata (the RGL motto, a lone "Cover" / "Contents" / etc.)
  //      and should be skipped entirely. Walk up to 15 lines looking for
  //      the first clean one.
  //
  // Belt-and-suspenders: if every line in the lookahead window fails the
  // filter, fall back to the unfiltered first line so we never emit "".
  const STRIP_PREFIX = /^.*?\b(?:e-?book\s*cover|ex\s*libris)\s*[:—–\-|]*\s*/i;
  const BOILERPLATE_LINE = new RegExp(
    [
      "roy\\s+glashan'?s\\s+library",
      "non\\s+sibi\\s+sed\\s+omnibus",
      "project\\s+gutenberg",
      "^\\s*RGL\\s*$",
      "^\\s*cover\\s*$",
      "^\\s*ex\\s*libris\\s*$",
      "^\\s*frontispiece\\s*$",
      "^\\s*title\\s*page\\s*$",
      "^\\s*table\\s*of\\s*contents\\s*$",
      "^\\s*contents\\s*$",
    ].join("|"),
    "i",
  );
  const lines = raw.split(/[\r\n]+/);
  for (let i = 0; i < Math.min(15, lines.length); i++) {
    let candidate = lines[i].trim();
    if (!candidate) continue;
    candidate = candidate.replace(STRIP_PREFIX, "").trim();
    if (!candidate) continue;
    if (BOILERPLATE_LINE.test(candidate)) continue;
    // Strays — single punctuation chars, ordinal stubs.
    if (candidate.length < 3) continue;
    const slice = candidate.slice(0, 60).trim();
    return candidate.length > 60 ? `${slice}…` : slice;
  }
  // Defensive: nothing survived the filter. Use the raw first line so
  // we still produce something the user can rename in Edit.
  const firstLine = raw.split(/\r?\n/, 1)[0];
  const trimmed = firstLine.slice(0, 60).trim();
  if (!trimmed) return "Narrative";
  return firstLine.length > 60 ? `${trimmed}…` : trimmed;
}

// ---- Chapter auto-split --------------------------------------------------
// When a paste / file-load / URL-fetch lands in the textarea, scan for
// chapter markers. If 2+ are found, surface a banner offering to split
// the text into separate clips. On Split: chapter 1 goes into the
// textarea, the rest queue up, generate() picks them off one by one and
// auto-continues until the queue drains. Single button push, walk away,
// come back to a fully-narrated book.

const chapterBanner = $("chapter-banner");
const chapterBannerCount = $("chapter-banner-count");
const chapterBannerSplit = $("chapter-banner-split");
const chapterBannerDismiss = $("chapter-banner-dismiss");
const chapterQueueEl = $("chapter-queue");
const chapterQueueText = $("chapter-queue-text");
const chapterQueueCancel = $("chapter-queue-cancel");

let _chapterQueue = [];          // [{title, text}] still to synthesize
let _chapterTotalCount = 0;      // fixed for the life of the queue
let _chapterCurrentIndex = 0;    // 1-based; what's loaded in the textarea right now
let _pendingChapterTitle = null; // consumed by generate() in place of makeTitle
let _detectedChapters = null;    // hangs around between banner show and Split click
// v139: background-mode queue. When true, _startBackgroundChapterQueue
// drives the chapter loop via _preSynthesizeChapter sequentially; no
// audio ever loads into the player, and _advanceChapterQueue (the
// foreground autoplay path) is bypassed entirely.
let _silentChapterQueue = false;
// v141: live per-chapter progress for the silent queue, sourced from
// the synthesizer's SSE `sentence` events. Without these the pill
// only ticked once per chapter (which can be MINUTES for a long
// one), making the queue look stuck. _bgSynthCurrentTitle holds the
// chapter whose synthesis is in flight; _bgSynthSentence /
// _bgSynthTotal are the latest counter and target.
let _bgSynthCurrentTitle = "";
// v225.tn33 (#509): per-synth telemetry surface so the "OK"/"FAIL"
// log lines can report whether the synthesis was REAL or stunted.
// The bg-queue's old "OK ${title}" line just said "we didn't throw"
// — a partial stream that ended cleanly logged success, leaving the
// tester with a 3-second clip and no audit trail. Telemetry that
// gets captured per synth and read by the queue-level log:
//   • startMs / endMs           — wall-clock bracket
//   • blobSize / durationSec    — what actually landed
//   • lastSentenceIndex / total — how far the stream got
//   • truncated                 — sentencesSeen < advertised
//   • charsPerSec               — sanity check; >800 = impossible
let _bgLastSynth = null;
function _bgResetSynthTelemetry() {
  _bgLastSynth = {
    startMs: Date.now(),
    endMs: null,
    blobSize: null,
    durationSec: null,
    sentencesSeen: 0,
    sentencesAdvertised: 0,
    sourceUrl: null,
    truncated: null,    // set at finalize
    charsPerSec: null,  // set at finalize
  };
}
let _bgSynthSentence = 0;
// v221.sync-4: server returns audio_sha256 in the result event when it
// successfully persisted the MP3 to the volume. Captured per-job so
// the saveClip path can record it on the clip and the sync adapter
// (#429) can later PUT the clip referencing the sha instead of
// re-uploading the audioB64. Reset at the start of each synth attempt.
let _bgCurrentServerAudioSha = null;
let _bgSynthTotal = 0;

// Pre-synthesis lookahead: chapter N+1 gets synthesized in the background
// while the user listens to chapter N, then loaded instantly from the
// library when chapter N's audio ends. _preSynthChapter holds {clipId,
// title} of the ready chapter; _preSynthController aborts any in-flight
// background fetch (used by cancel / regen / clear paths).
let _preSynthChapter = null;
let _preSynthController = null;

// Try each chapter-marker family in priority order. First family with
// 2+ matches wins; later families are ignored to avoid double-splitting.
// Returns null when nothing structured was found.
// Front-matter titles whose body content is reference / list / metadata
// and not worth synthesizing as audio. Match is case-insensitive against
// the heading text after the v84 normalization (so "## CONTENTS" lands
// here as "CONTENTS", and a "Table of Contents" header on another source
// also matches). PREFACE / FOREWORD / INTRODUCTION are intentionally
// NOT in this set — those are usually real prose.
const FRONT_MATTER_TITLES = new Set([
  "contents",
  "table of contents",
  "list of contents",
  "illustrations",
  "list of illustrations",
  "index",
  "glossary",
  "bibliography",
  "references",
  "colophon",
  "imprint",
  "copyright",
  "acknowledgements",
  "acknowledgments",
  "about the author",
  "about this book",
]);

function _isSkippableFrontMatter(title, body) {
  const t = (title || "").trim().toLowerCase().replace(/[:\-—.]+\s*$/, "");
  if (FRONT_MATTER_TITLES.has(t)) return true;
  // Belt-and-suspenders: if the body is dominated by short "CHAPTER N"
  // lines (a flattened TOC that escaped the title filter — happens when
  // a source uses a non-standard heading like "Table" instead of
  // "Contents"), treat it as front matter. Threshold: more than half the
  // non-blank lines are bare chapter references.
  const lines = body.split(/\r?\n/).map((s) => s.trim()).filter(Boolean);
  if (lines.length < 8) return false;
  const chapterishRe = /^(chapter|part|book|section)\s+[0-9ivxlcdm]+/i;
  const chapterish = lines.filter((ln) => chapterishRe.test(ln)).length;
  return chapterish / lines.length > 0.5;
}

function _detectChapters(text) {
  if (!text || text.length < 400) return null;
  const lines = text.split(/\r?\n/);

  // Pattern families. Each function maps a line to either null (no
  // match) or a title string.
  const families = [
    // Markdown ATX headings (# / ## / ###).
    (line) => {
      const m = line.match(/^(#{1,3})\s+(.+?)\s*#*\s*$/);
      if (!m) return null;
      const raw = m[2].trim();
      // Standard Ebooks renders chapter headings as bare Roman numerals
      // (## I, ## II, ## III) — a title of just "I" is useless in the
      // library, so promote it to "Chapter I" / "Chapter 12".
      if (/^[0-9]+$/.test(raw) || /^[ivxlcdm]+$/i.test(raw)) {
        return `Chapter ${raw.toUpperCase()}`;
      }
      // "CHAPTER I" / "Chapter II" / "PART 3" / "Part Three" — Project
      // Gutenberg headings injected server-side land here in ALL CAPS.
      // Title-case the keyword and keep whatever comes after it
      // (numeral + optional subtitle) intact so the library cards read
      // as "Chapter I" not "CHAPTER I".
      const k = raw.match(
        /^(chapter|part|book|section)\b\s*(.*)$/i
      );
      if (k) {
        const word = k[1].charAt(0).toUpperCase() + k[1].slice(1).toLowerCase();
        const rest = (k[2] || "").trim();
        return rest ? `${word} ${rest}` : word;
      }
      // Real titles like "Preface", "The Garden Party" flow through.
      return raw;
    },
    // "Chapter N" / "CHAPTER 12" / "Chapter One" / "Part 3" — optional
    // subtitle after a colon, em-dash, period, or just a space.
    (line) => {
      const m = line
        .trim()
        .match(
          /^(chapter|part|book|section)\s+([0-9]+|[ivxlcdm]+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty)\b[\s.:—–-]*(.*)$/i
        );
      if (!m) return null;
      const word = m[1].charAt(0).toUpperCase() + m[1].slice(1).toLowerCase();
      const num = m[2].trim();
      const subtitle = (m[3] || "").trim();
      const head = `${word} ${num}`;
      return subtitle ? `${head}: ${subtitle}` : head;
    },
  ];

  for (const match of families) {
    const hits = [];
    for (let i = 0; i < lines.length; i++) {
      const t = match(lines[i]);
      if (t) hits.push({ lineIdx: i, title: t });
    }
    if (hits.length < 2) continue;

    // Build chapters: body of chapter i is lines (hits[i]+1 .. hits[i+1]-1).
    const chapters = [];
    for (let h = 0; h < hits.length; h++) {
      const startLine = hits[h].lineIdx + 1;
      const endLine = h + 1 < hits.length ? hits[h + 1].lineIdx : lines.length;
      const body = lines.slice(startLine, endLine).join("\n").trim();
      // Skip chapters with nothing in them (a stray "Chapter 1" with no
      // following prose isn't worth a clip — saves the user from a junk
      // entry in their library).
      if (!body) continue;
      // Skip common front-matter sections that aren't worth listening to
      // as audio. The Project Gutenberg heading-injection pass surfaces
      // these as their own "chapters" — without the filter, TOC content
      // (35 "CHAPTER N." entries, each treated as a sentence with a
      // pause after it) ends up as the second clip in the queue.
      // PREFACE deliberately omitted — it's real prose worth hearing.
      if (_isSkippableFrontMatter(hits[h].title, body)) continue;
      chapters.push({ title: hits[h].title, text: body });
    }
    if (chapters.length < 2) continue;

    // Preamble before chapter 1: if it's shortish, fold into chapter 1.
    // If it's substantial (likely real prose like a foreword), promote
    // it to its own segment with an auto-suggested title.
    const preamble = lines.slice(0, hits[0].lineIdx).join("\n").trim();
    if (preamble) {
      if (preamble.length < 800) {
        chapters[0].text = preamble + "\n\n" + chapters[0].text;
      } else {
        chapters.unshift({ title: makeTitle(preamble), text: preamble });
      }
    }
    return chapters;
  }
  return null;
}

function _showChapterBanner(chapters) {
  _detectedChapters = chapters;
  chapterBannerCount.textContent =
    chapters.length === 1 ? "1 chapter" : `${chapters.length} chapters`;
  chapterBanner.hidden = false;
}

function _hideChapterBanner() {
  _detectedChapters = null;
  chapterBanner.hidden = true;
}

function _updateChapterQueueUI() {
  // v162: silent queue may be active even when _chapterTotalCount is
  // 0 (a single job was queued, picked up, and is in flight; the
  // queue array is empty but _bgCurrent isn't). Treat either signal
  // as "we have something to show in the pill."
  const silentActive = _silentChapterQueue || _bgCurrent;
  if (_chapterTotalCount <= 0 && !silentActive) {
    chapterQueueEl.hidden = true;
    return;
  }
  chapterQueueEl.hidden = false;
  const idx = _chapterCurrentIndex;
  const total = _chapterTotalCount;
  const nextTitle = _chapterQueue.length > 0 ? _chapterQueue[0].title : null;
  // v139: background-mode pill makes it explicit that nothing's
  // about to play — the user opted in for silent upload while away.
  // v141: add the current chapter's title + live sentence progress
  // (sourced from SSE in _preSynthesizeChapter) so a long chapter
  // doesn't look stuck. Also mark the pill .background-active so
  // the CSS pulse dot kicks in.
  if (silentActive) {
    chapterQueueEl.classList.add("background-active");
    const curTitle = _bgSynthCurrentTitle || (_bgCurrent && _bgCurrent.title) || "";
    const progress = _bgSynthTotal > 0
      ? ` · ${_bgSynthSentence}/${_bgSynthTotal} sentences`
      : "";
    const curLabel = curTitle ? `: ${curTitle}` : "";
    // v162: drop "X of Y" — the persistent queue can grow mid-flight,
    // so a fixed-total count goes stale. Show the current title +
    // sentence progress + pending count instead.
    const pendingTail = _chapterQueue.length
      ? ` · ${_chapterQueue.length} more queued`
      : "";
    chapterQueueText.textContent =
      `Background · Synthesizing${curLabel}${progress}${pendingTail}`;
    return;
  }
  // Foreground mode: drop the active class so the pulse dot doesn't
  // bleed across modes (e.g. if a foreground queue starts after a
  // background queue completes within the same session).
  chapterQueueEl.classList.remove("background-active");
  const head = `Chapter ${idx} of ${total}`;
  chapterQueueText.textContent = nextTitle
    ? `${head} · Next: ${nextTitle}`
    : `${head} · last one`;
}

function _startChapterQueue(chapters) {
  if (!chapters || chapters.length < 2) return;
  _chapterTotalCount = chapters.length;
  _chapterCurrentIndex = 1;
  const first = chapters[0];
  _chapterQueue = chapters.slice(1);
  _pendingChapterTitle = first.title;
  // Carry the first chapter's gitRef into _pendingGitRef so generate()'s
  // save callback pins it onto the clip. Subsequent chapters set their
  // own gitRef from _advanceChapterQueue.
  _pendingGitRef = first.gitRef || null;
  // v4.96 (#538 Phase 2): same idea for Scrivener — each queued
  // chapter carries its own scrivenerRef so Push to Scrivener works
  // on every clip from a multi-chapter import, not just the first.
  _pendingScrivenerRef = first.scrivenerRef || null;
  textEl.value = first.text;
  updateCounts();
  _hideChapterBanner();
  _updateChapterQueueUI();
  setStatus(
    `Chapter 1 of ${_chapterTotalCount} loaded. Click Generate — the rest will auto-continue.`
  );
}

// v161: post-queue failures banner. _silentQueueFailures persists the
// chapter objects across the queue's exit so the Retry button can
// re-run them; the banner element shows the chapter names and the
// Retry / Dismiss actions.
let _silentQueueFailures = [];
const silentQueueFailuresEl = $("silent-queue-failures");
const silentQueueFailuresCount = $("silent-queue-failures-count");
const silentQueueFailuresList = $("silent-queue-failures-list");
const silentQueueFailuresRetry = $("silent-queue-failures-retry");
const silentQueueFailuresLog = $("silent-queue-failures-log");
const silentQueueFailuresDismiss = $("silent-queue-failures-dismiss");

function _showSilentQueueFailuresBanner(failed) {
  if (!silentQueueFailuresEl) return;
  _silentQueueFailures = failed.slice();
  const n = failed.length;
  silentQueueFailuresCount.textContent =
    n === 1 ? "1 chapter" : `${n} chapters`;
  silentQueueFailuresList.innerHTML = "";
  for (const ch of failed) {
    const code = document.createElement("code");
    code.textContent = ch.title || "(untitled)";
    silentQueueFailuresList.appendChild(code);
  }
  silentQueueFailuresEl.hidden = false;
}
function _hideSilentQueueFailuresBanner() {
  if (!silentQueueFailuresEl) return;
  silentQueueFailuresEl.hidden = true;
  _silentQueueFailures = [];
}
if (silentQueueFailuresRetry) {
  silentQueueFailuresRetry.addEventListener("click", () => {
    if (!_silentQueueFailures.length) return;
    const retry = _silentQueueFailures.slice();
    _hideSilentQueueFailuresBanner();
    _startBackgroundChapterQueue(retry);
  });
}
if (silentQueueFailuresDismiss) {
  silentQueueFailuresDismiss.addEventListener(
    "click",
    _hideSilentQueueFailuresBanner,
  );
}
if (silentQueueFailuresLog) {
  // v177: one-click jump from "2 chapters failed" → debug log with
  // the per-chapter error context already captured.
  silentQueueFailuresLog.addEventListener("click", () => {
    if (typeof openDebugLog === "function") openDebugLog();
  });
}

// v162: persistent background queue + reorder + add-while-running.
//
// _chapterQueue (existing array) holds PENDING jobs only. _bgCurrent
// holds the job currently being synthesized (peeled off before
// processing so the queue is exclusively "what's next"). The worker
// is a simple while-loop fed from the front of the queue; when
// _chapterQueue gains items via _enqueueBg, the worker resumes (or
// restarts if it had drained) automatically.
//
// Each enqueued job snapshots its voice / rate / volume / speaker so
// the user can change the voice between queueings without
// retroactively affecting jobs already in the queue.
//
// Use case: "I'm reading article A; I find article B I'd rather get
// to first; I queue B at the top, drag B above A in the queue, and
// keep working." Or "queue 8 chapters then drag chapters 6-7 to
// the top because those are the ones I want to listen to tonight."

let _bgCurrent = null;       // job in flight, or null
let _bgRunning = false;      // worker loop active
let _bgOkCount = 0;          // saved successfully this run
let _bgFailures = [];        // accumulate persistent failures for the banner
// v169: elapsed-time clock for the current job. _bgCurrentStartedAt
// is set each time _bgRunWorker shifts a new job onto _bgCurrent;
// _bgCurrentTimerId polls every second so the queue panel can show
// a live "elapsed 0:45 · ~0:12 left" line on the in-flight row.
let _bgCurrentStartedAt = 0;
let _bgCurrentTimerId = null;
function _fmtMmSs(ms) {
  const total = Math.max(0, Math.round(ms / 1000));
  const m = Math.floor(total / 60);
  const s = total % 60;
  return `${m}:${String(s).padStart(2, "0")}`;
}
function _startBgCurrentTimer() {
  _stopBgCurrentTimer();
  _bgCurrentTimerId = setInterval(() => {
    // Cheap re-render: only the current row's meta needs to refresh
    // each second. Full panel rerender is fine — pending rows hash
    // by jobId, so the dragging session (if any) is untouched.
    _renderBgQueuePanel();
  }, 1000);
}
function _stopBgCurrentTimer() {
  if (_bgCurrentTimerId !== null) {
    clearInterval(_bgCurrentTimerId);
    _bgCurrentTimerId = null;
  }
}

function _bgJobFromUi(text, title) {
  const trimmed = (text || "").trim();
  return {
    id: `bgjob_${Date.now()}_${Math.floor(Math.random() * 1000)}`,
    title: (title || makeTitle(trimmed) || "(untitled)").trim(),
    text: trimmed,
    voiceId: voiceEl.value,
    voiceName: voiceEl.selectedOptions[0]?.textContent || voiceEl.value || "",
    rate: Number(rateEl.value),
    volume: Number(volumeEl.value) / 100,
    speakerId: speakerRow.hidden ? null : Number(speakerEl.value || 0),
  };
}

// Public-ish API: add one or many jobs to the background queue.
// Starts the worker if it isn't running yet. Captures the CURRENT
// voice settings into each job at enqueue time.
function _enqueueBg(jobsOrChapters) {
  const arr = Array.isArray(jobsOrChapters) ? jobsOrChapters : [jobsOrChapters];
  if (!arr.length) return;
  if (!voiceEl.value) {
    setStatus("Pick a voice before queueing silently.", true);
    return;
  }
  // v222 (#456): credential guard for the bg-queue path. Catches the
  // case where a chapter / picker file / re-narrate text happens to
  // be a bare credential. One confirm prompt per offender; cancel
  // skips that job (and only that job) — the rest of the batch still
  // queues. The foreground generate() path has its own guard above.
  const filtered = [];
  for (const j of arr) {
    const text = (j && j.text) ? String(j.text).trim() : "";
    if (_looksLikeCredential(text)) {
      const label = j.title ? `"${j.title}"` : "one of these chapters";
      if (!_confirmCredentialSynth(label)) {
        setStatus(
          `Skipped ${label} — looked like a credential.`,
          true,
        );
        continue;
      }
    }
    filtered.push(j);
  }
  if (!filtered.length) return;
  for (const j of filtered) {
    // Accept either a fully-built job OR a {title, text, ...chapter}
    // shape. Snapshot voice settings if missing.
    _chapterQueue.push({
      id: j.id || `bgjob_${Date.now()}_${Math.floor(Math.random() * 1000)}`,
      title: (j.title || makeTitle(j.text || "") || "(untitled)").trim(),
      text: (j.text || "").trim(),
      voiceId: j.voiceId || voiceEl.value,
      voiceName: j.voiceName || (voiceEl.selectedOptions[0]?.textContent || voiceEl.value || ""),
      rate: typeof j.rate === "number" ? j.rate : Number(rateEl.value),
      volume: typeof j.volume === "number" ? j.volume : Number(volumeEl.value) / 100,
      speakerId:
        j.speakerId !== undefined
          ? j.speakerId
          : speakerRow.hidden
          ? null
          : Number(speakerEl.value || 0),
      // v176: source provenance so the picker can flag "this file is
      // already in the queue" with a ✓ badge. gitRef carries repoUrl
      // + path; targetClipId, when set, tells _bgTrySynth/saveClip to
      // overwrite an existing clip instead of creating a new one (used
      // by the v176 "Re-narrate outdated" path).
      gitRef: j.gitRef || null,
      // v4.96 (#538 Phase 2): preserve Scrivener pin through the
      // bg-queue so multi-chapter Scrivener imports get Push to
      // Scrivener on every saved clip, not just the first.
      scrivenerRef: j.scrivenerRef || null,
      targetClipId: j.targetClipId || null,
    });
    // v220as: mark every re-narrate target as "queued" the moment it
    // enters the queue, so the library card shows a "Queued" badge
    // before the worker even reaches it.
    if (j.targetClipId) _bgMarkSyncing(j.targetClipId);
  }
  _hideSilentQueueFailuresBanner();
  _renderBgQueuePanel();
  _updateChapterQueueUI();
  if (!_bgRunning) _bgRunWorker();
}

// Try one job through the existing pre-synthesis pipeline.
// _preSynthesizeChapter takes a {title, text} object — pass through.
// It captures voice/rate/volume from the UI at synthesis time, so we
// briefly swap UI values to the job's snapshot before calling, then
// restore (the user might be changing settings mid-queue for the
// next item they're about to queue).
async function _bgTrySynth(job) {
  _preSynthChapter = null;
  // Snapshot the UI so we can restore after.
  const prev = {
    voice: voiceEl.value,
    rate: rateEl.value,
    volume: volumeEl.value,
    speaker: speakerEl.value,
  };
  // Best-effort: only swap if the values are actually different (avoids
  // dispatching a stream of change events when most queued items share
  // the user's current voice).
  let swapped = false;
  if (job.voiceId && job.voiceId !== voiceEl.value) {
    voiceEl.value = job.voiceId;
    swapped = true;
  }
  if (typeof job.rate === "number" && String(job.rate) !== rateEl.value) {
    rateEl.value = String(job.rate);
    swapped = true;
  }
  const volPct = String(Math.round((job.volume || 1) * 100));
  if (volPct !== volumeEl.value) {
    volumeEl.value = volPct;
    swapped = true;
  }
  if (job.speakerId !== null && job.speakerId !== undefined) {
    speakerEl.value = String(job.speakerId);
  }
  try {
    // v177: log the job's preflight state — voice, lengths, gitRef —
    // so a "chapter 2 keeps failing" report contains everything
    // needed to reproduce. Title + chars almost always pin the cause.
    // v225.tn33 (#509): fresh telemetry surface so the OK log can
    // see what _preSynthesizeChapter actually produced.
    _bgResetSynthTelemetry();
    // v225.tn35 (#511): compute a text-structure summary so a
    // transcript-pattern bug (Trump-speech repro: 14997 chars, 2
    // periods, 1 advertised sentence) is obvious at a glance.
    // Without this, you'd see chars=14997 in the start log and
    // sentencesAdvertised=1 in the OK log and have to mentally
    // connect them. With it, the start log says outright:
    //   sentenceMarks: 2, words: 2911, longestSentenceChars: 14945
    // which screams "transcript with no punctuation" on first read.
    const _jobText = job.text || "";
    const _jobWords = _jobText.split(/\s+/).filter(Boolean).length;
    const _jobMarks = (_jobText.match(/[.!?]/g) || []).length;
    const _jobCommas = (_jobText.match(/,/g) || []).length;
    // Pre-split locally with the same regex the server uses, so we
    // know how many sentences the SERVER will see before force-split
    // kicks in. _MAX_SENTENCE_CHARS on the server (500) gets
    // duplicated here intentionally — if it drifts, the metric still
    // diagnoses the pre-split shape, which is what matters for "did
    // the user paste a transcript".
    const _preSplitSentences = _jobText
      .split(/(?<=[.!?])\s+/)
      .map((s) => s.trim())
      .filter(Boolean);
    const _longestPreSplit = _preSplitSentences.reduce(
      (m, s) => (s.length > m ? s.length : m),
      0,
    );
    _dlog("bg-queue", `synth start: ${job.title}`, {
      chars: _jobText.length,
      voiceId: job.voiceId,
      rate: job.rate,
      volume: job.volume,
      speakerId: job.speakerId,
      targetClipId: job.targetClipId || null,
      gitRefPath: job.gitRef ? job.gitRef.path : null,
      // v225.tn33: textHead snippets the first ~80 chars so a tester
      // report with "this URL fails" is reproducible from the log
      // alone without round-tripping the source.
      textHead: (_jobText.trim().slice(0, 80) || "(empty)"),
      // v225.tn35 (#511): text-structure summary — answers "is this
      // a transcript-style input" before we even start synth.
      words: _jobWords,
      sentenceMarks: _jobMarks,                   // count of . ! ?
      commaCount: _jobCommas,
      sentencesPreSplit: _preSplitSentences.length,
      longestSentenceChars: _longestPreSplit,
      // Flag "transcript-shape" when there are very few sentence
      // marks per 1000 words. Mirrors the generate() pre-flight
      // heuristic; sets the keyword so a tester report can be
      // grepped/sorted by structural class.
      pattern:
        _jobWords >= 300 && (_jobMarks * 1000) / Math.max(1, _jobWords) < 10
          ? "transcript-low-punct"
          : (_longestPreSplit > 500 ? "long-sentence" : "normal"),
    });
    // v176: thread targetClipId + gitRef so the synth path can
    // overwrite an existing clip (Re-narrate outdated) instead of
    // creating a new one. Re-imports preserve title/notes/bookmarks
    // through saveClip below.
    // v220t: fromBgQueue tells _preSynthesizeChapter to skip the
    // end-of-chapter sleep check (that check only makes sense for
    // the foreground lookahead caller; for bg-queue it would kill
    // every job in the batch silently).
    await _preSynthesizeChapter(
      {
        title: job.title,
        text: job.text,
        targetClipId: job.targetClipId || null,
        gitRef: job.gitRef || null,
        scrivenerRef: job.scrivenerRef || null,
      },
      // v4.110: existingJobId reattaches to a running server job
      // (reattach-on-boot) instead of POSTing a new one.
      { fromBgQueue: true, existingJobId: job.existingJobId || null }
    );
  } catch (err) {
    _dlog("bg-queue", `synth threw: ${job.title}`, {
      errName: err && err.name,
      errMsg: err && err.message,
      stack: err && err.stack,
    });
    console.warn("[bg queue] synth threw:", job.title, err);
    if (swapped) {
      voiceEl.value = prev.voice;
      rateEl.value = prev.rate;
      volumeEl.value = prev.volume;
      speakerEl.value = prev.speaker;
    }
    return false;
  }
  if (swapped) {
    voiceEl.value = prev.voice;
    rateEl.value = prev.rate;
    volumeEl.value = prev.volume;
    speakerEl.value = prev.speaker;
  }
  const ok = !!(
    _preSynthChapter && _preSynthChapter.title === job.title
  );
  _preSynthChapter = null;
  return ok;
}

// v220ba: screen wake lock while the bg-queue is processing.
//
// Without this, phone sleep kills mid-flight synths: when the
// screen locks, iOS Safari + Android Chrome suspend the JS event
// loop and eventually drop the cellular radio for the tab. The SSE
// connection freezes, the v204 watchdog (paused via v216 while
// hidden) eventually catches it on resume, but the job has already
// FAILED. User saw exactly this:
//   16:46:54  synth start
//   16:47:25  SSE watchdog timeout — no bytes for 30s
//
// Wake Lock API keeps the screen on for the duration of the synth.
// Released when the queue drains. Re-acquired on visibilitychange
// because some browsers drop the lock when the tab loses focus
// (e.g. tapping notification center) and we want it back when the
// user returns.
//
// Feature-detected: older iOS Safari (< 16.4) and Firefox iOS don't
// have navigator.wakeLock at all — those users still need to keep
// the phone awake manually, but the warning status hint at least
// tells them why.
let _screenWakeLock = null; // WakeLockSentinel | null
let _screenWakeLockSupported =
  typeof navigator !== "undefined" &&
  navigator.wakeLock &&
  typeof navigator.wakeLock.request === "function";

async function _acquireScreenWakeLock() {
  if (!_screenWakeLockSupported) return false;
  if (_screenWakeLock) return true; // already held
  try {
    _screenWakeLock = await navigator.wakeLock.request("screen");
    _dlog("wake-lock", "acquired", { reason: "bg-queue running" });
    // Browser-initiated release (e.g. tab lost focus). Clear our
    // reference so the visibilitychange handler can re-acquire.
    _screenWakeLock.addEventListener("release", () => {
      _dlog("wake-lock", "released by browser");
      _screenWakeLock = null;
    });
    return true;
  } catch (e) {
    _dlog("wake-lock", "request failed", { err: String(e) });
    _screenWakeLock = null;
    return false;
  }
}

async function _releaseScreenWakeLock() {
  if (!_screenWakeLock) return;
  try {
    await _screenWakeLock.release();
    _dlog("wake-lock", "released by us");
  } catch {}
  _screenWakeLock = null;
}

// v225v4.9: opt-in "keep screen on while playing" for read-along
// listeners. Settings → "Keep screen on while playing" (Off / On).
// Off by default since the lock costs battery; users who want to
// follow the reading view as audio plays flip it on. Coexists with
// the bg-queue lock above — _screenWakeLock is a single sentinel,
// _acquireScreenWakeLock short-circuits when already held, and the
// player's release skips when _bgRunning to avoid dropping the lock
// the queue still needs.
let _keepScreenOnDuringPlayback = false;
function _readKeepScreenOnPref() {
  try {
    return (
      localStorage.getItem("narrative.keepScreenOnDuringPlayback") === "1"
    );
  } catch {
    return false;
  }
}
_keepScreenOnDuringPlayback = _readKeepScreenOnPref();

playerEl.addEventListener("play", () => {
  if (_keepScreenOnDuringPlayback) {
    _acquireScreenWakeLock().catch(() => {});
  }
});
function _maybeReleasePlaybackLock() {
  // Skip when the bg-queue still needs the lock — its own done-path
  // will release. This is the "don't drop the shared lock too early"
  // guard. Wake lock acquire is idempotent; release isn't.
  if (_keepScreenOnDuringPlayback && !_bgRunning) {
    _releaseScreenWakeLock().catch(() => {});
  }
}
playerEl.addEventListener("pause", _maybeReleasePlaybackLock);
playerEl.addEventListener("ended", _maybeReleasePlaybackLock);

// Re-acquire on tab focus IF the bg-queue is still running OR the
// user has the playback-keep-screen-on pref on and audio is
// currently playing. Without this, switching tabs once causes the
// lock to drop and the user has to navigate back to even get
// screen-on protection.
if (typeof document !== "undefined") {
  document.addEventListener("visibilitychange", () => {
    if (
      document.visibilityState !== "visible" ||
      !_screenWakeLockSupported ||
      _screenWakeLock
    ) {
      return;
    }
    const playerIsPlaying = !playerEl.paused && !playerEl.ended;
    if (
      _bgRunning ||
      (_keepScreenOnDuringPlayback && playerIsPlaying)
    ) {
      _acquireScreenWakeLock().catch(() => {});
    }
  });
}

// The worker. Pulls jobs off the front of _chapterQueue one at a
// time, runs them through _bgTrySynth with one auto-retry on
// failure, and continues until the queue drains or is cancelled.
// New items added via _enqueueBg while the worker is running just
// land at the queue's back and get processed when their turn comes.
async function _bgRunWorker() {
  if (_bgRunning) return;
  if (_chapterQueue.length === 0) return;
  _bgRunning = true;
  _silentChapterQueue = true;
  _chapterTotalCount = _chapterQueue.length;
  _chapterCurrentIndex = 0;
  _bgOkCount = 0;
  _bgFailures = [];
  _hideSilentQueueFailuresBanner();
  generateBtn.disabled = true;
  generateBtn.title = "Background queue is running — cancel it to generate manually.";
  _renderBgQueuePanel();
  // v220ba: grab the screen wake lock so phone sleep doesn't kill
  // the SSE connection mid-synth. Don't await — wake-lock failure
  // (unsupported browser, denied permission) shouldn't block the
  // queue from starting. Released in the cleanup block below.
  //
  // v221.tn10: only surface "Keeping screen on" / "Keep the screen
  // awake" messaging on touch-primary devices (phones, tablets).
  // Desktop browsers don't suspend windows the way phones lock, so
  // the wake-lock note is misleading noise there — tester reported
  // it appearing alongside the queue-start message in the hero
  // strip. The lock acquisition itself stays — it's harmless on
  // desktop, useful on mobile.
  const _lockAcquired = await _acquireScreenWakeLock();
  const _pluralItems = _chapterQueue.length === 1 ? "" : "s";
  const _baseMsg = `Background queue started — ${_chapterQueue.length} item${_pluralItems} pending.`;
  const _isTouchPrimary = matchMedia(
    "(hover: none), (pointer: coarse)"
  ).matches;
  const _queueStartMsg =
    _isTouchPrimary && _lockAcquired
      ? `${_baseMsg} 🔆 Keeping screen on.`
      : _isTouchPrimary && _screenWakeLockSupported
      ? `${_baseMsg} Keep the screen awake until it's done.`
      : _baseMsg;
  setStatus(_queueStartMsg);
  while (_chapterQueue.length > 0 && _silentChapterQueue) {
    _bgCurrent = _chapterQueue.shift();
    _chapterCurrentIndex += 1;
    _bgSynthCurrentTitle = _bgCurrent.title || "";
    _bgSynthSentence = 0;
    _bgSynthTotal = 0;
    // v169: record start time + run a 1s tick so the queue panel
    // shows live "elapsed 0:45" + ETA from sentence progress.
    _bgCurrentStartedAt = Date.now();
    _startBgCurrentTimer();
    // v220as: promote this clip from "Queued" to the actively-syncing
    // slot so the library card pulses on the right row.
    if (_bgCurrent.targetClipId) {
      _bgSetSyncingActive(_bgCurrent.targetClipId);
    }
    _updateChapterQueueUI();
    _renderBgQueuePanel();
    let success = await _bgTrySynth(_bgCurrent);
    if (!success && _silentChapterQueue) {
      _dlog("bg-queue", `RETRY ${_bgCurrent.title} after 1.5s`, {
        chars: (_bgCurrent.text || "").length,
        priorCursor: _bgSynthSentence,
      });
      console.warn(
        `[bg queue] retrying "${_bgCurrent.title}" after 1.5s…`
      );
      // v225v3.61 (#794): reset the sentence cursor before the retry.
      // _bgSynthSentence is the from=N value the resumable wrapper
      // passes when opening the /api/synth/jobs/{id}/stream. It's
      // meaningful ONLY within a single server-side job; across a
      // bg-queue retry we get a BRAND NEW job (POST /api/synth/jobs
      // returns a fresh id), and the new job's worker re-synthesizes
      // from sentence 0. If we leave the cursor at the failed
      // attempt's value (e.g. 197), the client's stream subscribe
      // filters out events 0..N-1 — which the new worker hasn't
      // produced yet — and the user sees no progress until the new
      // server reaches the prior cursor (minutes to hours).
      // Resetting to 0 lets the new job stream progress events
      // immediately. The previous attempt's partial audio is lost,
      // which is acceptable: it lived in the old job's memory buffer
      // and the wrapper's reconnect loop already gave up on it
      // before throwing through to here.
      _bgSynthSentence = 0;
      _bgSynthTotal = 0;
      // v4.110: if this was a reattach to a server job that turned out
      // to be gone (404 → first attempt failed), drop existingJobId so
      // the retry POSTs a FRESH job and re-synthesizes from scratch
      // rather than re-attaching to the same dead id.
      if (_bgCurrent) _bgCurrent.existingJobId = null;
      if (_silentChapterQueue) success = await _bgTrySynth(_bgCurrent);
    }
    if (success) {
      // v225.tn33 (#509): the OK log used to say "we didn't throw"
      // and nothing else — a partial stream that ended cleanly
      // logged success, leaving the tester with a 3-second clip
      // and no audit trail. Now we surface the per-synth telemetry
      // so a glance at the log answers "did real synthesis run":
      //   • charsPerSec > 800 = impossible for Piper on Fly CPU
      //     (a real bake is ~50-200/s). High value = early bailout.
      //   • truncated: true   = sentencesSeen < advertised. Server
      //     dropped the stream before all sentences were synthed.
      //   • durationSec near 0 or blobSize near 0 = no audio.
      // The "suspicious" flag is true when any of these red flags
      // hit — testers don't need to read details, just look for
      // OK lines tagged suspicious.
      const t = _bgLastSynth || {};
      const elapsedMs = (t.endMs || Date.now()) - (t.startMs || Date.now());
      const charsLen = (_bgCurrent.text || "").length;
      const suspicious =
        (t.charsPerSec != null && t.charsPerSec > 800) ||
        (t.truncated === true) ||
        (t.durationSec != null && t.durationSec < 2 && charsLen > 200) ||
        (t.blobSize != null && t.blobSize < 1024);
      _dlog("bg-queue", `OK ${_bgCurrent.title}${suspicious ? " ⚠ suspicious" : ""}`, {
        chars: charsLen,
        elapsedMs,
        charsPerSec: t.charsPerSec,
        sentencesSeen: t.sentencesSeen,
        sentencesAdvertised: t.sentencesAdvertised,
        truncated: t.truncated,
        durationSec: t.durationSec,
        blobSize: t.blobSize,
        suspicious,
      });
      // v225v4.101: if the just-synth'd clip is the one the user is
      // currently reading, re-load it so the reading-view spans + the
      // <audio> source swap to the new content. Without this, after a
      // Sync GitHub / Re-narrate-outdated / per-card 🔄, the IDB row
      // has new text + new audio but the on-screen reading view keeps
      // showing the old spans — the workaround was Clear + reload.
      // v220w made bg-queue "silent" (no auto-load) for re-narrates
      // when the user wasn't viewing the clip; that policy is right
      // for the library re-narrate-outdated batch case but wrong for
      // the foreground "I'm reading this and just hit Sync GitHub"
      // case. Gating on _currentClipId match preserves the silent
      // behavior for background queue items.
      // autoPlay:false because the user was reading; we shouldn't
      // surprise them by starting playback.
      if (_bgCurrent && _bgCurrent.targetClipId &&
          _bgCurrent.targetClipId === _currentClipId) {
        loadClip(_bgCurrent.targetClipId, { autoPlay: false }).catch((e) => {
          console.warn("[bg-queue] post-OK reload failed:", e);
        });
      }
      _bgOkCount += 1;
    } else if (_silentChapterQueue) {
      const t = _bgLastSynth || {};
      _dlog("bg-queue", `FAIL ${_bgCurrent.title} (both attempts)`, {
        chars: (_bgCurrent.text || "").length,
        gitRefPath: _bgCurrent.gitRef ? _bgCurrent.gitRef.path : null,
        // v225.tn33: same telemetry as OK so a FAIL report shows
        // whether the stream got partway before bailing.
        sentencesSeen: t.sentencesSeen,
        sentencesAdvertised: t.sentencesAdvertised,
      });
      _bgFailures.push(_bgCurrent);
    }
    // v220as: drop this clip from the syncing set whether it succeeded
    // or failed — either way, the bg-queue is no longer touching it.
    // The library card flips back to its normal state (clean if synth
    // succeeded → SHA updated; outdated badge stays put if it failed).
    if (_bgCurrent && _bgCurrent.targetClipId) {
      _bgUnmarkSyncing(_bgCurrent.targetClipId);
    }
    _bgCurrent = null;
    // v169: tear down the 1s tick when the job ends. If the worker
    // shifts another job on the next iteration, _startBgCurrentTimer
    // will restart it; otherwise the loop exits and the panel is hidden.
    _stopBgCurrentTimer();
    _renderBgQueuePanel();
  }
  const cancelled = !_silentChapterQueue;
  _silentChapterQueue = false;
  _bgRunning = false;
  _chapterTotalCount = 0;
  _chapterCurrentIndex = 0;
  _preSynthChapter = null;
  _bgSynthCurrentTitle = "";
  _bgSynthSentence = 0;
  _bgSynthTotal = 0;
  // v220as: cancellation path — anything still in the syncing set
  // (queued items the worker never got to) needs to clear too so the
  // cards stop showing "Queued" forever. Iterate over a snapshot
  // because _bgUnmarkSyncing mutates the set.
  for (const id of Array.from(_bgSyncingClipIds)) {
    _bgUnmarkSyncing(id);
  }
  _bgSyncingActiveClipId = null;
  // v220ba: release the screen wake lock now that the queue is done.
  // Don't await — release is fire-and-forget; nothing downstream
  // depends on it completing before status messages fire.
  _releaseScreenWakeLock().catch(() => {});
  generateBtn.disabled = false;
  generateBtn.title = "";
  _updateChapterQueueUI();
  _renderBgQueuePanel();
  if (cancelled) {
    setStatus(`Background queue cancelled — ${_bgOkCount} saved.`);
  } else if (_bgFailures.length > 0) {
    _showSilentQueueFailuresBanner(_bgFailures);
    setStatus(
      `Background queue done — ${_bgOkCount} saved, ${_bgFailures.length} need a retry.`,
      false
    );
  } else if (_bgOkCount > 0) {
    setStatus(`Background queue done — ${_bgOkCount} chapter${_bgOkCount === 1 ? "" : "s"} in your library.`);
  }
}

// v139 compat: keeps the existing import-picker callers
// (_startBackgroundChapterQueue) working — they just enqueue and
// trust the worker to run.
async function _startBackgroundChapterQueue(chapters) {
  if (!chapters || chapters.length === 0) return;
  _enqueueBg(chapters);
}

// v162: render the queue panel — current job (if any) + the pending
// list. Idempotent; safe to call from anywhere the queue state
// changes (enqueue, dequeue, reorder, remove, cancel).
const bgQueuePanel = $("bg-queue-panel");
const bgQueueCurrent = $("bg-queue-current");
const bgQueuePending = $("bg-queue-pending");
const bgQueueFooter = $("bg-queue-footer");
function _renderBgQueuePanel() {
  if (!bgQueuePanel) return;
  const hasCurrent = !!_bgCurrent;
  const pendingCount = _chapterQueue.length;
  bgQueuePanel.hidden = !hasCurrent && pendingCount === 0;
  if (hasCurrent) {
    bgQueueCurrent.hidden = false;
    bgQueueCurrent.innerHTML = "";
    const title = document.createElement("span");
    title.className = "bg-queue-title";
    title.textContent = _bgCurrent.title || "(untitled)";
    const meta = document.createElement("span");
    meta.className = "bg-queue-meta";
    // v169: live elapsed + ETA. ETA is derived from sentence-rate
    // (elapsed / sentences_done * sentences_remaining), so it only
    // shows up once at least a few sentences have completed — early
    // estimates from "0 sentences done" would be infinite or wildly
    // off and read as confusing noise.
    const parts = [];
    if (_bgSynthTotal > 0) {
      parts.push(`${_bgSynthSentence}/${_bgSynthTotal} sentences`);
    } else {
      parts.push("synthesizing…");
    }
    const elapsedMs = _bgCurrentStartedAt > 0 ? Date.now() - _bgCurrentStartedAt : 0;
    parts.push(`elapsed ${_fmtMmSs(elapsedMs)}`);
    if (
      _bgSynthSentence >= 5 &&
      _bgSynthTotal > _bgSynthSentence &&
      elapsedMs > 1000
    ) {
      const perSent = elapsedMs / _bgSynthSentence;
      const remaining = (_bgSynthTotal - _bgSynthSentence) * perSent;
      parts.push(`~${_fmtMmSs(remaining)} left`);
    }
    meta.textContent = parts.join(" · ");
    bgQueueCurrent.append(title, meta);
  } else {
    bgQueueCurrent.hidden = true;
    bgQueueCurrent.innerHTML = "";
  }
  bgQueuePending.innerHTML = "";
  for (let i = 0; i < _chapterQueue.length; i++) {
    const job = _chapterQueue[i];
    const row = document.createElement("div");
    row.className = "bg-queue-item";
    row.dataset.jobId = job.id;
    const drag = document.createElement("span");
    drag.className = "bg-queue-drag";
    drag.setAttribute("aria-label", "Drag to reorder");
    drag.title = "Drag to reorder";
    drag.textContent = "⋮⋮";
    _attachBgDragHandle(drag, row);
    const title = document.createElement("span");
    title.className = "bg-queue-title";
    title.textContent = job.title || "(untitled)";
    const meta = document.createElement("span");
    meta.className = "bg-queue-meta";
    const words = Math.max(1, Math.round((job.text || "").length / 5));
    const mins = Math.max(1, Math.round(words / 180));
    meta.textContent = `~${mins} min`;
    const remove = document.createElement("button");
    remove.type = "button";
    remove.className = "bg-queue-remove";
    remove.setAttribute("aria-label", "Remove from queue");
    remove.title = "Remove from queue";
    remove.textContent = "×";
    remove.addEventListener("click", (e) => {
      e.stopPropagation();
      const idx = _chapterQueue.findIndex((j) => j.id === job.id);
      if (idx >= 0) {
        _chapterQueue.splice(idx, 1);
        _renderBgQueuePanel();
        _updateChapterQueueUI();
      }
    });
    row.append(drag, title, meta, remove);
    bgQueuePending.appendChild(row);
  }
  // v163 / v176: recent-repos shortcut row at the bottom of the
  // queue panel. v163 showed a single "+ Add more from owner/repo"
  // link for the most recent. v176 surfaces up to RECENT_REPOS_MAX
  // (5) past repos as chips so a user juggling multiple book projects
  // can flip between them without re-pasting URLs.
  if (bgQueueFooter) {
    const recents = _getRecentGithubRepos();
    if (recents.length > 0) {
      bgQueueFooter.hidden = false;
      bgQueueFooter.innerHTML = "";
      // Section label so the chip row reads as deliberate UI, not
      // mystery buttons hanging off the queue.
      const label = document.createElement("span");
      label.className = "bg-queue-recents-label";
      label.textContent =
        recents.length === 1 ? "Recent repo:" : "Recent repos:";
      bgQueueFooter.appendChild(label);
      const chipRow = document.createElement("div");
      chipRow.className = "bg-queue-recents-chips";
      for (const r of recents) {
        const chip = document.createElement("button");
        chip.type = "button";
        chip.className = "bg-queue-recent-chip";
        chip.title = `Re-open the GitHub picker for ${r.owner}/${r.repo}`;
        chip.textContent = `${r.owner}/${r.repo}`;
        chip.addEventListener("click", () => {
          // Defer to openGithubBrowser so the chip flows through the
          // same picker / background-mode path as a fresh Import →
          // GitHub. _pushRecentGithubRepo on the fetch will bubble
          // this entry back to the front of the list.
          openGithubBrowser(r.url);
        });
        chipRow.appendChild(chip);
      }
      bgQueueFooter.appendChild(chipRow);
    } else {
      bgQueueFooter.hidden = true;
      bgQueueFooter.innerHTML = "";
    }
  }
}

// Drag-to-reorder for pending queue rows. Mirrors the library card
// drag pattern (Pointer Events + visual translateY + midpoint-based
// insertion math), just scoped to .bg-queue-pending.
let _bgDragSession = null;
function _attachBgDragHandle(handle, rowEl) {
  handle.addEventListener("pointerdown", (e) => {
    if (e.button !== 0 && e.button !== undefined && e.pointerType === "mouse") {
      return;
    }
    e.preventDefault();
    try { handle.setPointerCapture(e.pointerId); } catch {}
    _bgDragSession = {
      rowEl,
      pointerId: e.pointerId,
      startY: e.clientY,
      jobId: rowEl.dataset.jobId,
    };
    rowEl.classList.add("dragging");
    handle.addEventListener("pointermove", _onBgDragMove);
    handle.addEventListener("pointerup", _onBgDragEnd);
    handle.addEventListener("pointercancel", _onBgDragEnd);
  });
}
function _onBgDragMove(e) {
  if (!_bgDragSession || e.pointerId !== _bgDragSession.pointerId) return;
  e.preventDefault();
  const dy = e.clientY - _bgDragSession.startY;
  _bgDragSession.rowEl.style.transform = `translateY(${dy}px)`;
}
function _onBgDragEnd(e) {
  if (!_bgDragSession || e.pointerId !== _bgDragSession.pointerId) return;
  const { rowEl, jobId } = _bgDragSession;
  const handle = e.currentTarget;
  try { handle.releasePointerCapture(e.pointerId); } catch {}
  handle.removeEventListener("pointermove", _onBgDragMove);
  handle.removeEventListener("pointerup", _onBgDragEnd);
  handle.removeEventListener("pointercancel", _onBgDragEnd);
  const draggedRect = rowEl.getBoundingClientRect();
  const draggedMid = draggedRect.top + draggedRect.height / 2;
  rowEl.style.transform = "";
  rowEl.classList.remove("dragging");
  _bgDragSession = null;
  const siblings = Array.from(bgQueuePending.children).filter(
    (c) => c !== rowEl
  );
  let insertIdx = siblings.length;
  for (let i = 0; i < siblings.length; i++) {
    const r = siblings[i].getBoundingClientRect();
    if (draggedMid < r.top + r.height / 2) {
      insertIdx = i;
      break;
    }
  }
  const fromIdx = _chapterQueue.findIndex((j) => j.id === jobId);
  if (fromIdx === -1) return;
  const [job] = _chapterQueue.splice(fromIdx, 1);
  _chapterQueue.splice(insertIdx, 0, job);
  _renderBgQueuePanel();
  _updateChapterQueueUI();
}

// "Queue silently" button — captures the current textarea as a job
// and clears the textarea so the next paste starts fresh.
const queueSilentlyBtn = $("queue-silently");
if (queueSilentlyBtn) {
  queueSilentlyBtn.addEventListener("click", () => {
    const text = (textEl.value || "").trim();
    if (!text) {
      setStatus("Type or paste some text first to queue it.", true);
      textEl.focus();
      return;
    }
    if (!voiceEl.value) {
      setStatus("Pick a voice before queueing silently.", true);
      return;
    }
    const title = _pendingChapterTitle || makeTitle(text);
    _enqueueBg([{ title, text }]);
    textEl.value = "";
    updateCounts();
    _pendingChapterTitle = null;
    _hideChapterBanner();
    setStatus(
      `Queued "${title}" silently — ${_chapterQueue.length} in the queue.`
    );
    if (typeof _updateEmptyState === "function") _updateEmptyState();
  });
}

// Called from generate()'s save path. If there are more chapters waiting,
// load the next, set its pending title, and re-fire generate(). Returns
// true when it advanced (caller can suppress "ready to Play" UI), false
// when the queue is drained / not active.
function _advanceChapterQueue() {
  if (_chapterTotalCount <= 0) return false;
  if (_chapterQueue.length === 0) {
    // Last chapter just finished. Wipe state.
    const done = _chapterTotalCount;
    _chapterTotalCount = 0;
    _chapterCurrentIndex = 0;
    _pendingChapterTitle = null;
    _abortPreSynth();
    _updateChapterQueueUI();
    setStatus(`All ${done} chapters synthesized.`);
    return false;
  }
  const next = _chapterQueue.shift();
  _chapterCurrentIndex += 1;
  _pendingChapterTitle = next.title;
  _pendingGitRef = next.gitRef || null;
  // v4.96 (#538 Phase 2): carry next chapter's Scrivener pin too.
  _pendingScrivenerRef = next.scrivenerRef || null;
  _updateChapterQueueUI();

  // Fast path: chapter was pre-synthesized in the background while the
  // user listened to the previous one. Load it instantly from the
  // library and immediately kick off pre-synth for the chapter AFTER
  // this one so the chain continues. Save was done during pre-synth, so
  // mark the queue's save flag complete now (no generate() callback
  // will fire for this chapter).
  if (_preSynthChapter && _preSynthChapter.title === next.title) {
    const clipId = _preSynthChapter.clipId;
    _preSynthChapter = null;
    _pendingChapterTitle = null;
    _queueSaveComplete = true;
    setTimeout(() => loadClip(clipId), 50);
    if (_chapterQueue.length > 0) {
      _preSynthesizeChapter(_chapterQueue[0]);
    }
    return true;
  }

  // Slow path: pre-synth wasn't ready (first chapter, or a regen
  // interrupted the chain). Fall back to inline synthesis.
  textEl.value = next.text;
  updateCounts();
  // Defer so library re-render / save side effects from the previous
  // chapter complete before the next synthesis starts.
  setTimeout(() => generate(), 150);
  return true;
}

// Headless background synthesis of a queued chapter. Collects the SSE
// stream events into a buffer (no reading-view / player updates) and
// saves the result to IndexedDB as a regular clip. Sets _preSynthChapter
// when the result is ready; _advanceChapterQueue picks it up from there.
// v226 / #512: thin wrapper around the new server-side jobs API
// (synth_jobs.py). Drop-in replacement for the original
// fetch("/api/synthesize/stream") call — returns a Response whose
// body is a ReadableStream that internally pipes bytes from the
// job's SSE stream. On a network error or premature stream-end
// while the job is still running, the wrapper transparently
// reopens the stream with `?from=N` (using _bgSynthSentence as the
// cursor — the downstream reader keeps it up to date). The caller
// sees one uninterrupted stream of SSE events.
//
// Why this exists: a 28-minute synth that died at 177/198 sentences
// because Fly's load balancer dropped the SSE. The old endpoint ran
// synth IN the request handler, so a dropped connection killed the
// synth. The new endpoint detaches the synth into a background
// asyncio task — a dropped client just means the next reconnect
// replays whatever's buffered + live-streams the rest.
async function _openSynthJobStream(payload, externalController, opts) {
  // v4.110: reattach path. When opts.existingJobId is given we
  // skip POST /api/synth/jobs and attach the resumable read loop to a
  // job that's ALREADY running on the server (e.g. after a page reload
  // mid-synthesis — see _reattachActiveSynthJobs). The server still has
  // every sentence buffered, so opening the stream from=0 replays them
  // fast and then live-streams the tail. Everything downstream (reader
  // loop, stitch, save) is identical to a freshly-created job.
  let jobId = (opts && opts.existingJobId) || null;
  if (!jobId) {
    // v4.90: strip configured pre-synth symbols from the payload's text
    // fields. Done here (not at each caller) so ALL bg-queue paths — manual
    // generate, per-card 🔄, chapter queue, library re-narrate — pick up the
    // strip without per-call wiring. Mutates a shallow clone so the caller's
    // payload (which may be re-used in retry logic) keeps the raw text.
    const _stripped = { ...payload };
    if (typeof _stripped.text === "string") {
      _stripped.text = _stripSynthChars(_stripped.text);
    }
    if (Array.isArray(_stripped.segments)) {
      _stripped.segments = _stripped.segments.map((s) => ({
        ...s,
        text: typeof s.text === "string" ? _stripSynthChars(s.text) : s.text,
      }));
    }
    const createRes = await fetch("/api/synth/jobs", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(_stripped),
      signal: externalController.signal,
    });
    if (!createRes.ok) {
      // Mimic the original fetch behavior — return the failed
      // response so the caller's `if (!res.ok)` branch handles it.
      return createRes;
    }
    try {
      const cbody = await createRes.json();
      jobId = cbody.job_id;
    } catch {}
    if (!jobId) {
      return new Response(
        JSON.stringify({ error: "no job_id from server" }),
        { status: 502, headers: { "Content-Type": "application/json" } },
      );
    }
    _dlog("synth", "resumable job created", { jobId });
  } else {
    _dlog("synth", "resumable: reattaching to existing job", { jobId });
  }

  // Resumable byte stream. The downstream code processes SSE events
  // out of this stream as if it were a single connection. The
  // controller pushes bytes from one inner fetch at a time; when an
  // inner fetch ends or errors, we check the job's status, and
  // either close (terminal) or reopen with from=_bgSynthSentence.
  let reconnects = 0;
  const MAX_RECONNECTS = 8;
  const stream = new ReadableStream({
    async start(controller) {
      while (true) {
        if (externalController.signal.aborted) {
          controller.close();
          return;
        }
        const fromIdx = typeof _bgSynthSentence === "number" ? _bgSynthSentence : 0;
        let innerOk = false;
        try {
          const res = await fetch(
            `/api/synth/jobs/${jobId}/stream?from=${fromIdx}`,
            { signal: externalController.signal },
          );
          if (!res.ok) {
            controller.error(new Error(`HTTP ${res.status}`));
            return;
          }
          const reader = res.body.getReader();
          innerOk = true;
          while (true) {
            const { done, value } = await reader.read();
            if (done) break;
            controller.enqueue(value);
          }
        } catch (err) {
          if (externalController.signal.aborted) {
            controller.close();
            return;
          }
          reconnects++;
          _dlog("synth", "resumable: inner stream error, will check status", {
            jobId,
            fromIdx,
            reconnects,
            errName: err && err.name,
            errMsg: err && err.message,
          });
          if (reconnects > MAX_RECONNECTS) {
            controller.error(err);
            return;
          }
          // brief pause before status check + reopen
          await new Promise((r) => setTimeout(r, 1500));
        }
        // Either the inner stream ended cleanly (done=true) or we
        // hit a network error and are about to retry. Check job
        // status to decide: terminal → close, running → reopen.
        try {
          const statusRes = await fetch(`/api/synth/jobs/${jobId}`, {
            signal: externalController.signal,
          });
          if (statusRes.ok) {
            const status = await statusRes.json();
            if (
              status.status === "done"
              || status.status === "failed"
              || status.status === "cancelled"
            ) {
              // Terminal. If clean-done the result event already
              // came through; controller can close.
              _dlog("synth", "resumable: job terminal, closing stream", {
                jobId,
                jobStatus: status.status,
                sentencesDone: status.sentences_done,
              });
              controller.close();
              return;
            }
            // Still running — reopen on next loop iteration.
            if (innerOk) {
              _dlog("synth", "resumable: stream ended but job running, reconnecting", {
                jobId,
                fromIdx,
                sentencesDone: status.sentences_done,
              });
              reconnects++;
              if (reconnects > MAX_RECONNECTS) {
                controller.error(new Error("reconnect budget exhausted"));
                return;
              }
            }
          } else if (statusRes.status === 404) {
            // v4.110: the job is GONE (server restarted / evicted it).
            // Retrying the stream would just hit another 404 and burn
            // the reconnect budget — and with a backgrounded tab the
            // pill can sit frozen meanwhile. Close cleanly instead: the
            // reader loop in _preSynthesizeChapter ends, _bgTrySynth
            // returns false, and the existing retry-once POSTs a fresh
            // job. Converges in O(1) rather than draining MAX_RECONNECTS.
            _dlog("synth", "resumable: job 404 — server restarted, closing for fresh retry", {
              jobId,
              statusCode: statusRes.status,
            });
            controller.close();
            return;
          } else {
            // Status check failed but we're not aborting — try to
            // reopen the stream anyway.
            _dlog("synth", "resumable: status check failed, retrying", {
              jobId,
              statusCode: statusRes.status,
            });
          }
        } catch (err) {
          if (externalController.signal.aborted) {
            controller.close();
            return;
          }
          // Status check itself errored. Treat as a normal retry.
          _dlog("synth", "resumable: status check threw, retrying", {
            jobId,
            errMsg: err && err.message,
          });
        }
      }
    },
    cancel() {
      // Caller aborted the response. Tell the server to cancel the
      // job since we no longer care about its output. Best-effort.
      try {
        fetch(`/api/synth/jobs/${jobId}`, { method: "DELETE" }).catch(() => {});
      } catch {}
    },
  });

  return new Response(stream, {
    status: 200,
    headers: { "Content-Type": "text/event-stream" },
  });
}

// v225v4.22 (#811 B.7): Phase B partial re-narrate helper.
// Drives /api/synth/jobs with cache targets for a single sentence,
// polls until done, then calls /restitch to rebuild the combined MP3
// from the cache. Returns { blob, offsetsMs, sha256, durationMs } on
// success or null on any failure (caller falls through to splice.py).
//
// Throws on unexpected non-recoverable errors (e.g. network failure
// after the cache was already updated). The caller catches and falls
// back.
//
// Why this path exists vs splice.py: splice.py decodes the existing
// MP3, atrims a hole, concats the new sentence PCM, re-encodes.
// That produces an audible faint crossfade at the cut point on some
// material. The restitch path concats CLEAN per-sentence FLAC blobs
// from the cache — no cut, no seam, indistinguishable from a fresh
// full re-narrate. Validated end-to-end in #824 (v4.21 spike).
async function _phaseBPartialRenarrate({
  clipId,
  lineId,
  text,
  voiceId,
  speakerId,
  rate,
  expectedOffsetCount,
}) {
  if (!clipId || !lineId || !text) return null;

  // 1. Kick off a single-sentence synth job that writes one cache row.
  const jobPayload = {
    text: text,
    voice_id: voiceId,
    speaker_id: speakerId,
    rate: rate,
    target_clip_id: clipId,
    target_line_ids: [lineId],
  };
  const createRes = await fetch("/api/synth/jobs", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(jobPayload),
  });
  if (!createRes.ok) {
    let body = "";
    try { body = await createRes.text(); } catch {}
    throw new Error(
      `phaseB synth job create failed (${createRes.status}): ${body.slice(0, 200)}`
    );
  }
  const created = await createRes.json();
  const jobId = created && created.job_id;
  if (!jobId) throw new Error("phaseB synth job: no job_id in response");

  // 2. Poll status. Single sentence: usually finishes in a few seconds
  // (Piper) up to ~60s (Kokoro on Fly CPU). Cap at 5 minutes to avoid
  // hanging the UI if synth wedges.
  const deadline = Date.now() + 5 * 60 * 1000;
  let pollInterval = 800;
  while (true) {
    if (Date.now() > deadline) {
      // Best-effort cancel the wedged job so it doesn't keep eating
      // resources after we give up on it.
      try {
        fetch(`/api/synth/jobs/${jobId}`, { method: "DELETE" }).catch(() => {});
      } catch {}
      throw new Error("phaseB synth timed out after 5 minutes");
    }
    const sRes = await fetch(`/api/synth/jobs/${jobId}`);
    if (!sRes.ok) {
      throw new Error(`phaseB synth status check failed: ${sRes.status}`);
    }
    const snap = await sRes.json();
    if (snap.status === "done") break;
    if (snap.status === "failed" || snap.status === "cancelled") {
      throw new Error(
        `phaseB synth job ${snap.status}: ${snap.error || "(no detail)"}`
      );
    }
    await new Promise((r) => setTimeout(r, pollInterval));
    // Modest backoff — first poll quickly, then ease off if synth is
    // taking longer than expected.
    if (pollInterval < 2000) pollInterval = Math.min(pollInterval + 200, 2000);
  }

  // 3. Restitch from cache. Returns the new audio_sha256 + offsets.
  // A 409 here means the clip has lines without cache rows for one
  // or more sentences (Phase B not fully populated). That's exactly
  // the case where we want to fall through to splice.py.
  const rsRes = await fetch(
    `/api/library/clips/${encodeURIComponent(clipId)}/restitch`,
    { method: "POST", headers: { "Content-Type": "application/json" }, body: "" }
  );
  if (rsRes.status === 409) {
    // Cache incomplete. Return null so the caller falls through to
    // splice.py. The synth job we just ran did populate THIS one
    // sentence's cache, so the user gets incremental progress toward
    // a fully cached clip — next time they edit, the gap is smaller.
    return null;
  }
  if (!rsRes.ok) {
    let body = "";
    try { body = await rsRes.text(); } catch {}
    throw new Error(`restitch failed (${rsRes.status}): ${body.slice(0, 200)}`);
  }
  const rs = await rsRes.json();
  const sha = rs && rs.audio_sha256;
  const offsetsMs = rs && Array.isArray(rs.sentence_offsets_ms)
    ? rs.sentence_offsets_ms
    : null;
  const durationMs =
    rs && typeof rs.duration_sec === "number"
      ? Math.round(rs.duration_sec * 1000)
      : null;
  if (!sha || !offsetsMs) {
    throw new Error("restitch returned no audio_sha256 / offsets");
  }
  if (
    typeof expectedOffsetCount === "number" &&
    offsetsMs.length !== expectedOffsetCount
  ) {
    // Sentence count drift — engine split text differently than client.
    // Shouldn't happen on a single-sentence edit because lines_json
    // didn't change, but guard so we don't corrupt the player state.
    throw new Error(
      `restitch offset count ${offsetsMs.length} != expected ${expectedOffsetCount}`
    );
  }

  // 4. Download the new combined MP3.
  const audioRes = await fetch(
    `/api/library/audio/${encodeURIComponent(sha)}.mp3`
  );
  if (!audioRes.ok) {
    throw new Error(`audio download failed: ${audioRes.status}`);
  }
  const blob = await audioRes.blob();
  if (!blob || blob.size === 0) {
    throw new Error("audio download returned empty blob");
  }

  return { blob, offsetsMs, sha256: sha, durationMs };
}


// v4.110: on boot, reattach to a background synthesis job that's still
// running on the server (e.g. the user reloaded mid-synthesis). The job
// keeps running server-side in a detached task; without this the client
// forgets it and the work never lands as a clip. We feed a reattach job
// through the normal bg-queue worker with `existingJobId` so it shares
// the exact same read/stitch/save path. Deferred so the app's normal
// boot (which prompts for the API key if needed) runs first; bails
// silently on any error so it's never intrusive.
async function _reattachActiveSynthJobs() {
  try {
    if (_bgRunning) return;  // a queue is already driving synthesis
    const res = await fetch("/api/synth/jobs?active=1");
    if (!res.ok) return;
    const { jobs } = await res.json();
    const active = (jobs || []).filter(
      (j) => j && (j.status === "running" || j.status === "pending"),
    );
    // Only auto-reattach when there's exactly one — driving multiple
    // concurrent saves from boot is risky and rare. Jobs are already
    // tenant-scoped server-side, so this one is ours.
    if (active.length !== 1) {
      if (active.length > 1) {
        _dlog("synth", "boot: multiple active jobs, skipping auto-reattach", {
          count: active.length,
        });
      }
      return;
    }
    const snap = active[0];
    // Pull the detail (full text + params) so we can label + save the
    // clip without the original in-memory chapter.
    const dres = await fetch(`/api/synth/jobs/${snap.id}?detail=1`);
    if (!dres.ok) return;
    const d = await dres.json();
    if (!d.text) return;  // can't reconstruct the clip without its text
    _dlog("synth", "boot: reattaching to active synth job", {
      jobId: snap.id,
      title: d.title,
      done: snap.sentences_done,
      total: snap.sentences_total,
    });
    _chapterQueue.push({
      title: d.title || "Resuming…",
      text: d.text,
      targetClipId: d.target_clip_id || null,
      voiceId: d.voice_id || null,
      rate: typeof d.rate === "number" ? d.rate : null,
      volume: typeof d.volume === "number" ? d.volume : 1,
      speakerId: d.speaker_id != null ? d.speaker_id : null,
      existingJobId: snap.id,
    });
    if (typeof setStatus === "function") {
      setStatus(`Resuming background synthesis: ${d.title || "in progress"}…`);
    }
    _bgRunWorker();
  } catch (err) {
    _dlog && _dlog("synth", "boot: reattach probe failed (ignored)", {
      err: String(err && err.message || err),
    });
  }
}
// Defer so the normal boot (voice list, library, any key prompt) settles
// first; only acts if a job is genuinely still running server-side.
if (typeof window !== "undefined") {
  setTimeout(() => { try { _reattachActiveSynthJobs(); } catch {} }, 2500);
}


async function _preSynthesizeChapter(chapter, opts) {
  // v220t: bg-queue (silent batch import) shares this function with the
  // foreground lookahead caller. The end-of-chapter sleep check was a
  // foreground-lookahead optimization ("don't pre-synth N+1 if we're
  // stopping at N") — applying it to a user-triggered bg-queue batch is
  // a bug: every job in the queue fails silently if the user had
  // end-of-chapter sleep armed at any point. Caller passes
  // `fromBgQueue: true` to bypass.
  const fromBgQueue = !!(opts && opts.fromBgQueue);
  if (_sleepEndOfChapter && !fromBgQueue) {
    _dlog("synth", "pre-synth skipped: end-of-chapter sleep armed", {
      title: chapter && chapter.title,
    });
    return;
  }
  // Abort any in-flight pre-synth — we only ever look ahead one chapter.
  _abortPreSynth();
  _preSynthController = new AbortController();
  const myController = _preSynthController;
  const voiceId = voiceEl.value;
  if (!voiceId || !chapter || !chapter.text) {
    // v220t: log this — bg-queue otherwise sees a silent "no result"
    // and can't tell whether the voice picker got cleared or whether
    // the queue item itself was empty.
    _dlog("synth", "pre-synth bailed: missing voice/text", {
      title: chapter && chapter.title,
      hasVoice: !!voiceId,
      hasChapter: !!chapter,
      chars: (chapter && chapter.text || "").length,
    });
    _preSynthController = null;
    return;
  }
  const rate = Number(rateEl.value);
  const volume = Number(volumeEl.value) / 100;
  const speakerId = speakerRow.hidden ? null : Number(speakerEl.value || 0);
  const voiceName = voiceEl.selectedOptions[0]?.textContent || voiceEl.value || "";

  // v225v4.22 (#811 B.6): if this synth targets an existing Phase A
  // opted-in clip (clip.lines is populated), pass the cache targets so
  // the worker writes each sentence WAV to the per-sentence cache as
  // it's yielded. This is what unlocks B.7's clean partial re-narrate
  // path (synth+restitch instead of splice.py PCM cut). Fetched
  // synchronously here so we don't have to thread async lookups into
  // the payload-building below.
  let phaseB_targetClipId = null;
  let phaseB_targetLineIds = null;
  if (chapter.targetClipId) {
    try {
      const existing = await getClip(chapter.targetClipId);
      if (
        existing &&
        Array.isArray(existing.lines) &&
        existing.lines.length > 0
      ) {
        const ids = existing.lines
          .map((l) => l && l.id)
          .filter((id) => typeof id === "string" && id.length > 0);
        if (ids.length === existing.lines.length) {
          phaseB_targetClipId = chapter.targetClipId;
          phaseB_targetLineIds = ids;
          _dlog("synth", "Phase B cache write enabled", {
            clipId: chapter.targetClipId,
            lineCount: ids.length,
          });
        } else {
          _dlog("synth", "Phase B cache write skipped: malformed lines", {
            clipId: chapter.targetClipId,
            linesLen: existing.lines.length,
            validIds: ids.length,
          });
        }
      }
    } catch (e) {
      // If we can't read the existing clip for any reason, skip cache
      // targeting — falls back to the existing path which still works.
      _dlog("synth", "Phase B cache lookup failed, continuing without it", {
        clipId: chapter.targetClipId,
        errMsg: e && e.message,
      });
    }
  }

  try {
    // v226 / #512: route through the new resumable-jobs wrapper
    // instead of /api/synthesize/stream directly. The wrapper
    // creates a server-side job (synth runs in a detached asyncio
    // task), then opens an SSE stream that transparently reconnects
    // on network drop using _bgSynthSentence as the resume cursor.
    // Caller code below is unchanged — it just gets a Response
    // whose body never quits mid-synth.
    const _payload = {
      text: chapter.text,
      voice_id: voiceId,
      rate,
      volume,
      speaker_id: speakerId,
      // v4.110: carry the title so a boot-time reattach can label the
      // pill + save the clip without the original in-memory chapter.
      title: chapter.title || null,
    };
    if (phaseB_targetClipId && phaseB_targetLineIds) {
      _payload.target_clip_id = phaseB_targetClipId;
      _payload.target_line_ids = phaseB_targetLineIds;
    }
    // v4.110: opts.existingJobId → attach to a running server job
    // instead of POSTing a new one (reattach-on-boot path).
    const res = await _openSynthJobStream(_payload, myController, {
      existingJobId: (opts && opts.existingJobId) || null,
    });
    if (!res.ok) {
      // v177: capture the response body — synthesis errors often
      // include the actual reason (voice not found, OOM, etc.) in
      // the JSON detail. Clone so the read here doesn't block the
      // synth path's own reader.
      let body = "";
      try { body = await res.clone().text(); } catch {}
      _dlog("synth", `HTTP ${res.status} for chapter`, {
        status: res.status,
        title: chapter.title,
        chars: (chapter.text || "").length,
        body: body.slice(0, 500),
      });
      throw new Error(`HTTP ${res.status}`);
    }
    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buf = "";
    let combinedMp3 = null;
    let sentenceOffsetsMs = [];
    // v221.sync-4: reset per-attempt. Server populates this from the
    // result event if it persisted the MP3 to the volume; we land it
    // on the clip below so cross-device sync can reference the sha.
    _bgCurrentServerAudioSha = null;

    // v204: SSE watchdog. The server emits ': keepalive\n\n' comment
    // lines every 15s during synth so intermediaries (Fly's proxy,
    // nginx) see live traffic. If we go 30s (2x slack) without ANY
    // bytes on the stream, the upstream is almost certainly dead —
    // abort the fetch so we get a clear error to surface, rather
    // than silently waiting on a never-arriving response. The fetch
    // abort propagates as a reader.read() rejection caught by
    // _bgTrySynth's outer try/catch, which already triggers the
    // 1.5s-then-retry path. A failed retry lands in _bgFailures and
    // shows the "needs a retry" banner.
    let _watchdogFired = false;
    let _watchdogTimer = null;
    // v225.tn86 (#568): split into first-byte and steady-state
    // budgets. Cold-start synth on a large chapter (e.g. 14k chars,
    // 200 sentences) can take 45-90s to deliver the first byte —
    // Piper has to warm up the voice model and produce the first
    // sentence WAV before any data leaves the server. The previous
    // flat 30s budget tripped on exactly that case. Subsequent
    // bytes can stay tighter (server emits a keepalive every 15s,
    // so 30s steady is 2x slack). The watchdog now uses
    // FIRST_BYTE_MS until any bytes arrive, then drops to
    // STEADY_MS.
    const SSE_WATCHDOG_FIRST_BYTE_MS = 90000;
    const SSE_WATCHDOG_STEADY_MS = 30000;
    let _watchdogGotFirstByte = false;
    // v216: pause the watchdog while the tab is hidden. Mobile
    // browsers throttle background tabs — JS execution slows or
    // halts, so incoming SSE bytes don't get processed, the
    // watchdog's timer keeps running on the real clock, and at
    // 30s it aborts a fetch that the server is happily still
    // streaming to. The user comes back to a synth that "died" —
    // because we killed it. Tab-visibility-aware reset fixes that:
    //   - tab hidden  → don't schedule abort
    //   - tab visible → schedule abort as normal
    // Triggered by:
    //   1. opening the manual / What's new in a new tab (which sets
    //      the original tab to hidden on phone)
    //   2. switching to another app
    //   3. locking the phone
    const _isVisible = () =>
      typeof document === "undefined" || document.visibilityState !== "hidden";
    const _resetWatchdog = () => {
      if (_watchdogTimer) clearTimeout(_watchdogTimer);
      if (!_isVisible()) return;  // suspend
      const ms = _watchdogGotFirstByte
        ? SSE_WATCHDOG_STEADY_MS
        : SSE_WATCHDOG_FIRST_BYTE_MS;
      _watchdogTimer = setTimeout(() => {
        _watchdogFired = true;
        try { myController.abort(); } catch {}
      }, ms);
    };
    const _onVisibility = () => {
      if (!_isVisible()) {
        // Going hidden — drop the in-flight timer so it doesn't
        // fire while the tab is throttled.
        if (_watchdogTimer) {
          clearTimeout(_watchdogTimer);
          _watchdogTimer = null;
        }
      } else {
        // Coming back — restart with a fresh budget (90s if we
        // haven't seen first byte yet, 30s once the stream's
        // been delivering). Any server-side keepalive that piled
        // up while we were hidden will tick the wire soon and
        // reset us again.
        _resetWatchdog();
      }
    };
    document.addEventListener("visibilitychange", _onVisibility);
    _resetWatchdog();

    while (true) {
      let readResult;
      try {
        readResult = await reader.read();
      } catch (err) {
        if (_watchdogTimer) clearTimeout(_watchdogTimer);
        // v216: drop the visibility handler now that we're done
        // with this chapter's watchdog. Otherwise each chapter
        // queue run leaks a listener.
        document.removeEventListener("visibilitychange", _onVisibility);
        if (_watchdogFired) {
          const budgetMs = _watchdogGotFirstByte
            ? SSE_WATCHDOG_STEADY_MS
            : SSE_WATCHDOG_FIRST_BYTE_MS;
          _dlog("synth", `SSE watchdog timeout — no bytes for ${budgetMs / 1000}s`, {
            title: chapter.title,
            atSentence: _bgSynthSentence,
            ofTotal: _bgSynthTotal,
            phase: _watchdogGotFirstByte ? "steady" : "first-byte",
          });
          throw new Error(
            "connection lost — server may be restarting or unreachable"
          );
        }
        throw err;
      }
      // Reset on ANY incoming bytes — including the keepalive comment
      // lines, which won't parse as `data:` events but still tick the
      // wire.
      // v225.tn86 (#568): mark that we've seen at least one byte so
      // the watchdog drops from the cold-start budget (90s) to the
      // steady-state budget (30s) for subsequent ticks.
      if (!_watchdogGotFirstByte) _watchdogGotFirstByte = true;
      _resetWatchdog();
      const { done, value } = readResult;
      if (done) {
        if (_watchdogTimer) clearTimeout(_watchdogTimer);
        document.removeEventListener("visibilitychange", _onVisibility);
        break;
      }
      buf += decoder.decode(value, { stream: true });
      let nl;
      while ((nl = buf.indexOf("\n\n")) >= 0) {
        const chunk = buf.slice(0, nl);
        buf = buf.slice(nl + 2);
        for (const line of chunk.split("\n")) {
          if (!line.startsWith("data: ")) continue;
          const event = JSON.parse(line.slice(6));
          // v141: surface per-sentence progress into the silent-queue
          // pill so the user has something to watch during a long
          // chapter. Skip when the silent queue isn't active so the
          // lookahead pre-synth path (during a foreground queue)
          // doesn't fight the foreground status text.
          if (event.type === "sentence" && _silentChapterQueue) {
            _bgSynthSentence = (event.index || 0) + 1;
            _bgSynthTotal = event.total || 0;
            _updateChapterQueueUI();
            // v4.61 (#844): also paint the matching library card's
            // progress bar so it advances in lockstep with the
            // "3/174 sentences" counter in the bg-queue panel.
            // Imperative DOM update (not a full renderLibrary) so a
            // 200-sentence chapter doesn't trigger 200 list rebuilds.
            try {
              _paintBgSyncProgressOnCard(
                _bgSyncingActiveClipId,
                _bgSynthSentence,
                _bgSynthTotal,
              );
            } catch (e) {
              console.warn("[sync-progress] paint failed:", e);
            }
          }
          // v225.tn33 (#509): record sentence progress regardless of
          // queue mode so the OK telemetry knows how far the stream
          // got. Updated on EVERY sentence event so a truncated
          // stream shows "got 1 of 47" instead of "got 47 of 47".
          if (event.type === "sentence" && _bgLastSynth) {
            _bgLastSynth.sentencesSeen = (event.index || 0) + 1;
            _bgLastSynth.sentencesAdvertised = event.total || 0;
          }
          if (event.type === "result") {
            combinedMp3 = new Blob([base64ToBytes(event.mp3_b64)], {
              type: "audio/mpeg",
            });
            sentenceOffsetsMs = event.sentence_offsets_ms || [];
            // v221.sync-4: server persisted the MP3 to /data/audio/<sha>.mp3
            // and reported its sha256. Capturing it here so the sync
            // adapter (#429) can PUT the clip referring to the sha
            // instead of re-uploading the blob.
            if (event.audio_sha256) {
              _bgCurrentServerAudioSha = event.audio_sha256;
            }
          } else if (event.type === "error") {
            // v177: log the SSE error message + position so a "chapter
            // 2 fails" report contains the sentence number where it
            // broke (useful for "the third sentence has a weird char").
            _dlog("synth", `SSE error: ${event.message || "(no msg)"}`, {
              title: chapter.title,
              atSentence: _bgSynthSentence,
              ofTotal: _bgSynthTotal,
            });
            // v204: stop the watchdog so it doesn't fire abort after
            // we've already thrown.
            if (_watchdogTimer) clearTimeout(_watchdogTimer);
            // v216: clean up the visibility listener too.
            document.removeEventListener("visibilitychange", _onVisibility);
            throw new Error(event.message || "synthesis error");
          }
        }
      }
    }
    if (!combinedMp3) {
      _dlog("synth", "no audio in result", {
        title: chapter.title,
        chars: (chapter.text || "").length,
        sentencesSeen: _bgSynthSentence,
        totalAdvertised: _bgSynthTotal,
      });
      throw new Error("no audio in result");
    }

    // Get duration via a throwaway <audio> element so the saved clip
    // has accurate metadata for the library card.
    const tmpUrl = URL.createObjectURL(combinedMp3);
    const tmpAudio = new Audio();
    const duration = await new Promise((resolve) => {
      tmpAudio.addEventListener(
        "loadedmetadata",
        () => resolve(isFinite(tmpAudio.duration) ? tmpAudio.duration : 0),
        { once: true }
      );
      tmpAudio.addEventListener("error", () => resolve(0), { once: true });
      tmpAudio.src = tmpUrl;
    });
    URL.revokeObjectURL(tmpUrl);

    // v225.tn33 (#509): finalize per-synth telemetry — this is where
    // the bg-queue OK log will read its detail fields from. Includes
    // the truncated + charsPerSec derived signals so a tester report
    // showing "OK with charsPerSec: 10500, truncated: true" is the
    // smoking gun for "synth bailed mid-stream but the bg-queue
    // marked it success." Computed inline so we don't have to thread
    // the data back through return values.
    if (_bgLastSynth) {
      const now = Date.now();
      _bgLastSynth.endMs = now;
      _bgLastSynth.blobSize = combinedMp3 ? combinedMp3.size : 0;
      _bgLastSynth.durationSec = duration;
      const elapsedSec = Math.max(0.001, (now - _bgLastSynth.startMs) / 1000);
      const chars = (chapter.text || "").length;
      _bgLastSynth.charsPerSec = Math.round(chars / elapsedSec);
      // Truncated when sentence count is known + we saw fewer than
      // advertised. If advertised is 0 (older server) treat unknown.
      _bgLastSynth.truncated =
        _bgLastSynth.sentencesAdvertised > 0
          ? _bgLastSynth.sentencesSeen < _bgLastSynth.sentencesAdvertised
          : null;
    }

    // Cancelled mid-flight (user cancelled queue, started a regen, etc.)?
    // Don't write a stale clip to the library.
    if (myController.signal.aborted || _preSynthController !== myController) {
      // v220t: log so a "FAIL ... (both attempts)" report can pin
      // whether the controller was replaced (another _preSynthesize
      // call landed) vs explicitly aborted (queue cancel, regen).
      _dlog("synth", "pre-synth aborted mid-flight (post-stream)", {
        title: chapter && chapter.title,
        signalAborted: myController.signal.aborted,
        controllerSwapped: _preSynthController !== myController,
      });
      return;
    }

    // v176: if the queue item carries a targetClipId (Re-narrate
    // outdated), overwrite that clip instead of creating a new one.
    // Carry the existing clip's title/note/bookmarks/cover so a
    // re-narrate is transparent — only text + audio + gitRef change.
    let existingClip = null;
    if (chapter.targetClipId) {
      try { existingClip = await getClip(chapter.targetClipId); } catch {}
    }
    // v220as (bug #414): if targetClipId was provided but the lookup
    // came back empty, we MUST NOT fall through to "create new clip
    // with timestamp ID" — that's how we ended up with duplicate
    // chapter_00_draft cards (7:25 next to 8:51). The target was
    // supposed to be overwritten; if it's missing, the user deleted
    // it mid-flight or IndexedDB raced. Fail loudly so the failures
    // banner surfaces it instead of silently spawning an orphan.
    if (chapter.targetClipId && !existingClip) {
      _dlog("synth", "targetClipId lookup failed — aborting to avoid dup", {
        title: chapter.title,
        targetClipId: chapter.targetClipId,
      });
      // Throw so the bg-queue worker catches it, the retry path runs,
      // and (if both attempts miss) the failures banner shows the
      // user that this clip needs manual attention.
      throw new Error(
        `Re-narrate target clip ${chapter.targetClipId} not found — was it deleted while syncing?`
      );
    }
    const newClipId = existingClip
      ? existingClip.id
      : Date.now() + Math.floor(Math.random() * 1000);
    await saveClip({
      id: newClipId,
      title: existingClip ? existingClip.title : chapter.title,
      note: existingClip ? existingClip.note || "" : "",
      // v176: re-narrate updates the source text and audio in place;
      // everything else (notes, tags, cover, bookmarks) is the user's
      // metadata and must survive the refresh untouched.
      notes: existingClip ? existingClip.notes || "" : "",
      tags: existingClip ? existingClip.tags || [] : [],
      // v225fz11.cover (#677): fresh-chapter saves (no existingClip)
      // share the upload-time detected cover. Re-narrate (existingClip
      // truthy) keeps the user's existing cover. Bg-queue runs one
      // chapter at a time but we DON'T clear _pendingDetectedCover
      // here — a 12-chapter EPUB import should land the cover on every
      // new chapter. Clear happens on next upload / clearForNewClip.
      cover: existingClip
        ? existingClip.cover || undefined
        : (_pendingDetectedCover && _pendingDetectedCover.src) || undefined,
      text: chapter.text,
      voiceId,
      voiceName,
      rate,
      volume,
      speakerId,
      sentenceOffsetsSec: sentenceOffsetsMs.map((ms) => ms / 1000),
      blob: combinedMp3,
      durationSec: duration,
      // v221.sync-4: server's sha for the persisted MP3 (or null if
      // the volume was disabled / persist failed). Stored on the clip
      // so the sync adapter can PUT a metadata-only payload referring
      // to this sha instead of re-uploading the blob. saveClip writes
      // it raw; cross-device pulls use it to construct the audio URL.
      audioSha256: _bgCurrentServerAudioSha || undefined,
      // v220as (bug #416): detect silent-fallback sentences. The Piper
      // engine's v85 fix produces a zero-frame placeholder WAV when a
      // single sentence fails to phonemize — we get a "complete" synth
      // with one or more sentences that play as silence. Adjacent
      // offsets differing by < 30ms reveals these: a real sentence at
      // 22050 Hz is always at least ~50ms long once Piper adds its
      // pause buffer; a zero-frame WAV doesn't advance the offset at
      // all. Stash the count on the clip so a future "⚠ N silent
      // sentences" card chip can surface it. Cheap to compute
      // (single-pass over offsets), opt-in for downstream UIs that
      // want to warn the user.
      synthSilentSentenceCount: (() => {
        let n = 0;
        for (let i = 1; i < sentenceOffsetsMs.length; i++) {
          if (sentenceOffsetsMs[i] - sentenceOffsetsMs[i - 1] < 30) n++;
        }
        return n;
      })(),
      // Set when saveClip is reached from this success path — i.e.
      // the synth ran to completion, the controller wasn't swapped,
      // and the abort check at line 7352 didn't fire. Pairs with
      // lastSyncedAt for the "audio matches text" guarantee.
      synthOk: true,
      // Reset playhead on a re-narrate — the new audio's timeline is
      // different from the old one, so the old position is meaningless.
      progressSec: 0,
      // Carry bookmarks: text didn't fundamentally change, just got
      // re-fetched. User's marks are too valuable to wipe.
      bookmarks: existingClip && Array.isArray(existingClip.bookmarks)
        ? existingClip.bookmarks
        : [],
      // v225fz12.chapter-images (#678): fresh-chapter saves through
      // bg-queue merge the matched chapter_image (title or ordinal).
      // Re-narrate (existingClip truthy) keeps existing.images so the
      // user's URL-extracted images survive — chapter detection is a
      // one-shot benefit of the initial import.
      images: existingClip && Array.isArray(existingClip.images)
        ? existingClip.images
        : (() => {
            const base = [];
            const titleForMatch = chapter.title || "";
            // chapter queue is 1-indexed; the just-processed chapter
            // we're saving is at _chapterCurrentIndex if active.
            const ord =
              typeof _chapterCurrentIndex === "number" && _chapterCurrentIndex >= 1
                ? _chapterCurrentIndex - 1
                : 0;
            const chimg = _chapterImageForTitle(titleForMatch, ord);
            const entry = _chapterImageToImagesEntry(chimg);
            if (entry) base.push(entry);
            return base;
          })(),
      // gitRef: prefer the fresh one from the re-narrate fetch so
      // the new SHA is recorded; fall back to the existing clip's
      // ref if for some reason we don't have a new one.
      gitRef: chapter.gitRef || (existingClip ? existingClip.gitRef : null),
      // v4.96 (#538 Phase 2): same precedence for Scrivener pin.
      scrivenerRef: chapter.scrivenerRef || (existingClip ? existingClip.scrivenerRef : null),
      // v220as: stamp every git-sourced clip with "when did we last
      // fetch + synth this." Surfaced on the library card as
      // "Last synced: 5 min ago" so users can tell across sessions
      // whether the audio matches their latest GitHub edits. Only
      // recorded when there's actually a gitRef — pasted/uploaded
      // clips don't have a meaningful "sync" concept.
      lastSyncedAt:
        (chapter.gitRef || (existingClip && existingClip.gitRef))
          ? new Date().toISOString()
          : (existingClip ? existingClip.lastSyncedAt : null),
      // v223.tn23 (#493): preserve cross-device sync ledger across
      // re-narrate. Previously these fields got dropped from local
      // IDB on every regen because the save object built from
      // scratch. Symptom: library footer reverted from "Synced · X"
      // to "GitHub · X" after any re-narrate, because lastDeviceSyncAt
      // went null. Worse, annotations/highlights silently disappeared
      // until the next cross-device pull restored them (and if local
      // updatedAt was newer at push time, they'd be wiped on the
      // server too — same LWW class as #488).
      lastDeviceSyncAt: existingClip ? existingClip.lastDeviceSyncAt : undefined,
      annotations: existingClip && Array.isArray(existingClip.annotations)
        ? existingClip.annotations
        : [],
      highlights: existingClip && Array.isArray(existingClip.highlights)
        ? existingClip.highlights
        : [],
      // sentenceAssignments — bg-queue path doesn't change voice
      // assignments, so preserve any per-sentence overrides the user
      // set in the reading view (v220aa feature).
      sentenceAssignments:
        existingClip && existingClip.sentenceAssignments
          ? existingClip.sentenceAssignments
          : {},
      // Voice provenance — bg-queue synth captures it on the request
      // side via voiceId/voiceName/speakerId; if the existing clip had
      // a provenance snapshot we keep it (the new audio was generated
      // with the same voice the user picked, so the snapshot is still
      // accurate). Fresh clips get null.
      provenance: existingClip && existingClip.provenance
        ? existingClip.provenance
        : null,
      createdAt: existingClip
        ? existingClip.createdAt
        : new Date().toISOString(),
    });
    if (existingClip) {
      // Drop the outdated flag now that the clip is current. Routed
      // through _markClipFresh so the main-view banner clears too.
      _markClipFresh(existingClip.id);
    }
    renderLibrary();
    _preSynthChapter = { clipId: newClipId, title: chapter.title };
  } catch (err) {
    if (err.name !== "AbortError") {
      console.warn("[pre-synth] failed:", err);
      // v220t: log the real exception too. Previously only HTTP / SSE
      // errors got their own dlog and other errors (network, parse,
      // saveClip throw) were console-only — invisible in the debug log.
      _dlog("synth", `pre-synth threw: ${err.name || "Error"}`, {
        title: chapter && chapter.title,
        errMsg: err && err.message,
      });
    } else {
      // v220t: log aborts too so a "FAIL ... (both attempts)" report
      // tells us whether the bg-queue job was killed externally
      // (regen, manual cancel, page hidden retry).
      _dlog("synth", "pre-synth aborted", {
        title: chapter && chapter.title,
      });
    }
    _preSynthChapter = null;
  } finally {
    if (_preSynthController === myController) _preSynthController = null;
  }
}

function _abortPreSynth() {
  if (_preSynthController) {
    _preSynthController.abort();
    _preSynthController = null;
  }
  _preSynthChapter = null;
}

function _cancelChapterQueue() {
  if (_chapterTotalCount <= 0) return;
  // Wipe ALL queue state, not just the pending list. Previously we
  // only cleared _chapterQueue; the next save callback then ran
  // _advanceChapterQueue, hit the empty-queue branch, and flashed a
  // misleading "All N chapters synthesized" status (the user just
  // cancelled — they didn't synthesize all of them). Also clear the
  // pending-advance flag so a later 'ended' event doesn't try to
  // resume the cancelled queue.
  // v139: flip the silent flag so a running background loop bails out
  // of its next iteration. _abortPreSynth (below) terminates the
  // in-flight fetch so the current chapter aborts immediately rather
  // than running to completion. The "current chapter will still save"
  // language stays for foreground queues — in background mode, an
  // in-flight aborted chapter does NOT save (pre-synth bails before
  // saveClip on AbortError), which matches user expectation: they
  // hit cancel because they don't want it.
  const wasSilent = _silentChapterQueue;
  _silentChapterQueue = false;
  _chapterQueue = [];
  _chapterTotalCount = 0;
  _chapterCurrentIndex = 0;
  _pendingChapterTitle = null;
  _resetQueueAdvanceFlags();
  _abortPreSynth();
  // v141: restore Generate when cancelling a background queue. (For
  // foreground queues these are already at the right state.)
  if (wasSilent) {
    _bgSynthCurrentTitle = "";
    _bgSynthSentence = 0;
    _bgSynthTotal = 0;
    generateBtn.disabled = false;
    generateBtn.title = "";
    // v162: clear the persistent-worker state so the next enqueue
    // starts a fresh run instead of resuming with a stale current.
    _bgCurrent = null;
    _bgRunning = false;
    // v169: stop the elapsed-time tick so it doesn't keep firing
    // _renderBgQueuePanel after the panel is hidden.
    _stopBgCurrentTimer();
    if (typeof _renderBgQueuePanel === "function") _renderBgQueuePanel();
  }
  _updateChapterQueueUI();
  setStatus(
    wasSilent
      ? "Background queue cancelled."
      : "Chapter queue cancelled — current chapter will still save."
  );
}

// Single entry point for "text just arrived from outside; check it." All
// three import paths (paste / file upload / URL fetch) call this.
// 200 covers virtually every novel; books with more (War & Peace at 365,
// serialized works, devotionals) are rare enough that requiring a manual
// split is acceptable for them. Original cap of 30 was set thinking of
// markdown docs with subheadings; turned out to silently swallow real
// novels like Tom Sawyer (35 chapters) extracted from URLs.
const MAX_AUTO_DETECT = 200;

function _checkForChapters() {
  // Don't re-banner if a queue is already running — the user has already
  // decided to split a chunk and we shouldn't second-guess them.
  if (_chapterTotalCount > 0) return;
  const chapters = _detectChapters(textEl.value);
  if (
    chapters &&
    chapters.length >= 2 &&
    chapters.length <= MAX_AUTO_DETECT
  ) {
    _showChapterBanner(chapters);
  } else {
    _hideChapterBanner();
  }
}

// Paste fires BEFORE the textarea value updates, so defer to a tick.
textEl.addEventListener("paste", () => {
  setTimeout(_checkForChapters, 0);
});

chapterBannerSplit.addEventListener("click", () => {
  if (_detectedChapters) _startChapterQueue(_detectedChapters);
});

chapterBannerDismiss.addEventListener("click", _hideChapterBanner);

chapterQueueCancel.addEventListener("click", _cancelChapterQueue);

// ---- Reading view --------------------------------------------------------
// After Generate, the editable textarea is hidden and the input text is
// rendered as a stack of <span class="sentence"> elements. As audio plays,
// the span matching the current playback time is marked `.active`; spans
// before it get `.played` so the user can see how far they've gotten at a
// glance. Mirrors the backend's split_sentences regex so the per-sentence
// offsets emitted by /api/synthesize/stream line up with what we render.

const SENTENCE_SPLIT = /(?<=[.!?])\s+/;

function splitSentencesClient(text) {
  return (text || "")
    .trim()
    .split(SENTENCE_SPLIT)
    .map((s) => s.trim())
    .filter((s) => s.length > 0);
}

// Author-mode threshold for the long-sentence highlighter. 35 words is
// the standard "is this becoming a run-on?" line — short enough to flag
// real candidates without painting half a chapter amber. CSS gating
// means this attribute is inert for readers who never turn Author mode
// on, so we always tag and let the stylesheet decide.
const LONG_SENTENCE_WORD_THRESHOLD = 35;

// v211 (M7.1): cached highlights for the reading-view sentence
// builder. Populated by loadClip and updated by _saveHighlight.
let _readingViewHighlights = [];

// v223.tn15 (#479): auto-pause at paragraph break. State + helpers.
// _paragraphEndIndices: Set of sentence indices that end a paragraph.
//   Recomputed by enterReadingView() against the current clip's text.
// _paragraphPauseSec: 0 means off; 2/4/6 = seconds to auto-pause.
//   Persisted in localStorage; read at boot + on Settings radio change.
// _paragraphPauseTimer: setTimeout handle for the pending resume.
//   Cleared on user-initiated play/seek/skip so we never fight them.
// v223.tn18 (bugfix): var (not let) so the boot wiring at the top of
// the file — _paragraphPauseSec = _readParagraphPauseSec() — doesn't
// hit the let temporal dead zone and throw `Cannot access ...
// before initialization`. Throwing at module load halts ALL
// downstream script execution, including the Import dropdown wire-up
// at line 15257 — which is what broke #485 / #486's deploys for the
// user. var hoists script-wide, no TDZ.
var _paragraphEndIndices = new Set();
var _paragraphPauseSec = 0;
var _paragraphPauseTimer = null;

function _detectParagraphEndIndices(text, sentences) {
  const ends = new Set();
  if (!text || !Array.isArray(sentences) || sentences.length === 0) return ends;
  let cursor = 0;
  for (let i = 0; i < sentences.length; i++) {
    const s = (sentences[i] || "").trim();
    if (!s) continue;
    const idx = text.indexOf(s, cursor);
    if (idx < 0) continue;
    const endOfSentence = idx + s.length;
    cursor = endOfSentence;
    // Inspect the gap between this sentence's end and the next
    // non-whitespace character. A \n followed by any whitespace and
    // another \n signals a paragraph break in source-text style.
    const after = text.slice(endOfSentence);
    const nextNonWs = after.search(/\S/);
    const gap = nextNonWs < 0 ? after : after.slice(0, nextNonWs);
    if (/\n\s*\n/.test(gap) && i < sentences.length - 1) {
      ends.add(i);
    }
  }
  return ends;
}

function _readParagraphPauseSec() {
  try {
    const v = parseInt(localStorage.getItem("narrative.paragraphPauseSec") || "0", 10);
    return Number.isFinite(v) && v >= 0 ? v : 0;
  } catch {
    return 0;
  }
}

function _triggerParagraphPause() {
  // No-op if disabled, already paused, or a previous pause is still
  // counting down (would double up the status message).
  if (_paragraphPauseSec <= 0) return;
  if (!playerEl || playerEl.paused) return;
  if (_paragraphPauseTimer) return;
  try { _pauseAsUser(); } catch { try { playerEl.pause(); } catch {} }
  setStatus(`⏸ Paragraph pause — resuming in ${_paragraphPauseSec}s.`);
  _paragraphPauseTimer = setTimeout(() => {
    _paragraphPauseTimer = null;
    if (playerEl && playerEl.paused) {
      try { playerEl.play().catch(() => {}); } catch {}
    }
  }, _paragraphPauseSec * 1000);
}

function _cancelParagraphPauseTimer() {
  if (_paragraphPauseTimer) {
    clearTimeout(_paragraphPauseTimer);
    _paragraphPauseTimer = null;
  }
}

function enterReadingView(text, images, highlights, lines) {
  if (Array.isArray(highlights)) {
    _readingViewHighlights = highlights;
  }
  // v185 (M1) fix: if the user is currently in book view and just
  // clicked a different clip in the library, they expect to stay in
  // book view — just with the new chapter's content. Capture the
  // state now; we'll honor it at the end by re-entering book view
  // against the freshly stashed _bookViewSource.
  const wasInBookView =
    typeof bookView !== "undefined" && bookView && !bookView.hidden;
  const sentences = splitSentencesClient(text);
  // v225v4.6 (#810 step 5): stamp data-line-id on each sentence span
  // when the clip has per-sentence storage enabled (clip.lines[] is
  // populated). The reading view still splits clip.text the same way
  // it always has — the visible text + word counts + highlight builder
  // all stay anchored to splitSentencesClient(), so behavior is
  // unchanged for non-line clips. But spans gain a stable identifier
  // that survives sentence insertion/deletion, which future Phase B
  // work (per-sentence WAV cache, partial re-narrate) will key off of.
  //
  // Defensive: only stamp when lines.length === sentences.length. If
  // they disagree, the text has drifted from the stored lines (which
  // shouldn't happen until step 6 wires inline-edit through lines[],
  // but a stale state could exist), and stamping a stale ID would
  // anchor annotations to the wrong sentence. Better to fall through
  // to index-only spans + log it so we can find the cause.
  let _useLineIds = false;
  if (Array.isArray(lines) && lines.length > 0) {
    if (lines.length === sentences.length) {
      _useLineIds = true;
    } else if (typeof _dlog === "function") {
      _dlog("reading-view", "lines/sentences length mismatch", {
        sentencesFromText: sentences.length,
        storedLines: lines.length,
      });
    }
  }
  // v223.tn15 (#479): compute which sentences end a paragraph so the
  // auto-pause at paragraph break has somewhere to fire. Walks the
  // source text, finds each sentence's position, checks the gap to
  // the next sentence for \n\n. Last sentence is intentionally not
  // marked — end-of-clip has its own auto-advance behavior.
  _paragraphEndIndices = _detectParagraphEndIndices(text, sentences);
  readingView.innerHTML = "";

  // Bucket images by the sentence they should appear *before*. Each entry
  // is {sentence_index, src, alt}; the extractor numbers them against the
  // *cleaned* text (same splitter the server runs), so indexes line up
  // with the spans we're about to create. Indexes past the last sentence
  // get appended at the end so a trailing picture isn't silently lost.
  const imgList = Array.isArray(images) ? images : [];
  const imgByIndex = new Map();
  for (const img of imgList) {
    if (!img || !img.src) continue;
    const raw = Number(img.sentence_index);
    const idx = Number.isFinite(raw)
      ? Math.max(0, Math.min(sentences.length, Math.floor(raw)))
      : sentences.length;
    if (!imgByIndex.has(idx)) imgByIndex.set(idx, []);
    imgByIndex.get(idx).push(img);
  }

  function flushImagesAt(idx) {
    const bucket = imgByIndex.get(idx);
    if (!bucket) return;
    for (const img of bucket) {
      const el = document.createElement("img");
      el.className = "inline-image";
      el.loading = "lazy";
      el.decoding = "async";
      el.src = img.src;
      el.alt = img.alt || "";
      // A broken image (404, blocked host, expired hotlink) shouldn't
      // leave an empty slot in the middle of the reading view — drop it.
      el.addEventListener("error", () => el.remove(), { once: true });
      // v225fz12.chapter-images (#678): differentiate per-format.
      //   - source="chapter-image" + kind="decorative" → banner above
      //     the chapter heading, no caption, full-width.
      //   - source="chapter-image" + kind="figure" → wrap in <figure>
      //     with a <figcaption> drawn from alt so the figure carries
      //     its label. Empty alt → no caption (rare but possible).
      //   - default (URL-extracted inline image): unchanged behavior.
      if (img.source === "chapter-image") {
        if (img.kind === "decorative") {
          el.classList.add("chapter-image", "chapter-image-decorative");
          readingView.appendChild(el);
        } else {
          el.classList.add("chapter-image", "chapter-image-figure");
          const fig = document.createElement("figure");
          fig.className = "chapter-image-figure-wrap";
          fig.appendChild(el);
          if (img.alt) {
            const cap = document.createElement("figcaption");
            cap.textContent = img.alt;
            fig.appendChild(cap);
          }
          readingView.appendChild(fig);
        }
      } else {
        readingView.appendChild(el);
      }
    }
  }

  sentenceSpans = sentences.map((s, i) => {
    flushImagesAt(i);
    const span = document.createElement("span");
    span.className = "sentence";
    span.dataset.index = String(i);
    // v225v4.6 (#810 step 5): stamp the stored line id when present.
    // _useLineIds is gated above on lines.length === sentences.length,
    // so lines[i] is guaranteed to exist when we reach this branch.
    if (_useLineIds && lines[i] && lines[i].id) {
      span.dataset.lineId = lines[i].id;
    }
    // Long-sentence flag. Word count uses the same splitter as the
    // textarea meta line so an Author sees consistent numbers between
    // "247 words" in the meta and "this one's 41" in the reading view.
    const wc = _countWords(s);
    if (wc >= LONG_SENTENCE_WORD_THRESHOLD) {
      span.dataset.longSentence = "true";
      span.dataset.wordCount = String(wc);
      span.title = `${wc} words`;
    }
    // v211 (M7.1): use the shared content builder so reading view
    // sentences carry their highlights too. _readingViewHighlights
    // is populated by loadClip / generate when the clip's
    // highlights are read in.
    span.innerHTML = _buildSentenceContentHTML(s, i, _readingViewHighlights || []);
    // v220-AI: stash raw text + the built HTML on the span so the
    // attribution repaint can switch between "single-color whole span"
    // (preserves highlights / drop caps) and "split into colored
    // quote vs narration sub-spans" without permanently destroying
    // the highlight structure. dataset stores strings, so a string
    // snapshot is the most reliable cross-paint anchor.
    span.dataset.sentenceText = s;
    span.dataset.originalContent = span.innerHTML;
    span.addEventListener("click", () => {
      // v583: tap-then-confirm state machine. The previous "tap = seek
      // + play" was too eager — users listening to narration who tapped
      // a recently-past sentence (to annotate it) would yank the
      // playhead and interrupt their listening. The new contract:
      //
      //   tap currently-playing/active sentence → select (visual ring) ← v4.75
      //   tap other sentence (1st time)         → select (visual ring)
      //   tap other sentence (2nd time)         → seek + play
      //   tap different idle sentence           → replace selection
      //
      // v4.75 (#877): tap-on-active-sentence used to toggle play/pause
      // and clear selection. That hijacked the natural "I want to
      // bookmark the line I'm hearing right now" gesture — the listener
      // had to pause some other way, then tap the line twice (which
      // would re-seek to the same position). New contract: any tap on
      // any sentence is a select, full stop. Bookmark/edit/annotate
      // can then act on the selection. Pause has its own affordances
      // — Spacebar/K on desktop (v4.71/v4.72), the Play/Pause chip in
      // the player card or pull-up on phone. The same-sentence-second-
      // tap branch below (i === _selectedSentenceIdx) now naturally
      // handles "tap-tap-active-sentence" too: it'd seek to a position
      // we're already at, which is a no-op for the playhead.
      //
      // Tag-armed flow is unaffected: the capture-phase annotate
      // listener at the reading-view root already runs first and
      // stops propagation when a tag is armed, so armed-tap-apply
      // stays one-tap.
      //
      // v592: while a sentence is in inline-edit mode, clicks inside
      // it should move the text caret, not seek the audio. Bail
      // early so the contenteditable handles the click natively.
      if (typeof _inlineEditingIdx === "number" && _inlineEditingIdx === i) {
        return;
      }
      _readingViewUserScrolled = false;

      if (i === _selectedSentenceIdx) {
        // Second tap on a previously-selected sentence.
        // Commit the seek and start playing from there. If this is
        // the active sentence (idx === activeSentenceIdx) the seek
        // is effectively a no-op — currentTime stays at the same
        // position — but we still call seekToSentence to keep state
        // consistent and to handle the streaming-mode case where the
        // per-sentence WAV may need to (re-)load.
        _clearSelectedSentence();
        seekToSentence(i);
        if (playerEl.paused) playerEl.play().catch(() => {});
        return;
      }

      // First tap — select only. No seek, no play state change.
      // The visible ring tells the user that a second tap on the
      // same sentence will jump there. Applies uniformly whether
      // the tapped sentence is the active (playing) one or any
      // other.
      _paintSelectedSentence(i);
    });
    // v220-AA: long-press / right-click opens the per-sentence voice
    // assignment dialog. Wired here so every sentence in the reading
    // view is assignable. The visual mark for existing overrides is
    // applied below in a second pass once the array is built.
    _attachSentenceAssignHandlers(span, i);
    readingView.appendChild(span);
    return span;
  });
  // v220-AA: paint the current assignment markers (tag chip + dotted
  // underline) on any sentence with an existing override.
  for (let i = 0; i < sentenceSpans.length; i++) {
    _applySentenceAssignmentMark(sentenceSpans[i], i);
  }
  // v220-AB: also paint each sentence's text in its attributed
  // character's color. Runs once per reading-view build; the color
  // picker calls _repaintReadingViewAttribution directly for live
  // feedback as the user scrubs the picker.
  _repaintReadingViewAttribution();
  // Trailing images (anchored past the final sentence, or the catch-all
  // bucket for malformed indexes) — render them at the bottom.
  flushImagesAt(sentences.length);
  activeSentenceIdx = -1;
  // v583: a fresh reading-view build means new sentence spans, so
  // the cached _selectedSentenceIdx points at a stale element. Reset
  // here rather than across every reset call site — this is the
  // single chokepoint where sentenceSpans is rebuilt.
  _selectedSentenceIdx = -1;
  // v189: new clip → fresh start. Clear any pinned scroll state
  // from a previous reading-view session so the auto-scroll
  // resumes correctly for the new content.
  _readingViewUserScrolled = false;
  if (readingViewReturnBtn) readingViewReturnBtn.hidden = true;
  textEl.hidden = true;
  readingView.hidden = false;
  editTextBtn.hidden = false;
  saveTextBtn.hidden = true;
  // v185 (M1): book view toggle is bound to "we have a loaded clip
  // with rendered sentences" — same lifecycle as the Edit button.
  if (bookViewToggle) bookViewToggle.hidden = false;
  // Stash the current text + images so the book view can paginate
  // without re-running the splitter. Title comes from the loaded
  // clip when available; falls back to "Untitled chapter".
  _bookViewSource = {
    sentences: sentences.slice(),
    images: imgList.slice(),
    title: "",
    cover: null,
  };
  textLabel.textContent = "Now reading";
  // Chip strip is editing-only; clear it while we're in playback so the
  // reading view sits cleanly below the .meta line.
  if (fillerCountsEl) {
    fillerCountsEl.hidden = true;
    fillerCountsEl.innerHTML = "";
  }
  // v185 (M1) fix: if the user was in book view before this clip
  // load, repaginate the book view against the new content and put
  // them back there. Without this, loading a different clip from the
  // library while in book view leaves both views rendered at the
  // same time (the reading view fires up; the book view never
  // notices the content changed).
  if (wasInBookView && typeof enterBookView === "function") {
    enterBookView();
  }
}

function exitReadingView() {
  textEl.hidden = false;
  readingView.hidden = true;
  editTextBtn.hidden = true;
  // v189: hide the return-current pill alongside the reading view.
  // (The pinned flag is reset on the next enter, so no need to
  // touch it here.)
  if (readingViewReturnBtn) readingViewReturnBtn.hidden = true;
  // v185 (M1): close book view alongside reading view — same loaded-
  // clip lifecycle. If the user pressed Edit text mid-book, the
  // book view also needs to fold away so they're back in the
  // textarea editing context.
  if (typeof exitBookView === "function" && bookView && !bookView.hidden) {
    exitBookView({ skipReadingView: true });
  }
  if (bookViewToggle) bookViewToggle.hidden = true;
  _bookViewSource = null;
  // Save text only makes sense when there's a loaded clip to save into —
  // freshly-typed text with no clip yet still needs Generate first.
  saveTextBtn.hidden = !_currentClipId;
  textLabel.textContent = "Your text";
  sentenceSpans.forEach((s) => s.classList.remove("active", "played"));
  activeSentenceIdx = -1;
  // The chip strip was hidden while reading; bring it back if the text
  // we're editing has filler words worth flagging.
  _renderFillerChips(textEl.value);
}

async function saveCurrentClipText() {
  if (!_currentClipId) {
    setStatus("Load a clip first — there's nothing to save into.", true);
    return;
  }
  saveTextBtn.disabled = true;
  const oldLabel = saveTextBtn.textContent;
  saveTextBtn.textContent = "Saving…";
  try {
    const newText = textEl.value;
    // v223.tn19 (#488): atomic so concurrent absorb can't lose annotations.
    // Need a few values back from the mutation (oldText, needsRegen, clip
    // itself for the downstream branches), so capture them through the
    // closure rather than just returning from the mutator.
    let oldText = "";
    let needsRegen = false;
    const clip = await _mutateClipAtomic(_currentClipId, (c) => {
      oldText = c.text || "";
      const oldSentenceCount = splitSentencesClient(oldText).length;
      const newSentenceCount = splitSentencesClient(newText).length;
      needsRegen = oldSentenceCount !== newSentenceCount;
      c.text = newText;
      if (needsRegen) {
        // Old resume position likely doesn't map cleanly to the new audio,
        // so reset it before we save and kick off the regen.
        c.progressSec = 0;
      }
    });
    if (!clip) {
      setStatus("Clip not found — it may have been deleted in another tab.", true);
      return;
    }

    if (!needsRegen) {
      // Typo / capitalization / whitespace fix — same sentence boundaries,
      // audio still aligns. Just refresh the reading-view spans.
      setStatus(`Saved text changes to "${clip.title || "(untitled)"}."`);
      enterReadingView(newText, Array.isArray(clip.images) ? clip.images : []);
      renderLibrary();
      return;
    }

    // Sentence count changed — tell generate() to overwrite this clip's
    // audio in place. The text was already saved above; if the regen
    // is cancelled or fails, the old audio is still on disk and the
    // new text is preserved.
    setStatus(
      `Sentence count changed (${oldSentenceCount} → ${newSentenceCount}) — regenerating audio…`
    );
    _regenTargetClipId = _currentClipId;
    // Re-enter the reading view so the user can watch the new sentences
    // light up as the per-sentence streaming arrives. Sentence count
    // changed, so any URL-anchored image positions are stale — drop them.
    enterReadingView(newText, []);
    // Fire and forget — generate() drives its own status / progress UI.
    generate();
  } catch (e) {
    console.warn("save text failed:", e);
    setStatus(_withOfflineHint(`Save failed: ${e.message}`), true);
  } finally {
    saveTextBtn.disabled = false;
    saveTextBtn.textContent = oldLabel;
  }
}

saveTextBtn.addEventListener("click", saveCurrentClipText);

// ---- Clear (start a new clip) -------------------------------------------
// Empty the textarea + drop the "currently-loaded clip" binding so the next
// Generate creates a fresh row instead of overwriting / saving-into the
// previous one. Deliberately *doesn't* touch the player, the library, or
// the voice/preset settings — so you can keep listening to clip A while
// typing the text for clip B, and the voice you just dialed in carries
// forward to the next generation.
function clearForNewClip() {
  // Cancel any pending auto-advance — the user is clearly starting fresh.
  _cancelAutoAdvance();

  // v205: stop audio + hide the player card. Previously Clear would
  // wipe the textarea and decouple Save text from the clip, but leave
  // the audio playing and the player card visible — which felt wrong
  // (workspace looks empty while the previous clip narrates on). The
  // user is signaling "fresh slate", so the audio is part of what
  // gets cleared.
  if (!playerEl.paused) _pauseAsUser();
  playerCard.hidden = true;

  // Clear text mid-queue also cancels the queue. Otherwise the next
  // chapter would auto-load into the just-cleared textarea and surprise
  // the user. Hide the banner too in case a detection was lingering.
  if (_chapterTotalCount > 0) {
    _chapterQueue = [];
    _chapterTotalCount = 0;
    _chapterCurrentIndex = 0;
    _pendingChapterTitle = null;
    _abortPreSynth();
    _updateChapterQueueUI();
  }
  _hideChapterBanner();

  // If we were in the reading view, drop back to the textarea so the user
  // can actually type into the (about to be empty) editor.
  if (!readingView.hidden) exitReadingView();

  textEl.value = "";
  updateCounts();

  // Decouple from the previously-loaded clip: Save text + the regen path
  // both look at _currentClipId, so leaving it pointed at the old clip
  // would mean "Save text" silently saves into the wrong row.
  _currentClipId = null;
  _currentPlayingVoiceId = null;
  _lastProgressSaveAt = 0;
  saveTextBtn.hidden = true;
  // v225ep (#632): clip just got cleared → author pane's gate flips
  // off → CSS hides it via data-multipane-author drop.
  if (typeof _applyAuthorPaneLayout === "function") {
    try { _applyAuthorPaneLayout(); } catch {}
  }
  // Fade out the cover backdrop — no clip = no atmosphere.
  _setBackgroundArt(null);
  // No clip → no re-narrate banner. Reset the dismiss tracker too so a
  // future load of a different clip can prompt again.
  renarrateBanner.hidden = true;
  _renarrateDismissedClipId = null;
  // Drop any pending images from a URL fetch so they don't sneak onto
  // a freshly-typed clip.
  _pendingImages = [];
  _pendingGitRef = null;
  _pendingScrivenerRef = null;
  // v225fz11.cover (#677): drop the detected cover too — a clean
  // slate clip shouldn't inherit it from a previous import.
  _pendingDetectedCover = null;
  // v225fz12.chapter-images (#678): same reasoning for per-chapter
  // images — they belong to the import they came from, not the
  // next thing the user types.
  _pendingChapterImages = [];
  // v225fz14 (#688): tear down the preview strip — no pending
  // images, nothing to show.
  if (typeof _paintImportPreview === "function") _paintImportPreview();
  // v149: textarea + clip just got wiped — give the empty-state card
  // a chance to re-appear if the library is also empty.
  _updateEmptyState();

  // Wipe the sentence state so any leftover highlight from the previous
  // clip doesn't bleed into the next reading view.
  sentenceOffsetsSec = [];
  sentenceSpans = [];
  activeSentenceIdx = -1;

  textLabel.textContent = "Your text";
  textEl.focus();
  // Clear out the previously-loaded clip's bookmarks display too — they
  // belong to the clip we just decoupled from, not whatever the user
  // generates next.
  renderBookmarks();
  setStatus("Cleared. Ready for new text.");
}

clearBtn.addEventListener("click", clearForNewClip);

// v189: same pinned-scrub pattern as the book view (v187) — when the
// user manually scrolls the reading view to scan ahead, suppress
// the auto-scroll-to-active so the page stays where they put it.
// Flag flips on via wheel/touch/keyboard input on readingView;
// clears on Return-button click, sentence click, or auto-catch-up
// (audio reads forward until the active sentence is back in the
// visible portion of the reading view).
let _readingViewUserScrolled = false;
const readingViewReturnBtn = document.getElementById("reading-view-return");

// Sentence-in-viewport check. Both rects use viewport coordinates so
// a partial overlap counts as visible — same threshold the old
// auto-scroll used, just inverted.
function _readingViewActiveSpanVisible(span) {
  if (!span || !readingView) return false;
  const cRect = readingView.getBoundingClientRect();
  const sRect = span.getBoundingClientRect();
  return sRect.bottom > cRect.top && sRect.top < cRect.bottom;
}

function _readingViewUpdateReturnBtn() {
  if (!readingViewReturnBtn) return;
  // Hidden when: reading view not visible, no active sentence yet,
  // not pinned, or active sentence is already on screen.
  if (
    !readingView ||
    readingView.hidden ||
    activeSentenceIdx < 0 ||
    !_readingViewUserScrolled
  ) {
    readingViewReturnBtn.hidden = true;
    return;
  }
  const activeSpan = sentenceSpans[activeSentenceIdx];
  readingViewReturnBtn.hidden = _readingViewActiveSpanVisible(activeSpan);
}

// User-input listeners. Each pins the scroll position. Programmatic
// scrolls (the existing scrollBy in highlightCurrentSentence) DON'T
// trigger any of these, so the pin only catches real user intent.
if (readingView) {
  readingView.addEventListener("wheel", () => {
    _readingViewUserScrolled = true;
    _readingViewUpdateReturnBtn();
  }, { passive: true });
  readingView.addEventListener("touchstart", () => {
    _readingViewUserScrolled = true;
    _readingViewUpdateReturnBtn();
  }, { passive: true });
  readingView.addEventListener("keydown", (e) => {
    if (["PageUp", "PageDown", "ArrowUp", "ArrowDown", "Home", "End"].includes(e.key)) {
      _readingViewUserScrolled = true;
      _readingViewUpdateReturnBtn();
    }
  });
  // v586: tap outside any sentence in the reading view clears a
  // pending selection. The container click listener fires on the
  // bubble phase, AFTER the span's own click handler — so when a
  // span IS tapped, _selectedSentenceIdx is already updated by the
  // time we run, and closest(".sentence") matches the bubbled
  // target, so we don't clear. When the user taps in the paragraph
  // gaps, padding, or trailing-image area (anywhere inside the
  // reading view that isn't a sentence), closest is null and we
  // clear. Inline flag chips stopPropagation themselves so they
  // never reach this. Voice-note buttons (▶ ↻ ✕) live inside the
  // sentence span, so closest still finds the .sentence ancestor.
  readingView.addEventListener("click", (e) => {
    if (_selectedSentenceIdx < 0) return;
    if (e.target.closest && e.target.closest(".sentence")) return;
    _clearSelectedSentence();
  });
}

// v586: Esc clears pending sentence selection on desktop. Guarded
// against form-field focus so users can still Esc-out-of search
// boxes, the bookmark editor, etc. Doesn't preventDefault — other
// Esc handlers (dialog close, palette dismiss) should still run if
// nothing was selected, and run alongside ours if something was.
document.addEventListener("keydown", (e) => {
  if (e.key !== "Escape") return;
  if (_selectedSentenceIdx < 0) return;
  const t = e.target;
  if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA"
            || t.isContentEditable)) return;
  _clearSelectedSentence();
});
if (readingViewReturnBtn) {
  readingViewReturnBtn.addEventListener("click", () => {
    const activeSpan = sentenceSpans[activeSentenceIdx];
    if (!activeSpan) return;
    _readingViewUserScrolled = false;
    // Smooth scroll the active sentence to roughly center-vertical
    // of the reading view's visible region — feels less abrupt than
    // the original "snap to top/bottom edge" behavior.
    const cRect = readingView.getBoundingClientRect();
    const sRect = activeSpan.getBoundingClientRect();
    const target =
      sRect.top - cRect.top - cRect.height / 2 + sRect.height / 2;
    readingView.scrollBy({ top: target, behavior: "smooth" });
    _readingViewUpdateReturnBtn();
  });
}

// v223.tn12 (#477): word-level highlight inside the active sentence.
// Mirrors Apple Music / Speechify / Kindle Immersion — the writer's
// eye follows the exact word the narrator is hitting, which makes
// it easier to flag weak verbs, mispronunciations, and rhythm
// problems in flight. Word timings are estimated from the existing
// sentenceOffsetsSec by splitting each sentence's duration across
// its words proportional to character count (longer words take
// longer to say). No new audio analysis needed — feels right and
// stays accurate enough for the use case.
//
// Wrapping happens once per sentence, on first activation. Word
// spans live alongside any other inline children (text-highlight,
// character runs, voice-note ▶ buttons) — we walk text nodes only,
// preserving the surrounding element structure.

function _wrapSentenceWordsOnce(sentenceSpan) {
  if (!sentenceSpan || sentenceSpan.dataset.wordsWrapped === "true") return;
  const wordList = [];
  // Walk text nodes inside the sentence, skipping anything nested
  // inside an interactive button (the ▶ voice-note play button has
  // its own text node we don't want to wrap).
  const walker = document.createTreeWalker(
    sentenceSpan, NodeFilter.SHOW_TEXT, {
      acceptNode: (node) => {
        let p = node.parentNode;
        while (p && p !== sentenceSpan) {
          if (p.nodeType === 1 && (
            p.tagName === "BUTTON" ||
            (p.classList && p.classList.contains("annotate-voice-play"))
          )) {
            return NodeFilter.FILTER_REJECT;
          }
          p = p.parentNode;
        }
        return NodeFilter.FILTER_ACCEPT;
      },
    },
  );
  const textNodes = [];
  let n;
  while ((n = walker.nextNode())) textNodes.push(n);
  for (const textNode of textNodes) {
    const text = textNode.nodeValue || "";
    if (!/\S/.test(text)) continue;
    const tokens = text.split(/(\s+)/);
    const frag = document.createDocumentFragment();
    for (const tok of tokens) {
      if (!tok) continue;
      if (/^\s+$/.test(tok)) {
        frag.appendChild(document.createTextNode(tok));
      } else {
        const ws = document.createElement("span");
        ws.className = "word";
        ws.textContent = tok;
        wordList.push(ws);
        frag.appendChild(ws);
      }
    }
    textNode.parentNode.replaceChild(frag, textNode);
  }
  sentenceSpan._wordList = wordList;
  sentenceSpan.dataset.wordsWrapped = "true";
}

// Build per-word time intervals across a sentence by splitting its
// duration proportionally to character count. Returns parallel arrays
// of {start, end} per word, in seconds (global clip time).
function _computeWordIntervals(words, sentenceStart, sentenceEnd) {
  const n = words.length;
  if (!n) return [];
  const duration = Math.max(0, sentenceEnd - sentenceStart);
  const totalChars = words.reduce((acc, w) => acc + (w.length || 1), 0);
  const out = [];
  let t = sentenceStart;
  for (let i = 0; i < n; i++) {
    const fraction = totalChars > 0
      ? (words[i].length || 1) / totalChars
      : 1 / n;
    const dur = duration * fraction;
    out.push({ start: t, end: t + dur });
    t += dur;
  }
  // Snap the last word's end to the sentence boundary to absorb any
  // floating-point drift.
  if (out.length) out[out.length - 1].end = sentenceEnd;
  return out;
}

let _activeWordSpan = null;
let _activeWordIdx = -1;
let _activeSentenceIntervals = null;

function _paintActiveWord(now) {
  if (activeSentenceIdx < 0) return;
  const span = sentenceSpans[activeSentenceIdx];
  if (!span || !span._wordList) return;
  if (!_activeSentenceIntervals || !_activeSentenceIntervals.length) return;
  // Linear scan is fine for ~20-word sentences. Stop early.
  let idx = -1;
  for (let i = 0; i < _activeSentenceIntervals.length; i++) {
    const it = _activeSentenceIntervals[i];
    if (now >= it.start && now < it.end) { idx = i; break; }
    if (now < it.start) break;
  }
  // After the last word's end (very end of sentence): keep the last
  // word lit so we don't blank the highlight in the gap before the
  // next sentence becomes active.
  if (idx < 0 && now >= _activeSentenceIntervals[_activeSentenceIntervals.length - 1].end) {
    idx = _activeSentenceIntervals.length - 1;
  }
  if (idx === _activeWordIdx) return;
  if (_activeWordSpan) _activeWordSpan.classList.remove("word-active");
  _activeWordIdx = idx;
  _activeWordSpan = idx >= 0 ? span._wordList[idx] : null;
  if (_activeWordSpan) _activeWordSpan.classList.add("word-active");
}

function highlightCurrentSentence() {
  if (!sentenceSpans.length) return;
  // Use virtualTime() so the highlight tracks the right sentence even while
  // we're playing per-sentence blobs (where player.currentTime is local to
  // the current blob, not the whole document).
  const now = virtualTime();
  const idx = currentSentenceIndex(now);
  if (idx !== activeSentenceIdx) {
    const previousIdx = activeSentenceIdx;
    activeSentenceIdx = idx;
    sentenceSpans.forEach((span, i) => {
      span.classList.toggle("active", i === idx);
      span.classList.toggle("played", i < idx);
    });
    // v223.tn15 (#479): the sentence we just LEFT may have been the
    // last in its paragraph — give the listener a breath before the
    // narrator starts the next one. Only triggers on forward
    // transitions (skip-backs land here too, but the guard for
    // !playerEl.paused + the timer-busy check inside _triggerParagraphPause
    // keeps things sane). Disabled when paragraph-pause is set to 0s
    // (the default).
    if (
      previousIdx >= 0 &&
      idx > previousIdx &&
      _paragraphPauseSec > 0 &&
      _paragraphEndIndices.has(previousIdx)
    ) {
      _triggerParagraphPause();
    }
    // v223.tn12: rebuild word intervals for the newly-active sentence
    // and wrap its words on first activation. Previous sentence keeps
    // its wrapping (cheap to leave in place; words remain dim but
    // present, ready for replay).
    if (_activeWordSpan) {
      _activeWordSpan.classList.remove("word-active");
      _activeWordSpan = null;
      _activeWordIdx = -1;
    }
    _activeSentenceIntervals = null;
    if (idx >= 0 && Array.isArray(sentenceOffsetsSec) && sentenceOffsetsSec.length > idx) {
      const activeSpan = sentenceSpans[idx];
      _wrapSentenceWordsOnce(activeSpan);
      const wordList = activeSpan._wordList || [];
      const sStart = sentenceOffsetsSec[idx];
      let sEnd = sentenceOffsetsSec[idx + 1];
      if (sEnd == null || !isFinite(sEnd)) {
        sEnd = isFinite(playerEl.duration) ? playerEl.duration : sStart + 1;
      }
      _activeSentenceIntervals = _computeWordIntervals(
        wordList.map((w) => w.textContent || ""), sStart, sEnd,
      );
    }
  // v185 (M1): mirror the karaoke into the book view.
  // v187: respect the "pinned" state. When the user has manually
  // paged ahead to scan, the highlight still advances per the audio,
  // but the spread stays where they put it. Only when the active
  // sentence happens to land on the visible spread do we re-apply
  // the .active class. The nav row's "Return to current" button
  // (driven by _bookViewUpdateNav) gives the user a one-click way
  // back to the audio's location.
  if (bookView && !bookView.hidden && _bookSentenceToPage.length > 0) {
    const ppr = _bookViewPagesPerSpread();
    const desired = _bookViewSpreadOfSentence(idx, ppr);
    if (desired === _bookViewCurrentSpread) {
      // Audio caught up to where the user scrubbed to — drop the
      // pinned flag silently so the next manual-nav re-arms it.
      _bookViewUserPaged = false;
      _bookViewApplyActive(idx);
      _bookViewUpdateNav();
    } else if (_bookViewUserPaged) {
      // Pinned: leave the spread alone but refresh the nav so the
      // "Return to current" button reflects the new distance.
      _bookViewUpdateNav();
    } else {
      _bookViewRenderSpread(desired);
    }
  }
  const activeSpan = sentenceSpans[idx];
  if (activeSpan) {
    // v189: respect the pinned state. When the user has manually
    // scrolled to scan ahead, the highlight still tracks the audio
    // (above) but the scroll position stays where they put it. The
    // floating "Return to current" pill (driven by
    // _readingViewUpdateReturnBtn) gives them a one-click way back.
    if (_readingViewUserScrolled) {
      // Auto-catch-up: if the audio has read forward (or the user
      // scrolled back to where the audio is) until the active
      // sentence is now visible, silently clear the pin so the
      // auto-scroll resumes following from here.
      if (_readingViewActiveSpanVisible(activeSpan)) {
        _readingViewUserScrolled = false;
      }
      _readingViewUpdateReturnBtn();
    } else {
      // v223.tn11 (#476): comfort-zone auto-scroll. The old "edge-
      // park" rule (scroll only when the sentence fully leaves the
      // viewport, just enough to return it to the closest edge) left
      // the highlight stuck at the bottom of the viewport for the
      // entire reading session — no preview of upcoming sentences,
      // user loses the thread.
      //
      // New rule, matching Audible / Apple Music lyrics / Speechify /
      // Kindle Immersion: keep the active sentence in the UPPER third
      // of the viewport. When it drifts past the lower-third line (or
      // has scrolled above the top after a backward seek), smooth-
      // scroll just enough to put it back at the upper-third line.
      // The user always sees ~2/3 of the screen of upcoming text.
      //
      // Still scoped to the reading-view's own scrollbar via scrollBy
      // — scrollIntoView walks ALL ancestors and would yank the
      // document scroll when the user has scrolled the page for other
      // reasons (library reorder, etc).
      const cRect = readingView.getBoundingClientRect();
      const sRect = activeSpan.getBoundingClientRect();
      const viewportH = cRect.bottom - cRect.top;
      const sentenceTopInView = sRect.top - cRect.top;
      const upperThird = viewportH / 3;
      const lowerThird = viewportH * 2 / 3;
      if (sentenceTopInView < 0 || sentenceTopInView > lowerThird) {
        const delta = sentenceTopInView - upperThird;
        readingView.scrollBy({ top: delta, behavior: "smooth" });
      }
    }
  }
  }
  // v223.tn12: word paint runs on every tick (not just on sentence
  // transitions) so the active-word marker advances smoothly within a
  // sentence. Cheap — just a class toggle on a single span.
  _paintActiveWord(now);
}

// v592 / #537 Phase 2: inline single-sentence edit.
//
// Repurposes Edit text. If a sentence is selected (the v583 dashed
// ring), opens an in-place editor on THAT sentence. Otherwise falls
// back to legacy exitReadingView() (the full textarea) for power
// users who want to rewrite the whole chapter.
//
// Save flow: posts to a /api/synth/sentence/replace endpoint that
// re-synths the one sentence and splices the new audio into the
// combined MP3 server-side (#584 — endpoint not built yet, this
// phase uses a stub so we can validate the UX before sinking
// hours into ffmpeg + PCM math).
let _inlineEditingIdx = -1;
let _inlineEditOriginalText = "";
// v4.77 (#878 follow-up): single-flight guard for the splice/Phase-B
// round-trip inside _commitInlineEdit. The async commit can take 10–20 s
// on phone, and the 06-08 15:59 debug log showed every tap during that
// window — sentence reselect (via _paintSelectedSentence's auto-close),
// or a second ✎ tap (via _onEditTextClick's toggle-while-editing) —
// fired ANOTHER concurrent _commitInlineEdit. ~9 redundant commits
// stacked in 21 s before the first one resolved. Now the second and
// later attempts short-circuit until the in-flight commit lands.
let _inlineCommitInFlight = false;

function _onEditTextClick() {
  // v225dk: instrument every branch so the next debug log shows
  // exactly what happened on ✎ tap — entry vs cancel vs full-edit
  // fallback. The 06-03 13:21 log captured zero inline-edit
  // activity, so we can't tell whether the user actually entered
  // edit mode or which branch failed. dlog fixes that blindness.
  if (typeof _dlog === "function") {
    _dlog("inline-edit", "_onEditTextClick fired", {
      editingIdx: _inlineEditingIdx,
      selectedIdx: _selectedSentenceIdx,
      hasSpan:
        typeof _selectedSentenceIdx === "number" &&
        _selectedSentenceIdx >= 0 &&
        !!sentenceSpans[_selectedSentenceIdx],
    });
  }
  // v225dq: Smart ✎ — open/close confirmed working, so we can layer
  // the save behavior back on safely. While editing, tap ✎ to:
  //   • text unchanged → just close (cancel, restores original)
  //   • text changed   → save (splice + commit the new audio)
  // Change detection compares the live textContent against the
  // snapshot taken at entry. The user no longer needs to remember
  // "did I edit or not" — the button does the right thing both ways.
  if (typeof _inlineEditingIdx === "number" && _inlineEditingIdx >= 0) {
    // v4.77 (#878 follow-up): if a commit is already in flight, the ✎
    // tap shouldn't queue another splice — surface a "saving" status
    // and let the in-flight one finish. The phone log showed the user
    // tapping ✎ a second time mid-commit and queuing a duplicate
    // server round-trip, which is what made the first save feel
    // unresponsive.
    if (_inlineCommitInFlight) {
      if (typeof _dlog === "function") {
        _dlog("inline-edit", "toggle-while-editing skipped — commit in flight", {
          editingIdx: _inlineEditingIdx,
        });
      }
      setStatus("Still saving the previous edit…");
      return;
    }
    const editingSpan = sentenceSpans[_inlineEditingIdx];
    const currentText = editingSpan
      ? (editingSpan.textContent || "").trim()
      : "";
    const changed =
      currentText.length > 0 && currentText !== _inlineEditOriginalText;
    if (typeof _dlog === "function") {
      _dlog("inline-edit", "branch: toggle-while-editing", {
        changed,
        currentLen: currentText.length,
        originalLen: _inlineEditOriginalText.length,
      });
    }
    if (changed) {
      _commitInlineEdit();
    } else {
      _cancelInlineEdit();
    }
    return;
  }
  if (
    typeof _selectedSentenceIdx === "number" &&
    _selectedSentenceIdx >= 0 &&
    sentenceSpans[_selectedSentenceIdx]
  ) {
    if (typeof _dlog === "function") {
      _dlog("inline-edit", "branch: enter-inline", {
        idx: _selectedSentenceIdx,
      });
    }
    _enterInlineEdit(_selectedSentenceIdx);
    return;
  }
  // v225dp: edit mode requires a selected sentence — period. No
  // silent fall-through to the full-text editor on any device.
  // Phone learned this lesson first (v225do); applying the same
  // rule on desktop keeps the model consistent: ✎ is "edit the
  // selected sentence." If nothing is selected, the user gets an
  // explicit instruction instead of a confusing surprise. Users
  // who want to edit the whole clip text still have the Clear +
  // re-paste path; we can wire a dedicated full-text-edit button
  // later if anyone asks for it back.
  if (typeof _dlog === "function") {
    _dlog("inline-edit", "branch: hint-no-selection");
  }
  setStatus("Select a sentence first, then tap ✎ to edit it.", true);
}

function _enterInlineEdit(idx) {
  if (typeof _dlog === "function") {
    _dlog("inline-edit", "_enterInlineEdit called", {
      idx,
      currentEditingIdx: _inlineEditingIdx,
      hasSpan: !!sentenceSpans[idx],
    });
  }
  const span = sentenceSpans[idx];
  if (!span) return;
  if (_inlineEditingIdx === idx) return; // already editing this one

  // Cancel any other in-progress edit before starting a new one.
  if (_inlineEditingIdx >= 0) _cancelInlineEdit();

  // Pause playback so the narrator doesn't move on while typing.
  if (playerEl && !playerEl.paused) {
    try { playerEl.pause(); } catch {}
  }
  // If annotate-mode is armed, disarm it — we don't want a stray
  // chip tap to fire an annotation save during text editing.
  if (typeof _setAnnotateMode === "function") {
    try { _setAnnotateMode(false); } catch {}
  }
  // Clear the dashed-ring selection visual — the editing outline
  // replaces it as the "this is the current target" cue.
  if (typeof _clearSelectedSentence === "function") {
    _clearSelectedSentence();
  }

  _inlineEditingIdx = idx;
  _inlineEditOriginalText =
    span.dataset.sentenceText || span.textContent || "";

  span.classList.add("editing");
  // plaintext-only blocks rich-text paste + line breaks — we want
  // the user to edit prose, not a mini-document.
  span.setAttribute("contenteditable", "plaintext-only");
  // Replace any rendered child markup (active-word highlights,
  // attribution color spans, etc.) with the raw sentence text so
  // the contenteditable shows clean prose.
  span.textContent = _inlineEditOriginalText;
  span.focus();

  // Move caret to end of the line so the user can start typing
  // immediately after their last word.
  try {
    const range = document.createRange();
    range.selectNodeContents(span);
    range.collapse(false);
    const sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(range);
  } catch {}

  const onKey = (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      _commitInlineEdit();
    } else if (e.key === "Escape") {
      e.preventDefault();
      _cancelInlineEdit();
    }
  };
  // v225dl: outside-tap-commits is gone. ✎ in the top bar is the
  // single explicit save gesture (commit-if-changed). The previous
  // document-level capture-phase click handler raced with the ✎
  // button's own click — even after the v225dj guard, users reported
  // it still felt wonky. Removing the auto-commit makes the model
  // strictly intentional: type, then tap ✎ to save (or Enter on
  // desktop / Esc to cancel).
  span.addEventListener("keydown", onKey);
  span._editKeyHandler = onKey;

  // v225dq: phone copy reflects Smart ✎ — same button saves if
  // you typed, closes if you didn't. "When done" covers both
  // without needing two separate sentences.
  const _isPhone = window.matchMedia &&
    window.matchMedia("(max-width: 767px)").matches;
  setStatus(
    _isPhone
      ? "Editing sentence — tap ✎ when done."
      : "Editing sentence — Enter to save, Esc to cancel."
  );
}

async function _commitInlineEdit() {
  if (_inlineEditingIdx < 0) return;
  // v4.77 (#878 follow-up): single-flight guard. Belt-and-suspenders —
  // _paintSelectedSentence and _onEditTextClick already gate on this,
  // but any future call site gets the same protection for free here.
  if (_inlineCommitInFlight) {
    if (typeof _dlog === "function") {
      _dlog("inline-edit", "_commitInlineEdit skipped — already in flight", {
        editingIdx: _inlineEditingIdx,
      });
    }
    return;
  }
  const idx = _inlineEditingIdx;
  const span = sentenceSpans[idx];
  if (!span) { _exitInlineEdit(); return; }

  const newText = (span.textContent || "").trim();

  if (!newText) {
    // Empty after edit — treat as cancel rather than save-empty.
    _cancelInlineEdit();
    return;
  }
  if (newText === _inlineEditOriginalText) {
    // No change — just exit silently.
    _exitInlineEdit();
    return;
  }
  // Multi-sentence guard: if the user typed a sentence-ending
  // punct followed by whitespace + capital, we'd have to split
  // and resynth N sentences. v1 enforces single-sentence edits;
  // the user can re-narrate the whole clip for bigger changes.
  if (/[.!?]\s+[A-Z]/.test(newText)) {
    setStatus("Inline edit handles one sentence at a time.", true);
    span.focus();
    return;
  }
  if (!_currentClipId) {
    setStatus("No clip loaded — can't splice audio.", true);
    _cancelInlineEdit();
    return;
  }

  // Mark the span as in-flight so the user sees something happening.
  span.classList.add("editing-saving");
  setStatus("Re-synthesizing edited sentence…");
  // v4.77: set the single-flight gate AFTER all early-return guards but
  // BEFORE the first await. Cleared in finally so we never strand it
  // on an unexpected throw.
  _inlineCommitInFlight = true;

  try {
    // v592 Phase 2 (#585): real splice via /api/synthesize/splice.
    // POST a multipart form: the existing MP3 + a params JSON with
    // voice config + the offset table + new sentence text + index.
    // Server re-synths the one sentence in the matching voice, runs
    // a ffmpeg PCM-domain splice, returns the new MP3 plus an
    // updated offset table (sentences after idx shift by Δ where
    // Δ = new sentence duration − old sentence duration).
    //
    // v225v4.22 (#811 B.7): when the clip has lines populated (Phase A
    // opt-in) AND the per-sentence cache is complete, prefer the
    // Phase B path — synth the one sentence into the cache, then call
    // /restitch to rebuild the combined MP3 from cached FLACs. The
    // re-stitch has no PCM cut seam (because there's no cut — we're
    // re-concatenating clean per-sentence renderings). Falls through
    // to splice.py automatically on any failure (cache miss → 409,
    // missing line_id, etc.), so users without Phase B coverage still
    // get an edit.
    const clip = await getClip(_currentClipId);
    if (!clip || !clip.blob) {
      throw new Error("clip has no audio to splice");
    }
    const offsets = Array.isArray(clip.sentenceOffsetsSec)
      ? clip.sentenceOffsetsSec
      : sentenceOffsetsSec;
    if (!offsets || !offsets.length || idx >= offsets.length) {
      throw new Error(`sentence index ${idx} out of range`);
    }
    const offsetsMs = offsets.map((s) => Math.round(s * 1000));

    const params = {
      voice_id: clip.voiceId || voiceEl.value || null,
      speaker_id:
        typeof clip.speakerId === "number" ? clip.speakerId : null,
      rate: typeof clip.rate === "number" ? clip.rate : null,
      index: idx,
      // v4.91 (#883 follow-up): strip configured symbols pre-synth.
      // v4.90 covered generate() + bg-queue via _openSynthJobStream, but
      // the splice path goes straight through multipart POST without
      // that wrapper. Phase B path below uses _openSynthJobStream
      // already so it strips automatically — only this fallback needs
      // the explicit call. clip.text reconstruction below uses raw
      // newText, so the saved sentence keeps its markdown chars and
      // the reading view stays unchanged.
      text: _stripSynthChars(newText),
      sentence_offsets_ms: offsetsMs,
    };

    // v225v4.22 (#811 B.7): try Phase B first when the clip is
    // opted-in. Either path produces newBlob + newOffsetsMs + (maybe)
    // newSha so the rest of the function is identical.
    let newBlob = null;
    let newOffsetsMs = null;
    let newSha = null;
    let usedPhaseB = false;
    const lineForIdx =
      Array.isArray(clip.lines) &&
      clip.lines.length > idx &&
      clip.lines[idx] &&
      typeof clip.lines[idx].id === "string"
        ? clip.lines[idx].id
        : null;
    if (lineForIdx) {
      try {
        const r = await _phaseBPartialRenarrate({
          clipId: _currentClipId,
          lineId: lineForIdx,
          text: newText,
          voiceId: params.voice_id,
          speakerId: params.speaker_id,
          rate: params.rate,
          expectedOffsetCount: offsets.length,
        });
        if (r) {
          newBlob = r.blob;
          newOffsetsMs = r.offsetsMs;
          newSha = r.sha256;
          usedPhaseB = true;
          _dlog("synth", "Phase B partial re-narrate succeeded", {
            clipId: _currentClipId,
            lineId: lineForIdx,
            newDurMs: r.durationMs,
          });
        }
      } catch (e) {
        // Falls through to splice.py path below. We log so the debug
        // pipeline shows whether B.7 attempts are hitting a backfill
        // gap, a sentence-split mismatch, or an unrelated error.
        _dlog("synth", "Phase B partial re-narrate failed, falling back", {
          clipId: _currentClipId,
          lineId: lineForIdx,
          errMsg: e && e.message,
        });
      }
    }

    if (!usedPhaseB) {
      const fd = new FormData();
      fd.append(
        "audio",
        new File([clip.blob], "clip.mp3", { type: "audio/mpeg" }),
      );
      fd.append("params", JSON.stringify(params));

      const res = await fetch("/api/synthesize/splice", {
        method: "POST",
        body: fd,
      });
      if (!res.ok) {
        let detail = res.statusText;
        try {
          const j = await res.json();
          if (j && j.detail) detail = j.detail;
        } catch {}
        throw new Error(`splice failed (${res.status}): ${detail}`);
      }
      newBlob = await res.blob();
      if (!newBlob || newBlob.size === 0) {
        throw new Error("splice returned empty audio");
      }
      const newOffsetsHeader = res.headers.get("X-Narrative-Sentences");
      newOffsetsMs = newOffsetsHeader ? JSON.parse(newOffsetsHeader) : null;
      newSha = res.headers.get("X-Narrative-Audio-Sha256") || null;
    }

    if (!Array.isArray(newOffsetsMs) || newOffsetsMs.length !== offsets.length) {
      throw new Error("splice returned malformed offsets");
    }
    const newOffsetsSec = newOffsetsMs.map((ms) => ms / 1000);

    // Compute the playhead/bookmark shift before mutating clip state.
    // Δ is the duration change of the edited sentence; everything
    // strictly after the old sentence end shifts by Δ.
    const oldStartSec = offsets[idx];
    const oldEndSec =
      idx + 1 < offsets.length ? offsets[idx + 1] : null;
    const newStartSec = newOffsetsSec[idx];
    const newEndSec =
      idx + 1 < newOffsetsSec.length ? newOffsetsSec[idx + 1] : null;
    const deltaSec =
      oldEndSec != null && newEndSec != null
        ? (newEndSec - oldEndSec)
        : 0;

    // Reconstruct clip.text. Walk the existing spans to find the
    // char offset of sentence idx in the source text, then splice
    // newText in place of _inlineEditOriginalText at that exact
    // position. This preserves paragraph breaks + other whitespace
    // around the edit, which a naive sentences.join(" ") would lose.
    let newClipText = clip.text || "";
    {
      let cursor = 0;
      for (let i = 0; i < idx; i++) {
        const s = sentenceSpans[i] && sentenceSpans[i].dataset.sentenceText;
        if (!s) continue;
        const found = newClipText.indexOf(s, cursor);
        if (found < 0) { cursor = -1; break; }
        cursor = found + s.length;
      }
      if (cursor >= 0) {
        const oldStart = newClipText.indexOf(_inlineEditOriginalText, cursor);
        if (oldStart >= 0) {
          newClipText =
            newClipText.slice(0, oldStart) +
            newText +
            newClipText.slice(oldStart + _inlineEditOriginalText.length);
        }
      }
    }

    // Swap the audio in the player without disrupting the listening
    // session. Capture playhead first so we can restore it after the
    // src reload (which resets currentTime to 0).
    const wasPlaying = !playerEl.paused && !playerEl.ended;
    const oldPlayhead = playerEl.currentTime || 0;
    let newPlayhead = oldPlayhead;
    if (oldEndSec != null && oldPlayhead >= oldEndSec) {
      // After the edit: shift by Δ.
      newPlayhead = Math.max(0, oldPlayhead + deltaSec);
    } else if (oldPlayhead >= oldStartSec) {
      // Inside the edited sentence: pin to the new sentence start
      // so the user hears the replacement immediately.
      newPlayhead = newStartSec;
    }
    // else: before the edit, unchanged.

    if (lastBlobUrl) URL.revokeObjectURL(lastBlobUrl);
    lastBlob = newBlob;
    lastBlobUrl = URL.createObjectURL(newBlob);
    sentenceOffsetsSec = newOffsetsSec.slice();
    playerEl.src = lastBlobUrl;
    // Wait for the player to know its new duration before seeking +
    // optionally resuming. loadedmetadata fires fast for MP3.
    await new Promise((resolve) => {
      const onMeta = () => {
        playerEl.removeEventListener("loadedmetadata", onMeta);
        resolve();
      };
      playerEl.addEventListener("loadedmetadata", onMeta);
      // Safety net in case the event already fired or never does.
      setTimeout(resolve, 1500);
    });
    try { playerEl.currentTime = newPlayhead; } catch {}
    if (wasPlaying) {
      playerEl.play().catch(() => {});
    }

    // v225v4.7 (#810 step 6): if the clip has per-sentence storage on,
    // refresh the matching line in c.lines[] alongside the text/audio
    // update. Splice is 1-sentence-in / 1-sentence-out so the line
    // count and lineId stay stable — only the line's text, hash, and
    // updatedAt change. The atomic-tx + sync layer's per-line LWW
    // merge (#495 + Phase A backend) propagates this to other devices.
    //
    // Hash is computed before entering the mutator so a missing
    // NS_IDS helper fails fast without half-writing. If the clip's
    // line count somehow disagrees with the new sentence count (which
    // shouldn't happen on a splice but a stale state could exist),
    // skip the lines update and dlog it — leaves the lines array as
    // it was rather than corrupting it.
    let _newLineHash = null;
    if (window.NS_IDS && typeof window.NS_IDS.hashText === "function") {
      try {
        _newLineHash = await window.NS_IDS.hashText(newText);
      } catch (e) {
        _dlog("inline-edit", "hashText failed", {
          err: String(e && e.message ? e.message : e),
        });
      }
    }

    // Persist to IDB + push via sync pipeline. Bookmarks get shifted
    // too so they keep pointing at the right spot in the new audio.
    await _mutateClipAtomic(_currentClipId, (c) => {
      c.blob = newBlob;
      c.sentenceOffsetsSec = newOffsetsSec.slice();
      c.text = newClipText;
      c.durationSec = isFinite(playerEl.duration)
        ? playerEl.duration
        : (c.durationSec || 0);
      if (newSha) c.audioSha256 = newSha;
      if (Array.isArray(c.bookmarks) && c.bookmarks.length) {
        c.bookmarks = c.bookmarks.map((bm) => {
          if (typeof bm.time !== "number") return bm;
          if (oldEndSec != null && bm.time >= oldEndSec) {
            return { ...bm, time: Math.max(0, bm.time + deltaSec) };
          }
          if (bm.time >= oldStartSec) {
            return { ...bm, time: newStartSec };
          }
          return bm;
        });
      }
      // Phase A step 6: line storage update.
      if (Array.isArray(c.lines) && c.lines.length > 0 && _newLineHash) {
        if (idx >= 0 && idx < c.lines.length && c.lines[idx]) {
          const now = new Date().toISOString();
          c.lines[idx] = {
            ...c.lines[idx],
            text: newText,
            hash: _newLineHash,
            updatedAt: now,
          };
        } else {
          _dlog("inline-edit", "lines index out of range", {
            idx,
            linesLen: c.lines.length,
            sentencesLen: newOffsetsSec.length,
          });
        }
      }
    });

    // Reflect the new text on the span itself so future reads (e.g.
    // re-render of attribution, char count, save-text) see the
    // edited content. sentenceText is the raw form; originalContent
    // is the HTML scaffold the attribution paint restores to.
    span.dataset.sentenceText = newText;
    span.textContent = newText;
    span.dataset.originalContent = span.innerHTML;

    _exitInlineEdit();
    setStatus("Audio updated.");
  } catch (e) {
    console.warn("[inline-edit] save failed:", e);
    setStatus(_withOfflineHint(`Edit failed — ${e.message || e}. Tap ✎ to retry.`), true);
    span.classList.remove("editing-saving");
    // v225dh: also exit edit mode on failure so the user isn't
    // stranded with a contenteditable sentence and no escape. The
    // original text is restored so the reading view matches the
    // (unchanged) audio. They can re-select the sentence and tap
    // ✎ to try again. Without this, a failed splice left the
    // user permanently stuck per the 2026-06-03 debug log.
    _cancelInlineEdit();
  } finally {
    // v4.77: release the single-flight gate so the next ✎ tap or
    // sentence reselect can fire a fresh commit. Must clear on BOTH
    // success and failure paths — a stuck gate would lock the user
    // out of all future edits in this session.
    _inlineCommitInFlight = false;
  }
}

function _cancelInlineEdit() {
  if (typeof _dlog === "function") {
    _dlog("inline-edit", "_cancelInlineEdit called", {
      editingIdx: _inlineEditingIdx,
    });
  }
  if (_inlineEditingIdx < 0) return;
  const span = sentenceSpans[_inlineEditingIdx];
  if (span) {
    // Restore the original text — the contenteditable change is
    // local until commit, so we just rewrite back.
    span.textContent = _inlineEditOriginalText;
  }
  _exitInlineEdit();
  setStatus("Cancelled.");
}

function _exitInlineEdit() {
  if (typeof _dlog === "function") {
    _dlog("inline-edit", "_exitInlineEdit called", {
      editingIdx: _inlineEditingIdx,
    });
  }
  if (_inlineEditingIdx < 0) return;
  const span = sentenceSpans[_inlineEditingIdx];
  if (span) {
    span.removeAttribute("contenteditable");
    span.classList.remove("editing");
    span.classList.remove("editing-saving");
    if (span._editKeyHandler) {
      span.removeEventListener("keydown", span._editKeyHandler);
      delete span._editKeyHandler;
    }
    if (span._editOutsideHandler) {
      document.removeEventListener(
        "click", span._editOutsideHandler, true,
      );
      delete span._editOutsideHandler;
    }
  }
  _inlineEditingIdx = -1;
  _inlineEditOriginalText = "";
}

editTextBtn.addEventListener("click", _onEditTextClick);

// ---- Book view (M1) ----------------------------------------------------
// v185 (M1): a paginated two-page spread companion to the reading
// view. Same sentence content (we re-render the same text into book-
// shaped pages), same karaoke highlight, same click-to-seek
// semantics — different layout. Pages are computed by an off-screen
// measurement pass so prose breaks on sentence boundaries, never
// mid-sentence.
//
// State:
//   _bookViewSource — {sentences, images, title, cover} stash set by
//     enterReadingView so the book view can paginate the same data
//     without redoing the splitter.
//   _bookViewPages — array of arrays; _bookViewPages[p] is the
//     sentence indices that belong on page p.
//   _bookSentenceToPage — sentence-index -> page-index lookup so
//     highlightCurrentSentence can auto-flip to the active page.
//   _bookSentenceSpans — the actual span elements rendered inside
//     book pages, mirroring sentenceSpans (the reading-view array).
//     Karaoke logic updates both arrays in lockstep.
//   _bookViewCurrentSpread — index of the currently-visible spread
//     (0 = cover + first text page on desktop).
const bookView = $("book-view");
const bookViewSpread = $("book-view-spread");
const bookViewPrev = $("book-view-prev");
const bookViewNext = $("book-view-next");
const bookViewIndicator = $("book-view-indicator");
const bookViewReturn = $("book-view-return");
const bookViewToggle = $("book-view-toggle");
const bookViewPrintBtn = $("book-view-print");
const bookViewTocBtn = $("book-view-toc");
const bookViewTocDialog = $("book-view-toc-dialog");
const bookViewTocList = $("book-view-toc-list");
const bookViewTocClose = $("book-view-toc-close");
// v208 (M6.2/M6.3) refs.
const bookViewFind = $("book-view-find");
const bookViewFindInput = $("book-view-find-input");
const bookViewFindCount = $("book-view-find-count");
const bookViewFindPrev = $("book-view-find-prev");
const bookViewFindNext = $("book-view-find-next");
const bookViewFindClose = $("book-view-find-close");
// v208 (M6.2): flag set while the indicator is in click-to-edit mode
// so _bookViewUpdateNav doesn't clobber the input's value mid-typing.
let _bookViewIndicatorEditing = false;
// v208 (M6.3): current find-mode state. matches is sentence indices.
let _bookViewFindMatches = [];
let _bookViewFindCursor = 0;
// v187: "pinned" state — when the user manually pages (prev/next,
// arrow keys, swipe), suppress the auto-flip-on-active-sentence
// behavior so the spread stays where the reader put it while scanning
// ahead. The "Return to current" button shows whenever the audio's
// active sentence lives on a different spread. Reset to false when
// the user clicks that button or clicks a sentence on the visible
// spread (they're indicating they want to engage here).
let _bookViewUserPaged = false;
let _bookViewSource = null;
let _bookViewPages = [];           // [[sentenceIdx, ...], ...]
let _bookSentenceToPage = [];      // sentenceIdx -> pageIdx
let _bookSentenceSpans = [];       // sentenceIdx -> <span> in book DOM
let _bookViewCurrentSpread = 0;
let _bookViewSpreadsCount = 1;
// Desktop = two-page spread; mobile = single page. We compute this
// per-render from a media query so a window resize across the
// breakpoint just triggers a re-pagination on the next open.
function _bookViewPagesPerSpread() {
  return window.matchMedia("(max-width: 720px)").matches ? 1 : 2;
}

// v200 (M3.2): bucket clip.images by sentence_index. Mirrors the
// reading-view's reading-time logic so the book view places images
// against the same sentence the reading view does. Indexes beyond
// sentences.length collapse to a trailing bucket keyed at
// sentences.length, rendered after the final sentence on the last
// text page.
function _bookViewBucketImages(images, sentenceCount) {
  const m = new Map();
  if (!Array.isArray(images)) return m;
  for (const img of images) {
    if (!img || !img.src) continue;
    const raw = Number(img.sentence_index);
    const idx = Number.isFinite(raw)
      ? Math.max(0, Math.min(sentenceCount, Math.floor(raw)))
      : sentenceCount;
    if (!m.has(idx)) m.set(idx, []);
    m.get(idx).push(img);
  }
  return m;
}

// v200 (M3.2): preload natural dimensions for every image so the
// paginator's probe can reserve correct vertical space — without
// known dimensions, an <img> in the probe contributes 0 to
// scrollHeight until it loads asynchronously, and pagination races
// the network. Resolved-from-cache loads are near-instant on the
// second open since the reading view already fetched these.
// Failed loads stash null so the renderer can drop them.
function _bookViewPreloadImages(images) {
  return new Promise((resolve) => {
    const dims = new Map();
    if (!Array.isArray(images) || !images.length) return resolve(dims);
    let pending = 0;
    for (const img of images) {
      if (!img || !img.src || dims.has(img.src)) continue;
      pending++;
      const probe = new Image();
      probe.onload = () => {
        dims.set(img.src, { width: probe.naturalWidth, height: probe.naturalHeight });
        if (--pending === 0) resolve(dims);
      };
      probe.onerror = () => {
        dims.set(img.src, null);
        if (--pending === 0) resolve(dims);
      };
      probe.src = img.src;
    }
    if (pending === 0) resolve(dims);
  });
}

// v200 (M3.2): make an <img> element for a book-view page, sized
// to fit the page's content area. Explicit width/height attrs make
// the browser allocate the right vertical space immediately — the
// probe doesn't need to wait for the network. Clamp display height
// to half the page so an image never dominates. numColumns isn't
// reflected here yet; magazine 2-column will let images span the
// gutter (CSS column-span: all) instead of squeezing into one col.
function _bookViewMakeImageEl(imgRecord, dims, pageWidth, pageHeight) {
  const el = document.createElement("img");
  el.className = "book-inline-image";
  el.src = imgRecord.src;
  el.alt = imgRecord.alt || "";
  el.decoding = "async";
  el.loading = "eager";
  const d = dims.get(imgRecord.src);
  const contentWidth = pageWidth - 64;  // .book-page padding 32×2
  const maxHeight = Math.round(pageHeight * 0.5);
  // v207 (M5.3): in magazine theme, content flows in 2 columns. By
  // default an image gets column-span: all (spans both columns) which
  // suits chapter-opening figures but is overkill for small inline
  // graphics. Detect "small" via natural width < 1× single column;
  // mark via data-single-col so CSS skips the column-span override
  // and the image renders inside whichever column it landed in.
  const isMagazine =
    bookView && bookView.dataset.bookTheme === "magazine" && pageWidth > 480;
  const singleColumnContentWidth =
    isMagazine ? Math.round((pageWidth - 64 - 24) / 2) : contentWidth;
  if (d && d.width && d.height) {
    // M5.3: route small-in-magazine images into a single column.
    if (isMagazine && d.width < singleColumnContentWidth * 1.1) {
      el.dataset.singleCol = "true";
    }
    const targetMaxWidth = el.dataset.singleCol
      ? singleColumnContentWidth
      : contentWidth;
    const scale = Math.min(1, targetMaxWidth / d.width);
    const displayWidth = Math.round(d.width * scale);
    let displayHeight = Math.round(d.height * scale);
    if (displayHeight > maxHeight) {
      // Letterbox: cap height, scale width to match natural aspect.
      const verticalScale = maxHeight / displayHeight;
      displayHeight = maxHeight;
    }
    el.width = displayWidth;
    el.height = displayHeight;
  } else if (d === null) {
    // Known-failed load. Don't reserve space — renderer will drop.
    el.style.display = "none";
  } else {
    // Unknown dims (image not in preload map). Reserve a placeholder.
    el.height = 240;
  }
  // Failed loads: drop from DOM so they don't leave a void.
  el.addEventListener("error", () => el.remove(), { once: true });
  return el;
}

// v201 (M5.1): overflow predicate. The previous paginator only
// checked vertical overflow via `body.scrollHeight > pageHeight - 1`,
// which works for single-column themes (paperback, manuscript) where
// body's min-height: auto lets it grow past its flex allocation when
// content is too tall. Multi-column themes (magazine) overflow
// DIFFERENTLY: with column-count > 1 + column-fill: auto inside a
// fixed-height flex child, content past the last column extends
// horizontally to the right of the body, so scrollWidth grows but
// scrollHeight stays at clientHeight. The previous check would never
// fire in magazine, and the paginator would pack every sentence on
// page 1 (visually clipped by .book-page overflow: hidden).
//
// The hybrid below catches both cases. The +1 / -1 tolerances absorb
// sub-pixel rounding so a body whose content fits exactly to the
// pixel doesn't get a spurious overflow signal.
function _bookViewBodyOverflows(body, pageHeight) {
  // v225g24 (#721): reverted g16→g23 paginator changes per user
  // request — "roll everything back to when we had it fixed on the
  // desktop." Back to the v201 (M5.1) hybrid check that shipped in
  // v225g15: vertical via scrollHeight > pageHeight (chrome eats
  // ~100px so the last line clips on phone) + horizontal for
  // magazine multi-column overflow. Future fix: rewrite paginator
  // on CSS multi-column or paged.js; do NOT attempt another in-
  // place tweak.
  if (body.scrollHeight > pageHeight - 1) return true;
  if (body.scrollWidth > body.clientWidth + 1) return true;
  return false;
}

// v211 (M7.1): text highlights. Selection within a single .sentence
// span surfaces a floating toolbar; clicking a color saves a highlight
// to clip.highlights[] and re-renders the affected sentence wrapped
// in coloured spans. Works in both book view and reading view —
// _buildSentenceContent() is the shared renderer.
//
// Storage shape: clip.highlights = [{
//   id: number (Date.now() unique key),
//   sentence_index: number,
//   char_start: number, char_end: number,
//   color: "yellow" | "pink" | "blue",
//   createdAt: ISO string,
// }, ...]
//
// Multi-sentence selections are not supported in v1 — the toolbar
// stays hidden. Users adapt quickly; complex multi-span highlight
// math can wait for a later iteration.
const highlightToolbar = $("highlight-toolbar");
let _highlightActiveSelectionInfo = null;

function _getSelectionInsideSentence() {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0 || sel.isCollapsed) return null;
  const range = sel.getRangeAt(0);
  const startEl = range.startContainer.nodeType === Node.TEXT_NODE
    ? range.startContainer.parentElement
    : range.startContainer;
  const endEl = range.endContainer.nodeType === Node.TEXT_NODE
    ? range.endContainer.parentElement
    : range.endContainer;
  if (!startEl || !endEl) return null;
  const sentenceSpan = startEl.closest(".sentence");
  if (!sentenceSpan) return null;
  // Multi-sentence selections: punt for v1.
  if (endEl.closest(".sentence") !== sentenceSpan) return null;
  const sIdx = parseInt(sentenceSpan.dataset.index, 10);
  if (Number.isNaN(sIdx)) return null;
  // Compute offset within the sentence's textContent. The sentence
  // span may contain mixed text + highlight spans (re-rendered). We
  // walk the span's text nodes summing lengths until we hit the
  // range's start/end containers.
  const offsetIn = (container, offset) => {
    let pos = 0;
    const walker = document.createTreeWalker(
      sentenceSpan, NodeFilter.SHOW_TEXT, null
    );
    let node;
    while ((node = walker.nextNode())) {
      if (node === container) return pos + offset;
      pos += node.nodeValue.length;
    }
    return pos;
  };
  let start = offsetIn(range.startContainer, range.startOffset);
  let end = offsetIn(range.endContainer, range.endOffset);
  if (start > end) [start, end] = [end, start];
  if (start === end) return null;
  return {
    sentence_index: sIdx,
    char_start: start,
    char_end: end,
    rect: range.getBoundingClientRect(),
  };
}

function _showHighlightToolbar(info) {
  if (!highlightToolbar || !info) return;
  highlightToolbar.hidden = false;
  // Position above the selection, clipped to viewport.
  const r = info.rect;
  const toolbarH = 36;
  let top = r.top + window.scrollY - toolbarH - 8;
  if (top < window.scrollY + 4) top = r.bottom + window.scrollY + 8;
  let left = r.left + window.scrollX + r.width / 2 - 80;
  if (left < 8) left = 8;
  if (left + 160 > window.innerWidth) left = window.innerWidth - 168;
  highlightToolbar.style.top = `${top}px`;
  highlightToolbar.style.left = `${left}px`;
  _highlightActiveSelectionInfo = info;
}

function _hideHighlightToolbar() {
  if (highlightToolbar) highlightToolbar.hidden = true;
  _highlightActiveSelectionInfo = null;
}

async function _saveHighlight(info, color) {
  if (!_currentClipId) return;
  try {
    // v223.tn19 (#488): atomic so concurrent absorb can't lose annotations.
    const clip = await _mutateClipAtomic(_currentClipId, (c) => {
      if (!Array.isArray(c.highlights)) c.highlights = [];
      if (color === null) {
        // Remove: drop any highlight that overlaps the selected range
        // on the same sentence. v1: simple inclusive overlap check.
        c.highlights = c.highlights.filter((h) =>
          !(h.sentence_index === info.sentence_index &&
            h.char_end > info.char_start && h.char_start < info.char_end)
        );
      } else {
        c.highlights.push({
          id: Date.now(),
          sentence_index: info.sentence_index,
          char_start: info.char_start,
          char_end: info.char_end,
          color,
          createdAt: new Date().toISOString(),
        });
      }
    });
    if (!clip) return;
    // Re-render affected views.
    if (sentenceSpans && sentenceSpans[info.sentence_index]) {
      const span = sentenceSpans[info.sentence_index];
      span.innerHTML = _buildSentenceContentHTML(
        _bookViewSource && _bookViewSource.sentences
          ? _bookViewSource.sentences[info.sentence_index]
          : span.textContent.replace(/ $/, ""),
        info.sentence_index,
        clip.highlights
      );
    }
    if (typeof bookView !== "undefined" && bookView && !bookView.hidden) {
      if (_bookViewSource) _bookViewSource.highlights = clip.highlights;
      _bookViewRenderSpread(_bookViewCurrentSpread);
    }
  } catch (e) {
    console.warn("highlight save failed:", e);
  }
}

// Build the HTML for a sentence span's content, with any highlight
// ranges wrapped in <span class="text-highlight" data-color="...">.
// Used by both book-view sentence rendering and reading-view sentence
// rendering. Returns a string of innerHTML (caller assigns to span).
// Highlights are clamped to the sentence's text bounds + de-overlapped
// by selecting the latest highlight on overlap (last-write-wins).
function _buildSentenceContentHTML(text, sentenceIdx, highlights) {
  const myHighlights = (Array.isArray(highlights) ? highlights : [])
    .filter((h) => h.sentence_index === sentenceIdx)
    .map((h) => ({
      ...h,
      char_start: Math.max(0, Math.min(text.length, h.char_start)),
      char_end: Math.max(0, Math.min(text.length, h.char_end)),
    }))
    .filter((h) => h.char_end > h.char_start)
    .sort((a, b) => a.char_start - b.char_start || b.id - a.id);
  if (!myHighlights.length) {
    return _escapeHtmlForSentence(text);
  }
  // Walk text + highlight starts/ends, emitting either plain text or
  // wrapped highlight segments. Skip overlapping highlights past the
  // first one on a position.
  const out = [];
  let cursor = 0;
  for (const h of myHighlights) {
    if (h.char_start < cursor) continue;  // overlaps previously-emitted
    if (h.char_start > cursor) {
      out.push(_escapeHtmlForSentence(text.slice(cursor, h.char_start)));
    }
    out.push(
      `<span class="text-highlight" data-color="${h.color}">` +
      _escapeHtmlForSentence(text.slice(h.char_start, h.char_end)) +
      `</span>`
    );
    cursor = h.char_end;
  }
  if (cursor < text.length) {
    out.push(_escapeHtmlForSentence(text.slice(cursor)));
  }
  return out.join("");
}

function _escapeHtmlForSentence(s) {
  return String(s || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

// Wire selection listeners + toolbar buttons.
document.addEventListener("pointerup", (e) => {
  // Defer to next tick so the selection is finalized.
  setTimeout(() => {
    // Ignore if the pointerup was inside the toolbar (color click).
    if (highlightToolbar && highlightToolbar.contains(e.target)) return;
    const info = _getSelectionInsideSentence();
    if (info) {
      _showHighlightToolbar(info);
    } else {
      _hideHighlightToolbar();
    }
  }, 0);
});
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && highlightToolbar && !highlightToolbar.hidden) {
    _hideHighlightToolbar();
  }
});

// ──────────────────────────────────────────────────────────────────────
// v223.annotate-1: Phone-native revision annotations.
//
// See STRATEGY.md "Phone-native annotation" section for the design
// rationale + anchor model. Short version: every annotation is anchored
// to (clipId, sentenceIndex) with a sentenceFingerprint snapshot so we
// can detect if the sentence text shifted underneath it after a re-
// narrate. The annotation lives in clip.annotations[] and syncs cross-
// device via the existing saveClip wrapper.
//
// This slice (annotate-1) ships:
//   - data model + helpers (_addAnnotation / _removeAnnotation / etc)
//   - "Annotate mode" toggle chip in the player row
//   - tap-on-sentence-in-reading-view → palette of 6 tags → flag
//   - sentence-marker dot rendered on annotated sentences
//   - cross-device sync via saveClip (no new server endpoints needed —
//     annotations[] just rides on the clip row's existing JSON payload)
//
// Deferred to later annotate-* slices:
//   - review/resolve mode (annotate-3)
//   - jump-between-flags chip (annotate-2)
//   - voice notes (annotate-4)
//   - reanchor logic on re-narrate
//   - full gesture system (long-press, swipe)
// ──────────────────────────────────────────────────────────────────────

const annotateModeBtn = $("annotate-mode-btn");
const annotatePalette = $("annotate-palette");
const annotatePaletteHint = $("annotate-palette-hint");
const annotatePaletteClose = $("annotate-palette-close");
let _annotateMode = false;
let _annotatePendingSentenceIndex = null;
// v223.tn14: pause main playback while the palette is open so the
// narrator doesn't race past the sentence the user is contemplating.
// Resume on palette close — only if playback was actually running
// before the tap. Switching from one sentence to another while the
// palette is already open does NOT re-snapshot (would lose the "was
// playing" state).
let _annotateWasPlayingBeforePalette = false;

// Default tag → label mapping for the six starter chips. Keep in sync
// with the data-tag attributes on the buttons in index.html.
// v223.tn21 (#491): icon column added so _applyAnnotationMarkers can
// render inline tag chips on annotated sentences — answers "what was
// the annotation?" without requiring annotate mode or a refresh.
const ANNOTATE_TAGS = {
  cut:    { label: "Cut",    color: "#e57373", icon: "✂" },
  fact:   { label: "Fact",   color: "#64b5f6", icon: "✓" },
  weak:   { label: "Weak",   color: "#ffb74d", icon: "⚠" },
  pov:    { label: "POV",    color: "#ba68c8", icon: "👁" },
  expand: { label: "Expand", color: "#81c784", icon: "➕" },
  love:   { label: "Love",   color: "#f06292", icon: "❤" },
};

// Lightweight UUIDv4-ish — doesn't need to be cryptographically random,
// just unique within a tenant + clip. Date.now() + 8 random hex chars
// gives us collision-free ids for any realistic library size.
function _annotateNewId() {
  const r = Math.random().toString(16).slice(2, 10);
  return `a_${Date.now().toString(36)}_${r}`;
}

// Fingerprint = first 60 chars of the sentence at flag time. Used
// during reanchor-on-re-narrate to detect "this sentence has moved or
// changed." 60 chars is enough to distinguish near-duplicates while
// staying cheap to compare.
function _annotateFingerprint(sentenceText) {
  return (sentenceText || "").trim().slice(0, 60);
}

// Read annotations off a clip. Always returns an array; treats
// missing / non-array as empty.
function _listAnnotations(clip) {
  return Array.isArray(clip && clip.annotations) ? clip.annotations : [];
}

// Append an annotation to a clip and persist atomically. Uses a single
// readwrite IDB transaction so a concurrent writer (most often the
// playback progress tick) can't read its own stale pre-annotation
// snapshot and clobber the new annotation on its own write. IDB
// serializes readwrite transactions on the same object store, so once
// this tx commits, the next progress save's read sees the annotation
// and preserves it. Also pushes after the tx completes, so the server
// receives the updated clip with annotations populated.
async function _addAnnotation(clipId, anno) {
  try {
    const db = await openDB();
    const tx = db.transaction(STORE, "readwrite");
    const store = tx.objectStore(STORE);
    const clip = await idbReq(store.get(clipId));
    if (!clip) return null;
    const annotations = Array.isArray(clip.annotations)
      ? clip.annotations.slice()
      : [];

    // v585: one annotation per sentence (hard limit). If a live
    // (non-tombstoned) annotation already exists on this
    // sentenceIndex, REPLACE its tag-bearing fields rather than
    // pushing a second record. We preserve:
    //   - id (so the row's stable identity survives — deletes,
    //     server-side merges, and chip click handlers all key off
    //     this id)
    //   - any voice-note audio + transcript on the existing
    //     annotation that the incoming record doesn't bring
    //     itself. A user retagging a sentence shouldn't lose the
    //     voice recording attached to it.
    //
    // Net behavior:
    //   tag → sentence with no anno   → push (new annotation)
    //   tag → sentence with an anno   → swap tags in place
    //   voice → sentence with anno    → replace tags + audio + transcript
    //   voice → sentence with no anno → push (new voice annotation)
    //
    // The {...existing, ...incoming, id: existing.id} order means
    // every incoming field that's PRESENT wins, but absent fields
    // (e.g. tag-only inputs don't include `audio`) fall through to
    // existing. That's the preserve-voice-note-on-retag semantic.
    let merged = false;
    if (anno && typeof anno.sentenceIndex === "number") {
      const existingIdx = annotations.findIndex(
        (a) =>
          a &&
          a.sentenceIndex === anno.sentenceIndex &&
          !a.deletedAt,
      );
      if (existingIdx >= 0) {
        const existing = annotations[existingIdx];
        annotations[existingIdx] = {
          ...existing,
          ...anno,
          id: existing.id,
        };
        merged = true;
      }
    }
    if (!merged) {
      annotations.push(anno);
    }
    clip.annotations = annotations;
    clip.updatedAt = new Date().toISOString();
    await idbReq(store.put(clip));
    await new Promise((res, rej) => {
      tx.oncomplete = res;
      tx.onerror = () => rej(tx.error);
      tx.onabort = () => rej(tx.error);
    });
    if (typeof _syncPushClip === "function") {
      _syncPushClip(clip).catch((e) =>
        console.warn("[sync] push failed:", e),
      );
    }
    // v223.tn25 (#497): live-paint the new annotation. Previously the
    // tag-only call site flipped data-has-annotation manually to show
    // the dot, but the inline tag chip (cut/fact/love icon) wasn't
    // injected until the next loadClip rebuild — so the dot would
    // sit there orphaned until refresh. The reconciler handles
    // every marker type (dot, tag chip, voice ▶, transcript, ↻
    // retry) in one pass; calling it here keeps add/remove/edit
    // visually consistent regardless of which caller is mutating.
    if (
      _currentClipId === clipId &&
      typeof _applyAnnotationMarkers === "function"
    ) {
      try { _applyAnnotationMarkers(clip); } catch (e) {
        console.warn("[annotate] post-add repaint failed:", e);
      }
    }
    return anno;
  } catch (e) {
    console.warn("[annotate] add failed:", e);
    return null;
  }
}

// Remove by id. Returns true on success. Same atomic-tx pattern as add.
async function _removeAnnotation(clipId, annoId) {
  try {
    const db = await openDB();
    const tx = db.transaction(STORE, "readwrite");
    const store = tx.objectStore(STORE);
    const clip = await idbReq(store.get(clipId));
    if (!clip) return false;
    const before = Array.isArray(clip.annotations) ? clip.annotations : [];
    const after = before.filter((a) => a && a.id !== annoId);
    if (after.length === before.length) return false;
    clip.annotations = after;
    clip.updatedAt = new Date().toISOString();
    await idbReq(store.put(clip));
    await new Promise((res, rej) => {
      tx.oncomplete = res;
      tx.onerror = () => rej(tx.error);
      tx.onabort = () => rej(tx.error);
    });
    if (typeof _syncPushClip === "function") {
      _syncPushClip(clip).catch((e) =>
        console.warn("[sync] push failed:", e),
      );
    }
    // v223.tn25 (#497): live-repaint after delete — drop the chip,
    // dot, voice ▶, transcript, ↻ retry, whichever was rendered.
    if (
      _currentClipId === clipId &&
      typeof _applyAnnotationMarkers === "function"
    ) {
      try { _applyAnnotationMarkers(clip); } catch (e) {
        console.warn("[annotate] post-remove repaint failed:", e);
      }
    }
    return true;
  } catch (e) {
    console.warn("[annotate] remove failed:", e);
    return false;
  }
}

// v223.tn26 (#498): tombstone-based delete. After #495 the server
// merges incoming annotations against stored — a stale push with a
// shorter array no longer wipes anything. To actually propagate a
// delete cross-device, the client must set `deletedAt` on the
// specific annotation: that survives the merge, and the server's
// GET response filters tombstoned entries before returning so the
// client never sees ghost data. The reconciler filters them too in
// case a local repaint runs before the server round-trip lands.
//
// We don't reuse _removeAnnotation (which array-filters) because
// (a) its push would no longer reach the server's merge intent, and
// (b) we want the tombstone in local IDB too so a re-open of the
// app doesn't re-show the dot.
async function _tombstoneAnnotation(clipId, annoId) {
  try {
    const db = await openDB();
    const tx = db.transaction(STORE, "readwrite");
    const store = tx.objectStore(STORE);
    const clip = await idbReq(store.get(clipId));
    if (!clip) return false;
    const list = Array.isArray(clip.annotations) ? clip.annotations.slice() : [];
    const idx = list.findIndex((a) => a && a.id === annoId);
    if (idx === -1) return false;
    const now = new Date().toISOString();
    // Replace with a shallow copy so the array element identity
    // changes — defensive against any code that holds a reference
    // and might still think it's live.
    list[idx] = { ...list[idx], deletedAt: now, updatedAt: now };
    clip.annotations = list;
    clip.updatedAt = now;
    await idbReq(store.put(clip));
    await new Promise((res, rej) => {
      tx.oncomplete = res;
      tx.onerror = () => rej(tx.error);
      tx.onabort = () => rej(tx.error);
    });
    if (typeof _syncPushClip === "function") {
      _syncPushClip(clip).catch((e) =>
        console.warn("[sync] push failed:", e),
      );
    }
    if (
      _currentClipId === clipId &&
      typeof _applyAnnotationMarkers === "function"
    ) {
      try { _applyAnnotationMarkers(clip); } catch (e) {
        console.warn("[annotate] post-tombstone repaint failed:", e);
      }
    }
    return true;
  } catch (e) {
    console.warn("[annotate] tombstone failed:", e);
    return false;
  }
}

// v225.tn82 (#564): tap-reveal inline × on a flag chip. The chip
// itself stays a clean icon. First tap → seek (existing behavior)
// AND reveal an × badge beside the chip for ~4 seconds. Tap × to
// remove the annotation. Tap the chip again to reset the timer.
//
// Picked over an always-on × (the voice-note pattern) because flag
// chips can be dense — a chapter with 15 flagged sentences would
// gain 15 visible × buttons. Tap-reveal keeps the reading view
// clean while making delete one tap to discover.
//
// The long-press → action-sheet path stays as a fallback (bulletproofed
// in v225.tn80–81). Same `_tombstoneAnnotation` call inside either way.
let _revealedChipDelete = null;
let _revealedChipDeleteTimer = null;
const _CHIP_DELETE_REVEAL_MS = 4000;

function _hideChipDeleteReveal() {
  if (_revealedChipDeleteTimer) {
    clearTimeout(_revealedChipDeleteTimer);
    _revealedChipDeleteTimer = null;
  }
  if (_revealedChipDelete) {
    _revealedChipDelete.remove();
    _revealedChipDelete = null;
  }
}

function _revealChipDelete(chip) {
  // Only one × at a time across the whole reading view.
  _hideChipDeleteReveal();
  if (!chip || !chip.dataset || !chip.dataset.annoId) return;
  const aid = chip.dataset.annoId;
  const xBtn = document.createElement("button");
  xBtn.type = "button";
  xBtn.className = "annotate-tag-delete";
  xBtn.textContent = "×";
  xBtn.title = "Remove flag";
  xBtn.setAttribute("aria-label", "Remove flag");
  // Stop pointer events from leaking to the parent sentence (drag-
  // to-select voice assign) or the chip's own handlers.
  xBtn.addEventListener("pointerdown", (e) => e.stopPropagation());
  xBtn.addEventListener("pointerup", (e) => e.stopPropagation());
  xBtn.addEventListener("pointermove", (e) => e.stopPropagation());
  xBtn.addEventListener("contextmenu", (e) => e.preventDefault());
  xBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    e.preventDefault();
    _dlog("flag-chip", "inline × tapped", { aid });
    _hideChipDeleteReveal();
    _tombstoneAnnotation(_currentClipId, aid)
      .then((ok) => {
        if (ok) setStatus("Flag removed.");
      })
      .catch((err) => console.warn("[annotate] inline-delete failed:", err));
  });
  chip.insertAdjacentElement("afterend", xBtn);
  _revealedChipDelete = xBtn;
  _revealedChipDeleteTimer = setTimeout(_hideChipDeleteReveal, _CHIP_DELETE_REVEAL_MS);
  _dlog("flag-chip", "× revealed", { aid });
}

// Tiny action-sheet popup. Anchored just below the tapped element so
// it doesn't reflow the reading view. Outside-click dismiss; Esc
// dismiss. Used by the tag-chip-tap and voice-× paths to confirm
// destructive actions inline without a full modal.
function _showAnnoActionSheet(anchor, label, onConfirm) {
  // Tear down any prior sheet — at most one open at a time.
  const prior = document.querySelector(".anno-action-sheet");
  if (prior) prior.remove();

  const sheet = document.createElement("div");
  sheet.className = "anno-action-sheet";
  const removeBtn = document.createElement("button");
  removeBtn.type = "button";
  removeBtn.className = "anno-action-remove";
  removeBtn.textContent = label || "Remove";
  const cancelBtn = document.createElement("button");
  cancelBtn.type = "button";
  cancelBtn.className = "anno-action-cancel";
  cancelBtn.textContent = "Cancel";
  sheet.appendChild(removeBtn);
  sheet.appendChild(cancelBtn);
  document.body.appendChild(sheet);

  // Position below the anchor; clamp to viewport so an edge-chip
  // doesn't push the sheet off-screen.
  const rect = anchor.getBoundingClientRect();
  const sheetRect = sheet.getBoundingClientRect();
  let top = rect.bottom + window.scrollY + 4;
  let left = rect.left + window.scrollX;
  const maxLeft = window.scrollX + window.innerWidth - sheetRect.width - 8;
  if (left > maxLeft) left = maxLeft;
  if (left < window.scrollX + 8) left = window.scrollX + 8;
  sheet.style.top = `${top}px`;
  sheet.style.left = `${left}px`;
  // v225.tn80 (#562): instrument the action sheet so we can diagnose
  // "Remove flag takes two taps." Need to see where the sheet
  // lands, which element each tap hits, and whether the bubble
  // handler ever fires.
  _dlog("action-sheet", "opened", {
    label,
    anchorRect: { top: rect.top, left: rect.left, bottom: rect.bottom, right: rect.right },
    sheetPos: { top, left, w: sheetRect.width, h: sheetRect.height },
    viewport: { w: window.innerWidth, h: window.innerHeight },
  });

  const cleanup = () => {
    sheet.remove();
    document.removeEventListener("click", dismissOnOutside, true);
    document.removeEventListener("keydown", dismissOnEsc);
  };
  // v225.tn80 (#562): also treat the anchor (and its descendants) as
  // "inside." On touch devices, releasing a long-press fires a
  // synthetic click on the anchor chip *after* this listener is
  // attached. Without the anchor exemption, that synthetic click
  // hits the document in capture phase, `sheet.contains(chip)` is
  // false, and the sheet closes immediately. User then sees no
  // sheet and has to tap (or long-press) a second time. Reported
  // as "have to tap Remove flag twice."
  const dismissOnOutside = (e) => {
    if (sheet.contains(e.target)) return;
    if (anchor && (anchor === e.target || (anchor.contains && anchor.contains(e.target)))) {
      _dlog("action-sheet", "ignored click on anchor", {
        tag: e.target && e.target.tagName,
      });
      return;
    }
    _dlog("action-sheet", "dismissed by outside click", {
      tag: e.target && e.target.tagName,
      cls: e.target && e.target.className,
    });
    e.stopPropagation();
    cleanup();
  };
  const dismissOnEsc = (e) => {
    if (e.key === "Escape") { e.stopPropagation(); cleanup(); }
  };
  // v225.tn83 (#565): switch button activation from `click` to
  // `pointerup`. The v225bm log confirmed that on Android, the
  // first tap on Remove fires pointerdown without a paired click
  // — almost certainly because of the now-removed :hover CSS
  // triggering the "first tap = hover, second tap = activate"
  // dance. We keep `click` as a parallel handler for keyboard /
  // accessibility, and use a `fired` latch so we don't double-
  // confirm if both fire.
  let _removeFired = false;
  let _cancelFired = false;
  const _runRemove = (via) => {
    if (_removeFired) return;
    _removeFired = true;
    _dlog("action-sheet", `remove via ${via}`, { label });
    cleanup();
    Promise.resolve(onConfirm()).catch((err) =>
      console.warn("[annotate] action-sheet confirm failed:", err),
    );
  };
  const _runCancel = (via) => {
    if (_cancelFired) return;
    _cancelFired = true;
    _dlog("action-sheet", `cancel via ${via}`);
    cleanup();
  };
  removeBtn.addEventListener("pointerdown", (e) => {
    e.stopPropagation();
    _dlog("action-sheet", "remove pointerdown", { x: e.clientX, y: e.clientY });
  });
  cancelBtn.addEventListener("pointerdown", (e) => {
    e.stopPropagation();
    _dlog("action-sheet", "cancel pointerdown", { x: e.clientX, y: e.clientY });
  });
  // pointerup is the reliable touch-activation path on mobile —
  // it fires regardless of whether the browser's gesture
  // recognizer would have suppressed the synthetic click.
  removeBtn.addEventListener("pointerup", (e) => {
    e.stopPropagation();
    _runRemove("pointerup");
  });
  cancelBtn.addEventListener("pointerup", (e) => {
    e.stopPropagation();
    _runCancel("pointerup");
  });
  // Click is the keyboard / a11y fallback. If pointerup already
  // fired, the latch swallows this safely.
  removeBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    _runRemove("click");
  });
  cancelBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    _runCancel("click");
  });
  // Defer the outside-click listener so the click that opened the
  // sheet doesn't immediately close it.
  setTimeout(() => {
    document.addEventListener("click", dismissOnOutside, true);
    document.addEventListener("keydown", dismissOnEsc);
  }, 0);
}

// Toggle annotate mode. Updates the button's aria-pressed for screen
// readers, swaps the body data attribute so CSS can shift the
// sentence cursor + hover, and stashes the pref in localStorage so
// the mode survives reload.
function _setAnnotateMode(on) {
  _annotateMode = !!on;
  // v225.tn68 (#550): log every flip with a stack snippet so we can
  // see exactly which caller turned annotate mode on/off and why.
  // Diagnoses the "tag menu opens on every sentence tap" report:
  // helps us correlate stuck-mode with the specific user gesture
  // that left it that way.
  _dlog("annotate", "_setAnnotateMode", {
    on: _annotateMode,
    stack: new Error().stack?.split("\n").slice(1, 5).join(" | "),
  });
  if (annotateModeBtn) {
    annotateModeBtn.setAttribute("aria-pressed", _annotateMode ? "true" : "false");
  }
  document.body.dataset.annotateMode = _annotateMode ? "on" : "off";
  try {
    localStorage.setItem("narrative.annotateMode", _annotateMode ? "1" : "0");
  } catch {}
  if (!_annotateMode) _hideAnnotatePalette();
  setStatus(
    _annotateMode
      ? "Annotate mode on — tap a sentence to flag it."
      : "Annotate mode off."
  );
}

function _hideAnnotatePalette() {
  if (!annotatePalette) return;
  // v223.annotate-4: if a recording is in flight when the palette
  // closes (user tapped × or Esc, or moved to a different sentence),
  // discard the partial buffer + release the mic. Otherwise the
  // recorder would keep streaming and re-fire its onstop into a
  // sentence that's no longer "pending."
  if (typeof _voiceRecorder !== "undefined" && _voiceRecorder) {
    try {
      if (typeof _voiceTimerInterval !== "undefined" && _voiceTimerInterval) {
        clearInterval(_voiceTimerInterval); _voiceTimerInterval = null;
      }
      if (typeof _voiceAutoStopTimer !== "undefined" && _voiceAutoStopTimer) {
        clearTimeout(_voiceAutoStopTimer); _voiceAutoStopTimer = null;
      }
      if (typeof _voiceStopTranscription === "function") _voiceStopTranscription();
      _voiceRecorder.onstop = null;
      if (_voiceRecorder.state !== "inactive") _voiceRecorder.stop();
    } catch {}
    _voiceReleaseStream();
  }
  if (typeof _voiceShowTagRow === "function") _voiceShowTagRow();
  annotatePalette.hidden = true;
  _annotatePendingSentenceIndex = null;
  // v223.tn14: resume main playback if we paused it on palette open
  // (and it was playing pre-pause). Mirrors the voice-record
  // pause/resume pattern from #471 but covers every palette
  // interaction, not just the 🎤 button.
  if (_annotateWasPlayingBeforePalette && playerEl) {
    try { playerEl.play().catch(() => {}); } catch {}
  }
  _annotateWasPlayingBeforePalette = false;
}

function _showAnnotatePalette(sentenceIndex, sentenceText) {
  if (!annotatePalette) return;
  // v223.tn14: snapshot playback state + pause on FIRST open. Tapping
  // a different sentence while the palette is already up is a switch,
  // not a fresh open — don't re-snapshot (would clobber the "was
  // playing" flag with `paused === true`, since we paused it on the
  // first open) and don't re-pause (already paused).
  const wasHidden = !!annotatePalette.hidden;
  if (wasHidden && playerEl && !playerEl.paused) {
    _annotateWasPlayingBeforePalette = true;
    try { _pauseAsUser(); } catch { try { playerEl.pause(); } catch {} }
  }
  _annotatePendingSentenceIndex = sentenceIndex;
  // v223.annotate-4: starting a new sentence's palette resets the
  // record sub-view back to the tag row, so a stale "Recording…"
  // overlay doesn't bleed across switches.
  if (typeof _voiceShowTagRow === "function") _voiceShowTagRow();
  if (annotatePaletteHint) {
    const snippet = (sentenceText || "").trim().slice(0, 60);
    annotatePaletteHint.textContent = snippet
      ? `Flag: "${snippet}${sentenceText.length > 60 ? "…" : ""}"`
      : "Pick a tag to flag this sentence";
  }
  annotatePalette.hidden = false;
}

// Annotate mode no longer persists across reloads — on ANY tier.
//
// v225.tn69 (#551) skipped the restore on phone but kept it on desktop.
// That left desktop (and tablet) users with annotate mode silently ON
// from localStorage, where a capture-phase listener intercepts every
// sentence click and opens the annotate palette instead of seeking —
// the exact stuck state #551 fixed, just on the wider tiers. Annotate
// mode is only meaningful paired with an in-memory armed tag (which
// never survives a reload), so restoring the bare flag is never useful.
// It's now a deliberate per-session choice: click the Annotate button to
// enter it. Boot always starts OFF; sentence clicks seek + play by
// default everywhere.
try {
  if (localStorage.getItem("narrative.annotateMode") === "1") {
    // Clear the stale persisted flag so we don't dlog this every reload.
    try { localStorage.setItem("narrative.annotateMode", "0"); } catch {}
    _dlog("annotate", "boot: not restoring annotate mode (per-session only)");
  }
  document.body.dataset.annotateMode = "off";
} catch {}

if (annotateModeBtn) {
  annotateModeBtn.addEventListener("click", () => {
    _setAnnotateMode(!_annotateMode);
  });
}

// Palette tag click → create the annotation, mark the sentence,
// dismiss the palette.
if (annotatePalette) {
  annotatePalette.addEventListener("click", async (event) => {
    const closeBtn = event.target.closest("#annotate-palette-close");
    if (closeBtn) {
      _hideAnnotatePalette();
      return;
    }
    const tagBtn = event.target.closest(".annotate-tag-btn");
    if (!tagBtn) return;
    const tag = tagBtn.dataset.tag;
    if (!tag || !ANNOTATE_TAGS[tag]) return;
    const sentenceIndex = _annotatePendingSentenceIndex;
    if (sentenceIndex == null) {
      _hideAnnotatePalette();
      return;
    }
    // Pull the sentence text from the DOM span so the fingerprint is
    // exactly what the user saw at flag time. Falls back to "" if the
    // span vanished (rare race during re-render).
    const span = sentenceSpans && sentenceSpans[sentenceIndex];
    const sentenceText = span ? span.textContent : "";
    if (!_currentClipId) {
      setStatus("Load a clip first to flag a sentence.", true);
      _hideAnnotatePalette();
      return;
    }
    const anno = {
      id: _annotateNewId(),
      sentenceIndex,
      sentenceFingerprint: _annotateFingerprint(sentenceText),
      flaggedAt: new Date().toISOString(),
      source: "tap",
      tags: [tag],
    };
    await _addAnnotation(_currentClipId, anno);
    // Visual marker — flip the data attribute so the CSS dot shows
    // up immediately, without waiting for a full reading-view rebuild.
    if (span) span.dataset.hasAnnotation = "true";
    _hideAnnotatePalette();
    setStatus(`✓ Flagged sentence ${sentenceIndex + 1} as "${ANNOTATE_TAGS[tag].label}".`);
  });
}

if (annotatePaletteClose) {
  annotatePaletteClose.addEventListener("click", _hideAnnotatePalette);
}

// Esc dismisses the palette like every other dialog in the app.
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && annotatePalette && !annotatePalette.hidden) {
    _hideAnnotatePalette();
  }
});

// Reading-view sentence intercept. When annotate mode is on, a click
// on a sentence opens the palette instead of seeking. Capture phase
// + stopPropagation so we get to the event before the existing seek-
// on-tap handler (which lives in the same reading view container).
const readingViewEl = document.getElementById("reading-view");
if (readingViewEl) {
  // v225.tn71 (#553): coarse-grained pointerdown logger so we can
  // see WHAT the user is actually tapping when "tap a flag" reports
  // come in with no flag-chip dlog entries. Logs the target's tag +
  // class + first few chars of text content. Capture phase so we
  // catch the event even if downstream handlers stopPropagation.
  readingViewEl.addEventListener(
    "pointerdown",
    (e) => {
      const t = e.target;
      if (!t || !t.tagName) return;
      _dlog("reading-view", "pointerdown target", {
        tag: t.tagName,
        cls: t.className && typeof t.className === "string"
          ? t.className.slice(0, 60)
          : "",
        textHead: (t.textContent || "").trim().slice(0, 40),
        hasAnnoId: !!(t.dataset && t.dataset.annoId),
      });
    },
    true, // capture so we see it first
  );
  readingViewEl.addEventListener(
    "click",
    (event) => {
      if (!_annotateMode) return;
      const span = event.target.closest(".sentence");
      if (!span) return;
      const idx = Number(span.dataset.index);
      if (!isFinite(idx)) return;

      // v4.73: short-circuit on the inline voice-note control buttons so
      // they keep working when annotate-mode is on. The ▶ / ↻ / × buttons
      // render INSIDE the sentence span (so the user can act on a note
      // without dropping out of reading flow). Without this guard, this
      // capture-phase handler calls preventDefault + stopPropagation
      // BELOW and the buttons' own click handlers never run — symptom
      // diagnosed from the 2026-06-08 desktop debug log where the user
      // clicked ▶ 20+ times, ↻ 15+ times, × 10+ times in annotate-mode
      // and every click logged "[annotate] reading-view click" without
      // ever firing the underlying button. Phone has #551's auto-disarm
      // for this; desktop has no escape hatch until now. We also pass on
      // any other button.annotate-voice-* class in case future inline
      // voice-note controls get added (cluster is action-prefixed by
      // convention).
      const inlineVoiceCtrl = event.target.closest(
        "button.annotate-voice-play, button.annotate-voice-retry, " +
          "button.annotate-voice-delete, button[class*=\"annotate-voice-\"]"
      );
      if (inlineVoiceCtrl) {
        _dlog("annotate", "skip — inline voice-note control click", {
          idx,
          cls: inlineVoiceCtrl.className,
        });
        return; // bubble through to the button's own handler
      }

      const isPhone = window.matchMedia("(max-width: 767px)").matches;
      const hasArmedTag =
        typeof _phoneTagRowArmedTag !== "undefined" && !!_phoneTagRowArmedTag;
      _dlog("annotate", "reading-view click", {
        idx,
        annotateMode: _annotateMode,
        hasArmedTag,
        isPhone,
      });

      // v225.tn68 (#550): on phone with no armed tag, fall through to
      // seek. The phone has no visible annotate-mode toggle (#520
      // removed it from the pull-up Author section), so once mode
      // was stuck "on" — usually because the user tapped a tag chip
      // and then changed their mind without applying — every
      // sentence tap opened the palette with no exit. Now: phone +
      // no armed tag = auto-disarm + let the normal seek handler
      // fire. Tag-row arm-and-apply is the ONLY annotate path on
      // phone, which is what the post-v225.tn39 UX intended anyway.
      if (isPhone && !hasArmedTag) {
        if (typeof _setAnnotateMode === "function") {
          _setAnnotateMode(false);
        }
        _dlog("annotate", "auto-disarm: phone + no armed tag → seek");
        return; // no stopPropagation → the seek handler runs
      }

      event.preventDefault();
      event.stopPropagation();
      // v225.tn39 (#516): if a tag chip is armed from the bottom
      // tag row, short-circuit the palette and apply directly.
      // This is the "1-tap chip → 1-tap sentence" fast path the
      // double-deck design was built for.
      if (
        hasArmedTag &&
        typeof _phoneTagRowApplyArmedToSentence === "function"
      ) {
        if (_phoneTagRowApplyArmedToSentence(idx, span.textContent || "")) {
          return;
        }
      }
      _showAnnotatePalette(idx, span.textContent || "");
    },
    true, // capture phase so we win over the seek handler
  );
}

// Hook called from the reading-view render path to stamp the marker
// on any sentence span that already has an annotation. Tolerant: if
// the clip / span / spans array isn't ready, just no-ops.
// v223.annotate-4: also injects a small ▶ play button for any sentence
// whose annotation set includes a voice note — the user gets one tap
// to hear what their phone-self recorded against this sentence.
function _applyAnnotationMarkers(clip) {
  if (!Array.isArray(sentenceSpans) || !sentenceSpans.length) return;
  const annos = _listAnnotations(clip);
  // Index annotated sentences + best voice anno per sentence so we can
  // reconcile each span below. v223.tn20 (#490): made this function
  // RECONCILING (handles add + remove + transcript update) so a
  // cross-device pull that lands new — or removes — annotations
  // updates the reading view inline without a page reload.
  // v223.tn21 (#491): also collect a per-sentence list of non-voice
  // tag annotations so we can render inline tag-icon chips (✂ ⚠ etc.)
  // — answers "what was the annotation?" without entering annotate
  // mode. Dedup tags within a sentence (a user can flag the same
  // sentence twice with the same tag from different devices).
  const annotatedSentences = new Set();
  const voiceBySentence = new Map();
  // v223.tn26 (#498): tag chips now carry the annotation ID so a click
  // on the chip can resolve to a specific anno → tombstone via the
  // action sheet. Map shape: sentenceIndex → Map<tagKey, annoId>.
  const tagsBySentence = new Map();
  // v223.tn26: filter tombstoned annotations at the head of the
  // reconcile pass. Server stores them so the cross-device merge can
  // recognize the delete intent; client treats them as gone for all
  // rendering purposes. Doing this in one place means every downstream
  // map (annotatedSentences, voiceBySentence, tagsBySentence) is
  // automatically tombstone-aware.
  const liveAnnos = annos.filter((a) => a && !a.deletedAt);
  for (const a of liveAnnos) {
    if (!Number.isInteger(a.sentenceIndex)) continue;
    annotatedSentences.add(a.sentenceIndex);
    if (a.audio && a.audio.base64) {
      const prev = voiceBySentence.get(a.sentenceIndex);
      if (!prev || (a.flaggedAt || "") > (prev.flaggedAt || "")) {
        voiceBySentence.set(a.sentenceIndex, a);
      }
    }
    if (Array.isArray(a.tags)) {
      for (const t of a.tags) {
        if (t === "voice") continue; // voice already has ▶
        if (!ANNOTATE_TAGS[t]) continue;
        let m = tagsBySentence.get(a.sentenceIndex);
        if (!m) { m = new Map(); tagsBySentence.set(a.sentenceIndex, m); }
        // Last write wins per (sentence, tag) pair. Multi-device
        // duplicates of the same tag on the same sentence are rare;
        // tapping the chip deletes the most-recently-stamped one.
        m.set(t, a.id);
      }
    }
  }
  // Walk every sentence span and reconcile its markers against the
  // (new) annotation set. Sentence with anno → set the dot attr;
  // sentence without → clear it. Same for the inline ▶ button +
  // transcript block: ensure present when the anno calls for it,
  // strip otherwise.
  for (let i = 0; i < sentenceSpans.length; i++) {
    const span = sentenceSpans[i];
    if (!span) continue;
    const isAnnotated = annotatedSentences.has(i);
    // v223.tn27 (#499): defer dataset.hasAnnotation toggle to the END
    // of this iteration. The dot is now a *fallback* marker — shown
    // only when the reconciler couldn't paint any richer affordance
    // for this annotation. Clear it up-front; the tail block below
    // re-asserts it if nothing else gets rendered.
    if ("hasAnnotation" in span.dataset) {
      delete span.dataset.hasAnnotation;
    }
    // v223.tn22 (bugfix): sweep duplicate transcript siblings before
    // anything else. Earlier reconciler runs (pre-fix) could add a
    // second transcript span because `_voiceInjectPlayButton` already
    // injected one but our cached `existingTr` was queried before
    // that call and was stale-null. Cleans up any DOM that the old
    // bug left behind, on every pass.
    const allTr = span.querySelectorAll(".annotate-voice-transcript");
    if (allTr.length > 1) {
      for (let k = 1; k < allTr.length; k++) allTr[k].remove();
    }
    const voiceAnno = voiceBySentence.get(i);
    const existingBtn = span.querySelector(".annotate-voice-play");
    if (voiceAnno) {
      if (!existingBtn) {
        // No button yet → let _voiceInjectPlayButton add BOTH button
        // and transcript. Don't run the manual transcript branch
        // below — it would double up. The function reads the same
        // anno.transcript field we'd check anyway.
        _voiceInjectPlayButton(span, voiceAnno);
      } else {
        // Button already there. Whisper may have landed a transcript
        // later, OR another device edited it. Re-query the transcript
        // AFTER any inject so we don't see stale null.
        const existingTr = span.querySelector(".annotate-voice-transcript");
        const want = voiceAnno.transcript ? "“" + voiceAnno.transcript + "”" : "";
        if (want) {
          if (!existingTr) {
            const t = document.createElement("span");
            t.className = "annotate-voice-transcript";
            t.textContent = want;
            t.dataset.annoId = voiceAnno.id;
            span.appendChild(t);
          } else if (existingTr.textContent !== want) {
            existingTr.textContent = want;
          }
        } else if (existingTr) {
          existingTr.remove();
        }
      }
      // v223.tn22 (#492): re-transcribe affordance. Some memos save
      // audio but no transcript — Whisper's VAD filter returns "" on
      // quiet audio, and network blips silently drop the transcribe
      // call. Show a small ↻ button next to ▶ so the user can retry
      // server-side Whisper on demand. Removed once a transcript
      // lands. (v585 Phase 2 tried replacing this with an always-
      // present ✎ Edit dialog — reverted per user feedback.)
      let existingRetry = span.querySelector(".annotate-voice-retry");
      const needsTranscribe = voiceAnno.audio
        && voiceAnno.audio.base64
        && !voiceAnno.transcript;
      if (needsTranscribe) {
        if (!existingRetry) {
          const retry = document.createElement("button");
          retry.type = "button";
          retry.className = "annotate-voice-retry";
          retry.textContent = "↻";
          retry.title = "Transcribe this voice note via server";
          retry.dataset.annoId = voiceAnno.id;
          const capturedClipId = _currentClipId;
          const capturedAnno = voiceAnno;
          retry.addEventListener("click", async (e) => {
            e.stopPropagation();
            e.preventDefault();
            if (retry.classList.contains("busy")) return;
            retry.classList.add("busy");
            retry.textContent = "…";
            try {
              await _voiceTryServerTranscribe(
                capturedClipId,
                capturedAnno.id,
                capturedAnno.audio.base64,
                capturedAnno.audio.mime || "audio/webm",
              );
              if (span.querySelector(".annotate-voice-transcript")) {
                retry.remove();
              } else {
                retry.classList.remove("busy");
                retry.textContent = "↻";
              }
            } catch (err) {
              console.warn("[voice] retry transcribe failed:", err);
              retry.classList.remove("busy");
              retry.textContent = "↻";
            }
          });
          const btn = span.querySelector(".annotate-voice-play");
          if (btn) btn.insertAdjacentElement("afterend", retry);
          else span.insertBefore(retry, span.firstChild);
        }
      } else if (existingRetry) {
        existingRetry.remove();
      }
      // Sweep any v585 Phase 2 ✎ button left in the DOM from the
      // brief shipped version. Defensive against caches.
      const stalEdit = span.querySelector(".annotate-voice-edit");
      if (stalEdit) stalEdit.remove();
      // v223.tn26 (#498): × delete button next to ▶. Tap fires the
      // action sheet → tombstone. Sibling to ▶ + ↻ so all three
      // controls stack inline at the head of the sentence.
      let existingDel = span.querySelector(".annotate-voice-delete");
      if (!existingDel) {
        const del = document.createElement("button");
        del.type = "button";
        del.className = "annotate-voice-delete";
        del.textContent = "×";
        del.title = "Remove this voice note";
        del.dataset.annoId = voiceAnno.id;
        const capturedClipIdDel = _currentClipId;
        const capturedAnnoIdDel = voiceAnno.id;
        del.addEventListener("click", (e) => {
          e.stopPropagation();
          e.preventDefault();
          _showAnnoActionSheet(del, "Remove voice note", async () => {
            const ok = await _tombstoneAnnotation(
              capturedClipIdDel,
              capturedAnnoIdDel,
            );
            if (ok) setStatus("Voice note removed.");
          });
        });
        // Insert at the END of the inline controls (after ▶ and ↻ if
        // present). Walk forward from the play button to the last
        // sibling that's part of this anno's control cluster.
        const playBtn = span.querySelector(".annotate-voice-play");
        const retryBtn = span.querySelector(".annotate-voice-retry");
        const anchor = retryBtn || playBtn;
        if (anchor) anchor.insertAdjacentElement("afterend", del);
        else span.insertBefore(del, span.firstChild);
      } else {
        existingDel.dataset.annoId = voiceAnno.id;
      }
    } else {
      if (existingBtn) existingBtn.remove();
      const existingTr = span.querySelector(".annotate-voice-transcript");
      if (existingTr) existingTr.remove();
      const existingRetry = span.querySelector(".annotate-voice-retry");
      if (existingRetry) existingRetry.remove();
      const existingDel = span.querySelector(".annotate-voice-delete");
      if (existingDel) existingDel.remove();
    }
    // v223.tn21 (#491): reconcile inline tag-icon chips. One chip per
    // unique non-voice tag on this sentence. Anchored to the sentence
    // span so they ride with the text in the reading-ruler dim/bright
    // pass and travel with the sentence in scroll.
    const wantTagsMap = tagsBySentence.get(i) || new Map();
    const existingChips = span.querySelectorAll(".annotate-tag-chip");
    const existingTagKeys = new Set();
    for (const chip of existingChips) {
      const k = chip.dataset.tag;
      const wantedAnnoId = wantTagsMap.get(k);
      if (wantedAnnoId !== undefined) {
        existingTagKeys.add(k);
        // Refresh the annoId binding in case the chip survived from
        // a prior render where a different annotation owned this tag
        // (e.g., one was deleted, another added with same tag).
        chip.dataset.annoId = wantedAnnoId;
      } else {
        chip.remove();
      }
    }
    // Insert any new chips just after the ▶ button (or at the head if
    // there isn't one). Sorted by ANNOTATE_TAGS declaration order so
    // multi-tag sentences read in a consistent order across devices.
    const insertAnchor = span.querySelector(".annotate-voice-play") || null;
    for (const tagKey of Object.keys(ANNOTATE_TAGS)) {
      const annoIdForChip = wantTagsMap.get(tagKey);
      if (annoIdForChip === undefined) continue;
      if (existingTagKeys.has(tagKey)) continue;
      const meta = ANNOTATE_TAGS[tagKey];
      const chip = document.createElement("span");
      chip.className = "annotate-tag-chip";
      chip.dataset.tag = tagKey;
      chip.dataset.annoId = annoIdForChip;
      chip.textContent = meta.icon;
      chip.title = `${meta.label} — tap to seek; tap × that appears to remove`;
      chip.style.background = meta.color;
      // v225.tn60 (#543): chip tap was opening the delete action
      // sheet (v223.tn26 #498), which annoyed users mid-listen who
      // expected tap-to-seek like the rest of the sentence. New
      // behavior: tap chip → seek to that sentence; long-press →
      // delete action sheet. stopPropagation kept so we don't
      // double-fire seek + annotate-apply via the parent span.
      let _chipPressTimer = null;
      let _chipPressFired = false;
      const HOLD_MS = 500;
      const _findSentenceIdx = () => {
        // Walk up to the parent sentence span and read its index.
        // The reading-view sentence span stores it as data-index
        // (see the word-wrap path at line ~10242).
        let n = chip.parentNode;
        while (n && (!n.dataset || n.dataset.index == null)) {
          n = n.parentNode;
        }
        if (!n) return -1;
        const idx = parseInt(n.dataset.index, 10);
        return Number.isFinite(idx) ? idx : -1;
      };
      // v225.tn73 (#555): stopPropagation on EVERY pointer event so
      // the chip's gestures don't bubble up to the reading view's
      // voice-assign long-press detector (v220aa/v220ad). Previously
      // only `click` stopped propagation — the pointerdown leaked to
      // the parent, so a long-press on a flag chip fired BOTH the
      // chip's "Remove flag" action sheet AND the character-voice
      // assignment menu, opened simultaneously.
      chip.addEventListener("pointerdown", (e) => {
        e.stopPropagation();
        _chipPressFired = false;
        _dlog("flag-chip", "pointerdown", { tag: tagKey, annoId: chip.dataset.annoId });
        _chipPressTimer = setTimeout(() => {
          _chipPressTimer = null;
          _chipPressFired = true;
          const aid = chip.dataset.annoId;
          _dlog("flag-chip", "long-press fired", { aid });
          if (!aid) return;
          _showAnnoActionSheet(chip, "Remove flag", async () => {
            const ok = await _tombstoneAnnotation(_currentClipId, aid);
            if (ok) setStatus("Flag removed.");
          });
        }, HOLD_MS);
      });
      const _cancelChipHold = (e) => {
        if (e) e.stopPropagation();
        if (_chipPressTimer) {
          clearTimeout(_chipPressTimer);
          _chipPressTimer = null;
          _dlog("flag-chip", "hold cancelled", { type: e && e.type });
        }
      };
      chip.addEventListener("pointerup", _cancelChipHold);
      chip.addEventListener("pointercancel", _cancelChipHold);
      chip.addEventListener("pointerleave", _cancelChipHold);
      // Also stop pointermove so the v220ad drag-to-select handler
      // doesn't initiate a multi-sentence selection from a hold on
      // a chip. (The chip is inline with sentence text; even a small
      // wobble during long-press would normally drag-extend.)
      chip.addEventListener("pointermove", (e) => e.stopPropagation());
      chip.addEventListener("click", (e) => {
        e.stopPropagation();
        e.preventDefault();
        const idx = _findSentenceIdx();
        _dlog("flag-chip", "click", {
          pressFired: _chipPressFired,
          idx,
          haveSeekFn: typeof seekToSentence === "function",
        });
        // If the long-press already fired, suppress the click-as-seek
        // — the user was reaching for delete, not seek.
        if (_chipPressFired) {
          _chipPressFired = false;
          return;
        }
        if (idx >= 0 && typeof seekToSentence === "function") {
          seekToSentence(idx);
        }
        // v225.tn82 (#564): also reveal an inline × beside the chip
        // for ~4s. Tap × within that window to remove the flag
        // without ever opening the action sheet.
        _revealChipDelete(chip);
      });
      // Suppress the OS long-press context menu (same family of
      // fixes as v225.tn56/57 for the tag-row chips).
      chip.addEventListener("contextmenu", (e) => e.preventDefault());
      _dlog("flag-chip", "rendered + wired", {
        tag: tagKey,
        annoId: annoIdForChip,
        sentenceIdx: i,
      });
      // Insert after the voice-play button if present; else at head.
      if (insertAnchor && insertAnchor.parentNode === span) {
        insertAnchor.insertAdjacentElement("afterend", chip);
      } else {
        span.insertBefore(chip, span.firstChild);
      }
    }
    // v223.tn27 (#499): fallback dot. If this sentence is annotated
    // but none of the richer affordances (tag chip, voice ▶,
    // transcript) made it onto the DOM, keep the dataset attribute
    // so the CSS dot at least signals "there's something here." This
    // covers legacy entries with unrecognized tags and any future
    // client/server skew where a new tag ships before this build
    // knows about it. Normal annotations now paint their icon
    // *instead* of the dot, not in addition to it.
    if (isAnnotated) {
      const hasVisibleMarker = !!span.querySelector(
        ".annotate-tag-chip, .annotate-voice-play, .annotate-voice-transcript",
      );
      if (!hasVisibleMarker) {
        span.dataset.hasAnnotation = "true";
      }
    }
  }

  // v225dy (#611): keep the pull-up Author summary ("N flags · N
  // bookmarks") fresh after every annotation mutation. This is the
  // single reconcile funnel for add / remove / tombstone / live-paint,
  // so wiring it here catches every path without per-callsite plumbing.
  if (typeof _updatePullupState === "function") {
    try { _updatePullupState(); } catch (e) {
      console.warn("[pullup] state refresh after anno reconcile failed:", e);
    }
  }
  // v225ep (#632): same funnel feeds the desktop author pane.
  if (typeof _renderAuthorPane === "function") {
    try { _renderAuthorPane(); } catch (e) {
      console.warn("[author pane] refresh after anno reconcile failed:", e);
    }
  }
}

// ──────────────────────────────────────────────────────────────────────
// v223.annotate-4: voice notes attached to annotations.
//
// Capture: tap 🎤 in the palette → MediaRecorder runs on the mic,
// auto-stops at VOICE_NOTE_MAX_SEC. Resulting Blob is base64-encoded
// and stashed on the annotation as { mime, base64, durationSec }.
// Sync rides for free — the existing annotations JSON column already
// carries it cross-device after v223.annotate-1.5's schema bump.
//
// Playback: _applyAnnotationMarkers injects an inline ▶ button at the
// head of any sentence with a voice annotation. Click plays the memo
// via a transient Audio element and pauses the main playback for the
// duration so the memo isn't talked over.
//
// Cap at 30 seconds: the base64-in-annotation approach trades a clean
// sync path (everything in one JSON column) for payload size. 30s of
// opus at ~32 kbps is ~120 KB raw → ~160 KB base64, fine for a memo.
// Longer ramblings belong in clip.notes, not annotation audio.
// ──────────────────────────────────────────────────────────────────────

const VOICE_NOTE_MAX_SEC = 30;
let _voiceRecorder = null;
let _voiceChunks = [];
let _voiceMimeType = "";
let _voiceStartedAt = 0;
let _voiceTimerInterval = null;
let _voiceAutoStopTimer = null;
let _voiceStream = null;
let _voicePlayer = null;
let _voicePlayingBtn = null;
// v223.tn5 (#470): live speech-to-text. Audio remains the source of
// truth; the transcript becomes the searchable / skimmable surface on
// the desktop resolve side. SpeechRecognition runs alongside the
// MediaRecorder and accumulates the final-result chunks into
// _voiceTranscriptFinal. Interim chunks render in the UI but aren't
// saved (they keep mutating until the recognizer commits them).
let _voiceRecognition = null;
let _voiceTranscriptFinal = "";
// v223.tn8: persistent diagnostic log — every SR lifecycle event
// appends here so we can dump the full trace into the status bar at
// save time, where it doesn't get clobbered by the success message.
let _voiceSTTLog = [];
// v223.tn3: pause main playback while recording so the mic doesn't
// capture the narration through the device speaker. Track whether we
// paused so we can resume on save/cancel — only resume if playback
// was actually running when recording started.
//
// v223.tn4: ALSO mark recording-in-flight so the visibilitychange
// auto-resume handler doesn't bring playback back DURING recording.
// Bug seen on mobile: getUserMedia() permission prompt briefly
// backgrounds the page; iOS audio-session-category change fires a
// second pause event while visibility is "hidden", which flags
// _externallyPaused=true. When the prompt closes and visibility
// flips back, the auto-resume fires straight into a live mic.
// _voiceIsRecording short-circuits that.
let _voiceWasPlayingBeforeRecord = false;
let _voiceIsRecording = false;

function _voicePauseMainPlayback() {
  if (!playerEl) return;
  if (!playerEl.paused) {
    _voiceWasPlayingBeforeRecord = true;
    // Use _pauseAsUser semantics so the pause handler doesn't read
    // this as an OS interrupt just because the mic prompt happens to
    // background the page in the same tick.
    try { _pauseAsUser(); } catch { try { playerEl.pause(); } catch {} }
  } else {
    _voiceWasPlayingBeforeRecord = false;
  }
}
function _voiceResumeMainPlaybackIfNeeded() {
  if (_voiceWasPlayingBeforeRecord && playerEl) {
    try { playerEl.play().catch(() => {}); } catch {}
  }
  _voiceWasPlayingBeforeRecord = false;
}

async function _voiceStart() {
  if (!_currentClipId) {
    setStatus("Load a clip first to record a voice note.", true);
    return;
  }
  if (_voiceRecorder) return;
  if (typeof MediaRecorder === "undefined" ||
      !navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
    setStatus("Voice notes need a browser with mic recording.", true);
    return;
  }
  // Pause main playback before opening the mic so the narration
  // playing through the speaker isn't captured into the memo.
  _voicePauseMainPlayback();
  try {
    _voiceStream = await navigator.mediaDevices.getUserMedia({ audio: true });
  } catch (e) {
    console.warn("[voice] mic permission denied:", e);
    setStatus("Mic access denied — allow in browser settings.", true);
    _voiceResumeMainPlaybackIfNeeded();
    return;
  }
  // Pick a MIME type. webm/opus is universal on Chromium/Firefox;
  // Safari only offers audio/mp4. Falling through to empty string lets
  // the browser pick its default.
  const preferred = ["audio/webm;codecs=opus", "audio/webm", "audio/mp4", ""];
  let mime = "";
  for (const t of preferred) {
    if (!t || (typeof MediaRecorder.isTypeSupported === "function" &&
               MediaRecorder.isTypeSupported(t))) {
      mime = t; break;
    }
  }
  try {
    _voiceRecorder = mime
      ? new MediaRecorder(_voiceStream, { mimeType: mime })
      : new MediaRecorder(_voiceStream);
  } catch (e) {
    console.warn("[voice] MediaRecorder ctor failed:", e);
    _voiceReleaseStream();
    _voiceResumeMainPlaybackIfNeeded();
    setStatus("Couldn't start recording on this device.", true);
    return;
  }
  _voiceChunks = [];
  _voiceMimeType = _voiceRecorder.mimeType || "audio/webm";
  _voiceRecorder.ondataavailable = (ev) => {
    if (ev.data && ev.data.size > 0) _voiceChunks.push(ev.data);
  };
  _voiceRecorder.onstop = () => _voiceFinalize();
  _voiceRecorder.start();
  _voiceIsRecording = true;
  _voiceStartedAt = Date.now();
  // v225.tn40 (#517): body-level signal so any "is recording" UI
  // anywhere in the app can pulse without each one having to track
  // _voiceRecorder. Removed in _voiceReleaseStream when the
  // recorder is cleared.
  document.body.dataset.voiceRecording = "1";
  _voiceShowRecordRow();
  // v223.tn5 (#470): best-effort live transcription via Web Speech
  // API. On Android Chrome this often gets starved by MediaRecorder's
  // mic ownership (audio event fires but no samples), so the
  // server-side Whisper fallback in _voiceTryServerTranscribe()
  // picks up any memo that finishes without an SR transcript.
  _voiceStartTranscription();
  _voiceTimerInterval = setInterval(_voiceUpdateTimer, 200);
  _voiceAutoStopTimer = setTimeout(() => _voiceStop(),
    VOICE_NOTE_MAX_SEC * 1000);
}

// v223.tn5 (#470): Web Speech API live transcription. Continuous
// mode so the recognizer doesn't auto-stop on natural pauses (the
// user may pause to think mid-memo). Interim results update the UI
// while final-only results accumulate into _voiceTranscriptFinal,
// which becomes the annotation's transcript field on save.
//
// v223.tn6: visible status during the whole transcription lifecycle
// (was hidden until first onresult, which made silent failures look
// like the feature was broken). Pane is shown immediately with a
// placeholder; every recognizer event updates the placeholder so the
// user always sees what's happening.
//
// v223.tn7: also surface every SR lifecycle event in the main status
// bar so phones (where the in-palette pane may be hidden by the
// browser chrome) get unambiguous diagnostic feedback. Strip these
// once we confirm transcription is working in the wild.
function _voiceStartTranscription() {
  _voiceTranscriptFinal = "";
  _voiceSTTLog = [];
  const stt = (tag) => {
    _voiceSTTLog.push(tag);
    console.log("[voice]", tag);
  };
  const liveEl = document.getElementById("annotate-record-transcript");
  const setStatusText = (text, cls) => {
    if (!liveEl) return;
    liveEl.hidden = false;
    liveEl.innerHTML = `<span class="${cls || "interim"}">${_escapeHTML(text)}</span>`;
  };
  const Recog = typeof SpeechRecognition !== "undefined"
    ? SpeechRecognition
    : (typeof webkitSpeechRecognition !== "undefined"
      ? webkitSpeechRecognition
      : null);
  stt(Recog ? `start:${Recog === window.webkitSpeechRecognition ? "wk" : "std"}` : "noSR");
  if (!Recog) {
    setStatusText("Live transcript not supported in this browser — audio still saves.", "interim");
    _voiceRecognition = null;
    return;
  }
  try {
    _voiceRecognition = new Recog();
  } catch (e) {
    console.warn("[voice] SpeechRecognition ctor failed:", e);
    setStatusText("Couldn't start transcript — audio still saves.", "interim");
    _voiceRecognition = null;
    return;
  }
  _voiceRecognition.continuous = true;
  _voiceRecognition.interimResults = true;
  _voiceRecognition.lang = (navigator.language || "en-US");
  // Show placeholder immediately so the user knows transcription
  // is initializing — no silent dead pane while waiting for the
  // first event.
  setStatusText("Listening…", "interim");
  _voiceRecognition.onaudiostart = () => {
    stt("audio");
    if (!_voiceTranscriptFinal) setStatusText("Listening…", "interim");
  };
  _voiceRecognition.onspeechstart = () => { stt("speech"); };
  _voiceRecognition.onsoundstart = () => { stt("sound"); };
  _voiceRecognition.onstart = () => { stt("started"); };
  _voiceRecognition.onresult = (event) => {
    let interim = "";
    for (let i = event.resultIndex; i < event.results.length; i++) {
      const res = event.results[i];
      const txt = res[0] && res[0].transcript ? res[0].transcript : "";
      if (res.isFinal) {
        _voiceTranscriptFinal = (_voiceTranscriptFinal + " " + txt).trim();
      } else {
        interim += txt;
      }
    }
    if (liveEl) {
      liveEl.hidden = false;
      const finalHTML = _voiceTranscriptFinal
        ? `<span class="final">${_escapeHTML(_voiceTranscriptFinal)}</span> `
        : "";
      const interHTML = interim
        ? `<span class="interim">${_escapeHTML(interim.trim())}</span>`
        : "";
      const combined = finalHTML + interHTML;
      liveEl.innerHTML = combined || `<span class="interim">Listening…</span>`;
    }
  };
  _voiceRecognition.onerror = (e) => {
    // Common errors: no-speech, audio-capture, network. Don't crash
    // the recording; the audio still saves without a transcript.
    const code = e && e.error ? e.error : "unknown";
    console.warn("[voice] SpeechRecognition error:", code, e);
    stt(`err:${code}`);
    // Show non-fatal errors so the user knows why no text is
    // appearing. "no-speech" fires routinely when the user is
    // thinking — don't surface that, the auto-restart in onend
    // will pick recognition back up.
    if (code !== "no-speech" && code !== "aborted" && !_voiceTranscriptFinal) {
      setStatusText(`Transcript error: ${code} — audio still saves.`, "interim");
    }
  };
  // The recognizer can auto-end on long silence even in continuous
  // mode (especially on Chrome mobile). If we're still recording when
  // that happens, restart it so the rest of the memo gets transcribed.
  _voiceRecognition.onend = () => {
    stt("end");
    if (_voiceIsRecording && _voiceRecognition) {
      try { _voiceRecognition.start(); stt("restart"); }
      catch (e) { stt(`restartFail:${e.name||"e"}`); }
    }
  };
  // Tag results events too so we know if recognition is producing
  // anything at all. Lightweight (just a counter) so we don't bloat
  // the log with one entry per chunk.
  const origOnResult = _voiceRecognition.onresult;
  let _resultCount = 0;
  _voiceRecognition.onresult = (event) => {
    _resultCount++;
    if (_resultCount === 1) stt("result:1");
    origOnResult(event);
  };
  try {
    _voiceRecognition.start();
    stt("startOK");
  } catch (e) {
    stt(`startFail:${e.name||"e"}`);
    setStatusText(`Couldn't start transcript (${e.name || "error"}) — audio still saves.`, "interim");
  }
}

function _voiceStopTranscription() {
  if (!_voiceRecognition) return;
  // Detach onend so we don't auto-restart after the user-driven stop.
  _voiceRecognition.onend = null;
  try { _voiceRecognition.stop(); } catch {}
  _voiceRecognition = null;
}

// Reuses the existing escape helper if available; falls back to a
// small local copy so this module doesn't depend on a specific
// definition order.
function _escapeHTML(s) {
  return String(s || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function _voiceUpdateTimer() {
  const el = document.getElementById("annotate-record-timer");
  if (!el) return;
  const sec = (Date.now() - _voiceStartedAt) / 1000;
  const remaining = Math.max(0, VOICE_NOTE_MAX_SEC - sec);
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  el.textContent = `${m}:${String(s).padStart(2, "0")}`;
  if (remaining <= 5) el.dataset.warning = "true";
  else delete el.dataset.warning;
}

function _voiceStop() {
  if (_voiceTimerInterval) { clearInterval(_voiceTimerInterval); _voiceTimerInterval = null; }
  if (_voiceAutoStopTimer) { clearTimeout(_voiceAutoStopTimer); _voiceAutoStopTimer = null; }
  _voiceStopTranscription();
  if (_voiceRecorder && _voiceRecorder.state !== "inactive") {
    try { _voiceRecorder.stop(); } catch (e) { console.warn("[voice] stop:", e); }
  }
}

function _voiceCancel() {
  if (_voiceTimerInterval) { clearInterval(_voiceTimerInterval); _voiceTimerInterval = null; }
  if (_voiceAutoStopTimer) { clearTimeout(_voiceAutoStopTimer); _voiceAutoStopTimer = null; }
  _voiceStopTranscription();
  if (_voiceRecorder && _voiceRecorder.state !== "inactive") {
    // Detach onstop so finalize doesn't fire on the cancelled blob.
    _voiceRecorder.onstop = null;
    try { _voiceRecorder.stop(); } catch {}
  }
  _voiceReleaseStream();
  _voiceResumeMainPlaybackIfNeeded();
  _voiceShowTagRow();
  _hideAnnotatePalette();
}

function _voiceReleaseStream() {
  if (_voiceStream) {
    for (const t of _voiceStream.getTracks()) { try { t.stop(); } catch {} }
  }
  _voiceStream = null;
  _voiceRecorder = null;
  _voiceChunks = [];
  _voiceMimeType = "";
  _voiceStartedAt = 0;
  // v225.tn40 (#517): clear the global recording signal. Catches
  // every termination path — explicit stop, auto-stop at
  // VOICE_NOTE_MAX_SEC, cancel button, error during finalize.
  if (document.body.dataset.voiceRecording) {
    delete document.body.dataset.voiceRecording;
  }
  // Sync the tag-row mic button's own gesture state so a long-press
  // that was followed by auto-stop doesn't leave isPressed/mode
  // sticky for the next interaction.
  _phoneTagRowVoicePressMode = null;
  // v223.tn4: clear the "recording in flight" guard so the
  // visibilitychange auto-resume can fire again next time.
  _voiceIsRecording = false;
}

async function _voiceFinalize() {
  const sentenceIndex = _annotatePendingSentenceIndex;
  const startedAt = _voiceStartedAt;
  const blob = new Blob(_voiceChunks, { type: _voiceMimeType });
  const mime = _voiceMimeType || "audio/webm";
  _voiceReleaseStream();
  // Resume main playback (if it was running pre-record). Done before
  // the async base64 encode so the user gets immediate feedback that
  // narration is back, instead of waiting for the save to complete.
  _voiceResumeMainPlaybackIfNeeded();
  _voiceShowTagRow();
  if (!_currentClipId || sentenceIndex == null || blob.size === 0) {
    _hideAnnotatePalette();
    return;
  }
  let base64;
  try {
    base64 = await _blobToBase64(blob);
  } catch (e) {
    console.warn("[voice] base64 encode failed:", e);
    _hideAnnotatePalette();
    setStatus("Voice note save failed.", true);
    return;
  }
  const durationSec = Math.max(0.1, (Date.now() - startedAt) / 1000);
  const span = sentenceSpans && sentenceSpans[sentenceIndex];
  const sentenceText = span ? span.textContent : "";
  // v223.tn5 (#470): snapshot the live transcript at finalize-time
  // and clear the buffer so the next recording doesn't carry it over.
  const transcript = (_voiceTranscriptFinal || "").trim();
  _voiceTranscriptFinal = "";
  const anno = {
    id: _annotateNewId(),
    sentenceIndex,
    sentenceFingerprint: _annotateFingerprint(sentenceText),
    flaggedAt: new Date().toISOString(),
    source: "voice",
    tags: ["voice"],
    audio: {
      mime,
      base64,
      durationSec: Math.round(durationSec * 10) / 10,
    },
    // Only attach when present — keeps the JSON smaller for browsers
    // without SpeechRecognition support.
    ...(transcript ? { transcript } : {}),
  };
  await _addAnnotation(_currentClipId, anno);
  if (span) {
    span.dataset.hasAnnotation = "true";
    _voiceInjectPlayButton(span, anno);
  }
  _hideAnnotatePalette();
  // v223.tn10 (#475): if browser SR didn't yield a transcript (Android
  // Chrome mic-collision is the common case), fire-and-forget a
  // server-side Whisper request. The transcript lands on the
  // annotation when it returns, and the existing sync push propagates
  // to other devices. UX: show "transcribing…" so the user knows
  // text is on its way.
  const savedClipId = _currentClipId;
  _voiceSTTLog = [];
  if (transcript) {
    setStatus(`✓ Voice note saved (${anno.audio.durationSec.toFixed(1)}s)`);
  } else if (base64) {
    setStatus(`✓ Voice note saved (${anno.audio.durationSec.toFixed(1)}s) — transcribing…`);
    _voiceTryServerTranscribe(savedClipId, anno.id, base64, mime);
  } else {
    setStatus(`✓ Voice note saved (${anno.audio.durationSec.toFixed(1)}s)`);
  }
}

// v225.tn88 (#570): offline transcript queue. When _voiceTryServerTranscribe
// runs while offline (or fails the network call), the request lands here
// instead of being lost. Same payload that the endpoint expects, plus an
// id so we can dedupe on retry. Drains on the `online` event.
const _OFFLINE_PENDING_TRANSCRIBE_KEY = "narrative.pendingTranscribe";
function _readPendingTranscribes() {
  try {
    const raw = localStorage.getItem(_OFFLINE_PENDING_TRANSCRIBE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}
function _writePendingTranscribes(list) {
  try {
    localStorage.setItem(
      _OFFLINE_PENDING_TRANSCRIBE_KEY,
      JSON.stringify(list || []),
    );
  } catch {}
}
function _queuePendingTranscribe(entry) {
  const list = _readPendingTranscribes();
  // Dedupe by annoId so a re-tap doesn't queue twice.
  const filtered = list.filter((e) => e.annoId !== entry.annoId);
  filtered.push(entry);
  _writePendingTranscribes(filtered);
}
function _clearPendingTranscribe(annoId) {
  const list = _readPendingTranscribes().filter((e) => e.annoId !== annoId);
  _writePendingTranscribes(list);
}
async function _drainPendingTranscribes() {
  if (_isOffline()) return;
  const list = _readPendingTranscribes();
  if (!list.length) return;
  // Quiet drain — no toast unless something completes.
  for (const entry of list) {
    try {
      await _voiceTryServerTranscribe(
        entry.clipId,
        entry.annoId,
        entry.audioB64,
        entry.mime,
        true /* fromQueue */,
      );
      // _voiceTryServerTranscribe clears the queue entry on success.
    } catch (err) {
      console.warn("[voice] queued transcribe retry failed:", err);
      // Leave in queue for next online tick.
    }
  }
}

// v223.tn10 (#475): server-side Whisper fallback. Fire after a memo
// saves without a browser-SR transcript. Result patches onto the
// annotation in IDB and rides the next sync push to other devices.
// Best-effort — failures leave the memo audio-only.
// v225.tn88 (#570): if offline at call time, queue instead of fetching
// so the audio isn't lost. On reconnect, the queue drains and the
// transcripts land just like the original first-try path. The
// `fromQueue` flag suppresses the queue-write-back so we don't pile
// up duplicates during a retry storm.
async function _voiceTryServerTranscribe(clipId, annoId, audioB64, mime, fromQueue) {
  if (!clipId || !annoId || !audioB64) return;
  if (_isOffline()) {
    _queuePendingTranscribe({
      clipId, annoId, audioB64, mime: mime || "audio/webm",
      queuedAt: Date.now(),
    });
    setStatus(
      "Voice note saved — transcript queued (you're offline).",
    );
    return;
  }
  try {
    const res = await fetch("/api/library/transcribe", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ audioB64, mime: mime || "audio/webm" }),
    });
    if (!res.ok) {
      console.warn("[voice] /transcribe HTTP", res.status);
      // v225.tn88 (#570): queue for retry on a 5xx (server hiccup).
      // Hard 4xx is unlikely to succeed on retry, so don't pile up.
      if (res.status >= 500 && res.status < 600) {
        _queuePendingTranscribe({
          clipId, annoId, audioB64, mime: mime || "audio/webm",
          queuedAt: Date.now(),
        });
        setStatus(`Voice note saved — transcript queued (server ${res.status}).`);
      } else {
        setStatus(`Voice note saved (audio only — transcribe HTTP ${res.status}).`);
      }
      return;
    }
    const body = await res.json();
    const text = body && body.transcript ? String(body.transcript).trim() : "";
    if (!text) {
      setStatus("Voice note saved (audio only — couldn't transcribe).");
      return;
    }
    // Atomic IDB tx so we don't race with progress saves or other
    // annotation writes — same pattern as _addAnnotation / #469.
    const db = await openDB();
    const tx = db.transaction(STORE, "readwrite");
    const store = tx.objectStore(STORE);
    const clip = await idbReq(store.get(clipId));
    if (!clip) return;
    const annos = Array.isArray(clip.annotations) ? clip.annotations.slice() : [];
    const idx = annos.findIndex((a) => a && a.id === annoId);
    if (idx < 0) return;
    annos[idx] = { ...annos[idx], transcript: text };
    clip.annotations = annos;
    clip.updatedAt = new Date().toISOString();
    await idbReq(store.put(clip));
    await new Promise((resolve, reject) => {
      tx.oncomplete = resolve;
      tx.onerror = () => reject(tx.error);
      tx.onabort = () => reject(tx.error);
    });
    if (typeof _syncPushClip === "function") {
      _syncPushClip(clip).catch((e) => console.warn("[sync] push failed:", e));
    }
    // Paint the transcript inline now, so the desktop reviewer (or
    // the user, if they're still on the same sentence) sees it
    // without a reload.
    const updated = annos[idx];
    if (Number.isInteger(updated.sentenceIndex) && Array.isArray(sentenceSpans)) {
      const span = sentenceSpans[updated.sentenceIndex];
      if (span && !span.querySelector(".annotate-voice-transcript")) {
        const t = document.createElement("span");
        t.className = "annotate-voice-transcript";
        t.textContent = "“" + text + "”";
        t.dataset.annoId = updated.id;
        span.appendChild(t);
      }
    }
    const words = text.split(/\s+/).filter(Boolean).length;
    setStatus(`✓ Transcript ready (${words} word${words === 1 ? "" : "s"}).`);
    // v225.tn88 (#570): success — clear from the offline retry queue
    // if this was a queued retry.
    _clearPendingTranscribe(annoId);
  } catch (e) {
    console.warn("[voice] server transcribe failed:", e);
    // v225.tn88 (#570): network error counts as "queue for retry."
    // Most fetch failures here are network, not 4xx — we already
    // handled HTTP errors above. So queue the audio + annoId and
    // try again on the next `online` event.
    if (!fromQueue) {
      _queuePendingTranscribe({
        clipId, annoId, audioB64, mime: mime || "audio/webm",
        queuedAt: Date.now(),
      });
      setStatus("Voice note saved — transcript queued (network).");
    }
  }
}

function _voiceShowRecordRow() {
  const tagRow = document.getElementById("annotate-palette-tags");
  const recRow = document.getElementById("annotate-record-row");
  const hint = document.getElementById("annotate-palette-hint");
  if (tagRow) tagRow.hidden = true;
  if (recRow) recRow.hidden = false;
  if (hint) hint.textContent = `Recording — auto-stops at ${VOICE_NOTE_MAX_SEC}s`;
  const t = document.getElementById("annotate-record-timer");
  if (t) { t.textContent = "0:00"; delete t.dataset.warning; }
  // v223.tn5 (#470): reset live transcript pane; _voiceStartTranscription
  // unhides it once the recognizer is ready.
  const tr = document.getElementById("annotate-record-transcript");
  if (tr) { tr.innerHTML = ""; tr.hidden = true; }
}

function _voiceShowTagRow() {
  const tagRow = document.getElementById("annotate-palette-tags");
  const recRow = document.getElementById("annotate-record-row");
  const hint = document.getElementById("annotate-palette-hint");
  if (tagRow) tagRow.hidden = false;
  if (recRow) recRow.hidden = true;
  if (hint) hint.textContent = "Pick a tag to flag this sentence";
  const tr = document.getElementById("annotate-record-transcript");
  if (tr) { tr.innerHTML = ""; tr.hidden = true; }
}

function _voiceInjectPlayButton(span, anno) {
  if (!span || !anno || !anno.audio || !anno.audio.base64) return;
  // Don't double-inject if a re-render already added one.
  if (span.querySelector(".annotate-voice-play")) return;
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "annotate-voice-play";
  btn.textContent = "▶";
  const dur = anno.audio.durationSec || 0;
  // v223.tn5 (#470): if the annotation has a transcript, surface it
  // in the tooltip too — handy on desktop hover where the inline
  // block below may be partially scrolled out of view.
  const tipBase = `Voice note (${dur ? dur.toFixed(1) + "s" : "play"})`;
  btn.title = anno.transcript ? `${tipBase}\n${anno.transcript}` : tipBase;
  btn.dataset.annoId = anno.id;
  btn.addEventListener("click", (e) => {
    e.stopPropagation();
    e.preventDefault();
    _voicePlayAnno(anno, btn);
  });
  span.insertBefore(btn, span.firstChild);
  // v223.tn5 (#470): render the transcript as an inline italic block
  // appended to the sentence. Gives the desktop reviewer something
  // skim-able + searchable without having to listen. Tap-through to
  // the sentence still works because the block uses display:block
  // and doesn't catch sentence clicks.
  if (anno.transcript && !span.querySelector(".annotate-voice-transcript")) {
    const t = document.createElement("span");
    t.className = "annotate-voice-transcript";
    t.textContent = "“" + anno.transcript + "”";
    t.dataset.annoId = anno.id;
    span.appendChild(t);
  }
}

function _voicePlayAnno(anno, btn) {
  if (!anno || !anno.audio || !anno.audio.base64) return;
  // Stop any prior memo + clear its pulsing button.
  if (_voicePlayer) {
    try { _voicePlayer.pause(); } catch {}
    _voicePlayer.src = "";
    _voicePlayer = null;
  }
  if (_voicePlayingBtn) {
    _voicePlayingBtn.classList.remove("playing");
    _voicePlayingBtn = null;
  }
  // Pause main playback so the memo isn't talked over. Resume when
  // the memo ends or errors.
  const wasPlaying = playerEl && !playerEl.paused;
  if (wasPlaying) {
    try { playerEl.pause(); } catch {}
  }
  const src = `data:${anno.audio.mime || "audio/webm"};base64,${anno.audio.base64}`;
  _voicePlayer = new Audio(src);
  _voicePlayingBtn = btn || null;
  if (btn) btn.classList.add("playing");
  const cleanup = () => {
    if (btn) btn.classList.remove("playing");
    if (_voicePlayingBtn === btn) _voicePlayingBtn = null;
    if (wasPlaying) {
      try { playerEl.play().catch(() => {}); } catch {}
    }
  };
  _voicePlayer.onended = cleanup;
  _voicePlayer.onerror = (e) => { console.warn("[voice] play err:", e); cleanup(); };
  _voicePlayer.play().catch((e) => {
    console.warn("[voice] play failed:", e);
    cleanup();
  });
}

// Wire the palette's 🎤 button + record-row controls. The voice button
// has its own class so the existing tag-button click handler skips it.
{
  const voiceBtn = document.getElementById("annotate-voice-btn");
  if (voiceBtn) {
    voiceBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      e.preventDefault();
      _voiceStart();
    });
  }
  const stopBtn = document.getElementById("annotate-record-stop");
  if (stopBtn) stopBtn.addEventListener("click", () => _voiceStop());
  const cancelBtn = document.getElementById("annotate-record-cancel");
  if (cancelBtn) cancelBtn.addEventListener("click", () => _voiceCancel());
}
if (highlightToolbar) {
  highlightToolbar.addEventListener("pointerdown", (e) => {
    // Prevent selection collapse when clicking a toolbar button.
    e.preventDefault();
  });
  highlightToolbar.addEventListener("click", async (e) => {
    const btn = e.target.closest("button");
    if (!btn || !_highlightActiveSelectionInfo) return;
    const action = btn.dataset.action;
    const color = btn.dataset.color;
    const info = _highlightActiveSelectionInfo;
    _hideHighlightToolbar();
    window.getSelection()?.removeAllRanges();
    await _saveHighlight(info, action === "remove" ? null : color);
  });
}

// v206 (M4.1): detect chapter boundaries inside a clip's sentence
// array. Returns [{sentence_index, title}, ...] for each detected
// chapter, sorted by sentence_index. The sentence at sentence_index
// IS the chapter heading (or whatever opens the chapter) — drop cap
// fires on it, running header on subsequent pages keys off it, TOC
// jumps to it.
//
// Patterns matched (in order, first hit wins per sentence):
//   1. Markdown ATX heading: # / ## / ### Title
//   2. "Chapter N" / "CHAPTER 12" / "Part Three" — number or
//      lowercase word, optional subtitle after :/—/.
//   3. Bare Roman numeral as a short standalone sentence ("II.")
//
// Numeric/Roman-only titles get auto-promoted to "Chapter <N>" so a
// table of contents reads sensibly.
function _bookViewDetectChapters(sentences) {
  if (!Array.isArray(sentences) || sentences.length < 4) return [];
  const ROMAN = /^[ivxlcdm]+\.?$/i;
  const NUMERIC = /^[0-9]+$/;
  const out = [];
  for (let i = 0; i < sentences.length; i++) {
    const raw = (sentences[i] || "").trim();
    if (!raw) continue;
    let title = null;
    let m;
    // 1. Markdown ATX
    m = raw.match(/^(#{1,3})\s+(.+?)\s*#*$/);
    if (m) title = m[2].trim();
    // 2. Chapter/Part/Book/Section + N
    if (!title) {
      m = raw.match(
        /^(chapter|part|book|section)\s+([0-9]+|[ivxlcdm]+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|thirty|forty|fifty)\b[\s.:—–-]*(.*)$/i
      );
      if (m) {
        const word = m[1].charAt(0).toUpperCase() + m[1].slice(1).toLowerCase();
        const num = m[2].trim();
        const subtitle = (m[3] || "").trim();
        title = subtitle ? `${word} ${num}: ${subtitle}` : `${word} ${num}`;
      }
    }
    // 3. Bare Roman numeral as a short sentence (Standard Ebooks
    //    convention). Cap at 20 chars so a regular sentence
    //    starting with "I" doesn't get treated as a chapter.
    if (!title && raw.length < 20 && ROMAN.test(raw)) {
      title = `Chapter ${raw.replace(/\.$/, "").toUpperCase()}`;
    }
    if (!title) continue;
    // Promote numeric / Roman-only titles to "Chapter <N>" — a TOC
    // entry of just "II" is useless.
    if (NUMERIC.test(title) || /^[ivxlcdm]+$/i.test(title)) {
      title = `Chapter ${title.toUpperCase()}`;
    }
    out.push({ sentence_index: i, title });
  }
  return out;
}

// v206 (M4.3): which chapter contains the given sentence index?
// Returns null if no chapters at all (single-clip mode), or if the
// sentence falls before the first detected chapter (clip preamble).
function _bookViewChapterAt(sentenceIdx) {
  const chapters = (_bookViewSource && _bookViewSource.chapters) || [];
  let last = null;
  for (const ch of chapters) {
    if (ch.sentence_index <= sentenceIdx) last = ch;
    else break;
  }
  return last;
}

// v210 (M6.1): which pages contain a bookmark? Returns a Set of
// page indices. Bookmarks are time-based; convert each timeSec to
// a sentence index via the sentenceOffsetsSec array (cumulative
// per-sentence start times), then lookup the page via
// _bookSentenceToPage. Returns empty if no bookmarks or no
// pagination yet.
function _bookViewBookmarkedPageSet() {
  const out = new Set();
  const bms = (_bookViewSource && _bookViewSource.bookmarks) || [];
  if (!bms.length || !sentenceOffsetsSec || !sentenceOffsetsSec.length) return out;
  for (const bm of bms) {
    const t = (bm && typeof bm.timeSec === "number") ? bm.timeSec : 0;
    let sIdx = 0;
    for (let i = 0; i < sentenceOffsetsSec.length; i++) {
      if (sentenceOffsetsSec[i] <= t) sIdx = i;
      else break;
    }
    const pageIdx = _bookSentenceToPage[sIdx];
    if (pageIdx !== undefined) out.add(pageIdx);
  }
  return out;
}

// v206 (M4.2): is the given sentence index the first sentence of a
// chapter? Used by the renderer to decide drop-cap placement.
function _bookViewIsChapterStart(sentenceIdx) {
  const chapters = (_bookViewSource && _bookViewSource.chapters) || [];
  for (const ch of chapters) {
    if (ch.sentence_index === sentenceIdx) return true;
    if (ch.sentence_index > sentenceIdx) return false;
  }
  return false;
}

// Pure helper: split a list of sentences into per-page buckets by
// measuring how many fit in a given page height. Uses a hidden
// measurement container styled identically to a real .book-page so
// font metrics + hyphenation match exactly. Returns an array of
// [sentenceIndex, ...] for each page.
//
// v197 (M2): the probe page now includes the same header + footer
// elements that the renderer produces, so the body's available
// height reflects the actual rendered page. Without these stand-ins,
// the paginator would over-fill pages by ~50px each (header height +
// footer height + their borders/margins) and rendered pages would
// silently overflow.
//
// v200 (M3.2): optional imgByIdx (sentence_index → [imgRecord, ...])
// and imgDims (src → {width, height} | null) interleave images with
// sentences. An image attached to sentence N renders BEFORE that
// sentence; if image + sentence don't fit on the current page,
// both move to the next page together (the image is "anchored" to
// its sentence and never separates from it).
function _bookViewPaginate(sentences, pageWidth, pageHeight, imgByIdx, imgDims) {
  if (!sentences.length) return [[]];

  // Build the off-screen measurement page.
  const probe = document.createElement("div");
  probe.className = "book-view-measure";
  // v199 (M3.1): copy the book-view's current theme onto the probe
  // so measurement uses the same font family / line-height /
  // column-count as the live render. Without this, switching themes
  // would paginate against paperback metrics but render with
  // magazine metrics, and pages would visibly overflow.
  if (bookView && bookView.dataset.bookTheme) {
    probe.dataset.bookTheme = bookView.dataset.bookTheme;
  }
  // v199 (M3.1): also copy the font-size custom property — it's set
  // on bookView's style attribute (not a CSS rule), so it doesn't
  // cascade to the probe unless the probe is mounted inside bookView
  // or the var is restated here.
  if (bookView) {
    const fs = bookView.style.getPropertyValue("--book-font-size");
    if (fs) probe.style.setProperty("--book-font-size", fs);
  }
  const page = document.createElement("div");
  page.className = "book-page";
  page.style.width = `${pageWidth}px`;
  page.style.height = `${pageHeight}px`;
  // Header probe — same class as the real header, populated with a
  // 1-char placeholder so the line-height + padding compute (an
  // empty element collapses to 0 height in some font stacks).
  const probeHeader = document.createElement("div");
  probeHeader.className = "book-page-header";
  probeHeader.textContent = "·";
  page.appendChild(probeHeader);
  const body = document.createElement("div");
  body.className = "book-page-body";
  page.appendChild(body);
  // Footer probe.
  const probeFooter = document.createElement("div");
  probeFooter.className = "book-page-footer";
  probeFooter.textContent = "·";
  page.appendChild(probeFooter);
  probe.appendChild(page);
  document.body.appendChild(probe);

  const pages = [[]];
  let current = pages[0];
  // v200 (M3.2): each iteration places an image-anchored unit
  // (= zero or more images attached to sentence i, then the sentence
  // itself). The unit is atomic — if any part overflows, the whole
  // unit moves to the next page so the image stays with its sentence.
  for (let i = 0; i < sentences.length; i++) {
    // v206 (M4.2): force a page break BEFORE a chapter start so each
    // chapter opens on a fresh page (book convention). Skip when the
    // current page is empty — chapter 1 is allowed to lead the first
    // page. _bookViewIsChapterStart reads from _bookViewSource.chapters
    // which enterBookView populates before calling the paginator.
    if (current.length > 0 && _bookViewIsChapterStart(i)) {
      pages.push([]);
      current = pages[pages.length - 1];
      body.innerHTML = "";
    }
    const imgs = imgByIdx ? (imgByIdx.get(i) || []) : [];
    const placedImgEls = [];
    for (const img of imgs) {
      const el = _bookViewMakeImageEl(img, imgDims, pageWidth, pageHeight);
      body.appendChild(el);
      placedImgEls.push(el);
    }
    const span = document.createElement("span");
    span.className = "sentence";
    span.textContent = sentences[i] + " ";
    body.appendChild(span);
    if (_bookViewBodyOverflows(body, pageHeight)) {
      // Roll the entire unit off the current page.
      for (const el of placedImgEls) body.removeChild(el);
      body.removeChild(span);
      // Edge case: current page is empty AND the unit still won't
      // fit. Accept it on its own page (overflow visually trimmed
      // by CSS overflow: hidden on .book-page). Without this the
      // loop would infinite-loop on an oversize-image scenario.
      if (current.length === 0) {
        for (const img of imgs) {
          body.appendChild(_bookViewMakeImageEl(img, imgDims, pageWidth, pageHeight));
        }
        body.appendChild(span);
        current.push(i);
        pages.push([]);
        current = pages[pages.length - 1];
        body.innerHTML = "";
        continue;
      }
      // Start a new page with this unit.
      pages.push([i]);
      current = pages[pages.length - 1];
      body.innerHTML = "";
      for (const img of imgs) {
        body.appendChild(_bookViewMakeImageEl(img, imgDims, pageWidth, pageHeight));
      }
      const span2 = document.createElement("span");
      span2.className = "sentence";
      span2.textContent = sentences[i] + " ";
      body.appendChild(span2);
    } else {
      current.push(i);
    }
  }
  if (current.length === 0 && pages.length > 1) pages.pop();
  // v207 (M5.2): trailing images (sentence_index >= sentences.length)
  // get their own paginated section. Previously the renderer just
  // dumped them on the last text page without an overflow check —
  // a chapter with many or oversize trailing figures would silently
  // clip. Now we measure each, fitting on the current (last text)
  // page first; on overflow, spill into new pages.
  //
  // Per-page trailing-image bucket lives on _bookViewSource so the
  // renderer can look it up by page index without changing the
  // _bookViewPages return shape. Cleared at the start of every
  // paginate so a previous run's data doesn't leak in.
  const trailingByPage = new Map();
  if (_bookViewSource) _bookViewSource.trailingByPage = trailingByPage;
  const trailing = imgByIdx ? (imgByIdx.get(sentences.length) || []) : [];
  if (trailing.length) {
    // current/body still reflect the state of the last text page
    // from the loop above. Try fitting each trailing image there
    // before spilling.
    for (const img of trailing) {
      let el = _bookViewMakeImageEl(img, imgDims, pageWidth, pageHeight);
      body.appendChild(el);
      if (_bookViewBodyOverflows(body, pageHeight)) {
        body.removeChild(el);
        // Spill: create a fresh trailing page (empty sentence list).
        pages.push([]);
        current = pages[pages.length - 1];
        body.innerHTML = "";
        el = _bookViewMakeImageEl(img, imgDims, pageWidth, pageHeight);
        body.appendChild(el);
      }
      const pageIdx = pages.length - 1;
      if (!trailingByPage.has(pageIdx)) trailingByPage.set(pageIdx, []);
      trailingByPage.get(pageIdx).push(img);
    }
  }
  probe.remove();
  return pages;
}

// Build the actual book DOM from the paginated buckets. Renders one
// or two pages at a time (driven by _bookViewPagesPerSpread) into
// the spread container. The cover takes slot 0 on the first spread;
// text pages flow into the remaining slots. Returns the total spread
// count so the indicator + nav state can update.
function _bookViewRenderSpread(spreadIdx, flipDirection = null) {
  if (!bookViewSpread) return 0;
  // v220: capture the page that's about to flip out BEFORE we wipe
  // the DOM. We'll re-attach it as an absolutely-positioned overlay
  // after the new spread is rendered, then animate it rotating
  // around the spine. backface-visibility: hidden in the CSS makes
  // the overlay disappear at the 90° mark, revealing the new content
  // underneath without us having to render anything to the back side.
  let _flipOverlay = null;
  if (
    flipDirection &&
    bookViewSpread.children.length > 0 &&
    _bookViewAnimationsEnabled()
  ) {
    // forward: the right page flips away; back: the left page does.
    // On mobile (single-page spreads) there's just one slot, which
    // is the page we flip regardless of direction.
    const ppr = _bookViewPagesPerSpread();
    const flipSlot = ppr === 2 ? (flipDirection === "forward" ? 1 : 0) : 0;
    const oldPage = bookViewSpread.children[flipSlot];
    if (oldPage) {
      _flipOverlay = oldPage.cloneNode(true);
      _flipOverlay.classList.add("book-page-flipping");
      _flipOverlay.classList.add(`flip-${flipDirection}`);
    }
  }
  bookViewSpread.innerHTML = "";
  _bookSentenceSpans = [];
  const ppr = _bookViewPagesPerSpread();
  // Spread 0 reserves the left slot for the cover; subsequent spreads
  // pack page content into all slots. So total spreads is
  // ceil((textPages + 1coverSlot) / ppr) on desktop, or
  // 1coverSpread + ceil(textPages/1) on mobile.
  const textPageCount = _bookViewPages.length;
  let totalSpreads;
  if (ppr === 2) {
    totalSpreads = Math.ceil((textPageCount + 1) / 2);
  } else {
    // Mobile: cover gets its own spread, then one text page per spread.
    totalSpreads = textPageCount + 1;
  }
  if (totalSpreads < 1) totalSpreads = 1;
  _bookViewSpreadsCount = totalSpreads;
  if (spreadIdx < 0) spreadIdx = 0;
  if (spreadIdx >= totalSpreads) spreadIdx = totalSpreads - 1;
  _bookViewCurrentSpread = spreadIdx;

  // Compute which "slot" of the global flow we're rendering. Slot 0
  // is always the cover; slots 1..N are text page indexes 0..N-1.
  const startSlot = spreadIdx * ppr;
  for (let s = 0; s < ppr; s++) {
    const slot = startSlot + s;
    const pageEl = document.createElement("div");
    pageEl.className = "book-page";
    if (slot === 0) {
      // Cover page.
      pageEl.classList.add("book-page-cover");
      const src = _bookViewSource;
      // v225g12 (#700): _coverImgSrc handles all three formats:
      //   - { blob }   — canonical, from custom uploads
      //   - "data:…"   — from image_detector auto-detect (ebook saves)
      //   - { src: "data:…" } — defensive, in case the shape varies
      // Without this fallback the book view cover slot rendered the
      // seed-letter gradient even when the EPUB had a real cover,
      // because _openAsEbook saves clip.cover as a bare data URL
      // string (not the {blob,...} shape custom uploads use).
      const coverImgSrc = _coverImgSrc(src && src.cover);
      if (coverImgSrc) {
        const img = document.createElement("img");
        img.className = "book-page-cover-art";
        img.alt = src.title || "Cover";
        img.src = coverImgSrc.url;
        if (coverImgSrc.revoke) {
          img.addEventListener("load", () => URL.revokeObjectURL(img.src), { once: true });
        }
        pageEl.appendChild(img);
      } else {
        // Hash-gradient fallback. Uses the same title-hash color the
        // library card swatch derives so the cover matches the card.
        const fb = document.createElement("div");
        fb.className = "book-page-cover-fallback";
        const seed = (src && src.title) || "Untitled";
        fb.style.background = _coverFallbackGradient(seed);
        fb.textContent = seed.trim().slice(0, 1).toUpperCase() || "•";
        pageEl.appendChild(fb);
      }
      if (src && src.title) {
        const t = document.createElement("div");
        t.className = "book-page-cover-title";
        t.textContent = src.title;
        pageEl.appendChild(t);
      }
    } else {
      // Text page. slot 1 → text page 0; slot 2 → text page 1; ...
      const textPageIdx = slot - 1;
      const sentenceIdxs = _bookViewPages[textPageIdx] || [];

      // v210 (M6.1): bookmarked-page ribbon. A small accent-coloured
      // pennant in the top-right corner appears on every page that
      // contains a saved bookmark (resolved via timeSec → sentence
      // → page). Placed at the page level (not body) so it survives
      // body re-renders and doesn't get caught in column flow.
      // v220bb: ribbon is now a button — tap it to remove the
      // bookmark(s) on this page. If multiple bookmarks resolve here,
      // all go. Stops propagation so the tap isn't also treated as a
      // page-flip swipe by M6.4.
      if (_bookViewBookmarkedPageSet().has(textPageIdx)) {
        const ribbon = document.createElement("button");
        ribbon.type = "button";
        ribbon.className = "book-page-bookmark";
        ribbon.setAttribute("aria-label", "Remove bookmark from this page");
        ribbon.title = "Tap to remove bookmark";
        const _pageIdxForHandler = textPageIdx;
        ribbon.addEventListener("click", (e) => {
          e.stopPropagation();
          e.preventDefault();
          _deleteBookmarksOnBookViewPage(_pageIdxForHandler);
        });
        pageEl.appendChild(ribbon);
      }

      // v197 (M2) + v206 (M4.3): running header. When chapters are
      // detected, use the title of the chapter containing this
      // page's first sentence (book convention — left page would
      // ideally be the clip title, right page the chapter, but the
      // simpler "chapter on every page" reads cleanly in a single-
      // spread book view). Falls back to the clip title when no
      // chapter covers this page (preamble before chapter 1) OR
      // when there are no detected chapters at all.
      const _firstSentenceForHeader =
        (_bookViewPages[textPageIdx] && _bookViewPages[textPageIdx][0]) || 0;
      const _chapterForHeader = _bookViewChapterAt(_firstSentenceForHeader);
      const headerTitle =
        (_chapterForHeader && _chapterForHeader.title) ||
        (_bookViewSource && _bookViewSource.title) ||
        "";
      if (headerTitle) {
        const header = document.createElement("div");
        header.className = "book-page-header";
        header.textContent = headerTitle;
        pageEl.appendChild(header);
      }

      const body = document.createElement("div");
      body.className = "book-page-body";
      // v197 (M2) + v206 (M4.2): drop cap on the first page of
      // every chapter. The first text page is treated as chapter 0
      // even when no chapters are detected — single-clip fallback.
      const _firstSentence = sentenceIdxs[0];
      if (textPageIdx === 0 || _bookViewIsChapterStart(_firstSentence)) {
        body.dataset.dropCap = "true";
      }
      // v200 (M3.2): images for any sentence on this page render
      // inline before their anchor sentence. Source of truth is
      // _bookViewSource.imgByIdx (computed in enterBookView and
      // reused on repagination so the renderer never re-buckets).
      // v206 (M4.2): chapter-aware drop cap. Drop cap fires when
      // any sentence on this page is the start of a chapter (not
      // just textPageIdx === 0). The paginator forces a page break
      // before each chapter, so chapter-start is always the page's
      // FIRST sentence — that's where ::first-letter targets.
      const imgByIdx = (_bookViewSource && _bookViewSource.imgByIdx) || null;
      for (const sIdx of sentenceIdxs) {
        if (imgByIdx && imgByIdx.has(sIdx)) {
          for (const img of imgByIdx.get(sIdx)) {
            const el = document.createElement("img");
            el.className = "book-inline-image";
            el.src = img.src;
            el.alt = img.alt || "";
            el.loading = "lazy";
            el.decoding = "async";
            el.addEventListener("error", () => el.remove(), { once: true });
            body.appendChild(el);
          }
        }
        const span = document.createElement("span");
        span.className = "sentence";
        span.dataset.index = String(sIdx);
        const wc = _countWords(_bookViewSource.sentences[sIdx]);
        if (wc >= LONG_SENTENCE_WORD_THRESHOLD) {
          span.dataset.longSentence = "true";
          span.dataset.wordCount = String(wc);
          span.title = `${wc} words`;
        }
        // v211 (M7.1): use the shared content builder so any saved
        // highlights for this sentence render as wrapped spans.
        // Falls back to plain text when there are no highlights.
        const _hl = (_bookViewSource && _bookViewSource.highlights) || [];
        span.innerHTML = _buildSentenceContentHTML(
          _bookViewSource.sentences[sIdx], sIdx, _hl
        ) + " ";
        // Click → seek audio. Reuses the existing seekToSentence path.
        // v187: clicking a sentence on the visible spread means
        // "engage here" — drop the pinned state so the highlight
        // resumes auto-following.
        span.addEventListener("click", () => {
          _bookViewUserPaged = false;
          seekToSentence(sIdx);
          if (playerEl.paused) playerEl.play().catch(() => {});
        });
        body.appendChild(span);
        _bookSentenceSpans[sIdx] = span;
      }
      // v207 (M5.2): trailing images live in a per-page bucket on
      // _bookViewSource.trailingByPage (populated by the paginator).
      // Render whatever images this specific page got; if the
      // paginator put zero on this page, this is a no-op.
      const _trailingForThisPage =
        (_bookViewSource && _bookViewSource.trailingByPage &&
          _bookViewSource.trailingByPage.get(textPageIdx)) || [];
      for (const img of _trailingForThisPage) {
        const el = document.createElement("img");
        el.className = "book-inline-image";
        el.src = img.src;
        el.alt = img.alt || "";
        el.loading = "lazy";
        el.decoding = "async";
        el.addEventListener("error", () => el.remove(), { once: true });
        body.appendChild(el);
      }
      pageEl.appendChild(body);

      // v197 (M2): page-number footer. textPageIdx is 0-indexed;
      // human page numbers are 1-indexed. Skipping the "of N"
      // suffix avoids re-rendering every page when a single page's
      // count drifts (e.g., re-pagination at a new font size); a
      // single number is what real books show anyway.
      const footer = document.createElement("div");
      footer.className = "book-page-footer";
      footer.textContent = String(textPageIdx + 1);
      pageEl.appendChild(footer);
    }
    bookViewSpread.appendChild(pageEl);
  }
  _bookViewUpdateNav();
  // After re-render, re-apply the karaoke state for the currently-
  // active sentence (if any). The reading view's spans already carry
  // .active; the book view's freshly-minted spans need to catch up.
  if (activeSentenceIdx >= 0) {
    _bookViewApplyActive(activeSentenceIdx);
  }
  // v220: page-flip animation. _flipOverlay was captured at the top
  // of the function from the OLD spread, before this re-render wiped
  // it. Re-attach it as an absolute overlay over the spread; the CSS
  // keyframes rotate it around the spine, and backface-visibility:
  // hidden makes it disappear at the 90° mark — exposing the new
  // content (already rendered) underneath. We listen for animationend
  // so we can clean up the orphan node.
  if (_flipOverlay) {
    bookViewSpread.appendChild(_flipOverlay);
    const overlay = _flipOverlay;
    const cleanup = () => {
      overlay.removeEventListener("animationend", cleanup);
      overlay.removeEventListener("animationcancel", cleanup);
      overlay.remove();
    };
    overlay.addEventListener("animationend", cleanup);
    // Belt-and-suspenders: if a tab-switch or rapid re-render aborts
    // the animation, animationcancel fires and we still clean up.
    overlay.addEventListener("animationcancel", cleanup);
    // Hard fallback — if no event fires within 1.2s (animation is 0.6s),
    // assume something went wrong and yank the overlay anyway.
    setTimeout(cleanup, 1200);
  }
  return totalSpreads;
}

// v220: prefers-reduced-motion + an opt-out localStorage flag for
// users who find the flip distracting. Defaults to enabled.
function _bookViewAnimationsEnabled() {
  try {
    if (localStorage.getItem("narrative.bookFlipDisabled") === "1") return false;
  } catch {}
  if (typeof window.matchMedia === "function") {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return false;
  }
  return true;
}

function _bookViewUpdateNav() {
  if (bookViewPrev) bookViewPrev.disabled = _bookViewCurrentSpread <= 0;
  if (bookViewNext) bookViewNext.disabled = _bookViewCurrentSpread >= _bookViewSpreadsCount - 1;
  if (bookViewIndicator && !_bookViewIndicatorEditing) {
    // v208 (M6.2): guard textContent update during edit mode so the
    // user's input field isn't clobbered by a re-render mid-typing.
    bookViewIndicator.textContent =
      `Spread ${_bookViewCurrentSpread + 1} of ${_bookViewSpreadsCount}`;
  }
  // v187: show "Return to current" only when the user has scrubbed
  // away from where the audio is. Also requires actual audio
  // progress — no point offering a return when nothing's playing yet.
  if (bookViewReturn) {
    if (
      _bookViewUserPaged &&
      activeSentenceIdx >= 0 &&
      _bookSentenceToPage.length > 0
    ) {
      const ppr = _bookViewPagesPerSpread();
      const activeSpread = _bookViewSpreadOfSentence(activeSentenceIdx, ppr);
      bookViewReturn.hidden = activeSpread === _bookViewCurrentSpread;
    } else {
      bookViewReturn.hidden = true;
    }
  }
}

// v187: helper called from every manual-nav path (prev/next buttons,
// arrow keys, swipe). Renders the requested spread + flips the
// pinned flag on so subsequent active-sentence updates don't yank
// the spread back. Centralized so a future fourth manual-nav path
// (keyboard shortcuts overlay, gestures, etc.) just calls this.
function _bookViewNavigateManual(targetSpread) {
  // v225v3.7 (#741): page flip reveals the nav + restarts auto-hide
  // countdown so user always sees the new "Spread X of Y" after a flip.
  if (typeof _bookViewShowNav === "function") {
    try { _bookViewShowNav(); } catch {}
  }
  // v225v3.0 (#734): V3 branch — page-row translateX navigation.
  if (_bookViewV3Enabled()) {
    _bookViewV3GotoSpread(targetSpread);
    return;
  }
  // v225h0 (#728): V2 branch — multi-column flow doesn't use the V1
  // spread-render path. Translate the flow container directly.
  if (_bookViewV2Enabled()) {
    _bookViewV2GotoSpread(targetSpread);
    return;
  }
  if (targetSpread < 0 || targetSpread >= _bookViewSpreadsCount) return;
  _bookViewUserPaged = true;
  // v220: pass the direction so _bookViewRenderSpread can play the
  // page-flip animation. Same-spread or jump-by-N (e.g. page-jump,
  // TOC) skip the animation by passing null.
  const dir = targetSpread > _bookViewCurrentSpread ? "forward"
    : targetSpread < _bookViewCurrentSpread ? "backward"
    : null;
  // Only animate single-step transitions; multi-spread jumps (TOC,
  // page-jump, return-to-current) would look weird with a flip.
  const animate = dir !== null && Math.abs(targetSpread - _bookViewCurrentSpread) === 1;
  _bookViewRenderSpread(targetSpread, animate ? dir : null);
}

// =====================================================================
// v225h0 (#728): Book View V2 — multi-column module (Phase 1)
// =====================================================================
//
// Feature-flagged via localStorage.bookViewV2 = "true" or
// ?bookviewv2=1 in the URL. When on, enterBookView and
// _bookViewNavigateManual branch into the V2 functions below.
//
// Phase 1 scope: sentence + image rendering, prev/next nav, spread
// count via measurement-free CSS columns. Bookmarks/TOC/find/drop
// caps/print/3D flip are dropped — added back in Phase 2.

const _bookViewV2State = {
  spreadIdx: 0,
  spreadCount: 1,
  spreadWidth: 0,
  // v225h0.5 (#730): sentence-idx anchor for the start of the current
  // spread. Used by the resize handler to preserve reading position
  // when columns reflow (window resize, phone rotation, etc).
  anchorSentenceIdx: null,
};

function _bookViewV2Enabled() {
  try {
    // URL param wins (so QA can opt in without persisting).
    const params = new URLSearchParams(window.location.search);
    if (params.get("bookviewv2") === "1") {
      localStorage.setItem("bookViewV2", "true");
      return true;
    }
    return localStorage.getItem("bookViewV2") === "true";
  } catch {
    return false;
  }
}

function _bookViewV2Setup(source) {
  const spread = bookViewSpread;
  // Mark spread with v2 class so CSS overrides kick in. Remove if
  // re-entering after V1 use.
  spread.classList.add("v2");
  spread.innerHTML = "";

  const flow = document.createElement("div");
  flow.className = "book-view-flow";

  // Copy theme + font-size to the spread so the CSS vars cascade
  // into the flow exactly like the live render does in V1.
  if (bookView && bookView.dataset.bookTheme) {
    spread.dataset.bookTheme = bookView.dataset.bookTheme;
  }

  // Cover image as the first column.
  if (source.cover) {
    const resolved = typeof _coverImgSrc === "function"
      ? _coverImgSrc(source.cover)
      : null;
    const coverUrl = resolved ? resolved.url
      : typeof source.cover === "string" ? source.cover
      : (source.cover && source.cover.src) ? source.cover.src
      : null;
    if (coverUrl) {
      const coverWrap = document.createElement("div");
      coverWrap.className = "v2-cover-page";
      const img = document.createElement("img");
      img.src = coverUrl;
      img.alt = source.title || "Cover";
      coverWrap.appendChild(img);
      flow.appendChild(coverWrap);
    }
  }

  // Sentences with attached images in document order. v225h1 (#731):
  // each image goes in a .v2-image-page wrapper so CSS break-before/
  // break-after forces it onto its own column. Avoids the unbalanced
  // "image + 2 orphan lines" column we get with interleaved flow.
  const sentences = source.sentences || [];
  const imgByIdx = source.imgByIdx;
  const appendImagePage = (img) => {
    const wrap = document.createElement("div");
    wrap.className = "v2-image-page";
    const el = document.createElement("img");
    el.src = img.url || img.src;
    el.alt = img.alt || "";
    el.loading = "lazy";
    wrap.appendChild(el);
    flow.appendChild(wrap);
  };
  for (let i = 0; i < sentences.length; i++) {
    const imgs = imgByIdx ? (imgByIdx.get(i) || []) : [];
    for (const img of imgs) appendImagePage(img);
    const span = document.createElement("span");
    span.className = "sentence";
    span.dataset.idx = String(i);
    span.textContent = sentences[i] + " ";
    flow.appendChild(span);
  }

  // Trailing images (sentence_index = sentences.length) — also each
  // get their own page.
  if (imgByIdx) {
    const trailing = imgByIdx.get(sentences.length) || [];
    for (const img of trailing) appendImagePage(img);
  }

  spread.appendChild(flow);

  // Measure after layout settles. Two rAFs because the first frame
  // applies layout, the second has accurate scrollWidth.
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      _bookViewV2Measure();
      _bookViewV2GotoSpread(0);
      // Re-measure on image load (column count can change).
      const imgs = spread.querySelectorAll("img");
      let pendingImgs = imgs.length;
      if (pendingImgs === 0) return;
      imgs.forEach((img) => {
        if (img.complete) {
          pendingImgs--;
        } else {
          img.addEventListener("load", () => {
            pendingImgs--;
            if (pendingImgs <= 0) {
              _bookViewV2Measure();
              _bookViewV2GotoSpread(_bookViewV2State.spreadIdx);
            }
          }, { once: true });
          img.addEventListener("error", () => {
            pendingImgs--;
            if (pendingImgs <= 0) {
              _bookViewV2Measure();
              _bookViewV2GotoSpread(_bookViewV2State.spreadIdx);
            }
          }, { once: true });
        }
      });
      if (pendingImgs === 0) {
        _bookViewV2Measure();
        _bookViewV2GotoSpread(_bookViewV2State.spreadIdx);
      }
    });
  });
}

// v225h3 (#733): Readium-style two-phase layout. Phase A: lay out the
// flow as a single column at pageWidth and read scrollHeight (=
// total content height). Phase B: divide by pageHeight to get column
// count N. Phase C: lock the flow at columnCount:N, width:N*pageWidth,
// height:pageHeight — browser knows exactly what to make, no overflow
// clipping. Phase D: verify by reading where the last visible content
// piece actually sits and adjust N if our estimate was off.
function _bookViewV2Measure() {
  const spread = bookViewSpread;
  const flow = spread.querySelector(".book-view-flow");
  if (!flow) return;

  const isPhone = window.innerWidth <= 720;
  const pagesPerSpread = isPhone ? 1 : 2;
  const spreadWidth = spread.clientWidth;
  const pageWidth = spreadWidth / pagesPerSpread;
  const pageHeight = spread.clientHeight;

  // --- Phase A: single-column natural-height measurement --------------
  // Reset to single-column so scrollHeight = true content height.
  flow.style.transform = "none";
  flow.style.position = "relative";
  flow.style.width = pageWidth + "px";
  flow.style.height = "auto";
  flow.style.columnCount = "1";
  flow.style.columnWidth = "auto";
  // Force synchronous layout flush.
  // eslint-disable-next-line no-unused-expressions
  flow.offsetHeight;
  const contentHeight = flow.scrollHeight;

  // --- Phase B: estimate column count needed --------------------------
  // Each image with break-before:column + break-after:column eats one
  // extra column boundary. Add 2*imageCount safety margin + 2 to cover
  // mid-content widows. Overestimating is cheap (extra empty columns
  // are invisible after Phase D trim); underestimating clips content.
  const imageCount = flow.querySelectorAll(
    ".v2-image-page, .v2-cover-page"
  ).length;
  const estimatedColumns = Math.max(
    1,
    Math.ceil(contentHeight / Math.max(pageHeight, 100)) + 2 * imageCount + 2
  );

  // --- Phase C: lock multi-column layout ------------------------------
  flow.style.position = "absolute";
  flow.style.top = "0";
  flow.style.left = "0";
  flow.style.width = (estimatedColumns * pageWidth) + "px";
  flow.style.height = pageHeight + "px";
  flow.style.columnCount = String(estimatedColumns);
  flow.style.columnWidth = "auto";
  // Force flush so the multi-column layout settles before we measure.
  // eslint-disable-next-line no-unused-expressions
  flow.offsetWidth;

  // --- Phase D: trim to actual used columns ---------------------------
  // Find the rightmost piece of content (any sentence, image-page, or
  // cover-page). Divide its right edge by pageWidth to get the actual
  // column count used.
  const flowRect = flow.getBoundingClientRect();
  let maxRight = 0;
  const blocks = flow.querySelectorAll(
    ".sentence, .v2-image-page, .v2-cover-page"
  );
  blocks.forEach((el) => {
    const r = el.getBoundingClientRect();
    const relRight = r.right - flowRect.left;
    if (relRight > maxRight) maxRight = relRight;
  });
  let actualColumns = Math.max(1, Math.ceil(maxRight / pageWidth));

  // If actualColumns >= estimatedColumns, content overflowed our
  // estimate — re-layout with double and re-measure once.
  if (actualColumns >= estimatedColumns) {
    const N2 = estimatedColumns * 2;
    flow.style.width = (N2 * pageWidth) + "px";
    flow.style.columnCount = String(N2);
    // eslint-disable-next-line no-unused-expressions
    flow.offsetWidth;
    maxRight = 0;
    blocks.forEach((el) => {
      const r = el.getBoundingClientRect();
      const relRight = r.right - flowRect.left;
      if (relRight > maxRight) maxRight = relRight;
    });
    actualColumns = Math.max(1, Math.ceil(maxRight / pageWidth));
  }

  // Trim if we overestimated significantly.
  if (actualColumns < estimatedColumns) {
    flow.style.width = (actualColumns * pageWidth) + "px";
    flow.style.columnCount = String(actualColumns);
    // eslint-disable-next-line no-unused-expressions
    flow.offsetWidth;
  }

  // --- Done: update state -------------------------------------------
  _bookViewV2State.spreadWidth = spreadWidth;
  _bookViewV2State.spreadCount = Math.max(
    1,
    Math.ceil(actualColumns / pagesPerSpread)
  );
  _bookViewSpreadsCount = _bookViewV2State.spreadCount;

  if (typeof _dlog === "function") {
    _dlog("book-v2", "compute-layout", {
      spreadWidth,
      pageWidth,
      pageHeight,
      pagesPerSpread,
      contentHeight,
      imageCount,
      estimatedColumns,
      actualColumns,
      spreadCount: _bookViewV2State.spreadCount,
    });
  }
}

function _bookViewV2GotoSpread(n) {
  const spread = bookViewSpread;
  const flow = spread.querySelector(".book-view-flow");
  if (!flow) return;
  const total = _bookViewV2State.spreadCount;
  const target = Math.max(0, Math.min(n, total - 1));
  _bookViewV2State.spreadIdx = target;
  _bookViewCurrentSpread = target;
  flow.style.transform = `translateX(${-target * _bookViewV2State.spreadWidth}px)`;
  // v225h0.5 (#730): capture the sentence-idx at the start of this
  // spread so the resize handler can re-anchor reading position
  // after columns reflow.
  _bookViewV2State.anchorSentenceIdx =
    _bookViewV2FirstSentenceIdxAtSpread(target);
  _bookViewV2UpdateNav();
}

// v225h0.5 (#730): find the first sentence whose offsetLeft falls
// inside the given spread. Used to capture (on goto) and restore
// (on resize) reading position.
function _bookViewV2FirstSentenceIdxAtSpread(spreadIdx) {
  const spread = bookViewSpread;
  const flow = spread.querySelector(".book-view-flow");
  if (!flow) return null;
  const targetX = spreadIdx * _bookViewV2State.spreadWidth;
  const sentences = flow.querySelectorAll(".sentence");
  for (const s of sentences) {
    if (s.offsetLeft >= targetX) {
      const idx = parseInt(s.dataset.idx, 10);
      if (!isNaN(idx)) return idx;
    }
  }
  // Fallback: last sentence (we're on the final spread).
  if (sentences.length) {
    const last = sentences[sentences.length - 1];
    const idx = parseInt(last.dataset.idx, 10);
    return isNaN(idx) ? null : idx;
  }
  return null;
}

// v225h0.5 (#730): jump to whichever spread contains the given
// sentence. Called by the resize handler post-reflow to preserve
// the user's reading position. Bypasses GotoSpread's anchor capture
// (anchor stays unchanged across the re-anchor).
function _bookViewV2GotoSentenceIdx(sentenceIdx) {
  const spread = bookViewSpread;
  const flow = spread.querySelector(".book-view-flow");
  if (!flow) return;
  const span = flow.querySelector(`.sentence[data-idx="${sentenceIdx}"]`);
  if (!span) {
    _bookViewV2GotoSpread(0);
    return;
  }
  const newSpread = Math.floor(
    span.offsetLeft / Math.max(_bookViewV2State.spreadWidth, 1)
  );
  // Don't re-capture anchor — keep the original sentence-idx so
  // subsequent resizes still target the same place.
  const total = _bookViewV2State.spreadCount;
  const target = Math.max(0, Math.min(newSpread, total - 1));
  _bookViewV2State.spreadIdx = target;
  _bookViewCurrentSpread = target;
  flow.style.transform = `translateX(${-target * _bookViewV2State.spreadWidth}px)`;
  _bookViewV2UpdateNav();
}

function _bookViewV2UpdateNav() {
  if (bookViewIndicator) {
    bookViewIndicator.textContent =
      `Spread ${_bookViewV2State.spreadIdx + 1} of ${_bookViewV2State.spreadCount}`;
  }
  if (bookViewPrev) {
    bookViewPrev.disabled = _bookViewV2State.spreadIdx <= 0;
  }
  if (bookViewNext) {
    bookViewNext.disabled =
      _bookViewV2State.spreadIdx >= _bookViewV2State.spreadCount - 1;
  }
}

// v225h0.5 (#730): debounced + anchor-preserving resize handler.
// Native `resize` fires ~60×/s during a window drag — re-measuring
// on every event causes layout thrash. Debounce to 120ms (after the
// user stops dragging) and use the stored sentence-idx anchor so
// reading position survives the column reflow.
let _bookViewV2ResizeTimer = null;
window.addEventListener("resize", () => {
  if (!_bookViewV2Enabled()) return;
  if (!bookView || bookView.hidden) return;
  if (!bookViewSpread.classList.contains("v2")) return;
  if (_bookViewV2ResizeTimer) clearTimeout(_bookViewV2ResizeTimer);
  _bookViewV2ResizeTimer = setTimeout(() => {
    _bookViewV2ResizeTimer = null;
    _bookViewV2Measure();
    const anchor = _bookViewV2State.anchorSentenceIdx;
    if (anchor !== null && anchor !== undefined) {
      _bookViewV2GotoSentenceIdx(anchor);
    } else {
      _bookViewV2GotoSpread(_bookViewV2State.spreadIdx);
    }
  }, 120);
});

async function _enterBookViewV2() {
  if (!_bookViewSource || !_bookViewSource.sentences.length) {
    setStatus("Generate or load a clip first.", true);
    return;
  }
  // Populate title + cover from the loaded clip.
  if (_currentClipId) {
    const clip = await getClip(_currentClipId).catch(() => null);
    if (clip) {
      _bookViewSource.title = clip.title || "Untitled chapter";
      _bookViewSource.cover = clip.cover || null;
      _bookViewSource.bookmarks = clip.bookmarks || [];
      _bookViewSource.highlights = clip.highlights || [];
    }
  } else {
    _bookViewSource.title = "Untitled chapter";
  }

  // Preload image dimensions + bucket by sentence_index (shared with
  // V1; harmless even though V2 doesn't use imgDims for measurement).
  if (!_bookViewSource.imgByIdx) {
    _bookViewSource.imgByIdx = _bookViewBucketImages(
      _bookViewSource.images,
      _bookViewSource.sentences.length
    );
  }
  if (!_bookViewSource.imgDims) {
    bookView.style.visibility = "hidden";
    bookView.hidden = false;
    _bookViewSource.imgDims = await _bookViewPreloadImages(
      _bookViewSource.images || []
    );
  }

  bookView.hidden = false;
  bookView.style.visibility = "hidden";
  readingView.hidden = true;

  _bookViewV2Setup(_bookViewSource);

  if (bookViewToggle) bookViewToggle.textContent = "▶ Audio view";
  bookView.style.visibility = "visible";
  // Scroll the document to the top so the page header is visible.
  try {
    window.scrollTo({ top: 0, behavior: "instant" });
  } catch {
    window.scrollTo(0, 0);
  }
}

// =====================================================================
// v225v3.0 (#734): Book View V3 — manual JS pagination (word-processor)
// =====================================================================
//
// Each page is a real DOM <div> sized exactly to pageWidth × pageHeight.
// Content streams in sentence-by-sentence: append to current page body,
// check scrollHeight > clientHeight, if overflow remove + start new
// page. Images get their own page. No CSS columns anywhere; just
// block layout inside each page with overflow:hidden as the boundary.
//
// Feature-flagged via localStorage.bookViewV3 = "true" or ?bookviewv3=1.

const _bookViewV3State = {
  spreadIdx: 0,
  spreadCount: 1,
  pageCount: 1,
  pagesPerSpread: 2,
  pageWidth: 0,
  spreadWidth: 0,
  anchorSentenceIdx: null,
};

function _bookViewV3Enabled() {
  // v225v3.10 (Phase 2): V3 is now the DEFAULT book-view paginator.
  // ?bookviewv3=0 is the kill switch (persists in localStorage so the
  // fallback survives page reload). ?bookviewv3=1 re-enables for users
  // who explicitly opted out previously.
  try {
    const params = new URLSearchParams(window.location.search);
    if (params.get("bookviewv3") === "1") {
      localStorage.setItem("bookViewV3", "true");
      return true;
    }
    if (params.get("bookviewv3") === "0") {
      localStorage.setItem("bookViewV3", "false");
      return false;
    }
    const stored = localStorage.getItem("bookViewV3");
    if (stored === "false") return false;
    // Default true.
    return true;
  } catch {
    return true;
  }
}

// v225v3.21 (#359): StPageFlip corner-curl integration removed.
// Decision: V3's translateX slide is the keeper. The bundle, helpers,
// and pf.flip() routing have all been deleted. See whats-new.html for
// the rationale. _bookViewV3State.pages cache (set in setup) stays
// because nav helpers benefit from it even without StPageFlip.

function _bookViewV3CreatePage(pageRow, pageWidth, pageHeight) {
  const page = document.createElement("div");
  page.className = "book-view-page";
  page.style.width = pageWidth + "px";
  page.style.height = pageHeight + "px";
  const body = document.createElement("div");
  body.className = "book-view-page-body";
  page.appendChild(body);
  pageRow.appendChild(page);
  return { page, body };
}

function _bookViewV3MakeImagePage(pageRow, pageWidth, pageHeight, src, alt) {
  const { page, body } = _bookViewV3CreatePage(pageRow, pageWidth, pageHeight);
  page.classList.add("book-view-page-image");
  const img = document.createElement("img");
  img.src = src;
  img.alt = alt || "";
  img.loading = "lazy";
  body.appendChild(img);
}

function _bookViewV3Setup(source) {
  const spread = bookViewSpread;
  spread.classList.add("v3");
  spread.classList.remove("v2");
  spread.innerHTML = "";

  if (bookView && bookView.dataset.bookTheme) {
    spread.dataset.bookTheme = bookView.dataset.bookTheme;
  }

  const isPhone = window.innerWidth <= 720;
  const pagesPerSpread = isPhone ? 1 : 2;
  const spreadWidth = spread.clientWidth;
  const pageWidth = spreadWidth / pagesPerSpread;
  const pageHeight = spread.clientHeight;

  const pageRow = document.createElement("div");
  pageRow.className = "book-view-page-row";
  spread.appendChild(pageRow);

  let pageCount = 0;
  // v225v3.10 (Phase 2): text-page index, separate from `pageCount`
  // which includes cover + image pages. _bookSentenceToPage[] indexes
  // by this so TOC / bookmark lookups display "page N" of text
  // content (matching V1's convention).
  let textPageIdx = -1;
  // Reset the shared sentence → text-page map; the bookmark ribbon
  // helper, find-jump, and TOC all read from this.
  _bookSentenceToPage = [];

  // Helper: finalize a text page by appending the page-number footer
  // (matches V1's `.book-page-footer` class so existing CSS applies)
  // and stamping the text-page idx for the post-setup ribbon pass.
  const closeTextPage = (pageObj, tIdx) => {
    if (!pageObj || tIdx < 0) return;
    const footer = document.createElement("div");
    footer.className = "book-page-footer";
    footer.textContent = String(tIdx + 1);
    pageObj.page.appendChild(footer);
    pageObj.page.dataset.textPageIdx = String(tIdx);
  };

  // Cover image as first page (if present).
  if (source.cover) {
    const resolved = typeof _coverImgSrc === "function"
      ? _coverImgSrc(source.cover) : null;
    const coverUrl = resolved ? resolved.url
      : typeof source.cover === "string" ? source.cover
      : (source.cover && source.cover.src) ? source.cover.src
      : null;
    if (coverUrl) {
      _bookViewV3MakeImagePage(pageRow, pageWidth, pageHeight,
        coverUrl, source.title || "Cover");
      pageCount++;
    }
  }

  // Start the first text page.
  let cur = _bookViewV3CreatePage(pageRow, pageWidth, pageHeight);
  pageCount++;
  textPageIdx = 0;
  let hasContent = false;
  // v225v3.10: drop cap on first text page (clip opens here even
  // when no chapters detected — single-clip fallback, mirrors V1
  // line 17073).
  cur.body.dataset.dropCap = "true";

  // Helper: insert an image page, swapping the current empty page for
  // an image page and starting a fresh text page after.
  const pushImage = (src, alt) => {
    if (hasContent) {
      // Close the populated text page first (footer + stamp).
      closeTextPage(cur, textPageIdx);
      cur = _bookViewV3CreatePage(pageRow, pageWidth, pageHeight);
      pageCount++;
      textPageIdx++;
      hasContent = false;
    }
    // cur is now empty — replace with image page.
    pageRow.removeChild(cur.page);
    pageCount--;
    _bookViewV3MakeImagePage(pageRow, pageWidth, pageHeight, src, alt);
    pageCount++;
    // Start a fresh text page for following content. textPageIdx
    // stays where it is — we replaced the empty text page with an
    // image page, and the new text page takes over that index (no
    // numbering gap).
    cur = _bookViewV3CreatePage(pageRow, pageWidth, pageHeight);
    pageCount++;
    hasContent = false;
  };

  const sentences = source.sentences || [];
  const imgByIdx = source.imgByIdx;
  let firstBreakLogged = false;

  for (let i = 0; i < sentences.length; i++) {
    // Images attached to this sentence index get their own page first.
    const imgs = imgByIdx ? (imgByIdx.get(i) || []) : [];
    for (const img of imgs) {
      const src = img.url || img.src;
      if (src) pushImage(src, img.alt || "");
    }

    // Try to add the sentence to the current page.
    const span = document.createElement("span");
    span.className = "sentence";
    span.dataset.idx = String(i);
    span.textContent = sentences[i] + " ";
    cur.body.appendChild(span);
    hasContent = true;
    _bookSentenceToPage[i] = textPageIdx;

    // Overflow check.
    if (cur.body.scrollHeight > cur.body.clientHeight + 1) {
      if (!firstBreakLogged && typeof _dlog === "function") {
        firstBreakLogged = true;
        _dlog("book-v3", "first-break", {
          sentenceIdx: i,
          scrollHeight: cur.body.scrollHeight,
          clientHeight: cur.body.clientHeight,
          pageStyleHeight: cur.page.style.height,
          pageClientHeight: cur.page.clientHeight,
          pageOffsetHeight: cur.page.offsetHeight,
        });
      }
      cur.body.removeChild(span);
      // If the current page had ONLY this sentence and it overflows,
      // we have an oversize sentence. Accept the overflow (clipped by
      // overflow:hidden) rather than infinite-loop.
      if (cur.body.childNodes.length === 0) {
        cur.body.appendChild(span);
        hasContent = true;
        continue;
      }
      // Otherwise, close the current page (footer) and start a new
      // page with this sentence.
      closeTextPage(cur, textPageIdx);
      cur = _bookViewV3CreatePage(pageRow, pageWidth, pageHeight);
      pageCount++;
      textPageIdx++;
      // v225v3.10: chapter-aware drop cap. The paginator places a
      // page break right before a chapter-start sentence, so when
      // that sentence opens a new page it's always the body's first
      // node — ::first-letter targets it correctly.
      if (typeof _bookViewIsChapterStart === "function"
          && _bookViewIsChapterStart(i)) {
        cur.body.dataset.dropCap = "true";
      }
      cur.body.appendChild(span);
      hasContent = true;
      _bookSentenceToPage[i] = textPageIdx;
    }
  }

  // v225v3.1: if NO break was ever triggered (suspicious — content
  // claimed to fit in one page), log what the final body looks like.
  if (!firstBreakLogged && typeof _dlog === "function") {
    _dlog("book-v3", "no-breaks", {
      sentenceCount: sentences.length,
      finalScrollHeight: cur.body.scrollHeight,
      finalClientHeight: cur.body.clientHeight,
      pageClientHeight: cur.page.clientHeight,
      pageStyleHeight: cur.page.style.height,
    });
  }

  // Trailing images.
  if (imgByIdx) {
    const trailing = imgByIdx.get(sentences.length) || [];
    for (const img of trailing) {
      const src = img.url || img.src;
      if (src) pushImage(src, img.alt || "");
    }
  }

  // v225v3.10: close the last text page (footer + dataset stamp) OR
  // remove a trailing empty if pushImage left us with one.
  if (hasContent) {
    closeTextPage(cur, textPageIdx);
  } else if (pageCount > 1) {
    pageRow.removeChild(cur.page);
    pageCount--;
  }

  // v225v3.10 (Phase 2): bookmark-ribbon pass. After all pages exist,
  // attach a tap-to-remove ribbon to any text page that contains a
  // bookmarked sentence (resolved via timeSec → sentence → page in
  // _bookViewBookmarkedPageSet, which reads _bookSentenceToPage
  // populated above). Matches V1 lines 17030-17043.
  const bmSet = (typeof _bookViewBookmarkedPageSet === "function")
    ? _bookViewBookmarkedPageSet() : new Set();
  if (bmSet.size) {
    for (const pageEl of pageRow.children) {
      const tIdxStr = pageEl.dataset && pageEl.dataset.textPageIdx;
      if (!tIdxStr) continue;
      const tIdx = parseInt(tIdxStr, 10);
      if (bmSet.has(tIdx)) {
        const ribbon = document.createElement("button");
        ribbon.type = "button";
        ribbon.className = "book-page-bookmark";
        ribbon.setAttribute("aria-label", "Remove bookmark from this page");
        ribbon.title = "Tap to remove bookmark";
        const _pageIdxForHandler = tIdx;
        ribbon.addEventListener("click", (e) => {
          e.stopPropagation();
          e.preventDefault();
          if (typeof _deleteBookmarksOnBookViewPage === "function") {
            _deleteBookmarksOnBookViewPage(_pageIdxForHandler);
          }
        });
        pageEl.appendChild(ribbon);
      }
    }
  }

  // Fix the page row's width so flex layout has explicit dimensions.
  pageRow.style.width = (pageCount * pageWidth) + "px";

  // Cache the page array so nav helpers don't have to query the DOM
  // on every spread change.
  _bookViewV3State.pages = Array.from(pageRow.children);

  // Compute spread state.
  _bookViewV3State.pageCount = pageCount;
  _bookViewV3State.pagesPerSpread = pagesPerSpread;
  _bookViewV3State.pageWidth = pageWidth;
  _bookViewV3State.spreadWidth = pagesPerSpread * pageWidth;
  _bookViewV3State.spreadCount =
    Math.max(1, Math.ceil(pageCount / pagesPerSpread));
  _bookViewSpreadsCount = _bookViewV3State.spreadCount;

  if (typeof _dlog === "function") {
    _dlog("book-v3", "setup", {
      spreadWidth, pageWidth, pageHeight, pagesPerSpread,
      pageCount, spreadCount: _bookViewV3State.spreadCount,
      sentenceCount: sentences.length,
      textPages: textPageIdx + 1,
      bookmarkedPages: bmSet.size,
    });
  }

  // Initial position.
  _bookViewV3State.spreadIdx = 0;
  _bookViewV3GotoSpread(0);
}

function _bookViewV3GotoSpread(n) {
  const total = _bookViewV3State.spreadCount;
  const target = Math.max(0, Math.min(n, total - 1));

  // translateX slide between spreads.
  const spread = bookViewSpread;
  const pageRow = spread.querySelector(".book-view-page-row");
  if (!pageRow) return;
  _bookViewV3State.spreadIdx = target;
  _bookViewCurrentSpread = target;
  pageRow.style.transform =
    `translateX(${-target * _bookViewV3State.spreadWidth}px)`;
  // Capture anchor (first-page first-sentence) for resize handler.
  _bookViewV3State.anchorSentenceIdx =
    _bookViewV3FirstSentenceIdxAtSpread(target);
  _bookViewV3UpdateNav();
}

function _bookViewV3FirstSentenceIdxAtSpread(spreadIdx) {
  // Prefer cached pages array; fall back to DOM query if setup hasn't
  // populated it yet.
  let pages = _bookViewV3State && _bookViewV3State.pages;
  if (!pages || !pages.length) {
    const spread = bookViewSpread;
    const pageRow = spread && spread.querySelector(".book-view-page-row");
    if (!pageRow) return null;
    pages = pageRow.children;
  }
  const firstPageIdx = spreadIdx * _bookViewV3State.pagesPerSpread;
  if (firstPageIdx >= pages.length) return null;
  for (let k = firstPageIdx;
       k < pages.length && k < firstPageIdx + _bookViewV3State.pagesPerSpread;
       k++) {
    const span = pages[k].querySelector(".sentence");
    if (span) {
      const idx = parseInt(span.dataset.idx, 10);
      if (!isNaN(idx)) return idx;
    }
  }
  return null;
}

function _bookViewV3PageOfSentence(sentenceIdx) {
  // Prefer cached pages array; fall back to DOM query if setup hasn't
  // populated it yet.
  let pages = _bookViewV3State && _bookViewV3State.pages;
  if (!pages || !pages.length) {
    const spread = bookViewSpread;
    const pageRow = spread && spread.querySelector(".book-view-page-row");
    if (!pageRow) return 0;
    pages = Array.from(pageRow.children);
  }
  // Find the page containing the target sentence by walking up from
  // the span.
  let targetSpan = null;
  for (let i = 0; i < pages.length; i++) {
    const s = pages[i].querySelector(`.sentence[data-idx="${sentenceIdx}"]`);
    if (s) { targetSpan = s; break; }
  }
  if (!targetSpan) return 0;
  let el = targetSpan;
  while (el && !(el.classList && el.classList.contains("book-view-page"))) {
    el = el.parentElement;
  }
  if (!el) return 0;
  for (let i = 0; i < pages.length; i++) {
    if (pages[i] === el) return i;
  }
  return 0;
}

function _bookViewV3GotoSentenceIdx(sentenceIdx) {
  const pageIdx = _bookViewV3PageOfSentence(sentenceIdx);
  const ppr = _bookViewV3State.pagesPerSpread;
  const spreadIdx = Math.floor(pageIdx / ppr);
  const total = _bookViewV3State.spreadCount;
  const target = Math.max(0, Math.min(spreadIdx, total - 1));


  // Original translateX path. Bypasses GotoSpread's anchor re-capture
  // so the anchor sentence stays stable across subsequent resizes.
  const spread = bookViewSpread;
  const pageRow = spread.querySelector(".book-view-page-row");
  if (!pageRow) return;
  _bookViewV3State.spreadIdx = target;
  _bookViewCurrentSpread = target;
  pageRow.style.transform =
    `translateX(${-target * _bookViewV3State.spreadWidth}px)`;
  _bookViewV3UpdateNav();
}

function _bookViewV3UpdateNav() {
  if (bookViewIndicator) {
    bookViewIndicator.textContent =
      `Spread ${_bookViewV3State.spreadIdx + 1} of ${_bookViewV3State.spreadCount}`;
  }
  if (bookViewPrev) {
    bookViewPrev.disabled = _bookViewV3State.spreadIdx <= 0;
  }
  if (bookViewNext) {
    bookViewNext.disabled =
      _bookViewV3State.spreadIdx >= _bookViewV3State.spreadCount - 1;
  }
}

// v225v3.1 (#735): use ResizeObserver instead of window.resize so we
// fire AFTER the spread's actual box has resized — handles the case
// where the spread changes size from sidebars / orientation /
// other layout shifts that window.resize doesn't catch.
let _bookViewV3ResizeTimer = null;
let _bookViewV3LastW = 0;
let _bookViewV3LastH = 0;
if (typeof ResizeObserver !== "undefined" && bookViewSpread) {
  const ro = new ResizeObserver((entries) => {
    if (!_bookViewV3Enabled()) return;
    if (!bookView || bookView.hidden) return;
    if (!bookViewSpread.classList.contains("v3")) return;
    // Ignore noisy 1-2px sub-pixel changes — they cause re-paginate
    // loops without changing pagination outcome.
    const entry = entries[0];
    if (!entry) return;
    const w = Math.round(entry.contentRect.width);
    const h = Math.round(entry.contentRect.height);
    if (Math.abs(w - _bookViewV3LastW) < 4 &&
        Math.abs(h - _bookViewV3LastH) < 4) return;
    _bookViewV3LastW = w;
    _bookViewV3LastH = h;
    if (_bookViewV3ResizeTimer) clearTimeout(_bookViewV3ResizeTimer);
    _bookViewV3ResizeTimer = setTimeout(() => {
      _bookViewV3ResizeTimer = null;
      const anchor = _bookViewV3State.anchorSentenceIdx;
      if (typeof _dlog === "function") {
        _dlog("book-v3", "resize-trigger", {
          newW: w, newH: h,
          spreadW: bookViewSpread.clientWidth,
          spreadH: bookViewSpread.clientHeight,
          anchor,
        });
      }
      _bookViewV3Setup(_bookViewSource);
      if (anchor !== null && anchor !== undefined) {
        _bookViewV3GotoSentenceIdx(anchor);
      } else {
        _bookViewV3GotoSpread(0);
      }
    }, 100);
  });
  ro.observe(bookViewSpread);
}

async function _enterBookViewV3() {
  if (!_bookViewSource || !_bookViewSource.sentences.length) {
    setStatus("Generate or load a clip first.", true);
    return;
  }
  if (_currentClipId) {
    const clip = await getClip(_currentClipId).catch(() => null);
    if (clip) {
      _bookViewSource.title = clip.title || "Untitled chapter";
      _bookViewSource.cover = clip.cover || null;
      _bookViewSource.bookmarks = clip.bookmarks || [];
      _bookViewSource.highlights = clip.highlights || [];
    }
  } else {
    _bookViewSource.title = "Untitled chapter";
  }

  if (!_bookViewSource.imgByIdx) {
    _bookViewSource.imgByIdx = _bookViewBucketImages(
      _bookViewSource.images,
      _bookViewSource.sentences.length
    );
  }
  if (!_bookViewSource.imgDims) {
    bookView.style.visibility = "hidden";
    bookView.hidden = false;
    _bookViewSource.imgDims = await _bookViewPreloadImages(
      _bookViewSource.images || []
    );
  }

  bookView.hidden = false;
  bookView.style.visibility = "hidden";
  readingView.hidden = true;

  _bookViewV3Setup(_bookViewSource);

  if (bookViewToggle) bookViewToggle.textContent = "▶ Audio view";
  bookView.style.visibility = "visible";
  try {
    window.scrollTo({ top: 0, behavior: "instant" });
  } catch {
    window.scrollTo(0, 0);
  }
}

// v208 (M6.2): click the spread indicator to enter page-jump mode.
// Indicator's textContent is replaced with a number input; Enter
// commits, Esc / blur cancels. Guards against _bookViewUpdateNav
// overwriting the input mid-edit via _bookViewIndicatorEditing.
// v209 (M6.4): touch swipe for spread navigation. Pointer Events
// captures horizontal swipes on the spread element. Swipes that
// start on an interactive child (sentence span, image, button)
// don't trigger — that preserves click-to-seek and text selection.
// Distance threshold 80px keeps accidental drags from paging.
// Time threshold 800ms keeps slow scroll-and-rest from triggering.
// =====================================================================
// v225v3.7 (#741): Book view nav auto-hide (Kindle / Apple Books pattern)
// =====================================================================
//
// After 2.5s of no pointer activity in the book view, the floating
// nav pill fades out. Any pointer movement or tap within the book
// view brings it back + restarts the 2.5s countdown. Page-flip via
// button click or _bookViewNavigateManual also triggers a show.
// Layout doesn't change — only opacity + a small translateY for the
// "ducks out of the way" feel. Find bar / page-jump input cancel the
// hide timer while active so the user isn't fighting the timer
// during interaction.
const _BOOK_NAV_HIDE_DELAY_MS = 2500;
let _bookViewNavHideTimer = null;
let _bookViewNavEl = null;

function _bookViewGetNav() {
  if (_bookViewNavEl && document.contains(_bookViewNavEl)) {
    return _bookViewNavEl;
  }
  _bookViewNavEl = document.getElementById("book-view-nav");
  return _bookViewNavEl;
}

function _bookViewShowNav() {
  const nav = _bookViewGetNav();
  if (!nav) {
    try { _dlog("book-nav", "show — no nav el", {}); } catch {}
    return;
  }
  nav.classList.remove("auto-hidden");
  if (_bookViewNavHideTimer) {
    clearTimeout(_bookViewNavHideTimer);
    _bookViewNavHideTimer = null;
  }
  // v225v3.9: when the pill is mounted in the header slot, it lives
  // in the main app chrome — never auto-hide it there. Auto-hide
  // only applies when the nav is parented inside #book-view (phone
  // takeover path).
  if (nav.closest && nav.closest(".book-view-nav-slot")) return;
  _bookViewNavHideTimer = setTimeout(() => {
    _bookViewNavHideTimer = null;
    // Don't hide if the user is currently in the page-jump input or
    // the find bar — those expect persistent nav visibility.
    if (typeof _bookViewIndicatorEditing !== "undefined"
        && _bookViewIndicatorEditing) {
      try { _dlog("book-nav", "hide-skip — indicator editing", {}); } catch {}
      return;
    }
    if (typeof bookViewFind !== "undefined" && bookViewFind
        && !bookViewFind.hidden) {
      try { _dlog("book-nav", "hide-skip — find open", {}); } catch {}
      return;
    }
    nav.classList.add("auto-hidden");
    try { _dlog("book-nav", "hidden", {}); } catch {}
  }, _BOOK_NAV_HIDE_DELAY_MS);
}

// v225v3.9 (#741): pill-in-header relocation. On desktop we move the
// nav element out of #book-view and into the hero header slot so the
// pill renders inline with the brand / icons row. On phone (where
// the book view is a fullscreen takeover that covers the header)
// the nav stays parented to #book-view at the top.
function _bookViewMountNavInHeader() {
  const nav = _bookViewGetNav();
  const slot = document.getElementById("book-view-nav-slot");
  if (!nav || !slot) return;
  if (nav.parentElement === slot) {
    slot.hidden = false;
    return;
  }
  slot.appendChild(nav);
  slot.hidden = false;
  try { _dlog("book-nav", "mounted in header", {}); } catch {}
}
function _bookViewMountNavInBookView() {
  const nav = _bookViewGetNav();
  const slot = document.getElementById("book-view-nav-slot");
  const bv = (typeof bookView !== "undefined" && bookView)
    ? bookView
    : document.getElementById("book-view");
  if (slot) slot.hidden = true;
  if (!nav || !bv) return;
  if (nav.parentElement === bv) return;
  bv.appendChild(nav);
  try { _dlog("book-nav", "mounted in book-view", {}); } catch {}
}

function _bookViewWireNavAutoHide() {
  const bv = (typeof bookView !== "undefined" && bookView)
    ? bookView
    : document.getElementById("book-view");
  const nav = _bookViewGetNav();
  try { _dlog("book-nav", "wire", { hasBookView: !!bv, hasNav: !!nav }); } catch {}
  if (!bv) return;
  // Show on any pointer movement / interaction. passive: true so we
  // don't compete with the swipe handler.
  bv.addEventListener("pointermove", _bookViewShowNav, { passive: true });
  bv.addEventListener("pointerdown", _bookViewShowNav, { passive: true });
  // Keep the nav alive while the user is hovering / interacting with
  // it directly — wouldn't want it to hide mid-click.
  if (nav) {
    nav.addEventListener("pointerenter", () => {
      if (_bookViewNavHideTimer) {
        clearTimeout(_bookViewNavHideTimer);
        _bookViewNavHideTimer = null;
      }
      nav.classList.remove("auto-hidden");
    });
    nav.addEventListener("pointerleave", _bookViewShowNav);
    // Keyboard focus on any nav button also keeps visible (Tab nav).
    nav.addEventListener("focusin", () => {
      if (_bookViewNavHideTimer) {
        clearTimeout(_bookViewNavHideTimer);
        _bookViewNavHideTimer = null;
      }
      nav.classList.remove("auto-hidden");
    });
    nav.addEventListener("focusout", _bookViewShowNav);
  }
}

function _bookViewWireSwipe() {
  if (!bookViewSpread) return;
  let startX = 0;
  let startY = 0;
  let startTime = 0;
  let tracking = false;
  bookViewSpread.addEventListener("pointerdown", (e) => {
    // Don't swallow swipes that begin on interactive content. Sentence
    // spans handle click-to-seek; respecting their target lets the
    // existing click logic fire on tap.
    const target = e.target;
    if (
      target.closest("button") ||
      target.closest(".sentence") ||
      target.closest("img")
    ) {
      tracking = false;
      return;
    }
    if (e.pointerType !== "touch") return;  // mouse drag = text selection
    startX = e.clientX;
    startY = e.clientY;
    startTime = Date.now();
    tracking = true;
  });
  bookViewSpread.addEventListener("pointerup", (e) => {
    if (!tracking) return;
    tracking = false;
    const dx = e.clientX - startX;
    const dy = e.clientY - startY;
    const elapsed = Date.now() - startTime;
    if (elapsed > 800) return;  // too slow
    if (Math.abs(dx) < 80) return;  // too short
    if (Math.abs(dy) > Math.abs(dx)) return;  // vertical, not horizontal
    if (dx < 0) {
      // Swipe left → next spread (page advancing direction).
      _bookViewNavigateManual(_bookViewCurrentSpread + 1);
    } else {
      _bookViewNavigateManual(_bookViewCurrentSpread - 1);
    }
  });
  bookViewSpread.addEventListener("pointercancel", () => {
    tracking = false;
  });
}
_bookViewWireSwipe();

function _bookViewBeginPageJump() {
  if (!bookViewIndicator || _bookViewIndicatorEditing) return;
  if (_bookViewSpreadsCount <= 1) return;  // nothing to jump to
  _bookViewIndicatorEditing = true;
  const currentSpread = _bookViewCurrentSpread + 1;
  bookViewIndicator.innerHTML = "";
  const input = document.createElement("input");
  input.type = "number";
  input.min = "1";
  input.max = String(_bookViewSpreadsCount);
  input.value = String(currentSpread);
  input.className = "book-view-indicator-input";
  input.setAttribute("aria-label", "Spread number");
  bookViewIndicator.appendChild(input);
  input.focus();
  input.select();
  const finish = (commit) => {
    if (!_bookViewIndicatorEditing) return;
    _bookViewIndicatorEditing = false;
    if (commit) {
      const n = parseInt(input.value, 10);
      if (!Number.isNaN(n)) {
        const target = Math.max(1, Math.min(_bookViewSpreadsCount, n)) - 1;
        _bookViewNavigateManual(target);
      }
    }
    _bookViewUpdateNav();  // restore the textContent
  };
  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      finish(true);
    } else if (e.key === "Escape") {
      e.preventDefault();
      finish(false);
    }
  });
  input.addEventListener("blur", () => finish(false));
}

// v208 (M6.3): find within book view. Reads from
// _bookViewSource.sentences; case-insensitive substring match;
// matches stored as sentence indices. Cursor cycles through them
// via prev/next. Jumping to a match scrolls to the spread containing
// that sentence via _bookViewNavigateManual.
function _bookViewOpenFind() {
  if (!bookViewFind || !bookViewFindInput) return;
  if (!_bookViewSource || !_bookViewSource.sentences.length) return;
  bookViewFind.hidden = false;
  bookViewFindInput.focus();
  bookViewFindInput.select();
}
function _bookViewCloseFind() {
  if (!bookViewFind) return;
  bookViewFind.hidden = true;
  if (bookViewFindInput) bookViewFindInput.value = "";
  _bookViewFindMatches = [];
  _bookViewFindCursor = 0;
  _bookViewUpdateFindCount();
}
function _bookViewUpdateFindCount() {
  if (!bookViewFindCount) return;
  const total = _bookViewFindMatches.length;
  const cur = total ? _bookViewFindCursor + 1 : 0;
  bookViewFindCount.textContent = `${cur} / ${total}`;
}
function _bookViewRunFind(query) {
  _bookViewFindMatches = [];
  _bookViewFindCursor = 0;
  if (!query || !_bookViewSource) {
    _bookViewUpdateFindCount();
    return;
  }
  const q = query.toLowerCase();
  const sentences = _bookViewSource.sentences;
  for (let i = 0; i < sentences.length; i++) {
    if (sentences[i].toLowerCase().includes(q)) {
      _bookViewFindMatches.push(i);
    }
  }
  _bookViewUpdateFindCount();
  // Jump to the first match if any.
  if (_bookViewFindMatches.length) {
    _bookViewJumpToFindMatch();
  }
}
function _bookViewJumpToFindMatch() {
  const sIdx = _bookViewFindMatches[_bookViewFindCursor];
  if (sIdx === undefined) return;
  const ppr = _bookViewPagesPerSpread();
  const targetSpread = _bookViewSpreadOfSentence(sIdx, ppr);
  _bookViewNavigateManual(targetSpread);
}
function _bookViewCycleFind(delta) {
  if (!_bookViewFindMatches.length) return;
  _bookViewFindCursor =
    (_bookViewFindCursor + delta + _bookViewFindMatches.length) %
    _bookViewFindMatches.length;
  _bookViewUpdateFindCount();
  _bookViewJumpToFindMatch();
}

// Title-hash → CSS gradient. Same hash → same colors → same swatch
// as the library card, so a chapter's cover page tone matches its
// row in the library list. Kept inline (rather than reused from the
// library helper) so this module stays self-contained.
function _coverFallbackGradient(seed) {
  let hash = 0;
  for (let i = 0; i < seed.length; i++) {
    hash = (hash * 31 + seed.charCodeAt(i)) >>> 0;
  }
  const h1 = hash % 360;
  const h2 = (h1 + 35) % 360;
  return `linear-gradient(135deg, hsl(${h1}, 60%, 28%) 0%, hsl(${h2}, 55%, 18%) 100%)`;
}

// Apply the karaoke state to whichever book span matches the given
// sentence index. Cheaper than the reading-view's full forEach since
// only the active sentence changes per frame.
function _bookViewApplyActive(idx) {
  // Clear stale state on the book spans we touched last frame.
  for (const span of _bookSentenceSpans) {
    if (!span) continue;
    span.classList.remove("active");
  }
  // Mark "played" up to the current cursor + "active" on the cursor.
  for (let i = 0; i < _bookSentenceSpans.length; i++) {
    const span = _bookSentenceSpans[i];
    if (!span) continue;
    if (i < idx) span.classList.add("played");
    else span.classList.remove("played");
  }
  const activeSpan = _bookSentenceSpans[idx];
  if (activeSpan) activeSpan.classList.add("active");
}

// Public: enter book view. Reads the stashed _bookViewSource (set by
// enterReadingView). Mid-clip pivots — user can flip back to reading
// view at any time and pick up exactly where they were.
async function enterBookView() {
  if (!_bookViewSource || !_bookViewSource.sentences.length) {
    setStatus("Generate or load a clip first.", true);
    return;
  }
  // v225v3.7 (#741): wire auto-hide listeners ONCE on first open
  // (idempotent — re-binding the same handler on same element with
  // addEventListener is a no-op for duplicate identical references,
  // but we guard with a flag to avoid stacking timers on repeated
  // re-entries). Then trigger an initial show so the user sees the
  // controls when the view first appears, fading after 2.5s.
  if (!window.__bookViewNavAutoHideWired) {
    window.__bookViewNavAutoHideWired = true;
    if (typeof _bookViewWireNavAutoHide === "function") {
      try { _bookViewWireNavAutoHide(); } catch {}
    }
  }
  // v225v3.9 (#741): on desktop relocate the nav pill into the hero
  // header slot. On phone keep it inside the book view (fullscreen
  // takeover covers the header). Breakpoint mirrors the @media
  // (max-width: 720px) phone gate elsewhere.
  if (window.innerWidth > 720) {
    if (typeof _bookViewMountNavInHeader === "function") {
      try { _bookViewMountNavInHeader(); } catch {}
    }
  } else {
    if (typeof _bookViewMountNavInBookView === "function") {
      try { _bookViewMountNavInBookView(); } catch {}
    }
  }
  if (typeof _bookViewShowNav === "function") {
    try { _bookViewShowNav(); } catch {}
  }
  // v225v3.0 (#734): Book View V3 branch — word-processor pagination.
  // Takes priority over V2 and V1.
  if (_bookViewV3Enabled()) {
    return _enterBookViewV3();
  }
  // v225h0 (#728): Book View V2 branch — multi-column rewrite.
  // Feature-flagged so V1 remains the default until parity reached.
  if (_bookViewV2Enabled()) {
    return _enterBookViewV2();
  }
  // Populate title + cover from the currently-loaded clip if we have
  // its id (otherwise leave the fallback gradient + a generic title).
  if (_currentClipId) {
    getClip(_currentClipId).then((clip) => {
      if (!clip) return;
      _bookViewSource.title = clip.title || "Untitled chapter";
      _bookViewSource.cover = clip.cover || null;
      // v210 (M6.1): stash bookmarks on the source so the page
      // renderer can mark bookmarked pages with a ribbon. Bookmarks
      // are time-based (timeSec); the ribbon helper resolves time →
      // sentence_index → page_index via sentenceOffsetsSec +
      // _bookSentenceToPage.
      _bookViewSource.bookmarks = clip.bookmarks || [];
      // v211 (M7.1): stash highlights too. The renderer wraps any
      // highlighted char range in <span class="text-highlight">.
      _bookViewSource.highlights = clip.highlights || [];
      // Re-render so the cover page updates if the user opens the book
      // view before getClip resolves.
      _bookViewRenderSpread(_bookViewCurrentSpread);
    }).catch(() => {});
  } else {
    _bookViewSource.title = "Untitled chapter";
  }
  // v187: opening the book view should always start unpinned —
  // user just toggled in; they want auto-flip until they decide to
  // scrub. Without this, a pinned state from a previous session
  // (after exit→re-enter) would persist and confuse.
  _bookViewUserPaged = false;

  // v206 (M4.1): detect chapter boundaries once per book-view
  // session. Cached on _bookViewSource so theme / font-size changes
  // don't re-run the detector. _bookViewRepaginate reads from the
  // same cache (paginator + renderer both call _bookViewIsChapterStart
  // / _bookViewChapterAt which read _bookViewSource.chapters).
  if (!_bookViewSource.chapters) {
    _bookViewSource.chapters = _bookViewDetectChapters(_bookViewSource.sentences);
  }

  // v200 (M3.2): preload image dimensions + bucket by sentence_index
  // before paginating. Without natural dimensions, an <img> in the
  // measurement probe contributes 0 to scrollHeight until it loads
  // asynchronously, racing the paginator. Cache the bucket + dims on
  // _bookViewSource so _bookViewRepaginate can reuse them when the
  // user changes theme / text-size without re-downloading.
  if (!_bookViewSource.imgByIdx) {
    _bookViewSource.imgByIdx = _bookViewBucketImages(
      _bookViewSource.images,
      _bookViewSource.sentences.length
    );
  }
  if (!_bookViewSource.imgDims) {
    // Show the spread skeleton during preload so the user sees that
    // something's happening (most clips have 0 images and this is
    // instant; URL-fetched chapters can have a dozen).
    bookView.style.visibility = "hidden";
    bookView.hidden = false;
    _bookViewSource.imgDims = await _bookViewPreloadImages(
      _bookViewSource.images || []
    );
  }

  // Pre-measure: temporarily reveal the spread so the page-shaped
  // probe inherits the real CSS metrics. Hidden visibility keeps the
  // user from seeing a flash of un-paginated content.
  bookView.style.visibility = "hidden";
  bookView.hidden = false;
  readingView.hidden = true;
  const spreadRect = bookViewSpread.getBoundingClientRect();
  const ppr = _bookViewPagesPerSpread();
  const pageWidth = ppr === 2 ? spreadRect.width / 2 : spreadRect.width;
  const pageHeight = spreadRect.height;
  _bookViewPages = _bookViewPaginate(
    _bookViewSource.sentences,
    pageWidth,
    pageHeight,
    _bookViewSource.imgByIdx,
    _bookViewSource.imgDims
  );
  _bookSentenceToPage = [];
  for (let p = 0; p < _bookViewPages.length; p++) {
    for (const sIdx of _bookViewPages[p]) {
      _bookSentenceToPage[sIdx] = p;
    }
  }
  // Default to the spread containing the current active sentence so
  // a user mid-listen who toggles into book view lands on the right
  // page. Falls back to spread 0 (cover + first page) otherwise.
  const startSpread = activeSentenceIdx >= 0
    ? _bookViewSpreadOfSentence(activeSentenceIdx, ppr)
    : 0;
  _bookViewRenderSpread(startSpread);
  // v206 (M4.4): the Contents button only shows once we've
  // confirmed chapters exist for THIS clip.
  _bookViewUpdateTocButton();
  bookView.style.visibility = "visible";
  if (bookViewToggle) bookViewToggle.textContent = "▶ Audio view";
  // v225g10 (#698): scroll the PAGE to the top so the Narrative
  // header (title, ⚙ Settings, ⌘K, etc.) is visible — not the book
  // view's top edge. The previous behavior left the user at whatever
  // scroll position they were at before opening as ebook, which on
  // a Bicycle-Ghost-sized spread meant the header was off-screen
  // above and the spread filled the viewport, with no way to reach
  // navigation. window.scrollTo(0, 0) puts the page top in view;
  // the import preview + book view render below it; the user can
  // scroll down to engage with the book view OR see the header at
  // any time. Phone gets the fixed-position takeover from v225g3
  // so this call is harmless there (fixed elements ignore page
  // scroll). One RAF gives the visibility:visible above a paint
  // cycle to settle before the scroll fires.
  requestAnimationFrame(() => {
    try {
      window.scrollTo({ top: 0, behavior: "instant" });
    } catch {
      try { window.scrollTo(0, 0); } catch {}
    }
    // v225g13 (#701): after the page-scroll, do a second paint cycle
    // and force a repagination. User reported the bottom of each
    // book-view page was being clipped — last 1-2 lines of text cut
    // off mid-paragraph. Cause: the initial pagination measured the
    // spread BEFORE v225g9's max-height CSS clamp took effect (CSS
    // hadn't paint-settled when getBoundingClientRect ran inside
    // enterBookView's synchronous block). The paginator laid out
    // pages assuming the un-clamped tall geometry, then CSS shrunk
    // the spread to fit viewport-minus-nav, leaving the bottom of
    // each page overflowed and clipped. A re-measure + repaginate
    // after the CSS settles fixes the page-fit. The repaginator
    // preserves the user's spread position (it anchors on the
    // current sentence), so this is invisible to the user — pages
    // just suddenly fit correctly.
    requestAnimationFrame(() => {
      try { _bookViewRepaginate(); } catch (e) {
        console.warn("[bookview] post-enter repaginate failed:", e);
      }
    });
  });
}

// v202 (M3.3): build a single page element for the given slot
// (0 = cover, 1+ = text pages). Mirrors the per-page construction
// inside _bookViewRenderSpread but as a standalone function so the
// print path can build all pages at once without depending on the
// spread loop. Duplication is deliberate — the live renderer stays
// untouched.
function _bookViewBuildPageElement(slot) {
  const pageEl = document.createElement("div");
  pageEl.className = "book-page";

  if (slot === 0) {
    // Cover — same as the renderer's cover branch.
    pageEl.classList.add("book-page-cover");
    const src = _bookViewSource;
    // v225g12 (#700): same multi-format cover resolver as the live
    // renderer. Print rebuilds every page flat so this slot fires for
    // every book; without the resolver, print would show the seed-
    // letter gradient instead of the real cover for ebook clips.
    const coverImgSrc = _coverImgSrc(src && src.cover);
    if (coverImgSrc) {
      const img = document.createElement("img");
      img.className = "book-page-cover-art";
      img.alt = src.title || "Cover";
      img.src = coverImgSrc.url;
      if (coverImgSrc.revoke) {
        img.addEventListener("load", () => URL.revokeObjectURL(img.src), { once: true });
      }
      pageEl.appendChild(img);
    } else {
      const fb = document.createElement("div");
      fb.className = "book-page-cover-fallback";
      const seed = (src && src.title) || "Untitled";
      fb.style.background = _coverFallbackGradient(seed);
      fb.textContent = seed.trim().slice(0, 1).toUpperCase() || "•";
      pageEl.appendChild(fb);
    }
    if (src && src.title) {
      const t = document.createElement("div");
      t.className = "book-page-cover-title";
      t.textContent = src.title;
      pageEl.appendChild(t);
    }
    return pageEl;
  }

  // Text page — mirrors the renderer's text-page branch.
  const textPageIdx = slot - 1;
  const sentenceIdxs = _bookViewPages[textPageIdx] || [];

  const headerTitle = (_bookViewSource && _bookViewSource.title) || "";
  if (headerTitle) {
    const header = document.createElement("div");
    header.className = "book-page-header";
    header.textContent = headerTitle;
    pageEl.appendChild(header);
  }

  const body = document.createElement("div");
  body.className = "book-page-body";
  if (textPageIdx === 0) {
    body.dataset.dropCap = "true";
  }

  const imgByIdx = (_bookViewSource && _bookViewSource.imgByIdx) || null;
  for (const sIdx of sentenceIdxs) {
    if (imgByIdx && imgByIdx.has(sIdx)) {
      for (const img of imgByIdx.get(sIdx)) {
        const el = document.createElement("img");
        el.className = "book-inline-image";
        el.src = img.src;
        el.alt = img.alt || "";
        el.loading = "lazy";
        el.decoding = "async";
        el.addEventListener("error", () => el.remove(), { once: true });
        body.appendChild(el);
      }
    }
    const span = document.createElement("span");
    span.className = "sentence";
    span.dataset.index = String(sIdx);
    const wc = _countWords(_bookViewSource.sentences[sIdx]);
    if (wc >= LONG_SENTENCE_WORD_THRESHOLD) {
      span.dataset.longSentence = "true";
      span.dataset.wordCount = String(wc);
      span.title = `${wc} words`;
    }
    span.textContent = _bookViewSource.sentences[sIdx] + " ";
    span.addEventListener("click", () => {
      _bookViewUserPaged = false;
      seekToSentence(sIdx);
      if (playerEl.paused) playerEl.play().catch(() => {});
    });
    body.appendChild(span);
    _bookSentenceSpans[sIdx] = span;
  }
  const totalTextPages = _bookViewPages.length;
  if (textPageIdx === totalTextPages - 1 && imgByIdx) {
    const trailing = imgByIdx.get(_bookViewSource.sentences.length) || [];
    for (const img of trailing) {
      const el = document.createElement("img");
      el.className = "book-inline-image";
      el.src = img.src;
      el.alt = img.alt || "";
      el.loading = "lazy";
      el.decoding = "async";
      el.addEventListener("error", () => el.remove(), { once: true });
      body.appendChild(el);
    }
  }
  pageEl.appendChild(body);

  const footer = document.createElement("div");
  footer.className = "book-page-footer";
  footer.textContent = String(textPageIdx + 1);
  pageEl.appendChild(footer);

  return pageEl;
}

// v202 (M3.3): print the entire book. Rebuilds the spread DOM with
// every page laid out flat, sets body[data-book-printing] so the
// @media print rules + the screen rule that moves the book offscreen
// can take over, fires window.print(). Restores the single-spread
// rendering on the afterprint event so the user lands back where
// they were when they came back from the print dialog.
function _bookViewPrintBook() {
  if (!_bookViewSource || !_bookViewSource.sentences.length) {
    setStatus("Load a clip first.", true);
    return;
  }
  // v225v3.10 (Phase 2): V3 print path. V3 already has all pages in
  // the .book-view-page-row; we just disable the translateX so they
  // stack visually for the print preview. CSS (body[data-book-
  // printing] .book-view-page-row) handles the actual layout
  // override. On afterprint we restore by snapping back to the
  // saved spread index — no DOM rebuild needed.
  if (typeof _bookViewV3Enabled === "function" && _bookViewV3Enabled()
      && _bookViewV3State && _bookViewV3State.pageCount > 0) {
    const savedSpreadV3 = _bookViewV3State.spreadIdx || 0;
    document.body.dataset.bookPrinting = "true";
    const cleanupV3 = () => {
      window.removeEventListener("afterprint", cleanupV3);
      delete document.body.dataset.bookPrinting;
      if (typeof _bookViewV3GotoSpread === "function") {
        _bookViewV3GotoSpread(savedSpreadV3);
      }
    };
    window.addEventListener("afterprint", cleanupV3);
    requestAnimationFrame(() => {
      window.print();
    });
    return;
  }
  if (!_bookViewPages.length) {
    setStatus("Open the book view first to paginate.", true);
    return;
  }
  const savedSpread = _bookViewCurrentSpread;

  // Switch CSS into "print prep" mode BEFORE rebuilding the DOM —
  // otherwise the user would briefly see the all-pages layout
  // crammed into the 2-column spread grid. The screen-mode CSS
  // rule on body[data-book-printing] positions the book view
  // off-screen so the rebuild is invisible.
  document.body.dataset.bookPrinting = "true";

  // Build all pages flat into bookViewSpread.
  bookViewSpread.innerHTML = "";
  _bookSentenceSpans = [];
  const totalSlots = 1 + _bookViewPages.length;  // cover + text pages
  for (let slot = 0; slot < totalSlots; slot++) {
    const pageEl = _bookViewBuildPageElement(slot);
    bookViewSpread.appendChild(pageEl);
  }

  // Restore on afterprint. Browsers fire this whether the user
  // confirms printing or cancels the dialog.
  const cleanup = () => {
    window.removeEventListener("afterprint", cleanup);
    delete document.body.dataset.bookPrinting;
    // Re-render the spread the user was on. This re-populates
    // _bookSentenceSpans correctly so click-to-seek + karaoke
    // resume working on the right nodes.
    _bookViewRenderSpread(savedSpread);
  };
  window.addEventListener("afterprint", cleanup);

  // requestAnimationFrame so the DOM rebuild commits before the
  // print dialog opens (some browsers snapshot at print() call time).
  requestAnimationFrame(() => {
    window.print();
  });
}

// v206 (M4.4): open the table-of-contents dialog. Populates the list
// from _bookViewSource.chapters (computed in enterBookView) with
// per-chapter page numbers looked up via _bookSentenceToPage. Each
// row jumps via _bookViewNavigateManual so the pinned-scrub flag
// behaves like a user-initiated paging action.
function _bookViewOpenToc() {
  if (!bookViewTocDialog || !bookViewTocList) return;
  if (!_bookViewSource || !_bookViewSource.chapters) return;
  const chapters = _bookViewSource.chapters;
  bookViewTocList.innerHTML = "";
  if (!chapters.length) {
    const li = document.createElement("li");
    li.className = "book-view-toc-empty";
    li.textContent = "No chapters detected in this clip.";
    bookViewTocList.appendChild(li);
  } else {
    const ppr = _bookViewPagesPerSpread();
    for (const ch of chapters) {
      const li = document.createElement("li");
      li.className = "book-view-toc-row";
      const titleEl = document.createElement("span");
      titleEl.className = "book-view-toc-title";
      titleEl.textContent = ch.title;
      const pageEl = document.createElement("span");
      pageEl.className = "book-view-toc-page";
      const pageIdx = _bookSentenceToPage[ch.sentence_index];
      pageEl.textContent = (pageIdx !== undefined) ? String(pageIdx + 1) : "—";
      li.appendChild(titleEl);
      li.appendChild(pageEl);
      li.addEventListener("click", () => {
        const targetSpread = _bookViewSpreadOfSentence(ch.sentence_index, ppr);
        _bookViewNavigateManual(targetSpread);
        bookViewTocDialog.close();
      });
      bookViewTocList.appendChild(li);
    }
  }
  try { bookViewTocDialog.showModal(); }
  catch { bookViewTocDialog.show && bookViewTocDialog.show(); }
}

// v206 (M4.4): show/hide the Contents button based on whether the
// current clip has detected chapters. Called from enterBookView after
// chapter detection runs and from exitBookView to reset.
function _bookViewUpdateTocButton() {
  if (!bookViewTocBtn) return;
  const has =
    !!(_bookViewSource && _bookViewSource.chapters && _bookViewSource.chapters.length > 0);
  bookViewTocBtn.hidden = !has;
}

function _bookViewSpreadOfSentence(sIdx, ppr) {
  const pageIdx = _bookSentenceToPage[sIdx];
  if (pageIdx === undefined) return 0;
  // Slot 0 is cover; slot N>=1 is text page N-1. Spread = floor(slot/ppr).
  const slot = pageIdx + 1;
  return Math.floor(slot / ppr);
}

// v197 (M2): re-paginate the current source and re-render. Called
// when the user changes Book View text size in Settings, so the
// page break points and the current spread both shift to match
// the new font. Anchors the post-repagination spread on whichever
// sentence was at the top of the visible spread before the change —
// otherwise jumping from S → L size could land the user dozens of
// pages off because the same spread index now points at different
// content.
function _bookViewRepaginate() {
  if (!bookView || bookView.hidden) return;
  if (!_bookViewSource || !_bookViewSource.sentences.length) return;
  // Remember a sentence from the visible spread so we can return to
  // it. Use the active (audio-playing) sentence if it's on this
  // spread; otherwise the first sentence of the current spread.
  const ppr = _bookViewPagesPerSpread();
  let anchor = -1;
  if (
    activeSentenceIdx >= 0 &&
    _bookViewSpreadOfSentence(activeSentenceIdx, ppr) === _bookViewCurrentSpread
  ) {
    anchor = activeSentenceIdx;
  } else {
    const firstSlot = _bookViewCurrentSpread * ppr;
    const firstTextPage = firstSlot === 0 ? 0 : firstSlot - 1;
    const firstPageSentences = _bookViewPages[firstTextPage] || [];
    if (firstPageSentences.length) anchor = firstPageSentences[0];
  }
  // Re-measure and re-paginate.
  const spreadRect = bookViewSpread.getBoundingClientRect();
  const pageWidth = ppr === 2 ? spreadRect.width / 2 : spreadRect.width;
  const pageHeight = spreadRect.height;
  _bookViewPages = _bookViewPaginate(
    _bookViewSource.sentences,
    pageWidth,
    pageHeight,
    // v200 (M3.2): reuse the cached image bucket + dims so theme /
    // font-size changes don't re-trigger image downloads.
    _bookViewSource && _bookViewSource.imgByIdx,
    _bookViewSource && _bookViewSource.imgDims
  );
  _bookSentenceToPage = [];
  for (let p = 0; p < _bookViewPages.length; p++) {
    for (const sIdx of _bookViewPages[p]) {
      _bookSentenceToPage[sIdx] = p;
    }
  }
  const targetSpread = anchor >= 0
    ? _bookViewSpreadOfSentence(anchor, ppr)
    : _bookViewCurrentSpread;
  _bookViewRenderSpread(targetSpread);
}

// v197 (M2): user-selectable book font size. Persists to localStorage
// and applies to .book-view via a CSS custom property. Re-paginates
// the current book view on the fly when the user changes the size.
const BOOK_FONT_SIZE_KEY = "bookFontSize";
const BOOK_FONT_SIZES = {
  small: "14px",
  medium: "16px",
  large: "18px",
  xlarge: "20px",
};
function _loadBookFontSize() {
  const v = localStorage.getItem(BOOK_FONT_SIZE_KEY);
  return BOOK_FONT_SIZES[v] ? v : "medium";
}
function _applyBookFontSize(size) {
  const px = BOOK_FONT_SIZES[size] || BOOK_FONT_SIZES.medium;
  if (bookView) bookView.style.setProperty("--book-font-size", px);
}
// Apply on initial load so the CSS var is set before the user
// opens book view (pagination uses the var, so it must be set first).
_applyBookFontSize(_loadBookFontSize());

// v199 (M3.1): book-view theme variant. Independent of the app-wide
// Dark/Light/Auto theme — this picks the typographic personality of
// the book pages (paperback / magazine / manuscript). CSS lives on
// data-book-theme attribute on .book-view, which the paginator probe
// also receives (set explicitly in _bookViewPaginate). On change we
// re-paginate because font-family + line-height shifts move the
// per-page break points.
const BOOK_THEME_KEY = "bookTheme";
const BOOK_THEMES = new Set(["paperback", "magazine", "manuscript"]);
function _loadBookTheme() {
  const v = localStorage.getItem(BOOK_THEME_KEY);
  return BOOK_THEMES.has(v) ? v : "paperback";
}
function _applyBookTheme(theme) {
  const t = BOOK_THEMES.has(theme) ? theme : "paperback";
  if (bookView) bookView.dataset.bookTheme = t;
}
_applyBookTheme(_loadBookTheme());

// Public: leave book view. Either back to reading view (default) or
// onward to the textarea (when called from exitReadingView itself).
function exitBookView(opts = {}) {
  bookView.hidden = true;
  bookView.style.visibility = "";
  _bookSentenceSpans = [];
  if (bookViewSpread) bookViewSpread.innerHTML = "";
  if (bookViewToggle) bookViewToggle.textContent = "📖 Book view";
  // v225v3.7 (#741): clean up auto-hide state so next open starts
  // fresh with nav visible (avoids stale hide-timer firing on next
  // enter, and avoids the nav being already in auto-hidden state
  // when the user reopens).
  if (typeof _bookViewNavHideTimer !== "undefined" && _bookViewNavHideTimer) {
    clearTimeout(_bookViewNavHideTimer);
    _bookViewNavHideTimer = null;
  }
  const _navOnExit = (typeof _bookViewGetNav === "function") ? _bookViewGetNav() : null;
  if (_navOnExit) _navOnExit.classList.remove("auto-hidden");
  // v225v3.9 (#741): if the nav was relocated to the header slot,
  // move it back inside #book-view + hide the slot. Keeps the DOM
  // consistent for the next enter (avoids stale parenting if the
  // viewport changed between open and close).
  if (typeof _bookViewMountNavInBookView === "function") {
    try { _bookViewMountNavInBookView(); } catch {}
  }
  // v206 (M4.4): hide Contents until the next book view open.
  if (bookViewTocBtn) bookViewTocBtn.hidden = true;
  // v208 (M6.3): close the find bar so re-entering book view starts fresh.
  if (bookViewFind && !bookViewFind.hidden) _bookViewCloseFind();
  // v225v3.4 (#738): restore-on-close path. If we have a snapshot of
  // the pre-open import-preview state, restore the user there instead
  // of dropping them in the reading view of the just-previewed clip.
  // This makes "Read as ebook" a non-destructive preview from import.
  if (_ebookPreviewSnapshot && !opts.skipReadingView) {
    const s = _ebookPreviewSnapshot;
    _ebookPreviewSnapshot = null;
    window._ebookPreviewSnapshot = null;
    try {
      // Restore pending image / chapter state so the import preview
      // panel can re-render with its thumbnails.
      if (s.pendingCover) _pendingDetectedCover = s.pendingCover;
      if (s.pendingImages) _pendingImages = s.pendingImages;
      if (s.pendingChapterImages) _pendingChapterImages = s.pendingChapterImages;
      if (s.pendingChapterTitle !== undefined) _pendingChapterTitle = s.pendingChapterTitle;
      if (s.pendingGitRef !== undefined) _pendingGitRef = s.pendingGitRef;
      if (s.pendingScrivenerRef !== undefined) _pendingScrivenerRef = s.pendingScrivenerRef;
      // Restore textarea text (usually unchanged but covers edge cases
      // where loadClip muted it).
      if (textEl && s.textareaValue !== undefined) {
        textEl.value = s.textareaValue;
      }
      // Clear "current clip" — we were on import preview, no clip
      // loaded then, none loaded now.
      _currentClipId = null;
      if (typeof _setCurrentClipKind === "function") {
        _setCurrentClipKind(null);
      }
      // Hide the reading view — it would otherwise show the previewed
      // clip's sentences, which is exactly what we're trying NOT to do.
      if (readingView) readingView.hidden = true;
      // v225v3.5 (#739): UN-hide the textarea. loadClip toggled
      // textEl.hidden = true when it switched the UI to "loaded clip
      // playback" mode; restoring import-preview state requires the
      // textarea visible so the user can edit / paste / continue.
      // Also flip the edit/save buttons + book view toggle back to
      // their "no clip loaded" defaults so the chrome is consistent.
      if (textEl) textEl.hidden = false;
      if (typeof editTextBtn !== "undefined" && editTextBtn) editTextBtn.hidden = true;
      if (typeof saveTextBtn !== "undefined" && saveTextBtn) saveTextBtn.hidden = true;
      if (typeof bookViewToggle !== "undefined" && bookViewToggle) bookViewToggle.hidden = true;
      // Re-paint the import preview chrome (thumbnails, head row).
      if (typeof _paintImportPreview === "function") _paintImportPreview();
      // Refresh the phone Generate / Ebook bar at the bottom.
      if (typeof window._syncPhoneGenerateBar === "function") {
        try { window._syncPhoneGenerateBar(); } catch {}
      }
      _dlog("ebook", "exit restored import-preview snapshot", {
        hadCover: !!s.pendingCover,
        imageCount: s.pendingImages ? s.pendingImages.length : 0,
      });
      return;
    } catch (e) {
      _dlog("ebook", "exit restore failed — falling through to normal exit", {
        error: String(e),
      });
      // Fall through to the normal path below.
    }
  }
  if (!opts.skipReadingView) {
    // v225v3.57 (#790): on phone, closing an ebook clip's book view
    // shouldn't drop the user in reading view. For ebook clips, the
    // reading view is the cover acknowledgments + stacked inline
    // images with no scroll path to the story body — the user
    // called this the "can't read" state. Phone has no two-column
    // alternate layout for reading view either, so it's just dead-
    // end content. Drop to the empty/library surface instead;
    // re-tapping the clip from ☰ Library will re-enter book view
    // (via the v3.56 auto-enter path in loadClip).
    //
    // Desktop keeps the old behavior — its reading view is a useful
    // two-column surface and desktop users opted into book view
    // explicitly via the toggle.
    const _phoneNow = window.matchMedia &&
      window.matchMedia("(max-width: 767px)").matches;
    if (_phoneNow && _currentClipKind === "ebook") {
      try {
        _currentClipId = null;
        if (typeof _setCurrentClipKind === "function") {
          _setCurrentClipKind(null);
        }
        readingView.hidden = true;
        // Restore the empty-state chrome: textarea visible, edit/save
        // buttons hidden, book view toggle hidden. Mirrors the
        // _ebookPreviewSnapshot restore path so the post-close state
        // is consistent with "no clip loaded."
        if (textEl) textEl.hidden = false;
        if (typeof editTextBtn !== "undefined" && editTextBtn) editTextBtn.hidden = true;
        if (typeof saveTextBtn !== "undefined" && saveTextBtn) saveTextBtn.hidden = true;
        if (typeof bookViewToggle !== "undefined" && bookViewToggle) bookViewToggle.hidden = true;
        if (typeof window._syncPhoneGenerateBar === "function") {
          try { window._syncPhoneGenerateBar(); } catch {}
        }
        if (typeof _dlog === "function") {
          _dlog("ebook:exit", "phone ebook close → empty state", {});
        }
        return;
      } catch (e) {
        console.warn("[ebook] phone-exit cleanup failed:", e);
        // Fall through to the normal readingView.hidden = false below
        // so the user isn't stuck on a black screen if anything threw.
      }
    }
    readingView.hidden = false;
  }
}

if (bookViewToggle) {
  bookViewToggle.addEventListener("click", () => {
    if (bookView.hidden) enterBookView();
    else exitBookView();
  });
}
// v225g3 (#692): explicit Close button inside book view. Needed on
// phone (where the takeover hides the hero toggle) and helpful on
// desktop too. Also nudges _syncPhoneGenerateBar so the Generate
// bar can flip back on for non-ebook clips after exit.
const _bookViewCloseBtn = document.getElementById("book-view-close");
if (_bookViewCloseBtn) {
  _bookViewCloseBtn.addEventListener("click", () => {
    if (typeof exitBookView === "function" && !bookView.hidden) {
      exitBookView();
      if (typeof window._syncPhoneGenerateBar === "function") {
        try { window._syncPhoneGenerateBar(); } catch {}
      }
    }
  });
}
// v202 (M3.3): print button. Direct call; the function handles
// the no-paginated-pages edge case via setStatus.
if (bookViewPrintBtn) {
  bookViewPrintBtn.addEventListener("click", () => _bookViewPrintBook());
}
// v206 (M4.4): table of contents button + dialog close.
if (bookViewTocBtn) {
  bookViewTocBtn.addEventListener("click", () => _bookViewOpenToc());
}
if (bookViewTocClose && bookViewTocDialog) {
  bookViewTocClose.addEventListener("click", () => bookViewTocDialog.close());
}
// v208 (M6.2): indicator click → page-jump.
if (bookViewIndicator) {
  bookViewIndicator.addEventListener("click", () => _bookViewBeginPageJump());
}
// v208 (M6.3): find input wiring + close/prev/next + Ctrl+F.
if (bookViewFindInput) {
  bookViewFindInput.addEventListener("input", () =>
    _bookViewRunFind(bookViewFindInput.value)
  );
  bookViewFindInput.addEventListener("keydown", (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      _bookViewCycleFind(e.shiftKey ? -1 : 1);
    } else if (e.key === "Escape") {
      e.preventDefault();
      _bookViewCloseFind();
    }
  });
}
if (bookViewFindPrev) {
  bookViewFindPrev.addEventListener("click", () => _bookViewCycleFind(-1));
}
if (bookViewFindNext) {
  bookViewFindNext.addEventListener("click", () => _bookViewCycleFind(1));
}
if (bookViewFindClose) {
  bookViewFindClose.addEventListener("click", () => _bookViewCloseFind());
}
// Ctrl+F / Cmd+F → open the find bar when book view is visible.
// Override the browser's native find since the book view's text is
// already on screen and our match-aware paginator can jump to the
// page containing the hit (browser find can't do that).
document.addEventListener("keydown", (e) => {
  if ((e.ctrlKey || e.metaKey) && e.key === "f" && bookView && !bookView.hidden) {
    e.preventDefault();
    _bookViewOpenFind();
  }
});
if (bookViewPrev) {
  bookViewPrev.addEventListener("click", () => {
    // v187: route through _bookViewNavigateManual so the pinned
    // state flips on and the auto-flip stops yanking the spread
    // back to the active sentence the next animation frame.
    _bookViewNavigateManual(_bookViewCurrentSpread - 1);
  });
}
if (bookViewNext) {
  bookViewNext.addEventListener("click", () => {
    _bookViewNavigateManual(_bookViewCurrentSpread + 1);
  });
}
// v187: "Return to current" — un-pins + flips to the spread holding
// the audio's currently-narrated sentence. Hidden by default; the
// nav-update path reveals it when the user has scrubbed away.
if (bookViewReturn) {
  bookViewReturn.addEventListener("click", () => {
    if (activeSentenceIdx < 0) return;
    const ppr = _bookViewPagesPerSpread();
    const target = _bookViewSpreadOfSentence(activeSentenceIdx, ppr);
    _bookViewUserPaged = false;
    _bookViewRenderSpread(target);
  });
}
// Keyboard nav — ← / → only when book view is the active surface.
// Guard against clobbering arrow-key seeking in the main audio
// player by checking the focused element.
document.addEventListener("keydown", (e) => {
  if (!bookView || bookView.hidden) return;
  const focused = document.activeElement;
  if (focused && (focused.tagName === "INPUT" || focused.tagName === "TEXTAREA")) return;
  if (e.key === "ArrowLeft") {
    e.preventDefault();
    _bookViewNavigateManual(_bookViewCurrentSpread - 1);
  } else if (e.key === "ArrowRight") {
    e.preventDefault();
    _bookViewNavigateManual(_bookViewCurrentSpread + 1);
  }
});
// Touch swipe — horizontal-only, with a generous threshold so the
// user can scroll the page vertically without accidentally paging.
let _bookSwipeStart = null;
if (bookViewSpread) {
  bookViewSpread.addEventListener("touchstart", (e) => {
    if (e.touches.length !== 1) return;
    _bookSwipeStart = { x: e.touches[0].clientX, y: e.touches[0].clientY };
  }, { passive: true });
  bookViewSpread.addEventListener("touchend", (e) => {
    if (!_bookSwipeStart) return;
    const t = e.changedTouches[0];
    const dx = t.clientX - _bookSwipeStart.x;
    const dy = t.clientY - _bookSwipeStart.y;
    _bookSwipeStart = null;
    if (Math.abs(dx) < 60 || Math.abs(dy) > Math.abs(dx)) return;
    if (dx < 0) {
      _bookViewNavigateManual(_bookViewCurrentSpread + 1);
    } else if (dx > 0) {
      _bookViewNavigateManual(_bookViewCurrentSpread - 1);
    }
  }, { passive: true });
}

// ---- Library (IndexedDB) -------------------------------------------------
// Every generated clip is persisted so it can be replayed without paying the
// synthesis cost again. Clips are stored as their original WAV blob plus the
// metadata needed to restore the reading view and sentence-skip behavior.

// Keep the legacy DB name even after the app was renamed to Narrative — IndexedDB
// is keyed on this string, and changing it would orphan any clips users already saved.
const DB_NAME = "audiable";
const DB_VERSION = 1;
const STORE = "clips";

function openDB() {
  return new Promise((resolve, reject) => {
    const req = indexedDB.open(DB_NAME, DB_VERSION);
    req.onupgradeneeded = () => {
      const db = req.result;
      if (!db.objectStoreNames.contains(STORE)) {
        db.createObjectStore(STORE, { keyPath: "id" });
      }
    };
    req.onsuccess = () => resolve(req.result);
    req.onerror = () => reject(req.error);
  });
}

function idbReq(req) {
  return new Promise((res, rej) => {
    req.onsuccess = () => res(req.result);
    req.onerror = () => rej(req.error);
  });
}

// v223.tn19 (#488): atomic read-modify-write helper. Every clip
// mutation (bookmarks, highlights, mark-played, voice assignments,
// edit dialog saves, cover/tags/notes updates, etc.) was previously
// shaped as `getClip → mutate → saveClip`. Between the read and the
// write, _syncAbsorbServerClip could land — overwriting the IDB row
// with server's newer content (e.g. annotations from another
// device). Caller's saveClip then wrote back its stale snapshot,
// bumped updatedAt to NOW, and the resulting push wiped the
// just-absorbed content from the server via LWW.
//
// _mutateClipAtomic opens ONE readwrite transaction, reads the
// latest row inside it, runs the caller's mutator on that fresh
// clip, writes, awaits the tx commit, then pushes. IDB serializes
// readwrite transactions on the same object store, so absorb cannot
// interleave between this fn's read and write. The mutator
// receives the latest IDB state — never a stale snapshot.
//
// Use this anywhere a caller would normally do
//   `const clip = await getClip(id); clip.x = y; await saveClip(clip);`
// and replace it with
//   `await _mutateClipAtomic(id, (clip) => { clip.x = y; });`.
// The mutator can be async; return value is ignored.
async function _mutateClipAtomic(clipId, mutator) {
  if (clipId == null) return null;
  const db = await openDB();
  const tx = db.transaction(STORE, "readwrite");
  const store = tx.objectStore(STORE);
  const clip = await idbReq(store.get(clipId));
  if (!clip) return null;
  try { await mutator(clip); } catch (e) {
    console.warn("[saveClip] mutator threw:", e);
    try { tx.abort(); } catch {}
    throw e;
  }
  clip.updatedAt = new Date().toISOString();
  await idbReq(store.put(clip));
  await new Promise((resolve, reject) => {
    tx.oncomplete = resolve;
    tx.onerror = () => reject(tx.error);
    tx.onabort = () => reject(tx.error);
  });
  if (typeof _syncPushClip === "function") {
    _syncPushClip(clip).catch((e) => console.warn("[sync] push failed:", e));
  }
  return clip;
}

async function saveClip(clip) {
  const db = await openDB();
  // v222 (#453): ALWAYS stamp a fresh updatedAt on every save — not
  // just when it's missing. The old "if (!clip.updatedAt)" path
  // meant any saveClip call that mutated an existing clip (progress
  // ticks, bookmarks, notes, tags, cover edits) reused the stale
  // updatedAt from the previous save. Then on the server side: LWW
  // saw `payload.updatedAt == server.updated_at`, accepted as
  // idempotent, and stored the same timestamp back. /sync/state
  // never reflected the change, the receiving device's pull
  // comparator never triggered, and edits silently failed to
  // propagate across devices — including playback resume position.
  //
  // Bumping unconditionally guarantees every save reaches the server
  // with a strictly-newer timestamp, which makes the pull comparator
  // fire and the receiving device re-fetch. _syncAbsorbServerClip
  // still bypasses this wrapper (writes via idbReq.put directly) so
  // pulled clips preserve the server's updatedAt — no infinite loop.
  clip.updatedAt = new Date().toISOString();
  await idbReq(db.transaction(STORE, "readwrite").objectStore(STORE).put(clip));
  // Fire-and-forget server push — sync layer handles enabled-check,
  // network errors, conflicts. Doesn't await so saveClip stays fast.
  if (typeof _syncPushClip === "function") {
    _syncPushClip(clip).catch((e) => console.warn("[sync] push failed:", e));
  }
}

async function listClips() {
  const db = await openDB();
  const all = await idbReq(
    db.transaction(STORE, "readonly").objectStore(STORE).getAll()
  );
  // v222 (#458): drop soft-deleted clips at the source so every caller
  // (renderLibrary, chapter queue, bookmark timeline, etc.) skips them
  // automatically. Soft-deletes land here from _syncAbsorbServerClip
  // when another device deletes a clip — we keep the tombstone row in
  // IndexedDB (so the next sync pull doesn't re-fetch it) but never
  // surface it to the UI. Tester reported "I deleted on phone, the
  // card stays on desktop" — that was this filter being absent.
  return all.filter((c) => !c.deleted).sort((a, b) => b.id - a.id);
}

async function getClip(id) {
  const db = await openDB();
  return idbReq(db.transaction(STORE, "readonly").objectStore(STORE).get(id));
}

async function deleteClipById(id) {
  const db = await openDB();
  await idbReq(db.transaction(STORE, "readwrite").objectStore(STORE).delete(id));
  // v221.sync-5: mirror the delete server-side via soft-delete + LWW
  // stamp. Same fire-and-forget pattern.
  if (typeof _syncDeleteClip === "function") {
    _syncDeleteClip(id).catch((e) =>
      console.warn("[sync] delete failed:", e),
    );
  }
}

async function clearLibrary() {
  // v222 (#459): when sync is on, propagate the wipe to the server too.
  // Otherwise the next pull just re-fetches everything we just cleared
  // — tester reported "Delete library on desktop, phone briefly went
  // empty, then everything came back." deleteClipById does the local
  // hard-delete + the fire-and-forget _syncDeleteClip push for each
  // row, which the existing delete pipeline tested as working.
  //
  // listClips already filters out soft-deleted clips (v222c), so we
  // only iterate live rows. Sync push is fire-and-forget — we don't
  // await network round-trips per clip; the local IndexedDB delete is
  // what unblocks the UI.
  const all = await listClips();
  for (const c of all) {
    await deleteClipById(c.id);
  }
}

// ──────────────────────────────────────────────────────────────────────
// v221.sync-5: cross-device library sync adapter.
//
// Server-side library is canonical when sync is on. IndexedDB stays as
// a fast local cache + offline-friendly fallback. Per SYNC.md:
//   - PUT clips with `updatedAt` (LWW comparator on server)
//   - 409 on stale client → absorb server's version
//   - DELETE with `?updated_at=...` for soft-delete
//   - GET /sync/state for delta-pull on render
//   - audioSha256 is the cheap reference when the server already has
//     the blob; audioB64 only when we're uploading a fresh synth or
//     migrating a legacy local clip
//
// Per-device opt-in. Toggle in Settings → App. Flag in localStorage.
// ──────────────────────────────────────────────────────────────────────

const SYNC_ENABLED_KEY = "narrative.syncEnabled";
const SYNC_LAST_PULL_KEY = "narrative.syncLastPullAt";
// v225v3.52 (#430/#785): timestamp of first successful migration.
// Presence = "this device has uploaded its local library at least
// once." On flip OFF → ON we check this: missing → confirm + migrate;
// present → silent enable (the existing pull picks up wherever
// sync left off). Per-device flag, not server-stored.
const SYNC_MIGRATED_KEY = "narrative.syncMigratedAt";
const _SYNC_PULL_MIN_INTERVAL_MS = 30 * 1000; // throttle render-triggered pulls

let _syncPullInFlight = null;
let _syncStatusText = "";

function _syncIsEnabled() {
  try {
    return localStorage.getItem(SYNC_ENABLED_KEY) === "1";
  } catch {
    return false;
  }
}

function _syncSetEnabled(enabled) {
  try {
    if (enabled) {
      localStorage.setItem(SYNC_ENABLED_KEY, "1");
    } else {
      localStorage.removeItem(SYNC_ENABLED_KEY);
    }
  } catch {}
  _updateSyncStatusLine();
  if (enabled) {
    // Immediate pull so the toggle has visible effect; followups are
    // throttled to once per 30s.
    _syncPull(/*force*/ true).catch(() => {});
  }
}

// v225v3.52 (#430/#785): "has this device ever migrated?" check. Used
// to gate the confirm dialog on the very first OFF → ON flip. After
// successful migration we stamp the timestamp; subsequent flip-ons
// silently enable sync without re-asking.
function _syncIsMigrated() {
  try {
    return !!localStorage.getItem(SYNC_MIGRATED_KEY);
  } catch {
    return false;
  }
}

function _syncMarkMigrated() {
  try {
    localStorage.setItem(SYNC_MIGRATED_KEY, new Date().toISOString());
  } catch {}
}

// v225v3.52 (#430/#785): migration entrypoint. Called by the
// sync-enabled radio change handler when the user flips OFF → ON for
// the first time on this device. Counts local clips, estimates the
// upload size, asks for confirmation, runs _syncPushAll if confirmed,
// stamps the migrated flag on success.
//
// Returns true on success (sync should be enabled), false on cancel
// or failure (sync should NOT be enabled, radio should revert).
async function _syncMigrate() {
  let clips = [];
  try {
    clips = await listClips();
  } catch (e) {
    console.warn("[sync] migrate: listClips failed", e);
  }
  const total = clips.length;

  // Empty-library short-circuit: nothing to migrate, no need to ask.
  // Stamp the migrated flag AND flip SYNC_ENABLED_KEY on so the caller
  // can finish wiring the status line / pull. v4.56 fix: the previous
  // version only stamped migrated and skipped SYNC_ENABLED_KEY, which
  // meant the very first On click on a brand-new (empty-library)
  // device looked like a no-op — the radio went visually checked but
  // _syncIsEnabled() stayed false, so the status line still read
  // "Sync is off. Your library stays on this device only." Toggling
  // Off → On a second time hit the _syncIsMigrated() branch in the
  // change handler (the migrated flag DID get set), which correctly
  // called _syncSetEnabled(true). User reported as "doesn't take on
  // the first click — have to click off and then re-click on" on
  // 2026-06-07. Non-empty libraries weren't affected because the
  // push-all path below sets SYNC_ENABLED_KEY before pushing.
  if (total === 0) {
    try {
      localStorage.setItem(SYNC_ENABLED_KEY, "1");
    } catch {}
    _syncMarkMigrated();
    return true;
  }

  // Estimate upload size from each clip's audio blob. Text-only clips
  // contribute negligible bytes; the headline number is the MP3
  // payload. We approximate to MB with one decimal for human-friendly
  // copy ("~12.4 MB" reads more honest than "12345678 bytes").
  let totalBytes = 0;
  for (const c of clips) {
    if (c && c.blob && typeof c.blob.size === "number") {
      totalBytes += c.blob.size;
    }
  }
  const totalMB = totalBytes / (1024 * 1024);
  const sizeLabel =
    totalMB >= 1
      ? `~${totalMB.toFixed(1)} MB`
      : totalMB >= 0.1
      ? `~${totalMB.toFixed(1)} MB`
      : "< 1 MB";

  const msg =
    `This will upload your ${total} clip${total === 1 ? "" : "s"} ` +
    `(${sizeLabel}) to narrative-alpha.fly.dev so your other ` +
    `devices can sync them. Continue?`;

  // Native confirm — matches the app's other destructive-action
  // prompts (Clear all, library wipe, etc.). Keeps the bundle small
  // and works identically on phone + desktop.
  let ok = false;
  try {
    ok = window.confirm(msg);
  } catch {
    ok = false;
  }
  if (!ok) {
    return false;
  }

  // Run the migration via the existing _syncPushAll path, which
  // already handles per-clip iteration with progress status, preset
  // sweep, and a final pull. We need sync enabled while pushing
  // (every internal _syncPushClip call checks the flag), so flip it
  // on FIRST. If migration fails catastrophically we revert below.
  try {
    localStorage.setItem(SYNC_ENABLED_KEY, "1");
  } catch {}
  try {
    await _syncPushAll();
    _syncMarkMigrated();
    return true;
  } catch (e) {
    console.warn("[sync] migrate: push-all failed", e);
    // Migration didn't complete cleanly — revert the enabled flag
    // so the radio click doesn't appear to have "stuck" sync on
    // with an incomplete server-side state.
    try {
      localStorage.removeItem(SYNC_ENABLED_KEY);
    } catch {}
    _syncStatusText =
      "Couldn't migrate library to server — keeping sync off.";
    _updateSyncStatusLine();
    return false;
  }
}

function _updateSyncStatusLine() {
  const el = document.getElementById("sync-status-line");
  if (!el) return;
  if (!_syncIsEnabled()) {
    el.textContent = "Sync is off. Your library stays on this device only.";
    return;
  }
  const last = Number(localStorage.getItem(SYNC_LAST_PULL_KEY)) || 0;
  if (_syncStatusText) {
    el.textContent = _syncStatusText;
    return;
  }
  if (!last) {
    el.textContent = "Sync on. Pulling…";
    return;
  }
  const ago = _formatTimeAgo(last) || "just now";
  el.textContent = `Sync on. Last pulled ${ago}.`;
}

// Convert a Blob to base64 without loading the whole thing as a string
// at once — readAsDataURL chunks internally. Used for legacy clips
// whose audio bytes only live in IndexedDB (no server-side sha yet).
function _blobToBase64(blob) {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => {
      const s = String(r.result || "");
      const i = s.indexOf(",");
      resolve(i >= 0 ? s.slice(i + 1) : s);
    };
    r.onerror = () => reject(r.error);
    r.readAsDataURL(blob);
  });
}

// v225v3.62 (#788): _syncPushClip returns a result so callers can
// distinguish success from "we console.warn'd into the void."
// Shape:
//   { ok: true }                          — server accepted (HTTP 2xx)
//   { ok: true, conflict: true }          — HTTP 409; server's row was
//                                           newer, we absorbed it.
//                                           Not a failure — the receiver
//                                           caught up. Stamping success
//                                           flags is appropriate.
//   { ok: false, status: N, error: "..." } — HTTP 4xx/5xx (≠ 409). The
//                                            push did NOT land.
//   { ok: false, status: 0, error: "network: ..." } — fetch threw
//   { ok: false, status: 0, error: "skipped:..." }  — guard rail
//
// Batch callers (_syncPushAll, _syncBackfillKind, _syncMigrate) must
// check result.ok and gate any "stamp success" steps on every push
// returning ok:true. Existing-clip fire-and-forget callers (saveClip,
// deleteClipById) can ignore the return value but get a dlog entry on
// failure so the next schema mismatch is visible without code-spelunking.
async function _syncPushClip(clip) {
  if (!_syncIsEnabled()) {
    return { ok: false, status: 0, error: "skipped:sync-off" };
  }
  if (!clip || !clip.id) {
    return { ok: false, status: 0, error: "skipped:no-id" };
  }

  const payload = {
    id: clip.id,
    title: clip.title || "",
    text: clip.text || "",
    // v225v3.53 (#786): `kind` distinguishes audio clips from ebook
    // clips (#690). Without this, ebook clips push successfully but
    // lose their kind tag on the receiving device — book-view doesn't
    // route, and the clip looks like a broken audio clip with no blob.
    kind: clip.kind || null,
    voiceId: clip.voiceId || null,
    voiceName: clip.voiceName || null,
    rate: clip.rate != null ? clip.rate : null,
    volume: clip.volume != null ? clip.volume : null,
    speakerId: clip.speakerId != null ? clip.speakerId : null,
    durationSec: clip.durationSec || null,
    progressSec: clip.progressSec || 0,
    sentenceOffsetsSec: Array.isArray(clip.sentenceOffsetsSec)
      ? clip.sentenceOffsetsSec
      : [],
    bookmarks: Array.isArray(clip.bookmarks) ? clip.bookmarks : [],
    note: clip.note || "",
    notes: clip.notes || "",
    tags: Array.isArray(clip.tags) ? clip.tags : [],
    cover: clip.cover || null,
    gitRef: clip.gitRef || null,
    images: Array.isArray(clip.images) ? clip.images : [],
    // v223.annotate-1.5: phone-native revision flags. Server stores
    // them in clips.annotations_json (schema v3). Empty array when
    // missing so the Pydantic default_factory works either way.
    annotations: Array.isArray(clip.annotations) ? clip.annotations : [],
    // v225v4.0 (#810): Author-mode per-sentence storage. lines is null
    // for clips not opted in (server keeps lines_json NULL → blob path
    // runs unchanged). Sending null is critical: omitting the field
    // entirely would let the server's defense-in-depth merge preserve
    // whatever it had stored, which is wrong only in one direction
    // (a manual "disable" — not supported in Phase A — would silently
    // fail). For now we always send the current value and let the
    // server merge handle concurrent edits per-line ID.
    lines: Array.isArray(clip.lines) ? clip.lines : null,
    nextLineSeq: typeof clip.nextLineSeq === "number" ? clip.nextLineSeq : null,
    synthOk: clip.synthOk !== false,
    synthSilentSentenceCount: clip.synthSilentSentenceCount || 0,
    createdAt: clip.createdAt || clip.updatedAt,
    updatedAt: clip.updatedAt || new Date().toISOString(),
    lastSyncedAt: clip.lastSyncedAt || null,
    deleted: !!clip.deleted,
  };

  // Audio: prefer the sha (server already has the blob via v221.sync-4
  // persistence in the synth pipeline). Fall back to base64 upload
  // for legacy clips where the audio only lives in IndexedDB.
  if (clip.audioSha256) {
    payload.audioSha256 = clip.audioSha256;
  } else if (clip.blob) {
    try {
      payload.audioB64 = await _blobToBase64(clip.blob);
    } catch (e) {
      console.warn("[sync] blob encode failed; pushing metadata only", e);
    }
  }

  try {
    const res = await fetch(`/api/library/clips/${clip.id}`, {
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    });
    if (res.status === 409) {
      // LWW conflict — server's row is newer. Absorb its version
      // locally, drop our pending edit (it's already lost per the
      // doc's rule), surface a status hint so the user knows.
      try {
        const body = await res.json();
        const serverClip = body.detail && body.detail.server_clip;
        if (serverClip) await _syncAbsorbServerClip(serverClip);
      } catch {}
      setStatus(
        "Library was updated on another device; using the latest.",
      );
      return { ok: true, conflict: true };
    }
    if (!res.ok) {
      // v225v3.62 (#788): pull the response body for the error
      // message so the dlog records WHY (Pydantic validation,
      // tenant mismatch, etc.) — invaluable when the next schema
      // change quietly breaks something.
      let errBody = "";
      try { errBody = (await res.text()).slice(0, 240); } catch {}
      console.warn(`[sync] push failed: HTTP ${res.status}`, errBody);
      if (typeof _dlog === "function") {
        _dlog("sync", "push failed", {
          clipId: clip.id,
          status: res.status,
          body: errBody,
        });
      }
      return { ok: false, status: res.status, error: errBody || `HTTP ${res.status}` };
    }
    return { ok: true };
  } catch (e) {
    const msg = String(e && e.message || e);
    console.warn("[sync] push network error:", e);
    if (typeof _dlog === "function") {
      _dlog("sync", "push network error", {
        clipId: clip.id,
        error: msg,
      });
    }
    return { ok: false, status: 0, error: `network: ${msg}` };
  }
}

async function _syncDeleteClip(clipId) {
  if (!_syncIsEnabled()) return;
  if (!clipId) return;
  const updatedAt = new Date().toISOString();
  try {
    const u = `/api/library/clips/${clipId}?updated_at=${encodeURIComponent(updatedAt)}`;
    await fetch(u, { method: "DELETE" });
  } catch (e) {
    console.warn("[sync] delete failed:", e);
  }
}

// Pull server state, fetch any clips newer-than-local, write them
// to IndexedDB. Called from renderLibrary (throttled). Pass force=true
// to bypass the 30s debounce — used when the user explicitly flips
// sync on or refreshes the library.
async function _syncPull(force) {
  if (!_syncIsEnabled()) return;
  if (_syncPullInFlight) return _syncPullInFlight;

  const last = Number(localStorage.getItem(SYNC_LAST_PULL_KEY)) || 0;
  if (!force && Date.now() - last < _SYNC_PULL_MIN_INTERVAL_MS) return;

  _syncStatusText = "Syncing…";
  _updateSyncStatusLine();

  _syncPullInFlight = (async () => {
    try {
      const stateRes = await fetch("/api/library/sync/state");
      if (!stateRes.ok) {
        if (stateRes.status === 503) {
          // Server-side sync disabled — surface but don't repeatedly
          // hammer the endpoint until the user fixes it.
          _syncStatusText = "Server sync not available.";
        } else {
          _syncStatusText = `Sync state: HTTP ${stateRes.status}`;
        }
        return;
      }
      const state = await stateRes.json();
      const serverClips = state.clips || {};
      const localList = await listClips();
      const localById = new Map(localList.map((c) => [String(c.id), c]));

      // Pull anything where server.updated_at > local.updatedAt, or
      // where the clip exists on server but not locally.
      const toPull = [];
      for (const [idStr, serverUpdatedAt] of Object.entries(serverClips)) {
        const local = localById.get(idStr);
        if (!local) {
          toPull.push(idStr);
        } else if (
          !local.updatedAt ||
          serverUpdatedAt > local.updatedAt
        ) {
          toPull.push(idStr);
        }
      }
      for (const idStr of toPull) {
        await _syncFetchAndStoreClip(Number(idStr));
      }

      localStorage.setItem(SYNC_LAST_PULL_KEY, String(Date.now()));
      _syncStatusText = "";
      // Re-render so newly-pulled clips appear without a manual refresh.
      if (toPull.length > 0 && typeof renderLibrary === "function") {
        renderLibrary();
      }
    } catch (e) {
      _syncStatusText = `Sync pull error: ${e.message}`;
      console.warn("[sync] pull failed:", e);
    } finally {
      _syncPullInFlight = null;
      _updateSyncStatusLine();
    }
  })();
  return _syncPullInFlight;
}

async function _syncFetchAndStoreClip(clipId) {
  const res = await fetch(`/api/library/clips/${clipId}`);
  if (!res.ok) return;
  const body = await res.json();
  const sc = body && body.clip;
  if (!sc) return;
  await _syncAbsorbServerClip(sc);
}

async function _syncAbsorbServerClip(sc) {
  // Convert the server clip dict back into the local IndexedDB shape.
  // Audio: if the server has a sha + we don't have the bytes locally,
  // fetch on demand and stash as a Blob. This is the "phone fetches
  // a re-narrated chapter" path — desktop synth's MP3 lands here.
  let blob = null;
  if (sc.audioUrl) {
    try {
      const audioRes = await fetch(sc.audioUrl);
      if (audioRes.ok) {
        blob = await audioRes.blob();
      }
    } catch (e) {
      console.warn("[sync] audio fetch failed for", sc.id, e);
    }
  }
  const localShape = {
    id: sc.id,
    title: sc.title,
    text: sc.text,
    // v225v3.53 (#786): preserve ebook-mode tag so receiving device
    // routes through book-view + skips audio-load branches. Falsy
    // server value → undefined locally → treated as an audio clip.
    kind: sc.kind || undefined,
    voiceId: sc.voiceId,
    voiceName: sc.voiceName,
    rate: sc.rate,
    volume: sc.volume,
    speakerId: sc.speakerId,
    durationSec: sc.durationSec,
    progressSec: sc.progressSec,
    sentenceOffsetsSec: sc.sentenceOffsetsSec || [],
    bookmarks: sc.bookmarks || [],
    note: sc.note || "",
    notes: sc.notes || "",
    tags: sc.tags || [],
    cover: sc.cover || undefined,
    gitRef: sc.gitRef || null,
    images: sc.images || [],
    // v223.annotate-1.5: server returns annotations from the JSON
    // column; preserve them on the local IDB row so the receiving
    // device sees the same flags + marker dots without a re-fetch.
    annotations: Array.isArray(sc.annotations) ? sc.annotations : [],
    // v225v4.0 (#810): per-sentence storage. Server only emits these
    // fields when the clip is opted in; absent → undefined locally →
    // clip stays in the legacy blob model on the receiving device. A
    // cross-device convert thus propagates automatically: device A
    // converts, syncs, device B's next absorb lands clip.lines and
    // the reading view starts emitting data-line-id on next load.
    lines: Array.isArray(sc.lines) ? sc.lines : undefined,
    nextLineSeq: typeof sc.nextLineSeq === "number" ? sc.nextLineSeq : undefined,
    synthOk: sc.synthOk !== false,
    synthSilentSentenceCount: sc.synthSilentSentenceCount || 0,
    createdAt: sc.createdAt,
    updatedAt: sc.updatedAt,
    lastSyncedAt: sc.lastSyncedAt,
    // v223.tn17 (#486): mark "this device just received fresh content
    // from the server" so the library card footer can show
    // "Synced · 5m ago" alongside / instead of the GitHub
    // "Last synced 17h ago" line. Local-only field — not part of the
    // server payload, doesn't sync; each device tracks its own.
    lastDeviceSyncAt: new Date().toISOString(),
    audioSha256: sc.audioSha256 || undefined,
    blob: blob || undefined,
    deleted: !!sc.deleted,
  };
  // Direct IndexedDB write — bypass the saveClip wrapper so we don't
  // re-push to server in a loop.
  const db = await openDB();
  await idbReq(
    db.transaction(STORE, "readwrite").objectStore(STORE).put(localShape),
  );
  // v223.tn20 (#490): if the user is currently viewing this clip, the
  // reading-view spans were built with whatever annotations existed at
  // load time and don't auto-refresh. Repaint markers + voice-note ▶
  // buttons + transcripts inline so new content from another device
  // shows up without a page reload.
  if (_currentClipId === localShape.id) {
    // v225v4.101: detect whether TEXT changed in this absorb. If yes,
    // do a full loadClip so the reading-view spans rebuild from new
    // content; if no (annotations/bookmarks only — the original #490
    // use case), do the lighter marker + drawer refresh as before.
    // The bug v4.100 probed: GitHub Pull lands new text into IDB but
    // sentence spans never rebuild, so user sees old text forever.
    const newText = localShape.text || "";
    const readingView = document.querySelector(".reading-view")
      || document.getElementById("reading-view");
    const rvText = readingView ? (readingView.textContent || "") : "";
    const textChanged =
      rvText.trim().length > 0 && newText.trim() !== rvText.trim();
    if (typeof _dlog === "function") {
      try {
        _dlog("sync-absorb", "current clip absorbed", {
          clipId: localShape.id,
          newTextLen: newText.length,
          newTextHead: newText.slice(0, 80),
          renderedTextLen: rvText.length,
          renderedTextHead: rvText.slice(0, 80),
          textChanged,
          action: textChanged ? "loadClip" : "light-refresh",
          kind: localShape.kind || "audio",
        });
      } catch {}
    }
    if (textChanged) {
      // Full reload — rebuilds sentence spans, swaps audio source,
      // restores progressSec from IDB. autoPlay:false because the
      // user was reading silently; don't surprise them with playback.
      loadClip(localShape.id, { autoPlay: false }).catch((e) => {
        console.warn("[sync] post-absorb reload failed:", e);
      });
    } else {
      try {
        if (typeof _applyAnnotationMarkers === "function") {
          _applyAnnotationMarkers(localShape);
        }
        // Bookmarks list (if visible) also reads from IDB — re-render
        // so a bookmark added on another device appears immediately.
        if (typeof renderBookmarks === "function") {
          renderBookmarks().catch(() => {});
        }
      } catch (e) {
        console.warn("[sync] post-absorb refresh failed:", e);
      }
    }
  }
}

// Throttled pull from renderLibrary. We don't want to hit the server
// every single render; once every 30s is plenty for a phone polling
// for updates while a desktop synth happens.
let _syncPullScheduled = false;
function _syncPullDebounced() {
  if (!_syncIsEnabled()) return;
  if (_syncPullScheduled) return;
  _syncPullScheduled = true;
  setTimeout(() => {
    _syncPullScheduled = false;
    _syncPull(false).catch(() => {});
  }, 0);
}

// v223.tn1: push every local clip to the server, then pull. Users
// reach for this after offline editing, before swapping devices, or
// when they want immediate confirmation instead of waiting for the
// 60s auto-pull. Reuses _syncPushClip (already idempotent + LWW)
// and _syncPull(true) (force-refresh) so behavior matches the
// background path — just compressed into one button.
let _syncPushAllInFlight = false;
async function _syncPushAll() {
  if (!_syncIsEnabled()) {
    _syncStatusText = "Turn sync on first.";
    _updateSyncStatusLine();
    return;
  }
  if (_syncPushAllInFlight) return;
  _syncPushAllInFlight = true;
  try {
    const clips = await listClips();
    const total = clips.length;
    let pushed = 0;
    let failed = 0;
    // v225v3.62 (#788): _syncPushClip now returns {ok, ...} instead of
    // silently swallowing 4xx/5xx as console.warn. The original code
    // here wrapped the call in try/catch and counted failures via the
    // throw — but _syncPushClip never threw, so `failed` stayed at 0
    // even when every PUT returned 422 (the v3.53 backfill bug).
    // Check result.ok directly; the try/catch is defense in depth for
    // a truly unexpected throw (e.g. listClips changing shape).
    for (const clip of clips) {
      _syncStatusText = `Pushing ${pushed + 1}/${total}…`;
      _updateSyncStatusLine();
      try {
        const result = await _syncPushClip(clip);
        if (result && result.ok) pushed++;
        else failed++;
      } catch (e) {
        failed++;
        console.warn("[sync] push threw unexpectedly for clip", clip.id, e);
      }
    }
    // v225fz8 (#674): push every locally-saved preset too. The user
    // probably has a few from before they opted into sync; without
    // this, first-time opt-in would only ship clips and their preset
    // list would silently stay device-local. Counts join the clip
    // numbers in the status toast below.
    if (typeof _loadPresets === "function") {
      const presets = _loadPresets();
      for (const preset of presets) {
        // Stamp updatedAt if missing — legacy presets from pre-v225fz8
        // don't have one and would otherwise lose every LWW race.
        if (!preset.updatedAt) {
          preset.updatedAt = preset.createdAt || new Date().toISOString();
        }
        try {
          await _syncPushPreset(preset);
        } catch (e) {
          console.warn("[sync] preset push failed:", preset.id, e);
        }
      }
      // Persist the updatedAt backfill so subsequent runs don't re-stamp.
      _savePresets(presets);
    }
    _syncStatusText = total
      ? `Pushed ${pushed}/${total}${failed ? ` (${failed} failed)` : ""}. Pulling…`
      : "Nothing local to push. Pulling…";
    _updateSyncStatusLine();
    await _syncPull(/*force*/ true);
    // v225fz8 (#674): include presets in the manual Sync now sweep so
    // users mash the button after saving a preset on phone and see it
    // immediately on desktop. Runs after the clip pull so the status
    // line's "Pulling…" text covers both.
    if (typeof _syncPullPresets === "function") {
      await _syncPullPresets().catch(() => {});
    }
    // _syncPull clears _syncStatusText on success; restore a confirmation
    // line so users see the button did something.
    const ago = "just now";
    _syncStatusText = total
      ? `Synced ${pushed}/${total} ${ago}.${failed ? ` ${failed} failed — see console.` : ""}`
      : `Pulled ${ago}.`;
    _updateSyncStatusLine();
  } finally {
    _syncPushAllInFlight = false;
    // v4.59 (#489): the legacy `sync-now-btn` was split into a Pull
    // (`sync-pull-btn`) and a Force-push (`sync-push-btn`). Restore
    // BOTH if they exist (only one is in flight at a time, but the
    // legacy button id is also tolerated so older shells still work).
    const _restore = (id, label) => {
      const b = document.getElementById(id);
      if (b) {
        b.disabled = false;
        b.textContent = label;
      }
    };
    _restore("sync-now-btn", "Sync now");
    _restore("sync-push-btn", "Force-push to server");
    _restore("sync-pull-btn", "Pull now");
  }
}

// Wire the radios + initial state. Toggle uses the same theme-picker
// markup so the visual matches Mode/Theme/Skip rows.
// v225v3.52 (#430/#785): the radio handler is the entrypoint for the
// FIRST flip OFF → ON on a device. Subsequent flips (after a successful
// migration, OR the user later flipping off) just call _syncSetEnabled
// directly. The first flip-on calls _syncMigrate which prompts +
// pushes existing clips before sync goes live.
async function _syncRadioChange(radio) {
  if (!radio.checked) return;
  if (radio.value !== "on") {
    _syncSetEnabled(false);
    return;
  }
  // value === "on"
  if (_syncIsMigrated()) {
    // We've done the dance before — just enable + pull, no prompt.
    _syncSetEnabled(true);
    return;
  }
  // First-time enable on this device. Run migration, which prompts
  // the user, pushes clips, stamps the flag. On cancel/failure, revert
  // the radio so it visibly stays OFF.
  const ok = await _syncMigrate();
  if (!ok) {
    const off = document.querySelector(
      'input[name="sync-enabled"][value="off"]'
    );
    if (off) off.checked = true;
    _updateSyncStatusLine();
    return;
  }
  // Migration succeeded. _syncMigrate already set the enabled flag
  // and ran a push; now do the symmetric pull so anything on the
  // server (e.g., presets pushed from another device that we don't
  // yet have locally) flows in.
  _updateSyncStatusLine();
  _syncPull(/*force*/ true).catch(() => {});
}

document
  .querySelectorAll('input[name="sync-enabled"]')
  .forEach((radio) => {
    radio.addEventListener("change", () => {
      _syncRadioChange(radio).catch((e) =>
        console.warn("[sync] radio change handler failed:", e)
      );
    });
  });
// v4.59 (#489): Sync now is now two distinct buttons.
//
//   Pull now (sync-pull-btn) — calls _syncPull(force=true) +
//     _syncPullPresets. Safe everyday "refresh from server" action.
//     Local state is preserved via LWW on the server side.
//
//   Force-push to server (sync-push-btn) — calls _syncPushAll, which
//     pushes every local clip + preset to the server, then re-pulls.
//     This is the destructive operation: anything edited on another
//     device since that device last synced will be CLOBBERED by this
//     device's state. Guarded by a confirm dialog with a diff
//     summary (clip count + preset count).
//
// Both buttons stay disabled while the in-flight op runs so a fat-finger
// can't fan out a second push wave overlapping the first.
{
  const pullBtn = document.getElementById("sync-pull-btn");
  if (pullBtn) {
    pullBtn.addEventListener("click", async () => {
      if (pullBtn.disabled) return;
      if (!_syncIsEnabled()) {
        setStatus("Turn on sync above before pulling.", true);
        return;
      }
      pullBtn.disabled = true;
      pullBtn.textContent = "Pulling…";
      try {
        await _syncPull(/*force*/ true);
        // v225fz8 (#674) parity: presets sync alongside clips. The
        // legacy Sync now button pulled both; preserve that here so
        // users mash Pull after saving a preset on phone and see it
        // on desktop.
        if (typeof _syncPullPresets === "function") {
          await _syncPullPresets().catch(() => {});
        }
        _syncStatusText = "Pulled just now.";
        _updateSyncStatusLine();
      } catch (e) {
        console.warn("[sync] pull failed:", e);
        _syncStatusText = `Pull failed: ${e.message}`;
        _updateSyncStatusLine();
      } finally {
        pullBtn.disabled = false;
        pullBtn.textContent = "Pull now";
      }
    });
  }

  const pushBtn = document.getElementById("sync-push-btn");
  if (pushBtn) {
    pushBtn.addEventListener("click", async () => {
      if (pushBtn.disabled) return;
      if (!_syncIsEnabled()) {
        setStatus("Turn on sync above before force-pushing.", true);
        return;
      }
      // Build a short diff summary BEFORE confirming so the user knows
      // exactly what they're about to upload. Counts are cheap; we
      // already have listClips and the in-memory presets list.
      let clipCount = 0;
      let presetCount = 0;
      try {
        const clips = await listClips();
        clipCount = (clips || []).length;
      } catch {}
      try {
        if (typeof _loadPresets === "function") {
          presetCount = (_loadPresets() || []).length;
        }
      } catch {}
      const ok = window.confirm(
        `Force-push to server?\n\n` +
        `This will overwrite the server with this device's library:\n` +
        `  • ${clipCount} clip${clipCount === 1 ? "" : "s"}\n` +
        `  • ${presetCount} voice preset${presetCount === 1 ? "" : "s"}\n\n` +
        `Anything edited on another device since that device's last ` +
        `pull will be REPLACED by this device's version.\n\n` +
        `If you just want the latest from the server, cancel this and ` +
        `use Pull now instead.`
      );
      if (!ok) {
        _syncStatusText = "Force-push cancelled.";
        _updateSyncStatusLine();
        return;
      }
      pushBtn.disabled = true;
      pushBtn.textContent = "Pushing…";
      try {
        await _syncPushAll();
      } finally {
        // _syncPushAll's finally already restores button labels; this
        // is belt-and-suspenders for the path where the function
        // throws before reaching its own finally.
        pushBtn.disabled = false;
        pushBtn.textContent = "Force-push to server";
      }
    });
  }

  // Backward compat: if a hot-loaded older index.html still has the
  // legacy `sync-now-btn`, wire it to the old behavior so nothing
  // visibly breaks during the SW swap window.
  const legacyBtn = document.getElementById("sync-now-btn");
  if (legacyBtn) {
    legacyBtn.addEventListener("click", async () => {
      if (legacyBtn.disabled) return;
      legacyBtn.disabled = true;
      legacyBtn.textContent = "Syncing…";
      try {
        await _syncPushAll();
      } finally {
        legacyBtn.disabled = false;
        legacyBtn.textContent = "Sync now";
      }
    });
  }
}
_updateSyncStatusLine();
// v225v3.52 (#430/#785): backfill the migrated-at flag for users who
// had sync ENABLED before this code shipped. Without this, a user
// who flips OFF then back ON would see a surprise migration dialog
// even though their server state is already current. If sync is on
// already, by definition they've migrated (or were never in a state
// that needed migrating — empty initial libraries) — so stamp it.
if (_syncIsEnabled() && !_syncIsMigrated()) {
  _syncMarkMigrated();
}
// v225v3.53 (#786): one-time backfill for the `kind` field. Clips
// that were pushed under v3.52 or earlier landed on the server with
// kind=NULL because the push payload didn't include the field. After
// v3.53 the payload + server schema carry it, but existing rows are
// still un-tagged — so any ebook clip a user already has would still
// pull onto a fresh device as a "kind=null = audio" clip.
//
// Fix: on boot, if sync is on and we haven't backfilled yet, scan
// local clips and re-push any with a non-null `kind`. Audio clips
// are skipped (their kind was always null; nothing to update).
// Stamp a flag so this runs exactly once per device. Fire-and-forget
// so boot isn't blocked — re-pushes happen in the background while
// the user uses the app.
// v225v3.55 (#787-followup): bumped key suffix from "...At" → "...AtV2".
// v3.53's backfill stamped the flag even though every PUT returned 422
// (the 422 was caused by ClipUpsert rejecting string covers, fixed in
// v3.54). Old key = backfill-thinks-it-succeeded; new key = re-fire on
// next boot so the corrected payloads actually land on the server.
const SYNC_KIND_BACKFILL_KEY = "narrative.syncKindBackfilledAtV2";
async function _syncBackfillKind() {
  try {
    if (localStorage.getItem(SYNC_KIND_BACKFILL_KEY)) return;
  } catch {
    return;
  }
  try {
    const clips = await listClips();
    const ebookish = (clips || []).filter((c) => c && c.kind);
    // v225v3.62 (#788): track per-clip success so we only stamp the
    // localStorage flag when every push actually landed. Before #788,
    // _syncPushClip silently swallowed 4xx/5xx and this loop's
    // try/catch never fired — the flag got stamped even when every
    // PUT returned 422 (the v3.53 bug). Now we count ok vs failed
    // explicitly; if anything failed, leave the flag missing so the
    // backfill runs again next boot (after the user / a deploy fixes
    // whatever was wrong).
    let pushed = 0;
    let failed = 0;
    for (const c of ebookish) {
      try {
        const result = await _syncPushClip(c);
        if (result && result.ok) pushed++;
        else failed++;
      } catch (e) {
        failed++;
        console.warn("[sync] kind backfill threw unexpectedly for", c.id, e);
      }
    }
    if (failed === 0) {
      try {
        localStorage.setItem(SYNC_KIND_BACKFILL_KEY, new Date().toISOString());
      } catch {}
    }
    if (typeof _dlog === "function") {
      _dlog("sync", "kind-backfill complete", {
        total: ebookish.length,
        pushed,
        failed,
        stamped: failed === 0,
      });
    }
  } catch (e) {
    console.warn("[sync] kind backfill scan failed", e);
  }
}
if (_syncIsEnabled()) {
  _syncBackfillKind().catch(() => {});
}
// Also sync the radio's checked state to the localStorage flag. The
// radios are unchecked by default in the HTML; without this the
// Settings dialog opens showing neither radio active even though
// sync IS on.
const _syncRadioInitial = document.querySelector(
  `input[name="sync-enabled"][value="${_syncIsEnabled() ? "on" : "off"}"]`
);
if (_syncRadioInitial) _syncRadioInitial.checked = true;
if (_syncIsEnabled()) {
  // Kick a pull at boot so the library renders with server state in
  // hand (or close to it — pull is async).
  _syncPull(true).catch(() => {});
  setInterval(() => _syncPull(false).catch(() => {}), 60 * 1000);
  // v225fz8 (#674): presets are a separate endpoint, pulled in
  // parallel. Same 60s poll cadence so a preset saved on phone shows
  // up on desktop without a refresh. Pull is cheap (tiny payload,
  // tenant-scoped) so polling at clip cadence is fine.
  if (typeof _syncPullPresets === "function") {
    _syncPullPresets().catch(() => {});
    setInterval(() => _syncPullPresets().catch(() => {}), 60 * 1000);
  }
}

function formatTime(sec) {
  if (!isFinite(sec) || sec <= 0) return "0:00";
  const total = Math.round(sec);
  const m = Math.floor(total / 60);
  const s = total % 60;
  return `${m}:${String(s).padStart(2, "0")}`;
}

function formatClipMeta(clip) {
  const parts = [];
  // v220p: voice name moved out of the meta line into the title row,
  // where it has horizontal room to display without truncating to "A.".
  // See makeClipCard's titleTop construction. The meta line now just
  // carries word-count / duration / date.
  const wordCount = _countWords(clip.text);
  if (wordCount > 0) parts.push(`${wordCount.toLocaleString()}w`);
  // Show resume position if there's a meaningful in-progress checkpoint,
  // otherwise just show the duration.
  if (clip.durationSec) {
    const progress = Number(clip.progressSec) || 0;
    if (progress > 1 && progress < clip.durationSec - 1) {
      parts.push(`${formatTime(progress)} / ${formatTime(clip.durationSec)}`);
    } else {
      parts.push(formatTime(clip.durationSec));
    }
  }
  if (clip.createdAt) {
    const d = new Date(clip.createdAt);
    const today = new Date();
    const sameDay = d.toDateString() === today.toDateString();
    parts.push(
      sameDay
        ? d.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })
        : d.toLocaleDateString()
    );
  }
  return parts.join(" · ");
}

// ---- Library order, search, auto-advance --------------------------------
// _playMode controls BOTH the on-screen sort and the auto-advance order so
// "what plays next" matches "what you see next" — except for shuffle, which
// keeps the newest-first display but randomizes auto-advance.
//
// listClips() returns newest-first (id descending), so "newest" needs no
// extra work; sortClips() handles the others.
const PLAY_MODES = ["newest", "oldest", "longest", "shortest", "custom", "shuffle"];
const PLAY_MODE_LABELS = {
  newest: "Newest first",
  oldest: "Oldest first",
  longest: "Longest first",
  shortest: "Shortest first",
  custom: "Custom order",
  shuffle: "Shuffle",
};
const PLAY_MODE_KEY = "narrative.playMode";
const LIBRARY_ORDER_KEY = "narrative.libraryOrder";

function _loadLibraryOrder() {
  try {
    const raw = localStorage.getItem(LIBRARY_ORDER_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.map(Number).filter(Number.isFinite) : [];
  } catch {
    return [];
  }
}

function _saveLibraryOrder(ids) {
  try {
    localStorage.setItem(LIBRARY_ORDER_KEY, JSON.stringify(ids));
  } catch {}
}

let _playMode = PLAY_MODES.includes(localStorage.getItem(PLAY_MODE_KEY))
  ? localStorage.getItem(PLAY_MODE_KEY)
  : "newest";

// Search query is session-scoped (re-typing on reload is fine; remembering
// a stale filter past a refresh is annoying).
let _librarySearch = "";

function sortClips(clips, mode) {
  if (mode === "oldest") return [...clips].reverse();
  if (mode === "longest") {
    return [...clips].sort(
      (a, b) => (b.durationSec || 0) - (a.durationSec || 0)
    );
  }
  if (mode === "shortest") {
    return [...clips].sort(
      (a, b) => (a.durationSec || 0) - (b.durationSec || 0)
    );
  }
  if (mode === "custom") {
    // Honor the user-drag-defined order from localStorage. Clips not in
    // the order list (e.g. freshly generated after the last reorder) fall
    // through to newest-first behind whatever's been explicitly placed.
    const order = _loadLibraryOrder();
    const orderIdx = new Map(order.map((id, i) => [id, i]));
    return [...clips].sort((a, b) => {
      const ai = orderIdx.has(a.id) ? orderIdx.get(a.id) : Infinity;
      const bi = orderIdx.has(b.id) ? orderIdx.get(b.id) : Infinity;
      if (ai !== bi) return ai - bi;
      // Tie-breaker for unsorted clips: newest first.
      return b.id - a.id;
    });
  }
  // newest, shuffle → leave at listClips() default (newest-first)
  return clips;
}

function updatePlayModeBtn() {
  playModeBtn.textContent = PLAY_MODE_LABELS[_playMode];
}

playModeBtn.addEventListener("click", () => {
  const i = PLAY_MODES.indexOf(_playMode);
  _playMode = PLAY_MODES[(i + 1) % PLAY_MODES.length];
  try { localStorage.setItem(PLAY_MODE_KEY, _playMode); } catch {}
  updatePlayModeBtn();
  // Re-render the library so the new sort applies immediately.
  renderLibrary();
  // v166: first-tap hint — the sort chip cycles through six modes
  // (Newest / Oldest / Longest / Shortest / Custom / Shuffle) but a
  // first-time tester sees the label change once and has no signal
  // that more taps keep cycling. Matches the v150 hint pattern.
  if (typeof _fireChipHint === "function") {
    _fireChipHint(
      "narrative.hintSeen.playMode",
      "💡 Tap the sort chip again to cycle: Newest · Oldest · Longest · Shortest · Custom · Shuffle.",
    );
  }
});

updatePlayModeBtn();

librarySearch.addEventListener("input", () => {
  _librarySearch = librarySearch.value;
  renderLibrary();
});

librarySearch.addEventListener("keydown", (e) => {
  if (e.key === "Escape") {
    librarySearch.value = "";
    _librarySearch = "";
    renderLibrary();
    librarySearch.blur();
  }
});

// "Hide played" filter — toggles whether clips with a playedAt stamp are
// rendered. Persisted across reloads so the preference sticks.
const HIDE_PLAYED_KEY = "narrative.hidePlayed";
let _hidePlayed = (() => {
  try { return localStorage.getItem(HIDE_PLAYED_KEY) === "true"; }
  catch { return false; }
})();

function _updateHidePlayedBtn() {
  libraryHidePlayedBtn.textContent = _hidePlayed ? "Show all" : "Hide played";
  libraryHidePlayedBtn.setAttribute("aria-pressed", String(_hidePlayed));
}
_updateHidePlayedBtn();

libraryHidePlayedBtn.addEventListener("click", () => {
  _hidePlayed = !_hidePlayed;
  try { localStorage.setItem(HIDE_PLAYED_KEY, _hidePlayed ? "true" : "false"); }
  catch {}
  _updateHidePlayedBtn();
  renderLibrary();
  // v166: first-tap status confirms which state we just flipped into,
  // so a tester who can't tell whether they're now hiding or showing
  // gets an unambiguous signal once. CSS aria-pressed styling carries
  // the state visually after that.
  if (typeof _fireChipHint === "function") {
    _fireChipHint(
      "narrative.hintSeen.hidePlayed",
      _hidePlayed
        ? "💡 Played clips are now hidden — the button reads 'Show all' while filtered."
        : "💡 Showing every clip again. Tap 'Hide played' to filter finished ones out.",
    );
  }
});

// "Sync GitHub" — batch-check every git-sourced clip in the library
// against current GitHub SHAs. Groups by repoUrl+branch so a 35-chapter
// queue from one repo is one API call, not 35. Updates _outdatedClipIds
// then re-renders the library so cards flag themselves.
async function syncAllFromGithub() {
  // v225v4.103: visible feedback + one-tap full sync.
  // Old behavior: tap Sync GitHub → SHA check → silently populate
  // _outdatedClipIds → setStatus a summary (invisible on this user's
  // desktop because #status is display:none). User taps the button,
  // sees nothing, files a bug. Two-step design (Sync GitHub, then
  // "Re-narrate outdated") was buried.
  // New: alert() the outcome at every exit, and if outdated clips are
  // found, offer to chain into renarrateAllOutdated() in the same tap.
  const _slog = (msg, payload) => {
    if (typeof _dlog === "function") _dlog("github-sync-all", msg, payload || {});
  };
  _slog("button tapped", {});
  const token = getGithubToken();
  if (!token) {
    _slog("bail: no GitHub PAT", {});
    alert("Sync GitHub failed: no GitHub PAT saved.\n\n" +
          "Open Settings → Account → GitHub credentials and paste a " +
          "Personal Access Token. Then tap Sync GitHub again.");
    setStatus("Set a GitHub PAT in Settings before syncing.", true);
    return;
  }
  const allClips = await listClips();
  const gitClips = allClips.filter((c) => c.gitRef && c.gitRef.repoUrl && c.gitRef.path);
  _slog("filtered to GitHub clips", {
    total: allClips.length, gitClips: gitClips.length,
  });
  if (gitClips.length === 0) {
    _slog("bail: no GitHub clips", {});
    alert("No GitHub-sourced clips in the library.\n\n" +
          "Import a clip from GitHub first (Import dropdown → GitHub).");
    setStatus("No GitHub-sourced clips in the library.");
    return;
  }
  // Group clips by repoUrl+branch so one tree call covers many clips.
  const groups = new Map(); // key = "url::branch" → {repoUrl, branch, clips: [{id, path, sha}]}
  for (const clip of gitClips) {
    const key = `${clip.gitRef.repoUrl}::${clip.gitRef.branch || ""}`;
    if (!groups.has(key)) {
      groups.set(key, {
        repoUrl: clip.gitRef.repoUrl,
        branch: clip.gitRef.branch || null,
        clips: [],
      });
    }
    groups.get(key).clips.push({
      id: clip.id,
      path: clip.gitRef.path,
      sha: clip.gitRef.sha,
    });
  }
  librarySyncGithubBtn.disabled = true;
  const originalLabel = librarySyncGithubBtn.textContent;
  librarySyncGithubBtn.textContent = "Syncing…";
  setStatus(
    `Syncing ${gitClips.length} clip${gitClips.length === 1 ? "" : "s"} across ${groups.size} repo${groups.size === 1 ? "" : "s"}…`
  );
  try {
    const items = Array.from(groups.values()).map((g) => ({
      repoUrl: g.repoUrl,
      branch: g.branch,
      paths: Array.from(new Set(g.clips.map((c) => c.path))),
    }));
    const res = await fetch("/api/github/sync-check", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ github_token: token, items }),
    });
    if (!res.ok) {
      let detail = `HTTP ${res.status}`;
      try { const j = await res.json(); if (j.detail) detail = j.detail; } catch {}
      throw new Error(detail);
    }
    const data = await res.json();
    // Walk results and flag outdated clip ids.
    const newOutdated = new Set();
    let errors = 0;
    for (const result of data.results || []) {
      if (result.error) {
        errors++;
        continue;
      }
      const key = `${result.repoUrl}::${result.branch || ""}`;
      const group = groups.get(key) || groups.get(`${result.repoUrl}::`);
      if (!group) continue;
      for (const c of group.clips) {
        const currentSha = (result.shas || {})[c.path] || "";
        if (currentSha && currentSha !== c.sha) {
          newOutdated.add(c.id);
        }
      }
    }
    _outdatedClipIds = newOutdated;
    renderLibrary();
    const outdatedCount = newOutdated.size;
    const errTail = errors ? ` (${errors} repo${errors === 1 ? "" : "s"} failed)` : "";
    _slog("sync-check complete", {
      gitClips: gitClips.length, outdated: outdatedCount, errors,
    });
    if (outdatedCount === 0) {
      const msg = `All ${gitClips.length} GitHub-sourced clip${gitClips.length === 1 ? "" : "s"} ` +
                  `up to date.${errTail}`;
      alert(msg);
      setStatus(msg);
    } else {
      const summary = `${outdatedCount} of ${gitClips.length} clip${gitClips.length === 1 ? "" : "s"} ` +
                      `have newer commits on GitHub.${errTail}`;
      setStatus(summary);
      // Offer to chain into the second half — refetch + re-narrate —
      // in the same tap. Without this, the user has to find the
      // "Re-narrate outdated" button and tap it manually, OR open each
      // outdated card and tap "Refetch + re-narrate" on its banner.
      // That two-step flow is what's been confusing the user.
      const proceed = confirm(
        `${summary}\n\n` +
        `Refetch new text from GitHub and re-narrate them now?\n\n` +
        `(This re-narrates ${outdatedCount} clip${outdatedCount === 1 ? "" : "s"} in the ` +
        `background — watch the queue panel for progress.)`
      );
      _slog("renarrate confirm", { proceed, outdatedCount });
      if (proceed && typeof renarrateAllOutdated === "function") {
        // Fire-and-forget — the renarrate function manages its own
        // button state + status. We've already cleared this one's
        // disabled flag below in the finally.
        renarrateAllOutdated().catch((e) => {
          console.warn("[sync-all] renarrate chain threw:", e);
        });
      }
    }
  } catch (err) {
    _slog("threw", { error: String(err && err.message || err) });
    alert(`Sync failed: ${err.message}`);
    setStatus(_withOfflineHint(`Sync failed: ${err.message}`), true);
  } finally {
    librarySyncGithubBtn.disabled = false;
    librarySyncGithubBtn.textContent = originalLabel;
  }
}

librarySyncGithubBtn.addEventListener("click", syncAllFromGithub);

// v176: companion to Sync all. The Sync flow populates
// _outdatedClipIds with library clips whose upstream SHA has moved.
// This handler closes the loop by refetching each outdated clip and
// dropping it into the background queue with targetClipId set, so
// _preSynthesizeChapter overwrites the existing clip rather than
// minting a new one. Title, notes, bookmarks, cover, tags all
// survive (see saveClip block in _preSynthesizeChapter).
// v220al: refetch the GitHub source for a single clip and drop it into
// the background queue with targetClipId set. Returns true on success,
// false on any failure (no gitRef, network error, non-OK response).
// Used by both the bulk "Re-narrate outdated" button (full library
// sweep) AND the per-card sync chip on outdated cards.
async function _refetchAndQueueClipFromGithub(id, token) {
  // v225v4.102: instrument every silent-return path so the next debug
  // log pins down exactly where the Sync GitHub flow bails. The user
  // reported "the button clicks but nothing happens" — no bg-queue
  // start, no sync-absorb, no visible feedback. Possible causes:
  // missing gitRef, malformed repoUrl, /api/extract/url 4xx/5xx,
  // network error. Each gets its own dlog frame.
  const _slog = (msg, payload) => {
    if (typeof _dlog === "function") _dlog("github-sync", msg, payload || {});
  };
  _slog("refetch start", { id, hasToken: !!token });
  const clip = await getClip(id);
  if (!clip) {
    _slog("bail: clip not in IDB", { id });
    return false;
  }
  if (!clip.gitRef) {
    _slog("bail: clip has no gitRef", { id, title: clip.title });
    return false;
  }
  if (!clip.gitRef.repoUrl) {
    _slog("bail: gitRef.repoUrl missing", { id, gitRef: clip.gitRef });
    return false;
  }
  if (!clip.gitRef.path) {
    _slog("bail: gitRef.path missing", { id, gitRef: clip.gitRef });
    return false;
  }
  const { repoUrl, branch, path } = clip.gitRef;
  const m = repoUrl.match(/github\.com\/([^/]+)\/([^/]+)/);
  if (!m) {
    _slog("bail: repoUrl doesn't match github pattern", { id, repoUrl });
    return false;
  }
  const owner = m[1];
  const repo = m[2];
  const rawUrl =
    `https://raw.githubusercontent.com/${owner}/${repo}/${branch || "main"}/${encodeURI(path)}`;
  _slog("fetching from extract API", {
    id, owner, repo, branch: branch || "main", path,
  });
  let res;
  try {
    res = await fetch("/api/extract/url", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        url: rawUrl,
        github_token: token || undefined,
        // No git_sha here — we WANT the latest, not a pinned version.
      }),
    });
  } catch (netErr) {
    _slog("bail: fetch threw (network)", { id, error: String(netErr) });
    throw netErr;  // let outer catch surface to user
  }
  if (!res.ok) {
    let body = "";
    try { body = (await res.text()).slice(0, 240); } catch {}
    _slog("bail: extract API returned non-OK", {
      id, status: res.status, body,
    });
    return false;
  }
  const data = await res.json();
  _slog("extract OK, enqueuing bg-synth", {
    id, textLen: (data.text || "").length, hasGitRef: !!data.gitRef,
  });
  // Drop it into the background queue. _bgRunWorker will pick it
  // up, _preSynthesizeChapter will overwrite the existing clip
  // because targetClipId is set.
  //
  // v4.58 (#846): preserve the clip's existing voice on refetch.
  // This path's intent is "the source moved, redo the narration" —
  // voice is not part of what changed. Previously _enqueueBg fell
  // back to voiceEl.value (current picker), which silently swapped
  // the voice whenever the user had changed their default picker
  // since the clip was originally narrated. Fall back to picker
  // ONLY for legacy clips that predate voice provenance (v219).
  _enqueueBg([{
    title: clip.title,
    text: (data.text || "").trim(),
    targetClipId: clip.id,
    gitRef: data.gitRef || clip.gitRef,
    voiceId: clip.voiceId || voiceEl.value,
    voiceName:
      clip.voiceName ||
      (voiceEl.selectedOptions[0]?.textContent || voiceEl.value || ""),
    speakerId:
      typeof clip.speakerId === "number"
        ? clip.speakerId
        : (speakerRow.hidden ? null : Number(speakerEl.value || 0)),
    rate: typeof clip.rate === "number" ? clip.rate : Number(rateEl.value),
    volume:
      typeof clip.volume === "number"
        ? clip.volume
        : Number(volumeEl.value) / 100,
  }]);
  return true;
}

async function renarrateAllOutdated() {
  if (!_outdatedClipIds || _outdatedClipIds.size === 0) return;
  const token = getGithubToken();
  if (!token) {
    setStatus("Set a GitHub PAT in Settings before re-narrating.", true);
    return;
  }
  if (!voiceEl.value) {
    setStatus("Pick a voice before re-narrating.", true);
    return;
  }
  // Snapshot so the iteration is stable even if the worker drops
  // entries from the set as each re-narrate lands.
  const ids = Array.from(_outdatedClipIds);
  libraryRenarrateOutdatedBtn.disabled = true;
  const originalLabel = libraryRenarrateOutdatedBtn.textContent;
  libraryRenarrateOutdatedBtn.textContent = "Refetching…";
  let enqueued = 0;
  let failed = 0;
  for (let i = 0; i < ids.length; i++) {
    const id = ids[i];
    setStatus(`Refetching ${i + 1}/${ids.length} outdated clips…`);
    try {
      const ok = await _refetchAndQueueClipFromGithub(id, token);
      if (ok) enqueued++; else failed++;
    } catch (err) {
      console.warn("[renarrate] failed for clip", id, err);
      failed++;
    }
  }
  libraryRenarrateOutdatedBtn.disabled = false;
  libraryRenarrateOutdatedBtn.textContent = originalLabel;
  const tail = failed
    ? ` (${failed} couldn't be refetched)`
    : "";
  if (enqueued === 0) {
    setStatus(`No clips could be refetched.${tail}`, true);
  } else {
    setStatus(
      `Queued ${enqueued} re-narrate${enqueued === 1 ? "" : "s"} — watch the queue panel for progress.${tail}`
    );
  }
}
if (libraryRenarrateOutdatedBtn) {
  libraryRenarrateOutdatedBtn.addEventListener("click", renarrateAllOutdated);
}

// Returns the id of the clip that should play after `fromId` ends, or null
// if we're at the end of the queue (or shuffle has no other clips). Walks
// the same sort order the user sees in the library.
// v225.tn90 (#572): pre-cache the next-up clip's audio while we're
// playing the current one. Cheap insurance against a mid-row signal
// drop on a train or plane. Only fetches when the clip has an
// audioSha256 pointer but no local Blob; never fetches if we're
// offline (the call would just fail). Best-effort — failures are
// swallowed since this is purely opportunistic.
async function _precacheClipAudio(clipId) {
  if (!clipId || _isOffline()) return;
  try {
    const clip = await getClip(clipId);
    if (!clip) return;
    // Already have a local Blob? Nothing to do.
    if (clip.audio && clip.audio instanceof Blob && clip.audio.size > 0) return;
    if (!clip.audioSha256) return;
    const url = `/api/library/audio/${clip.audioSha256}.mp3`;
    const res = await fetch(url);
    if (!res.ok) return;
    const blob = await res.blob();
    if (!blob || blob.size === 0) return;
    // Atomic write so we don't race with any other clip mutation.
    const db = await openDB();
    const tx = db.transaction(STORE, "readwrite");
    const store = tx.objectStore(STORE);
    const cur = await idbReq(store.get(clipId));
    if (!cur) return;
    cur.audio = blob;
    await idbReq(store.put(cur));
    await new Promise((resolve, reject) => {
      tx.oncomplete = resolve;
      tx.onerror = () => reject(tx.error);
      tx.onabort = () => reject(tx.error);
    });
  } catch (err) {
    console.info("[precache] next-clip audio fetch failed:", err);
  }
}

async function nextClipId(fromId) {
  let clips;
  try {
    clips = await listClips();
  } catch {
    return null;
  }
  if (!clips.length) return null;

  // v225v3.58 (#791): auto-advance must skip ebook clips. They have no
  // audio blob; loading one mid-advance "jumps" the user to an ebook
  // they didn't ask to open and silently kills the audio session.
  // Filter at the source so both shuffle and sequential branches see
  // only playable candidates. Same predicate used in loadClip's
  // _isEbookClip detection — kind === "ebook" is the canonical
  // signal (set by _openAsEbook + synced through v3.53 schema).
  // Companion to the 🎧 Audio / 📖 Ebooks library split below — both
  // changes treat ebook clips as a separate class from audio.
  const playable = clips.filter((c) => c && c.kind !== "ebook");
  if (!playable.length) return null;

  if (_playMode === "shuffle") {
    const others = playable.filter((c) => c.id !== fromId);
    if (!others.length) return null;
    return others[Math.floor(Math.random() * others.length)].id;
  }

  const ordered = sortClips(playable, _playMode);
  const idx = ordered.findIndex((c) => c.id === fromId);
  if (idx < 0 || idx + 1 >= ordered.length) return null;
  return ordered[idx + 1].id;
}

// A clip is "in progress" when its saved resume position is past the very
// first second AND not basically at the end. Matches the same threshold
// formatClipMeta uses to decide whether to render the "1:23 / 5:00" string.
function isClipInProgress(clip) {
  const p = Number(clip.progressSec) || 0;
  const d = Number(clip.durationSec) || 0;
  return p > 1 && p < d - 1;
}

// ---- Cover swatch helpers ----------------------------------------------
// Deterministic visual identity for clip cards. djb2-hash the title to
// two HSL hues, then build a 135° gradient between them. The first
// letter (or 1-2 characters) sits on top in semi-transparent white.
// Same title → same swatch on every render and every device, which
// makes the library scannable even with a hundred entries.

function _djb2Hash(str) {
  let h = 5381;
  for (let i = 0; i < str.length; i++) {
    h = (h * 33) ^ str.charCodeAt(i);
  }
  return h >>> 0;
}

function _clipSwatchGradient(title) {
  const t = (title || "untitled").trim() || "untitled";
  const h = _djb2Hash(t);
  // Two hues 30-90° apart for visible-but-harmonious gradients.
  const hue1 = h % 360;
  const hue2 = (hue1 + 30 + (Math.floor(h / 360) % 60)) % 360;
  return `linear-gradient(135deg, hsl(${hue1} 55% 45%), hsl(${hue2} 60% 35%))`;
}

// Accent color for the card's Libby-style background tint. Prefers the
// dominant color extracted from an uploaded cover; falls back to a
// title-hash-derived HSL so even un-covered clips have a per-title
// identity color. Returns {h, s, l} in HSL (h: 0-360, s/l: 0-100).
function _clipAccentColor(clip) {
  if (clip && clip.cover && clip.cover.color) return clip.cover.color;
  const h = _djb2Hash(((clip && clip.title) || "untitled").trim() || "untitled");
  return { h: h % 360, s: 55, l: 45 };
}

// v220as: short relative-time helper for the "Last synced: 5 min ago"
// line on git-sourced library cards. Returns small strings tuned for
// glanceability — "just now" → "5 min ago" → "2 hr ago" → "yesterday"
// → "3 days ago" → date. Returns empty string on bad/missing input
// so callers can `if (text) append(...)`.
function _formatTimeAgo(isoOrMs) {
  if (!isoOrMs) return "";
  const t = typeof isoOrMs === "number" ? isoOrMs : Date.parse(isoOrMs);
  if (Number.isNaN(t)) return "";
  const diffMs = Date.now() - t;
  if (diffMs < 0) return "just now";
  const sec = Math.floor(diffMs / 1000);
  if (sec < 45) return "just now";
  const min = Math.floor(sec / 60);
  if (min < 60) return `${min} min ago`;
  const hr = Math.floor(min / 60);
  if (hr < 24) return `${hr} hr ago`;
  const day = Math.floor(hr / 24);
  if (day === 1) return "yesterday";
  if (day < 7) return `${day} days ago`;
  // Older than a week — show the date so the user doesn't have to
  // count "37 days ago" in their head.
  return new Date(t).toLocaleDateString();
}

function _clipSwatchInitial(title) {
  const t = (title || "").trim();
  if (!t) return "·";
  // Use the first 1-2 letters of the first word, skipping leading
  // chapter-numbering noise like "01 - " or "Chapter 1: ".
  const cleaned = t
    .replace(/^chapter\s+\w+[:.\s-]*/i, "")
    .replace(/^\d+\s*[-—.]\s*/, "")
    .trim();
  const ch = (cleaned || t).match(/\p{L}/u);
  return ch ? ch[0].toUpperCase() : t[0].toUpperCase();
}

function makeClipCard(clip) {
  const item = document.createElement("div");
  const isSelected = _librarySelectedIds.has(clip.id);
  const isOutdated = _outdatedClipIds.has(clip.id);
  // v220as: three sync states — queued (in bg-queue, not yet running),
  // syncing-now (this is the active job), idle (default). Used both
  // for the .syncing-* card classes (CSS pulse + border accent) and
  // for the inline status chip rendered just below the title row.
  const isSyncingNow = _bgSyncingActiveClipId === clip.id;
  const isSyncingQueued =
    !isSyncingNow && _bgSyncingClipIds.has(clip.id);
  // v4.61 (#844): if this card is the active sync AND we've already
  // received at least one sentence event for it, mark the card so
  // the CSS picks the determinate progress bar over the indeterminate
  // comet. The CSS variable carries the 0..1 fraction; CSS does
  // `width: calc(var(--clip-progress) * 100%)`.
  const hasSyncProgress =
    isSyncingNow
    && _bgSyncProgress.clipId === clip.id
    && _bgSyncProgress.fraction > 0;
  item.className =
    "clip" +
    (clip.id === _currentClipId ? " current" : "") +
    (_libraryMultiSelect && isSelected ? " selected" : "") +
    (isOutdated ? " outdated" : "") +
    (isSyncingNow ? " syncing-now" : "") +
    (isSyncingQueued ? " syncing-queued" : "") +
    (hasSyncProgress ? " has-sync-progress" : "");
  // Stamp the clip id onto the DOM node so the drag-commit pass can read
  // the visual order without looking anything up.
  item.dataset.clipId = String(clip.id);
  // v4.61 (#844): restore the in-flight progress fraction onto the
  // freshly rendered card so a re-render mid-sync (filter change,
  // tag toggle, sort flip) doesn't reset the bar to 0.
  if (hasSyncProgress) {
    item.style.setProperty(
      "--clip-progress",
      String(_bgSyncProgress.fraction),
    );
  }
  // Libby-style per-card accent (v125). Derived from the uploaded
  // cover's dominant color, or the title-hash if no cover. Two CSS
  // custom properties: --clip-accent (solid for borders if needed)
  // and --clip-accent-tint (10% alpha for the soft background wash).
  const accent = _clipAccentColor(clip);
  item.style.setProperty(
    "--clip-accent",
    `hsl(${accent.h} ${accent.s}% ${accent.l}%)`
  );
  item.style.setProperty(
    "--clip-accent-tint",
    `hsl(${accent.h} ${accent.s}% ${accent.l}% / 0.12)`
  );

  // In select mode the drag-handle slot is repurposed for a checkbox.
  // Reorder doesn't make sense during a selection pass — the user is
  // either committing to delete / export or cancelling out.
  let leftCell;
  if (_libraryMultiSelect) {
    leftCell = document.createElement("div");
    leftCell.className = "clip-select-checkbox";
    leftCell.textContent = isSelected ? "☑" : "☐";
    leftCell.setAttribute(
      "aria-label",
      isSelected ? "Deselect this clip" : "Select this clip"
    );
    // No listener here — the whole card toggles selection (see below).
  } else {
    leftCell = document.createElement("div");
    // Drag-to-reorder is a power-user feature; hide the grip in Simple
    // mode so casual readers don't see clutter for an interaction they
    // wouldn't use. The drag handler is wired anyway — harmless on a
    // hidden element.
    leftCell.className = "clip-drag advanced-only";
    leftCell.setAttribute("aria-label", "Drag to reorder");
    leftCell.title = "Drag to reorder";
    // Two stacked vertical ellipses render reliably as a "grip" affordance
    // across iOS / Android / Windows fonts.
    leftCell.textContent = "⋮⋮";
    _attachDragHandle(leftCell, item);
  }

  const playBtn = document.createElement("button");
  playBtn.className = "clip-play";
  playBtn.type = "button";
  playBtn.setAttribute("aria-label", `Play ${clip.title}`);
  // Show the full title on hover (desktop) / long-press (mobile) for
  // when the clamped 2-line title doesn't show the whole thing.
  if (clip.title) playBtn.title = clip.title;
  // Visual identity swatch — Hoopla-style cover-art tile. If the user
  // uploaded a cover (v125), render that as a background image. Otherwise
  // fall back to the title-hash gradient so every card still has an
  // identity. Object URLs created here are tracked on the card so they
  // can be revoked when the library re-renders (see below).
  const swatch = document.createElement("span");
  swatch.className = "clip-swatch";
  swatch.setAttribute("aria-hidden", "true");
  // v225g12 (#700): use _coverImgSrc so the swatch renders for ebook
  // clips (cover saved as a data-URL string) the same as for custom
  // uploads (cover saved as { blob }).
  const _swatchCover = _coverImgSrc(clip.cover);
  if (_swatchCover) {
    swatch.style.backgroundImage = `url("${_swatchCover.url}")`;
    if (_swatchCover.revoke) swatch.dataset.coverUrl = _swatchCover.url;
    swatch.classList.add("has-cover");
  } else {
    swatch.style.background = _clipSwatchGradient(clip.title || "");
    swatch.textContent = _clipSwatchInitial(clip.title || "");
  }
  const titleStack = document.createElement("span");
  titleStack.className = "clip-title-stack";
  // v220o: title moved to its own row at the top of the card (see
  // _libraryTitleTop below). The inline titleEl that used to live
  // here got crushed to invisible width on cards with the full action
  // strip (↺ + Cover 🔄 ✎ ×) — tester reported "no title visible."
  // titleStack now carries only the note + indicators.
  //
  // v220u: dropped the meta line entirely. Tester reported "2." on
  // a card — that was the start of "2,500w · 18:42 · 5/30" getting
  // CSS-clipped to invisibility by the same narrow-width pressure
  // that killed the title in v220o. The duration moved into the
  // title row (next to voice) where there's actual room; word count
  // + date are gone from the card surface — Edit dialog still has
  // them if anyone wants the detail.
  playBtn.append(swatch, titleStack);

  // v220as: sync status line (REMOVED in v4.88).
  //
  // History:
  //   v220as added a .clip-sync-status pill with two states:
  //     - "Syncing now…" (active) — removed in v4.87 once the bottom-
  //       edge progress bar (v4.85/v4.86) carried that signal cleanly
  //     - "Queued — N ahead" (queued) — removed in v4.88 per user
  //       request; the dim amber .clip.syncing-queued outline alone
  //       conveys "waiting in queue" without the extra pill chrome
  //
  // If queue position info is wanted back in the future, do it as a
  // numeric badge on the 🔄 chip ("🔄 #3") rather than reviving the
  // amber text pill that competed for space with the cover swatch.

  // If the user added a note, render it as a small italic line below
  // the standard meta. Keeps the card a single tap-target.
  if (clip.note && clip.note.trim()) {
    const noteEl = document.createElement("span");
    noteEl.className = "clip-note";
    noteEl.textContent = clip.note.trim();
    titleStack.appendChild(noteEl);
  }
  // v225fo (#658): notes indicator relocated. Used to render here
  // inside titleStack (next to the cover swatch) but the "📝 Notes"
  // label kept overflowing onto the +Cover chip on cards with short
  // play buttons. Moved to the lastSyncFooter strip below where it
  // shares the bottom row with "Synced · N ago" — both are clip-
  // metadata signals that belong on the low-chrome footer, not
  // crammed against the play button. See lastSyncFooter construction
  // further down.
  // Tag chips. Each chip carries the tag-hash color as a left border so
  // the same tag is always the same color across cards. Inside the play
  // button so a single tap still loads the clip (no nested interactives).
  if (Array.isArray(clip.tags) && clip.tags.length > 0) {
    const tagsRow = document.createElement("span");
    tagsRow.className = "clip-tags";
    for (const tag of clip.tags) {
      const chip = document.createElement("span");
      chip.className = "clip-tag";
      chip.textContent = tag;
      chip.style.borderColor = _tagColor(tag);
      tagsRow.appendChild(chip);
    }
    titleStack.appendChild(tagsRow);
  }

  // v220as: "Last synced: N min ago" on git-sourced clips. Saved by
  // the saveClip block during re-narrate (or on initial import once
  // we backfill). Quiet dim-color line — metadata, not the headline —
  // but answers the question "is this audio current?" without a
  // round-trip to GitHub. Skipped when isSyncingNow is true so the
  // active "Syncing now…" line isn't undercut by stale timing.
  //
  // v221.tn8-fixme: built here but appended to `item` AT THE END as a
  // full-width strip across the card's bottom edge instead of being
  // tucked inside titleStack. Old placement got crushed on narrow
  // cards with multiple action chips; new placement reads at a glance
  // and matches the card's footer-strip pattern.
  //
  // v223.tn17 (#486): the footer now picks the most-recent of two
  // distinct sync sources and labels accordingly:
  //   • lastSyncedAt    → GitHub re-pull (only set on git-sourced)
  //   • lastDeviceSyncAt → cross-device library sync absorb
  // Whichever is newer wins the label. Footer shows for ANY clip with
  // either timestamp — previously gated to git-sourced clips, which
  // meant the cross-device freshness signal had nowhere to land.
  // v225fo (#658): footer is now a flex row carrying two clip-metadata
  // signals — the notes badge (📝) on the LEFT and the sync timestamp
  // on the RIGHT. The notes badge is created if clip.notes has content,
  // independent of whether a sync timestamp exists, so cards with notes
  // but no sync metadata still get the footer strip.
  let lastSyncFooter = null;
  let syncText = null;
  let syncTitle = null;
  if (!isSyncingNow && !isSyncingQueued) {
    const ghAt = clip.lastSyncedAt || null;
    const devAt = clip.lastDeviceSyncAt || null;
    let chosenAt = null;
    let label = null;
    if (ghAt && devAt) {
      if (ghAt >= devAt) { chosenAt = ghAt; label = "GitHub"; }
      else               { chosenAt = devAt; label = "Synced"; }
    } else if (ghAt) {
      chosenAt = ghAt; label = "GitHub";
    } else if (devAt) {
      chosenAt = devAt; label = "Synced";
    }
    if (chosenAt) {
      const rel = _formatTimeAgo(chosenAt);
      if (rel) {
        syncText = `${label} · ${rel}`;
        syncTitle = new Date(chosenAt).toLocaleString();
      }
    }
  }
  const hasNotes = !!(clip.notes && clip.notes.trim());
  if (syncText || hasNotes) {
    lastSyncFooter = document.createElement("div");
    lastSyncFooter.className = "clip-last-synced";
    if (hasNotes) {
      const notesSpan = document.createElement("span");
      notesSpan.className = "clip-last-synced-notes";
      notesSpan.textContent = "📝 Notes";
      notesSpan.title = "This clip has notes attached";
      lastSyncFooter.appendChild(notesSpan);
    } else {
      // Empty placeholder so the sync text aligns right consistently
      // whether or not the card has notes.
      const spacer = document.createElement("span");
      spacer.className = "clip-last-synced-notes is-empty";
      lastSyncFooter.appendChild(spacer);
    }
    if (syncText) {
      const syncSpan = document.createElement("span");
      syncSpan.className = "clip-last-synced-text";
      syncSpan.textContent = syncText;
      if (syncTitle) syncSpan.title = syncTitle;
      lastSyncFooter.appendChild(syncSpan);
    }
  }

  // v220as (bug #416): partial-synth warning. If the silent-sentence
  // counter from saveClip is > 0, the user has a clip whose SHA shows
  // "in sync" but a few sentences play as silence. Surface it as a
  // small ⚠ chip so the user can re-narrate manually. Tap-through
  // intentionally still plays the clip — they may want to verify
  // which sentences are affected.
  if (
    !isSyncingNow &&
    !isSyncingQueued &&
    typeof clip.synthSilentSentenceCount === "number" &&
    clip.synthSilentSentenceCount > 0
  ) {
    const warnEl = document.createElement("span");
    warnEl.className = "clip-partial-synth-warn";
    const n = clip.synthSilentSentenceCount;
    warnEl.textContent = `⚠ ${n} silent sentence${n === 1 ? "" : "s"}`;
    warnEl.title =
      `Synthesis completed but ${n} sentence${n === 1 ? "" : "s"} ` +
      `produced no audio (Piper's text frontend rejected the input). ` +
      `Re-narrate to retry, or edit those sentences to remove the ` +
      `failing punctuation/markup.`;
    titleStack.appendChild(warnEl);
  }
  // In select mode, tapping the card toggles selection — playing a clip
  // mid-bulk-action would be confusing.
  playBtn.addEventListener("click", () => {
    if (_libraryMultiSelect) {
      if (_librarySelectedIds.has(clip.id)) {
        _librarySelectedIds.delete(clip.id);
      } else {
        _librarySelectedIds.add(clip.id);
      }
      // Disarm the bulk delete confirm whenever the selection changes —
      // otherwise the count under "Tap again to delete N" could be stale.
      _disarmBulkDelete();
      _updateMultiSelectCounts();
      renderLibrary();
      return;
    }
    // v221.tn14: clicking the same card's swatch toggles play/pause
    // instead of re-loading. Tester reported re-clicking instinctively
    // to stop playback (Spotify / Apple Music / Audible all behave this
    // way). loadClip would reset the playhead state machine, which
    // wastes the user's resume position and feels like a glitch.
    //
    // Branching:
    //   - same clip currently loaded AND playing  → pause in place
    //   - same clip loaded AND paused             → resume (no reload)
    //   - different clip OR no clip loaded        → loadClip as before
    if (clip.id === _currentClipId) {
      if (!playerEl.paused) {
        playerEl.pause();
      } else {
        playerEl.play().catch(() => {});
      }
      return;
    }
    // v589: on phone, load silently. Author feedback: card taps were
    // starting playback unexpectedly. The bottom-bar play button is
    // right there — user decides when to start. Desktop keeps the
    // tap-loads-and-plays behavior since the click is more deliberate.
    const _isPhone = window.matchMedia("(max-width: 767px)").matches;
    loadClip(clip.id, { autoPlay: !_isPhone });
  });

  // Reset-to-start ↺ — shown only for clips that actually have a resume
  // position to wipe. Reading my book chapters back as I revise: I want
  // to restart from the top after editing the manuscript, not pick up
  // mid-paragraph from the version I heard last.
  const showReset = isClipInProgress(clip);
  let resetBtn = null;
  if (showReset) {
    resetBtn = document.createElement("button");
    resetBtn.className = "clip-reset";
    resetBtn.type = "button";
    resetBtn.setAttribute("aria-label", `Reset ${clip.title} to start`);
    resetBtn.title = "Reset to start";
    // Anticlockwise open circle arrow — the universal "reset" glyph.
    resetBtn.textContent = "↺";
    resetBtn.addEventListener("click", async (e) => {
      e.stopPropagation();
      await resetClipProgress(clip.id);
    });
  }

  // v220n: Re-narrate chip. One-tap re-render with the voice currently
  // picked in the hero (which may differ from the clip's stored voice —
  // exactly the case after picking a new narrator and wanting to redo
  // old clips). Placed before Edit so it's reachable with thumb on
  // mobile without skipping past delete.
  //
  // v220q: pulses while the regen is in flight so the user knows it's
  // working. State lives in _renarratingClipIds; cleared by the
  // v225fb (#644): per-card ↻ syncBtn removed.
  //
  // Previously this chip was the "refetch from GitHub + re-narrate"
  // affordance on outdated cards. v225ey added an outdated banner
  // attached to the bottom of the same cards with a prominent
  // "Refetch + re-narrate" button — same action, more discoverable
  // copy. User reported the two icons (↻ sync chip + 🔄 re-narrate
  // chip) read as the same action because both are circular arrows
  // sitting next to each other in the row.
  //
  // Removing the chip makes the surface unambiguous:
  //   - Banner button "Refetch + re-narrate" → pulls fresh text + re-narrates
  //   - Row chip 🔄                          → re-narrates existing text
  //
  // The variable name is kept (as `null`) so the row-append code below
  // doesn't need to change — it already handles null entries.
  const syncBtn = null;

  // v225ey: per-card outdated banner. The desktop banner only fires
  // when an outdated clip is the currently-loaded one; testers asked
  // for the same affordance attached to every outdated card in the
  // library so they don't have to load each one to see it. Same
  // handlers as the desktop banner: Refetch → _refetchAndQueueClipFromGithub
  // (which queues a bg-sync that overwrites the clip in place,
  // preserving bookmarks / annotations / highlights). Dismiss drops
  // the clip from _outdatedClipIds — session-scoped, matches the
  // desktop banner's dismiss semantics.
  let outdatedFooter = null;
  if (isOutdated && clip.gitRef && clip.gitRef.repoUrl) {
    outdatedFooter = document.createElement("div");
    outdatedFooter.className = "clip-outdated-footer";
    const msg = document.createElement("span");
    msg.className = "clip-outdated-msg";
    // Two-part copy mirrors the desktop banner: bold lead + soft tail
    // so the eye lands on "Updated on GitHub" first.
    const lead = document.createElement("strong");
    lead.textContent = "Updated on GitHub.";
    const tail = document.createTextNode(" Re-narrate with the latest commit?");
    msg.appendChild(lead);
    msg.appendChild(tail);
    const actions = document.createElement("span");
    actions.className = "clip-outdated-actions";
    const refetchBtn = document.createElement("button");
    refetchBtn.type = "button";
    refetchBtn.className = "clip-outdated-btn primary";
    refetchBtn.textContent = "Refetch + re-narrate";
    refetchBtn.addEventListener("click", async (e) => {
      e.stopPropagation();
      // v225v4.102: every silent-bail now alerts() AND dlogs, because
      // #status is display:none on this user's desktop (CSS rule fires
      // even outside phone case) so setStatus() is invisible. The
      // alert() forces visible feedback so the user can't tap the
      // button and see literally nothing happen.
      const _slog = (msg, payload) => {
        if (typeof _dlog === "function") _dlog("github-sync", msg, payload || {});
      };
      _slog("refetchBtn clicked", {
        clipId: clip.id, title: clip.title,
        hasGitRef: !!clip.gitRef,
        gitRefRepoUrl: clip.gitRef ? clip.gitRef.repoUrl : null,
      });
      const token = getGithubToken();
      if (!token) {
        _slog("bail: no GitHub token saved", { clipId: clip.id });
        alert("Sync GitHub failed: no GitHub PAT saved.\n\n" +
              "Open Settings → Account → GitHub credentials and paste a " +
              "Personal Access Token. Then tap Refetch again.");
        setStatus("Set a GitHub PAT in Settings before syncing.", true);
        return;
      }
      if (!voiceEl.value) {
        _slog("bail: no voice selected", { clipId: clip.id });
        alert("Sync GitHub failed: no voice selected.\n\n" +
              "Pick a voice from the voice picker, then tap Refetch again.");
        setStatus("Pick a voice before syncing.", true);
        return;
      }
      refetchBtn.disabled = true;
      try {
        const ok = await _refetchAndQueueClipFromGithub(clip.id, token);
        if (ok) {
          // v225v3.24: mirror the in-view banner's instant-hide on
          // confirm (line 24420). Once the user has queued the
          // refetch, both the card footer AND any main-view banner
          // showing for this clip should clear immediately — even
          // before the bg-queue synth finishes — so the user sees
          // their tap registered.
          _markClipFresh(clip.id);
          _slog("queued for re-narrate", {
            clipId: clip.id, title: clip.title,
          });
          alert(`Queued "${clip.title}" for re-narrate.\n\n` +
                `The bg-queue panel will show progress. ` +
                `The reading view will update when synth completes.`);
          setStatus(
            `Queued ${clip.title} for re-narrate — watch the queue panel.`,
          );
        } else {
          _slog("queue returned false", { clipId: clip.id });
          alert(`Couldn't refetch "${clip.title}" from GitHub.\n\n` +
                `Check the debug log for the bail reason ` +
                `(category: github-sync).`);
          setStatus(`Couldn't refetch ${clip.title} from GitHub.`, true);
          refetchBtn.disabled = false;
        }
      } catch (err) {
        _slog("threw", {
          clipId: clip.id, error: String(err && err.message || err),
        });
        console.warn("[outdated-banner] per-card refetch failed:", err);
        alert(`Sync failed: ${err.message}`);
        setStatus(_withOfflineHint(`Sync failed: ${err.message}`), true);
        refetchBtn.disabled = false;
      }
    });
    const dismissBtn = document.createElement("button");
    dismissBtn.type = "button";
    dismissBtn.className = "clip-outdated-btn";
    dismissBtn.textContent = "Dismiss";
    dismissBtn.setAttribute("aria-label", "Dismiss");
    dismissBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      // Session-only dismissal: drop from the outdated set + re-render
      // so the card returns to its normal state (no ↻ badge, no sync
      // chip, no banner). On next library reload the freshness check
      // may re-flag it if the SHA still differs upstream. Routed
      // through _markClipFresh so the main-view banner clears too if
      // it happens to be showing for this clip.
      _markClipFresh(clip.id);
      renderLibrary();
    });
    actions.appendChild(refetchBtn);
    actions.appendChild(dismissBtn);
    outdatedFooter.appendChild(msg);
    outdatedFooter.appendChild(actions);
  }

  // v220az: per-card 🔄 chip. Reads from _bgSyncingClipIds (the bg-queue
  // signal) instead of _renarratingClipIds (now dead — the foreground
  // re-narrate path it tracked has been removed). Whole-card pulse via
  // .syncing-now/.syncing-queued classes is the dominant visual cue;
  // .busy here just keeps the chip-level color-shift for users who
  // notice it.
  const renarrateBtn = document.createElement("button");
  renarrateBtn.className = "clip-renarrate";
  const _renarrateInFlight = _bgSyncingClipIds.has(clip.id);
  if (_renarrateInFlight) {
    renarrateBtn.classList.add("busy");
  }
  renarrateBtn.type = "button";
  // v4.58 (#846): the chip's contract changed. Short-tap = reuse the
  // clip's own voice (the most common case — "the audio sounds stale
  // because I just edited the text, give me fresh narration in the
  // SAME voice"). Long-press = override with the current voice picker
  // (the rare case — "I'm intentionally swapping voices on this
  // clip"). Reflect both in the aria-label + tooltip.
  renarrateBtn.setAttribute(
    "aria-label",
    `Re-narrate ${clip.title} in this clip's voice (long-press for current voice picker)`
  );
  renarrateBtn.title = _renarrateInFlight
    ? "Re-narrating in the background…"
    : "Re-narrate (in the background) — tap: same voice · long-press: current picker";
  renarrateBtn.textContent = "🔄";

  // Long-press detection via Pointer Events. ~500ms threshold matches
  // the platform convention (Android context-menu / iOS tap-and-hold).
  // We set _longPressed inside the timer and check it in the click
  // handler to suppress the synthetic click that follows a long-press.
  let _lpTimer = null;
  let _longPressed = false;
  const LP_MS = 500;
  const _cancelLongPress = () => {
    if (_lpTimer) {
      clearTimeout(_lpTimer);
      _lpTimer = null;
    }
  };
  renarrateBtn.addEventListener("pointerdown", (e) => {
    _longPressed = false;
    _cancelLongPress();
    _lpTimer = setTimeout(() => {
      _longPressed = true;
      _lpTimer = null;
      // Fire immediately on the long-press threshold so the user gets
      // feedback without having to release. Stop the chip from being
      // re-tappable until the queue acks via _bgSyncingClipIds.
      _libraryRenarrate(clip.id, { usePickerVoice: true });
    }, LP_MS);
  });
  // Any movement that turns the press into a drag, or a cancel
  // event (scroll, touch-leave), aborts the long-press timer.
  renarrateBtn.addEventListener("pointermove", _cancelLongPress);
  renarrateBtn.addEventListener("pointercancel", _cancelLongPress);
  renarrateBtn.addEventListener("pointerleave", _cancelLongPress);
  renarrateBtn.addEventListener("pointerup", _cancelLongPress);
  renarrateBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    // If the long-press timer already fired, swallow the click —
    // otherwise we'd re-narrate twice (once with picker, once with
    // clip voice).
    if (_longPressed) {
      _longPressed = false;
      return;
    }
    _libraryRenarrate(clip.id);
  });
  // Right-click on desktop = also "use picker voice" (mirror the
  // long-press semantic for mouse users who don't long-click).
  renarrateBtn.addEventListener("contextmenu", (e) => {
    e.preventDefault();
    e.stopPropagation();
    _cancelLongPress();
    _libraryRenarrate(clip.id, { usePickerVoice: true });
  });

  const editBtn = document.createElement("button");
  editBtn.className = "clip-edit";
  editBtn.type = "button";
  editBtn.setAttribute("aria-label", `Edit ${clip.title}`);
  editBtn.title = "Edit title + note";
  // Pencil glyph (U+270E) — renders consistently on Windows, macOS, iOS, Android.
  editBtn.textContent = "✎";
  editBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    openClipEdit(clip.id);
  });

  const delBtn = document.createElement("button");
  delBtn.className = "clip-delete";
  delBtn.type = "button";
  delBtn.setAttribute("aria-label", `Delete ${clip.title}`);
  delBtn.textContent = "×";
  delBtn.addEventListener("click", async (e) => {
    e.stopPropagation();
    await deleteClipById(clip.id);
    renderLibrary();
  });

  // v150: "+ Cover" affordance — only rendered for clips that don't
  // have an uploaded cover yet. Cover upload was previously invisible
  // unless the user opened ✎ Edit and scrolled to the right row;
  // testers never knew the feature existed. The button is a quiet
  // dashed-border chip (low chrome) that opens Edit dialog and
  // scrolls the cover picker into view.
  let addCoverBtn = null;
  if (!clip.cover || !clip.cover.blob) {
    addCoverBtn = document.createElement("button");
    addCoverBtn.className = "clip-add-cover";
    addCoverBtn.type = "button";
    addCoverBtn.setAttribute("aria-label", `Add cover image to ${clip.title}`);
    addCoverBtn.title = "Add a cover image";
    addCoverBtn.textContent = "+ Cover";
    addCoverBtn.addEventListener("click", (e) => {
      e.stopPropagation();
      openClipEdit(clip.id);
      // Let the dialog finish rendering, then nudge the cover picker
      // into view + focus so the user lands exactly at the next step.
      setTimeout(() => {
        const coverPick = document.getElementById("clip-edit-cover-pick");
        if (coverPick) {
          coverPick.scrollIntoView({ behavior: "smooth", block: "center" });
          coverPick.focus();
        }
      }, 120);
    });
  }

  // v220o: title row at top of the card, styled like the + Cover
  // chip (small, semibold, slight tracking, dim color). Clickable —
  // tapping the title loads the clip same as tapping the body.
  // The whole card is now flex-column: title row above, existing
  // body row below.
  //
  // v220p: title row now also carries the clip's voice name on the
  // right. Most useful signal during the narrator-audition cleanup
  // — at a glance you can see which clips were generated with the
  // old voice (Alan / Amy) vs the new one (LibriTTS spkr 7).
  const titleTop = document.createElement("button");
  titleTop.className = "clip-title-top";
  titleTop.type = "button";
  titleTop.setAttribute("aria-label", `Play ${clip.title}`);
  const titleText = document.createElement("span");
  titleText.className = "clip-title-top-text";
  titleText.textContent = clip.title || "(untitled)";
  titleTop.appendChild(titleText);
  // v220u: duration in the title row, just left of the voice. The
  // bottom meta line used to carry word count · duration · date, but
  // the action strip squeezed it to one-character clipping ("2.").
  // Title row has room for the one signal that actually helps the
  // user decide whether to play it now — duration. Resume-position
  // (`1:23 / 5:00`) renders for in-progress clips.
  // v225g1 (#690): ebook clips have no duration → show a "📖 Ebook"
  // pill in the same slot so the row still has a strong glance signal
  // about what kind of clip it is. Falls back to duration for normal
  // audio clips (and to nothing for clips that haven't synth'd yet).
  if (clip.kind === "ebook" || (!clip.durationSec && !clip.blob)) {
    const badge = document.createElement("span");
    badge.className = "clip-title-top-ebook";
    badge.textContent = "📖 Ebook";
    badge.title = "No audio yet — tap to read; tap Generate later to add audio.";
    titleTop.appendChild(badge);
  } else if (clip.durationSec) {
    const durSpan = document.createElement("span");
    durSpan.className = "clip-title-top-duration";
    const progress = Number(clip.progressSec) || 0;
    if (progress > 1 && progress < clip.durationSec - 1) {
      durSpan.textContent = `${formatTime(progress)} / ${formatTime(clip.durationSec)}`;
    } else {
      durSpan.textContent = formatTime(clip.durationSec);
    }
    titleTop.appendChild(durSpan);
  }
  if (clip.voiceName) {
    const voiceSpan = document.createElement("span");
    voiceSpan.className = "clip-title-top-voice";
    // v220bd: route through the shared display helper so this matches
    // the hero voice chip exactly — "Alan (en_GB, medium)" → "Alan".
    // Falls through "LibriTTS · high · spkr 7" → "LibriTTS" because
    // the helper handles both separator styles. Speaker id stays on
    // as a trailing #N suffix when the voice has multiple speakers.
    const shortVoice = _displayVoiceName(clip.voiceName);
    const speakerSuffix = (typeof clip.speakerId === "number" && clip.speakerId > 0)
      ? ` #${clip.speakerId}` : "";
    voiceSpan.textContent = shortVoice + speakerSuffix;
    voiceSpan.title = clip.voiceName; // full name still visible on hover
    titleTop.appendChild(voiceSpan);
  }
  // v225eu: active-card repeat badge. The chip in the player is global —
  // when it's on, the badge marks WHICH card the loop currently applies
  // to (i.e. the one playing). Disappears for off, glyph matches the
  // chip so the connection reads at a glance.
  if (
    clip.id === _currentClipId &&
    typeof _repeatMode !== "undefined" &&
    _repeatMode !== "off"
  ) {
    const badge = document.createElement("span");
    badge.className = "clip-title-top-repeat";
    badge.textContent = _repeatMode === "one" ? "🔂" : "🔁";
    badge.title =
      _repeatMode === "one"
        ? "Looping this clip (tap the 🔂 chip in the player to cycle off)"
        : "Repeating all clips";
    badge.setAttribute("aria-label", badge.title);
    titleTop.appendChild(badge);
  }
  titleTop.addEventListener("click", (e) => {
    if (_libraryMultiSelect) {
      // Same toggle-selection behavior as tapping the body.
      if (_librarySelectedIds.has(clip.id)) {
        _librarySelectedIds.delete(clip.id);
      } else {
        _librarySelectedIds.add(clip.id);
      }
      _disarmBulkDelete();
      _updateMultiSelectCounts();
      renderLibrary();
    } else {
      // v589: same gate as the card-body click. Phone loads silently.
      const _isPhone = window.matchMedia("(max-width: 767px)").matches;
      loadClip(clip.id, { autoPlay: !_isPhone });
    }
  });

  // Inner row holds the handle / swatch / meta / actions — was the
  // entire card's children pre-v220o. Wrapping lets the card grow
  // a second row (the title above) without breaking flex layout.
  const row = document.createElement("div");
  row.className = "clip-row";

  // In select mode, hide the per-clip action buttons — bulk delete /
  // export live in the tools row instead. Just checkbox + body.
  // v220al: syncBtn slots in just before renarrateBtn so the order on
  // outdated cards is [↺ reset?] + [+ Cover?] + [↻ sync] [🔄 re-narrate] [✎] [×].
  // Keeps the sync chip adjacent to the re-narrate chip since they're
  // related (sync = "fresh text + re-narrate", re-narrate = "current
  // text + re-narrate").
  if (_libraryMultiSelect) {
    row.append(leftCell, playBtn);
  } else if (resetBtn) {
    const tail = [resetBtn, addCoverBtn, syncBtn, renarrateBtn, editBtn, delBtn].filter(Boolean);
    row.append(leftCell, playBtn, ...tail);
  } else {
    const tail = [addCoverBtn, syncBtn, renarrateBtn, editBtn, delBtn].filter(Boolean);
    row.append(leftCell, playBtn, ...tail);
  }
  item.append(titleTop, row);
  // v221.tn9: append the "Last synced N min ago" strip as the last
  // child so it spans the card's full width across the bottom edge.
  // Previously lived inside titleStack (inside the play button), where
  // it was vulnerable to the same width-crush that v220u dropped the
  // meta line for. Full-width footer reads cleanly even on the
  // narrowest mobile breakpoint.
  if (lastSyncFooter) item.append(lastSyncFooter);
  // v225ey: outdated banner is the absolute last child so it's the
  // most prominent thing at the bottom edge — testers should see it
  // on a quick scroll past the card.
  if (outdatedFooter) item.append(outdatedFooter);
  return item;
}

// v220q: clips currently being re-narrated from a library card click.
// makeClipCard reads this set and applies the .busy class to the 🔄
// chip, which pulses via CSS. Cleared from the saveClip().then() path
// in generate() once the new audio lands; safety timeout below clears
// it if something goes wrong silently.
const _renarratingClipIds = new Set();
function _clearRenarrating(clipId) {
  if (!_renarratingClipIds.has(clipId)) return;
  _renarratingClipIds.delete(clipId);
  renderLibrary();
}

// v220as: any clip ID that's queued or actively synth'ing through the
// bg-queue with a targetClipId set. Distinct from _renarratingClipIds
// (which only tracks the per-card 🔄 chip path) — this covers Sync
// GitHub bulk + per-card ↻ Sync chip + Re-narrate outdated. The
// library card uses this to render a "Syncing…" status badge so the
// user can SEE which clip is being processed during a silent bg-queue
// run (previous bug: invisible state caused "I cancelled but Narrative
// thinks chapter_00 is in sync"). Three states per clip:
//   - in set + this id === _bgSyncingActiveClipId   → "Syncing…" + pulse
//   - in set                                        → "Queued"
//   - not in set                                    → idle
let _bgSyncingActiveClipId = null;
const _bgSyncingClipIds = new Set();
function _bgMarkSyncing(clipId) {
  if (!clipId) return;
  _bgSyncingClipIds.add(clipId);
  if (typeof renderLibrary === "function") renderLibrary();
}
function _bgUnmarkSyncing(clipId) {
  if (!clipId) return;
  const changed = _bgSyncingClipIds.delete(clipId);
  if (_bgSyncingActiveClipId === clipId) _bgSyncingActiveClipId = null;
  // v4.61 (#844): also drop progress state so a re-render after the
  // job finishes doesn't repaint a stale 0.94 fill on the next card
  // that happens to enter syncing-now.
  if (_bgSyncProgress.clipId === clipId) {
    _bgSyncProgress = { clipId: null, fraction: 0 };
  }
  if (changed && typeof renderLibrary === "function") renderLibrary();
}
function _bgSetSyncingActive(clipId) {
  _bgSyncingActiveClipId = clipId || null;
  // v4.61 (#844): new sync target → reset progress so the previous
  // job's final fraction doesn't briefly flash on the new card.
  _bgSyncProgress = { clipId: null, fraction: 0 };
  if (typeof renderLibrary === "function") renderLibrary();
}

// v4.61 (#844): per-clip sync progress for the library card bar.
// Tracks the most recently observed sentence/total pair from the SSE
// stream so renderLibrary can stamp the same value back on the card
// when it re-renders (e.g. after the user changes filters mid-sync).
// `clipId === null` means "no progress yet" — the card falls back to
// the indeterminate comet animation in that case.
let _bgSyncProgress = { clipId: null, fraction: 0 };

// Imperative paint: called from the SSE sentence handler so the live
// card advances on every sentence without round-tripping through
// renderLibrary (which would relayout the whole list 200 times for
// a long chapter). renderLibrary handles the steady-state case where
// the card re-renders for an unrelated reason (filter change, tab
// switch) — it reads _bgSyncProgress and re-applies the class + var.
function _paintBgSyncProgressOnCard(clipId, sentence, total) {
  if (!clipId || !total || total <= 0) return;
  const fraction = Math.max(0, Math.min(1, sentence / total));
  _bgSyncProgress = { clipId, fraction };
  // querySelector scoped to the active library list — the card lives
  // under .clip with data-clip-id stamped by renderLibrary. Returns
  // null if the user happens to have the library closed; that's fine,
  // the next renderLibrary will re-apply from _bgSyncProgress.
  const card = document.querySelector(
    `.clip[data-clip-id="${CSS.escape(String(clipId))}"]`
  );
  if (!card) return;
  card.classList.add("has-sync-progress");
  card.style.setProperty("--clip-progress", String(fraction));
}

// v220n: re-narrate a library clip with the current voice picker state,
// even if it differs from the clip's stored voice. Use case: user picks
// a new narrator (e.g., LibriTTS speaker 7) and wants to redo the
// existing 11 Alan / Amy clips one by one.
//
// loadClip() overwrites the picker with the clip's stored voice, so we
// snapshot the user's preferred voice/speaker BEFORE loading and
// restore it AFTER. Then trigger the existing v200 regen machinery.
//
// v220r: synchronous re-entrancy guard. _synthController isn't set
// until generate() runs — there's a window during `await loadClip`
// where two rapid taps could BOTH proceed and end up calling
// generate() twice (= two SSE streams producing the same audio).
// User reported "double of the new voice + pause stops and goes" —
// classic two-parallel-streams symptom. Use a separate flag set
// synchronously at function entry.
async function _libraryRenarrate(clipId, opts) {
  // v220az: route the per-card 🔄 chip through the silent bg-queue
  // instead of the foreground synth path.
  //
  // Previous behavior (v220s/v220w): tapped chip → paused current
  // playback → swapped textarea content → called generate() in the
  // foreground. User reported: "I was listening to chapter 0 and
  // tapped re-narrate on chapter 1 — playback stopped and the text
  // window jumped to chapter 1." That's broken: the wand chip is a
  // LIBRARY action; the player should never be touched by a library
  // interaction.
  //
  // Bg-queue path gives us the right semantics for free:
  //   - player stays bound to whatever's playing
  //   - textarea stays untouched
  //   - the v220as "Syncing now…" badge appears on the target card
  //   - saveClip's targetClipId-aware path overwrites the clip in
  //     place, preserving bookmarks/notes/tags/cover
  //   - the new audio replaces the old on disk; if the user happens
  //     to be listening to the SAME clip mid-re-narrate, their
  //     current playerEl.src stays bound to the old blob URL until
  //     they next load the clip — no audio glitch
  //
  // v4.58 (#846): voice-source is now explicit. Default behavior is
  // "preserve the clip's existing voice" — short-tapping 🔄 just
  // refreshes the audio with whatever voice the clip was last
  // narrated with. This was the user's mental model all along:
  // "I keep re-narrating with the wrong voice when I want to reuse
  // my current voice." Previously the chip always used voiceEl.value
  // (the picker), so changing your default voice silently swapped
  // every subsequent re-narrate. Now it doesn't.
  //
  // Pass { usePickerVoice: true } to opt INTO the old behavior —
  // either via long-press on the chip (escape hatch when you DO
  // want to swap voices) or via the Voice Apply picker (whose whole
  // purpose is "apply the current picker voice to these clips").
  if (!clipId) return;
  const usePickerVoice = !!(opts && opts.usePickerVoice);

  // Skip re-taps on a clip that's already in the queue or being
  // synth'd. _bgSyncingClipIds is the canonical "this clip has work
  // in flight" signal (populated by _enqueueBg, drained by the
  // worker on success or cancel).
  if (_bgSyncingClipIds.has(clipId)) {
    setStatus(`Already re-narrating that clip — watch the queue panel.`);
    return;
  }

  let clip;
  try {
    clip = await getClip(clipId);
  } catch (e) {
    setStatus(_withOfflineHint(`Re-narrate failed: ${e.message}`), true);
    return;
  }
  if (!clip || !clip.text) {
    setStatus("Couldn't read that clip's text.", true);
    return;
  }

  // Pick the voice source. Default = clip's existing voice; picker
  // is the explicit opt-in.
  const clipHasVoice = !!clip.voiceId;
  const wantPicker = usePickerVoice || !clipHasVoice;
  if (wantPicker && !voiceEl.value) {
    setStatus("Pick a voice before re-narrating.", true);
    return;
  }

  // Build the per-job voice snapshot. _enqueueBg's fallback logic
  // (line ~12837) only fires for missing fields, so explicit values
  // here are honored.
  const voiceId = wantPicker ? voiceEl.value : clip.voiceId;
  const voiceName = wantPicker
    ? (voiceEl.selectedOptions[0]?.textContent || voiceEl.value || "")
    : (clip.voiceName || clip.voiceId || "");
  const speakerId = wantPicker
    ? (speakerRow.hidden ? null : Number(speakerEl.value || 0))
    : (typeof clip.speakerId === "number" ? clip.speakerId : null);
  const rate = wantPicker
    ? Number(rateEl.value)
    : (typeof clip.rate === "number" ? clip.rate : Number(rateEl.value));
  const volume = wantPicker
    ? Number(volumeEl.value) / 100
    : (typeof clip.volume === "number" ? clip.volume : Number(volumeEl.value) / 100);

  _enqueueBg([{
    title: clip.title,
    text: clip.text,
    targetClipId: clip.id,
    gitRef: clip.gitRef || null,
    voiceId,
    voiceName,
    speakerId,
    rate,
    volume,
  }]);

  const voiceLabelRaw = voiceName || voiceId || "the current voice";
  const voiceLabel = _displayVoiceName(voiceLabelRaw) || voiceLabelRaw;
  const source = wantPicker ? "current picker voice" : "this clip's voice";
  setStatus(
    `Re-narrating "${clip.title}" in the background with ${voiceLabel} ` +
    `(${source}) — keep listening.`
  );
}

async function resetClipProgress(id) {
  try {
    // v223.tn19 (#488): atomic so concurrent absorb can't lose annotations.
    const clip = await _mutateClipAtomic(id, (c) => {
      c.progressSec = 0;
      // Manual reset means "I want this back in my listening queue" — clear
      // playedAt so the Hide-played filter shows it again.
      c.playedAt = null;
    });
    if (!clip) return;
    // If the user is hitting reset on the clip they're currently listening
    // to, rewind the player itself too — otherwise the IndexedDB row says
    // 0 but the audio keeps playing from where it was.
    if (_currentClipId === id) {
      try { playerEl.currentTime = 0; } catch {}
    }
    renderLibrary();
    setStatus(`Reset "${clip.title || "clip"}" to start.`);
  } catch (e) {
    console.warn("reset progress failed:", e);
    setStatus(_withOfflineHint(`Reset failed: ${e.message}`), true);
  }
}

// ---- Drag-to-reorder (Pointer Events) -----------------------------------
// Works for both mouse and touch via the unified Pointer Events API. The
// pointerdown handler captures the pointer so move/up events keep firing
// even if the user drags outside the original handle. On drop, we figure
// out where the card landed by walking its sibling clip cards top-to-
// bottom and looking for the first one whose vertical midpoint is BELOW
// the dragged card's midpoint.

let _dragSession = null; // {cardEl, pointerId, startY}

// v168: first-clip tour banner. Once-per-device, shown above the
// library list as soon as the user has at least one clip on file.
// Connects three discoverability surfaces in a single banner —
// covers (✎ Edit), drag-to-reorder, and the 📝 Notes chip — at the
// moment the user has a clip those features apply to.
const FIRST_CLIP_TOUR_KEY = "narrative.firstClipTourSeen";
// v175: separate flag for the confetti burst so it stays once-only
// even if the tour banner is re-dismissed or cleared. Cleared by the
// Settings "Replay onboarding tips" link (along with the tour flag).
const FIRST_CLIP_CONFETTI_KEY = "narrative.firstClipConfettiSeen";
function _isFirstClipTourSeen() {
  try { return localStorage.getItem(FIRST_CLIP_TOUR_KEY) === "1"; } catch { return false; }
}
function _dismissFirstClipTour() {
  try { localStorage.setItem(FIRST_CLIP_TOUR_KEY, "1"); } catch {}
  const el = document.getElementById("first-clip-tour");
  if (el) el.hidden = true;
}
// v175: track previous clip count across renderLibrary calls so we
// can detect the 0 → ≥1 transition. -1 sentinel = "first call this
// session, no transition info yet" — used to suppress confetti on
// page load with existing clips (returning user shouldn't celebrate
// every reload). Only the genuine 0 → 1 jump fires confetti.
let _lastSeenClipCount = -1;
function _updateFirstClipTour(clipCount) {
  const el = document.getElementById("first-clip-tour");
  if (!el) return;
  el.hidden = _isFirstClipTourSeen() || clipCount <= 0;

  // v175 / v178: confetti burst on the user's first ever clip save.
  // Two gates:
  // 1. Transition gate: prev === 0 AND new >= 1. Page-init calls
  //    arrive with prev === -1 and are ignored regardless of count
  //    (a returning user with 5 clips doesn't re-celebrate). The
  //    only path that satisfies prev === 0 is "user started this
  //    session empty, just saved their first clip."
  // 2. One-shot gate: localStorage flag. Once fired, never again
  //    (unless cleared by Settings → Replay onboarding tips).
  // v178: log every evaluation so a "confetti didn't pop" report has
  // diagnosis-ready entries showing which gate blocked the fire.
  const prev = _lastSeenClipCount;
  _lastSeenClipCount = clipCount;
  let confettiSeen = false;
  try {
    confettiSeen = localStorage.getItem(FIRST_CLIP_CONFETTI_KEY) === "1";
  } catch {}
  const transitionFires = prev === 0 && clipCount >= 1;
  if (transitionFires && !confettiSeen) {
    _dlog("confetti", `FIRE — first clip transition`, {
      prev, clipCount, confettiSeen,
    });
    try { localStorage.setItem(FIRST_CLIP_CONFETTI_KEY, "1"); } catch {}
    _playConfetti();
  } else if (transitionFires && confettiSeen) {
    _dlog("confetti", "skip — transition fires but flag already set", {
      prev, clipCount, flagKey: FIRST_CLIP_CONFETTI_KEY,
    });
  } else if (clipCount >= 1 && !confettiSeen) {
    // Most common "why didn't it pop?" cause: user upgraded to v175
    // with clips already on file, so prev jumps from -1 directly to
    // their existing count and the transition gate is impossible to
    // satisfy. Log it so the debug view surfaces the diagnosis.
    _dlog("confetti", "skip — no 0→≥1 transition (gate blocked)", {
      prev, clipCount, confettiSeen, hint: "use Settings → Replay onboarding tips to test"
    });
  }
}

// v175: lightweight canvas confetti — no dependency, ~140 paper
// rectangles falling from the top with gravity + drag + per-particle
// rotation. Fires once on the 0 → ≥1 clip transition. Respects
// prefers-reduced-motion (skips entirely). High-DPI canvas scaling
// via devicePixelRatio so it's crisp on retina screens. Particles
// auto-clean up after 4.5s — the canvas removes itself when the
// last particle is either offscreen or fully faded.
function _playConfetti() {
  // Accessibility: users who've asked for reduced motion get no
  // surprise animation. The tour banner still appears as their
  // first-clip cue.
  try {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  } catch {}
  // Don't stack bursts — if one is already mid-flight, leave it.
  if (document.getElementById("confetti-canvas")) return;

  const canvas = document.createElement("canvas");
  canvas.id = "confetti-canvas";
  canvas.setAttribute("aria-hidden", "true");
  const dpr = window.devicePixelRatio || 1;
  const W = window.innerWidth;
  const H = window.innerHeight;
  canvas.width = W * dpr;
  canvas.height = H * dpr;
  canvas.style.cssText =
    "position:fixed;inset:0;width:100%;height:100%;" +
    "pointer-events:none;z-index:9999;";
  document.body.appendChild(canvas);
  const ctx = canvas.getContext("2d");
  ctx.scale(dpr, dpr);

  // Accent-palette-aligned colors. The blue matches the app accent;
  // the other five give the burst variety without going garish.
  const COLORS = ["#6ea8fe", "#ffb86c", "#ff6b6b", "#a78bfa", "#34d399", "#fbbf24"];
  const COUNT = 140;
  const GRAVITY = 0.18;
  const DRAG = 0.003;
  const LIFETIME_MS = 4500;
  const FADE_FRACTION = 0.7; // start fading at 70% of lifetime

  // Spawn from the top — slightly biased toward center so the burst
  // reads as coming from "the page" rather than the edges. vy is
  // gentle (1.5-4.5) so they drift down rather than fall like rocks.
  const particles = [];
  for (let i = 0; i < COUNT; i++) {
    particles.push({
      x: W / 2 + (Math.random() - 0.5) * (W * 0.6),
      y: -20 - Math.random() * 80,
      vx: (Math.random() - 0.5) * 8,
      vy: 1.5 + Math.random() * 3,
      angle: Math.random() * Math.PI * 2,
      angVel: (Math.random() - 0.5) * 0.3,
      color: COLORS[(Math.random() * COLORS.length) | 0],
      w: 5 + Math.random() * 5,
      h: 9 + Math.random() * 6,
    });
  }

  const start = performance.now();
  let rafId = 0;
  function frame(now) {
    const elapsed = now - start;
    ctx.clearRect(0, 0, W, H);
    let alive = false;
    const fadeStart = LIFETIME_MS * FADE_FRACTION;
    const alphaFromElapsed = elapsed > fadeStart
      ? Math.max(0, 1 - (elapsed - fadeStart) / (LIFETIME_MS * (1 - FADE_FRACTION)))
      : 1;
    for (const p of particles) {
      p.vy += GRAVITY;
      p.vx -= p.vx * DRAG;
      p.x += p.vx;
      p.y += p.vy;
      p.angle += p.angVel;
      if (alphaFromElapsed > 0 && p.y < H + 50) {
        alive = true;
        ctx.save();
        ctx.globalAlpha = alphaFromElapsed;
        ctx.translate(p.x, p.y);
        ctx.rotate(p.angle);
        ctx.fillStyle = p.color;
        ctx.fillRect(-p.w / 2, -p.h / 2, p.w, p.h);
        ctx.restore();
      }
    }
    if (alive && elapsed < LIFETIME_MS) {
      rafId = requestAnimationFrame(frame);
    } else {
      cancelAnimationFrame(rafId);
      canvas.remove();
    }
  }
  rafId = requestAnimationFrame(frame);
}
const _firstClipTourDismissBtn = document.getElementById("first-clip-tour-dismiss");
if (_firstClipTourDismissBtn) {
  _firstClipTourDismissBtn.addEventListener("click", _dismissFirstClipTour);
}

// v149: one-time drag-to-reorder hint. Sits inside the library
// dialog and appears the first time the user has 2+ clips. Dismissed
// permanently on either the × button click or the user's first
// successful drag (set in _onDragEnd).
const DRAG_HINT_KEY = "narrative.dragHintDismissed";
function _isDragHintDismissed() {
  try { return localStorage.getItem(DRAG_HINT_KEY) === "1"; } catch { return false; }
}
function _dismissDragHint() {
  try { localStorage.setItem(DRAG_HINT_KEY, "1"); } catch {}
  const el = document.getElementById("drag-hint");
  if (el) el.hidden = true;
}
function _updateDragHint(clipCount) {
  const el = document.getElementById("drag-hint");
  if (!el) return;
  el.hidden = _isDragHintDismissed() || clipCount < 2;
}
const _dragHintDismissBtn = document.getElementById("drag-hint-dismiss");
if (_dragHintDismissBtn) {
  _dragHintDismissBtn.addEventListener("click", _dismissDragHint);
}

function _attachDragHandle(handle, cardEl) {
  handle.addEventListener("pointerdown", (e) => {
    // Ignore non-primary buttons (right-click etc).
    if (e.button !== 0 && e.button !== undefined && e.pointerType === "mouse") {
      return;
    }
    e.preventDefault();
    try { handle.setPointerCapture(e.pointerId); } catch {}

    _dragSession = {
      cardEl,
      pointerId: e.pointerId,
      startY: e.clientY,
    };
    cardEl.classList.add("dragging");

    handle.addEventListener("pointermove", _onDragMove);
    handle.addEventListener("pointerup", _onDragEnd);
    handle.addEventListener("pointercancel", _onDragEnd);
  });
}

function _onDragMove(e) {
  if (!_dragSession || e.pointerId !== _dragSession.pointerId) return;
  e.preventDefault();
  const dy = e.clientY - _dragSession.startY;
  _dragSession.cardEl.style.transform = `translateY(${dy}px)`;
}

async function _onDragEnd(e) {
  if (!_dragSession || e.pointerId !== _dragSession.pointerId) return;
  const { cardEl } = _dragSession;
  const handle = e.currentTarget;
  try { handle.releasePointerCapture(e.pointerId); } catch {}
  handle.removeEventListener("pointermove", _onDragMove);
  handle.removeEventListener("pointerup", _onDragEnd);
  handle.removeEventListener("pointercancel", _onDragEnd);

  // Where did the card visually land? Snapshot rect BEFORE we reset the
  // transform so it reflects the dragged position.
  const draggedRect = cardEl.getBoundingClientRect();
  const draggedMid = draggedRect.top + draggedRect.height / 2;

  cardEl.style.transform = "";
  cardEl.classList.remove("dragging");
  _dragSession = null;
  // v149: first successful drag = user discovered the feature, kill
  // the hint banner forever.
  if (!_isDragHintDismissed()) _dismissDragHint();

  // Find first sibling whose midpoint is below ours — that's the insertion
  // point. Only consider cards in the SAME parent (so the drag is bounded
  // by the section the card started in).
  const parent = cardEl.parentNode;
  const siblings = Array.from(parent.children).filter(
    (c) => c !== cardEl && c.classList.contains("clip")
  );
  let insertBefore = null;
  for (const sib of siblings) {
    const r = sib.getBoundingClientRect();
    const mid = r.top + r.height / 2;
    if (draggedMid < mid) {
      insertBefore = sib;
      break;
    }
  }

  if (insertBefore) {
    parent.insertBefore(cardEl, insertBefore);
  } else {
    parent.appendChild(cardEl);
  }

  await _commitDragOrder();
}

async function _commitDragOrder() {
  // Walk the WHOLE library list (across both sections), record the visual
  // order of clip ids, persist to localStorage. We then re-render to make
  // sure the sectioned view is in the right shape — if a clip was dragged
  // across the Continue Listening / Other Clips boundary, the section
  // partition needs to re-run.
  const clipEls = Array.from(libraryList.querySelectorAll(".clip[data-clip-id]"));
  const order = clipEls.map((el) => Number(el.dataset.clipId)).filter(Number.isFinite);
  _saveLibraryOrder(order);

  // Switching to "custom" mode is the cleanest way to signal to the user
  // that their drag took effect — and it makes the sort consistent with
  // what they just dropped into place.
  if (_playMode !== "custom") {
    _playMode = "custom";
    try { localStorage.setItem(PLAY_MODE_KEY, _playMode); } catch {}
    updatePlayModeBtn();
  }

  renderLibrary();
}

// v225v3.59 (#791): re-pointable target so renderLibrary can route
// section headers into the Audio panel vs the Ebook panel. Default
// is the legacy library-list element for any callers outside the
// renderLibrary flow.
let _sectionHeaderTarget = null;
function _appendSectionHeader(label, subtitle) {
  const target = _sectionHeaderTarget || libraryList;
  const h = document.createElement("div");
  h.className = "library-section";
  h.textContent = label;
  target.appendChild(h);
  // v168: optional one-line subtitle under the section header. Used
  // to explain "Continue listening" to anyone who arrives at a
  // library that's been auto-split into two sections and doesn't
  // know why. Other sections just pass null and skip it.
  if (subtitle) {
    const sub = document.createElement("div");
    sub.className = "library-section-subtitle";
    sub.textContent = subtitle;
    target.appendChild(sub);
  }
}

// v225v3.59 (#791): library tab/panel state + handlers.
const LIBRARY_ACTIVE_KIND_KEY = "narrative.libraryActiveKind";
let _libraryActiveKind =
  localStorage.getItem(LIBRARY_ACTIVE_KIND_KEY) === "ebook" ? "ebook" : "audio";

function _libraryUpdateTabCounts(audioCount, ebookCount) {
  const a = document.getElementById("lib-tab-count-audio");
  const e = document.getElementById("lib-tab-count-ebook");
  if (a) a.textContent = String(audioCount);
  if (e) e.textContent = String(ebookCount);
}

function _librarySetActiveKind(kind, opts = {}) {
  kind = kind === "ebook" ? "ebook" : "audio";
  if (kind === _libraryActiveKind && !opts.force) return;
  _libraryActiveKind = kind;
  try { localStorage.setItem(LIBRARY_ACTIVE_KIND_KEY, kind); } catch {}
  const panels = document.getElementById("library-panels");
  if (panels) {
    if (opts.noAnim) panels.classList.add("no-anim");
    panels.dataset.active = kind;
    if (opts.noAnim) {
      // Re-enable animation on the next frame so future switches slide.
      requestAnimationFrame(() => {
        requestAnimationFrame(() => panels.classList.remove("no-anim"));
      });
    }
  }
  const tabA = document.getElementById("lib-tab-audio");
  const tabE = document.getElementById("lib-tab-ebook");
  if (tabA) {
    tabA.classList.toggle("is-active", kind === "audio");
    tabA.setAttribute("aria-selected", kind === "audio" ? "true" : "false");
  }
  if (tabE) {
    tabE.classList.toggle("is-active", kind === "ebook");
    tabE.setAttribute("aria-selected", kind === "ebook" ? "true" : "false");
  }
}

// Wire tab clicks + initial state. Runs once at module load.
(function _wireLibraryTabs() {
  const tabA = document.getElementById("lib-tab-audio");
  const tabE = document.getElementById("lib-tab-ebook");
  if (tabA) tabA.addEventListener("click", () => _librarySetActiveKind("audio"));
  if (tabE) tabE.addEventListener("click", () => _librarySetActiveKind("ebook"));
  // Apply persisted state with animation suppressed so the dialog
  // doesn't slide at first paint.
  _librarySetActiveKind(_libraryActiveKind, { noAnim: true, force: true });
})();

// Phone-only swipe-to-switch on the panel viewport. Tracks horizontal
// drag, follows the finger with a partial transform, and snaps to the
// next/previous panel on release if the drag crossed a threshold.
// Desktop ignores swipe — only the tabs work there.
(function _wireLibrarySwipe() {
  const viewport = document.getElementById("library-viewport");
  if (!viewport) return;
  const isPhone = () =>
    window.matchMedia && window.matchMedia("(max-width: 767px)").matches;
  let startX = 0, startY = 0, dragging = false, dx = 0;
  const SLIDE_THRESHOLD = 60; // px past which we commit a switch
  const ANGLE_GUARD = 1.2;    // require horizontal-dominant motion

  viewport.addEventListener("touchstart", (e) => {
    if (!isPhone()) return;
    if (e.touches.length !== 1) return;
    startX = e.touches[0].clientX;
    startY = e.touches[0].clientY;
    dragging = true;
    dx = 0;
  }, { passive: true });

  viewport.addEventListener("touchmove", (e) => {
    if (!dragging) return;
    const t = e.touches[0];
    const ax = Math.abs(t.clientX - startX);
    const ay = Math.abs(t.clientY - startY);
    // First-move arbitration: if the user's gesture is vertical-
    // dominant, abandon — they're scrolling the panel content.
    if (ax < 8 && ay < 8) return;
    if (ay * ANGLE_GUARD > ax) {
      dragging = false;
      return;
    }
    dx = t.clientX - startX;
    // Bound dx so we don't slide off into never-land at the edges.
    const panels = document.getElementById("library-panels");
    if (!panels) return;
    panels.classList.add("no-anim");
    // base offset depends on current active kind: 0 (audio) or -50% (ebook)
    const baseOffset = _libraryActiveKind === "ebook" ? -50 : 0;
    // Convert dx into a percentage of viewport width so it matches the
    // 200%-wide panels container. 1 viewport width = 50% of container.
    const vw = viewport.clientWidth || 1;
    const extra = (dx / vw) * 50; // dx px → % of panels
    panels.style.transform = `translateX(${baseOffset + extra}%)`;
  }, { passive: true });

  viewport.addEventListener("touchend", () => {
    if (!dragging) return;
    dragging = false;
    const panels = document.getElementById("library-panels");
    if (!panels) return;
    panels.classList.remove("no-anim");
    panels.style.transform = ""; // clear inline, let data-active CSS take over
    if (Math.abs(dx) >= SLIDE_THRESHOLD) {
      // Negative dx = finger went left = reveal panel to the right.
      const nextKind = dx < 0 ? "ebook" : "audio";
      _librarySetActiveKind(nextKind);
    }
    // Below threshold = snap back to current kind via the existing
    // CSS transform — no further action needed.
    dx = 0;
  }, { passive: true });

  viewport.addEventListener("touchcancel", () => {
    if (!dragging) return;
    dragging = false;
    const panels = document.getElementById("library-panels");
    if (panels) {
      panels.classList.remove("no-anim");
      panels.style.transform = "";
    }
    dx = 0;
  }, { passive: true });
})();

// Build + render the tag-filter chip row above the library list.
//   allClips      — for the universe of tag chips to show
//   visibleClips  — for the count badge on each chip
// Side effect: prunes _libraryTagFilter of tags no clip carries anymore.
function _renderTagFilterRow(allClips, visibleClips) {
  if (!libraryTagFilters) return;
  // Collect distinct tags across all clips. Use an order-preserving
  // map so the chip order is stable: alphabetical, but ties broken by
  // first-appearance order in the library (which already follows the
  // user's sort).
  const allTags = new Set();
  for (const c of allClips) {
    if (Array.isArray(c.tags)) {
      for (const t of c.tags) allTags.add(t);
    }
  }
  // Prune stale filters.
  for (const t of _libraryTagFilter) {
    if (!allTags.has(t)) _libraryTagFilter.delete(t);
  }
  if (allTags.size === 0) {
    libraryTagFilters.hidden = true;
    libraryTagFilters.innerHTML = "";
    return;
  }
  libraryTagFilters.hidden = false;
  libraryTagFilters.innerHTML = "";

  // Per-tag count against the visible (post-search) set, so users
  // don't get "draft (12)" when only 2 of those 12 match the search.
  const counts = new Map();
  for (const c of visibleClips) {
    if (Array.isArray(c.tags)) {
      for (const t of c.tags) counts.set(t, (counts.get(t) || 0) + 1);
    }
  }

  const sorted = [...allTags].sort();
  for (const tag of sorted) {
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = "library-tag-chip";
    const isActive = _libraryTagFilter.has(tag);
    if (isActive) chip.classList.add("active");
    chip.style.borderColor = _tagColor(tag);
    const n = counts.get(tag) || 0;
    chip.textContent = `${tag} · ${n}`;
    chip.setAttribute(
      "aria-pressed",
      isActive ? "true" : "false"
    );
    chip.addEventListener("click", () => {
      if (_libraryTagFilter.has(tag)) _libraryTagFilter.delete(tag);
      else _libraryTagFilter.add(tag);
      renderLibrary();
    });
    libraryTagFilters.appendChild(chip);
  }

  // "Clear" link appears only when a filter is active.
  if (_libraryTagFilter.size > 0) {
    const clear = document.createElement("button");
    clear.type = "button";
    clear.className = "library-tag-clear";
    clear.textContent = "Clear";
    clear.addEventListener("click", () => {
      _libraryTagFilter.clear();
      renderLibrary();
    });
    libraryTagFilters.appendChild(clear);
  }
}

async function renderLibrary() {
  // v221.sync-5: fire a debounced pull so a phone rendering the
  // library will pick up any clips a desktop synth'd since last
  // pull. Doesn't await — render shows current IndexedDB state
  // immediately; the pull writes deltas and triggers a re-render
  // via its own renderLibrary() call when it lands new clips.
  if (typeof _syncPullDebounced === "function") _syncPullDebounced();

  let clips = [];
  try {
    clips = await listClips();
  } catch (e) {
    console.warn("library read failed:", e);
  }
  // v149: track whether any clip exists so _updateEmptyState can
  // hide the first-run starter card the moment the user has even
  // one clip in their library.
  _libraryHasClips = clips.length > 0;
  _updateEmptyState();
  // v149: drag-to-reorder discovery hint inside the library dialog.
  // Show only when there are 2+ clips (sorting one is meaningless)
  // and the user hasn't already dismissed or used the feature.
  _updateDragHint(clips.length);
  // v168: first-clip tour banner — bridges Edit / drag / Notes
  // discoverability the moment any clip lands in the library.
  _updateFirstClipTour(clips.length);
  // Snapshot the unfiltered list before sort/filter mutations so the tag
  // filter row can show every tag that exists (not just ones surviving
  // the current search). Prune _libraryTagFilter of any tag that no
  // clip carries anymore — otherwise a user who deletes the last
  // "draft" clip would see "0 clips with tag: draft" forever.
  const allClips = clips.slice();
  const totalCount = clips.length;
  // Revoke any cover object URLs from the previous render before we
  // wipe the DOM — each card's swatch may have created one. Without
  // this, repeated renderLibrary() calls slowly leak blob references.
  libraryList
    .querySelectorAll(".clip-swatch[data-cover-url]")
    .forEach((s) => {
      try { URL.revokeObjectURL(s.dataset.coverUrl); } catch {}
    });
  libraryList.innerHTML = "";
  // Library trigger badge in the hero. Shows total clip count, or
  // hides when the library is empty so first-time users see a clean
  // hero without a "0" sitting there.
  if (libraryTriggerCount) {
    if (totalCount > 0) {
      libraryTriggerCount.textContent = String(totalCount);
      libraryTriggerCount.hidden = false;
    } else {
      libraryTriggerCount.hidden = true;
    }
  }
  if (totalCount === 0) {
    // Empty-state stub — the dialog still opens, but the user gets a
    // friendly nudge instead of staring at a blank panel.
    const empty = document.createElement("div");
    empty.className = "library-empty";
    empty.textContent =
      "No clips yet — generate one or import a previous library zip.";
    libraryList.appendChild(empty);
    return;
  }

  // Show "Sync GitHub" only when at least one clip in the library has a
  // gitRef — no point offering it on a Tom Sawyer-only library.
  const hasGitClips = clips.some(
    (c) => c.gitRef && c.gitRef.repoUrl && c.gitRef.path
  );
  librarySyncGithubBtn.hidden = !hasGitClips;
  // v176: "Re-narrate outdated" surfaces only after Sync has actually
  // flagged something. Reading from the _outdatedClipIds Set keeps the
  // button honest — if a user re-imported a clip via another path, it
  // drops out of the set and the button hides.
  if (libraryRenarrateOutdatedBtn) {
    const outdatedCount = _outdatedClipIds ? _outdatedClipIds.size : 0;
    libraryRenarrateOutdatedBtn.hidden = outdatedCount === 0;
    libraryRenarrateOutdatedBtn.textContent =
      outdatedCount > 0
        ? `Re-narrate outdated (${outdatedCount})`
        : "Re-narrate outdated";
  }

  // "All bookmarks" only earns a slot in the tools row once there's at
  // least one bookmark somewhere — otherwise it's a dead button.
  const hasAnyBookmark = clips.some(
    (c) => Array.isArray(c.bookmarks) && c.bookmarks.length > 0
  );
  libraryAllBookmarksBtn.hidden = !hasAnyBookmark;

  // Sort first, then filter — that way the visible order matches what
  // auto-advance will play next.
  clips = sortClips(clips, _playMode);

  // "Hide played" filter — drop clips that have a playedAt stamp AND are
  // no longer in progress. In-progress clips (Continue Listening) stay
  // visible even if previously finished, since the user is replaying.
  if (_hidePlayed) {
    clips = clips.filter((c) => {
      const progress = Number(c.progressSec) || 0;
      const wasPlayed = !!c.playedAt;
      if (!wasPlayed) return true;
      return progress > 1; // played-and-restarted is still in rotation
    });
  }

  const query = _librarySearch.trim().toLowerCase();
  if (query) {
    clips = clips.filter((c) => {
      return (
        (c.title || "").toLowerCase().includes(query) ||
        (c.text || "").toLowerCase().includes(query) ||
        (c.voiceName || "").toLowerCase().includes(query) ||
        (c.note || "").toLowerCase().includes(query)
      );
    });
  }

  // Render the tag-filter chip row using ALL clips (so chips don't
  // disappear mid-interaction when a search hides their owners), with
  // counts computed against the post-search set so the numbers stay
  // meaningful.
  _renderTagFilterRow(allClips, clips);

  // Apply tag filter (AND across selected tags) AFTER search so the
  // header count below counts the actually-displayed clips.
  if (_libraryTagFilter.size > 0) {
    clips = clips.filter((c) => {
      const tags = Array.isArray(c.tags) ? c.tags : [];
      for (const wanted of _libraryTagFilter) {
        if (!tags.includes(wanted)) return false;
      }
      return true;
    });
  }

  // Header label reflects whether either filter is hiding anything.
  const filterActive = (query !== "" || _libraryTagFilter.size > 0);
  libraryLabel.textContent =
    filterActive && clips.length !== totalCount
      ? `Library · ${clips.length} of ${totalCount}`
      : "Library";

  if (clips.length === 0) {
    const empty = document.createElement("div");
    empty.className = "library-empty";
    if (_libraryTagFilter.size > 0) {
      const tags = [...(_libraryTagFilter)].join(", ");
      empty.textContent = query
        ? `No clips match "${query}" with tags: ${tags}`
        : `No clips with tags: ${tags}`;
    } else {
      empty.textContent = `No clips match "${query}"`;
    }
    libraryList.appendChild(empty);
    return;
  }

  // v225v3.59 (#791): tabbed library — render into two panels rather
  // than one flat list. Audio panel keeps Continue listening as a
  // sub-section (resume affordance stays one tap); ebook panel just
  // lists its clips. Tab counts update via _libraryUpdateTabCounts.
  // The legacy libraryList element stays mounted but hidden — old
  // helpers (_appendSectionHeader, etc.) target whichever container
  // _libraryActivePanel points to at the time of the call.
  const audioClips = clips.filter((c) => c.kind !== "ebook");
  const ebookClips = clips.filter((c) => c.kind === "ebook");
  const inProgress = audioClips.filter(isClipInProgress);
  const inProgressIds = new Set(inProgress.map((c) => c.id));
  const otherAudio = audioClips.filter((c) => !inProgressIds.has(c.id));

  const audioPanel = document.getElementById("lib-panel-audio");
  const ebookPanel = document.getElementById("lib-panel-ebook");
  if (audioPanel) audioPanel.innerHTML = "";
  if (ebookPanel) ebookPanel.innerHTML = "";

  // Re-point the section-header helper at the audio panel for the
  // duration of audio rendering; restore after. _appendSectionHeader
  // appends to whichever container is set as _sectionHeaderTarget.
  const _prevTarget = _sectionHeaderTarget;
  _sectionHeaderTarget = audioPanel;

  if (audioPanel) {
    if (inProgress.length > 0) {
      _appendSectionHeader(
        `Continue listening · ${inProgress.length}`,
        "Clips you started but didn't finish — picks up where you left off.",
      );
      for (const clip of inProgress) audioPanel.appendChild(makeClipCard(clip));
      if (otherAudio.length > 0) {
        _appendSectionHeader(`Other audio · ${otherAudio.length}`);
      }
    }
    for (const clip of otherAudio) audioPanel.appendChild(makeClipCard(clip));
    if (audioClips.length === 0) {
      const empty = document.createElement("div");
      empty.className = "library-empty";
      empty.textContent = "No audio clips yet — generate one to add audio.";
      audioPanel.appendChild(empty);
    }
  }

  _sectionHeaderTarget = ebookPanel;
  if (ebookPanel) {
    for (const clip of ebookClips) ebookPanel.appendChild(makeClipCard(clip));
    if (ebookClips.length === 0) {
      const empty = document.createElement("div");
      empty.className = "library-empty";
      empty.textContent = "No ebooks yet — import a file with the 📥 button.";
      ebookPanel.appendChild(empty);
    }
  }
  _sectionHeaderTarget = _prevTarget;

  // Update tab counts. Counts reflect the total kind population BEFORE
  // search/tag filtering would have been applied — that matches the
  // "Library · X of N" header convention.
  _libraryUpdateTabCounts(audioClips.length, ebookClips.length);
}

// ---- Edit clip (title + note + tags) ------------------------------------
// Opens the <dialog> with the current values, saves the new ones back into
// the same IndexedDB row. Audio blob and all the synthesis-side fields
// (voice, speaker, offsets, duration) are left untouched.
let _editingClipId = null;

// Tag normalization. The free-form comma-separated input becomes a clean
// array: trimmed, lowercased, deduped, empty entries dropped, max ~24
// chars per tag so the chip layout doesn't explode if someone pastes a
// paragraph in. Cap of 12 tags per clip — past that the card UI starts
// dominating.
function _normalizeTags(input) {
  if (Array.isArray(input)) {
    return _normalizeTags(input.join(","));
  }
  if (typeof input !== "string") return [];
  const seen = new Set();
  const out = [];
  for (const raw of input.split(",")) {
    const t = raw.trim().toLowerCase().slice(0, 24);
    if (!t) continue;
    if (seen.has(t)) continue;
    seen.add(t);
    out.push(t);
    if (out.length >= 12) break;
  }
  return out;
}

// Same djb2 hash as the cover swatch, but mapped to a single HSL hue so
// every tag has a stable color. Hueshift only — saturation/lightness
// fixed so chips read as a coherent set even with a dozen distinct tags.
function _tagColor(tag) {
  const h = _djb2Hash(String(tag || "")) % 360;
  return `hsl(${h} 60% 38%)`;
}

// ---- Cover-image helpers (v125) ----------------------------------------
// Authors can upload story-board art per chapter. We resize uploads to
// a 256x256 square (cover-fit), JPEG-encode at ~85% quality (~20-30KB
// each), and sample a dominant color for the Libby-style tint. The
// blob lives on `clip.cover.blob`; the color on `clip.cover.color`.

const COVER_SIZE_PX = 256;
const COVER_JPEG_QUALITY = 0.85;

// Process a user-uploaded image:
//   - Load via createImageBitmap (handles orientation + format)
//   - Draw cover-fit to a 256x256 canvas
//   - Extract dominant color by downsampling to 16x16 and averaging
//   - Encode to JPEG blob
// Returns { blob, color: {h,s,l} } or throws on unreadable input.
async function _processCoverImage(file) {
  const bitmap = await createImageBitmap(file);
  try {
    const canvas = document.createElement("canvas");
    canvas.width = COVER_SIZE_PX;
    canvas.height = COVER_SIZE_PX;
    const ctx = canvas.getContext("2d");
    // Cover-fit: scale so the smaller dimension matches the canvas,
    // then center-crop the overflow on the larger dimension.
    const scale = Math.max(
      COVER_SIZE_PX / bitmap.width,
      COVER_SIZE_PX / bitmap.height
    );
    const drawW = bitmap.width * scale;
    const drawH = bitmap.height * scale;
    const dx = (COVER_SIZE_PX - drawW) / 2;
    const dy = (COVER_SIZE_PX - drawH) / 2;
    ctx.drawImage(bitmap, dx, dy, drawW, drawH);

    const color = _sampleDominantColor(ctx);
    const blob = await new Promise((resolve, reject) =>
      canvas.toBlob(
        (b) => (b ? resolve(b) : reject(new Error("toBlob returned null"))),
        "image/jpeg",
        COVER_JPEG_QUALITY
      )
    );
    return { blob, color };
  } finally {
    bitmap.close();
  }
}

// Dominant-color sampler. Down-samples to 16x16 via drawImage scaling,
// reads back via getImageData, averages the RGB values, converts to
// HSL. Cheap (256 pixels) and good-enough for "soft tint backdrop"
// — no need to chase a perceptually-perfect dominant color.
function _sampleDominantColor(srcCtx) {
  const SAMPLE = 16;
  const tmp = document.createElement("canvas");
  tmp.width = SAMPLE;
  tmp.height = SAMPLE;
  const tctx = tmp.getContext("2d");
  tctx.drawImage(srcCtx.canvas, 0, 0, SAMPLE, SAMPLE);
  const data = tctx.getImageData(0, 0, SAMPLE, SAMPLE).data;
  let r = 0, g = 0, b = 0, n = 0;
  for (let i = 0; i < data.length; i += 4) {
    // Skip fully-transparent pixels (uploaded PNGs can have alpha).
    if (data[i + 3] < 8) continue;
    r += data[i];
    g += data[i + 1];
    b += data[i + 2];
    n++;
  }
  if (n === 0) return { h: 220, s: 30, l: 40 };
  return _rgbToHsl(r / n, g / n, b / n);
}

function _rgbToHsl(r, g, b) {
  r /= 255; g /= 255; b /= 255;
  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const l = (max + min) / 2;
  let h = 0, s = 0;
  if (max !== min) {
    const d = max - min;
    s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
    switch (max) {
      case r: h = (g - b) / d + (g < b ? 6 : 0); break;
      case g: h = (b - r) / d + 2; break;
      case b: h = (r - g) / d + 4; break;
    }
    h *= 60;
  }
  return { h: Math.round(h), s: Math.round(s * 100), l: Math.round(l * 100) };
}

// Object-URL lifecycle. Cards and the edit preview both render covers
// via createObjectURL — track them so we can revoke when the dialog
// closes / library re-renders, avoiding the slow leak Chrome warns about.
let _editPendingCover = null; // {blob, color} staged for save, or null
let _editPendingCoverUrl = null;

function _setEditCoverPreview(blob) {
  if (_editPendingCoverUrl) {
    URL.revokeObjectURL(_editPendingCoverUrl);
    _editPendingCoverUrl = null;
  }
  if (blob) {
    _editPendingCoverUrl = URL.createObjectURL(blob);
    clipEditCoverPreview.style.backgroundImage = `url("${_editPendingCoverUrl}")`;
    clipEditCoverRemove.hidden = false;
  } else {
    clipEditCoverPreview.style.backgroundImage = "";
    clipEditCoverRemove.hidden = true;
  }
}

// v219: render the read-only voice-provenance block in the Edit dialog.
// Returns silently if the clip has no provenance (pre-v219 clips, or
// clips made against an unaudited voice where we'd be guessing).
function _renderProvenanceBlock(clip) {
  const wrap = document.getElementById("clip-edit-provenance");
  if (!wrap) return;
  const p = clip && clip.provenance;
  if (!p) {
    wrap.hidden = true;
    return;
  }
  const badge = document.getElementById("clip-edit-provenance-badge");
  const voiceEl = document.getElementById("clip-edit-provenance-voice");
  const licEl = document.getElementById("clip-edit-provenance-license");
  const attrEl = document.getElementById("clip-edit-provenance-attribution");

  if (badge) {
    badge.textContent = p.licenseCommercial ? "Commercial ✓" : "Non-commercial";
    badge.classList.remove("commercial", "noncommercial");
    badge.classList.add(p.licenseCommercial ? "commercial" : "noncommercial");
  }
  if (voiceEl) {
    const speakerSuffix = (p.speakerId != null && p.speakerId !== 0)
      ? ` · speaker ${p.speakerId}`
      : "";
    voiceEl.innerHTML =
      `<span class="clip-edit-provenance-key">Voice:</span> ` +
      `<span class="clip-edit-provenance-val">${
        (p.voiceName || p.voiceId || "Unknown").replace(/</g, "&lt;")
      }${speakerSuffix}</span>`;
  }
  if (licEl) {
    const ds = p.licenseDataset ? ` · ${p.licenseDataset}` : "";
    licEl.innerHTML =
      `<span class="clip-edit-provenance-key">License:</span> ` +
      `<span class="clip-edit-provenance-val">${
        (p.license || "Unknown").replace(/</g, "&lt;")
      }${ds.replace(/</g, "&lt;")}</span>`;
  }
  if (attrEl) {
    attrEl.textContent = p.attribution || "(no attribution required)";
  }
  wrap.hidden = false;
}

// v225fz7 (#673): re-read the edit-dialog clip from IDB and re-paint
// the text fields that can be mutated by side actions (Clear marks,
// Restore from backup). Without this, the dialog keeps its initial
// values and a subsequent Save would silently undo the side action by
// writing the stale textarea content back. Only the fields that
// clear/restore can change get re-synced — title / cover / tags /
// gitRef etc. are not affected and stay as the user has them. Safe to
// call when the dialog is closed or pointing at a different clip
// (no-ops). Used by the clear-marks + restore-marks confirm flows.
async function _resyncClipEditFromIDB() {
  if (_editingClipId == null) return;
  const dlg = document.getElementById("clip-edit");
  if (!dlg || !dlg.open) return;
  try {
    const clip = await getClip(_editingClipId);
    if (!clip) return;
    if (typeof clip.notes === "string") {
      clipEditNotes.value = clip.notes;
    }
  } catch (e) {
    console.warn("[clip-edit] resync from IDB failed:", e);
  }
}

async function openClipEdit(clipId) {
  const clip = await getClip(clipId);
  if (!clip) return;
  _editingClipId = clipId;
  clipEditTitle.value = clip.title || "";
  clipEditNote.value = clip.note || "";
  clipEditNotes.value = clip.notes || "";
  clipEditTags.value = Array.isArray(clip.tags) ? clip.tags.join(", ") : "";
  // v179: show source path + short SHA for GitHub-sourced clips. The
  // user can confirm "this is the chapter I just pushed" without
  // alt-tabbing to GitHub. Tooltip on the SHA chip shows the full hash.
  const gitRefEl = document.getElementById("clip-edit-gitref");
  if (gitRefEl) {
    if (clip.gitRef && clip.gitRef.sha && clip.gitRef.path) {
      const pathEl = document.getElementById("clip-edit-gitref-path");
      const shaEl = document.getElementById("clip-edit-gitref-sha");
      if (pathEl) pathEl.textContent = clip.gitRef.path;
      if (shaEl) {
        shaEl.textContent = clip.gitRef.sha.slice(0, 7);
        shaEl.title = `Full commit SHA: ${clip.gitRef.sha}`;
      }
      gitRefEl.hidden = false;
    } else {
      gitRefEl.hidden = true;
    }
  }
  // v4.96 (#538 Phase 2): Scrivener pin display. Same gate pattern
  // as gitRef — show project + doc path, with the Push to Scrivener
  // button right alongside. Hidden for non-Scrivener clips.
  const scrivRefEl = document.getElementById("clip-edit-scrivref");
  if (scrivRefEl) {
    if (clip.scrivenerRef && clip.scrivenerRef.doc_id) {
      const projEl = document.getElementById("clip-edit-scrivref-project");
      const docEl = document.getElementById("clip-edit-scrivref-doc");
      if (projEl) projEl.textContent = clip.scrivenerRef.project_name || "(unknown project)";
      if (docEl) docEl.textContent = clip.scrivenerRef.doc_path || `BinderItem ${clip.scrivenerRef.doc_id}`;
      scrivRefEl.hidden = false;
    } else {
      scrivRefEl.hidden = true;
    }
  }
  // Cover staging. `_editPendingCover` represents the cover that will
  // be saved — initially mirrors the clip's current cover (or null if
  // none). User upload / remove mutates it; save persists it.
  if (clip.cover && clip.cover.blob) {
    _editPendingCover = { blob: clip.cover.blob, color: clip.cover.color || null };
    _setEditCoverPreview(clip.cover.blob);
  } else {
    _editPendingCover = null;
    _setEditCoverPreview(null);
  }
  // v219: voice provenance display. Read-only block shows what voice +
  // license were in effect when the clip's audio was generated. Hidden
  // when the clip has no provenance recorded (pre-v219 clips, or clips
  // generated against an unaudited voice — we don't fabricate).
  _renderProvenanceBlock(clip);
  // v225v4.0 (#810): paint the line-by-line storage section. CSS
  // visibility gates on .author-only handle the mode hiding; this
  // chooses between the OFF (Enable button) and ON (badge + count)
  // sub-states based on whether clip.lines is populated.
  try {
    await _paintLinesEditState(clipId);
  } catch (e) {
    console.warn("[clip-edit] lines state paint failed:", e);
  }
  clipEditDialog.showModal();
  clipEditTitle.focus();
  clipEditTitle.select();
}

function closeClipEdit() {
  _editingClipId = null;
  // Clean up any preview object URL the dialog created.
  if (_editPendingCoverUrl) {
    URL.revokeObjectURL(_editPendingCoverUrl);
    _editPendingCoverUrl = null;
  }
  _editPendingCover = null;
  clipEditDialog.close();
}

async function saveClipEdit() {
  if (!_editingClipId) return closeClipEdit();
  const id = _editingClipId;
  try {
    const newTitle = (clipEditTitle.value || "").trim() || "(untitled)";
    const newNote = (clipEditNote.value || "").trim();
    const newNotes = (clipEditNotes.value || "").trim();
    const newTags = _normalizeTags(clipEditTags.value);
    // v223.tn19 (#488): atomic so concurrent absorb can't lose annotations.
    const clip = await _mutateClipAtomic(id, (c) => {
      c.title = newTitle;
      c.note = newNote;
      c.notes = newNotes;
      c.tags = newTags;
      // Apply the staged cover. null = "remove cover".
      if (_editPendingCover && _editPendingCover.blob) {
        c.cover = {
          blob: _editPendingCover.blob,
          color: _editPendingCover.color || null,
        };
      } else {
        delete c.cover;
      }
    });
    if (!clip) return closeClipEdit();
    closeClipEdit();
    renderLibrary();
    // If the user edited the currently-loaded clip's cover, refresh
    // the page backdrop so the new image (or removal) takes effect
    // without requiring a reload of the clip.
    if (id === _currentClipId) {
      _setBackgroundArt(clip);
      // v225eb (#615): refresh phone top-bar title if the user just
      // renamed the currently-loaded clip. Pass the freshly mutated
      // clip so we don't race the IDB read with the SaveClip write.
      if (typeof _phonePaintTopTitle === "function") {
        try { _phonePaintTopTitle(clip); } catch {}
      }
      // v225ep (#632): refresh desktop author pane in case the user
      // edited Notes (the most likely Edit-dialog change that this
      // pane surfaces). Also covers tag/title/cover changes that
      // don't directly affect the pane but cost nothing to repaint.
      if (typeof _renderAuthorPane === "function") {
        try { _renderAuthorPane(); } catch {}
      }
    }
    setStatus(`Updated "${newTitle}"`);
  } catch (e) {
    console.warn("clip edit save failed:", e);
    setStatus(_withOfflineHint(`Save failed: ${e.message}`), true);
  }
}

clipEditCoverPick.addEventListener("click", () => clipEditCoverInput.click());
clipEditCoverInput.addEventListener("change", async (e) => {
  const file = e.target.files && e.target.files[0];
  if (!file) return;
  try {
    const processed = await _processCoverImage(file);
    _editPendingCover = processed;
    _setEditCoverPreview(processed.blob);
  } catch (err) {
    console.warn("cover upload failed:", err);
    setStatus(_withOfflineHint(`Cover upload failed: ${err.message}`), true);
  } finally {
    // Reset so picking the same file again still fires "change".
    clipEditCoverInput.value = "";
  }
});
clipEditCoverRemove.addEventListener("click", () => {
  _editPendingCover = null;
  _setEditCoverPreview(null);
});

clipEditClose.addEventListener("click", closeClipEdit);
clipEditSave.addEventListener("click", saveClipEdit);
clipEditDialog.addEventListener("close", () => { _editingClipId = null; });

// v4.94 (#886): Share book mockup. Opens a dialog with a 3D paperback
// rendering of the current clip, plus a "Download PNG" button that
// outputs a 1080x1080 canvas-flat version (social-share ready). The
// .bm-* DOM is the same shape as landing.html so the brand presentation
// is consistent; the PNG export uses a separate canvas-API renderer so
// the file ships identically across browsers — no html2canvas, no
// CSS-3D round-trip quirks.
const bookMockupDialog = $("book-mockup");
const bookMockupClose = $("book-mockup-close");
const bookMockupTitle = $("book-mockup-title");
const bookMockupAuthor = $("book-mockup-author");
const bookMockupTitleDisplay = $("book-mockup-title-display");
const bookMockupAuthorDisplay = $("book-mockup-author-display");
const bookMockupCoverFace = $("book-mockup-cover");
const bookMockupDownload = $("book-mockup-download");
const bookMockupCoverPick = $("book-mockup-cover-pick");
const bookMockupCoverInput = $("book-mockup-cover-input");
const bookMockupCoverClear = $("book-mockup-cover-clear");
const _BOOK_MOCKUP_AUTHOR_KEY = "narrativeBookMockupAuthor";
const _BOOK_MOCKUP_DEFAULT_COLOR = "#1b2244";
let _bookMockupCoverUrl = null;
let _bookMockupSourceClipId = null;
// v4.95: standalone-mode state. When openBookMockup is invoked without a
// clipId, the dialog becomes a free-form mockup builder — user picks a
// cover image OR a color, types a title and author, downloads the PNG.
// _bookMockupStandaloneCover is a Blob from the file input. _bookMockupColor
// is a hex string from a swatch click. Both reset when the dialog closes.
let _bookMockupStandaloneCover = null;
let _bookMockupColor = null;
// v4.99 (#892): rotation state. Y is left/right spin (degrees, -180..180),
// X is up/down tilt (-90..90). Defaults match the original CSS pose so the
// dialog opens looking identical to v4.95. Both the live CSS preview and
// the canvas PNG renderer read these — single source of truth.
const _BOOK_MOCKUP_ROT_DEFAULT = { y: -28, x: 4 };
let _bookMockupRot = { ..._BOOK_MOCKUP_ROT_DEFAULT };
// Named poses for the preset buttons. Reset matches the default.
const _BOOK_MOCKUP_POSES = {
  "three-quarter-left":  { y: -28, x: 4 },
  "three-quarter-right": { y:  28, x: 4 },
  "front":               { y:   0, x: 0 },
  "side":                { y: -88, x: 0 },
  "top":                 { y:   0, x: 70 },
  "reset":               { y: -28, x: 4 },
};

async function openBookMockup(clipId) {
  if (!bookMockupDialog) return;
  const clip = clipId ? await getClip(clipId) : null;
  _bookMockupSourceClipId = clipId || null;
  _bookMockupStandaloneCover = null;
  _bookMockupColor = null;
  // v4.99 (#892): reset rotation to default on every open so a fresh
  // dialog opens looking like v4.95 did.
  _bookMockupRot = { ..._BOOK_MOCKUP_ROT_DEFAULT };
  _applyBookMockupRotation();
  const title = clip && clip.title
    ? clip.title
    : (clipId ? "Your clip" : "");
  const savedAuthor = (() => {
    try { return localStorage.getItem(_BOOK_MOCKUP_AUTHOR_KEY) || ""; }
    catch (e) { return ""; }
  })();
  const author = savedAuthor || (clipId ? "You" : "");
  bookMockupTitle.value = title;
  bookMockupAuthor.value = author;
  _paintBookMockupPreview(
    title || "Your title",
    author,
    clip && clip.cover ? clip.cover : null,
  );
  _refreshBookMockupCoverState();
  bookMockupDialog.showModal();
  if (!clipId) {
    // Standalone mode — focus the title field so the user can type
    // immediately. With a clip, the title is pre-filled so we skip.
    setTimeout(() => { try { bookMockupTitle.focus(); bookMockupTitle.select(); } catch (e) {} }, 50);
  }
}

function _refreshBookMockupCoverState() {
  // Sync the Clear-cover button visibility + swatch active state with the
  // current cover mode (uploaded image vs picked color vs clip cover).
  const hasUploadedCover = _bookMockupStandaloneCover instanceof Blob;
  const hasPickedColor = !!_bookMockupColor;
  if (bookMockupCoverClear) {
    bookMockupCoverClear.hidden = !(hasUploadedCover || hasPickedColor);
  }
  const swatches = document.querySelectorAll(".book-mockup-swatch");
  swatches.forEach((s) => {
    const active = !hasUploadedCover && hasPickedColor && s.dataset.color === _bookMockupColor;
    s.classList.toggle("active", active);
  });
  // Apply the picked color to the cover's CSS var so the live preview
  // updates. If no color is picked, reset to the stylesheet default.
  const scene = document.querySelector(".book-mockup-stage .bm-scene");
  if (scene) {
    if (hasPickedColor && !hasUploadedCover) {
      scene.style.setProperty("--bm-cover-bg", _bookMockupColor);
    } else {
      scene.style.removeProperty("--bm-cover-bg");
    }
  }
}

function closeBookMockup() {
  if (_bookMockupCoverUrl) {
    URL.revokeObjectURL(_bookMockupCoverUrl);
    _bookMockupCoverUrl = null;
  }
  _bookMockupSourceClipId = null;
  if (bookMockupDialog && bookMockupDialog.open) bookMockupDialog.close();
}

// v4.99 (#892): push the current rotation state into the live preview's
// CSS vars and the slider/value-label DOM. Called by every rotation
// input — sliders, preset buttons, drag. Centralizes the round-trip so
// no UI control has to know about the others.
function _applyBookMockupRotation() {
  const book = document.getElementById("book-mockup-book");
  if (book) {
    // v4.99: set both the CSS vars (so the stylesheet's transform: rule
    // gets the right values for caching / first-paint) AND the inline
    // transform directly (because some renderers — notably the Playwright
    // headless Chromium we use for verification — don't re-evaluate var()
    // inside transform functions after the element first paints).
    book.style.setProperty("--bm-rot-y", _bookMockupRot.y + "deg");
    book.style.setProperty("--bm-rot-x", _bookMockupRot.x + "deg");
    book.style.transform =
      `rotateY(${_bookMockupRot.y}deg) rotateX(${_bookMockupRot.x}deg)`;
  }
  const yEl = document.getElementById("book-mockup-rot-y");
  const xEl = document.getElementById("book-mockup-rot-x");
  const yVal = document.getElementById("book-mockup-rot-y-val");
  const xVal = document.getElementById("book-mockup-rot-x-val");
  if (yEl && yEl.value !== String(_bookMockupRot.y)) yEl.value = _bookMockupRot.y;
  if (xEl && xEl.value !== String(_bookMockupRot.x)) xEl.value = _bookMockupRot.x;
  if (yVal) yVal.textContent = Math.round(_bookMockupRot.y) + "°";
  if (xVal) xVal.textContent = Math.round(_bookMockupRot.x) + "°";
  // Drop any preset highlight if the current angles don't match a preset.
  const presets = document.querySelectorAll(".book-mockup-rotate-presets button[data-rot]");
  presets.forEach((btn) => {
    const pose = _BOOK_MOCKUP_POSES[btn.dataset.rot];
    const matches = pose &&
      Math.round(pose.y) === Math.round(_bookMockupRot.y) &&
      Math.round(pose.x) === Math.round(_bookMockupRot.x);
    btn.classList.toggle("active", !!matches);
  });
}

function _paintBookMockupPreview(title, author, cover) {
  if (bookMockupTitleDisplay) bookMockupTitleDisplay.textContent = title;
  if (bookMockupAuthorDisplay) bookMockupAuthorDisplay.textContent = author ? `By ${author}` : "";
  if (!bookMockupCoverFace) return;
  if (_bookMockupCoverUrl) {
    URL.revokeObjectURL(_bookMockupCoverUrl);
    _bookMockupCoverUrl = null;
  }
  // v4.95: standalone-uploaded cover beats the clip cover. Author can
  // open Share mockup on a clip with cover X and re-share with cover Y
  // without renaming the clip.
  const effectiveCover = _bookMockupStandaloneCover instanceof Blob
    ? { blob: _bookMockupStandaloneCover }
    : cover;
  if (effectiveCover && effectiveCover.blob instanceof Blob) {
    _bookMockupCoverUrl = URL.createObjectURL(effectiveCover.blob);
    bookMockupCoverFace.style.backgroundImage = `url("${_bookMockupCoverUrl}")`;
    bookMockupCoverFace.dataset.hasArt = "1";
  } else {
    bookMockupCoverFace.style.backgroundImage = "";
    delete bookMockupCoverFace.dataset.hasArt;
  }
}

function _bookMockupLoadCoverImage(cover) {
  return new Promise((resolve) => {
    if (!cover || !(cover.blob instanceof Blob)) return resolve(null);
    const url = URL.createObjectURL(cover.blob);
    const img = new Image();
    img.onload = () => { URL.revokeObjectURL(url); resolve(img); };
    img.onerror = () => { URL.revokeObjectURL(url); resolve(null); };
    img.src = url;
  });
}

function _wrapBookMockupText(ctx, text, maxWidth) {
  const words = (text || "").split(/\s+/).filter(Boolean);
  const lines = [];
  let current = "";
  for (const w of words) {
    const trial = current ? `${current} ${w}` : w;
    if (ctx.measureText(trial).width <= maxWidth || !current) {
      current = trial;
    } else {
      lines.push(current);
      current = w;
    }
  }
  if (current) lines.push(current);
  return lines;
}

// v4.99 (#892): 3D book mockup renderer. Replaces the v4.95 flat 2D card
// so the saved PNG matches the rotated CSS preview at any angle. Renders
// the book as six face quads (cover, back, spine, fore-edge, top, bottom)
// projected through Y/X rotation + cheap perspective, painted back-to-
// front with the camera-facing face-cull check. Each face's content is
// pre-rendered into an offscreen canvas at the face's native pixel size,
// then drawn into the projected quad via a two-triangle affine — gives a
// passable perspective approximation without a homography solver.
async function downloadBookMockupPng() {
  const title = (bookMockupTitle.value || "Your clip").trim() || "Your clip";
  const author = (bookMockupAuthor.value || "").trim();
  try { localStorage.setItem(_BOOK_MOCKUP_AUTHOR_KEY, author); } catch (e) {}
  let coverImg = null;
  if (_bookMockupStandaloneCover instanceof Blob) {
    coverImg = await _bookMockupLoadCoverImage({ blob: _bookMockupStandaloneCover });
  } else if (_bookMockupSourceClipId) {
    const clip = await getClip(_bookMockupSourceClipId);
    if (clip && clip.cover) coverImg = await _bookMockupLoadCoverImage(clip.cover);
  }
  const fallbackColor = _bookMockupColor || _BOOK_MOCKUP_DEFAULT_COLOR;
  const canvas = document.createElement("canvas");
  const W = 1080, H = 1080;
  canvas.width = W; canvas.height = H;
  const ctx = canvas.getContext("2d");

  // --- 1. Backdrop (unchanged from v4.95) ---
  const bg = ctx.createLinearGradient(0, 0, 0, H);
  bg.addColorStop(0, "#0b1020");
  bg.addColorStop(1, "#1b2240");
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);
  const glow = ctx.createRadialGradient(W / 2, H * 1.05, 0, W / 2, H * 1.05, W * 0.65);
  glow.addColorStop(0, "rgba(124, 156, 255, 0.32)");
  glow.addColorStop(1, "rgba(124, 156, 255, 0)");
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, W, H);

  // --- 2. Pre-render each face's contents at native size ---
  // Book box: 520×780 (cover), 70 deep. Matches the v4.95 flat size so
  // the front-on view (0°/0°) looks identical to the old PNG.
  const FW = 520, FH = 780, FD = 70;
  const coverFace = _buildBookMockupFace(FW, FH, coverImg, fallbackColor, title, author);
  const backFace  = _buildBookMockupBackFace(FW, FH);
  const spineFace = _buildBookMockupSpineFace(FD, FH, fallbackColor, title);
  const edgeH     = _buildBookMockupEdgeFace(FD, FH);  // right fore-edge (vertical stripes)
  const edgeV     = _buildBookMockupEdgeFace(FW, FD);  // top/bottom (horizontal stripes)

  // --- 3. Define box corners in book-local space (origin at center) ---
  const hw = FW / 2, hh = FH / 2, hd = FD / 2;
  const corners = [
    { x: -hw, y: -hh, z:  hd }, // 0 front TL
    { x:  hw, y: -hh, z:  hd }, // 1 front TR
    { x:  hw, y:  hh, z:  hd }, // 2 front BR
    { x: -hw, y:  hh, z:  hd }, // 3 front BL
    { x: -hw, y: -hh, z: -hd }, // 4 back TL
    { x:  hw, y: -hh, z: -hd }, // 5 back TR
    { x:  hw, y:  hh, z: -hd }, // 6 back BR
    { x: -hw, y:  hh, z: -hd }, // 7 back BL
  ];

  // Six faces. Each names: corner indices in winding order TL→TR→BR→BL
  // (as seen from outside the box), source canvas to drape over the quad,
  // and source UV size (matches source canvas dimensions).
  const faces = [
    { name: "cover",  idx: [0, 1, 2, 3], src: coverFace, sw: FW, sh: FH },
    { name: "back",   idx: [5, 4, 7, 6], src: backFace,  sw: FW, sh: FH },
    { name: "spine",  idx: [4, 0, 3, 7], src: spineFace, sw: FD, sh: FH },
    { name: "right",  idx: [1, 5, 6, 2], src: edgeH,     sw: FD, sh: FH },
    { name: "top",    idx: [4, 5, 1, 0], src: edgeV,     sw: FW, sh: FD },
    { name: "bottom", idx: [3, 2, 6, 7], src: edgeV,     sw: FW, sh: FD },
  ];

  // --- 4. Rotate corners by Y then X (matches CSS rotateY().rotateX()) ---
  const ry = (_bookMockupRot.y || 0) * Math.PI / 180;
  const rxa = (_bookMockupRot.x || 0) * Math.PI / 180;
  const cy = Math.cos(ry), sy = Math.sin(ry);
  const cxa = Math.cos(rxa), sxa = Math.sin(rxa);
  const rotated = corners.map((p) => {
    // Y-rotation
    let x = p.x * cy + p.z * sy;
    let z = -p.x * sy + p.z * cy;
    let y = p.y;
    // X-rotation
    const yr = y * cxa - z * sxa;
    const zr = y * sxa + z * cxa;
    return { x, y: yr, z: zr };
  });

  // --- 5. Project to 2D with cheap perspective ---
  // Focal length controls how dramatic the foreshortening is. Larger =
  // flatter (closer to ortho); smaller = more perspective. 1500 matches
  // the CSS `perspective: 1500px` in styles.css so projected angles agree.
  const focal = 1500;
  const cx2D = W / 2;
  const cy2D = H / 2 - 40; // shift up a bit to leave room for the wordmark
  const projected = rotated.map((p) => {
    const f = focal / (focal - p.z);
    return { x: cx2D + p.x * f, y: cy2D + p.y * f, z: p.z };
  });

  // --- 6. Drop shadow under the lowest projected point ---
  const projY = projected.map((p) => p.y);
  const projX = projected.map((p) => p.x);
  const lowY = Math.max(...projY);
  const midX = (Math.min(...projX) + Math.max(...projX)) / 2;
  const shadowW = (Math.max(...projX) - Math.min(...projX)) * 0.85;
  ctx.save();
  ctx.fillStyle = "rgba(0, 0, 0, 0.5)";
  ctx.filter = "blur(28px)";
  ctx.beginPath();
  ctx.ellipse(midX, lowY + 36, shadowW / 2, 22, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  // --- 7. Face visibility + depth sort ---
  // A face is visible when its outward normal points at the camera (which
  // sits on +z looking toward origin). Normal computed as edge0 × edge1
  // of the rotated quad; sign of the resulting z component tells us
  // whether the face is front-facing.
  const visible = [];
  for (const face of faces) {
    const [i0, i1, i2, i3] = face.idx;
    const p0 = rotated[i0], p1 = rotated[i1], p2 = rotated[i2];
    const ex = p1.x - p0.x, ey = p1.y - p0.y;
    const fx = p2.x - p0.x, fy = p2.y - p0.y;
    const nz = ex * fy - ey * fx;
    if (nz < 0) {
      const avgZ = (rotated[i0].z + rotated[i1].z + rotated[i2].z + rotated[i3].z) / 4;
      visible.push({ face, avgZ });
    }
  }
  // Far → near so closer faces paint over farther ones.
  visible.sort((a, b) => a.avgZ - b.avgZ);

  // --- 8. Paint each visible face ---
  for (const { face } of visible) {
    const [i0, i1, i2, i3] = face.idx;
    _drawTexturedQuad(
      ctx, face.src, face.sw, face.sh,
      projected[i0], projected[i1], projected[i2], projected[i3],
    );
  }

  // --- 9. Footer wordmark (unchanged) ---
  ctx.textBaseline = "alphabetic";
  ctx.textAlign = "center";
  ctx.fillStyle = "rgba(231, 236, 255, 0.55)";
  ctx.font = "600 22px -apple-system, 'Segoe UI', Roboto, sans-serif";
  ctx.fillText("Made with Narrative", W / 2, H - 70);
  ctx.fillStyle = "rgba(231, 236, 255, 0.32)";
  ctx.font = "400 16px -apple-system, 'Segoe UI', Roboto, sans-serif";
  ctx.fillText("narrative-alpha.fly.dev", W / 2, H - 44);

  canvas.toBlob((blob) => {
    if (!blob) return;
    const a = document.createElement("a");
    const url = URL.createObjectURL(blob);
    const safe = (title || "clip").replace(/[^a-z0-9\-_. ]/gi, "").replace(/\s+/g, "-").slice(0, 60) || "clip";
    a.href = url;
    a.download = `${safe}-narrative-mockup.png`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000);
  }, "image/png", 0.95);
}

// --- 3D helpers (#892) ---

// Build a face canvas containing the front cover artwork — either the
// user's cover image (cover-fit, no title overlay) or the title-on-color
// fallback. Always includes the AUDIOBOOK badge near the bottom.
function _buildBookMockupFace(width, height, coverImg, fallbackColor, title, author) {
  const c = document.createElement("canvas");
  c.width = width; c.height = height;
  const cx = c.getContext("2d");
  if (coverImg) {
    cx.fillStyle = "#1b2244";
    cx.fillRect(0, 0, width, height);
    const ar = coverImg.width / coverImg.height;
    const targetAr = width / height;
    let dw, dh, dx, dy;
    if (ar > targetAr) {
      dh = height; dw = dh * ar; dx = -(dw - width) / 2; dy = 0;
    } else {
      dw = width; dh = dw / ar; dx = 0; dy = -(dh - height) / 2;
    }
    cx.drawImage(coverImg, dx, dy, dw, dh);
  } else {
    cx.fillStyle = fallbackColor;
    cx.fillRect(0, 0, width, height);
    cx.fillStyle = "#7c9cff";
    _roundRect(cx, 60, 70, width * 0.42, 12, 6);
    cx.fill();
    cx.fillStyle = "#e7ecff";
    cx.font = "700 56px Georgia, 'Iowan Old Style', serif";
    cx.textBaseline = "top";
    const titleMaxW = width - 100;
    const titleLines = _wrapBookMockupText(cx, title, titleMaxW);
    const lineH = 64;
    const titleBlockH = titleLines.length * lineH;
    let titleY = height - 200 - titleBlockH;
    for (const line of titleLines) {
      cx.fillText(line, 50, titleY);
      titleY += lineH;
    }
    if (author) {
      cx.fillStyle = "rgba(231, 236, 255, 0.65)";
      cx.font = "600 20px -apple-system, 'Segoe UI', Roboto, sans-serif";
      cx.fillText(author.toUpperCase(), 50, height - 170);
    }
  }
  // AUDIOBOOK badge — overlay always, so the brand mark stays visible
  // even on an image cover. Matches the v4.95 layout.
  const badgeX = 50, badgeY = height - 100, badgeH = 44;
  cx.font = "600 16px -apple-system, 'Segoe UI', Roboto, sans-serif";
  const badgeTextW = cx.measureText("AUDIOBOOK").width;
  const badgeW = badgeTextW + 90;
  cx.fillStyle = "rgba(11, 16, 32, 0.78)";
  _roundRect(cx, badgeX, badgeY, badgeW, badgeH, badgeH / 2);
  cx.fill();
  cx.strokeStyle = "rgba(255, 255, 255, 0.18)";
  cx.lineWidth = 1;
  cx.stroke();
  cx.fillStyle = "#7c9cff";
  const barXs = [0, 8, 16, 24, 32, 40];
  const barHs = [12, 22, 8, 18, 6, 20];
  for (let i = 0; i < barXs.length; i++) {
    const x = badgeX + 16 + barXs[i];
    const h = barHs[i];
    const y = badgeY + (badgeH - h) / 2;
    _roundRect(cx, x, y, 3, h, 1.5);
    cx.fill();
  }
  cx.fillStyle = "#e7ecff";
  cx.textBaseline = "middle";
  cx.fillText("AUDIOBOOK", badgeX + 68, badgeY + badgeH / 2);
  return c;
}

function _buildBookMockupBackFace(width, height) {
  const c = document.createElement("canvas");
  c.width = width; c.height = height;
  const cx = c.getContext("2d");
  cx.fillStyle = "#0e1430";
  cx.fillRect(0, 0, width, height);
  return c;
}

// Spine: dark gradient with the title set vertically (rotated 90°). Width
// param is the book's depth dimension; height is the cover height.
function _buildBookMockupSpineFace(width, height, coverColor, title) {
  const c = document.createElement("canvas");
  c.width = width; c.height = height;
  const cx = c.getContext("2d");
  const grad = cx.createLinearGradient(0, 0, width, 0);
  grad.addColorStop(0, "#0e1430");
  grad.addColorStop(0.5, coverColor);
  grad.addColorStop(1, "#0e1430");
  cx.fillStyle = grad;
  cx.fillRect(0, 0, width, height);
  // Title text running down the spine — rotated 90° clockwise so it reads
  // bottom-up. Only render if spine is wide enough for a legible row.
  if (width >= 36 && title) {
    cx.save();
    cx.translate(width / 2, height / 2);
    cx.rotate(-Math.PI / 2);
    cx.fillStyle = "rgba(231, 236, 255, 0.85)";
    cx.font = "600 22px Georgia, 'Iowan Old Style', serif";
    cx.textBaseline = "middle";
    cx.textAlign = "center";
    const maxLen = height - 40;
    let s = title;
    while (cx.measureText(s).width > maxLen && s.length > 4) s = s.slice(0, -1);
    if (s !== title) s = s.slice(0, -1) + "…";
    cx.fillText(s, 0, 0);
    cx.restore();
  }
  return c;
}

// Page edge: cream paper with closely-spaced ruled lines. Used for the
// top / bottom / fore-edge faces. Direction parameter inferred from
// aspect ratio — long axis gets the line direction.
function _buildBookMockupEdgeFace(width, height) {
  const c = document.createElement("canvas");
  c.width = width; c.height = height;
  const cx = c.getContext("2d");
  cx.fillStyle = "#f4ecd8";
  cx.fillRect(0, 0, width, height);
  cx.strokeStyle = "#d8cfb8";
  cx.lineWidth = 1;
  // Rule lines run along the longer axis to mimic a stack of pages.
  if (height >= width) {
    for (let y = 1; y < height; y += 2) {
      cx.beginPath();
      cx.moveTo(0, y);
      cx.lineTo(width, y);
      cx.stroke();
    }
  } else {
    for (let x = 1; x < width; x += 2) {
      cx.beginPath();
      cx.moveTo(x, 0);
      cx.lineTo(x, height);
      cx.stroke();
    }
  }
  return c;
}

// Draw a textured quad by splitting it into two triangles and applying
// a per-triangle affine transform. Not a true perspective homography,
// but for the moderate rotations a book mockup uses (no extreme
// fisheye angles), this looks correct enough that a casual viewer
// can't tell the difference from a real 3D render. Source corners
// (TL, TR, BR, BL) map to dest corners (p0, p1, p2, p3).
function _drawTexturedQuad(ctx, src, sw, sh, p0, p1, p2, p3) {
  // Triangle A: source (0,0)-(sw,0)-(sw,sh) → dest (p0, p1, p2)
  _drawTriangleImage(ctx, src, 0, 0, sw, 0, sw, sh, p0, p1, p2);
  // Triangle B: source (0,0)-(sw,sh)-(0,sh) → dest (p0, p2, p3)
  _drawTriangleImage(ctx, src, 0, 0, sw, sh, 0, sh, p0, p2, p3);
}

function _drawTriangleImage(ctx, src, sx0, sy0, sx1, sy1, sx2, sy2, p0, p1, p2) {
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(p0.x, p0.y);
  ctx.lineTo(p1.x, p1.y);
  ctx.lineTo(p2.x, p2.y);
  ctx.closePath();
  ctx.clip();
  const m = _solveAffine(sx0, sy0, sx1, sy1, sx2, sy2, p0, p1, p2);
  if (m) {
    ctx.setTransform(m.a, m.b, m.c, m.d, m.e, m.f);
    ctx.drawImage(src, 0, 0);
  }
  ctx.restore();
}

// Solve for the affine transform that maps (sx0,sy0), (sx1,sy1), (sx2,sy2)
// to (p0, p1, p2). Returns null when the source triangle is degenerate.
// Affine matrix in canvas form is [a c e; b d f] meaning
//   dest.x = a*src.x + c*src.y + e
//   dest.y = b*src.x + d*src.y + f
function _solveAffine(sx0, sy0, sx1, sy1, sx2, sy2, p0, p1, p2) {
  const det = (sx1 - sx0) * (sy2 - sy0) - (sx2 - sx0) * (sy1 - sy0);
  if (Math.abs(det) < 1e-9) return null;
  const invDet = 1 / det;
  const a = ((p1.x - p0.x) * (sy2 - sy0) - (p2.x - p0.x) * (sy1 - sy0)) * invDet;
  const c = ((p2.x - p0.x) * (sx1 - sx0) - (p1.x - p0.x) * (sx2 - sx0)) * invDet;
  const e = p0.x - a * sx0 - c * sy0;
  const b = ((p1.y - p0.y) * (sy2 - sy0) - (p2.y - p0.y) * (sy1 - sy0)) * invDet;
  const d = ((p2.y - p0.y) * (sx1 - sx0) - (p1.y - p0.y) * (sx2 - sx0)) * invDet;
  const f = p0.y - b * sx0 - d * sy0;
  return { a, b, c, d, e, f };
}

function _roundRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

if (bookMockupClose) bookMockupClose.addEventListener("click", closeBookMockup);
if (bookMockupDialog) bookMockupDialog.addEventListener("close", () => {
  if (_bookMockupCoverUrl) {
    URL.revokeObjectURL(_bookMockupCoverUrl);
    _bookMockupCoverUrl = null;
  }
  _bookMockupSourceClipId = null;
  // v4.95: reset standalone state on close so a fresh open starts clean.
  _bookMockupStandaloneCover = null;
  _bookMockupColor = null;
  if (bookMockupCoverInput) bookMockupCoverInput.value = "";
});

// v4.95: cover controls — upload image, pick color, clear.
if (bookMockupCoverPick && bookMockupCoverInput) {
  bookMockupCoverPick.addEventListener("click", () => bookMockupCoverInput.click());
}
if (bookMockupCoverInput) {
  bookMockupCoverInput.addEventListener("change", () => {
    const f = bookMockupCoverInput.files && bookMockupCoverInput.files[0];
    if (!f) return;
    _bookMockupStandaloneCover = f;
    _bookMockupColor = null;
    _paintBookMockupPreview(
      bookMockupTitle.value || "Your title",
      bookMockupAuthor.value || "",
      null,
    );
    _refreshBookMockupCoverState();
  });
}
if (bookMockupCoverClear) {
  bookMockupCoverClear.addEventListener("click", () => {
    _bookMockupStandaloneCover = null;
    _bookMockupColor = null;
    if (bookMockupCoverInput) bookMockupCoverInput.value = "";
    _paintBookMockupPreview(
      bookMockupTitle.value || "Your title",
      bookMockupAuthor.value || "",
      null,
    );
    _refreshBookMockupCoverState();
    // Re-fetch clip cover if we came from a clip — clearing the standalone
    // override should fall back to the clip's own cover.
    if (_bookMockupSourceClipId) {
      getClip(_bookMockupSourceClipId).then((clip) => {
        if (clip && clip.cover) {
          _paintBookMockupPreview(
            bookMockupTitle.value || "Your title",
            bookMockupAuthor.value || "",
            clip.cover,
          );
        }
      });
    }
  });
}
document.querySelectorAll(".book-mockup-swatch").forEach((sw) => {
  sw.addEventListener("click", () => {
    const c = sw.dataset.color;
    if (!c) return;
    _bookMockupColor = c;
    _bookMockupStandaloneCover = null;
    if (bookMockupCoverInput) bookMockupCoverInput.value = "";
    _paintBookMockupPreview(
      bookMockupTitle.value || "Your title",
      bookMockupAuthor.value || "",
      null,
    );
    _refreshBookMockupCoverState();
  });
});
if (bookMockupTitle) bookMockupTitle.addEventListener("input", () => {
  const placeholder = _bookMockupSourceClipId ? "Your clip" : "Your title";
  _paintBookMockupPreview(
    bookMockupTitle.value || placeholder,
    bookMockupAuthor.value || "",
    null,
  );
  if (_bookMockupSourceClipId && !(_bookMockupStandaloneCover instanceof Blob)) {
    getClip(_bookMockupSourceClipId).then((clip) => {
      if (clip && clip.cover) {
        _paintBookMockupPreview(bookMockupTitle.value || placeholder, bookMockupAuthor.value || "", clip.cover);
      }
    });
  }
});
if (bookMockupAuthor) bookMockupAuthor.addEventListener("input", () => {
  const display = bookMockupAuthorDisplay;
  if (display) display.textContent = bookMockupAuthor.value ? `By ${bookMockupAuthor.value}` : "";
});
// v4.99 (#892): rotation control wiring. Sliders push their value into
// _bookMockupRot; preset buttons jump to a named pose; pointer drag on
// the book spins both axes. All paths call _applyBookMockupRotation()
// which updates the CSS vars + slider labels + preset highlight in lock-
// step. The PNG renderer reads _bookMockupRot at click-time so saved
// images always match the live preview.
const _rotYInput = document.getElementById("book-mockup-rot-y");
const _rotXInput = document.getElementById("book-mockup-rot-x");
if (_rotYInput) {
  _rotYInput.addEventListener("input", () => {
    _bookMockupRot.y = parseFloat(_rotYInput.value) || 0;
    _applyBookMockupRotation();
  });
}
if (_rotXInput) {
  _rotXInput.addEventListener("input", () => {
    _bookMockupRot.x = parseFloat(_rotXInput.value) || 0;
    _applyBookMockupRotation();
  });
}
document.querySelectorAll(".book-mockup-rotate-presets button[data-rot]").forEach((btn) => {
  btn.addEventListener("click", () => {
    const pose = _BOOK_MOCKUP_POSES[btn.dataset.rot];
    if (!pose) return;
    _bookMockupRot = { ...pose };
    _applyBookMockupRotation();
  });
});
// Drag-to-spin on the live book. Works with mouse + touch + pen via
// Pointer Events. 1px of horizontal drag = 0.6° of Y rotation; 1px
// vertical = 0.6° of X tilt. Clamped to slider ranges so user can't
// drag the book into nonsense.
(function _wireBookMockupDrag() {
  const book = document.getElementById("book-mockup-book");
  if (!book) return;
  let dragging = false;
  let startX = 0, startY = 0, startRotY = 0, startRotX = 0;
  book.addEventListener("pointerdown", (e) => {
    if (!bookMockupDialog || !bookMockupDialog.open) return;
    dragging = true;
    startX = e.clientX; startY = e.clientY;
    startRotY = _bookMockupRot.y; startRotX = _bookMockupRot.x;
    book.classList.add("is-dragging");
    try { book.setPointerCapture(e.pointerId); } catch (err) {}
    e.preventDefault();
  });
  book.addEventListener("pointermove", (e) => {
    if (!dragging) return;
    const dx = e.clientX - startX;
    const dy = e.clientY - startY;
    _bookMockupRot.y = Math.max(-180, Math.min(180, startRotY + dx * 0.6));
    _bookMockupRot.x = Math.max(-90,  Math.min(90,  startRotX - dy * 0.6));
    _applyBookMockupRotation();
  });
  const end = (e) => {
    if (!dragging) return;
    dragging = false;
    book.classList.remove("is-dragging");
    try { book.releasePointerCapture(e.pointerId); } catch (err) {}
  };
  book.addEventListener("pointerup", end);
  book.addEventListener("pointercancel", end);
})();

if (bookMockupDownload) bookMockupDownload.addEventListener("click", () => {
  downloadBookMockupPng().catch((err) => {
    console.warn("[book-mockup] download failed:", err);
  });
});

const clipEditShareMockupBtn = $("clip-edit-share-mockup");
if (clipEditShareMockupBtn) {
  clipEditShareMockupBtn.addEventListener("click", () => {
    if (!_editingClipId) return;
    openBookMockup(_editingClipId);
  });
}

// v4.60 (#538 Phase 1A): Push-to-GitHub button. Closes the
// revise-as-you-listen loop — write the clip's current text back to
// the source file on GitHub with a real commit. Only available for
// clips imported from GitHub (the gitRef block hides itself otherwise,
// taking the button with it).
//
// Flow:
//   1. User opens Edit dialog for a GitHub-sourced clip.
//   2. User taps "⇡ Push to GitHub".
//   3. window.confirm shows the commit-message preview (default:
//      "Revised in Narrative: <title>") + the target path/branch.
//   4. POST /api/github/push-file with the current clip.text +
//      stored gitRef.sha (for optimistic-concurrency check).
//   5a. On success: server returns the new blob SHA. We stash it
//       into clip.gitRef.sha so the "outdated" detector (#234) sees
//       parity with the remote.
//   5b. On 409 (stale SHA): the source moved on GitHub since we
//       imported. Tell the user to Pull first (using the per-card
//       Sync chip or Settings → Pull now), then re-open Edit, then
//       try Push again.
//   5c. On 401/403: token issue. Send user to Settings → GitHub token.
//
// v4.80 (#849) — Phase 1B: preserve YAML frontmatter on push. The
// extractor now splits `---\n...\n---\n` off the top before handing
// the body to the client, and stashes the verbatim block on
// gitRef.frontmatter. On push we prepend that block to clip.text so
// the round-trip leaves the metadata intact. Old clips (imported
// before v4.80) have no frontmatter field — push them as before.
// Files without a frontmatter block get an empty string and the
// prepend is a no-op.
const _clipEditPushGithubBtn = document.getElementById("clip-edit-push-github-btn");
if (_clipEditPushGithubBtn) {
  _clipEditPushGithubBtn.addEventListener("click", async () => {
    if (_clipEditPushGithubBtn.disabled) return;
    if (!_editingClipId) return;
    const clip = await getClip(_editingClipId);
    if (!clip) {
      setStatus("Couldn't read that clip.", true);
      return;
    }
    if (!clip.gitRef || !clip.gitRef.repoUrl || !clip.gitRef.path || !clip.gitRef.sha) {
      setStatus("This clip isn't linked to a GitHub source.", true);
      return;
    }
    const token = getGithubToken();
    if (!token) {
      setStatus(
        "Set a GitHub token in Settings before pushing.",
        true,
      );
      return;
    }
    const text = (clip.text || "").trim();
    if (!text) {
      setStatus("Nothing to push — clip text is empty.", true);
      return;
    }

    // Build the default commit message + show confirm with the
    // target path/branch so the user can't get confused about which
    // file they're about to overwrite.
    const branch = clip.gitRef.branch || "main";
    const defaultMessage = `Revised in Narrative: ${clip.title || "(untitled)"}`;
    const previewMessage = window.prompt(
      `Push to GitHub?\n\n` +
      `  Repo:   ${clip.gitRef.repoUrl}\n` +
      `  Branch: ${branch}\n` +
      `  File:   ${clip.gitRef.path}\n` +
      `  SHA:    ${clip.gitRef.sha.slice(0, 7)} (your imported version)\n\n` +
      `Edit the commit message below, then OK to push.\n` +
      `Cancel keeps everything local.`,
      defaultMessage,
    );
    if (previewMessage === null) {
      setStatus("Push cancelled.");
      return;
    }
    const message = previewMessage.trim() || defaultMessage;

    _clipEditPushGithubBtn.disabled = true;
    const _origLabel = _clipEditPushGithubBtn.textContent;
    _clipEditPushGithubBtn.textContent = "Pushing…";
    // v4.80 (#849): prepend YAML frontmatter so the file round-trips
    // intact. clip.gitRef.frontmatter is populated by extract.py's
    // URL-fetch path for .md / .markdown sources; empty string for
    // formats that don't have a frontmatter, missing entirely on
    // old clips imported before v4.80 (treat as empty).
    const frontmatter = (clip.gitRef && clip.gitRef.frontmatter) || "";
    const pushContent = frontmatter + (clip.text || "");
    try {
      const res = await fetch("/api/github/push-file", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          github_token: token,
          repo_url: clip.gitRef.repoUrl,
          branch,
          path: clip.gitRef.path,
          content: pushContent,
          message,
          expected_sha: clip.gitRef.sha,
          host: clip.gitRef.host || null,
        }),
      });
      const data = await res.json().catch(() => ({}));
      _dlog("github-push", `result for ${clip.gitRef.path}`, {
        httpStatus: res.status,
        ok: data && data.ok,
        reason: data && data.reason,
        blobSha: data && data.blob_sha ? String(data.blob_sha).slice(0, 7) : null,
        commitSha: data && data.commit_sha ? String(data.commit_sha).slice(0, 7) : null,
      });
      if (!res.ok || !data || data.ok === false) {
        const reason = (data && data.reason) || "http_error";
        if (reason === "stale_sha") {
          setStatus(
            `GitHub source has moved since you imported. Pull first ` +
            `(per-card ↻ Sync chip or Settings → Pull now), then re-open ` +
            `Edit and try Push again.`,
            true,
          );
        } else if (reason === "not_found") {
          setStatus(
            `File not found on GitHub: ${clip.gitRef.path} @ ${branch}. ` +
            `Check the branch in Edit.`,
            true,
          );
        } else if (reason === "auth") {
          setStatus(
            "GitHub rejected the push — token may not have write access. " +
            "Settings → GitHub → Test token to diagnose.",
            true,
          );
        } else if (reason === "network") {
          setStatus(_withOfflineHint("Network error pushing to GitHub."), true);
        } else {
          const msg = (data && data.message) || `HTTP ${res.status}`;
          setStatus(`Push failed: ${msg}`, true);
        }
        return;
      }

      // Success: stash the new blob SHA into clip.gitRef.sha so the
      // outdated detector (#234) sees parity again, and the next time
      // the user opens Edit it shows the new short SHA in the chip.
      const newSha = data.blob_sha || "";
      if (newSha) {
        try {
          await _mutateClipAtomic(clip.id, (c) => {
            if (c.gitRef) c.gitRef.sha = newSha;
          });
        } catch (e) {
          console.warn("[github-push] post-push SHA update failed:", e);
        }
        // Repaint the SHA chip in the open Edit dialog so the user
        // sees the new short SHA without having to close + re-open.
        const shaEl = document.getElementById("clip-edit-gitref-sha");
        if (shaEl) {
          shaEl.textContent = newSha.slice(0, 7);
          shaEl.title = `Full commit SHA: ${newSha}`;
        }
      }
      const commitShort = data.commit_sha
        ? String(data.commit_sha).slice(0, 7)
        : "(no SHA returned)";
      setStatus(
        `Pushed "${clip.title || "clip"}" to GitHub — commit ${commitShort}.`
      );
    } catch (e) {
      console.warn("[github-push] threw:", e);
      setStatus(_withOfflineHint(`Push failed: ${e.message}`), true);
    } finally {
      _clipEditPushGithubBtn.disabled = false;
      _clipEditPushGithubBtn.textContent = _origLabel;
    }
  });
}

// v4.96 (#538 Phase 2): Push to Scrivener. Companion to the GitHub
// push above for Scrivener-imported clips. The user picks their
// original .scriv.zip from disk, the server patches the matching
// BinderItem RTF with the revised text, and the browser downloads
// the result as a fresh .scriv.zip. The bundle is never persisted
// server-side — re-upload each push. Patched scenes lose any RTF
// formatting (bold/italic/font in those scenes only); other scenes
// round-trip byte-for-byte.
const _clipEditPushScrivBtn = document.getElementById("clip-edit-push-scrivener-btn");
const _clipEditScrivInput = document.getElementById("clip-edit-scrivener-input");
if (_clipEditPushScrivBtn && _clipEditScrivInput) {
  _clipEditPushScrivBtn.addEventListener("click", () => {
    if (_clipEditPushScrivBtn.disabled) return;
    if (!_editingClipId) return;
    // Open the OS file picker. The change handler below does the actual
    // upload-and-download work; this click just kicks off the picker.
    _clipEditScrivInput.value = "";
    _clipEditScrivInput.click();
  });
  _clipEditScrivInput.addEventListener("change", async (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    if (!_editingClipId) return;
    const clip = await getClip(_editingClipId);
    if (!clip) {
      setStatus("Couldn't read that clip.", true);
      return;
    }
    if (!clip.scrivenerRef || !clip.scrivenerRef.doc_id) {
      setStatus("This clip isn't linked to a Scrivener source.", true);
      return;
    }
    const text = (clip.text || "").trim();
    if (!text) {
      setStatus("Nothing to push — clip text is empty.", true);
      return;
    }
    _clipEditPushScrivBtn.disabled = true;
    const _origLabel = _clipEditPushScrivBtn.textContent;
    _clipEditPushScrivBtn.textContent = "Patching…";
    try {
      const formData = new FormData();
      formData.append("file", file);
      formData.append(
        "edits",
        JSON.stringify([
          { doc_id: clip.scrivenerRef.doc_id, new_text: clip.text || "" },
        ]),
      );
      const res = await fetch("/api/scrivener/patch", {
        method: "POST",
        body: formData,
      });
      _dlog("scriv-push", `result for ${clip.scrivenerRef.doc_id}`, {
        httpStatus: res.status,
        ok: res.ok,
        patched: res.headers.get("X-Scriv-Patched") || "",
        missing: res.headers.get("X-Scriv-Missing") || "",
      });
      if (!res.ok) {
        let detail = `HTTP ${res.status}`;
        try {
          const j = await res.json();
          if (j && j.detail) detail = j.detail;
        } catch (_) {}
        setStatus(_withOfflineHint(`Scrivener patch failed: ${detail}`), true);
        return;
      }
      const missingHdr = res.headers.get("X-Scriv-Missing") || "";
      if (missingHdr && missingHdr.includes(clip.scrivenerRef.doc_id)) {
        setStatus(
          "That .scriv bundle doesn't contain this clip's scene. " +
          "Pick the project file the clip was imported from.",
          true,
        );
        return;
      }
      const blob = await res.blob();
      // Pull the filename from Content-Disposition if present; fall back
      // to project name from scrivenerRef + .scriv.zip suffix.
      const cd = res.headers.get("Content-Disposition") || "";
      const m = cd.match(/filename="([^"]+)"/);
      const safeProject = (clip.scrivenerRef.project_name || "scrivener-project")
        .replace(/[^A-Za-z0-9._-]/g, "_");
      const downloadName = m ? m[1] : `${safeProject}.scriv.zip`;
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = downloadName;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      // Defer revocation so Safari has time to start the download.
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      setStatus(
        `Patched ${downloadName} — open it in Scrivener and File → Import to merge.`,
      );
    } catch (err) {
      console.warn("[scriv-push] threw:", err);
      setStatus(_withOfflineHint(`Scrivener patch failed: ${err.message}`), true);
    } finally {
      _clipEditPushScrivBtn.disabled = false;
      _clipEditPushScrivBtn.textContent = _origLabel;
      _clipEditScrivInput.value = "";
    }
  });
}

// v4.76 (#878): Push notes to GitHub. Companion to the prose push
// above. Writes the existing Markdown export (clip.notes + bookmarks
// + annotations) to a sibling .notes.md file in the same repo/branch.
//
// Path strategy: strip the last extension on clip.gitRef.path and
// append .notes.md. Examples:
//   chapters/04.md          → chapters/04.notes.md
//   chapters/04.markdown    → chapters/04.notes.md
//   chapters/04             → chapters/04.notes.md
//   chapters/scene.intro.md → chapters/scene.intro.notes.md (only
//                             the LAST dot is the extension)
//
// SHA handling: notes files don't get a SHA on import (they're a
// derived sibling, not the source). We send expected_sha:"" and the
// server's v4.76 auto-resolve does a GET to discover whether the
// file exists yet — if 200, uses that SHA; if 404, creates the file.
// First push creates, subsequent pushes update. We don't cache the
// notes SHA client-side because the server resolves on every push,
// which is the simpler-and-correct model for a side artifact.
function _deriveNotesPath(srcPath) {
  if (typeof srcPath !== "string" || !srcPath) return "";
  const lastSlash = srcPath.lastIndexOf("/");
  const dir = lastSlash >= 0 ? srcPath.slice(0, lastSlash + 1) : "";
  const base = lastSlash >= 0 ? srcPath.slice(lastSlash + 1) : srcPath;
  const lastDot = base.lastIndexOf(".");
  // Only treat as an extension if the dot isn't the first char
  // (preserves dotfiles like ".gitignore" if they somehow show up).
  const stem = lastDot > 0 ? base.slice(0, lastDot) : base;
  return dir + stem + ".notes.md";
}

const _clipEditPushNotesBtn = document.getElementById("clip-edit-push-notes-btn");
if (_clipEditPushNotesBtn) {
  _clipEditPushNotesBtn.addEventListener("click", async () => {
    if (_clipEditPushNotesBtn.disabled) return;
    if (!_editingClipId) return;
    const clip = await getClip(_editingClipId);
    if (!clip) {
      setStatus("Couldn't read that clip.", true);
      return;
    }
    if (!clip.gitRef || !clip.gitRef.repoUrl || !clip.gitRef.path) {
      setStatus("This clip isn't linked to a GitHub source.", true);
      return;
    }
    const token = getGithubToken();
    if (!token) {
      setStatus(
        "Set a GitHub token in Settings before pushing.",
        true,
      );
      return;
    }

    // Build the Markdown body using the same exporter the local
    // download path uses (v225dr/#604). Guards: if there's literally
    // nothing to write (no clip.notes, no bookmarks, no annotations),
    // refuse rather than commit an empty stub.
    const md = (typeof _buildClipNotesMarkdown === "function")
      ? _buildClipNotesMarkdown(clip)
      : "";
    const hasNotes = (clip.notes || "").trim().length > 0;
    const hasBookmarks = Array.isArray(clip.bookmarks) && clip.bookmarks.length > 0;
    const hasAnnotations = Array.isArray(clip.annotations)
      && clip.annotations.some((a) => a && !a.deletedAt);
    if (!hasNotes && !hasBookmarks && !hasAnnotations) {
      setStatus(
        "Nothing to push — this clip has no notes, bookmarks, or annotations yet.",
        true,
      );
      return;
    }
    if (!md) {
      setStatus("Couldn't build the notes markdown.", true);
      return;
    }

    const notesPath = _deriveNotesPath(clip.gitRef.path);
    const branch = clip.gitRef.branch || "main";
    const defaultMessage = `Notes: ${clip.title || "(untitled)"}`;
    const previewMessage = window.prompt(
      `Push notes to GitHub?\n\n` +
      `  Repo:   ${clip.gitRef.repoUrl}\n` +
      `  Branch: ${branch}\n` +
      `  File:   ${notesPath}  ${" ".repeat(0)}(sibling of ${clip.gitRef.path})\n\n` +
      `Content: notes + bookmarks + annotations as Markdown.\n\n` +
      `Edit the commit message below, then OK to push.\n` +
      `Cancel keeps everything local.`,
      defaultMessage,
    );
    if (previewMessage === null) {
      setStatus("Push cancelled.");
      return;
    }
    const message = previewMessage.trim() || defaultMessage;

    _clipEditPushNotesBtn.disabled = true;
    const _origLabel = _clipEditPushNotesBtn.textContent;
    _clipEditPushNotesBtn.textContent = "Pushing…";
    try {
      const res = await fetch("/api/github/push-file", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          github_token: token,
          repo_url: clip.gitRef.repoUrl,
          branch,
          path: notesPath,
          content: md,
          message,
          // Empty SHA → server auto-resolves via GET-then-PUT. First
          // push to a never-existed path → server creates it.
          expected_sha: "",
          host: clip.gitRef.host || null,
        }),
      });
      const data = await res.json().catch(() => ({}));
      _dlog("github-push-notes", `result for ${notesPath}`, {
        httpStatus: res.status,
        ok: data && data.ok,
        reason: data && data.reason,
        commitSha: data && data.commit_sha ? String(data.commit_sha).slice(0, 7) : null,
      });
      if (!res.ok || !data || data.ok === false) {
        const reason = (data && data.reason) || "http_error";
        if (reason === "stale_sha") {
          // Notes file was edited on GitHub between the auto-resolve
          // GET and the PUT — rare but possible. Tell the user to
          // retry; the next push will re-resolve.
          setStatus(
            `Notes file changed on GitHub between probe and push. ` +
            `Try Push notes again — it'll re-resolve.`,
            true,
          );
        } else if (reason === "not_found") {
          setStatus(
            `Branch not found on GitHub: ${branch}. ` +
            `Check the branch in Edit.`,
            true,
          );
        } else if (reason === "auth") {
          setStatus(
            "GitHub rejected the push — token may not have write access. " +
            "Settings → GitHub → Test token to diagnose.",
            true,
          );
        } else if (reason === "auto_resolve_failed") {
          setStatus(
            `Couldn't check whether ${notesPath} exists yet: ` +
            ((data && data.message) || "GitHub error"),
            true,
          );
        } else if (reason === "network") {
          setStatus(_withOfflineHint("Network error pushing notes to GitHub."), true);
        } else {
          const msg = (data && data.message) || `HTTP ${res.status}`;
          setStatus(`Notes push failed: ${msg}`, true);
        }
        return;
      }
      const commitShort = data.commit_sha
        ? String(data.commit_sha).slice(0, 7)
        : "(no SHA returned)";
      // v225v4.100: alert() the success so phone users can see it. On
      // phone, #status is hidden when a clip is loaded (per #709 /
      // v4.46) so setStatus() lands on an invisible element. Push is a
      // write-back to GitHub with no native confirmation, so users were
      // unsure whether the push happened. alert() shows on all
      // platforms; matches the confirm() already used at the start of
      // this same flow. Errors get the same treatment below.
      const successMsg =
        `Pushed notes for "${clip.title || "clip"}"\n\n` +
        `→ ${notesPath}\n\n` +
        `Commit ${commitShort} on ${(clip.gitRef && clip.gitRef.branch) || "default branch"}.`;
      alert(successMsg);
      setStatus(`Pushed notes → ${notesPath} (commit ${commitShort}).`);
    } catch (e) {
      console.warn("[github-push-notes] threw:", e);
      const errMsg = _withOfflineHint(`Notes push failed: ${e.message}`);
      alert(errMsg);
      setStatus(errMsg, true);
    } finally {
      _clipEditPushNotesBtn.disabled = false;
      _clipEditPushNotesBtn.textContent = _origLabel;
    }
  });
}

// v225fz3 (#670): "Clear marks…" button in the Edit clip dialog opens
// the confirm modal scoped to whichever clip the Edit dialog is
// currently editing. Edit dialog stays open behind the confirm — if
// the user cancels the clear they're back in Edit where they were.
const _clipEditClearMarksBtn = document.getElementById("clip-edit-clear-marks-btn");
if (_clipEditClearMarksBtn) {
  _clipEditClearMarksBtn.addEventListener("click", () => {
    if (_editingClipId == null) return;
    _openClearMarksConfirm(_editingClipId);
  });
}

// v225fz5 (#672): "Restore from backup…" button. Same scoping as the
// Clear button — operates on _editingClipId. Opens the OS file picker;
// the change handler does the parse + confirm-dialog flow.
const _clipEditRestoreMarksBtn = document.getElementById("clip-edit-restore-marks-btn");
const _clipEditRestoreInput = document.getElementById("clip-edit-restore-input");
if (_clipEditRestoreMarksBtn && _clipEditRestoreInput) {
  _clipEditRestoreMarksBtn.addEventListener("click", () => {
    if (_editingClipId == null) return;
    // Reset so picking the same file twice still fires `change`.
    _clipEditRestoreInput.value = "";
    _clipEditRestoreInput.click();
  });
  _clipEditRestoreInput.addEventListener("change", async () => {
    const file = _clipEditRestoreInput.files && _clipEditRestoreInput.files[0];
    if (!file) return;
    const targetClipId = _editingClipId;
    if (targetClipId == null) {
      setStatus("Restore needs a clip open in the Edit dialog.", true);
      return;
    }
    let text;
    try {
      text = await file.text();
    } catch (e) {
      console.warn("[md-restore] file read failed:", e);
      setStatus("Couldn't read the file.", true);
      return;
    }
    const backup = _parseClipBackupFromMd(text);
    if (!backup) {
      setStatus(
        "This file doesn't contain Narrative backup data.",
        true,
      );
      return;
    }
    _openRestoreMarksConfirm(targetClipId, backup);
  });
}

// v219: copy-attribution affordance. Grabs the exact credit line
// from the currently-displayed provenance block. Lets audiobook
// publishers / animators paste it straight into a credits roll
// without having to retype dataset names.
const _clipEditProvCopy = document.getElementById("clip-edit-provenance-copy");
if (_clipEditProvCopy) {
  _clipEditProvCopy.addEventListener("click", async () => {
    const el = document.getElementById("clip-edit-provenance-attribution");
    const txt = el ? (el.textContent || "").trim() : "";
    if (!txt || txt === "(no attribution required)") {
      setStatus("Nothing to copy — this voice doesn't require attribution.");
      return;
    }
    try {
      await navigator.clipboard.writeText(txt);
      setStatus("Attribution copied to clipboard.");
    } catch (err) {
      console.warn("provenance copy failed:", err);
      setStatus("Copy failed — select the text manually.", true);
    }
  });
}
clipEditTitle.addEventListener("keydown", (e) => {
  // Enter on the title field saves; multi-line note handles Enter natively.
  if (e.key === "Enter") {
    e.preventDefault();
    saveClipEdit();
  }
});

// ----- Notes dialog (v138) -----
// Lightweight focused editor for clip.notes. Opens from the 📝 chip
// in player-actions while a clip is loaded. Saves on close so the
// user doesn't have to remember a Save button mid-thought.
async function openNotesDialog(clipId) {
  if (!clipId) return;
  const clip = await getClip(clipId);
  if (!clip) return;
  _notesEditingClipId = clipId;
  notesDialogTitle.textContent = clip.title || "Notes";
  notesDialogText.value = clip.notes || "";
  notesDialogStatus.textContent = "";
  notesDialog.showModal();
  notesDialogText.focus();
  // v225v4.25 (#373): render the timestamp chip strip + update the
  // "+ Time" button state immediately so users see existing markers
  // and know whether stamping is available right now (depends on
  // whether THIS clip is the one loaded in the player).
  _notesRenderTimestampChips();
  _notesUpdateStampButtonState();
  // Repaint chips every second while the dialog is open so the
  // "currently-playing" highlight tracks playback in real time. Also
  // catches the case where the user starts playing AFTER opening the
  // dialog (e.g. tapped Play in the mini-player while taking notes)
  // — the stamp button transitions from disabled to enabled without
  // a manual refresh. Stopped in the close handler.
  if (_notesTimestampsActiveTracker) {
    clearInterval(_notesTimestampsActiveTracker);
  }
  _notesTimestampsActiveTracker = setInterval(() => {
    _notesRenderTimestampChips();
    _notesUpdateStampButtonState();
  }, 1000);
}

async function _commitNotes() {
  const id = _notesEditingClipId;
  if (!id) return;
  try {
    const newNotes = (notesDialogText.value || "").trim();
    // v223.tn19 (#488): atomic so concurrent absorb can't lose annotations.
    // Mutator returns early via the "did we change anything" flag captured
    // in the closure — if notes unchanged, no write happens.
    let changed = false;
    await _mutateClipAtomic(id, (c) => {
      if ((c.notes || "") === newNotes) return;
      c.notes = newNotes;
      changed = true;
    });
    // Refresh the library so the 📝 card indicator appears/disappears
    // without requiring a reload. Only if we actually wrote.
    if (changed) renderLibrary();
  } catch (e) {
    console.warn("notes save failed:", e);
  }
}

// v225v4.24 (#829): Notes-dialog dictation. Self-contained — doesn't
// touch _voiceRecorder / annotation state; just records mic, runs
// Web Speech for a live transcript, falls back to server Whisper on
// stop, and inserts the resulting text at the textarea's cursor.
// Cap at 120 seconds (longer than the per-sentence VOICE_NOTE_MAX_SEC
// because this is a memo, not an inline reaction).
const NOTES_DICTATE_MAX_SEC = 120;
let _notesDictateRecorder = null;
let _notesDictateChunks = [];
let _notesDictateMime = "";
let _notesDictateStream = null;
let _notesDictateStartedAt = 0;
let _notesDictateTimerInterval = null;
let _notesDictateAutoStopTimer = null;
let _notesDictateRecognition = null;
let _notesDictateTranscriptFinal = "";

function _notesDictateUpdateTimer() {
  const el = document.getElementById("notes-dictate-timer");
  if (!el) return;
  const sec = Math.floor((Date.now() - _notesDictateStartedAt) / 1000);
  const remaining = Math.max(0, NOTES_DICTATE_MAX_SEC - sec);
  const m = Math.floor(sec / 60);
  const s = sec % 60;
  el.textContent = `${m}:${String(s).padStart(2, "0")}`;
  el.hidden = false;
  // Last 10 seconds: tint the timer warning so the user knows time is
  // almost up before the auto-stop fires.
  if (remaining <= 10) el.dataset.warning = "true";
  else delete el.dataset.warning;
}

function _notesDictateSetButtonState(state) {
  const btn = document.getElementById("notes-dialog-dictate");
  if (!btn) return;
  const label = btn.querySelector(".notes-dictate-label");
  const timer = btn.querySelector(".notes-dictate-timer");
  if (state === "recording") {
    btn.dataset.recording = "1";
    delete btn.dataset.busy;
    if (label) label.textContent = "Stop";
    if (timer) timer.hidden = false;
    btn.setAttribute("aria-label", "Stop dictation");
  } else if (state === "transcribing") {
    delete btn.dataset.recording;
    btn.dataset.busy = "1";
    if (label) label.textContent = "Transcribing…";
    if (timer) { timer.hidden = true; timer.textContent = "0:00"; }
  } else {
    delete btn.dataset.recording;
    delete btn.dataset.busy;
    if (label) label.textContent = "Dictate";
    if (timer) { timer.hidden = true; timer.textContent = "0:00"; }
    btn.setAttribute("aria-label", "Dictate notes");
  }
}

function _notesDictateSetStatus(text) {
  const el = document.getElementById("notes-dialog-status");
  if (el) el.textContent = text || "";
}

function _notesDictateInsertText(text) {
  // Insert at the current cursor position, or append if the textarea
  // hasn't been focused. Preserves what the user has already typed;
  // adds a leading space if we're appending mid-sentence so the
  // transcript doesn't run into the existing word.
  const ta = notesDialogText;
  if (!ta || !text) return;
  const trimmed = text.trim();
  if (!trimmed) return;
  const before = ta.value.slice(0, ta.selectionStart || 0);
  const after = ta.value.slice(ta.selectionEnd || 0);
  // Add a space before if there's preceding text on the same line and
  // it doesn't already end in whitespace.
  const sep = before && !/\s$/.test(before) ? " " : "";
  const next = before + sep + trimmed + after;
  // Respect the 10000-char cap so the maxlength doesn't truncate
  // mid-word silently. If the new text would overflow, clip the
  // transcript to fit.
  const MAX = 10000;
  if (next.length > MAX) {
    const allowed = Math.max(0, MAX - before.length - after.length - sep.length);
    const clipped = trimmed.slice(0, allowed);
    ta.value = before + sep + clipped + after;
    _notesDictateSetStatus("Dictated (clipped — notes hit the 10,000-char cap).");
  } else {
    ta.value = next;
    _notesDictateSetStatus(`Dictated ${trimmed.length} chars.`);
  }
  // Move caret to end of inserted text + persist via the standard
  // commit hook so the change isn't lost if the dialog is closed by
  // tab-switching rather than the Close button.
  const caret = before.length + sep.length + trimmed.length;
  try { ta.setSelectionRange(caret, caret); } catch {}
  ta.focus();
  // Schedule a save (notes dialog persists on close, but commit now
  // so we don't lose the dictation if the user navigates away).
  _commitNotes().catch((e) => console.warn("[notes] dictate commit failed:", e));
}

function _notesDictateStartRecognition() {
  // Live transcript via Web Speech API, identical pattern to the
  // annotation voice notes (#470). Continuous mode + auto-restart on
  // unexpected end so a long memo stays captured.
  _notesDictateTranscriptFinal = "";
  const Recog = typeof SpeechRecognition !== "undefined"
    ? SpeechRecognition
    : (typeof webkitSpeechRecognition !== "undefined"
      ? webkitSpeechRecognition
      : null);
  if (!Recog) {
    _notesDictateRecognition = null;
    return;
  }
  try {
    _notesDictateRecognition = new Recog();
  } catch (e) {
    console.warn("[notes-dictate] SR ctor failed:", e);
    _notesDictateRecognition = null;
    return;
  }
  _notesDictateRecognition.continuous = true;
  _notesDictateRecognition.interimResults = true;
  _notesDictateRecognition.lang = (navigator.language || "en-US");
  let interimText = "";
  _notesDictateRecognition.onresult = (event) => {
    interimText = "";
    for (let i = event.resultIndex; i < event.results.length; i++) {
      const res = event.results[i];
      const txt = res[0] && res[0].transcript ? res[0].transcript : "";
      if (res.isFinal) {
        _notesDictateTranscriptFinal =
          (_notesDictateTranscriptFinal + " " + txt).trim();
      } else {
        interimText += txt;
      }
    }
    // Surface partial progress in the status line so the user sees
    // recognition is working before they stop.
    const preview =
      _notesDictateTranscriptFinal +
      (interimText ? " " + interimText.trim() : "");
    if (preview) {
      _notesDictateSetStatus(`Listening: "${preview.slice(-60)}"`);
    }
  };
  _notesDictateRecognition.onerror = (e) => {
    const code = e && e.error ? e.error : "unknown";
    if (code !== "no-speech" && code !== "aborted") {
      console.warn("[notes-dictate] SR error:", code, e);
    }
  };
  _notesDictateRecognition.onend = () => {
    if (_notesDictateRecorder && _notesDictateRecognition) {
      try { _notesDictateRecognition.start(); } catch {}
    }
  };
  try { _notesDictateRecognition.start(); }
  catch (e) { console.warn("[notes-dictate] SR start failed:", e); }
}

function _notesDictateStopRecognition() {
  if (!_notesDictateRecognition) return;
  _notesDictateRecognition.onend = null;
  try { _notesDictateRecognition.stop(); } catch {}
  _notesDictateRecognition = null;
}

async function _notesDictateStart() {
  if (_notesDictateRecorder) {
    _notesDictateStop();
    return;
  }
  if (typeof MediaRecorder === "undefined" ||
      !navigator.mediaDevices ||
      !navigator.mediaDevices.getUserMedia) {
    _notesDictateSetStatus("Dictation needs a browser with mic recording.");
    return;
  }
  try {
    _notesDictateStream =
      await navigator.mediaDevices.getUserMedia({ audio: true });
  } catch (e) {
    console.warn("[notes-dictate] mic permission denied:", e);
    _notesDictateSetStatus("Mic access denied — allow in browser settings.");
    return;
  }
  const preferred = ["audio/webm;codecs=opus", "audio/webm", "audio/mp4", ""];
  let mime = "";
  for (const t of preferred) {
    if (!t || (typeof MediaRecorder.isTypeSupported === "function" &&
               MediaRecorder.isTypeSupported(t))) {
      mime = t;
      break;
    }
  }
  try {
    _notesDictateRecorder = mime
      ? new MediaRecorder(_notesDictateStream, { mimeType: mime })
      : new MediaRecorder(_notesDictateStream);
  } catch (e) {
    console.warn("[notes-dictate] MediaRecorder ctor failed:", e);
    _notesDictateReleaseStream();
    _notesDictateSetStatus("Couldn't start recording on this device.");
    return;
  }
  _notesDictateChunks = [];
  _notesDictateMime = _notesDictateRecorder.mimeType || "audio/webm";
  _notesDictateRecorder.ondataavailable = (ev) => {
    if (ev.data && ev.data.size > 0) _notesDictateChunks.push(ev.data);
  };
  _notesDictateRecorder.onstop = () => _notesDictateFinalize();
  _notesDictateRecorder.start();
  _notesDictateStartedAt = Date.now();
  _notesDictateSetButtonState("recording");
  _notesDictateSetStatus("Listening… click Stop or wait for auto-stop.");
  _notesDictateStartRecognition();
  _notesDictateTimerInterval = setInterval(_notesDictateUpdateTimer, 250);
  _notesDictateAutoStopTimer = setTimeout(
    () => _notesDictateStop(),
    NOTES_DICTATE_MAX_SEC * 1000,
  );
  _notesDictateUpdateTimer();
}

function _notesDictateStop() {
  if (_notesDictateTimerInterval) {
    clearInterval(_notesDictateTimerInterval);
    _notesDictateTimerInterval = null;
  }
  if (_notesDictateAutoStopTimer) {
    clearTimeout(_notesDictateAutoStopTimer);
    _notesDictateAutoStopTimer = null;
  }
  _notesDictateStopRecognition();
  if (_notesDictateRecorder && _notesDictateRecorder.state !== "inactive") {
    try { _notesDictateRecorder.stop(); }
    catch (e) { console.warn("[notes-dictate] stop:", e); }
  }
}

function _notesDictateReleaseStream() {
  if (_notesDictateStream) {
    for (const t of _notesDictateStream.getTracks()) {
      try { t.stop(); } catch {}
    }
  }
  _notesDictateStream = null;
  _notesDictateRecorder = null;
  _notesDictateChunks = [];
  _notesDictateMime = "";
  _notesDictateStartedAt = 0;
}

async function _notesDictateFinalize() {
  // Snapshot what we have BEFORE releasing state so a "Start" tap
  // during the async work doesn't clobber it.
  const blob = new Blob(_notesDictateChunks, { type: _notesDictateMime });
  const mime = _notesDictateMime || "audio/webm";
  const liveTranscript = (_notesDictateTranscriptFinal || "").trim();
  _notesDictateTranscriptFinal = "";
  _notesDictateReleaseStream();

  if (liveTranscript) {
    // Web Speech got us a transcript — use it directly. Free, instant,
    // no network round-trip.
    _notesDictateSetButtonState("idle");
    _notesDictateInsertText(liveTranscript);
    return;
  }
  if (!blob || blob.size === 0) {
    _notesDictateSetButtonState("idle");
    _notesDictateSetStatus("No audio captured.");
    return;
  }
  // No live transcript — fall back to server Whisper. Common case on
  // Android Chrome where the SR's mic-ownership races with
  // MediaRecorder, but also kicks in on Firefox (no SR at all).
  _notesDictateSetButtonState("transcribing");
  _notesDictateSetStatus("Transcribing audio…");
  if (_isOffline()) {
    _notesDictateSetButtonState("idle");
    _notesDictateSetStatus(
      "Offline — couldn't transcribe. Try again when you're back online.",
    );
    return;
  }
  let base64;
  try {
    base64 = await _blobToBase64(blob);
  } catch (e) {
    console.warn("[notes-dictate] base64 encode failed:", e);
    _notesDictateSetButtonState("idle");
    _notesDictateSetStatus("Couldn't encode audio for transcription.");
    return;
  }
  try {
    const res = await fetch("/api/library/transcribe", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ audioB64: base64, mime: mime }),
    });
    if (!res.ok) {
      _notesDictateSetButtonState("idle");
      _notesDictateSetStatus(
        `Couldn't transcribe (HTTP ${res.status}).`,
      );
      return;
    }
    const body = await res.json();
    const text = body && body.transcript
      ? String(body.transcript).trim()
      : "";
    _notesDictateSetButtonState("idle");
    if (text) {
      _notesDictateInsertText(text);
    } else {
      _notesDictateSetStatus("No speech detected.");
    }
  } catch (e) {
    console.warn("[notes-dictate] /transcribe failed:", e);
    _notesDictateSetButtonState("idle");
    _notesDictateSetStatus("Transcription failed — try again.");
  }
}

// v225v4.25 (#373): Timestamped inline notes. Two halves:
//
//   1. Insert button stamps the current playback time into the
//      textarea at the cursor as [m:ss] or [h:mm:ss]. Disabled when
//      no clip is playing because there's no time to stamp. Pairs
//      with Dictate: speak the thought, tap + Time, get a stamped
//      note.
//   2. Live parser scans the textarea for [m:ss] / [h:mm:ss] patterns
//      and renders each as a tappable chip in the strip above the
//      textarea. Tap a chip → seek the player to that time. If a
//      different clip is loaded, load this note's clip first so the
//      seek lands somewhere meaningful.
//
// Why chips rather than rewriting the textarea into a contenteditable:
// the existing edit experience (selection, plain-text paste, undo,
// dictation, the 10,000-char maxlength) all just work because it's a
// textarea. A contenteditable would buy click-in-prose links at the
// cost of breaking those for marginal UX win — the chip strip gives
// 90% of the value (a tappable index of timestamps) with 5% of the
// risk.
const _NOTES_TS_RE = /\[(?:(\d{1,2}):)?(\d{1,2}):(\d{2})\]/g;
let _notesTimestampsDebounce = 0;
let _notesTimestampsActiveTracker = null;

function _notesFormatStamp(totalSec, useHours) {
  totalSec = Math.max(0, Math.floor(totalSec));
  const h = Math.floor(totalSec / 3600);
  const m = Math.floor((totalSec % 3600) / 60);
  const s = totalSec % 60;
  if (useHours || h > 0) {
    return `[${h}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}]`;
  }
  return `[${m}:${String(s).padStart(2, "0")}]`;
}

function _notesParseTimestamps(text) {
  // Returns [{label, sec, start, end}, …]. Validates that minutes <
  // 60 and seconds < 60 — rejects garbage like [99:99] silently so we
  // don't render confusing chips that seek to weird positions.
  if (!text) return [];
  const out = [];
  const seen = new Set();
  _NOTES_TS_RE.lastIndex = 0;
  let m;
  while ((m = _NOTES_TS_RE.exec(text)) !== null) {
    const hRaw = m[1];
    const mPart = Number(m[2]);
    const sPart = Number(m[3]);
    if (sPart >= 60) continue;
    let sec;
    let label;
    if (hRaw != null) {
      const h = Number(hRaw);
      if (mPart >= 60) continue;
      sec = h * 3600 + mPart * 60 + sPart;
      label = `${h}:${String(mPart).padStart(2, "0")}:${String(sPart).padStart(2, "0")}`;
    } else {
      // [m:ss] form — minutes can exceed 60 (e.g. [127:34] for long
      // clips), so don't reject on mPart range here.
      sec = mPart * 60 + sPart;
      label = `${mPart}:${String(sPart).padStart(2, "0")}`;
    }
    // Dedupe — repeated [0:32] in the notes only renders once. Sort
    // happens later when we lay out the strip.
    const key = sec;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ label, sec, start: m.index, end: m.index + m[0].length });
  }
  // Sort by seconds so the chip strip reads in playback order, which
  // is what makes it useful as an index.
  out.sort((a, b) => a.sec - b.sec);
  return out;
}

function _notesRenderTimestampChips() {
  const strip = document.getElementById("notes-timestamps-strip");
  if (!strip) return;
  const items = _notesParseTimestamps(notesDialogText.value || "");
  if (!items.length) {
    strip.hidden = true;
    strip.innerHTML = "";
    return;
  }
  strip.hidden = false;
  // Re-render. Small enough that we just rebuild rather than diff.
  strip.innerHTML = "";
  const isOwnerCurrent = _notesEditingClipId === _currentClipId;
  const playerSec = playerEl && isFinite(playerEl.currentTime)
    ? playerEl.currentTime
    : 0;
  for (const item of items) {
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = "notes-timestamp-chip";
    chip.textContent = item.label;
    chip.title = isOwnerCurrent
      ? `Seek to ${item.label}`
      : `Load this clip and seek to ${item.label}`;
    if (isOwnerCurrent && Math.abs(playerSec - item.sec) < 1.0) {
      chip.dataset.active = "1";
    }
    chip.addEventListener("click", () => _notesSeekToTimestamp(item.sec));
    strip.appendChild(chip);
  }
}

async function _notesSeekToTimestamp(sec) {
  if (!isFinite(sec) || sec < 0) return;
  const targetClipId = _notesEditingClipId;
  if (!targetClipId) return;
  // If a different clip is loaded in the player, switch to this one
  // first so the seek lands on the audio the notes are actually
  // about. Otherwise the user would expect to hear position X of
  // chapter_03 and get position X of whatever's loaded.
  if (_currentClipId !== targetClipId) {
    try {
      await loadClip(targetClipId);
    } catch (e) {
      console.warn("[notes] seek: loadClip failed:", e);
      return;
    }
  }
  try {
    playerEl.currentTime = sec;
    // Auto-play on tap is intuitive — the user clicked the timestamp
    // because they want to listen. Best-effort; browsers may refuse
    // without a recent user gesture (this IS a click, so it usually
    // succeeds, but autoplay quirks can interfere).
    playerEl.play().catch(() => {});
  } catch (e) {
    console.warn("[notes] seek failed:", e);
  }
}

function _notesInsertStampAtCursor() {
  if (!playerEl) return;
  const sec = isFinite(playerEl.currentTime) ? playerEl.currentTime : 0;
  // Choose format based on whether the clip is hour-long (use h:mm:ss
  // even if the current time is under an hour, so all stamps for the
  // same clip have a consistent shape).
  const dur = isFinite(playerEl.duration) ? playerEl.duration : 0;
  const useHours = dur >= 3600 || sec >= 3600;
  const stamp = _notesFormatStamp(sec, useHours);
  const ta = notesDialogText;
  const before = ta.value.slice(0, ta.selectionStart || 0);
  const after = ta.value.slice(ta.selectionEnd || 0);
  const sep = before && !/\s$/.test(before) ? " " : "";
  const insert = sep + stamp;
  if (ta.value.length + insert.length > 10000) {
    _notesDictateSetStatus("Notes are at the 10,000-char cap — clear something first.");
    return;
  }
  ta.value = before + insert + after;
  const caret = before.length + insert.length;
  try { ta.setSelectionRange(caret, caret); } catch {}
  ta.focus();
  _notesDictateSetStatus(`Inserted ${stamp}`);
  // Persist + re-render the chip strip so the new timestamp shows
  // up immediately.
  _commitNotes().catch((e) => console.warn("[notes] stamp commit failed:", e));
  _notesRenderTimestampChips();
}

function _notesUpdateStampButtonState() {
  const btn = document.getElementById("notes-dialog-stamp");
  if (!btn) return;
  // Disabled when there's no live player to read a time from, OR
  // when the loaded clip isn't the one we're editing notes for (in
  // that case the stamp would record the wrong audio's position).
  const hasPlayer = playerEl && isFinite(playerEl.currentTime);
  const sameClip = _notesEditingClipId === _currentClipId;
  btn.disabled = !(hasPlayer && sameClip);
  btn.title = !sameClip && _notesEditingClipId
    ? "Load this clip in the player to stamp times into its notes"
    : "Insert [m:ss] at cursor (from player)";
}

(function _notesTimestampsWire() {
  const ta = document.getElementById("notes-dialog-text");
  const stampBtn = document.getElementById("notes-dialog-stamp");
  if (ta) {
    ta.addEventListener("input", () => {
      // Cheap debounce — every keystroke would re-render on every
      // hold. 120ms feels live without re-renders flooding the DOM
      // during fast typing or dictation insertions.
      if (_notesTimestampsDebounce) clearTimeout(_notesTimestampsDebounce);
      _notesTimestampsDebounce = setTimeout(() => {
        _notesRenderTimestampChips();
        _notesUpdateStampButtonState();
      }, 120);
    });
  }
  if (stampBtn) {
    stampBtn.addEventListener("click", _notesInsertStampAtCursor);
  }
})();

// Wire the button (idempotent — guard against duplicate listeners on
// hot-reload). Hide the button entirely if the browser doesn't support
// MediaRecorder so we don't surface a control that can't work.
(function _notesDictateWire() {
  const btn = document.getElementById("notes-dialog-dictate");
  if (!btn) return;
  if (typeof MediaRecorder === "undefined" ||
      !navigator.mediaDevices ||
      !navigator.mediaDevices.getUserMedia) {
    btn.hidden = true;
    return;
  }
  btn.addEventListener("click", () => {
    if (_notesDictateRecorder) _notesDictateStop();
    else _notesDictateStart();
  });
})();

notesBtn.addEventListener("click", () => {
  if (!_currentClipId) {
    setStatus("Load a clip first to open its notes.", true);
    return;
  }
  openNotesDialog(_currentClipId);
  // v225fm (#655): first-tap hint distinguishes clip-wide Notes
  // from per-sentence bookmarks/flags so users don't conflate them.
  if (typeof _fireChipHint === "function") {
    _fireChipHint(
      "narrative.hintSeen.notes",
      "💡 Notes are free-form thoughts about the whole clip. For per-moment thoughts, use 🔖 Bookmark.",
    );
  }
});

// ────────────────────────────────────────────────────────────────────────
// v225dr: Markdown export — current clip's notes + bookmarks + annotations.
// Author-facing format, deliberately readable: pastes cleanly into
// Scrivener, Obsidian, an editor's inbox, or a notes-only GitHub
// commit (Phase 2 round-trip, not built yet — see task #538).
// ────────────────────────────────────────────────────────────────────────

function _msToClockMd(sec) {
  // Bookmarks store time in seconds; annotations use sentence offsets
  // that we lift from sentenceOffsetsSec when present. Format as
  // m:ss (or h:mm:ss for clips >1h). Bare-bones — author readability
  // beats precision past whole seconds for revision notes.
  if (typeof sec !== "number" || !isFinite(sec) || sec < 0) return "?";
  const total = Math.floor(sec);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  const pad = (n) => String(n).padStart(2, "0");
  return h > 0 ? `${h}:${pad(m)}:${pad(s)}` : `${m}:${pad(s)}`;
}

function _slugifyForFilename(s) {
  return (s || "untitled")
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[̀-ͯ]/g, "")    // strip accents
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 60) || "untitled";
}

function _mdEscape(s) {
  // Keep the prose readable — only escape characters that would
  // actively break Markdown rendering in a way the author wouldn't
  // expect. We do NOT escape underscores or asterisks inside the
  // sentence quote; that would mangle italics the author wrote on
  // purpose. Backticks would create code spans, so neutralize those.
  return String(s == null ? "" : s).replace(/`/g, "\\`");
}

function _buildClipNotesMarkdown(clip) {
  const title = (clip.title || "Untitled").trim();
  const v = (typeof _currentAppVersion === "function")
    ? _currentAppVersion() : "?";
  const dateStr = new Date().toISOString().slice(0, 10);
  const durStr = (typeof clip.durationSec === "number" && clip.durationSec > 0)
    ? _msToClockMd(clip.durationSec) + " audio"
    : "";

  const lines = [];
  lines.push(`# ${title}`);
  lines.push("");
  lines.push(
    `*Exported from Narrative ${v} · ${dateStr}` +
    (durStr ? ` · ${durStr}` : "") +
    "*"
  );
  lines.push("");

  // ─ Notes ─────────────────────────────────────────────────────────
  const freeNotes = (clip.notes || "").trim();
  if (freeNotes) {
    lines.push("## Notes");
    lines.push("");
    lines.push(freeNotes);
    lines.push("");
  }

  // ─ Bookmarks ─────────────────────────────────────────────────────
  // v225dv: bookmarks store the time under `timeSec`, not `time`. The
  // initial export read the wrong field and every row rendered as
  // "**?** — <note>". Confirmed via clip.bookmarks schema at
  // addBookmarkAtCurrentTime (line ~3838).
  const bms = Array.isArray(clip.bookmarks)
    ? clip.bookmarks
        .slice()
        .sort((a, b) => (a.timeSec || 0) - (b.timeSec || 0))
    : [];
  if (bms.length) {
    lines.push("## Bookmarks");
    lines.push("");
    for (const bm of bms) {
      const ts = _msToClockMd(bm.timeSec);
      const note = (bm.note || "").trim();
      lines.push(
        note
          ? `- **${ts}** — ${_mdEscape(note)}`
          : `- **${ts}**`
      );
    }
    lines.push("");
  }

  // ─ Annotations ───────────────────────────────────────────────────
  // Drop tombstoned rows; sort by sentence index so the export
  // matches reading order, not flag-order.
  const annoAll = Array.isArray(clip.annotations) ? clip.annotations : [];
  const annos = annoAll
    .filter((a) => a && !a.deletedAt)
    .sort((a, b) => (a.sentenceIndex || 0) - (b.sentenceIndex || 0));

  if (annos.length) {
    lines.push("## Annotations");
    lines.push("");
    // ANNOTATE_TAGS is defined ~line 12097 — same icon+label mapping
    // the UI uses, so the export matches what the author sees.
    const tagInfo = (typeof ANNOTATE_TAGS !== "undefined" && ANNOTATE_TAGS)
      ? ANNOTATE_TAGS
      : {};
    const offsetsSec = Array.isArray(clip.sentenceOffsetsSec)
      ? clip.sentenceOffsetsSec : [];
    for (const a of annos) {
      const idx = (typeof a.sentenceIndex === "number") ? a.sentenceIndex : -1;
      const tsec = (idx >= 0 && idx < offsetsSec.length) ? offsetsSec[idx] : null;
      const ts = (tsec != null) ? ` · ~${_msToClockMd(tsec)}` : "";
      lines.push(`### Sentence ${idx + 1}${ts}`);
      // v225dx: tag line moved ABOVE the sentence quote. Reading
      // flow: heading → what kind of note this is → what sentence
      // it's on → optional voice-note transcript. Easier to scan a
      // long revision list — "what's the flag?" answers in the
      // first line under each heading.
      //
      // v225dv: annotations store the flag(s) under `tags` (an
      // array), not `tag` singular. Confirmed via the addAnnotation
      // callers at lines 12681, 13542, 22433 which all push
      // `tags: [tagKey]`. Voice-note annotations carry
      // `tags: ["voice"]` so we map that to a friendly label.
      const tagsArr = Array.isArray(a.tags)
        ? a.tags
        : (a.tag ? [a.tag] : []);   // backwards-compat for any
                                    // pre-tags-array stored rows
      const tagLines = [];
      for (const t of tagsArr) {
        const meta = t && tagInfo[t];
        if (meta) {
          tagLines.push(`${meta.icon} **${meta.label}**`);
        } else if (t === "voice") {
          tagLines.push("🎤 **Voice note**");
        } else if (t) {
          tagLines.push(`**${_mdEscape(t)}**`);
        }
      }
      if (tagLines.length) {
        lines.push(tagLines.join("  ·  "));
        lines.push("");
      }
      // v225dw: prefer the FULL sentence text over the 60-char
      // fingerprint. The fingerprint is a hash-ish prefix used by
      // the reanchor-on-re-narrate path, not the human-readable
      // form. When the clip being exported is the currently-loaded
      // one (always true in v1 since the button only acts on
      // _currentClipId), each sentenceSpans entry carries the raw
      // sentence text in its dataset — that's our preferred
      // source. Fingerprint stays as a fallback.
      const liveSpan =
        clip.id === _currentClipId &&
        Array.isArray(sentenceSpans) &&
        sentenceSpans[idx];
      const sentText = (
        (liveSpan && liveSpan.dataset && liveSpan.dataset.sentenceText) ||
        a.sentenceText ||
        a.sentenceFingerprint ||
        ""
      ).trim();
      if (sentText) {
        lines.push(`> ${_mdEscape(sentText)}`);
        lines.push("");
      }
      const transcript = (a.transcript || "").trim();
      if (transcript) {
        lines.push(`> ${_mdEscape(transcript)} *(voice note)*`);
        lines.push("");
      }
    }
  }

  // Empty-state — only the header, nothing else. Better than a stray
  // dangling title with no content underneath.
  if (!freeNotes && !bms.length && !annos.length) {
    lines.push("*No notes, bookmarks, or annotations on this clip yet.*");
    lines.push("");
  }

  // v225fz5 (#672): append a hidden backup block so the .md can
  // round-trip — i.e. the same file the Clear-marks flow exports as
  // a safety net is also a valid restore source. The block is an
  // HTML comment so it never renders in a markdown viewer; the
  // payload is base64-encoded JSON so user content with stray "-->"
  // or special chars can't break the parser. Schema below is what
  // _parseClipBackup / _restoreClipMarks expect.
  try {
    const backup = {
      version: 1,
      clipId: clip.id,
      title: clip.title || "",
      exportedAt: new Date().toISOString(),
      // Bookmarks have no tombstones — array contains live entries only.
      bookmarks: Array.isArray(clip.bookmarks) ? clip.bookmarks : [],
      // Export LIVE annotations only. Tombstoned entries shouldn't
      // come back on restore — they'd just re-tombstone and silently
      // hide. Restoring them as live again would defeat the previous
      // clear/delete.
      annotations: (Array.isArray(clip.annotations) ? clip.annotations : [])
        .filter((a) => a && !a.deletedAt),
      notes: typeof clip.notes === "string" ? clip.notes : "",
    };
    const payload = JSON.stringify(backup);
    // btoa() handles ASCII; JSON.stringify already escapes non-ASCII
    // to \uXXXX, so the payload is always ASCII. Encoding will not
    // throw on user content.
    const b64 = btoa(payload);
    lines.push("");
    lines.push("<!--NARRATIVE_BACKUP v1");
    lines.push(b64);
    lines.push("-->");
  } catch (e) {
    // If anything in the backup-block construction blows up, ship the
    // human-readable part anyway. The .md is still useful as a
    // reference even if it can't be restored from.
    console.warn("[md-export] backup block skipped:", e);
  }

  // Strip trailing blank line so the file ends with the last real
  // line + a single newline.
  while (lines.length && lines[lines.length - 1] === "") lines.pop();
  return lines.join("\n") + "\n";
}

// v225fz5 (#672): extract the backup payload from an exported .md.
// Returns the decoded object on success, or null if the file isn't a
// Narrative backup (missing the marker, malformed base64, JSON parse
// failure, or wrong schema version). The marker pattern is anchored on
// our literal "NARRATIVE_BACKUP v1" string so any reasonable .md file
// the user picks by mistake just returns null without throwing.
function _parseClipBackupFromMd(mdText) {
  if (typeof mdText !== "string") return null;
  // Tolerate trailing whitespace + CRLF line endings — users on
  // Windows opening + re-saving the .md in Notepad will introduce
  // both. The capturing group grabs base64 chars + newlines; we
  // strip whitespace before decoding.
  const m = mdText.match(
    /<!--NARRATIVE_BACKUP v1\s+([A-Za-z0-9+/=\s]+?)\s*-->/,
  );
  if (!m) return null;
  let json;
  try {
    json = atob(m[1].replace(/\s+/g, ""));
  } catch (e) {
    console.warn("[md-restore] base64 decode failed:", e);
    return null;
  }
  let obj;
  try {
    obj = JSON.parse(json);
  } catch (e) {
    console.warn("[md-restore] JSON parse failed:", e);
    return null;
  }
  if (!obj || obj.version !== 1) {
    console.warn("[md-restore] unexpected schema version:", obj && obj.version);
    return null;
  }
  return obj;
}

// v225fz5 (#672): apply a parsed backup to a clip. Two modes:
//
//   - "replace" (default after a Clear-marks flow): the backup's
//     bookmarks/annotations/notes overwrite whatever's on the clip
//     now. Right answer for the canonical "undo a clear" case.
//
//   - "add": append the backup's marks alongside existing ones,
//     deduping by id when present so the same backup applied twice
//     doesn't double up. Right answer when the user is reviving an
//     older backup but has done new work in the meantime they want
//     to keep.
//
// Returns the counts of what landed so the caller can toast it.
async function _restoreClipMarks(clipId, backup, mode) {
  if (clipId == null || !backup) return null;
  const isAdd = mode === "add";
  const landed = { bookmarks: 0, annotations: 0, notes: 0 };
  const now = new Date().toISOString();
  try {
    await _mutateClipAtomic(clipId, (c) => {
      // ─ Bookmarks ─────────────────────────────────────────────────
      const incomingBms = Array.isArray(backup.bookmarks)
        ? backup.bookmarks
        : [];
      if (isAdd) {
        const existing = Array.isArray(c.bookmarks) ? c.bookmarks : [];
        const seenIds = new Set(existing.map((b) => b && b.id).filter(Boolean));
        const fresh = incomingBms.filter(
          (b) => b && (!b.id || !seenIds.has(b.id)),
        );
        c.bookmarks = existing.concat(fresh);
        landed.bookmarks = fresh.length;
      } else {
        c.bookmarks = incomingBms.slice();
        landed.bookmarks = incomingBms.length;
      }
      // ─ Annotations ───────────────────────────────────────────────
      // Backup-exported annotations have NO deletedAt by construction
      // (we filtered them out at export). Bump updatedAt to now so
      // the server-side merge prefers our restored copy over any
      // stale ghost record on another device.
      const incomingAnnos = (
        Array.isArray(backup.annotations) ? backup.annotations : []
      ).map((a) => ({ ...a, deletedAt: undefined, updatedAt: now }));
      if (isAdd) {
        const existing = Array.isArray(c.annotations) ? c.annotations : [];
        const seenIds = new Set(existing.map((a) => a && a.id).filter(Boolean));
        const fresh = incomingAnnos.filter(
          (a) => a && (!a.id || !seenIds.has(a.id)),
        );
        c.annotations = existing.concat(fresh);
        landed.annotations = fresh.length;
      } else {
        c.annotations = incomingAnnos;
        landed.annotations = incomingAnnos.length;
      }
      // ─ Notes ─────────────────────────────────────────────────────
      // Notes is a single field, so "add" doesn't really mean
      // anything; we append the backup notes onto current with a
      // separator, but only if both are non-empty. Replace mode
      // overwrites.
      const backupNotes = typeof backup.notes === "string"
        ? backup.notes.trim()
        : "";
      if (backupNotes) {
        if (isAdd) {
          const existing = typeof c.notes === "string" ? c.notes.trim() : "";
          c.notes = existing
            ? `${existing}\n\n---\n\n${backupNotes}`
            : backupNotes;
        } else {
          c.notes = backupNotes;
        }
        landed.notes = 1;
      } else if (!isAdd) {
        // Replace mode + empty backup notes → clear the field. Matches
        // the export's snapshot: "this clip had no notes at the time."
        c.notes = "";
      }
    });
  } catch (e) {
    console.warn("[md-restore] mutation failed:", e);
    return null;
  }
  // Same multi-surface refresh as _clearClipMarks — same need to
  // repaint reading view chips, drawer rows, library cards, panes.
  if (
    _currentClipId === clipId &&
    typeof _applyAnnotationMarkers === "function"
  ) {
    try {
      const clip = await getClip(clipId);
      if (clip) _applyAnnotationMarkers(clip);
    } catch (e) {
      console.warn("[md-restore] annotation repaint failed:", e);
    }
  }
  if (_currentClipId === clipId && typeof renderBookmarks === "function") {
    try { await renderBookmarks(); } catch {}
  }
  if (typeof renderLibrary === "function") {
    try { renderLibrary(); } catch {}
  }
  if (typeof _renderAuthorPane === "function") {
    try { _renderAuthorPane(); } catch {}
  }
  if (typeof _updatePullupState === "function") {
    try { _updatePullupState(); } catch {}
  }
  _dlog("md-restore", "done", { clipId, mode: isAdd ? "add" : "replace", ...landed });
  return landed;
}

const exportNotesBtn = document.getElementById("export-notes-btn");
// v225fz3 (#670): optional clipId arg so the clear-marks flow can
// export ANY clip (not just the currently-loaded one). When omitted,
// behavior is unchanged — falls back to _currentClipId as before.
// Returns true on success, false on any error / no clip / no data;
// caller can use the result to decide whether to proceed with a
// dependent destructive action.
async function _exportClipNotes(clipId) {
  const targetId = clipId != null ? clipId : _currentClipId;
  if (!targetId) {
    setStatus("Load a clip first to export its notes.", true);
    return false;
  }
  let clip;
  try {
    clip = await getClip(targetId);
  } catch (e) {
    setStatus(`Couldn't read clip — ${e.message || e}`, true);
    return false;
  }
  if (!clip) {
    setStatus("Clip not found.", true);
    return false;
  }
  const md = _buildClipNotesMarkdown(clip);
  const blob = new Blob([md], { type: "text/markdown;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  const slug = _slugifyForFilename(clip.title);
  const date = new Date().toISOString().slice(0, 10);
  a.href = url;
  a.download = `${slug}-notes-${date}.md`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  setStatus("Notes exported.");
  return true;
}
if (exportNotesBtn) {
  exportNotesBtn.addEventListener("click", () => _exportClipNotes());
}

// v225fz3 (#670): "Clear revision marks" — author workflow completion
// action. After applying edits to the source manuscript, wipe the
// clip's bookmarks + annotations + free-form notes so the next
// listen-through starts clean. NOT cleared: book-view highlights
// (they're a reading mark, not a revision mark — user's call in #670)
// and voice/character assignments (they're clip configuration).
//
// Honors per-category opt-out: opts.bookmarks / opts.annotations /
// opts.notes default to true; flip any to false to preserve that
// category. Annotations get the tombstone treatment (deletedAt on
// each, not array-filter) so the cleared state propagates cross-
// device — mirrors the single-delete path in _tombstoneAnnotation
// (#498). Bookmarks array-filter is fine — they don't have the
// server-side merge intent annotations got in #495.
//
// Returns the cleared counts so the caller can show a status toast.
async function _clearClipMarks(clipId, opts) {
  if (clipId == null) return null;
  const o = opts || {};
  const clearBookmarks = o.bookmarks !== false;
  const clearAnnotations = o.annotations !== false;
  const clearNotes = o.notes !== false;
  const cleared = { bookmarks: 0, annotations: 0, notes: 0 };
  const now = new Date().toISOString();
  let clipForSync = null;
  try {
    clipForSync = await _mutateClipAtomic(clipId, (c) => {
      if (clearBookmarks && Array.isArray(c.bookmarks)) {
        cleared.bookmarks = c.bookmarks.length;
        c.bookmarks = [];
      }
      if (clearAnnotations && Array.isArray(c.annotations)) {
        // Count live (non-deleted) entries only — already-tombstoned
        // ones shouldn't inflate the "cleared 47" toast.
        const live = c.annotations.filter((a) => a && !a.deletedAt);
        cleared.annotations = live.length;
        // Tombstone each live entry. Keep the entry in the array so
        // the server-side merge sees deletedAt and propagates the
        // delete; _mutateClipAtomic's saveClip will push it.
        c.annotations = c.annotations.map((a) => {
          if (!a || a.deletedAt) return a;
          return { ...a, deletedAt: now, updatedAt: now };
        });
      }
      if (clearNotes && typeof c.notes === "string" && c.notes.trim()) {
        cleared.notes = 1;
        c.notes = "";
      }
    });
  } catch (e) {
    console.warn("[clear-marks] mutation failed:", e);
    return null;
  }
  // Repaint the reading view's annotation chips so cleared flags
  // disappear immediately (not just on next clip-load). Mirrors the
  // pattern in _removeAnnotation / _tombstoneAnnotation.
  if (
    clearAnnotations &&
    _currentClipId === clipId &&
    clipForSync &&
    typeof _applyAnnotationMarkers === "function"
  ) {
    try { _applyAnnotationMarkers(clipForSync); } catch (e) {
      console.warn("[clear-marks] annotation repaint failed:", e);
    }
  }
  // Refresh the bookmark drawer + ribbon if we cleared bookmarks AND
  // the loaded clip is the one we cleared.
  if (
    clearBookmarks &&
    _currentClipId === clipId &&
    typeof renderBookmarks === "function"
  ) {
    try { await renderBookmarks(); } catch (e) {
      console.warn("[clear-marks] bookmark repaint failed:", e);
    }
  }
  // Library + author pane + pull-up author counts all read from the
  // mutated clip on next render.
  if (typeof renderLibrary === "function") {
    try { renderLibrary(); } catch {}
  }
  if (typeof _renderAuthorPane === "function") {
    try { _renderAuthorPane(); } catch {}
  }
  if (typeof _updatePullupState === "function") {
    try { _updatePullupState(); } catch {}
  }
  _dlog("clear-marks", "done", { clipId, ...cleared });
  return cleared;
}

// v225fz3 (#670): clear-marks dialog wiring. Opened from the Edit
// clip dialog's "Clear marks…" button OR the command palette
// "act:clear-marks" entry. Populates counts from the target clip,
// remembers the user's last "Export first?" preference, and on
// confirm: exports the .md (if checked) THEN clears (if export
// succeeded or was skipped). The export-then-clear order matters
// — if export throws, we don't wipe the data.
const _CLEAR_MARKS_EXPORT_PREF_KEY = "narrative.clearMarks.exportFirst";
let _clearMarksDialogBound = false;
let _clearMarksCurrentClipId = null;

function _initClearMarksDialog() {
  if (_clearMarksDialogBound) return;
  const dlg = document.getElementById("clear-marks-confirm");
  if (!dlg) return;
  _clearMarksDialogBound = true;
  const close = () => {
    if (dlg.open) dlg.close();
    _clearMarksCurrentClipId = null;
  };
  dlg
    .querySelector("#clear-marks-close")
    .addEventListener("click", close);
  dlg
    .querySelector("#clear-marks-cancel")
    .addEventListener("click", close);
  dlg.addEventListener("click", (e) => {
    if (e.target === dlg) close();
  });
  const confirmBtn = dlg.querySelector("#clear-marks-confirm-btn");
  confirmBtn.addEventListener("click", async () => {
    const clipId = _clearMarksCurrentClipId;
    if (clipId == null) return;
    const bookmarks = dlg.querySelector("#clear-marks-cat-bookmarks").checked;
    const annotations = dlg.querySelector("#clear-marks-cat-annotations").checked;
    const notes = dlg.querySelector("#clear-marks-cat-notes").checked;
    const exportFirst = dlg.querySelector("#clear-marks-export-first").checked;
    try {
      localStorage.setItem(
        _CLEAR_MARKS_EXPORT_PREF_KEY,
        exportFirst ? "1" : "0",
      );
    } catch {}
    // Nothing to do — silently close (don't pop a toast that'd feel
    // like a phantom action).
    if (!bookmarks && !annotations && !notes) {
      close();
      return;
    }
    confirmBtn.disabled = true;
    if (exportFirst) {
      const ok = await _exportClipNotes(clipId);
      if (!ok) {
        // _exportClipNotes already set an error status. Don't proceed
        // to clear — the safety net failed.
        confirmBtn.disabled = false;
        return;
      }
    }
    const cleared = await _clearClipMarks(clipId, {
      bookmarks,
      annotations,
      notes,
    });
    // v225fz7 (#673): if the Edit clip dialog is still open on this
    // clip (it stays open behind the confirm modal), repaint its
    // notes textarea from IDB so a subsequent Save can't write back
    // the stale pre-clear content.
    if (typeof _resyncClipEditFromIDB === "function") {
      try { await _resyncClipEditFromIDB(); } catch {}
    }
    confirmBtn.disabled = false;
    close();
    if (cleared) {
      const parts = [];
      if (cleared.bookmarks)
        parts.push(`${cleared.bookmarks} bookmark${cleared.bookmarks === 1 ? "" : "s"}`);
      if (cleared.annotations)
        parts.push(`${cleared.annotations} annotation${cleared.annotations === 1 ? "" : "s"}`);
      if (cleared.notes) parts.push("notes");
      setStatus(
        parts.length
          ? `Cleared ${parts.join(", ")}.`
          : "Nothing to clear.",
      );
    }
  });
  document.addEventListener("keydown", (e) => {
    if (!dlg.open) return;
    if (e.key === "Escape") {
      e.preventDefault();
      close();
    }
  });
}

// v225fz5 (#672): restore-marks confirm dialog wiring. Mirrors the
// init/open shape of the clear-marks dialog. Targets a specific clip
// (passed in by caller) — usually _editingClipId for the Edit-dialog
// path, or _currentClipId for the command palette path.
let _restoreMarksDialogBound = false;
let _restoreMarksCurrentClipId = null;
let _restoreMarksCurrentBackup = null;

function _initRestoreMarksDialog() {
  if (_restoreMarksDialogBound) return;
  const dlg = document.getElementById("restore-marks-confirm");
  if (!dlg) return;
  _restoreMarksDialogBound = true;
  const close = () => {
    if (dlg.open) dlg.close();
    _restoreMarksCurrentClipId = null;
    _restoreMarksCurrentBackup = null;
  };
  dlg.querySelector("#restore-marks-close").addEventListener("click", close);
  dlg.querySelector("#restore-marks-cancel").addEventListener("click", close);
  dlg.addEventListener("click", (e) => {
    if (e.target === dlg) close();
  });
  const confirmBtn = dlg.querySelector("#restore-marks-confirm-btn");
  confirmBtn.addEventListener("click", async () => {
    const clipId = _restoreMarksCurrentClipId;
    const backup = _restoreMarksCurrentBackup;
    if (clipId == null || !backup) return;
    const modeInput = dlg.querySelector(
      "input[name='restore-marks-mode']:checked",
    );
    const mode = modeInput ? modeInput.value : "replace";
    confirmBtn.disabled = true;
    const landed = await _restoreClipMarks(clipId, backup, mode);
    // v225fz7 (#673): same reason as the clear path — repaint the
    // Edit dialog's notes textarea from IDB so a subsequent Save
    // doesn't clobber the restored content.
    if (typeof _resyncClipEditFromIDB === "function") {
      try { await _resyncClipEditFromIDB(); } catch {}
    }
    confirmBtn.disabled = false;
    close();
    if (landed) {
      const parts = [];
      if (landed.bookmarks)
        parts.push(`${landed.bookmarks} bookmark${landed.bookmarks === 1 ? "" : "s"}`);
      if (landed.annotations)
        parts.push(`${landed.annotations} annotation${landed.annotations === 1 ? "" : "s"}`);
      if (landed.notes) parts.push("notes");
      setStatus(
        parts.length
          ? `Restored ${parts.join(", ")}.`
          : "Nothing to restore.",
      );
    } else {
      setStatus("Restore failed.", true);
    }
  });
  document.addEventListener("keydown", (e) => {
    if (!dlg.open) return;
    if (e.key === "Escape") {
      e.preventDefault();
      close();
    }
  });
}

async function _openRestoreMarksConfirm(clipId, backup) {
  _initRestoreMarksDialog();
  const dlg = document.getElementById("restore-marks-confirm");
  if (!dlg) return;
  let targetClip;
  try {
    targetClip = await getClip(clipId);
  } catch (e) {
    setStatus(`Couldn't read clip — ${e.message || e}`, true);
    return;
  }
  if (!targetClip) {
    setStatus("Clip not found.", true);
    return;
  }
  _restoreMarksCurrentClipId = clipId;
  _restoreMarksCurrentBackup = backup;
  // Header: which clip is the backup FROM (title at export time +
  // a friendly export date if we have one). The exportedAt is stored
  // as ISO; trim to date for display.
  dlg.querySelector("#restore-marks-source-title").textContent =
    backup.title || "a clip";
  const dateEl = dlg.querySelector("#restore-marks-source-date");
  if (backup.exportedAt) {
    const d = backup.exportedAt.slice(0, 10);
    dateEl.textContent = `(exported ${d})`;
  } else {
    dateEl.textContent = "";
  }
  // Cross-clip warning: backup.clipId vs target clipId. The backup
  // can still be applied — copying marks across clips is a real
  // use-case — but the author should know they're doing it.
  const mismatchEl = dlg.querySelector("#restore-marks-mismatch");
  const sameClip = backup.clipId && backup.clipId === clipId;
  if (sameClip) {
    mismatchEl.hidden = true;
  } else {
    mismatchEl.hidden = false;
    dlg.querySelector("#restore-marks-target-title").textContent =
      targetClip.title || "this clip";
  }
  // Counts — straight from the backup payload.
  const bmCount = Array.isArray(backup.bookmarks) ? backup.bookmarks.length : 0;
  const annoCount = Array.isArray(backup.annotations)
    ? backup.annotations.length
    : 0;
  const notesLen = typeof backup.notes === "string"
    ? backup.notes.trim().length
    : 0;
  dlg.querySelector("#restore-marks-count-bookmarks").textContent = String(bmCount);
  dlg.querySelector("#restore-marks-count-annotations").textContent = String(annoCount);
  dlg.querySelector("#restore-marks-count-notes").textContent = notesLen
    ? `${notesLen} char${notesLen === 1 ? "" : "s"}`
    : "—";
  // Reset radio to Replace each time (matches the most common case
  // right after a Clear; Add is an opt-in second choice).
  const replaceRadio = dlg.querySelector(
    "input[name='restore-marks-mode'][value='replace']",
  );
  if (replaceRadio) replaceRadio.checked = true;
  // Disable confirm when there's nothing to restore.
  const anyRestorable = bmCount > 0 || annoCount > 0 || notesLen > 0;
  dlg.querySelector("#restore-marks-confirm-btn").disabled = !anyRestorable;
  if (!dlg.open) dlg.showModal();
}

async function _openClearMarksConfirm(clipId) {
  _initClearMarksDialog();
  const dlg = document.getElementById("clear-marks-confirm");
  if (!dlg) return;
  let clip;
  try {
    clip = await getClip(clipId);
  } catch (e) {
    setStatus(`Couldn't read clip — ${e.message || e}`, true);
    return;
  }
  if (!clip) {
    setStatus("Clip not found.", true);
    return;
  }
  _clearMarksCurrentClipId = clipId;
  const titleEl = dlg.querySelector("#clear-marks-clip-title");
  if (titleEl) titleEl.textContent = clip.title || "this clip";
  // Count LIVE (non-tombstoned) annotations only — already-deleted
  // ones shouldn't show in the preview.
  const bmCount = Array.isArray(clip.bookmarks) ? clip.bookmarks.length : 0;
  const annoCount = Array.isArray(clip.annotations)
    ? clip.annotations.filter((a) => a && !a.deletedAt).length
    : 0;
  const notesText = typeof clip.notes === "string" ? clip.notes.trim() : "";
  const notesLen = notesText.length;
  dlg.querySelector("#clear-marks-count-bookmarks").textContent = String(bmCount);
  dlg.querySelector("#clear-marks-count-annotations").textContent = String(annoCount);
  dlg.querySelector("#clear-marks-count-notes").textContent = notesLen
    ? `${notesLen} char${notesLen === 1 ? "" : "s"}`
    : "—";
  // Pre-check checkboxes based on what actually exists — no point
  // checking "Annotations" when there are zero. Per-category default
  // also disables that row so the toggle reads as "this is empty,
  // not just unchecked."
  const bmInput = dlg.querySelector("#clear-marks-cat-bookmarks");
  const annoInput = dlg.querySelector("#clear-marks-cat-annotations");
  const notesInput = dlg.querySelector("#clear-marks-cat-notes");
  bmInput.checked = bmCount > 0;
  bmInput.disabled = bmCount === 0;
  annoInput.checked = annoCount > 0;
  annoInput.disabled = annoCount === 0;
  notesInput.checked = notesLen > 0;
  notesInput.disabled = notesLen === 0;
  // Restore the user's last "Export first?" preference. Defaults to
  // ON because the .md is the artifact they take to their source.
  const expInput = dlg.querySelector("#clear-marks-export-first");
  let expPref = "1";
  try {
    const stored = localStorage.getItem(_CLEAR_MARKS_EXPORT_PREF_KEY);
    if (stored === "0" || stored === "1") expPref = stored;
  } catch {}
  expInput.checked = expPref === "1";
  // Disable confirm if nothing is actually clearable — empty clip
  // shouldn't let the author hit a destructive button that does
  // nothing.
  const anyClearable = bmCount > 0 || annoCount > 0 || notesLen > 0;
  dlg.querySelector("#clear-marks-confirm-btn").disabled = !anyClearable;
  if (!dlg.open) dlg.showModal();
}

// ───────────────────────────────────────────────────────────────────
// v225v4.0 (#810): Author-mode per-sentence storage — Phase A.
// Conversion modal + Edit-dialog status painter. The schema and
// merge logic live server-side (see library_db.py v5 + _merge_lines
// in library_api.py); the hash + ID helpers are in
// static/sentence-ids.js (twin of sentence_ids.py); the design is
// in SENTENCE_IDS.md. This block is just the UX: clip-level toggle,
// confirm modal, conversion transaction.
// ───────────────────────────────────────────────────────────────────

let _linesConvertCurrentClipId = null;
let _linesConvertWired = false;

function _initLinesConvertDialog() {
  if (_linesConvertWired) return;
  _linesConvertWired = true;
  const dlg = document.getElementById("lines-convert-confirm");
  if (!dlg) return;
  const close = () => {
    _linesConvertCurrentClipId = null;
    dlg.close();
  };
  dlg.querySelector("#lines-convert-close").addEventListener("click", close);
  dlg.querySelector("#lines-convert-cancel").addEventListener("click", close);
  // Click outside (on the backdrop) cancels — match #clear-marks-confirm.
  dlg.addEventListener("click", (e) => {
    if (e.target === dlg) close();
  });
  const confirmBtn = dlg.querySelector("#lines-convert-confirm-btn");
  confirmBtn.addEventListener("click", async () => {
    const clipId = _linesConvertCurrentClipId;
    if (clipId == null) return;
    confirmBtn.disabled = true;
    try {
      const ok = await _runLinesConversion(clipId, dlg);
      if (!ok) {
        // Error already surfaced via setStatus; leave the modal open so
        // the user can retry or cancel.
        confirmBtn.disabled = false;
        return;
      }
    } catch (e) {
      console.warn("[lines-convert] failed:", e);
      setStatus(`Couldn't enable line-by-line storage — ${e.message || e}`, true);
      confirmBtn.disabled = false;
      return;
    }
    close();
  });
}

async function _openLinesConvertConfirm(clipId) {
  _initLinesConvertDialog();
  const dlg = document.getElementById("lines-convert-confirm");
  if (!dlg) return;
  let clip;
  try {
    clip = await getClip(clipId);
  } catch (e) {
    setStatus(`Couldn't read clip — ${e.message || e}`, true);
    return;
  }
  if (!clip) {
    setStatus("Clip not found.", true);
    return;
  }
  if (Array.isArray(clip.lines) && clip.lines.length > 0) {
    // Defensive: shouldn't be reachable since the Enable button is
    // hidden in this state, but avoid double-applying if it is.
    setStatus("This clip already uses line-by-line storage.");
    return;
  }
  _linesConvertCurrentClipId = clipId;
  // Sentence count for the headline. Use the same splitter we'll run at
  // conversion time so the preview matches the result exactly.
  const sentences = splitSentencesClient(clip.text || "");
  const sentenceCount = sentences.length;
  dlg.querySelector("#lines-convert-clip-title").textContent =
    clip.title || "this clip";
  dlg.querySelector("#lines-convert-sentence-count").textContent =
    `${sentenceCount} sentence${sentenceCount === 1 ? "" : "s"}`;
  // Count what gets dropped. Annotations: live (non-tombstoned) only.
  // Voice assignments: count keys on the sentenceAssignments object.
  const annoCount = Array.isArray(clip.annotations)
    ? clip.annotations.filter((a) => a && !a.deletedAt).length
    : 0;
  const assignCount = clip.sentenceAssignments &&
    typeof clip.sentenceAssignments === "object"
    ? Object.keys(clip.sentenceAssignments).length
    : 0;
  const anyLoss = annoCount > 0 || assignCount > 0;
  const lossBlock = dlg.querySelector("#lines-convert-loss-block");
  if (anyLoss) {
    dlg.querySelector("#lines-convert-count-annotations").textContent =
      String(annoCount);
    dlg.querySelector("#lines-convert-count-assignments").textContent =
      String(assignCount);
    // Default "Export first" ON when there's something to lose, OFF
    // when the conversion is trivially safe.
    dlg.querySelector("#lines-convert-export-first").checked = annoCount > 0;
    lossBlock.hidden = false;
  } else {
    lossBlock.hidden = true;
  }
  const confirmBtn = dlg.querySelector("#lines-convert-confirm-btn");
  confirmBtn.disabled = sentenceCount === 0;
  if (!dlg.open) dlg.showModal();
}

// v225v4.3 (#814): pre-save "store by sentence" opt-in. The checkbox
// lives above the Generate / Open-as-ebook row (HTML in index.html,
// CSS in styles.css). State is sticky via localStorage so once a user
// ticks it, every future save in Author mode lands the new clip in
// line storage without re-asking. Gate: Author mode + checkbox both
// required — Standard/Simple users never write lines even if the key
// is stale from a prior Author session.
const _STORE_BY_LINES_KEY = "narrative.storeByLines.default";

function _isStoreByLinesEnabled() {
  try {
    if (typeof getUIMode === "function" && getUIMode() !== "author") {
      return false;
    }
  } catch {}
  const el = document.getElementById("store-by-lines-toggle");
  if (!el) return false;
  return !!el.checked;
}

// Post-save augmentation. If the toggle is on (gated above), build
// {lines, nextLineSeq} from the just-saved clip's text and write them
// back via _mutateClipAtomic so the same sync layer that protects
// per-line LWW also lands them on the user's other devices. No-op when
// the toggle is off, mode isn't Author, NS_IDS helpers haven't loaded,
// or the clip already has lines (fresh save shouldn't, but defensive).
async function _maybeApplyLinesToClip(clipId, text) {
  if (clipId == null) return;
  if (!_isStoreByLinesEnabled()) return;
  if (!window.NS_IDS || typeof window.NS_IDS.hashText !== "function") {
    _dlog("store-by-lines", "skip: NS_IDS helpers missing", { clipId });
    return;
  }
  const sentences = splitSentencesClient(text || "");
  if (sentences.length === 0) {
    _dlog("store-by-lines", "skip: no sentences", { clipId });
    return;
  }
  try {
    const hashes = await Promise.all(
      sentences.map((s) => window.NS_IDS.hashText(s)),
    );
    const now = new Date().toISOString();
    const lines = sentences.map((s, i) => ({
      id: window.NS_IDS.mintLineId(clipId, i + 1),
      text: s,
      hash: hashes[i],
      updatedAt: now,
    }));
    const nextLineSeq = sentences.length + 1;
    await _mutateClipAtomic(clipId, (c) => {
      // Defensive — if a save race already wrote lines, leave them.
      if (Array.isArray(c.lines) && c.lines.length > 0) return;
      c.lines = lines;
      c.nextLineSeq = nextLineSeq;
    });
    _dlog("store-by-lines", "applied", { clipId, sentences: sentences.length });
  } catch (e) {
    console.warn("[store-by-lines] apply failed:", e);
    _dlog("store-by-lines", "apply failed", {
      clipId,
      err: String(e && e.message ? e.message : e),
    });
  }
}

// Boot wiring: restore the toggle's checked state from localStorage,
// and persist on every change so the choice is sticky across imports
// and sessions. Runs on load — safe to call even if the toggle isn't
// in the DOM (Standard / Simple users never hit this path because the
// HTML row is .author-only and CSS hides it).
(function _initStoreByLinesToggle() {
  const el = document.getElementById("store-by-lines-toggle");
  if (!el) return;
  try {
    const stored = localStorage.getItem(_STORE_BY_LINES_KEY);
    el.checked = stored === "1";
  } catch {}
  el.addEventListener("change", () => {
    try {
      localStorage.setItem(_STORE_BY_LINES_KEY, el.checked ? "1" : "0");
    } catch {}
    _dlog("store-by-lines", "toggle changed", { checked: el.checked });
  });
})();

// Run the actual conversion. Atomic: lines + nextLineSeq go in;
// annotations tombstone (so cross-device sync propagates the delete);
// sentenceAssignments wipes. Returns true on success.
async function _runLinesConversion(clipId, dlg) {
  const clip = await getClip(clipId);
  if (!clip) {
    setStatus("Clip not found.", true);
    return false;
  }
  if (!window.NS_IDS || typeof window.NS_IDS.hashText !== "function") {
    setStatus("Sentence-ID helpers missing (page reload required).", true);
    return false;
  }
  const exportFirst = dlg.querySelector("#lines-convert-export-first");
  const wantsExport = exportFirst && !exportFirst.disabled && exportFirst.checked;
  if (wantsExport) {
    const okExport = await _exportClipNotes(clipId);
    if (!okExport) {
      // _exportClipNotes set the error status; bail rather than
      // dropping annotations the user wanted backed up first.
      return false;
    }
  }
  const sentences = splitSentencesClient(clip.text || "");
  if (sentences.length === 0) {
    setStatus("Nothing to index — this clip has no text.", true);
    return false;
  }
  const now = new Date().toISOString();
  // Hash each sentence (NFC + collapse whitespace, sha256[:12]).
  // Done outside the mutation so a hash-compute failure doesn't half-
  // write the clip.
  const hashes = await Promise.all(
    sentences.map((s) => window.NS_IDS.hashText(s)),
  );
  // Mint IDs c_{clip_id}-0001 .. -NNNN; nextLineSeq lands at N+1 so the
  // next sentence the user inserts after conversion gets a fresh
  // counter. Birth order, never reused — see SENTENCE_IDS.md.
  const lines = sentences.map((text, i) => ({
    id: window.NS_IDS.mintLineId(clipId, i + 1),
    text,
    hash: hashes[i],
    updatedAt: now,
  }));
  const nextLineSeq = sentences.length + 1;
  let droppedAnno = 0;
  let droppedAssign = 0;
  try {
    await _mutateClipAtomic(clipId, (c) => {
      c.lines = lines;
      c.nextLineSeq = nextLineSeq;
      // Tombstone every live annotation so the server-side merge
      // recognizes the delete as authoritative and propagates it to
      // the user's other devices. Mirror _clearClipMarks's pattern.
      if (Array.isArray(c.annotations)) {
        const live = c.annotations.filter((a) => a && !a.deletedAt);
        droppedAnno = live.length;
        c.annotations = c.annotations.map((a) => {
          if (!a || a.deletedAt) return a;
          return { ...a, deletedAt: now, updatedAt: now };
        });
      }
      // Voice assignments are clip-local (no cross-device sync layer
      // for them yet), so a hard clear is safe.
      if (c.sentenceAssignments && typeof c.sentenceAssignments === "object") {
        droppedAssign = Object.keys(c.sentenceAssignments).length;
        c.sentenceAssignments = {};
        c.assignmentsDirty = false;
      }
    });
  } catch (e) {
    console.warn("[lines-convert] mutation failed:", e);
    setStatus(`Conversion failed — ${e.message || e}`, true);
    return false;
  }
  _dlog("lines-convert", "done", {
    clipId,
    sentences: sentences.length,
    droppedAnno,
    droppedAssign,
    exportedFirst: wantsExport,
  });
  setStatus(
    `Enabled line-by-line storage — ${sentences.length} sentence${sentences.length === 1 ? "" : "s"} indexed.`,
  );
  // Repaint Edit-dialog status (ON badge + count) so the user sees
  // the change without closing/re-opening.
  await _paintLinesEditState(clipId);
  // Repaint reading-view annotation chips (they're all tombstoned now).
  try {
    const refreshed = await getClip(clipId);
    if (
      refreshed &&
      _currentClipId === clipId &&
      typeof _applyAnnotationMarkers === "function"
    ) {
      _applyAnnotationMarkers(refreshed);
    }
  } catch {}
  return true;
}

// Paint the Edit dialog's lines section to reflect current state.
// Called from openClipEdit and after a successful conversion.
async function _paintLinesEditState(clipId) {
  const offEl = document.getElementById("clip-edit-lines-off");
  const onEl = document.getElementById("clip-edit-lines-on");
  if (!offEl || !onEl) return;
  let clip;
  try {
    clip = await getClip(clipId);
  } catch {
    return;
  }
  const hasLines = clip && Array.isArray(clip.lines) && clip.lines.length > 0;
  if (hasLines) {
    offEl.hidden = true;
    onEl.hidden = false;
    const countEl = document.getElementById("clip-edit-lines-count");
    if (countEl) {
      const n = clip.lines.length;
      countEl.textContent = `— ${n} sentence${n === 1 ? "" : "s"} indexed`;
    }
  } else {
    offEl.hidden = false;
    onEl.hidden = true;
  }
}

// Wire the Enable button. Lazy lookup of the element since the Edit
// dialog HTML is parsed at boot but the script runs after.
(function _wireLinesEnableBtn() {
  const btn = document.getElementById("clip-edit-lines-enable-btn");
  if (!btn) return;
  btn.addEventListener("click", () => {
    if (_editingClipId == null) return;
    _openLinesConvertConfirm(_editingClipId);
  });
})();

notesDialogClose.addEventListener("click", () => notesDialog.close());
notesDialog.addEventListener("close", async () => {
  // v225v4.24 (#829): stop dictation cleanly if the dialog is closed
  // mid-recording. Releases the mic + cancels the timer; the user's
  // partial transcript (if any) is already in the textarea via the
  // commit hook in _notesDictateInsertText, so closing mid-record
  // doesn't lose what they've said so far. The MediaRecorder's
  // onstop will still fire — _notesDictateFinalize handles the case
  // where the textarea is no longer the active surface gracefully
  // (it inserts text anyway; next time you open Notes, you'll see it).
  if (_notesDictateRecorder) {
    _notesDictateStop();
  }
  _notesDictateSetButtonState("idle");
  // v225v4.25 (#373): stop the active-chip tracker so we're not
  // running setInterval forever after the dialog closes.
  if (_notesTimestampsActiveTracker) {
    clearInterval(_notesTimestampsActiveTracker);
    _notesTimestampsActiveTracker = null;
  }
  await _commitNotes();
  _notesEditingClipId = null;
});

// ---- Library export / import (zip backup) -------------------------------
// Self-contained STORED-mode zip implementation. We skip JSZip (~100 KB)
// because:
//   1. MP3 is already compressed — DEFLATE on it would buy a couple percent.
//   2. The manifest is tiny.
//   3. Keeping the app dependency-free is worth a few hundred lines of code.
//
// Format reference: https://pkware.cachefly.net/webdocs/casestudies/APPNOTE.TXT
const _ZIP_LFH_SIG = 0x04034b50;
const _ZIP_CD_SIG = 0x02014b50;
const _ZIP_EOCD_SIG = 0x06054b50;

const _CRC32_TABLE = (() => {
  const t = new Uint32Array(256);
  for (let i = 0; i < 256; i++) {
    let c = i;
    for (let j = 0; j < 8; j++) c = (c >>> 1) ^ ((c & 1) ? 0xedb88320 : 0);
    t[i] = c >>> 0;
  }
  return t;
})();

function _crc32(bytes) {
  let crc = 0xffffffff;
  for (let i = 0; i < bytes.length; i++) {
    crc = (crc >>> 8) ^ _CRC32_TABLE[(crc ^ bytes[i]) & 0xff];
  }
  return (crc ^ 0xffffffff) >>> 0;
}

// Builds a zip from [{name, data: Uint8Array}, ...] and returns a Uint8Array.
// STORED only (compression method 0). UTF-8 filenames via the language-encoding
// flag (bit 11 in the GP bit flag field).
function makeZip(entries) {
  const encoder = new TextEncoder();

  // Pass 1: pre-compute name bytes, CRC, sizes, local-header offsets.
  const records = entries.map((e) => ({
    nameBytes: encoder.encode(e.name),
    data: e.data,
    crc: _crc32(e.data),
    size: e.data.length,
    localOffset: 0,
  }));

  let pos = 0;
  for (const r of records) {
    r.localOffset = pos;
    pos += 30 + r.nameBytes.length + r.size;
  }
  const cdStart = pos;
  for (const r of records) {
    pos += 46 + r.nameBytes.length;
  }
  const cdEnd = pos;
  const totalSize = cdEnd + 22;

  const out = new Uint8Array(totalSize);
  const view = new DataView(out.buffer);
  let p = 0;

  // Local file headers + raw data
  for (const r of records) {
    view.setUint32(p, _ZIP_LFH_SIG, true); p += 4;
    view.setUint16(p, 20, true); p += 2;          // version needed
    view.setUint16(p, 0x0800, true); p += 2;      // GP bit flag — UTF-8 names
    view.setUint16(p, 0, true); p += 2;           // method (STORED)
    view.setUint16(p, 0, true); p += 2;           // mod time
    view.setUint16(p, 0, true); p += 2;           // mod date
    view.setUint32(p, r.crc, true); p += 4;
    view.setUint32(p, r.size, true); p += 4;
    view.setUint32(p, r.size, true); p += 4;
    view.setUint16(p, r.nameBytes.length, true); p += 2;
    view.setUint16(p, 0, true); p += 2;
    out.set(r.nameBytes, p); p += r.nameBytes.length;
    out.set(r.data, p); p += r.size;
  }

  // Central directory
  for (const r of records) {
    view.setUint32(p, _ZIP_CD_SIG, true); p += 4;
    view.setUint16(p, 20, true); p += 2;          // version made by
    view.setUint16(p, 20, true); p += 2;          // version needed
    view.setUint16(p, 0x0800, true); p += 2;      // GP flag — UTF-8 names
    view.setUint16(p, 0, true); p += 2;           // method
    view.setUint16(p, 0, true); p += 2;
    view.setUint16(p, 0, true); p += 2;
    view.setUint32(p, r.crc, true); p += 4;
    view.setUint32(p, r.size, true); p += 4;
    view.setUint32(p, r.size, true); p += 4;
    view.setUint16(p, r.nameBytes.length, true); p += 2;
    view.setUint16(p, 0, true); p += 2;
    view.setUint16(p, 0, true); p += 2;
    view.setUint16(p, 0, true); p += 2;           // disk number
    view.setUint16(p, 0, true); p += 2;           // internal attrs
    view.setUint32(p, 0, true); p += 4;           // external attrs
    view.setUint32(p, r.localOffset, true); p += 4;
    out.set(r.nameBytes, p); p += r.nameBytes.length;
  }

  // End of central directory
  view.setUint32(p, _ZIP_EOCD_SIG, true); p += 4;
  view.setUint16(p, 0, true); p += 2;
  view.setUint16(p, 0, true); p += 2;
  view.setUint16(p, records.length, true); p += 2;
  view.setUint16(p, records.length, true); p += 2;
  view.setUint32(p, cdEnd - cdStart, true); p += 4;
  view.setUint32(p, cdStart, true); p += 4;
  view.setUint16(p, 0, true); p += 2;            // comment length

  return out;
}

// Parse a zip blob back into [{name, data}, ...]. Throws on malformed
// input or any non-STORED entry (we'd never produce DEFLATE'd output).
function readZip(bytes) {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  // Scan backwards for EOCD signature — comment can be up to 64KB.
  let eocd = -1;
  const minStart = Math.max(0, bytes.length - 65557);
  for (let i = bytes.length - 22; i >= minStart; i--) {
    if (view.getUint32(i, true) === _ZIP_EOCD_SIG) {
      eocd = i;
      break;
    }
  }
  if (eocd < 0) throw new Error("not a zip file (EOCD record missing)");

  const numEntries = view.getUint16(eocd + 10, true);
  const cdOffset = view.getUint32(eocd + 16, true);

  const decoder = new TextDecoder();
  const out = [];
  let p = cdOffset;
  for (let i = 0; i < numEntries; i++) {
    if (view.getUint32(p, true) !== _ZIP_CD_SIG) {
      throw new Error("malformed central directory entry");
    }
    const method = view.getUint16(p + 10, true);
    const compSize = view.getUint32(p + 20, true);
    const nameLen = view.getUint16(p + 28, true);
    const extraLen = view.getUint16(p + 30, true);
    const commentLen = view.getUint16(p + 32, true);
    const localOffset = view.getUint32(p + 42, true);
    const name = decoder.decode(bytes.subarray(p + 46, p + 46 + nameLen));
    p += 46 + nameLen + extraLen + commentLen;

    if (method !== 0) {
      throw new Error(`zip uses unsupported compression (method ${method}) for ${name}`);
    }
    if (view.getUint32(localOffset, true) !== _ZIP_LFH_SIG) {
      throw new Error(`bad local header for ${name}`);
    }
    const lhNameLen = view.getUint16(localOffset + 26, true);
    const lhExtraLen = view.getUint16(localOffset + 28, true);
    const dataStart = localOffset + 30 + lhNameLen + lhExtraLen;
    const data = bytes.slice(dataStart, dataStart + compSize);
    out.push({ name, data });
  }
  return out;
}

async function exportLibrary(idsFilter = null) {
  const exportBtn = $("library-export");
  exportBtn.disabled = true;
  exportBtn.textContent = "Building…";
  try {
    const allClips = await listClips();
    const clips = idsFilter
      ? allClips.filter((c) => idsFilter.has(c.id))
      : allClips;
    if (clips.length === 0) {
      setStatus(
        idsFilter
          ? "Nothing selected — nothing to export."
          : "Library is empty — nothing to export.",
        true
      );
      return;
    }
    const presets = _loadPresets();

    const manifestClips = [];
    const entries = [];

    for (const clip of clips) {
      if (!clip.blob) continue;
      const bytes = new Uint8Array(await clip.blob.arrayBuffer());
      const ext = clip.blob.type === "audio/mpeg" ? "mp3" : "wav";
      const audioFile = `audio/${clip.id}.${ext}`;
      entries.push({ name: audioFile, data: bytes });

      // v125: include uploaded cover image as a JPEG sidecar, with
      // the dominant color carried in the manifest entry so import
      // can rehydrate the full cover record without re-sampling.
      let coverFile = null;
      let coverColor = null;
      if (clip.cover && clip.cover.blob) {
        const coverBytes = new Uint8Array(await clip.cover.blob.arrayBuffer());
        coverFile = `covers/${clip.id}.jpg`;
        entries.push({ name: coverFile, data: coverBytes });
        coverColor = clip.cover.color || null;
      }

      manifestClips.push({
        id: clip.id,
        title: clip.title || "",
        note: clip.note || "",
        notes: clip.notes || "",
        text: clip.text || "",
        voiceId: clip.voiceId || null,
        voiceName: clip.voiceName || "",
        speakerId: typeof clip.speakerId === "number" ? clip.speakerId : null,
        rate: Number(clip.rate) || 180,
        volume: typeof clip.volume === "number" ? clip.volume : 1.0,
        sentenceOffsetsSec: clip.sentenceOffsetsSec || [],
        durationSec: Number(clip.durationSec) || 0,
        progressSec: Number(clip.progressSec) || 0,
        createdAt: clip.createdAt || new Date(clip.id).toISOString(),
        audioFile,
        audioType: clip.blob.type,
        bookmarks: Array.isArray(clip.bookmarks) ? clip.bookmarks : [],
        playedAt: clip.playedAt || null,
        tags: Array.isArray(clip.tags) ? clip.tags : [],
        coverFile,
        coverColor,
        // v219: carry voice provenance across export/import so the
        // attribution string for any clip survives a backup → restore.
        // null for pre-v219 clips that have no provenance recorded.
        provenance: clip.provenance || null,
      });
    }

    const manifest = {
      schema: 1,
      app: "Narrative",
      exportedAt: new Date().toISOString(),
      clips: manifestClips,
      presets,
      // Carry the user-defined library order along so a restore lands
      // with chapters / clips in the right sequence on a fresh device.
      libraryOrder: _loadLibraryOrder(),
      playMode: _playMode,
    };

    const manifestBytes = new TextEncoder().encode(
      JSON.stringify(manifest, null, 2)
    );
    // Put the manifest first so a partial download still finds it.
    entries.unshift({ name: "manifest.json", data: manifestBytes });

    const zip = makeZip(entries);
    const blob = new Blob([zip], { type: "application/zip" });
    const url = URL.createObjectURL(blob);
    const today = new Date().toISOString().slice(0, 10);
    const a = document.createElement("a");
    a.href = url;
    a.download = `narrative-library-${today}.zip`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);

    const mb = (zip.length / (1024 * 1024)).toFixed(1);
    setStatus(`Exported ${manifestClips.length} clip(s) (${mb} MB).`);
  } catch (e) {
    console.warn("export failed:", e);
    setStatus(_withOfflineHint(`Export failed: ${e.message}`), true);
  } finally {
    exportBtn.disabled = false;
    exportBtn.textContent = "Export";
  }
}

async function importLibraryFromFile(file) {
  const importBtn = $("library-import");
  importBtn.disabled = true;
  importBtn.textContent = "Reading…";
  try {
    const bytes = new Uint8Array(await file.arrayBuffer());
    const entries = readZip(bytes);

    const manifestEntry = entries.find((e) => e.name === "manifest.json");
    if (!manifestEntry) {
      throw new Error("no manifest.json — is this a Narrative export?");
    }
    const manifest = JSON.parse(new TextDecoder().decode(manifestEntry.data));
    if (!manifest.clips || !Array.isArray(manifest.clips)) {
      throw new Error("manifest.json has no clips array");
    }

    // Audio + cover lookups: filename → bytes.
    const audioByName = new Map();
    const coverByName = new Map();
    for (const e of entries) {
      if (e.name.startsWith("audio/")) audioByName.set(e.name, e.data);
      else if (e.name.startsWith("covers/")) coverByName.set(e.name, e.data);
    }

    const existingIds = new Set((await listClips()).map((c) => c.id));
    let imported = 0;
    let skippedDup = 0;
    let skippedMissing = 0;

    for (const mc of manifest.clips) {
      if (existingIds.has(mc.id)) {
        skippedDup++;
        continue;
      }
      const audioBytes = audioByName.get(mc.audioFile);
      if (!audioBytes) {
        console.warn(`audio missing for clip ${mc.id} (${mc.audioFile})`);
        skippedMissing++;
        continue;
      }
      const blob = new Blob([audioBytes], {
        type: mc.audioType || "audio/mpeg",
      });
      // Cover sidecar (v125). Older manifests don't carry coverFile —
      // those clips just get the title-hash gradient when rendered.
      let cover = undefined;
      if (mc.coverFile) {
        const coverBytes = coverByName.get(mc.coverFile);
        if (coverBytes) {
          cover = {
            blob: new Blob([coverBytes], { type: "image/jpeg" }),
            color: mc.coverColor || null,
          };
        }
      }
      // v223.tn24 (#494 guard): if a clip with this ID already exists
      // locally, read its annotations/highlights and prefer them when
      // the manifest doesn't carry the field. Older exports (pre-v223)
      // don't include annotations — without this preservation, an
      // import of an old zip would clobber any flags the user added
      // since then AND push the empty array up to the server,
      // wiping marks across all devices.
      let _existingForMerge = null;
      try { _existingForMerge = await getClip(mc.id); } catch {}
      await saveClip({
        id: mc.id,
        title: mc.title || "(untitled)",
        note: mc.note || "",
        // v138: per-clip notes scratchpad. Older manifests don't
        // carry it — default to empty.
        notes: mc.notes || "",
        text: mc.text || "",
        voiceId: mc.voiceId || null,
        voiceName: mc.voiceName || "",
        speakerId: typeof mc.speakerId === "number" ? mc.speakerId : null,
        rate: Number(mc.rate) || 180,
        volume: typeof mc.volume === "number" ? mc.volume : 1.0,
        sentenceOffsetsSec: mc.sentenceOffsetsSec || [],
        durationSec: Number(mc.durationSec) || 0,
        progressSec: Number(mc.progressSec) || 0,
        // Bookmarks: array of {id, timeSec, note, createdAt}. Older
        // manifests don't have the field — default to empty.
        bookmarks: Array.isArray(mc.bookmarks) ? mc.bookmarks : [],
        playedAt: mc.playedAt || null,
        // Tags arrived in v109; older manifests don't carry them.
        tags: _normalizeTags(mc.tags),
        // Cover arrived in v125; older manifests don't carry it.
        ...(cover ? { cover } : {}),
        // v219: provenance carried verbatim if present. Older manifests
        // simply don't have it and the field stays undefined — the Edit
        // dialog handles that by hiding the provenance block.
        ...(mc.provenance ? { provenance: mc.provenance } : {}),
        // v223.tn24: prefer manifest's annotations/highlights; if the
        // manifest lacks them but the local clip has them, keep local.
        // This means "import older zip" is no longer a wipe vector.
        annotations: Array.isArray(mc.annotations)
          ? mc.annotations
          : (_existingForMerge && Array.isArray(_existingForMerge.annotations)
              ? _existingForMerge.annotations
              : []),
        highlights: Array.isArray(mc.highlights)
          ? mc.highlights
          : (_existingForMerge && Array.isArray(_existingForMerge.highlights)
              ? _existingForMerge.highlights
              : []),
        // Cross-device sync ledger — local-only field, never in
        // manifests. Preserve so a re-import doesn't reset the
        // "Synced · X ago" footer to GitHub.
        lastDeviceSyncAt: _existingForMerge ? _existingForMerge.lastDeviceSyncAt : undefined,
        createdAt: mc.createdAt || new Date(mc.id).toISOString(),
        blob,
      });
      imported++;
    }

    // Merge presets in by id; existing ones win.
    let presetsAdded = 0;
    if (Array.isArray(manifest.presets) && manifest.presets.length > 0) {
      const existing = _loadPresets();
      const existingPresetIds = new Set(existing.map((p) => p.id));
      for (const p of manifest.presets) {
        if (!existingPresetIds.has(p.id)) {
          existing.unshift(p);
          presetsAdded++;
        }
      }
      _savePresets(existing);
      renderPresets();
    }

    // Restore manual library order — append any ids that weren't already
    // present so existing local clips stay where they are.
    if (Array.isArray(manifest.libraryOrder) && manifest.libraryOrder.length > 0) {
      const existingOrder = _loadLibraryOrder();
      const seen = new Set(existingOrder);
      const merged = existingOrder.slice();
      for (const id of manifest.libraryOrder) {
        const n = Number(id);
        if (Number.isFinite(n) && !seen.has(n)) {
          merged.push(n);
          seen.add(n);
        }
      }
      _saveLibraryOrder(merged);
    }

    // Restore the play / sort mode if it was custom — otherwise leave the
    // local choice alone (the user's current sort preference wins).
    if (manifest.playMode === "custom" && _playMode !== "custom") {
      _playMode = "custom";
      try { localStorage.setItem(PLAY_MODE_KEY, _playMode); } catch {}
      updatePlayModeBtn();
    }

    renderLibrary();
    const parts = [`imported ${imported} clip(s)`];
    if (skippedDup) parts.push(`${skippedDup} duplicate(s) skipped`);
    if (skippedMissing) parts.push(`${skippedMissing} missing audio skipped`);
    if (presetsAdded) parts.push(`${presetsAdded} preset(s) added`);
    setStatus(parts.join(", ") + ".");
  } catch (e) {
    console.warn("import failed:", e);
    setStatus(_withOfflineHint(`Import failed: ${e.message}`), true);
  } finally {
    importBtn.disabled = false;
    importBtn.textContent = "Import";
  }
}

$("library-export").addEventListener("click", () => exportLibrary());
$("library-import").addEventListener("click", () => $("library-import-file").click());
$("library-import-file").addEventListener("change", (e) => {
  const file = e.target.files?.[0];
  if (file) importLibraryFromFile(file);
  // Reset so selecting the same file twice still fires "change".
  e.target.value = "";
});

// ---- Library multi-select -----------------------------------------------
// Bulk delete + bulk export for clip libraries that have grown past
// "click × thirty times in a row" territory. Tapping the Select link
// flips renderLibrary into select mode: each card grows a checkbox in
// place of the drag handle, tapping the card toggles its selection
// (instead of loading and playing), and the tools row swaps to
// Cancel · Select all · Export N · Delete N with live counts.
let _libraryMultiSelect = false;
const _librarySelectedIds = new Set();

const libraryToolsIdle = $("library-tools-idle");
const libraryToolsSelect = $("library-tools-select");
const librarySelectBtn = $("library-select");
const librarySelectCancelBtn = $("library-select-cancel");
const librarySelectAllBtn = $("library-select-all");
const librarySelectExportBtn = $("library-select-export");
const librarySelectDeleteBtn = $("library-select-delete");

function _enterMultiSelect() {
  _libraryMultiSelect = true;
  _librarySelectedIds.clear();
  libraryToolsIdle.hidden = true;
  libraryToolsSelect.hidden = false;
  _updateMultiSelectCounts();
  // Reset the delete button's confirm-arming if a previous session left
  // it half-armed.
  _disarmBulkDelete();
  renderLibrary();
}

function _exitMultiSelect() {
  _libraryMultiSelect = false;
  _librarySelectedIds.clear();
  libraryToolsIdle.hidden = false;
  libraryToolsSelect.hidden = true;
  _disarmBulkDelete();
  renderLibrary();
}

function _updateMultiSelectCounts() {
  const n = _librarySelectedIds.size;
  librarySelectExportBtn.textContent = `Export ${n}`;
  librarySelectDeleteBtn.textContent =
    _bulkDeleteArmed ? `Tap again to delete ${n}` : `Delete ${n}`;
  librarySelectExportBtn.disabled = n === 0;
  librarySelectDeleteBtn.disabled = n === 0;
  if (n === 0) _disarmBulkDelete();
}

// Tap-twice-to-confirm pattern (same as Reset stats) so a bulk delete
// doesn't fire on a single misclick. Three seconds armed window; resets
// on selection change, mode exit, or another action.
let _bulkDeleteArmed = false;
let _bulkDeleteArmTimer = null;
function _armBulkDelete() {
  _bulkDeleteArmed = true;
  clearTimeout(_bulkDeleteArmTimer);
  _bulkDeleteArmTimer = setTimeout(_disarmBulkDelete, 3000);
  _updateMultiSelectCounts();
}
function _disarmBulkDelete() {
  _bulkDeleteArmed = false;
  clearTimeout(_bulkDeleteArmTimer);
  _bulkDeleteArmTimer = null;
}

librarySelectBtn.addEventListener("click", _enterMultiSelect);
librarySelectCancelBtn.addEventListener("click", _exitMultiSelect);

librarySelectAllBtn.addEventListener("click", () => {
  // Select every clip currently rendered (respects the active filter
  // and sort). Reads the DOM so a search-narrowed view selects only
  // what the user is looking at, not the full library.
  const visible = libraryList.querySelectorAll(".clip[data-clip-id]");
  for (const node of visible) {
    const id = Number(node.dataset.clipId);
    if (Number.isFinite(id)) _librarySelectedIds.add(id);
  }
  _updateMultiSelectCounts();
  renderLibrary();
});

librarySelectExportBtn.addEventListener("click", async () => {
  if (_librarySelectedIds.size === 0) return;
  const ids = new Set(_librarySelectedIds);
  await exportLibrary(ids);
  _exitMultiSelect();
});

librarySelectDeleteBtn.addEventListener("click", async () => {
  if (_librarySelectedIds.size === 0) return;
  if (!_bulkDeleteArmed) {
    _armBulkDelete();
    return;
  }
  const ids = [..._librarySelectedIds];
  _disarmBulkDelete();
  try {
    for (const id of ids) {
      await deleteClipById(id);
      if (_currentClipId === id) {
        _currentClipId = null;
        _currentPlayingVoiceId = null;
      }
    }
    setStatus(`Deleted ${ids.length} clip${ids.length === 1 ? "" : "s"}.`);
  } catch (e) {
    console.warn("bulk delete failed:", e);
    setStatus(_withOfflineHint(`Bulk delete failed: ${e.message}`), true);
  }
  _exitMultiSelect();
});

// v589: { autoPlay } opt added. Defaults to true so every existing
// caller (chapter-queue auto-advance, bookmark-jump cross-clip, etc.)
// keeps its current behavior. The library-card click on phone passes
// `autoPlay: false` so tapping a card silently loads — the user then
// hits the bottom-bar play button when ready. Author feedback: card
// taps were starting playback unexpectedly, especially when the
// previous clip was mid-paragraph and the new clip jumped to it.
async function loadClip(id, { autoPlay = true } = {}) {
  const clip = await getClip(id);
  if (!clip) return;

  // Whatever auto-advance had queued is now stale — the user picked
  // something explicitly.
  _cancelAutoAdvance();
  // A-B loop bounds belonged to whatever audio was loaded before.
  clearAbLoop();
  // v225eb (#615): refresh the phone top-bar title for the new clip.
  // Pass `clip` directly — _currentClipId isn't assigned until
  // later in loadClip, so the no-arg form would read stale state
  // (or null on first load) and paint an empty title.
  if (typeof _phonePaintTopTitle === "function") {
    try { _phonePaintTopTitle(clip); } catch {}
  }

  // v220-AA: hydrate the per-sentence override map for this clip so
  // the reading view's long-press handler can read/write it. Empty
  // object = no overrides (every sentence uses auto-detection).
  _currentClipAssignments =
    clip.sentenceAssignments && typeof clip.sentenceAssignments === "object"
      ? { ...clip.sentenceAssignments }
      : {};
  // v220-AG: hydrate the dirty flag too so a banner persists across
  // page reloads if the user made changes but didn't re-render.
  _currentClipAssignmentsDirty = !!clip.assignmentsDirty;
  _updatePendingAssignmentsBanner();

  // Drop any in-progress streaming state so the chained-playback / virtualTime
  // logic doesn't try to walk a queue from a previous generate().
  resetStream();

  // v225g1 (#690): ebook clips have no audio blob. URL.createObjectURL
  // would throw on undefined. Clear the player's source so a stale
  // blob from a previous audio clip doesn't keep playing, and skip
  // sentenceOffsetsSec (which is empty on ebooks anyway). The rest of
  // loadClip — text, images, highlights, voice picker hydration — is
  // safe to run; voiceId/rate/volume guards are conditional already.
  const _isEbookClip = clip.kind === "ebook" || !clip.blob;
  // v225g3 (#692): stamp the kind so the phone Generate bar hides
  // and CSS gates can react. Setter also prods _syncPhoneGenerateBar.
  if (typeof _setCurrentClipKind === "function") {
    _setCurrentClipKind(_isEbookClip ? "ebook" : "audio");
  }
  // v225g11 (#699): clear ALL pending import state. The loaded clip
  // is now the source of truth — its own clip.images / clip.cover
  // get used by enterReadingView + book view. Any leftover
  // _pendingImages / _pendingDetectedCover / _pendingChapterImages
  // from an earlier import session is stale: it doesn't belong to
  // this clip, and if the user later taps "📖 Open as ebook" on
  // newly-pasted text, the stale list would silently get saved onto
  // the new clip. User reported: opened Bicycle Ghost as ebook,
  // later opened "Chapter 1: The Awakening" as ebook — the
  // Awakening's book view showed the Bicycle Ghost's Ex Libris
  // image because that pending list was never cleared. Clearing
  // here closes the leak. The upload + URL handlers reset these
  // explicitly when they have new data; loadClip resets them when
  // the user transitions away from "live import flow" to "viewing
  // a saved clip."
  _pendingImages = [];
  _pendingDetectedCover = null;
  _pendingChapterImages = [];
  _pendingGitRef = null;
  _pendingScrivenerRef = null;
  _pendingChapterTitle = null;
  if (typeof _paintImportPreview === "function") {
    try { _paintImportPreview(); } catch {}
  }
  if (_isEbookClip) {
    if (lastBlobUrl) URL.revokeObjectURL(lastBlobUrl);
    lastBlob = null;
    lastBlobUrl = null;
    try { playerEl.removeAttribute("src"); playerEl.load(); } catch {}
    // Hide the player card and download button — there's no audio.
    if (playerCard) playerCard.hidden = true;
    sentenceOffsetsSec = [];
  } else {
    if (lastBlobUrl) URL.revokeObjectURL(lastBlobUrl);
    lastBlob = clip.blob;
    lastBlobUrl = URL.createObjectURL(clip.blob);
    sentenceOffsetsSec = (clip.sentenceOffsetsSec || []).slice();
  }

  textEl.value = clip.text || "";
  updateCounts();
  if (clip.voiceId) {
    voiceEl.value = clip.voiceId;
    onVoiceChange(); // re-render the speaker row for the new voice
    if (
      typeof clip.speakerId === "number" &&
      !speakerRow.hidden &&
      speakerEl.options.length > clip.speakerId
    ) {
      speakerEl.value = String(clip.speakerId);
    }
  }
  if (clip.rate) {
    rateEl.value = String(clip.rate);
    rateValueEl.textContent = String(clip.rate);
  }
  if (typeof clip.volume === "number") {
    volumeEl.value = String(Math.round(clip.volume * 100));
    volumeValueEl.textContent = `${Math.round(clip.volume * 100)}%`;
  }

  // Bind the player to this clip so the throttled progress-saver knows which
  // library row to update as playback advances.
  _currentClipId = id;
  // v225ep (#632): _currentClipId just changed, so the desktop
  // author pane's clip-loaded gate now flips on. _applyAuthorPaneLayout
  // both toggles the body data-attribute (CSS shows the pane) and
  // calls _renderAuthorPane to populate it with this clip's data.
  if (typeof _applyAuthorPaneLayout === "function") {
    try { _applyAuthorPaneLayout(); } catch {}
  }
  // Libby-style page backdrop — fade in the cover as a blurred wash.
  _setBackgroundArt(clip);
  // Listen-stats attributes by the clip's stored voice (not the picker,
  // which can drift while playback continues). Cached here so the
  // timeupdate accumulator doesn't have to round-trip IDB on every tick.
  _currentPlayingVoiceId = clip.voiceId || null;
  // v225.tn85 (#567): also snapshot rate/volume/speaker so the
  // re-narrate banner can detect drift on any of them, not just
  // voice. Null = "unknown" → banner won't fire on this axis.
  _currentPlayingRate =
    typeof clip.rate === "number" ? clip.rate : null;
  _currentPlayingVolume =
    typeof clip.volume === "number" ? clip.volume : null;
  _currentPlayingSpeakerId =
    typeof clip.speakerId === "number" ? clip.speakerId : null;
  // v225.tn90 (#572): kick off best-effort pre-cache of the next
  // clip's audio so a mid-row signal drop on a train/plane doesn't
  // strand the auto-advance. Runs after a 2s settle so it doesn't
  // compete with the current clip's audio start.
  if (typeof _precacheClipAudio === "function") {
    setTimeout(async () => {
      try {
        const nextId = await nextClipId(clip.id);
        if (nextId) _precacheClipAudio(nextId);
      } catch {}
    }, 2000);
  }
  _lastProgressSaveAt = Date.now();
  // loadClip sets voiceEl.value to clip.voiceId above, so the picker
  // matches the clip's voice on entry — re-narrate banner should be
  // hidden. Reset the dismiss tracker too so a future voice change on
  // this clip can prompt.
  renarrateBanner.hidden = true;
  _renarrateDismissedClipId = null;

  enterReadingView(
    clip.text || "",
    Array.isArray(clip.images) ? clip.images : [],
    Array.isArray(clip.highlights) ? clip.highlights : [],
    // v225v4.6 (#810 step 5): thread clip.lines so the reading-view
    // sentence builder can stamp data-line-id on each span. Other
    // enterReadingView callers (generate / save-text) pass nothing
    // here — fresh text has no stored lines yet; the post-save
    // augmentation in _maybeApplyLinesToClip will create them, and
    // the next loadClip on this row will pick them up.
    Array.isArray(clip.lines) ? clip.lines : null
  );
  // v223.annotate-1: paint the small accent dot on any sentence span
  // that already has a flagged annotation. enterReadingView rebuilds
  // sentenceSpans from scratch, so the data-has-annotation attrs need
  // re-applying after the fact.
  if (typeof _applyAnnotationMarkers === "function") {
    _applyAnnotationMarkers(clip);
  }
  setMediaMetadata(clip.text || "");

  // Resume from saved position once metadata is in. Only restore if it's a
  // meaningful chunk past the start AND a bit before the end — otherwise
  // just play from 0 so the user isn't dumped at the end of a "completed" clip.
  // v225g1 (#690): ebook clips skip resume + player-card + autoplay
  // entirely. The book view is what they came for; there's no audio
  // to seek into. setStatus still fires so the user gets confirmation.
  if (_isEbookClip) {
    downloadBtn.disabled = true;
    setStatus(`📖 Loaded · ${clip.title || "(untitled)"} (ebook — no audio)`);
    // v225v3.56 (#789): when an ebook clip lands on phone, drop into
    // book view automatically. The post-import path (_openAsEbook)
    // does this explicitly, but a synced ebook clip arriving via
    // library tap / loadClip went only as far as reading view —
    // user saw only the cover acknowledgments page + images and
    // couldn't find the actual story without knowing about the
    // book-view affordance. Phone-only because desktop users have
    // an explicit "open as ebook" affordance and may prefer to see
    // the scrolling preview first. Guard with hidden check so we
    // don't re-enter when the user is already inside book view.
    try {
      if (typeof _dlog === "function") {
        _dlog("ebook:load", "loaded ebook clip", {
          id: clip.id,
          title: (clip.title || "").slice(0, 60),
          textLen: (clip.text || "").length,
          imagesCount: Array.isArray(clip.images) ? clip.images.length : 0,
          hasCover: !!clip.cover,
          coverType: typeof clip.cover,
        });
      }
    } catch {}
    const _phoneNow = window.matchMedia &&
      window.matchMedia("(max-width: 767px)").matches;
    if (_phoneNow && typeof enterBookView === "function") {
      const bv = document.getElementById("book-view");
      if (bv && bv.hidden) {
        try {
          await enterBookView();
          if (typeof _dlog === "function") {
            _dlog("ebook:load", "auto-entered book view (phone)", {
              id: clip.id,
            });
          }
        } catch (e) {
          console.error("[ebook] auto-enter book view failed:", e);
          if (typeof _dlog === "function") {
            _dlog("ebook:load", "auto-enter book view threw", {
              id: clip.id,
              error: String(e && e.message || e),
            });
          }
        }
      }
    }
  } else {
    const resumeAt = Number(clip.progressSec) || 0;
    if (resumeAt > 1) {
      playerEl.addEventListener("loadedmetadata", () => {
        const dur = playerEl.duration;
        if (isFinite(dur) && resumeAt < dur - 1) {
          playerEl.currentTime = resumeAt;
        }
      }, { once: true });
    }

    playerEl.src = lastBlobUrl;
    playerCard.hidden = false;
    downloadBtn.disabled = false;

    setStatus(
      resumeAt > 1
        ? `Resuming · ${clip.title} · ${formatTime(resumeAt)}`
        : `Loaded · ${clip.title}`
    );
    // v589: only auto-play when the caller asks for it. The library-
    // card click on phone passes autoPlay:false so the user sees the
    // loaded clip and decides whether to start.
    if (autoPlay) playerEl.play().catch(() => {});
  }
  // Re-render so the ▶ indicator moves to this clip + the new clip's
  // bookmarks list appears under the player.
  renderLibrary();
  renderBookmarks();
  // Keep the mini player's title fresh even when it's currently visible
  // (e.g. auto-advance fires while the user is scrolled down).
  _updateMiniPlayerTitle();
  // GitHub source check. If this clip came from GitHub and the upstream
  // SHA has changed, surface the outdated banner so the user can
  // refetch + re-narrate. Quietly silent if no token, no gitRef, or
  // the check fails (network, rate limit) — we don't want a banner
  // popping up for non-content reasons.
  _gitOutdatedBanner.hidden = true;
  _gitOutdatedClipId = null;
  if (clip.gitRef && clip.gitRef.repoUrl && clip.gitRef.path && getGithubToken()) {
    _checkGitSourceFreshness(clip);
  }

  // v225v4.45 (#709 follow-up): layout probe after the reading view
  // has painted. Two requestAnimationFrames so we read AFTER the
  // CSS transitions for #status banner, tag row, pull-up etc. have
  // settled. The clip-load is where the user reported the stacked-
  // controls bug — that's the snapshot we want.
  try {
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        if (typeof _dlogLayoutProbe === "function") {
          _dlogLayoutProbe(`loadClip:${id}`);
        }
      });
    });
  } catch {}
}

libraryClearBtn.addEventListener("click", async () => {
  if (!confirm("Delete all saved clips? This can't be undone.")) return;
  await clearLibrary();
  renderLibrary();
});

// ---- Import dropdown ----------------------------------------------------
// One menu fronts every manuscript source: Upload file (single doc),
// Paste URL (any URL or github.com/owner/repo), GitHub repo (URL row
// prefilled), Scrivener bundle (.scriv.zip), Obsidian vault (.zip).
// Each item dispatches to the same downstream entry points the old
// per-source buttons used. Closing on outside-click / Escape keeps
// the menu disposable without modal overhead.

function _openImportMenu() {
  importMenu.hidden = false;
  importBtn.setAttribute("aria-expanded", "true");
  // v225.tn45 (#522): on phone, render the menu as a centered
  // modal instead of the trigger-anchored dropdown. The pull-up
  // (if open) closes so the modal lands cleanly on the reading
  // view background rather than stacked over the drawer.
  const isPhone = window.matchMedia("(max-width: 767px)").matches;
  if (isPhone) {
    document.body.dataset.importMenu = "open";
    if (
      document.body.dataset.pullup === "open" &&
      typeof _phonePullupClose === "function"
    ) {
      _phonePullupClose();
    }
  }
}

function _closeImportMenu() {
  importMenu.hidden = true;
  importBtn.setAttribute("aria-expanded", "false");
  if (document.body.dataset.importMenu) {
    delete document.body.dataset.importMenu;
  }
}

importBtn.addEventListener("click", (e) => {
  e.stopPropagation();
  if (importMenu.hidden) _openImportMenu();
  else _closeImportMenu();
});

document.addEventListener("click", (e) => {
  if (importMenu.hidden) return;
  if (importMenu.contains(e.target) || importBtn.contains(e.target)) return;
  _closeImportMenu();
});

document.addEventListener("keydown", (e) => {
  if (!importMenu.hidden && e.key === "Escape") _closeImportMenu();
});

importMenu.addEventListener("click", (e) => {
  const btn = e.target.closest("button[data-import]");
  if (!btn) return;
  _closeImportMenu();
  const source = btn.dataset.import;
  if (source === "file") {
    uploadInput.click();
  } else if (source === "url") {
    if (urlRow.hidden) showUrlRow({ placeholder: "https://… (article URL)" });
    else hideUrlRow();
  } else if (source === "github") {
    // Open the URL row pre-primed for a github.com/owner/repo paste.
    // _isGithubRepoRoot() in fetchFromUrl will route this to
    // openGithubBrowser, so we don't need a separate code path here.
    // v142: hint up top spells out repo root vs file URL — testers
    // were pasting /blob/<branch>/<path> URLs from individual
    // chapter files and getting confused when nothing loaded.
    // v163 / v176: pre-fill with the most recently browsed repo and
    // (v176) surface up to RECENT_REPOS_MAX recents as one-click
    // chips so a user juggling multiple projects can flip between
    // them without re-pasting URLs. Single recent → just the prefill
    // + hint; 2+ recents → also show the chip row.
    const recents = _getRecentGithubRepos();
    const lastRepo = recents.length > 0 ? recents[0] : null;
    showUrlRow({
      placeholder: "github.com/owner/repo",
      prefill: lastRepo ? lastRepo.url : "https://github.com/",
      hint: lastRepo
        ? `Last opened: <strong>${lastRepo.owner}/${lastRepo.repo}</strong>. Hit Fetch to re-open it, or paste a different repo URL.`
        : 'Paste the <strong>repo root</strong> — like ' +
          '<code>github.com/owner/repo</code> — not a link to a ' +
          'specific file. We\'ll open a picker so you can choose ' +
          'which chapters to import.',
      recentRepos: recents,
    });
  } else if (source === "gist") {
    // v181: pre-prime the URL row for a Gist paste. fetchFromUrl
    // dispatches to openGistBrowser when the host matches.
    showUrlRow({
      placeholder: "gist.github.com/user/<id>",
      prefill: "https://gist.github.com/",
      hint:
        'Paste a Gist URL — like ' +
        '<code>gist.github.com/user/abc123</code>. Single-file Gists ' +
        'load straight into the textarea; multi-file Gists open the ' +
        'picker.',
    });
  } else if (source === "gdrive") {
    // v4.100 (#896): signed-in users get the Google Picker (browse their
    // private Drive); everyone else falls back to the public share-link
    // row from Phase 1. _handleGdriveImport picks the branch.
    _handleGdriveImport();
  } else if (source === "scrivener") {
    scrivenerInput.click();
  } else if (source === "obsidian") {
    obsidianInput.click();
  }
});

// ---- URL row ------------------------------------------------------------
// Inline input above the textarea. Submit fetches the article server-
// side (trafilatura strips nav/ads/footers) and drops clean text into
// the textarea, ready for Generate. Used by both Paste URL and GitHub
// repo menu items — the placeholder/prefill differs but the fetch path
// is shared.

function showUrlRow(opts) {
  urlRow.hidden = false;
  urlInput.disabled = false;
  urlFetchBtn.disabled = false;
  if (opts && opts.placeholder) urlInput.placeholder = opts.placeholder;
  if (opts && opts.prefill != null) urlInput.value = opts.prefill;
  // v142: per-flow hint above the row. innerHTML so callers can
  // emphasize key shapes with <strong>/<code>; copy is hard-coded
  // by the caller so we're not interpolating untrusted input.
  if (opts && opts.hint) {
    urlRowHint.innerHTML = opts.hint;
    urlRowHint.hidden = false;
  } else {
    urlRowHint.innerHTML = "";
    urlRowHint.hidden = true;
  }
  // v176: recent-repos chip row. Only the GitHub flow passes
  // opts.recentRepos; other callers leave this hidden. Each chip
  // pre-fills the URL field + auto-submits Fetch so a user juggling
  // multiple book projects can flip between them without re-pasting.
  if (urlRowRecents) {
    if (opts && Array.isArray(opts.recentRepos) && opts.recentRepos.length > 1) {
      urlRowRecents.hidden = false;
      urlRowRecents.innerHTML = "";
      const label = document.createElement("span");
      label.className = "url-row-recents-label";
      label.textContent = "Switch to:";
      urlRowRecents.appendChild(label);
      // Skip index 0 — that's already pre-filled. Surface the rest.
      for (let i = 1; i < opts.recentRepos.length; i++) {
        const r = opts.recentRepos[i];
        const chip = document.createElement("button");
        chip.type = "button";
        chip.className = "url-row-recent-chip";
        chip.title = `Switch to ${r.owner}/${r.repo}`;
        chip.textContent = `${r.owner}/${r.repo}`;
        chip.addEventListener("click", (e) => {
          e.preventDefault();
          urlInput.value = r.url;
          // Auto-submit so the picker opens immediately — the user
          // explicitly picked this repo, no need for a second click.
          fetchFromUrl();
        });
        urlRowRecents.appendChild(chip);
      }
    } else {
      urlRowRecents.hidden = true;
      urlRowRecents.innerHTML = "";
    }
  }
  urlInput.focus();
  // For prefilled-with-prefix cases (github), put the caret at end so
  // the user can keep typing the owner/repo without clearing the prefix.
  if (opts && opts.prefill) {
    const len = urlInput.value.length;
    urlInput.setSelectionRange(len, len);
  } else {
    urlInput.select();
  }
}

function hideUrlRow() {
  urlRow.hidden = true;
  urlInput.value = "";
  urlRowHint.hidden = true;
  urlRowHint.innerHTML = "";
  // v176: also clear recents chips so they don't bleed into the next
  // showUrlRow call (e.g. Paste URL after GitHub).
  if (urlRowRecents) {
    urlRowRecents.hidden = true;
    urlRowRecents.innerHTML = "";
  }
}

urlInput.addEventListener("keydown", (e) => {
  if (e.key === "Enter") {
    e.preventDefault();
    fetchFromUrl();
  } else if (e.key === "Escape") {
    hideUrlRow();
  }
});

// ---- Scrivener bundle upload (dedicated input) -------------------------
// Posts the .zip to /api/extract/scrivener and opens the shared
// picker with the parsed chapter list. Mirrors the .zip branch in
// the main upload handler — kept separate because the explicit menu
// path always knows it's a Scrivener bundle (no sniff needed).

scrivenerInput.addEventListener("change", async (e) => {
  const file = e.target.files?.[0];
  if (!file) return;
  setStatus(`Reading ${file.name}…`);
  try {
    const formData = new FormData();
    formData.append("file", file);
    const res = await fetch("/api/extract/scrivener", {
      method: "POST",
      body: formData,
    });
    if (!res.ok) {
      let detail = `HTTP ${res.status}`;
      try { const j = await res.json(); if (j.detail) detail = j.detail; } catch {}
      throw new Error(detail);
    }
    const data = await res.json();
    openScrivenerBrowser(data);
    setStatus(
      `Loaded ${data.project_name} · ${data.chapters.length} chapter${data.chapters.length === 1 ? "" : "s"}`
    );
  } catch (err) {
    setStatus(_withOfflineHint(`Scrivener import failed: ${err.message}`), true);
  } finally {
    scrivenerInput.value = "";
  }
});

// ---- Obsidian vault upload (dedicated input) ---------------------------
// Same shape as the Scrivener handler — POST the zip, open the shared
// picker with the parsed note list. The Obsidian endpoint filters out
// .obsidian/, templates/, etc. server-side so the user only ever sees
// importable Markdown notes.

obsidianInput.addEventListener("change", async (e) => {
  const file = e.target.files?.[0];
  if (!file) return;
  setStatus(`Reading ${file.name}…`);
  try {
    const formData = new FormData();
    formData.append("file", file);
    const res = await fetch("/api/extract/obsidian", {
      method: "POST",
      body: formData,
    });
    if (!res.ok) {
      let detail = `HTTP ${res.status}`;
      try { const j = await res.json(); if (j.detail) detail = j.detail; } catch {}
      throw new Error(detail);
    }
    const data = await res.json();
    openObsidianBrowser(data);
    setStatus(
      `Loaded ${data.vault_name} · ${data.chapters.length} note${data.chapters.length === 1 ? "" : "s"}`
    );
  } catch (err) {
    setStatus(_withOfflineHint(`Obsidian import failed: ${err.message}`), true);
  } finally {
    obsidianInput.value = "";
  }
});

urlFetchBtn.addEventListener("click", fetchFromUrl);

// ---- GitHub freshness check (auto-check on clip load) ---------------------
// When a clip with a stored gitRef is opened, fire a single sync-check
// against GitHub. If the upstream SHA has moved, show the outdated
// banner. Refetch-and-renarrate runs the existing regen path so the
// clip's bookmarks survive.
const _gitOutdatedBanner = $("git-outdated-banner");
const _gitOutdatedConfirm = $("git-outdated-confirm");
const _gitOutdatedDismiss = $("git-outdated-dismiss");
let _gitOutdatedClipId = null;
let _gitOutdatedNewSha = null;

async function _checkGitSourceFreshness(clip) {
  if (!clip || !clip.gitRef) return;
  const { repoUrl, branch, path, sha: storedSha } = clip.gitRef;
  if (!repoUrl || !path) return;
  try {
    const res = await fetch("/api/github/sync-check", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        github_token: getGithubToken() || undefined,
        items: [{ repoUrl, branch, paths: [path] }],
      }),
    });
    if (!res.ok) return;
    const data = await res.json();
    const result = (data.results || [])[0];
    if (!result || result.error) return;
    const currentSha = (result.shas || {})[path];
    if (!currentSha || currentSha === storedSha) return;
    // Outdated. Surface banner targeting THIS specific clip; if the
    // user loads a different clip mid-check, the load handler hides
    // the banner so we don't act on stale state.
    if (_currentClipId !== clip.id) return;
    _gitOutdatedClipId = clip.id;
    _gitOutdatedNewSha = currentSha;
    _gitOutdatedBanner.hidden = false;
  } catch {
    // Silent: rate-limit, network blip, etc.
  }
}

_gitOutdatedDismiss.addEventListener("click", () => {
  _gitOutdatedBanner.hidden = true;
  _gitOutdatedClipId = null;
  _gitOutdatedNewSha = null;
});

_gitOutdatedConfirm.addEventListener("click", async () => {
  if (!_gitOutdatedClipId) return;
  const clipId = _gitOutdatedClipId;
  _gitOutdatedBanner.hidden = true;
  const clip = await getClip(clipId);
  if (!clip || !clip.gitRef) return;
  const { repoUrl, branch, path } = clip.gitRef;
  const m = repoUrl.match(/github\.com\/([^/]+)\/([^/]+)/);
  if (!m) {
    setStatus("Couldn't parse repo URL — refetch cancelled.", true);
    return;
  }
  const owner = m[1];
  const repo = m[2];
  const rawUrl =
    `https://raw.githubusercontent.com/${owner}/${repo}/${branch}/${encodeURI(path)}`;
  setStatus(`Refetching ${path}…`);
  try {
    const res = await fetch("/api/extract/url", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        url: rawUrl,
        github_token: getGithubToken() || undefined,
        git_sha: _gitOutdatedNewSha || undefined,
      }),
    });
    if (!res.ok) {
      let detail = `HTTP ${res.status}`;
      try { const j = await res.json(); if (j.detail) detail = j.detail; } catch {}
      throw new Error(detail);
    }
    const data = await res.json();
    // Stash the new gitRef so the regen-save callback writes it back.
    _pendingGitRef = data.gitRef || null;
    _pendingImages = Array.isArray(data.images) ? data.images : [];
    // Mark this clip as the regen target. generate() preserves title,
    // note, bookmarks, createdAt — only the text + audio change.
    _regenTargetClipId = clipId;
    textEl.value = data.text || "";
    updateCounts();
    // Hand off to generate(). The save path picks up regenExistingMeta
    // via getClip, which now returns the gitRef-updated state.
    generate();
  } catch (err) {
    setStatus(_withOfflineHint(`Refetch failed: ${err.message}`), true);
  }
});

// ---- GitHub repo browser (Level 2 GitHub integration) ----
// Opened from fetchFromUrl when the user pastes a repo-root URL.
// Calls /api/github/tree to list .md/.txt/.docx/.pdf/.epub files,
// renders them as checkboxes, and either loads one (single selection
// = same as URL fetch) or builds a chapter queue (multi-selection =
// each file becomes a chapter).

// ---- Shared document picker --------------------------------------------
// Multi-file manuscript sources (GitHub, Scrivener, Obsidian) all need
// the same UI: titled dialog, meta line, filter input, scrollable list
// of selectable items, running selection summary, Use button. This
// component owns that machinery; callers pass items + an async Use
// callback and get back the selected subset.
//
// Items shape:
//   { id: string, title: string, subtitle?: string,
//     size?: number,  // bytes — formatted as B/KB/MB
//     chars?: number, // characters — formatted as "X chars" / "X.Yk chars"
//     extra?: any }   // anything the caller wants threaded back (sha, text, …)
//
// Lifecycle:
//   const handle = openDocumentPicker({title, meta, items, onUse, …})
//   handle.setTitle(s) / setMeta(s) / setItems(arr) / close()
// Use cases:
//   - GitHub opens with items=null + meta="Loading…", then fills via setItems
//     once /api/github/tree responds (or shows the error in setMeta).
//   - Scrivener / Obsidian open with items pre-populated.
// onUse is invoked AFTER the dialog closes — async work runs in the
// status bar, not blocking the dialog.

const docPickerDialog = $("document-picker-dialog");
const docPickerClose = $("doc-picker-close");
const docPickerCancel = $("doc-picker-cancel");
const docPickerUse = $("doc-picker-use");
const docPickerTitle = $("doc-picker-title");
const docPickerMeta = $("doc-picker-meta");
const docPickerFilter = $("doc-picker-filter");
const docPickerList = $("doc-picker-list");
const docPickerSummary = $("doc-picker-summary");
// v176: "Hide already imported" filter chip. Only revealed when the
// caller passes an isImported callback (GitHub flow today).
const docPickerHideImported = $("doc-picker-hide-imported");
// v179: GitHub branch picker + folder suggestion chips. Both are
// populated by openGithubBrowser and hidden for non-GitHub sources.
const docPickerBranchesRow = $("doc-picker-branches-row");
const docPickerBranches = $("doc-picker-branches");
const docPickerFolderChips = $("doc-picker-folder-chips");
// v139: background-mode toggle row. Shown only when 2+ items are
// selected (single picks bypass the queue entirely).
const docPickerBgLabel = $("doc-picker-bg-label");
const docPickerBgToggle = $("doc-picker-bg-toggle");

let _docPickerState = null;

function _docPickerFormatSize(bytes) {
  if (!bytes) return "";
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}

function _docPickerFormatChars(n) {
  if (!n) return "";
  if (n < 1000) return `${n} chars`;
  return `${(n / 1000).toFixed(1)}k chars`;
}

function _docPickerItemSize(item) {
  // Prefer chars (cleaner for pre-parsed text), fall back to bytes
  // (for raw filesystem items like GitHub tree entries).
  if (item.chars != null) return _docPickerFormatChars(item.chars);
  if (item.size != null) return _docPickerFormatSize(item.size);
  return "";
}

// v182: build a folder tree from a flat list of items keyed by path.
// VSCode-style: folders carry .folders (Map<name, node>) and .files
// (array of items). Each node also tracks its full path so the
// renderer can look up "is this folder open" state without re-walking.
function _docPickerBuildTree(items) {
  const root = { name: "", path: "", folders: new Map(), files: [] };
  for (const it of items) {
    const segments = (it.title || it.id || "").split("/");
    let node = root;
    let accum = "";
    for (let i = 0; i < segments.length - 1; i++) {
      const seg = segments[i];
      if (!seg) continue;
      accum = accum ? `${accum}/${seg}` : seg;
      if (!node.folders.has(seg)) {
        node.folders.set(seg, {
          name: seg, path: accum, folders: new Map(), files: [],
        });
      }
      node = node.folders.get(seg);
    }
    // Last segment is the filename (or, if the path had no slashes,
    // the whole thing is a root-level file).
    node.files.push(it);
  }
  return root;
}

// v182: walk the tree and collect every file item under a node (used
// for the folder-checkbox bulk-select tri-state). Returns an array
// of the underlying item objects, NOT just ids, so the caller can
// also tally chars/bytes if it wants.
function _docPickerCollectFiles(node) {
  const out = [];
  function walk(n) {
    for (const f of n.files) out.push(f);
    for (const child of n.folders.values()) walk(child);
  }
  walk(node);
  return out;
}

// v182: when the user types into the filter input, every folder
// whose subtree contains at least one matching file should auto-
// expand. Returns the Set of folder paths to mark open this render.
function _docPickerAutoExpanded(node, matches) {
  const out = new Set();
  function walk(n) {
    let any = false;
    for (const f of n.files) {
      if (matches.has(f.id)) any = true;
    }
    for (const child of n.folders.values()) {
      const childHas = walk(child);
      if (childHas) {
        out.add(child.path);
        any = true;
      }
    }
    return any;
  }
  walk(node);
  return out;
}

function _docPickerRender() {
  if (!_docPickerState) return;
  const s = _docPickerState;
  const q = (docPickerFilter.value || "").trim().toLowerCase();
  const items = s.items || [];
  // v176: precompute imported-set so we don't call isImported(it)
  // twice per row (once for badge, once for the hide filter).
  // Cache lives only for this render — small Map<id, true>.
  const importedIds = new Set();
  if (typeof s.isImported === "function") {
    for (const it of items) {
      try {
        if (s.isImported(it)) importedIds.add(it.id);
      } catch {}
    }
  }
  let filtered = q
    ? items.filter(
        (it) =>
          it.title.toLowerCase().includes(q) ||
          (it.subtitle || "").toLowerCase().includes(q)
      )
    : items;
  // v176: optional "Hide already imported" filter — applied after the
  // text filter so the running count reflects both filters together.
  if (s.hideImported && importedIds.size > 0) {
    filtered = filtered.filter((it) => !importedIds.has(it.id));
  }
  docPickerList.innerHTML = "";
  if (!filtered.length) {
    const empty = document.createElement("div");
    empty.className = "doc-picker-file-empty";
    empty.textContent = q
      ? s.noMatchText || "No matching items."
      : s.hideImported && importedIds.size > 0
      ? "Every file in this repo is already in your library or queue."
      : s.emptyText || "No items.";
    docPickerList.appendChild(empty);
    return;
  }

  // v182: tree-mode renderer. Builds a folder hierarchy from the
  // filtered items, then walks it recursively. Folders render as
  // disclosure rows (▸/▾ + folder icon + name + descendant count +
  // tri-state checkbox); files render as indented leaf rows with the
  // existing checkbox + ✓ imported badge + size.
  if (s.treeView) {
    _docPickerRenderTree(filtered, importedIds, q);
    return;
  }

  // Legacy flat list — Scrivener / Obsidian still use this path.
  for (const it of filtered) {
    docPickerList.appendChild(_docPickerMakeFileRow(it, importedIds, 0));
  }
}

// v182: render one file row. Extracted so both the flat list and the
// tree leaves can share it. `depth` is the indentation level (0 for
// flat / root, increments per folder); 0 leaves padding at the
// default so the legacy Scrivener / Obsidian layouts stay unchanged.
function _docPickerMakeFileRow(it, importedIds, depth) {
  const s = _docPickerState;
  const label = document.createElement("label");
  label.className = "doc-picker-file";
  const imported = importedIds.has(it.id);
  if (imported) label.classList.add("doc-picker-file-imported");
  if (depth > 0) {
    label.classList.add("doc-picker-file-leaf");
    label.style.paddingLeft = `${depth * 16 + 6}px`;
  }
  const cb = document.createElement("input");
  cb.type = "checkbox";
  cb.checked = s.selected.has(it.id);
  cb.addEventListener("change", (e) => {
    e.stopPropagation();
    if (cb.checked) s.selected.add(it.id);
    else s.selected.delete(it.id);
    _docPickerUpdateSummary();
    // v182: a leaf flip changes the tri-state ancestors above it. In
    // tree mode we re-render to refresh those rows; flat mode skips
    // the re-render to avoid scroll thrash.
    if (s.treeView) _docPickerRender();
  });
  const pathSpan = document.createElement("span");
  pathSpan.className = "doc-picker-file-path";
  // In tree mode, show only the basename (the folder path is conveyed
  // by indentation + parent rows). In flat mode keep the full path.
  let labelText = it.title;
  if (s.treeView) {
    const slash = (it.title || "").lastIndexOf("/");
    if (slash >= 0) labelText = it.title.slice(slash + 1);
  }
  pathSpan.textContent = it.subtitle ? `${labelText}  (${it.subtitle})` : labelText;
  if (imported) {
    const badge = document.createElement("span");
    badge.className = "doc-picker-file-imported-badge";
    badge.textContent = "✓ imported";
    badge.title = "Already in your library or sitting in the queue";
    pathSpan.appendChild(document.createTextNode(" "));
    pathSpan.appendChild(badge);
    // v223.tn16 (#485): if the caller wired up getSyncMeta, append
    // the matching clip's "last synced N min ago" timestamp next to
    // the badge. Quiet dim color — secondary signal, not the headline.
    if (s.getSyncMeta) {
      const meta = s.getSyncMeta(it);
      if (meta && meta.lastSyncedAt) {
        const rel = _formatTimeAgo(meta.lastSyncedAt);
        if (rel) {
          const tsSpan = document.createElement("span");
          tsSpan.className = "doc-picker-file-synced-ago";
          tsSpan.textContent = " · " + rel;
          tsSpan.title = new Date(meta.lastSyncedAt).toLocaleString();
          pathSpan.appendChild(tsSpan);
        }
      }
    }
  }
  const sizeSpan = document.createElement("span");
  sizeSpan.className = "doc-picker-file-size";
  sizeSpan.textContent = _docPickerItemSize(it);
  label.appendChild(cb);
  label.appendChild(pathSpan);
  label.appendChild(sizeSpan);
  return label;
}

// v182: tree-mode renderer — builds the folder hierarchy and walks
// it recursively. Folders that contain matching files auto-expand
// when a filter is active so the user can scan results without
// clicking through dozens of carets.
function _docPickerRenderTree(filteredItems, importedIds, q) {
  const s = _docPickerState;
  const tree = _docPickerBuildTree(filteredItems);
  // When filtering, all matching paths' ancestors auto-expand. When
  // not filtering, use the user's persisted expand state (so a manual
  // open survives across re-renders, e.g. after a checkbox flip).
  const matches = new Set(filteredItems.map((it) => it.id));
  const autoOpen = q ? _docPickerAutoExpanded(tree, matches) : null;
  function isOpen(path) {
    if (autoOpen && autoOpen.has(path)) return true;
    return s.expandedFolders.has(path);
  }

  function renderNode(node, depth) {
    const folderNames = Array.from(node.folders.keys()).sort((a, b) =>
      a.toLowerCase().localeCompare(b.toLowerCase())
    );
    for (const fname of folderNames) {
      const child = node.folders.get(fname);
      const row = _docPickerMakeFolderRow(child, depth, isOpen(child.path));
      docPickerList.appendChild(row);
      if (isOpen(child.path)) renderNode(child, depth + 1);
    }
    const sortedFiles = node.files
      .slice()
      .sort((a, b) => (a.title || "").toLowerCase().localeCompare(
        (b.title || "").toLowerCase()
      ));
    for (const f of sortedFiles) {
      docPickerList.appendChild(_docPickerMakeFileRow(f, importedIds, depth));
    }
  }
  renderNode(tree, 0);
}

// v182: render one folder row. Layout: [▸/▾] [📁/📂] name (n) [tri-state cb].
// Click the row (anywhere outside the checkbox) → toggle expand.
// Click the checkbox → toggle all descendant files (mirrors VSCode's
// search "select all in folder" feel).
function _docPickerMakeFolderRow(node, depth, open) {
  const s = _docPickerState;
  const row = document.createElement("div");
  row.className = "doc-picker-folder";
  row.style.paddingLeft = `${depth * 16 + 6}px`;
  // Caret + folder icon.
  const caret = document.createElement("span");
  caret.className = "doc-picker-folder-caret";
  caret.textContent = open ? "▾" : "▸";
  caret.setAttribute("aria-hidden", "true");
  const icon = document.createElement("span");
  icon.className = "doc-picker-folder-icon";
  icon.textContent = open ? "📂" : "📁";
  icon.setAttribute("aria-hidden", "true");
  const name = document.createElement("span");
  name.className = "doc-picker-folder-name";
  name.textContent = node.name;
  // Descendant count for quick scan ("chapters/ (35)").
  const descendants = _docPickerCollectFiles(node);
  const count = document.createElement("span");
  count.className = "doc-picker-folder-count";
  count.textContent = `(${descendants.length})`;
  // Tri-state checkbox — checked if all descendants selected, mixed
  // if some, unchecked if none. Click toggles all of them.
  const cb = document.createElement("input");
  cb.type = "checkbox";
  cb.className = "doc-picker-folder-cb";
  const selectedDescendants = descendants.filter((f) => s.selected.has(f.id));
  if (selectedDescendants.length === 0) {
    cb.checked = false;
    cb.indeterminate = false;
  } else if (selectedDescendants.length === descendants.length) {
    cb.checked = true;
    cb.indeterminate = false;
  } else {
    cb.checked = false;
    cb.indeterminate = true;
  }
  cb.addEventListener("click", (e) => e.stopPropagation());
  cb.addEventListener("change", () => {
    const turnOn = cb.checked;
    for (const f of descendants) {
      if (turnOn) s.selected.add(f.id);
      else s.selected.delete(f.id);
    }
    _docPickerUpdateSummary();
    _docPickerRender();
  });
  row.appendChild(caret);
  row.appendChild(icon);
  row.appendChild(name);
  row.appendChild(count);
  row.appendChild(cb);
  // Whole-row click toggles expand (except when the click started in
  // the checkbox — handled by stopPropagation above).
  row.addEventListener("click", () => {
    if (open) s.expandedFolders.delete(node.path);
    else s.expandedFolders.add(node.path);
    _docPickerRender();
  });
  return row;
}

function _docPickerUpdateSummary() {
  if (!_docPickerState) return;
  const s = _docPickerState;
  const items = s.items || [];
  const picked = items.filter((it) => s.selected.has(it.id));
  const n = picked.length;
  // Sum whichever metric the items carry. Mixed-shape lists shouldn't
  // happen within a single picker session, but fall back gracefully.
  const sumChars = picked.reduce((sum, it) => sum + (it.chars || 0), 0);
  const sumBytes = picked.reduce((sum, it) => sum + (it.size || 0), 0);
  const sizeStr = sumChars
    ? _docPickerFormatChars(sumChars)
    : sumBytes
    ? _docPickerFormatSize(sumBytes)
    : "";
  docPickerSummary.textContent = n
    ? `${n} selected${sizeStr ? ` · ~${sizeStr}` : ""}`
    : "";
  docPickerUse.disabled = n === 0;
  docPickerUse.textContent =
    n > 1
      ? (s.useLabelMulti && s.useLabelMulti(n)) || `Open as ${n}-chapter queue`
      : s.useLabelSingle || "Use selected";
  // v139: background toggle only makes sense for multi-pick (singles
  // bypass the queue entirely). Hide on 0/1 to avoid implying we'd
  // skip playback on a one-chapter load.
  docPickerBgLabel.hidden = n < 2;
}

function openDocumentPicker(config) {
  // Reset every render-driving piece of state. The dialog is reused
  // across sources, so leftover state from a previous open would leak
  // (stale items, stale filter, stale selected Set).
  _docPickerState = {
    items: Array.isArray(config.items) ? config.items : null,
    selected: new Set(),
    onUse: config.onUse || (async () => {}),
    emptyText: config.emptyText,
    noMatchText: config.noMatchText,
    useLabelSingle: config.useLabelSingle,
    useLabelMulti: config.useLabelMulti,
    // v176: caller-supplied predicate. Returns true if the item
    // should be flagged as "already imported" (library + queue
    // both count). When provided, the picker reveals the "Hide
    // already imported" toggle chip and shows ✓ badges + dim row
    // styling on each matching row.
    isImported: typeof config.isImported === "function" ? config.isImported : null,
    // v223.tn16 (#485): optional per-item sync-meta callback. Returns
    // { lastSyncedAt } (or null) for an item flagged as imported.
    // When present, the picker row appends "· N min ago" after the
    // ✓ imported badge so users see at a glance how fresh each file's
    // local clip is — useful when deciding whether to re-import.
    getSyncMeta: typeof config.getSyncMeta === "function" ? config.getSyncMeta : null,
    hideImported: false,
    // v182: VSCode-style tree rendering. Opt-in per caller. GitHub
    // turns it on because flat /path/to/chapter_03.md rows get unreadable
    // past ~30 files; Scrivener and Obsidian keep the flat list because
    // their items are already pre-grouped (chapter → scene) and a
    // second hierarchy would just nest.
    treeView: !!config.treeView,
    // Persistent expand state — survives re-renders triggered by
    // checkbox flips. Filter auto-expansion is computed per render
    // separately and doesn't mutate this Set.
    expandedFolders: new Set(),
  };
  docPickerTitle.textContent = config.title || "Pick items";
  docPickerMeta.textContent = config.meta || "";
  docPickerFilter.value = "";
  docPickerFilter.placeholder = config.filterPlaceholder || "Filter…";
  docPickerSummary.textContent = "";
  docPickerUse.disabled = true;
  docPickerUse.textContent = config.useLabelSingle || "Use selected";
  // v176: surface the hide-imported chip only when the caller can
  // tell us what's already imported. Reset its pressed state.
  if (docPickerHideImported) {
    const showChip = !!_docPickerState.isImported;
    docPickerHideImported.hidden = !showChip;
    docPickerHideImported.setAttribute("aria-pressed", "false");
  }
  // v179: reset branch picker + folder chips on every open. The
  // GitHub caller will fill them in via the returned handle once
  // /api/github/branches lands and the tree is parsed.
  if (docPickerBranchesRow) {
    docPickerBranchesRow.hidden = true;
    if (docPickerBranches) docPickerBranches.innerHTML = "";
  }
  if (docPickerFolderChips) {
    docPickerFolderChips.hidden = true;
    docPickerFolderChips.innerHTML = "";
  }
  // v139: reset background toggle on every open so a previously
  // ticked checkbox doesn't silently affect a fresh import.
  // v163: if the background queue is currently running, default the
  // checkbox to on so a quick-add round-trip ("+ Add more from
  // owner/repo") drops new picks straight into the queue instead
  // of forcing the user to remember to tick the box every time.
  // The label still hides until 2+ items are selected (see
  // _docPickerUpdateSummary), but the checked state is preserved.
  docPickerBgToggle.checked = !!_bgRunning;
  docPickerBgLabel.hidden = true;
  if (_docPickerState.items === null) {
    docPickerList.innerHTML = "";
  } else {
    _docPickerRender();
  }
  docPickerDialog.showModal();
  // Return a handle so the caller can mutate the dialog after open —
  // GitHub uses this to swap "Loading…" for the loaded file list (or
  // an error message) once /api/github/tree responds.
  return {
    setTitle(s) { docPickerTitle.textContent = s; },
    setMeta(s) { docPickerMeta.textContent = s; },
    setItems(arr) {
      if (!_docPickerState) return;
      _docPickerState.items = Array.isArray(arr) ? arr : [];
      _docPickerState.selected = new Set();
      _docPickerRender();
      _docPickerUpdateSummary();
    },
    // v179: populate the GitHub branch dropdown. `onChange` fires with
    // the new branch name when the user picks a different one — the
    // caller is responsible for re-fetching the tree on that branch.
    setBranches(list, current, onChange) {
      if (!docPickerBranchesRow || !docPickerBranches) return;
      if (!Array.isArray(list) || list.length === 0) {
        docPickerBranchesRow.hidden = true;
        return;
      }
      docPickerBranches.innerHTML = "";
      for (const name of list) {
        const opt = document.createElement("option");
        opt.value = name;
        opt.textContent = name;
        if (name === current) opt.selected = true;
        docPickerBranches.appendChild(opt);
      }
      docPickerBranchesRow.hidden = false;
      docPickerBranches.onchange = () => {
        if (typeof onChange === "function") onChange(docPickerBranches.value);
      };
    },
    // v179: populate the auto-suggest folder chips. Each entry is
    // {label, prefix}. Clicking a chip writes the prefix into the
    // filter input + triggers a re-render.
    setFolderChips(chips) {
      if (!docPickerFolderChips) return;
      if (!Array.isArray(chips) || chips.length === 0) {
        docPickerFolderChips.hidden = true;
        docPickerFolderChips.innerHTML = "";
        return;
      }
      docPickerFolderChips.innerHTML = "";
      const label = document.createElement("span");
      label.className = "doc-picker-folder-chips-label";
      label.textContent = "Filter to:";
      docPickerFolderChips.appendChild(label);
      for (const c of chips) {
        const chip = document.createElement("button");
        chip.type = "button";
        chip.className = "doc-picker-folder-chip";
        chip.textContent = c.label || c.prefix;
        chip.title = `Filter to files under ${c.prefix}`;
        chip.addEventListener("click", () => {
          // Toggle: if already filtered, clear; else apply.
          const current = (docPickerFilter.value || "").trim();
          if (current === c.prefix) {
            docPickerFilter.value = "";
            chip.classList.remove("active");
          } else {
            docPickerFilter.value = c.prefix;
            // Clear other active states so only one chip reads as on.
            docPickerFolderChips
              .querySelectorAll(".doc-picker-folder-chip.active")
              .forEach((el) => el.classList.remove("active"));
            chip.classList.add("active");
          }
          _docPickerRender();
        });
        docPickerFolderChips.appendChild(chip);
      }
      docPickerFolderChips.hidden = false;
    },
    close() { docPickerDialog.close(); },
  };
}

docPickerClose.addEventListener("click", () => docPickerDialog.close());
docPickerCancel.addEventListener("click", () => docPickerDialog.close());
docPickerFilter.addEventListener("input", _docPickerRender);
// v176: hide-imported chip toggle. Sets aria-pressed for the styling,
// flips _docPickerState.hideImported, re-renders.
if (docPickerHideImported) {
  docPickerHideImported.addEventListener("click", () => {
    if (!_docPickerState) return;
    _docPickerState.hideImported = !_docPickerState.hideImported;
    docPickerHideImported.setAttribute(
      "aria-pressed",
      _docPickerState.hideImported ? "true" : "false"
    );
    _docPickerRender();
  });
}

docPickerUse.addEventListener("click", async () => {
  if (!_docPickerState || _docPickerState.selected.size === 0) return;
  const s = _docPickerState;
  const picked = (s.items || []).filter((it) => s.selected.has(it.id));
  // v139: background mode only kicks in for multi-pick imports — a
  // single-clip load goes straight to the textarea, not a queue.
  const background = docPickerBgToggle.checked && picked.length > 1;
  // Close first so the caller can drive status updates in the UI
  // without competing with the dialog (e.g. "Fetching 1 of 5…").
  docPickerDialog.close();
  try {
    await s.onUse(picked, { background });
  } catch (err) {
    console.error("[doc-picker] onUse failed:", err);
    setStatus(`Failed: ${err.message || err}`, true);
  }
});

// ---- GitHub repo browser (uses shared document picker) ----------------
// openGithubBrowser opens the shared picker immediately with a
// "Loading…" placeholder, calls /api/github/tree, then either fills
// the picker with the file list or shows the error in the meta line.
// The Use callback fetches the selected file(s) via /api/extract/url
// (single = textarea; multi = chapter queue), threading the per-file
// SHA so the extract endpoint can skip an extra contents-API call.

async function openGithubBrowser(repoUrl) {
  // v176: build the "already imported" lookup ahead of opening the
  // picker. We don't know the canonical repoUrl until /api/github/tree
  // resolves (it might normalize the URL), so we collect both:
  //  - paths from clips whose gitRef.repoUrl matches this exact input
  //    URL (most common after a re-open of a previously-imported repo)
  //  - paths from bg queue items with a matching gitRef.repoUrl
  // The actual isImported callback below uses these sets; we refresh
  // them again after the tree call lands (closure mutation) so the
  // canonical URL also matches.
  const importedPaths = new Set();
  // v222 (#460): when the user re-imports a file via the picker, the
  // bg-queue should UPDATE the existing clip in place — not spawn a
  // duplicate. importedByPath maps gitRef.path → existing clip id so
  // the onUse handler can attach targetClipId to the queue item and
  // route through the existing v176 update-in-place path (same logic
  // the per-card 🔄 Re-narrate chip uses).
  //
  // When duplicates already exist in the library (because this fix
  // wasn't always there), prefer the most-recently-updated row so we
  // overwrite the live one rather than a stale tombstone.
  const importedByPath = new Map();
  const considerExisting = (clip) => {
    if (!clip || !clip.gitRef || clip.gitRef.repoUrl !== repoUrl) return;
    if (!clip.gitRef.path) return;
    const key = clip.gitRef.path;
    importedPaths.add(key);
    const prev = importedByPath.get(key);
    if (!prev || (clip.updatedAt && clip.updatedAt > prev.updatedAt)) {
      // v223.tn16 (#485): also stash lastSyncedAt so the picker can
      // surface "✓ imported · 17h ago" next to each row. Lets the
      // user see how fresh their local copy is before re-importing.
      importedByPath.set(key, {
        id: clip.id,
        updatedAt: clip.updatedAt || "",
        lastSyncedAt: clip.lastSyncedAt || null,
      });
    }
  };
  const pathsFromUrl = (url) => {
    if (!url) return;
    for (const j of _chapterQueue) {
      if (j && j.gitRef && j.gitRef.repoUrl === url && j.gitRef.path) {
        importedPaths.add(j.gitRef.path);
      }
    }
  };
  try {
    const allClips = await listClips();
    for (const c of allClips) considerExisting(c);
  } catch {}
  pathsFromUrl(repoUrl);

  const picker = openDocumentPicker({
    title: "Browse GitHub repo",
    meta: "Loading…",
    items: null,
    filterPlaceholder: "Filter by path…",
    emptyText: "No text-format files found in this repo.",
    noMatchText: "No matching files.",
    // v176: predicate the picker uses for ✓ badge + dim + the
    // "Hide already imported" filter chip. extra.path is the
    // GitHub-side file path.
    isImported: (item) => {
      const p = item && item.extra && item.extra.path;
      return p ? importedPaths.has(p) : false;
    },
    // v223.tn16 (#485): return the matching clip's lastSyncedAt so
    // the picker row can render "✓ imported · N min ago".
    getSyncMeta: (item) => {
      const p = item && item.extra && item.extra.path;
      const entry = p ? importedByPath.get(p) : null;
      return entry || null;
    },
    // v182: VSCode-style folder hierarchy. Big repos (185+ files in
    // the screenshot) get unreadable as a flat list — group by folder,
    // collapse by default, filter auto-expands matches.
    treeView: true,
    onUse: async (picked, opts = {}) => {
      // Items carry the raw GitHub file objects in `extra`. Build the
      // raw.githubusercontent URLs and a path→sha lookup for the
      // extract endpoint.
      const token = getGithubToken();
      const buildUrl = (path) =>
        `https://raw.githubusercontent.com/${gh.owner}/${gh.repo}/${gh.branch}/${encodeURI(path)}`;
      hideUrlRow();

      if (picked.length === 1) {
        const f = picked[0].extra;
        setStatus(`Fetching ${f.path}…`);
        try {
          const res = await fetch("/api/extract/url", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              url: buildUrl(f.path),
              github_token: token || undefined,
              git_sha: f.sha || undefined,
            }),
          });
          if (!res.ok) {
            let detail = `HTTP ${res.status}`;
            try { const j = await res.json(); if (j.detail) detail = j.detail; } catch {}
            throw new Error(detail);
          }
          const data = await res.json();
          exitReadingView();
          textEl.value = data.text || "";
          // v4.79 (#881): overwrite ALL the pending image state, not just
          // _pendingImages. Previously this branch only touched the inline
          // images array, so a previous import's _pendingDetectedCover and
          // _pendingChapterImages would survive into this fetch and get
          // attached to the saved clip at Generate time. User reported
          // picking the wrong repo first, then picking the right one, and
          // seeing the wrong repo's screenshot inline images persist into
          // the new clip's library card. The multi-file branch below
          // already does this correctly (29519-29522); this aligns the
          // single-file branch with the same contract.
          _pendingImages = Array.isArray(data.images) ? data.images : [];
          _pendingDetectedCover =
            (data.cover && typeof data.cover === "object" && data.cover.src)
              ? data.cover
              : null;
          _pendingChapterImages =
            Array.isArray(data.chapter_images)
              ? data.chapter_images.filter((c) => c && c.src)
              : [];
          _pendingGitRef = data.gitRef || null;
          // v4.79 (#881): also call _paintImportPreview so the visible
          // thumbnail strip ("Detected in this import") repaints. Without
          // this, even when the state above gets cleared correctly, the
          // DOM still shows whatever was painted by the previous import —
          // so the user sees stale thumbs that imply they'll attach to
          // the new save. Repaint here keeps the visible truth in sync.
          if (typeof _paintImportPreview === "function") _paintImportPreview();
          updateCounts();
          _checkForChapters();
          setStatus(`Loaded ${f.path} · ${(data.chars || 0).toLocaleString()} chars · ready to Generate`);
          textEl.focus();
        } catch (err) {
          setStatus(_withOfflineHint(`Fetch failed: ${err.message}`), true);
        }
        return;
      }

      setStatus(`Fetching ${picked.length} files…`);
      _dlog("github", `multi-fetch start: ${picked.length} files`, {
        owner: gh.owner, repo: gh.repo, branch: gh.branch,
        paths: picked.map((p) => p.extra && p.extra.path).filter(Boolean),
      });
      const chapters = [];
      const skipped = []; // {path, reason} for the post-loop summary
      for (let i = 0; i < picked.length; i++) {
        const f = picked[i].extra;
        setStatus(`Fetching ${i + 1} of ${picked.length}: ${f.path}…`);
        _dlog("github", `fetch [${i + 1}/${picked.length}] ${f.path}`, {
          sha: f.sha, size: f.size,
        });
        try {
          const res = await fetch("/api/extract/url", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              url: buildUrl(f.path),
              github_token: token || undefined,
              git_sha: f.sha || undefined,
            }),
          });
          if (!res.ok) {
            let detail = `HTTP ${res.status}`;
            try {
              const j = await res.json();
              if (j && j.detail) detail += ` — ${j.detail}`;
            } catch {}
            _dlog("github", `SKIP ${f.path}: ${detail}`, { status: res.status });
            skipped.push({ path: f.path, reason: detail });
            console.warn(`[github] skipping ${f.path}: ${detail}`);
            continue;
          }
          const data = await res.json();
          const rawText = data.text || "";
          const cleanText = rawText.trim();
          // v177: empty-text guard. Some files (TOC.md, image-only
          // chapters, all-frontmatter, etc.) return empty text after
          // trafilatura strips boilerplate. Pushing an empty-text
          // chapter into the queue guarantees a downstream synthesis
          // failure ("no audio in result") with a useless error in
          // the failures banner. Catch it here so the user sees a
          // specific "empty content" reason and the synth path never
          // runs.
          if (!cleanText) {
            _dlog(
              "github",
              `SKIP ${f.path}: empty text after extract`,
              {
                rawChars: rawText.length,
                cleanChars: 0,
                images: Array.isArray(data.images) ? data.images.length : 0,
              }
            );
            skipped.push({ path: f.path, reason: "empty after extract" });
            continue;
          }
          const title = f.path.split("/").pop().replace(/\.[^.]+$/, "");
          // v222 (#460): if a clip already exists for this gitRef.path
          // (lookup populated at picker open), attach targetClipId so
          // the bg-queue updates in place instead of duplicating. The
          // bg-queue's _bgTrySynth path already handles targetClipId
          // and carries forward bookmarks / notes / cover / tags.
          const existingMatch = importedByPath.get(f.path);
          const targetClipId = existingMatch ? existingMatch.id : null;
          _dlog("github", `OK ${f.path}`, {
            title,
            chars: cleanText.length,
            sha: (data.gitRef && data.gitRef.sha) || f.sha || null,
            images: Array.isArray(data.images) ? data.images.length : 0,
            targetClipId,
          });
          chapters.push({
            title,
            text: cleanText,
            gitRef: data.gitRef || null,
            targetClipId,
          });
        } catch (err) {
          _dlog("github", `THROW ${f.path}: ${err.message}`, {
            errName: err.name, stack: err.stack,
          });
          skipped.push({ path: f.path, reason: err.message });
          console.warn(`[github] skipping ${f.path}: ${err.message}`);
        }
      }
      _dlog("github", `multi-fetch done`, {
        ok: chapters.length, skipped: skipped.length, skips: skipped,
      });
      if (chapters.length === 0) {
        const tail = skipped.length
          ? ` (${skipped.length} skipped — see Settings → View debug log)`
          : "";
        setStatus(`No files could be fetched.${tail}`, true);
        return;
      }
      if (skipped.length) {
        // Non-fatal: some files made it through. Quick toast so the
        // user notices the gap; the debug log has per-file detail.
        setStatus(
          `${chapters.length} fetched, ${skipped.length} skipped — see Settings → View debug log`
        );
      }
      if (chapters.length === 1) {
        exitReadingView();
        textEl.value = chapters[0].text;
        _pendingChapterTitle = chapters[0].title;
        _pendingImages = [];
        _pendingGitRef = null;
        _pendingDetectedCover = null;
        _pendingChapterImages = [];
        if (typeof _paintImportPreview === "function") _paintImportPreview();
        updateCounts();
        _checkForChapters();
        setStatus(`Loaded ${chapters[0].title} · ready to Generate`);
        return;
      }
      // v139: background mode runs synthesis silently — chapters land
      // in the library without ever loading into the player. Ideal
      // for unattended overnight imports.
      if (opts.background) {
        _startBackgroundChapterQueue(chapters);
      } else {
        _startChapterQueue(chapters);
      }
    },
  });

  // Stash owner/repo/branch for the Use callback. Closure captures the
  // mutable handle, but we still need the response data after fetch.
  let gh = { owner: "", repo: "", branch: "" };
  try {
    const token = getGithubToken();
    const branch = _githubBranchFromUrl(repoUrl);
    const res = await fetch("/api/github/tree", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        url: repoUrl,
        branch: branch || undefined,
        github_token: token || undefined,
      }),
    });
    if (!res.ok) {
      let detail = `HTTP ${res.status}`;
      try {
        const j = await res.json();
        if (j.detail) detail = j.detail;
      } catch {}
      throw new Error(detail);
    }
    const data = await res.json();
    gh = { owner: data.owner, repo: data.repo, branch: data.branch };
    // v163 / v176: remember this repo on the recents list so the user
    // can re-open it with one click — chip rows above the URL field
    // and in the queue panel footer surface up to RECENT_REPOS_MAX
    // entries, most-recent-first.
    _pushRecentGithubRepo({
      url: repoUrl,
      owner: data.owner,
      repo: data.repo,
      branch: data.branch,
    });
    // v176: refresh the imported-paths set against the canonical URL
    // returned by /api/github/tree. clip.gitRef.repoUrl could have
    // been written by an older path that normalized differently
    // (trailing slash, .git suffix, www subdomain).
    try {
      const allClips = await listClips();
      for (const c of allClips) {
        if (
          c.gitRef &&
          c.gitRef.path &&
          (c.gitRef.repoUrl === repoUrl ||
            (data.owner &&
              data.repo &&
              c.gitRef.repoUrl &&
              c.gitRef.repoUrl.toLowerCase().includes(
                `${data.owner.toLowerCase()}/${data.repo.toLowerCase()}`
              )))
        ) {
          importedPaths.add(c.gitRef.path);
        }
      }
    } catch {}
    for (const j of _chapterQueue) {
      if (
        j &&
        j.gitRef &&
        j.gitRef.path &&
        j.gitRef.repoUrl &&
        data.owner &&
        data.repo &&
        j.gitRef.repoUrl.toLowerCase().includes(
          `${data.owner.toLowerCase()}/${data.repo.toLowerCase()}`
        )
      ) {
        importedPaths.add(j.gitRef.path);
      }
    }
    const files = Array.isArray(data.files) ? data.files : [];
    picker.setTitle(`${data.owner}/${data.repo}`);
    const truncatedHint = data.truncated
      ? " · ⚠ tree truncated by GitHub (large repo)"
      : "";
    const importedCount = files.reduce(
      (n, f) => n + (importedPaths.has(f.path) ? 1 : 0),
      0
    );
    const importedNote = importedCount > 0
      ? ` · ${importedCount} already imported`
      : "";
    picker.setMeta(
      `branch: ${data.branch} · ${files.length} text files${truncatedHint}${importedNote}`
    );
    picker.setItems(
      files.map((f) => ({
        id: f.path,
        title: f.path,
        size: f.size,
        extra: f,
      }))
    );
    // v179: detect common manuscript folders so the picker can offer
    // one-click filter chips. Looks for paths that share a top-level
    // segment (chapters/, manuscript/, src/, etc.) with >=3 files.
    // Skips suggestions when the whole repo lives under one folder
    // (no point offering a filter that doesn't filter anything).
    if (typeof picker.setFolderChips === "function") {
      const chips = _suggestFolderChips(files);
      picker.setFolderChips(chips);
    }
    // v179: fetch branches in parallel with rendering. Failure is
    // non-fatal — the picker still works on the resolved branch.
    if (typeof picker.setBranches === "function") {
      try {
        const bRes = await fetch("/api/github/branches", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            url: repoUrl,
            github_token: token || undefined,
          }),
        });
        if (bRes.ok) {
          const bData = await bRes.json();
          picker.setBranches(
            bData.branches || [],
            data.branch,
            (newBranch) => {
              if (!newBranch || newBranch === data.branch) return;
              // Re-open the picker for the same repo on the new
              // branch. openGithubBrowser builds the /tree/<branch>
              // URL by parsing the URL, so we need to inject the
              // branch in the URL form GitHub expects.
              const swapped = _withGithubBranch(repoUrl, newBranch);
              picker.close();
              openGithubBrowser(swapped);
            }
          );
        } else {
          _dlog("github", "branches fetch failed", { status: bRes.status });
        }
      } catch (err) {
        _dlog("github", `branches fetch threw: ${err.message}`, {});
      }
    }
  } catch (err) {
    picker.setMeta(`Failed: ${err.message}`);
    picker.setItems([]);
  }
}

// v179: walk the GitHub tree and surface common manuscript folders
// as suggested filters. A "chip-worthy" folder is one that:
//   - has at least 3 files under it (otherwise the filter is noise)
//   - isn't the only folder in the repo (filtering everything ≠ filtering)
//   - has a known manuscript-y name OR happens to be the densest folder
// Returns an array of {label, prefix} ready for picker.setFolderChips.
function _suggestFolderChips(files) {
  if (!Array.isArray(files) || files.length < 3) return [];
  // Tally files per top-level folder.
  const counts = new Map();
  let rootCount = 0;
  for (const f of files) {
    const slash = (f.path || "").indexOf("/");
    if (slash < 0) {
      rootCount++;
    } else {
      const top = f.path.slice(0, slash);
      counts.set(top, (counts.get(top) || 0) + 1);
    }
  }
  // If everything is at the root, or all files live in one folder,
  // a folder filter doesn't help — bail out.
  if (counts.size === 0) return [];
  if (counts.size === 1 && rootCount === 0) return [];

  // Folder names common in manuscripts and dev repos that host books.
  const FAVORED = new Set([
    "chapters", "chapter", "manuscript", "manuscripts", "src", "content",
    "book", "books", "novel", "novels", "drafts", "draft", "posts",
    "essays", "writing", "writings", "docs", "doc", "pages", "story",
  ]);

  // Build the chip list: favored folders (with >=3 files) first,
  // then the single densest non-favored folder as a fallback —
  // capped at 3 chips total so the row doesn't bloat.
  const chips = [];
  for (const [name, n] of counts.entries()) {
    if (n >= 3 && FAVORED.has(name.toLowerCase())) {
      chips.push({ label: `${name}/`, prefix: `${name}/`, count: n });
    }
  }
  if (chips.length === 0) {
    // No favored match — surface the densest folder if it covers
    // a meaningful fraction of the tree.
    let best = null;
    for (const [name, n] of counts.entries()) {
      if (n < 3) continue;
      if (!best || n > best.count) best = { name, count: n };
    }
    if (best && best.count >= Math.max(3, files.length * 0.3)) {
      chips.push({ label: `${best.name}/`, prefix: `${best.name}/`, count: best.count });
    }
  }
  chips.sort((a, b) => b.count - a.count);
  return chips.slice(0, 3).map(({ label, prefix }) => ({ label, prefix }));
}

// v179: swap the branch segment in a github.com URL so the recents
// list / picker can re-open the same repo on a different branch
// without the user re-typing. Accepts both the repo-root form
// (github.com/owner/repo) and the tree form
// (github.com/owner/repo/tree/<branch>/...) — returns the tree form.
function _withGithubBranch(url, branch) {
  try {
    const u = new URL(url);
    if (!u.hostname.endsWith("github.com")) return url;
    const parts = u.pathname.split("/").filter(Boolean);
    if (parts.length < 2) return url;
    const owner = parts[0];
    const repo = parts[1].replace(/\.git$/, "");
    // Drop any existing /tree/<branch>/... suffix; we'll rebuild it.
    u.pathname = `/${owner}/${repo}/tree/${encodeURIComponent(branch)}`;
    return u.toString();
  } catch {
    return url;
  }
}

// v181: open the shared picker on a Gist's file list.
//
// Single-file gists short-circuit: we fetch the file content directly
// via /api/extract/url with the raw_url + skip the picker.
//
// Multi-file gists open the picker. Selecting one file loads it into
// the textarea (same as the GitHub single-pick path); selecting
// multiple files queues them as a multi-chapter import.
async function openGistBrowser(gistUrl) {
  hideUrlRow();
  setStatus(`Fetching Gist…`);
  const token = getGithubToken();
  let meta;
  try {
    const res = await fetch("/api/gist/meta", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        url: gistUrl,
        github_token: token || undefined,
      }),
    });
    if (!res.ok) {
      let detail = `HTTP ${res.status}`;
      try { const j = await res.json(); if (j.detail) detail = j.detail; } catch {}
      throw new Error(detail);
    }
    meta = await res.json();
  } catch (err) {
    _dlog && _dlog("gist", `meta fetch failed: ${err.message}`, {});
    setStatus(_withOfflineHint(`Gist fetch failed: ${err.message}`), true);
    return;
  }
  const files = Array.isArray(meta.files) ? meta.files : [];
  if (files.length === 0) {
    setStatus("This Gist has no files.", true);
    return;
  }

  // Single-file gist: route straight to the textarea via the existing
  // URL extractor on the file's raw URL. The picker would just be one
  // extra click for no win.
  if (files.length === 1) {
    const f = files[0];
    setStatus(`Loading ${f.filename}…`);
    try {
      const res = await fetch("/api/extract/url", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          url: f.raw_url,
          github_token: token || undefined,
        }),
      });
      if (!res.ok) {
        let detail = `HTTP ${res.status}`;
        try { const j = await res.json(); if (j.detail) detail = j.detail; } catch {}
        throw new Error(detail);
      }
      const data = await res.json();
      exitReadingView();
      textEl.value = data.text || "";
      // v4.79 (#881): same pending-state-leak gap as the GitHub picker's
      // single-file branch fixed in the same release. Gists never return
      // covers or chapter_images (they're per-file raw fetches), so
      // these always clear to null/[] — but the previous import may have
      // set them, and without an explicit clear they survive and get
      // attached to the new clip at save. _paintImportPreview repaints
      // the visible strip; without it the DOM holds the old thumbnails.
      _pendingImages = Array.isArray(data.images) ? data.images : [];
      _pendingDetectedCover = null;
      _pendingChapterImages = [];
      _pendingGitRef = null; // Gist files don't have a gitRef we can sync against
      _pendingChapterTitle = f.filename.replace(/\.[^.]+$/, "");
      if (typeof _paintImportPreview === "function") _paintImportPreview();
      updateCounts();
      _checkForChapters();
      setStatus(
        `Loaded ${f.filename} · ${(data.chars || 0).toLocaleString()} chars · ready to Generate`
      );
      textEl.focus();
    } catch (err) {
      _dlog && _dlog("gist", `single-file fetch failed: ${err.message}`, {
        filename: f.filename,
      });
      setStatus(_withOfflineHint(`Gist fetch failed: ${err.message}`), true);
    }
    return;
  }

  // Multi-file: open the picker. Each file becomes a candidate
  // chapter in the picker; on Use, we fetch each file's raw_url via
  // /api/extract/url and feed the resulting chapters to the queue.
  const title = meta.owner
    ? `Gist by @${meta.owner}`
    : "GitHub Gist";
  const picker = openDocumentPicker({
    title,
    meta: meta.description || `${files.length} files`,
    items: files.map((f) => ({
      id: f.filename,
      title: f.filename,
      subtitle: f.language || f.type || "",
      size: f.size,
      extra: f,
    })),
    filterPlaceholder: "Filter by filename…",
    emptyText: "No files in this gist.",
    noMatchText: "No matching files.",
    onUse: async (picked, opts = {}) => {
      if (picked.length === 1) {
        const f = picked[0].extra;
        setStatus(`Loading ${f.filename}…`);
        try {
          const res = await fetch("/api/extract/url", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              url: f.raw_url,
              github_token: token || undefined,
            }),
          });
          if (!res.ok) {
            let detail = `HTTP ${res.status}`;
            try { const j = await res.json(); if (j.detail) detail = j.detail; } catch {}
            throw new Error(detail);
          }
          const data = await res.json();
          exitReadingView();
          textEl.value = data.text || "";
          _pendingImages = Array.isArray(data.images) ? data.images : [];
          _pendingGitRef = null;
          _pendingChapterTitle = f.filename.replace(/\.[^.]+$/, "");
          updateCounts();
          _checkForChapters();
          setStatus(`Loaded ${f.filename} · ready to Generate`);
        } catch (err) {
          setStatus(_withOfflineHint(`Gist fetch failed: ${err.message}`), true);
        }
        return;
      }
      setStatus(`Fetching ${picked.length} files…`);
      const chapters = [];
      const skipped = [];
      for (let i = 0; i < picked.length; i++) {
        const f = picked[i].extra;
        setStatus(`Fetching ${i + 1} of ${picked.length}: ${f.filename}…`);
        try {
          const res = await fetch("/api/extract/url", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              url: f.raw_url,
              github_token: token || undefined,
            }),
          });
          if (!res.ok) {
            skipped.push({ filename: f.filename, reason: `HTTP ${res.status}` });
            continue;
          }
          const data = await res.json();
          const clean = (data.text || "").trim();
          // Same empty-text guard as the GitHub multi-fetch path.
          if (!clean) {
            skipped.push({ filename: f.filename, reason: "empty after extract" });
            continue;
          }
          chapters.push({
            title: f.filename.replace(/\.[^.]+$/, ""),
            text: clean,
          });
        } catch (err) {
          skipped.push({ filename: f.filename, reason: err.message });
        }
      }
      if (chapters.length === 0) {
        const tail = skipped.length
          ? ` (${skipped.length} skipped — see Settings → View debug log)`
          : "";
        setStatus(`No files could be loaded.${tail}`, true);
        return;
      }
      if (skipped.length) {
        setStatus(
          `${chapters.length} fetched, ${skipped.length} skipped — see Settings → View debug log`
        );
        _dlog && _dlog("gist", "multi-fetch done with skips", {
          ok: chapters.length, skipped,
        });
      }
      if (opts.background) {
        _startBackgroundChapterQueue(chapters);
      } else {
        _startChapterQueue(chapters);
      }
    },
  });
}

// ---- Scrivener browser (uses shared document picker) ------------------
// Opened by the upload handler when the user picks a .zip file and
// the backend detects it's a Scrivener bundle. Chapters are already
// parsed in-memory by /api/extract/scrivener — the picker just hands
// the selected chapters off to the textarea (single) or chapter
// queue (multi). No gitRef because Scrivener bundles aren't sync-
// checkable (file-system-only, no remote SHA).

function openScrivenerBrowser(data) {
  const chapters = Array.isArray(data.chapters) ? data.chapters : [];
  const skipped = Array.isArray(data.skipped) ? data.skipped : [];
  const skippedHint = skipped.length
    ? ` · ${skipped.length} skipped (Research/Trash/empty)`
    : "";
  openDocumentPicker({
    title: data.project_name || "Scrivener project",
    meta: `${chapters.length} chapter${chapters.length === 1 ? "" : "s"} found${skippedHint}`,
    filterPlaceholder: "Filter by title or folder…",
    emptyText: "No chapters in this project.",
    noMatchText: "No matching chapters.",
    items: chapters.map((c) => ({
      id: c.id,
      title: c.title,
      subtitle: c.path || "",
      chars: c.chars,
      extra: c,
    })),
    onUse: async (picked, opts = {}) => {
      // v4.96 (#538 Phase 2): build the scrivenerRef so generate()
      // can pin it onto the saved clip. doc_id is the only id the
      // patch endpoint needs; project_name + doc_path are display.
      const refFor = (ch) => ({
        project_name: data.project_name || "",
        doc_id: ch.id,
        doc_path: ch.path || "",
      });
      if (picked.length === 1) {
        const ch = picked[0].extra;
        exitReadingView();
        textEl.value = ch.text;
        _pendingChapterTitle = ch.title;
        _pendingImages = [];
        _pendingGitRef = null;
        _pendingScrivenerRef = refFor(ch);
        _pendingDetectedCover = null;
        _pendingChapterImages = [];
        if (typeof _paintImportPreview === "function") _paintImportPreview();
        updateCounts();
        _checkForChapters();
        setStatus(`Loaded ${ch.title} · ready to Generate`);
        return;
      }
      const chapters = picked.map((p) => ({
        title: p.extra.title,
        text: p.extra.text,
        scrivenerRef: refFor(p.extra),
      }));
      if (opts.background) {
        _startBackgroundChapterQueue(chapters);
      } else {
        _startChapterQueue(chapters);
      }
    },
  });
}

// ---- Obsidian vault browser (uses shared document picker) -------------
// Backend already filtered out .obsidian/, templates/, attachments/, etc.
// and stripped wikilinks + embeds from the body. The picker just lets
// the user choose which notes to import as chapters.

function openObsidianBrowser(data) {
  const chapters = Array.isArray(data.chapters) ? data.chapters : [];
  const skipped = Array.isArray(data.skipped) ? data.skipped : [];
  const skippedHint = skipped.length
    ? ` · ${skipped.length} skipped (.obsidian/templates/empty)`
    : "";
  openDocumentPicker({
    title: data.vault_name || "Obsidian vault",
    meta: `${chapters.length} note${chapters.length === 1 ? "" : "s"} found${skippedHint}`,
    filterPlaceholder: "Filter by title or folder…",
    emptyText: "No notes in this vault.",
    noMatchText: "No matching notes.",
    items: chapters.map((c) => ({
      id: c.id,
      title: c.title,
      subtitle: c.path || "",
      chars: c.chars,
      extra: c,
    })),
    onUse: async (picked, opts = {}) => {
      if (picked.length === 1) {
        const ch = picked[0].extra;
        exitReadingView();
        textEl.value = ch.text;
        _pendingChapterTitle = ch.title;
        _pendingImages = [];
        _pendingGitRef = null;
        _pendingDetectedCover = null;
        _pendingChapterImages = [];
        if (typeof _paintImportPreview === "function") _paintImportPreview();
        updateCounts();
        _checkForChapters();
        setStatus(`Loaded ${ch.title} · ready to Generate`);
        return;
      }
      const chapters = picked.map((p) => ({
        title: p.extra.title,
        text: p.extra.text,
      }));
      if (opts.background) {
        _startBackgroundChapterQueue(chapters);
      } else {
        _startChapterQueue(chapters);
      }
    },
  });
}

// Deep-link from the manual: visiting "/?prefillUrl=https%3A%2F%2F..."
// (optionally with "&autofetch=1") opens the URL row, pre-fills the
// input, and — when autofetch is set — runs the fetch immediately so
// a tester can click a sample URL in the manual and land on a loaded
// article one click later.
(function _handlePrefillUrlFromQuery() {
  try {
    const params = new URLSearchParams(location.search);
    const u = params.get("prefillUrl");
    if (!u) return;
    showUrlRow();
    urlInput.value = u;
    const auto = params.get("autofetch") === "1";
    // Strip the query param so a reload doesn't re-trigger the fetch
    // (the user expects reload to start fresh, not re-grab the same
    // article).
    history.replaceState(null, "", location.pathname);
    if (auto) {
      // Defer so the existing setStatus / busy-state UI has time to
      // render before the fetch's "Fetching…" status overwrites it.
      setTimeout(() => fetchFromUrl(), 50);
    }
  } catch {}
})();

// True if a URL points at a GitHub repo view that should open the file
// browser (rather than fetching the URL's HTML page). Covers:
//   - github.com/owner/repo                          → default branch
//   - github.com/owner/repo/tree/main                → explicit branch
//   - github.com/owner/repo/tree/main/folder         → folder view
// Excluded: blob/ raw/ are specific files (Level 1 fetches those);
// commit/ issues/ pull/ releases/ wiki/ aren't manuscripts.
function _isGithubRepoRoot(url) {
  try {
    const u = new URL(url);
    if (u.hostname !== "github.com" && u.hostname !== "www.github.com") {
      return false;
    }
    const parts = u.pathname.split("/").filter(Boolean);
    if (parts.length < 2) return false;
    if (parts.length === 2) return true; // owner/repo
    const verb = parts[2];
    if (verb === "tree") return true; // branch / folder view
    return false;
  } catch {
    return false;
  }
}

// v142: graceful normalization for github URLs the user might
// reasonably paste but that aren't a repo root — most commonly a
// /blob/<branch>/<path> URL to a specific chapter file. Returns
// {rootUrl, original, kind} when the input is a github URL we can
// strip back to a browseable repo, null otherwise. kind is one of
// "root" (already a root or tree URL — no correction needed),
// "file" (/blob/ — stripped to owner/repo), or "other" (issues /
// pulls / commits / etc — also stripped to owner/repo).
function _normalizeGithubUrl(url) {
  try {
    const u = new URL(url);
    if (u.hostname !== "github.com" && u.hostname !== "www.github.com") {
      return null;
    }
    const parts = u.pathname.split("/").filter(Boolean);
    if (parts.length < 2) return null;
    const owner = parts[0];
    const repo = parts[1];
    const rootUrl = `https://github.com/${owner}/${repo}`;
    if (parts.length === 2) {
      return { rootUrl, original: url, kind: "root" };
    }
    const verb = parts[2];
    if (verb === "tree") {
      // owner/repo/tree/<branch>[/<path>] — _isGithubRepoRoot already
      // routes this directly; surface as "root" so we don't show a
      // correction message for a URL that was always going to work.
      return { rootUrl: url, original: url, kind: "root" };
    }
    if (verb === "blob") {
      return { rootUrl, original: url, kind: "file" };
    }
    // /issues, /pulls, /commits, /actions, /wiki, /releases, etc.
    return { rootUrl, original: url, kind: "other" };
  } catch {
    return null;
  }
}


// Extract the branch name from a /tree/<branch>/ URL. Returns null if
// the URL doesn't carry a branch (we'll let the server look up the
// repo's default).
function _githubBranchFromUrl(url) {
  try {
    const u = new URL(url);
    const parts = u.pathname.split("/").filter(Boolean);
    if (parts.length >= 4 && parts[2] === "tree") {
      return parts[3];
    }
  } catch {}
  return null;
}

// v4.100 (#896): extracted from fetchFromUrl so the Drive Picker import
// path applies a fetched document the exact same way a URL fetch does.
// `data` is the server's {filename, chars, text, images, gitRef?} shape
// from /api/extract/url, /api/extract/gdrive, or /api/gdrive/fetch.
function _applyImportedDocument(data) {
  // Same shape as the file-upload path — keep behavior aligned.
  exitReadingView();
  textEl.value = data.text || "";
  // Stash any images the server pulled out. They survive until the next
  // generate() saves them onto the clip (or until the user hits Clear).
  _pendingImages = Array.isArray(data.images) ? data.images : [];
  // GitHub-sourced URLs come back with gitRef; stash so the next
  // generate() pins it onto the saved clip. (Drive has no gitRef.)
  _pendingGitRef = data.gitRef || null;
  // v225fz11.cover (#677): URL/Drive fetch doesn't run image_detector
  // (covers come from file uploads only). Reset so a previously uploaded
  // file's cover doesn't leak into this fetched clip.
  _pendingDetectedCover = null;
  // v225fz12.chapter-images (#678): same — no chapter_images here; reset
  // so they don't leak across imports.
  _pendingChapterImages = [];
  // v225g6 (#695): same fresh-start semantics as the upload path —
  // release the ebook-kind gate + drop the previous clip id so the phone
  // Generate bar reappears and a Generate tap doesn't route through the
  // regen path against an unrelated old clip.
  if (typeof _setCurrentClipKind === "function") {
    _setCurrentClipKind(null);
  }
  _currentClipId = null;
  if (typeof window._syncPhoneGenerateBar === "function") {
    try { window._syncPhoneGenerateBar(); } catch {}
  }
  // v225fz14 (#688): repaint preview strip (fetch can still contribute
  // inline images via _pendingImages above).
  _paintImportPreview();
  updateCounts();
  _checkForChapters();
}

async function fetchFromUrl() {
  const url = (urlInput.value || "").trim();
  if (!url) return;
  // v181: Gist URLs go through a separate flow. /api/gist/meta returns
  // the file list; single-file gists land in the textarea directly,
  // multi-file gists open the picker so the user can choose which
  // files become chapters.
  if (_isGistUrl(url)) {
    openGistBrowser(url);
    return;
  }
  // GitHub repo root URLs → open the file browser instead of fetching
  // the landing page (which trafilatura would extract as marketing
  // chrome, not as a manuscript).
  if (_isGithubRepoRoot(url)) {
    openGithubBrowser(url);
    return;
  }
  // v142: graceful fallback for "wrong-shape" github URLs the user
  // might paste — a /blob/ file URL, a /pull/ link, etc. Instead of
  // letting it slide through to trafilatura (which silently fails on
  // most of those), strip to the repo root and tell the user what
  // we did so they understand the picker that just opened.
  const gh = _normalizeGithubUrl(url);
  if (gh && gh.kind !== "root") {
    if (gh.kind === "file") {
      setStatus(
        "That looked like a link to a specific file. Opening the repo's chapter picker instead — tick the chapter(s) you want.",
      );
    } else {
      setStatus(
        "Opening the repo's chapter picker — paste the repo root URL next time to skip this step.",
      );
    }
    openGithubBrowser(gh.rootUrl);
    return;
  }
  urlInput.disabled = true;
  urlFetchBtn.disabled = true;
  urlFetchBtn.textContent = "Fetching…";
  // Show the bare hostname while we wait so the user knows we're hitting
  // the right place (and not eg. truncating their URL).
  let host = url;
  try {
    host = new URL(url).hostname || url;
  } catch {}
  setStatus(`Fetching ${host}…`);

  try {
    // Attach a GitHub PAT only when the URL is a GitHub URL. The token
    // lives in localStorage; the backend further restricts forwarding
    // to github.com / raw.githubusercontent.com so a stale token can't
    // leak to other hosts via a redirect.
    const body = { url };
    if (_isGithubUrl(url)) {
      const token = getGithubToken();
      if (token) body.github_token = token;
    }
    // v4.96 (#892): Drive URLs route through /api/extract/gdrive so the
    // backend can resolve Google Docs to a DOCX export instead of
    // trying to trafilatura-parse the share landing page.
    const endpoint = _isGdriveUrl(url)
      ? "/api/extract/gdrive"
      : "/api/extract/url";
    const res = await fetch(endpoint, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    });
    if (!res.ok) {
      let detail = `HTTP ${res.status}`;
      try {
        const j = await res.json();
        if (j.detail) detail = j.detail;
      } catch {}
      throw new Error(detail);
    }
    const data = await res.json();

    // Drop the extracted text into the textarea + reset pending clip
    // state. Shared with the Drive Picker path (see _applyImportedDocument).
    _applyImportedDocument(data);

    hideUrlRow();
    const chars = (data.chars || 0).toLocaleString();
    setStatus(`Loaded ${data.filename} · ${chars} chars · ready to Generate`);
    // v225g5 (#694): same caret + scroll fix as the upload path —
    // phone browsers scroll a long textarea to the caret on focus,
    // and the caret defaults to the end after textEl.value = "…".
    try {
      textEl.scrollTop = 0;
      if (typeof textEl.setSelectionRange === "function") {
        textEl.setSelectionRange(0, 0);
      }
    } catch {}
    const _isPhone = window.matchMedia("(max-width: 767px)").matches;
    if (!_isPhone) textEl.focus();
    try {
      window.scrollTo({ top: 0, behavior: "instant" });
    } catch {
      try { window.scrollTo(0, 0); } catch {}
    }
  } catch (err) {
    setStatus(_withOfflineHint(`Fetch failed: ${err.message}`), true);
  } finally {
    urlInput.disabled = false;
    urlFetchBtn.disabled = false;
    urlFetchBtn.textContent = "Fetch";
  }
}


// v225v4.1 (#812): extracted from the uploadInput change handler so
// drag-and-drop onto the textarea can reuse the same import path. Any
// caller passing a File ends up in the same place: server extract →
// stash detected images/cover → repaint preview → reset clip id →
// optionally auto-route to ebook view. Returns nothing; surfaces all
// errors via setStatus.
async function _runFileImport(file) {
  if (!file) return;

  // Single-document upload path (txt/md/pdf/epub/docx). The accept
  // filter on #upload-input excludes .zip — Scrivener and Obsidian
  // each have their own input behind dedicated Import menu items.
  setStatus(`Reading ${file.name}…`);

  try {
    const formData = new FormData();
    formData.append("file", file);
    const res = await fetch("/api/extract", { method: "POST", body: formData });
    if (!res.ok) {
      let detail = `HTTP ${res.status}`;
      try {
        const j = await res.json();
        if (j.detail) detail = j.detail;
      } catch {}
      throw new Error(detail);
    }
    const data = await res.json();

    // Leave reading view if we were in it — uploading is an edit action.
    exitReadingView();
    textEl.value = data.text || "";
    updateCounts();
    _checkForChapters();

    // v225fz11.cover (#677): if the file's image_detector found a cover,
    // stash it so generate()'s fresh-clip save branch can slot it into
    // clip.cover. We only keep covers with an inline src — skipped
    // entries (oversized) come back as {skipped, size_bytes, ...} with
    // no usable image, so we drop those silently. Detected covers
    // never overwrite an existing clip.cover (re-narrate paths
    // already preserve existing.cover before this even runs).
    if (data.cover && typeof data.cover === "object" && data.cover.src) {
      _pendingDetectedCover = data.cover;
    } else {
      _pendingDetectedCover = null;
    }
    // v225fz12.chapter-images (#678): stash per-chapter leading
    // images. Filtered to entries with a usable src — skipped
    // (oversized) entries come back as {skipped, ...} without one.
    _pendingChapterImages = Array.isArray(data.chapter_images)
      ? data.chapter_images.filter((c) => c && c.src)
      : [];
    // v225fz13 (#687): EPUB uploads now surface inline <img> tags
    // alongside the text (same shape as URL fetch returns:
    // {sentence_index, src, alt}). Stash so generate()'s fresh-clip
    // branch threads them into clip.images and the reading view
    // renders them above the right sentence.
    // v225g6 (#695): ALWAYS overwrite — previously this branch only
    // set _pendingImages when the new import HAD images, so a TXT/MD
    // import after an EPUB would silently inherit the EPUB's image
    // list and surface it in the "Detected in this import" card.
    // User reported uploading a debug log after a Bicycle Ghost
    // EPUB and seeing the ghost's Green-Baize Door + Ex Libris in
    // the new import's preview. Always-assign aligns with how
    // _pendingDetectedCover + _pendingChapterImages already reset.
    _pendingImages = Array.isArray(data.images) ? data.images : [];
    // v225g6 (#695): also release the "current clip is an ebook"
    // gate so the phone Generate bar reappears on the new import.
    // Uploading a new file is implicitly "I'm starting fresh" —
    // the previous ebook clip's kind shouldn't suppress UI for
    // unrelated text. Same call clears document.body.dataset.clipKind
    // so any CSS rules also reset.
    if (typeof _setCurrentClipKind === "function") {
      _setCurrentClipKind(null);
    }
    // Drop the previous clip's id too — the new text isn't bound to
    // it yet, and leaving it set would route a subsequent Generate
    // tap through the regen path (overwriting the old clip with
    // the new text). Mirrors the semantic of Clear → New.
    _currentClipId = null;
    // Nudge the bar's observer in case it was stuck in ebook-hidden.
    if (typeof window._syncPhoneGenerateBar === "function") {
      try { window._syncPhoneGenerateBar(); } catch {}
    }
    // v225fz14 (#688): paint the thumbnail strip so the user sees
    // exactly what art will land on the saved clip before tapping
    // Generate.
    _paintImportPreview();

    const chars = (data.chars || 0).toLocaleString();
    setStatus(`Loaded ${data.filename} · ${chars} chars · ready to Generate`);
    // v225g5 (#694): pin the caret + scroll to position 0 so the user
    // lands at the top of the imported text. Without this, phone
    // browsers focus the textarea with the caret wherever, and the
    // first paint scrolls the textarea to the bottom of a long
    // import (e.g. a 14k-char EPUB chapter) — user reported "after
    // import I'm looking at THE END of the book." Skip .focus() on
    // phone entirely; users typically want to read, not type. On
    // desktop the focus is benign (no scroll-to-caret quirk).
    try {
      textEl.scrollTop = 0;
      if (typeof textEl.setSelectionRange === "function") {
        textEl.setSelectionRange(0, 0);
      }
    } catch {}
    const _isPhone = window.matchMedia("(max-width: 767px)").matches;
    if (!_isPhone) textEl.focus();
    // Also scroll the page itself to the top so the import-preview
    // card + the first few sentences are visible — not the bottom
    // of the textarea + the Generate bar.
    try {
      window.scrollTo({ top: 0, behavior: "instant" });
    } catch {
      try { window.scrollTo(0, 0); } catch {}
    }

    // v225v4.2 (#813): defensive re-pin to override deferred scrolls.
    // User report: desktop ebook import + a few seconds later the
    // text window "jumped up" and header icons became unreachable.
    // Suspect: textEl.focus() above + a deferred layout shift (image
    // decode, chapter banner mount, scroll anchoring) re-scrolls the
    // page down to keep the focused textarea in view. Two extra
    // scrollTo(0,0) calls override that: one after layout settles
    // (double-rAF), one at +200ms for slower decodes/observers.
    // Cheap, idempotent — if the page is already at top this is a
    // no-op. If it later moves on its own (e.g. user scrolled), the
    // probe below will show that in the log.
    try {
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          try { window.scrollTo({ top: 0, behavior: "instant" }); }
          catch { try { window.scrollTo(0, 0); } catch {} }
        });
      });
      setTimeout(() => {
        try { window.scrollTo({ top: 0, behavior: "instant" }); }
        catch { try { window.scrollTo(0, 0); } catch {} }
      }, 200);
    } catch {}

    // v225v4.2 (#813): scroll telemetry. Snapshot scrollY +
    // textarea/preview/banner offsets at intervals to catch what
    // moves the page between t=0 and "a few seconds later." Plus a
    // scroll-event listener that records every scroll change during
    // the 5-second window so a deferred jump leaves a fingerprint.
    try {
      const _t0 = performance.now();
      const _snapshot = (label) => {
        try {
          const trect = textEl.getBoundingClientRect();
          const preview = document.getElementById("import-preview");
          const previewH = preview && !preview.hidden ? preview.offsetHeight : 0;
          const banner = document.getElementById("chapter-banner");
          const bannerH = banner && !banner.hidden ? banner.offsetHeight : 0;
          _dlog("import-scroll", label, {
            elapsedMs: Math.round(performance.now() - _t0),
            scrollY: Math.round(window.scrollY),
            innerH: window.innerHeight,
            textTop: Math.round(trect.top),
            textBottom: Math.round(trect.bottom),
            previewH,
            bannerH,
            activeEl: (document.activeElement && document.activeElement.tagName) || null,
            activeId: (document.activeElement && document.activeElement.id) || null,
          });
        } catch {}
      };
      const _onScroll = () => _snapshot("scroll-event");
      window.addEventListener("scroll", _onScroll, { passive: true });
      _snapshot("t+0");
      setTimeout(() => _snapshot("t+50"), 50);
      setTimeout(() => _snapshot("t+250"), 250);
      setTimeout(() => _snapshot("t+800"), 800);
      setTimeout(() => _snapshot("t+2000"), 2000);
      setTimeout(() => {
        _snapshot("t+5000");
        window.removeEventListener("scroll", _onScroll);
      }, 5000);
    } catch {}

    // v225g1 (#690): if the upload was triggered by the "📖 Read as
    // ebook" empty-state tile (or any other caller that set the flag),
    // skip the "wait for Generate" step and route straight into the
    // ebook save + book-view path. Flag is one-shot — cleared on first
    // use so a subsequent generate-tap on the same text still synths.
    if (_pendingEbookMode) {
      _pendingEbookMode = false;
      try {
        await _openAsEbook();
      } catch (e) {
        console.error("[ebook] auto-route after upload failed:", e);
      }
    }
  } catch (err) {
    setStatus(`Upload failed: ${err.message}`, true);
    _pendingEbookMode = false; // clear so the flag doesn't stick into a later import
  } finally {
    // Reset so picking the same file again still fires "change".
    uploadInput.value = "";
  }
}

uploadInput.addEventListener("change", (e) => {
  const file = e.target.files?.[0];
  _runFileImport(file);
});

// v225v4.1 (#812): drag-and-drop file import on the textarea. Drop a
// .epub / .pdf / .docx / .txt / .md from Finder/Explorer onto the
// text area and it routes through the same path the Import dropdown
// uses. Whole-document import gesture, same shape as paste.
//
// We also catch dragover on the document itself with preventDefault so
// a misaimed drop outside the textarea doesn't make the browser
// navigate to the file's contents (default behavior would swap out the
// whole app). Drop ONLY on the textarea actually imports.
(function _initFileDropTarget() {
  if (!textEl) return;

  // The set of extensions we'll accept by drop. Matches
  // #upload-input's accept attribute. Lowercased; checked after
  // splitting on the last "." so "Chapter.One.epub" still parses.
  const DROP_ACCEPT = new Set([
    "txt", "md", "markdown", "pdf", "epub", "docx",
  ]);

  function _isAcceptedFile(file) {
    if (!file || !file.name) return false;
    const i = file.name.lastIndexOf(".");
    if (i < 0) return false;
    return DROP_ACCEPT.has(file.name.slice(i + 1).toLowerCase());
  }

  // Document-level: stop the browser from opening the dropped file
  // when the user misses the textarea. Important — without this, a
  // missed drop loses ALL their app state because the browser
  // navigates to the file.
  document.addEventListener("dragover", (e) => {
    // Only intercept when the drag includes files; ignore in-page
    // drags (drag-handle reordering, etc.) so we don't disturb them.
    if (e.dataTransfer && Array.from(e.dataTransfer.types || []).includes("Files")) {
      e.preventDefault();
    }
  });
  document.addEventListener("drop", (e) => {
    if (e.dataTransfer && Array.from(e.dataTransfer.types || []).includes("Files")) {
      // If the actual drop target isn't the textarea, swallow it so
      // the browser doesn't load the file.
      if (e.target !== textEl && !textEl.contains(e.target)) {
        e.preventDefault();
      }
    }
  });

  // textarea-level: highlight on dragenter, clear on dragleave/drop,
  // route the file on drop.
  let _dragDepth = 0;
  textEl.addEventListener("dragenter", (e) => {
    if (!e.dataTransfer || !Array.from(e.dataTransfer.types || []).includes("Files")) return;
    e.preventDefault();
    _dragDepth++;
    textEl.classList.add("file-drop-active");
  });
  textEl.addEventListener("dragover", (e) => {
    if (!e.dataTransfer || !Array.from(e.dataTransfer.types || []).includes("Files")) return;
    e.preventDefault();
    e.dataTransfer.dropEffect = "copy";
  });
  textEl.addEventListener("dragleave", (e) => {
    if (!e.dataTransfer || !Array.from(e.dataTransfer.types || []).includes("Files")) return;
    _dragDepth = Math.max(0, _dragDepth - 1);
    if (_dragDepth === 0) textEl.classList.remove("file-drop-active");
  });
  textEl.addEventListener("drop", (e) => {
    if (!e.dataTransfer || !Array.from(e.dataTransfer.types || []).includes("Files")) return;
    e.preventDefault();
    _dragDepth = 0;
    textEl.classList.remove("file-drop-active");
    const file = e.dataTransfer.files && e.dataTransfer.files[0];
    if (!file) return;
    if (!_isAcceptedFile(file)) {
      setStatus(
        `Can't import ${file.name} — try .epub, .pdf, .docx, .txt, or .md.`,
        true,
      );
      return;
    }
    if (e.dataTransfer.files.length > 1) {
      setStatus(
        `Dropped ${e.dataTransfer.files.length} files — importing only the first (${file.name}).`,
      );
    }
    _runFileImport(file);
  });
})();

renderLibrary();

function currentSentenceIndex(time) {
  // Binary search for largest index i with sentenceOffsetsSec[i] <= time.
  if (!sentenceOffsetsSec.length) return -1;
  let lo = 0;
  let hi = sentenceOffsetsSec.length - 1;
  let result = 0;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (sentenceOffsetsSec[mid] <= time + 1e-3) {
      result = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return result;
}

function seekToSentence(i) {
  // Streaming mode: jump to a sentence inside the per-sentence queue. Each
  // sentence is its own audio source, so we have to re-point player.src and
  // rebuild _streamElapsed (the cumulative duration of all earlier sentences)
  // so virtualTime() stays consistent.
  if (
    _streamPlayhead >= 0 &&
    i >= 0 &&
    i < _streamQueue.length &&
    _streamQueue[i].url
  ) {
    let elapsed = 0;
    for (let k = 0; k < i; k++) elapsed += _streamQueue[k].durationSec || 0;
    _streamElapsed = elapsed;
    _streamPlayhead = i - 1; // startNextStreamSentence pre-increments
    startNextStreamSentence();
    return;
  }

  // Post-swap (combined WAV) mode: just move currentTime.
  if (i < 0) {
    playerEl.currentTime = 0;
    return;
  }
  if (i >= sentenceOffsetsSec.length) {
    if (isFinite(playerEl.duration)) playerEl.currentTime = playerEl.duration;
    return;
  }
  playerEl.currentTime = sentenceOffsetsSec[i];
}

function setMediaMetadata(text) {
  if (!("mediaSession" in navigator) || typeof MediaMetadata === "undefined") return;
  navigator.mediaSession.metadata = new MediaMetadata({
    title: makeTitle(text),
    artist: "Narrative",
    album: "Local TTS",
    artwork: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png" },
    ],
  });
}

function setupMediaSession() {
  if (!("mediaSession" in navigator)) return;

  const safeSet = (action, handler) => {
    try {
      navigator.mediaSession.setActionHandler(action, handler);
    } catch {
      // Browser doesn't support this action — ignore.
    }
  };

  safeSet("play", () => playerEl.play());
  // Lock-screen / Bluetooth pause is a user action — flag it so the
  // pause handler doesn't mistake it for an OS interrupt just because
  // the tab is in the background.
  safeSet("pause", () => _pauseAsUser());
  safeSet("stop", () => {
    _pauseAsUser();
    playerEl.currentTime = 0;
  });

  // Sentence-skip handlers shared between prev/next track and seek buttons.
  // iOS displays prev/next track buttons on the lock screen / Control Center
  // by default; Android may show either set; desktop media keys typically
  // map to prev/next. Registering both ensures the buttons appear regardless
  // of platform choice, and they all run the same sentence-jump logic.
  const backHandler = (details = {}) => {
    if (sentenceOffsetsSec.length) {
      const vt = virtualTime();
      const idx = currentSentenceIndex(vt);
      const sentenceStart = sentenceOffsetsSec[idx] ?? 0;
      // Podcast-app behavior: if you're past the first second of a sentence,
      // restart it; otherwise jump to the previous sentence.
      if (vt - sentenceStart > 1.0) {
        seekToSentence(idx);
      } else {
        seekToSentence(idx - 1);
      }
      return;
    }
    const skip = details.seekOffset || 10;
    playerEl.currentTime = Math.max(0, playerEl.currentTime - skip);
  };
  const forwardHandler = (details = {}) => {
    if (sentenceOffsetsSec.length) {
      const idx = currentSentenceIndex(virtualTime());
      seekToSentence(idx + 1);
      return;
    }
    const skip = details.seekOffset || 10;
    const dur = isFinite(playerEl.duration) ? playerEl.duration : Infinity;
    playerEl.currentTime = Math.min(dur, playerEl.currentTime + skip);
  };
  safeSet("previoustrack", backHandler);
  safeSet("nexttrack", forwardHandler);
  safeSet("seekbackward", backHandler);
  safeSet("seekforward", forwardHandler);
  safeSet("seekto", (details) => {
    if (details.fastSeek && "fastSeek" in playerEl) {
      playerEl.fastSeek(details.seekTime);
      return;
    }
    playerEl.currentTime = details.seekTime;
  });

  playerEl.addEventListener("play", () => {
    navigator.mediaSession.playbackState = "playing";
  });
  playerEl.addEventListener("pause", () => {
    navigator.mediaSession.playbackState = "paused";
    // Pause is the most important resume checkpoint — save immediately so
    // closing the tab right after pausing still leaves a usable bookmark.
    maybeSaveProgress(true);
  });
  playerEl.addEventListener("ended", async () => {
    // While streaming, "ended" just means the current sentence's blob
    // finished — chain to the next queued sentence instead of stopping.
    if (_streamPlayhead >= 0) {
      const cur = _streamQueue[_streamPlayhead];
      _streamElapsed += (cur && cur.durationSec) || playerEl.duration || 0;
      if (_streamPlayhead + 1 < _streamQueue.length) {
        startNextStreamSentence();
        return;
      }
      // Streaming queue exhausted — user has heard every per-sentence
      // WAV. Mark "audio side" complete. If save already landed,
      // _tryAdvanceQueue fires the 4-second breath; if save lands
      // later, IT will fire the breath. Either ordering works.
      // v165: also skip when a background queue is running — the
      // background pipeline doesn't play anything, so any "audio
      // ended" signal here belongs to a foreground clip the user
      // started manually and must not poke the chapter queue.
      if (_chapterTotalCount > 0 && !_silentChapterQueue) {
        _queueAudioComplete = true;
        _tryAdvanceQueue();
      }
      // Queue exhausted; the next sentence event (or the final swap to the
      // combined WAV) will resume playback.
      return;
    }
    navigator.mediaSession.playbackState = "none";
    // Clip is done — clear its resume position so the next play starts
    // from the beginning (and the card stops showing "1:23 / 5:00").
    const justEndedId = _currentClipId;
    await markCurrentClipPlayed();

    // Chapter queue: combined MP3 just finished playing. Mark the
    // audio side complete and try to advance. If save .then() already
    // fired (the common case for long chapters that finished synth
    // well before playback), _tryAdvanceQueue schedules the breath
    // and we return so library auto-advance doesn't compete. If save
    // hasn't fired yet, the audio flag waits; when save eventually
    // sets _queueSaveComplete, the advance fires from there.
    // v165: only fire when a FOREGROUND queue is active. A
    // background queue (_silentChapterQueue) doesn't play anything
    // through this audio element — if we hit this branch with the
    // background flag set, the user just played a saved clip from
    // the library and we must leave the background queue alone.
    if (_chapterTotalCount > 0 && !_silentChapterQueue) {
      _queueAudioComplete = true;
      _tryAdvanceQueue();
      // Suppress library auto-advance while a chapter queue is active
      // regardless of whether _tryAdvanceQueue actually scheduled the
      // advance this tick (save might still be pending).
      return;
    }

    // End-of-clip sleep mode (the no-queue equivalent of end-of-chapter):
    // the clip just finished, and we were asked to stop at the next
    // boundary. Don't queue up an auto-advance — _onSleepBoundaryReached
    // resets the sleep state and tells the listener.
    if (_sleepEndOfChapter && _chapterTotalCount <= 0) {
      _onSleepBoundaryReached("clip");
      return;
    }

    // v225eu: repeat-mode intercept. Loop-this restarts the same clip
    // and returns true; repeat-all + end-of-queue schedules a wrap to
    // the first clip and returns true. Off / repeat-all + not-last
    // returns false and falls through to default advance.
    if (justEndedId && _chapterTotalCount <= 0) {
      const handled = await _repeatHandleEnded(justEndedId);
      if (handled) return;
    }

    // Auto-advance to the next clip in the library according to _playMode.
    // Give the listener a 3-second breath between chapters so transitions
    // don't slam together — your ear needs a beat to register a chapter
    // change. Cancellable: if the user starts a different clip or hits
    // any control during the gap, _autoAdvanceTimer gets cleared by
    // whatever takes over.
    // Suppressed while a chapter queue is active — the queue's own
    // advance logic owns transitions between its chapters.
    if (justEndedId && _chapterTotalCount <= 0) {
      const nextId = await nextClipId(justEndedId);
      if (nextId) {
        setStatus("Up next in 3s…");
        _cancelAutoAdvance();
        _autoAdvanceTimer = setTimeout(() => {
          _autoAdvanceTimer = null;
          loadClip(nextId);
        }, 3000);
      }
    }
  });

  // Capture each per-sentence WAV's true duration so virtualTime() and the
  // queue-jump math have accurate offsets across sentences.
  playerEl.addEventListener("loadedmetadata", () => {
    if (
      _streamPlayhead >= 0 &&
      _streamPlayhead < _streamQueue.length &&
      isFinite(playerEl.duration)
    ) {
      _streamQueue[_streamPlayhead].durationSec = playerEl.duration;
    }
  });

  const updatePosition = () => {
    // During streaming we don't know the total duration yet — skip so we
    // don't feed the OS misleading values for the lock-screen scrubber.
    if (_streamPlayhead >= 0) return;
    const dur = playerEl.duration;
    if (!isFinite(dur) || dur <= 0) return;
    try {
      navigator.mediaSession.setPositionState({
        duration: dur,
        position: Math.min(playerEl.currentTime, dur),
        playbackRate: playerEl.playbackRate || 1,
      });
    } catch {
      // Some browsers throw if values are stale — safe to ignore.
    }
  };
  playerEl.addEventListener("loadedmetadata", updatePosition);
  playerEl.addEventListener("timeupdate", updatePosition);
  playerEl.addEventListener("ratechange", updatePosition);

  // Karaoke-style highlight in the reading view, driven by the same
  // timeupdate signal so it stays in sync with playback.
  playerEl.addEventListener("timeupdate", highlightCurrentSentence);
  playerEl.addEventListener("seeked", highlightCurrentSentence);

  // Throttled resume-position checkpoint. Plus an immediate save when the
  // tab closes so we don't lose the last few seconds.
  playerEl.addEventListener("timeupdate", () => maybeSaveProgress(false));
  window.addEventListener("pagehide", () => maybeSaveProgress(true));
}

// ---- Voice browser -------------------------------------------------------
// Fetches the full Piper voice catalog from /api/voices/catalog and lets the
// user install a new voice without touching the CLI. Groups by language, has
// a live search input, and pings /api/voices afterwards so the just-installed
// voice shows up in the main dropdown immediately.

let _voiceCatalog = null; // cached per page load

// v219: look up provenance fields (license + attribution) for a voice id.
// Used by generate() to snapshot the license that applies to a clip's
// audio at generation time — important because Narrative's license
// audit may revise commercial-status later, and the clip's recorded
// attribution should reflect what was true when it was made.
//
// voice ids on clips carry the "piper:" prefix (engine route); the
// catalog stores bare ids. Strip the prefix before lookup.
function _voiceProvenance(voiceIdWithPrefix) {
  if (!voiceIdWithPrefix || !_voiceCatalog) return null;
  const bare = String(voiceIdWithPrefix).replace(/^piper:/, "");
  const entry = _voiceCatalog.find((v) => v.id === bare);
  if (!entry) return null;
  return {
    license: entry.license || "",
    licenseDataset: entry.license_dataset || "",
    licenseCommercial: !!entry.license_commercial,
    attribution: entry.license_attribution || "",
  };
}

// "Show installed only" chip state. Reset each time the dialog opens so
// the default browsing experience always shows the full catalog.
let _installedOnly = false;

function updateInstalledToggle() {
  // Show the installed count when the filter is off (helpful at a glance);
  // flip to "All voices" when it's on so the toggle action is obvious.
  const installedCount = _voiceCatalog
    ? _voiceCatalog.filter((v) => v.installed).length
    : 0;
  voiceInstalledToggle.classList.toggle("active", _installedOnly);
  voiceInstalledToggle.setAttribute("aria-pressed", String(_installedOnly));
  voiceInstalledToggle.textContent = _installedOnly
    ? "All voices"
    : `Installed only (${installedCount})`;
}

let _favoritesOnly = false;
// v218: "Commercial only" filter state. Reset on every dialog open like
// the others so first-time discovery sees the whole catalog.
let _commercialOnly = false;
// Language-code filter. Empty string = "all languages." Set by the
// <select> below the filter chips; survives across browser opens.
let _languageFilter = "";

function updateCommercialToggle() {
  // Same count idiom as the other chips: show "(N)" of matching voices
  // when off so the user knows how much narrows in; flip to "All voices"
  // when on. Counts every voice with license_commercial === true, which
  // includes the small audited green set today and grows as we audit more.
  const commercialCount = _voiceCatalog
    ? _voiceCatalog.filter((v) => v.license_commercial).length
    : 0;
  voiceCommercialToggle.classList.toggle("active", _commercialOnly);
  voiceCommercialToggle.setAttribute("aria-pressed", String(_commercialOnly));
  voiceCommercialToggle.textContent = _commercialOnly
    ? "All voices"
    : `Commercial only (${commercialCount})`;
}

// Build the language picker options from the catalog. Each option is
// "Language name (N)" where N is the count of voices in that language.
// Sorted alphabetically; "All languages (total)" stays pinned at the top.
function _populateLanguageFilter() {
  if (!_voiceCatalog) return;
  // Stash the current selection so a re-populate (e.g. after install /
  // remove changes counts) doesn't reset the user's choice.
  const current = voiceLanguageFilter.value;

  // v154: bucket by ISO 639-1 prefix (the part before "_") so all
  // en_* voices group under a single "English" entry. Previously
  // the dropdown had separate buckets for en_US and en_GB that
  // both displayed as "English (N)" — picking the en_GB bucket
  // hid LibriTTS (en_US, 904 speakers) and a tester reported
  // "LibriTTS doesn't show up under English." The list itself
  // still sub-headers by country, so consolidating the dropdown
  // doesn't lose any locale information.
  const byLang = new Map();
  for (const v of _voiceCatalog) {
    const code = v.language_code || "";
    if (!code) continue;
    const baseLang = code.split("_")[0] || code;
    if (!byLang.has(baseLang)) {
      byLang.set(baseLang, {
        name: v.language_name || baseLang,
        count: 0,
      });
    }
    byLang.get(baseLang).count += 1;
  }

  // Preserve "All languages" header; rebuild the rest.
  voiceLanguageFilter.innerHTML = "";
  const allOpt = document.createElement("option");
  allOpt.value = "";
  allOpt.textContent = `All languages (${_voiceCatalog.length})`;
  voiceLanguageFilter.appendChild(allOpt);

  const sorted = [...byLang.entries()].sort((a, b) =>
    a[1].name.localeCompare(b[1].name)
  );
  for (const [code, info] of sorted) {
    const opt = document.createElement("option");
    opt.value = code;
    opt.textContent = `${info.name} (${info.count})`;
    voiceLanguageFilter.appendChild(opt);
  }

  // Restore the selection if still valid; otherwise fall back to "all."
  if (current && byLang.has(current)) {
    voiceLanguageFilter.value = current;
  } else {
    voiceLanguageFilter.value = _languageFilter || "";
  }
}

function updateFavoritesToggle() {
  const favCount = getFavoriteVoices().length;
  voiceFavoritesToggle.classList.toggle("active", _favoritesOnly);
  voiceFavoritesToggle.setAttribute("aria-pressed", String(_favoritesOnly));
  voiceFavoritesToggle.textContent = _favoritesOnly
    ? "All voices"
    : `★ Favorites (${favCount})`;
}

async function loadVoiceCatalog(force = false) {
  if (_voiceCatalog && !force) return _voiceCatalog;
  voiceBrowserList.innerHTML =
    '<div class="voice-browser-loading">Loading catalog…</div>';
  try {
    const res = await fetch("/api/voices/catalog");
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const data = await res.json();
    _voiceCatalog = data.voices || [];
    // Rebuild the language dropdown so its options reflect the fresh
    // catalog (count per language can shift after an install / remove).
    _populateLanguageFilter();
  } catch (e) {
    voiceBrowserList.innerHTML =
      `<div class="voice-browser-loading">Failed to load catalog: ${e.message}</div>`;
    _voiceCatalog = null;
  }
  return _voiceCatalog;
}

// v167: inline favorites tip — shown in the voice browser when no
// voice has been starred yet AND the user hasn't dismissed it.
// Dismiss flag persists in localStorage so a returning user who
// dismissed it doesn't see it again.
const VOICE_FAV_TIP_KEY = "narrative.voiceFavTipDismissed";
function _updateVoiceFavoritesTip() {
  const tip = document.getElementById("voice-favorites-tip");
  if (!tip) return;
  let dismissed = false;
  try { dismissed = localStorage.getItem(VOICE_FAV_TIP_KEY) === "1"; } catch {}
  const favCount = getFavoriteVoices().length;
  tip.hidden = dismissed || favCount > 0;
}
const _voiceFavTipDismissBtn = document.getElementById("voice-favorites-tip-dismiss");
if (_voiceFavTipDismissBtn) {
  _voiceFavTipDismissBtn.addEventListener("click", () => {
    try { localStorage.setItem(VOICE_FAV_TIP_KEY, "1"); } catch {}
    _updateVoiceFavoritesTip();
  });
}

// v219: parallel "Commercial only" first-tap hint. Same dismiss
// pattern as the favorites tip, and self-dismisses the first time
// the user actually toggles the Commercial chip — proving they know
// it's there. Persisted in localStorage so a returning user who
// already used the chip doesn't see the banner again.
const VOICE_COMM_TIP_KEY = "narrative.voiceCommercialTipDismissed";
function _updateVoiceCommercialTip() {
  const tip = document.getElementById("voice-commercial-tip");
  if (!tip) return;
  let dismissed = false;
  try { dismissed = localStorage.getItem(VOICE_COMM_TIP_KEY) === "1"; } catch {}
  tip.hidden = dismissed;
}
const _voiceCommTipDismissBtn = document.getElementById("voice-commercial-tip-dismiss");
if (_voiceCommTipDismissBtn) {
  _voiceCommTipDismissBtn.addEventListener("click", () => {
    try { localStorage.setItem(VOICE_COMM_TIP_KEY, "1"); } catch {}
    _updateVoiceCommercialTip();
  });
}

function renderVoiceCatalog() {
  if (!_voiceCatalog) return;
  updateInstalledToggle();
  updateCommercialToggle();
  // v167: keep the tip in sync with the current favorites state on
  // every render — covers "user opens browser fresh" and "user just
  // un-starred their last favorite" without extra calls elsewhere.
  _updateVoiceFavoritesTip();
  // v219: same pattern for the Commercial-only tip.
  _updateVoiceCommercialTip();
  updateFavoritesToggle();
  const favSet = new Set(getFavoriteVoices());
  const q = voiceBrowserSearch.value.trim().toLowerCase();
  const matches = _voiceCatalog.filter((v) => {
    if (_installedOnly && !v.installed) return false;
    if (_favoritesOnly && !favSet.has(v.id)) return false;
    // v218: commercial-use filter. Voices fall into license_commercial=true
    // only when explicitly audited in tts/voice_licenses.py.
    if (_commercialOnly && !v.license_commercial) return false;
    // v154: match on the ISO 639-1 prefix so the consolidated
    // "English" filter (which now stores "en" as its value) matches
    // both en_US (LibriTTS et al) and en_GB voices. Fall back to
    // exact match for any catalog entries where the code already
    // lacks an underscore.
    if (_languageFilter) {
      const code = v.language_code || "";
      const base = code.split("_")[0] || code;
      if (base !== _languageFilter) return false;
    }
    if (!q) return true;
    return (
      v.name.toLowerCase().includes(q) ||
      v.language_name.toLowerCase().includes(q) ||
      v.language_native.toLowerCase().includes(q) ||
      v.language_code.toLowerCase().includes(q) ||
      v.country.toLowerCase().includes(q) ||
      v.id.toLowerCase().includes(q)
    );
  });

  // Group by "Language (Country)" so the user can scan by region.
  const byGroup = new Map();
  for (const v of matches) {
    const country = v.country ? ` (${v.country})` : "";
    const label = `${v.language_name || v.language_code}${country}`;
    if (!byGroup.has(label)) byGroup.set(label, []);
    byGroup.get(label).push(v);
  }

  // Within a group, installed first, then alphabetical by name.
  for (const arr of byGroup.values()) {
    arr.sort(
      (a, b) =>
        Number(b.installed) - Number(a.installed) ||
        a.name.localeCompare(b.name) ||
        a.quality.localeCompare(b.quality)
    );
  }

  voiceBrowserList.innerHTML = "";
  if (byGroup.size === 0) {
    // Give context-aware empty copy so the user understands WHY the list
    // is empty — "no installed voices yet" vs. "your filter excluded all."
    const empty = document.createElement("div");
    empty.className = "voice-browser-loading";
    if (_favoritesOnly && getFavoriteVoices().length === 0) {
      empty.textContent =
        "No favorites yet. Tap a ☆ on any voice to star it.";
    } else if (_installedOnly && !_voiceCatalog.some((v) => v.installed)) {
      empty.textContent =
        "No voices installed yet. Turn off the filter to browse the catalog.";
    } else if (_languageFilter) {
      const langOpt = voiceLanguageFilter.querySelector(
        `option[value="${CSS.escape(_languageFilter)}"]`
      );
      const langName = langOpt ? langOpt.textContent : _languageFilter;
      empty.textContent = `No voices match these filters in ${langName}.`;
    } else {
      empty.textContent = "No voices match.";
    }
    voiceBrowserList.appendChild(empty);
    return;
  }

  // Sort groups alphabetically (looks nicer than catalog-insertion order).
  const sortedGroups = [...byGroup.entries()].sort((a, b) =>
    a[0].localeCompare(b[0])
  );

  for (const [label, voices] of sortedGroups) {
    const head = document.createElement("div");
    head.className = "catalog-group";
    head.textContent = label;
    voiceBrowserList.appendChild(head);

    for (const v of voices) {
      voiceBrowserList.appendChild(makeCatalogRow(v));
    }
  }
}

function makeCatalogRow(v) {
  const row = document.createElement("div");
  row.className = "catalog-voice";

  // ★ Favorite toggle. Star is leftmost so the user's eye lands on it
  // first when scanning a long catalog.
  const favBtn = document.createElement("button");
  favBtn.type = "button";
  const isFav = isFavoriteVoice(v.id);
  favBtn.className = "catalog-voice-fav" + (isFav ? " starred" : "");
  favBtn.textContent = isFav ? "★" : "☆";
  favBtn.title = isFav ? "Remove from favorites" : "Add to favorites";
  favBtn.setAttribute(
    "aria-label",
    isFav ? `Unfavorite ${v.name}` : `Favorite ${v.name}`
  );
  favBtn.setAttribute("aria-pressed", String(isFav));
  favBtn.addEventListener("click", async (e) => {
    e.stopPropagation();
    toggleFavoriteVoice(v.id);
    // Re-render the catalog so the row repositions if Favorites-only is
    // active, and refresh the main picker's "★ Favorites" optgroup.
    renderVoiceCatalog();
    _refreshFavoritesInMainPicker();
    // v167: re-evaluate the favorites tip banner — it hides once any
    // favorite exists. The v166 setStatus hint fired but the voice
    // browser modal occluded the status bar, so the user never saw
    // it AND the localStorage seen-flag got locked. We're now using
    // an inline banner instead (see _updateVoiceFavoritesTip).
    _updateVoiceFavoritesTip();
  });
  row.appendChild(favBtn);

  const info = document.createElement("div");
  info.className = "catalog-voice-info";

  const nameEl = document.createElement("div");
  nameEl.className = "catalog-voice-name";
  nameEl.textContent = `${cap(v.name)} · ${v.quality}`;

  // v217: license badge. Green "Commercial ✓" if the voice is cleared
  // for distributing generated audio; amber "Non-commercial" otherwise.
  // Tooltip carries the dataset, license, and required attribution.
  if (typeof v.license_commercial === "boolean") {
    const badge = document.createElement("span");
    badge.className = v.license_commercial
      ? "catalog-voice-license commercial"
      : "catalog-voice-license noncommercial";
    badge.textContent = v.license_commercial ? "Commercial ✓" : "Non-commercial";
    const tipBits = [];
    if (v.license) tipBits.push(`License: ${v.license}`);
    if (v.license_dataset) tipBits.push(`Dataset: ${v.license_dataset}`);
    if (v.license_attribution)
      tipBits.push(`Credit: ${v.license_attribution}`);
    if (v.license_notes) tipBits.push(v.license_notes);
    badge.title = tipBits.join("\n");
    nameEl.appendChild(document.createTextNode(" "));
    nameEl.appendChild(badge);
  }

  const metaParts = [];
  if (v.size_mb) metaParts.push(`${v.size_mb} MB`);
  if (v.num_speakers > 1) metaParts.push(`${v.num_speakers} speakers`);
  metaParts.push(v.id);
  const metaEl = document.createElement("div");
  metaEl.className = "catalog-voice-meta";
  metaEl.textContent = metaParts.join(" · ");

  info.append(nameEl, metaEl);

  // Preview button — plays the pre-recorded HuggingFace sample so users can
  // hear a voice before committing to a ~60MB download.
  const preview = document.createElement("button");
  preview.type = "button";
  preview.className = "catalog-voice-preview";
  preview.textContent = "▶";
  preview.setAttribute("aria-label", `Preview ${v.name}`);
  // Title doubles as a row-level hint. With custom text set, the ▶ on
  // uninstalled rows runs an install + auto-preview; without it, it
  // plays the standard sample. Either way, one click ends in audio.
  preview.title = v.installed
    ? "Preview voice"
    : "Preview standard sample (install first to hear your text)";
  preview.addEventListener("click", () => togglePreview(v, preview));

  const action = document.createElement("button");
  action.type = "button";
  action.className = v.installed
    ? "catalog-voice-action installed"
    : "catalog-voice-action";
  action.textContent = v.installed ? "Installed" : "Install";
  action.disabled = v.installed;
  if (!v.installed) {
    action.addEventListener("click", () => installCatalogVoice(v, action));
  }

  row.append(info, preview, action);

  // Installed voices get a small × button for uninstall. We keep the
  // "Installed" pill so the row's state still reads at a glance.
  if (v.installed) {
    const removeBtn = document.createElement("button");
    removeBtn.type = "button";
    removeBtn.className = "catalog-voice-remove";
    removeBtn.textContent = "×";
    removeBtn.title = "Remove this voice from disk";
    removeBtn.setAttribute("aria-label", `Remove ${v.name}`);
    removeBtn.addEventListener("click", () => removeCatalogVoice(v, removeBtn));
    row.appendChild(removeBtn);
  }

  return row;
}

async function removeCatalogVoice(voice, btn) {
  // Soft confirm — a 130 MB LibriTTS install isn't fun to redo by accident,
  // but it's also one click away if they change their mind.
  const ok = confirm(
    `Remove "${cap(voice.name)} (${voice.quality})"? ` +
    `(${voice.size_mb} MB will be freed; you can re-install anytime.)`
  );
  if (!ok) return;

  btn.disabled = true;
  // Stop any preview that's playing the file we're about to delete.
  stopPreview();
  try {
    const res = await fetch(`/api/voices/${encodeURIComponent(voice.id)}`, {
      method: "DELETE",
    });
    if (!res.ok) {
      let detail = `HTTP ${res.status}`;
      try {
        const j = await res.json();
        if (j.detail) detail = j.detail;
      } catch {}
      throw new Error(detail);
    }
    // Update local catalog state and re-render so the row flips back
    // from "Installed (×)" to "Install".
    voice.installed = false;
    renderVoiceCatalog();
    // Refresh the main voice dropdown so the removed voice disappears
    // from there too. If it was the current selection, the dropdown
    // will fall back to its first option (and the speaker row will
    // hide via onVoiceChange).
    await loadVoices();
  } catch (e) {
    console.warn("voice remove failed:", e);
    btn.disabled = false;
    setStatus(`Remove failed: ${e.message}`, true);
  }
}

// ---- Voice preview ------------------------------------------------------
// One shared Audio element so clicking a new preview cleanly stops the old
// one. Buttons that 404 (voice has no published sample) get permanently
// disabled with a tooltip so the user doesn't keep retrying.
let _previewAudio = null;
let _previewBtn = null; // the catalog row button currently showing "■"

function _ensurePreviewAudio() {
  if (_previewAudio) return _previewAudio;
  _previewAudio = new Audio();
  _previewAudio.addEventListener("ended", _resetPreviewBtn);
  return _previewAudio;
}

function _resetPreviewBtn() {
  if (!_previewBtn) return;
  _previewBtn.classList.remove("playing", "loading");
  _previewBtn.textContent = "▶";
  _previewBtn = null;
}

// Holds a blob URL from a custom-text synth so we can revoke it on stop
// instead of leaking the object URL across previews.
let _previewBlobUrl = null;

function stopPreview() {
  if (_previewAudio) {
    _previewAudio.pause();
    _previewAudio.removeAttribute("src");
    _previewAudio.load(); // forces the browser to release the request
  }
  if (_previewBlobUrl) {
    URL.revokeObjectURL(_previewBlobUrl);
    _previewBlobUrl = null;
  }
  _resetPreviewBtn();
}

// ---- Audition lifecycle ------------------------------------------------
// When the user clicks ▶ on an uninstalled voice (with custom text set),
// we install it on disk so synthesis can run. But the user hasn't
// committed to keeping it — they're just auditioning. Track which
// installs were triggered by an audition and roll them back when the
// browser dialog closes, unless the user explicitly hit "Keep."
const _auditionedVoiceIds = new Set();
// voice.id -> the row's action button element. Lets _commitAudition
// flip the pill from "Keep" back to "Installed" in place.
const _auditionActionBtns = new Map();

function _markAuditioned(voice, actionBtn) {
  _auditionedVoiceIds.add(voice.id);
  // installCatalogVoice() already mutated the pill to "Installed"
  // (disabled). We need a fresh node so the original click listener
  // doesn't fire alongside the new "Keep" one. cloneNode + replaceWith
  // is the simplest way to drop addEventListener handlers.
  const fresh = actionBtn.cloneNode(false);
  fresh.classList.remove("installed");
  fresh.classList.add("keep");
  fresh.textContent = "Keep";
  fresh.disabled = false;
  fresh.title =
    "Keep this voice. Without Keep, it auto-removes when you close this dialog.";
  fresh.addEventListener("click", () => _commitAudition(voice));
  actionBtn.replaceWith(fresh);
  _auditionActionBtns.set(voice.id, fresh);
}

function _commitAudition(voice) {
  const btn = _auditionActionBtns.get(voice.id);
  if (!btn) return;
  _auditionedVoiceIds.delete(voice.id);
  _auditionActionBtns.delete(voice.id);
  btn.classList.remove("keep");
  btn.classList.add("installed");
  btn.textContent = "Installed";
  btn.disabled = true;
  btn.title = "";
}

// Iterate the audition set, DELETE each voice via /api/voices/{id}, and
// clear the state. Called on dialog close + best-effort on tab close.
// No confirm dialog — these were never permanent commits.
async function _revertAuditions() {
  if (_auditionedVoiceIds.size === 0) return;
  const ids = [..._auditionedVoiceIds];
  _auditionedVoiceIds.clear();
  _auditionActionBtns.clear();
  // Stop any in-flight preview using a soon-to-be-deleted file.
  stopPreview();
  await Promise.all(
    ids.map((id) =>
      fetch(`/api/voices/${encodeURIComponent(id)}`, { method: "DELETE" })
        .catch((e) => console.warn("audition revert failed:", id, e))
    )
  );
  // Mutate the local catalog state so subsequent renders show the right
  // pill (Install instead of Installed) without a server round trip.
  if (_voiceCatalog) {
    for (const v of _voiceCatalog) {
      if (ids.includes(v.id)) v.installed = false;
    }
  }
  // Main voice picker reflects only installed voices; refresh it so the
  // reverted ones disappear.
  await loadVoices();
}

// Triggered when the user clicks ▶ with custom text set on an
// uninstalled row. Finds the row's Install pill, calls the standard
// install flow (live percentage shown on the pill), then on success
// re-invokes togglePreview to actually play the custom text. The
// install is recorded as an audition so it gets rolled back unless
// the user hits "Keep" before closing the dialog.
async function _installThenPreview(voice, btn) {
  const row = btn.closest(".catalog-voice");
  if (!row) return;
  const installBtn = row.querySelector(".catalog-voice-action");
  if (!installBtn || installBtn.disabled) {
    // No install affordance to hijack — bail without surprise. (Could
    // happen if the catalog markup changes and the row no longer has a
    // standard install button.)
    return;
  }
  // Mark the row's ▶ as "queued for play after install" so the user
  // gets visual feedback that something's happening; the install pill
  // already shows the live percentage.
  btn.classList.add("queued");
  btn.textContent = "…";
  try {
    await installCatalogVoice(voice, installBtn);
  } finally {
    btn.classList.remove("queued");
    btn.textContent = "▶";
  }
  // installCatalogVoice mutates voice.installed = true on success.
  // Mark the install as an audition so closing the dialog without
  // committing reverts it. Then fire the preview the user asked for.
  if (voice.installed) {
    _markAuditioned(voice, installBtn);
    if (!_previewBtn) {
      togglePreview(voice, btn);
    }
  }
}

async function togglePreview(voice, btn) {
  // Same button → toggle off.
  if (_previewBtn === btn) {
    stopPreview();
    return;
  }
  stopPreview();

  const customText = (voicePreviewText?.value || "").trim();

  // Install-then-preview path: if the user typed custom text and this
  // voice isn't installed yet, kick off the install in-place on the
  // row's "Install" pill. When the install completes, the install
  // helper recursively re-invokes togglePreview — at which point the
  // voice IS installed and the synth-custom path below runs. Without
  // this branch, custom text on an uninstalled row would silently fall
  // back to the static sample, which defeats the whole point of
  // typing custom text in the first place.
  if (customText && !voice.installed) {
    _installThenPreview(voice, btn);
    return;
  }

  const audio = _ensurePreviewAudio();
  btn.classList.add("loading");
  btn.textContent = "…";
  _previewBtn = btn;

  // Custom-text path: if the user pasted their own preview text, ask the
  // server to synthesize it with this voice instead of playing the
  // canned HuggingFace sample. Routes through /api/synthesize which
  // returns one WAV in a single response (good fit for short previews).
  //
  // Gotcha: the catalog returns bare slugs ("en_US-amy-medium"); the
  // tts dispatcher routes by an engine prefix ("piper:..."). Without
  // the prefix, every preview silently falls through to the SAPI
  // default voice and sounds identical.
  const canSynthCustom = customText && voice.installed;
  try {
    if (canSynthCustom) {
      const res = await fetch("/api/synthesize", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          text: customText.slice(0, 300),
          voice_id: `piper:${voice.id}`,
          rate: 180,
          volume: 1.0,
          // Multi-speaker voices: first speaker for the preview is fine —
          // browsing the catalog is "do I like the voice family;" speaker
          // selection happens later in the dedicated speaker picker.
          speaker_id: voice.num_speakers > 1 ? 0 : null,
        }),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const blob = await res.blob();
      _previewBlobUrl = URL.createObjectURL(blob);
      audio.src = _previewBlobUrl;
    } else {
      // Static-sample path: original behavior. Pre-recorded sample
      // proxied from HuggingFace; instant playback, zero TTS cost.
      // Reached only when the preview-text input is empty — the
      // (custom text + uninstalled) case is intercepted above and
      // routed through _installThenPreview.
      // v225v4.27 (#704): same Tauri-aware prefix as the other voice
      // sample sites — <audio src=…> doesn't route through window.fetch
      // so the cross-origin rewrite has to happen here directly.
      audio.src = `${API_ORIGIN}/api/voices/sample/${encodeURIComponent(voice.id)}`;
    }
    await audio.play();
    btn.classList.remove("loading");
    btn.classList.add("playing");
    btn.textContent = "■";
  } catch (err) {
    // Most common causes:
    //   - 404 on the static sample (no published sample for this voice)
    //   - synthesis failure for a voice that isn't installed yet
    if (_previewBtn === btn) {
      btn.classList.remove("playing", "loading");
      btn.textContent = "—";
      btn.title = canSynthCustom
        ? "Synthesis failed for this voice"
        : "No preview available for this voice";
      btn.disabled = true;
      _previewBtn = null;
    }
    console.info("preview unavailable:", voice.id, err.message || err);
  }
}

function cap(s) {
  return s ? s[0].toUpperCase() + s.slice(1) : s;
}

async function installCatalogVoice(voice, btn) {
  btn.disabled = true;
  btn.classList.remove("failed");
  btn.textContent = "Starting…";
  try {
    const res = await fetch("/api/voices/install/stream", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ voice_id: voice.id }),
    });
    if (!res.ok) {
      let detail = `HTTP ${res.status}`;
      try {
        const j = await res.json();
        if (j.detail) detail = j.detail;
      } catch {}
      throw new Error(detail);
    }

    // Parse the SSE stream the same way generate() does.
    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let buf = "";
    let total = 0;
    let finished = false;
    let errorMsg = null;

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buf += decoder.decode(value, { stream: true });
      const blocks = buf.split("\n\n");
      buf = blocks.pop();
      for (const block of blocks) {
        const line = block.trim();
        if (!line.startsWith("data:")) continue;
        let event;
        try { event = JSON.parse(line.slice(5).trim()); } catch { continue; }

        if (event.type === "start") {
          total = event.total_bytes || 0;
          btn.textContent = "0%";
        } else if (event.type === "progress") {
          const pct = total > 0
            ? Math.min(100, Math.round((event.downloaded / total) * 100))
            : 0;
          btn.textContent = `${pct}%`;
        } else if (event.type === "done") {
          finished = true;
        } else if (event.type === "error") {
          errorMsg = event.message || "install error";
        }
      }
    }

    if (errorMsg) throw new Error(errorMsg);
    if (!finished) throw new Error("install stream ended early");

    voice.installed = true;
    btn.classList.add("installed");
    btn.textContent = "Installed";
    await loadVoices();
  } catch (e) {
    console.warn("voice install failed:", e);
    btn.classList.add("failed");
    btn.textContent = "Failed";
    setTimeout(() => {
      btn.classList.remove("failed");
      btn.textContent = "Install";
      btn.disabled = false;
    }, 2500);
  }
}

