// Best-effort: if the user closes the tab mid-audition, try to clean up
// the voice files anyway. `keepalive: true` lets the DELETE request
// outlive the page; not 100% reliable across browsers, but a worthwhile
// fallback so the disk doesn't quietly fill up with abandoned voices.
window.addEventListener("pagehide", () => {
  if (_auditionedVoiceIds.size === 0) return;
  for (const id of _auditionedVoiceIds) {
    try {
      fetch(`/api/voices/${encodeURIComponent(id)}`, {
        method: "DELETE",
        keepalive: true,
      });
    } catch {}
  }
});

// ---- Long-press tooltips on touch devices ------------------------------
// Mobile browsers ignore `title` attributes on buttons (no hover state), so
// every hint we've sprinkled across the UI is desktop-only. This gives touch
// users the same affordance: hold for ~500ms on any element with a `title`,
// a tooltip toast appears, and the synthetic click that follows is
// suppressed so the long-press doesn't also trigger the button.
(() => {
  let _tipTimer = null;
  let _tipStartX = 0;
  let _tipStartY = 0;
  let _tipShown = false;
  let _tipTarget = null;
  let _tipNode = null;
  let _tipDismissTimer = null;

  // Pointer is over a coarse input (finger / stylus). Don't bother on a
  // mouse — browsers already do `title` hover tooltips there.
  function _isTouch() {
    return matchMedia("(hover: none), (pointer: coarse)").matches;
  }

  function _hideTooltip() {
    if (_tipNode) {
      _tipNode.remove();
      _tipNode = null;
    }
    if (_tipDismissTimer) {
      clearTimeout(_tipDismissTimer);
      _tipDismissTimer = null;
    }
  }

  function _showTooltip(target, text) {
    _hideTooltip();
    const node = document.createElement("div");
    node.className = "tooltip-toast";
    node.textContent = text;
    // v225v4.14: if the long-pressed target lives inside an open
    // <dialog>, append the tooltip to that dialog instead of body.
    // showModal()-opened dialogs render in the browser's top layer
    // above everything in body regardless of z-index, so a tooltip
    // parented to body ends up clipped behind the dialog content.
    // Reported on the phone Library dialog — long-press on a card
    // button (Re-narrate, Sync, ✎, ×, etc.) fired the tooltip but
    // it rendered behind the cards. Walking up via .closest finds
    // the nearest open dialog ancestor; falling back to body keeps
    // every non-dialog long-press behaving as before.
    const host =
      target.closest("dialog[open]") || document.body;
    host.appendChild(node);

    // Position above the target if there's room, else below.
    const rect = target.getBoundingClientRect();
    const tipRect = node.getBoundingClientRect();
    const margin = 8;
    let top = rect.top - tipRect.height - margin;
    if (top < 8) top = rect.bottom + margin;
    let left = rect.left + rect.width / 2 - tipRect.width / 2;
    left = Math.max(8, Math.min(left, window.innerWidth - tipRect.width - 8));
    node.style.top = `${Math.round(top)}px`;
    node.style.left = `${Math.round(left)}px`;

    _tipNode = node;
    _tipDismissTimer = setTimeout(_hideTooltip, 2500);
  }

  function _cancelPending() {
    if (_tipTimer) {
      clearTimeout(_tipTimer);
      _tipTimer = null;
    }
    _tipTarget = null;
  }

  document.addEventListener(
    "touchstart",
    (e) => {
      if (!_isTouch()) return;
      if (e.touches.length !== 1) return;
      const target = e.target.closest("[title]");
      if (!target) return;
      // Drag handle owns its own pointer events; don't fight it.
      if (target.classList.contains("clip-drag")) return;
      const text = target.getAttribute("title");
      if (!text) return;

      _cancelPending();
      _tipShown = false;
      _tipTarget = target;
      _tipStartX = e.touches[0].clientX;
      _tipStartY = e.touches[0].clientY;

      _tipTimer = setTimeout(() => {
        _tipTimer = null;
        if (!_tipTarget) return;
        _showTooltip(_tipTarget, text);
        _tipShown = true;
      }, 500);
    },
    { passive: true }
  );

  document.addEventListener(
    "touchmove",
    (e) => {
      if (!_tipTimer && !_tipShown) return;
      if (e.touches.length !== 1) {
        _cancelPending();
        _hideTooltip();
        return;
      }
      const dx = e.touches[0].clientX - _tipStartX;
      const dy = e.touches[0].clientY - _tipStartY;
      // ~10px dead zone; beyond that the user is scrolling or swiping.
      if (dx * dx + dy * dy > 100) {
        _cancelPending();
        if (_tipShown) _hideTooltip();
        _tipShown = false;
      }
    },
    { passive: true }
  );

  document.addEventListener("touchend", () => {
    _cancelPending();
    // Leave the tooltip visible for its auto-dismiss window so the user can
    // actually read what they held to see.
  });

  document.addEventListener("touchcancel", () => {
    _cancelPending();
    _hideTooltip();
    _tipShown = false;
  });

  // Suppress the synthetic click that follows a successful long-press, so
  // holding to read the tooltip doesn't also fire the button's action.
  document.addEventListener(
    "click",
    (e) => {
      if (_tipShown) {
        e.preventDefault();
        e.stopPropagation();
        _tipShown = false;
      }
    },
    true
  );
})();

// Register the service worker so the app shell loads offline and the page
// ---- Global bookmark timeline (#251) -----------------------------------
// "All bookmarks" in the library tools row opens this dialog: every
// bookmark across every clip, sortable + filterable. Each row carries a
// Jump button that loads the source clip (if not current) and seeks to
// the bookmark's time. The trigger button is hidden in renderLibrary
// unless at least one clip has a bookmark.

let _allBookmarksEntries = []; // flattened {clip, bookmark} pairs, last fetch
let _allBookmarksSort = "recent";

function _formatAbsRecency(iso) {
  // Bookmark createdAt is an ISO timestamp; format it relative to "now"
  // for the sort=recent display. Falls back to YYYY-MM-DD on parse fail.
  if (!iso) return "";
  const d = new Date(iso);
  if (isNaN(d.getTime())) return iso.slice(0, 10);
  return d.toLocaleString();
}

async function _allBookmarksGather() {
  const clips = await listClips();
  const entries = [];
  for (const c of clips) {
    if (!Array.isArray(c.bookmarks) || c.bookmarks.length === 0) continue;
    for (const b of c.bookmarks) {
      entries.push({
        clipId: c.id,
        clipTitle: c.title || "(untitled)",
        clipTags: Array.isArray(c.tags) ? c.tags : [],
        bookmark: b,
      });
    }
  }
  _allBookmarksEntries = entries;
}

function _allBookmarksRender() {
  if (!allBookmarksList) return;
  const q = (allBookmarksFilter.value || "").trim().toLowerCase();
  let rows = _allBookmarksEntries.slice();

  if (q) {
    rows = rows.filter((e) => {
      const note = (e.bookmark.note || "").toLowerCase();
      const title = e.clipTitle.toLowerCase();
      const tags = e.clipTags.join(" ").toLowerCase();
      return note.includes(q) || title.includes(q) || tags.includes(q);
    });
  }

  switch (_allBookmarksSort) {
    case "time-in-clip":
      rows.sort(
        (a, b) =>
          (a.bookmark.timeSec || 0) - (b.bookmark.timeSec || 0) ||
          a.clipTitle.localeCompare(b.clipTitle)
      );
      break;
    case "clip-title":
      rows.sort(
        (a, b) =>
          a.clipTitle.localeCompare(b.clipTitle) ||
          (a.bookmark.timeSec || 0) - (b.bookmark.timeSec || 0)
      );
      break;
    case "recent":
    default:
      // createdAt absent on older bookmarks → fall back to clipId so
      // the row still sorts in some defensible order.
      rows.sort((a, b) => {
        const ta = a.bookmark.createdAt
          ? Date.parse(a.bookmark.createdAt)
          : a.clipId;
        const tb = b.bookmark.createdAt
          ? Date.parse(b.bookmark.createdAt)
          : b.clipId;
        return tb - ta;
      });
      break;
  }

  allBookmarksList.innerHTML = "";

  if (rows.length === 0) {
    const empty = document.createElement("div");
    empty.className = "all-bookmarks-empty";
    empty.textContent = q
      ? "No bookmarks match your filter."
      : "No bookmarks yet — add one with the 🔖 chip in the player.";
    allBookmarksList.appendChild(empty);
    allBookmarksSummary.textContent = "";
    return;
  }

  // Group by clip — gives a visual sense of where the listener is
  // spending revision attention. Sort modes still control the order
  // of CLIPS via first-row position; bookmarks within a clip stay in
  // ascending time so the per-clip subgroup reads naturally.
  const byClip = new Map();
  for (const r of rows) {
    if (!byClip.has(r.clipId)) byClip.set(r.clipId, []);
    byClip.get(r.clipId).push(r);
  }
  // Within each group, always sort bookmarks by time-in-clip.
  for (const arr of byClip.values()) {
    arr.sort((a, b) => (a.bookmark.timeSec || 0) - (b.bookmark.timeSec || 0));
  }

  for (const [clipId, clipRows] of byClip) {
    const head = document.createElement("div");
    head.className = "all-bookmarks-clip-head";
    head.textContent = clipRows[0].clipTitle;
    allBookmarksList.appendChild(head);

    for (const r of clipRows) {
      const row = document.createElement("div");
      row.className = "all-bookmarks-row";
      row.setAttribute("role", "listitem");

      const time = document.createElement("span");
      time.className = "all-bookmarks-time";
      time.textContent = formatTime(r.bookmark.timeSec || 0);

      const note = document.createElement("span");
      note.className = "all-bookmarks-note";
      note.textContent = r.bookmark.note || "(no note)";
      if (!r.bookmark.note) note.classList.add("muted");

      const when = document.createElement("span");
      when.className = "all-bookmarks-when";
      when.textContent = _formatAbsRecency(r.bookmark.createdAt);

      const jump = document.createElement("button");
      jump.type = "button";
      jump.className = "all-bookmarks-jump";
      jump.textContent = "Jump";
      jump.setAttribute(
        "aria-label",
        `Jump to ${r.clipTitle} at ${formatTime(r.bookmark.timeSec || 0)}`
      );
      jump.addEventListener("click", async () => {
        allBookmarksDialog.close();
        if (_currentClipId !== clipId) {
          await loadClip(clipId);
        }
        seekToTime(r.bookmark.timeSec || 0);
        // Auto-play after jump — the listener clicked to hear that line,
        // not to pause on it.
        try { await playerEl.play(); } catch {}
      });

      row.append(time, note, when, jump);
      allBookmarksList.appendChild(row);
    }
  }

  allBookmarksSummary.textContent =
    `${rows.length} bookmark${rows.length === 1 ? "" : "s"} across ${byClip.size} clip${byClip.size === 1 ? "" : "s"}`;
}

async function openAllBookmarks() {
  _allBookmarksSort = allBookmarksSort.value || "recent";
  allBookmarksFilter.value = "";
  await _allBookmarksGather();
  _allBookmarksRender();
  allBookmarksDialog.showModal();
}

if (libraryAllBookmarksBtn) {
  libraryAllBookmarksBtn.addEventListener("click", openAllBookmarks);
}
if (allBookmarksClose) {
  allBookmarksClose.addEventListener("click", () => allBookmarksDialog.close());
}
if (allBookmarksFilter) {
  allBookmarksFilter.addEventListener("input", _allBookmarksRender);
}
if (allBookmarksSort) {
  allBookmarksSort.addEventListener("change", () => {
    _allBookmarksSort = allBookmarksSort.value;
    _allBookmarksRender();
  });
}

// is installable on the home screen. Service workers only register over
// HTTPS or localhost; on a plain-HTTP LAN address registration will silently
// fail, which is fine — the app still works, just without offline caching.
if ("serviceWorker" in navigator) {
  window.addEventListener("load", () => {
    navigator.serviceWorker
      .register("/sw.js")
      .catch((err) => console.info("SW registration skipped:", err.message));
  });
}

// v225.tn38 (#515): persistent tag row above the player bar.
//
// Spotify-style double-deck bottom. The row contains the 6 annotation
// tag chips (✂ ✓ ⚠ 👁 ➕ ❤) + a 🎤 voice button + a ⌃ chevron that
// opens the existing pull-up drawer. Tapping a chip flags the
// sentence that's currently being narrated (read from
// activeSentenceIdx) — no need for the author to tap the sentence
// first.
//
// Coexists with the original palette flow: tap a sentence in
// annotate mode to open the palette for that specific sentence
// (good for flagging a non-current sentence). The tag row is the
// fast path for "listening live, react in 1 tap."
// v225.tn39 (#516): two-step tag-row flow.
//   1. Tap a chip → ARM that tag (pause playback, enter annotate mode,
//                                  chip glows to show what's loaded)
//   2. Tap a sentence → APPLY armed tag, exit annotate mode, resume
//
// Originally (#515) chip-tap fired immediately against the currently-
// narrating sentence. Two problems with that: (a) by the time the
// author taps, the narrator may be partway into the NEXT sentence
// so the wrong span gets flagged, (b) the author can't decide
// retroactively to flag the previous sentence they were thinking
// about. The two-step model fixes both — pausing on arm gives the
// author room to scan the reading view and pick the right sentence.
//
// Tap the same armed chip again → DISARM (cancel + resume).
// Tap a different chip while armed → switch arm (mode + pause persist).
// Esc / outside-tap → disarm.
let _phoneTagRowArmedTag = null;
let _phoneTagRowWasPlaying = false;
// v225.tn40 (#517): tracks which gesture the user used to start the
// voice recording — "tap" means recording stops on next tap of the
// 🎤 button (hands-free mode); "hold" means recording stops on the
// pointerup event of the original press (walkie-talkie mode). Cleared
// in _voiceReleaseStream so an auto-stop at VOICE_NOTE_MAX_SEC doesn't
// leave stale state for the next gesture.
let _phoneTagRowVoicePressMode = null;

function _phoneTagRowDisarm() {
  if (!_phoneTagRowArmedTag) return;
  _phoneTagRowArmedTag = null;
  // Clear armed visual on every chip — defensive in case multiple
  // got the class somehow.
  document.querySelectorAll(".phone-tag-row-chip.armed")
    .forEach((c) => c.classList.remove("armed"));
  // Exit annotate mode (which also closes the palette if it opened).
  if (typeof _setAnnotateMode === "function") _setAnnotateMode(false);
  // Resume playback if we paused on arm. _voiceResumeMainPlaybackIfNeeded
  // already exists for this pattern; reuse it so we share the
  // "wasPlaying" semantics.
  if (_phoneTagRowWasPlaying && playerEl && playerEl.paused) {
    try { playerEl.play().catch(() => {}); } catch {}
  }
  _phoneTagRowWasPlaying = false;
}

function _phoneTagRowArm(tagKey) {
  _dlog("tag-row-arm", "entry", {
    tagKey,
    currentClip: _currentClipId,
    armed: _phoneTagRowArmedTag,
    selectedSentence: _selectedSentenceIdx,
  });
  if (!_currentClipId) {
    setStatus("Load a clip first to flag a sentence.", true);
    _dlog("tag-row-arm", "no clip — bailing");
    return;
  }
  // v584: complement to v583's tap-then-confirm selection. If a
  // sentence is currently selected (dashed ring from a previous
  // tap), applying a tag goes directly — no need to arm-then-tap
  // again. This is the inverse of the existing arm-then-tap flow
  // and gives the user two equally valid orderings:
  //   tag chip → sentence    (existing)
  //   sentence → tag chip    (NEW)
  // Playback is NOT paused for this path — the user already
  // controlled their listening state via the prior sentence tap
  // (or via the player buttons), so we don't override it.
  if (
    typeof _selectedSentenceIdx === "number" &&
    _selectedSentenceIdx >= 0 &&
    sentenceSpans[_selectedSentenceIdx]
  ) {
    const idx = _selectedSentenceIdx;
    const text = sentenceSpans[idx].textContent || "";
    _phoneTagRowArmedTag = tagKey; // satisfy apply func's read
    _clearSelectedSentence();
    _phoneTagRowApplyArmedToSentence(idx, text);
    // apply calls _phoneTagRowDisarm internally → armed state
    // resets to null, chip-armed class clears, _wasPlaying gate
    // ensures no spurious resume.
    return;
  }
  // Tapping the same chip again → cancel.
  if (_phoneTagRowArmedTag === tagKey) {
    _phoneTagRowDisarm();
    setStatus("Cancelled.");
    return;
  }
  // First arm OR switch-arm: pause playback once + enter annotate mode.
  const wasFirstArm = _phoneTagRowArmedTag == null;
  _phoneTagRowArmedTag = tagKey;
  if (wasFirstArm) {
    _phoneTagRowWasPlaying = !!(playerEl && !playerEl.paused);
    if (_phoneTagRowWasPlaying) {
      try { _pauseAsUser(); } catch { try { playerEl.pause(); } catch {} }
    }
    if (typeof _setAnnotateMode === "function") _setAnnotateMode(true);
  }
  // Update chip visuals: armed chip glows, others reset.
  document.querySelectorAll(".phone-tag-row-chip").forEach((c) => {
    if (c.dataset.tag === tagKey) c.classList.add("armed");
    else c.classList.remove("armed");
  });
  setStatus(`${ANNOTATE_TAGS[tagKey].icon} ${ANNOTATE_TAGS[tagKey].label} armed — tap a sentence.`);
}

// Called from the reading-view click handler (the existing
// annotate-mode listener) when a sentence is tapped AND a tag is
// armed. Bypasses the palette since the tag is already chosen.
function _phoneTagRowApplyArmedToSentence(sentenceIndex, sentenceText) {
  const tagKey = _phoneTagRowArmedTag;
  if (!tagKey) return false;
  if (!_currentClipId) return false;
  const anno = {
    id: _annotateNewId(),
    sentenceIndex,
    sentenceFingerprint: _annotateFingerprint(sentenceText || ""),
    flaggedAt: new Date().toISOString(),
    source: "tagrow-arm",
    tags: [tagKey],
  };
  _addAnnotation(_currentClipId, anno).catch((e) =>
    console.warn("[tagrow] apply failed:", e),
  );
  // Flash the chip as confirmation + disarm + resume.
  const chip = document.querySelector(
    `.phone-tag-row-chip[data-tag="${tagKey}"]`,
  );
  if (chip) {
    chip.classList.remove("flashed");
    void chip.offsetWidth;
    chip.classList.add("flashed");
  }
  setStatus(`✓ ${ANNOTATE_TAGS[tagKey].label} · sentence ${sentenceIndex + 1}`);
  _phoneTagRowDisarm();
  // v225.tn55 (#533): they got it — kill the hint forever so it
  // doesn't keep nagging an author who now knows the pattern.
  _phoneTagRowDismissHint();
  return true;
}

// Back-compat name (the chip click handler below still calls this).
function _phoneTagRowFireTag(tagKey) {
  _phoneTagRowArm(tagKey);
}

function _phoneTagRowBoot() {
  if (!_phonePullupIsPhone()) return;
  const chipsContainer = document.getElementById("phone-tag-row-chips");
  if (chipsContainer && !chipsContainer.children.length) {
    for (const [key, meta] of Object.entries(ANNOTATE_TAGS)) {
      const chip = document.createElement("button");
      chip.type = "button";
      chip.className = "phone-tag-row-chip";
      chip.dataset.tag = key;
      chip.title = `${meta.label} — flag the currently-playing sentence`;
      chip.setAttribute("aria-label", `Flag current sentence as ${meta.label}`);
      chip.textContent = meta.icon;
      chip.style.background = meta.color;
      chip.addEventListener("click", (e) => {
        e.stopPropagation();
        _dlog("tag-row-chip", "click", { tag: key });
        _phoneTagRowFireTag(key);
      });
      // v225.tn56/57 (#539/#540): kill the Android text-selection
      // menu that long-press triggers. v225.tn72 (#554): removed
      // the touchstart preventDefault that was here — it ALSO
      // suppressed the synthetic click event on mobile, which
      // broke "tap a tag to arm" entirely. The CSS already has
      // `touch-action: manipulation` + `user-select: none` +
      // `-webkit-touch-callout: none` (see styles.css for the
      // .phone-tag-row-chip block), which handle selection
      // suppression without breaking click. contextmenu +
      // selectstart preventDefault stays — those don't affect
      // click firing.
      chip.addEventListener("contextmenu", (e) => e.preventDefault());
      chip.addEventListener("selectstart", (e) => e.preventDefault());
      chipsContainer.appendChild(chip);
    }
  }
  // v225.tn40 (#517): voice button — dual gesture mode.
  //   • TAP: starts recording, second tap stops (hands-free).
  //   • PRESS-AND-HOLD: starts after ~250ms while held, stops on
  //     release (walkie-talkie style for quick bursts).
  // Pointer events distinguish the two: short release before the
  // threshold = tap (toggle); release after threshold = hold-end.
  const voiceBtn = document.getElementById("phone-tag-row-voice");
  if (voiceBtn && !voiceBtn.dataset.bound) {
    voiceBtn.dataset.bound = "1";
    // v225.tn56 (#539): voice button's whole point is press-and-hold,
    // so the Android long-press → context menu is doubly broken
    // here — it both interrupts the hold gesture AND shows a Copy
    // menu over an icon. preventDefault on contextmenu fixes both.
    voiceBtn.addEventListener("contextmenu", (e) => e.preventDefault());
    let holdTimer = null;
    let pressStart = 0;
    const HOLD_THRESHOLD_MS = 250;
    const _startVoiceAtCurrentSentence = () => {
      if (!_currentClipId) {
        setStatus("Load a clip first to record a voice note.", true);
        return false;
      }
      const idx = typeof activeSentenceIdx === "number"
        ? activeSentenceIdx : -1;
      if (idx < 0) {
        setStatus("Play a clip first — voice notes attach to the current sentence.", true);
        return false;
      }
      _annotatePendingSentenceIndex = idx;
      _voiceStart();
      return true;
    };
    voiceBtn.addEventListener("pointerdown", (e) => {
      e.preventDefault();
      pressStart = Date.now();
      try { voiceBtn.setPointerCapture(e.pointerId); } catch {}
      // If already recording in tap mode, this pointerdown becomes
      // "second tap to stop" at pointerup — don't schedule a hold
      // start that would conflict.
      if (_phoneTagRowVoicePressMode === "tap" && _voiceRecorder) return;
      // Schedule the press-hold start. If the user releases before
      // this fires, the pointerup handler clears it and treats the
      // gesture as a tap.
      holdTimer = setTimeout(() => {
        holdTimer = null;
        if (_startVoiceAtCurrentSentence()) {
          _phoneTagRowVoicePressMode = "hold";
        }
      }, HOLD_THRESHOLD_MS);
    });
    voiceBtn.addEventListener("pointerup", (e) => {
      pressStart = 0;
      try { voiceBtn.releasePointerCapture(e.pointerId); } catch {}

      // v225.tn41 (#518): rewrote this state machine. The earlier
      // version (v225w) bailed when pointerdown early-returned during
      // the "second tap to stop a tap-mode recording" — that path
      // never scheduled a holdTimer, so the pointerup branch keyed
      // on holdTimer existence fell through and the stop never
      // fired. User saw the tap-highlight blue square (the OS
      // confirming the tap landed) but recording kept going.
      //
      // Cases handled, in order:
      //   1. Hold-mode release → stop. Hold mode is set by the
      //      hold-timer callback; reaching pointerup with that mode
      //      means we're ending a press-and-hold.
      //   2. Tap-mode + recording → stop. This is the new branch.
      //      The first tap left mode = "tap" and a recorder running;
      //      this pointerup is the second tap, and it stops cleanly
      //      regardless of whether a holdTimer was scheduled.
      //   3. Quick tap, not yet recording → start in tap mode. The
      //      hold timer hadn't fired (release was fast); pointerdown
      //      had no recorder yet so it scheduled one, and we cancel
      //      it here before starting the recording.

      // 1. Hold-mode release.
      if (_phoneTagRowVoicePressMode === "hold") {
        if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
        _voiceStop();
        _phoneTagRowVoicePressMode = null;
        return;
      }

      // Cancel any pending hold-start timer regardless of which
      // branch we end up in — the gesture is resolved at pointerup.
      if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }

      // 2. Tap-mode + already recording → second tap stops it.
      if (_voiceRecorder && _phoneTagRowVoicePressMode === "tap") {
        _voiceStop();
        _phoneTagRowVoicePressMode = null;
        return;
      }

      // 3. Quick tap, no recorder → start in tap mode.
      if (!_voiceRecorder) {
        if (_startVoiceAtCurrentSentence()) {
          _phoneTagRowVoicePressMode = "tap";
        }
      }
    });
    // pointercancel happens when the OS interrupts the gesture
    // (system gesture, scroll lock, etc.). Treat it as a release of
    // any in-flight hold so we don't end up stuck recording.
    voiceBtn.addEventListener("pointercancel", (e) => {
      pressStart = 0;
      try { voiceBtn.releasePointerCapture(e.pointerId); } catch {}
      if (holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
      if (_phoneTagRowVoicePressMode === "hold" && _voiceRecorder) {
        _voiceStop();
        _phoneTagRowVoicePressMode = null;
      }
    });
  }
  // v225.tn39 (#516): Esc cancels an armed tag (in addition to the
  // chip-tap-same-twice cancel and the implicit disarm-on-apply).
  if (!document.body.dataset.tagrowEscBound) {
    document.body.dataset.tagrowEscBound = "1";
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && _phoneTagRowArmedTag) {
        e.stopPropagation();
        _phoneTagRowDisarm();
        setStatus("Cancelled.");
      }
    });
  }

  // Chevron toggles the existing pull-up drawer.
  const chevron = document.getElementById("phone-tag-row-chevron");
  if (chevron && !chevron.dataset.bound) {
    chevron.dataset.bound = "1";
    chevron.addEventListener("click", (e) => {
      e.stopPropagation();
      _phonePullupToggle();
    });
  }

  // v225.tn55 (#533): first-tap hint above the tag row. Authors
  // can't tell that those icons do anything until they tap one.
  // Inject a one-shot bubble that explains the arm-and-apply
  // pattern, dismisses on the first successful apply OR the ✕.
  // Lives in localStorage so it doesn't reappear; "Replay
  // onboarding tips" clears the key (registered in
  // _ONBOARDING_HINT_KEYS above).
  _phoneTagRowMaybeShowHint();
}

const _TAGROW_HINT_KEY = "narrative.hintSeen.tagRow";

function _phoneTagRowHintDismissed() {
  try {
    return localStorage.getItem(_TAGROW_HINT_KEY) === "1";
  } catch {
    return false;
  }
}

function _phoneTagRowDismissHint() {
  try {
    localStorage.setItem(_TAGROW_HINT_KEY, "1");
  } catch {}
  const el = document.getElementById("phone-tag-row-hint");
  if (el) el.hidden = true;
}

function _phoneTagRowMaybeShowHint() {
  if (_phoneTagRowHintDismissed()) return;
  const app = document.querySelector(".app");
  const tagRow = document.getElementById("phone-tag-row");
  if (!app || !tagRow) return;
  let hint = document.getElementById("phone-tag-row-hint");
  if (!hint) {
    hint = document.createElement("div");
    hint.id = "phone-tag-row-hint";
    hint.className = "phone-tag-row-hint";
    hint.setAttribute("role", "status");
    hint.innerHTML =
      '<span class="phone-tag-row-hint-icon" aria-hidden="true">💡</span>' +
      '<span class="phone-tag-row-hint-text">Tap a tag, then tap a sentence to flag it.</span>' +
      '<button type="button" class="phone-tag-row-hint-dismiss" aria-label="Dismiss hint">✕</button>';
    hint
      .querySelector(".phone-tag-row-hint-dismiss")
      .addEventListener("click", (e) => {
        e.stopPropagation();
        _phoneTagRowDismissHint();
      });
    // Append as sibling of #phone-tag-row inside .app so it can
    // anchor above the row using fixed positioning with shared
    // stacking context.
    app.appendChild(hint);
  }
  hint.hidden = false;
}
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", _phoneTagRowBoot);
} else {
  _phoneTagRowBoot();
}
window.addEventListener("resize", () => {
  if (_phonePullupIsPhone()) _phoneTagRowBoot();
});

// v225.mobile / Phase C (#506): ☰ top menu sheet.
//
// On phone the entire hero (brand + tagline + 4 icon buttons) is
// hidden in CSS. A single ☰ button gets injected at top-left and
// opens a small sheet that slides down from the top with shortcuts
// to Library / Import / New clip / Settings / Help. Items don't
// relocate the hero buttons (which broke pull-up because of the
// transparent surfaces; here we don't need to anyway) — they just
// dispatch click() on the corresponding existing buttons that
// stay in the hidden hero. All wiring is preserved automatically.
function _phoneMenuIsPhone() {
  return window.matchMedia("(max-width: 767px)").matches;
}
function _phoneMenuOpen() {
  document.body.dataset.menu = "open";
  // v225v3.51 (#784): flip the button to ✕ + update aria so the user
  // has a clear close affordance. CSS bumps z-index above the menu so
  // it stays tappable.
  const btn = document.querySelector(".phone-menu-btn");
  if (btn) {
    btn.textContent = "✕";
    btn.setAttribute("aria-label", "Close menu");
    btn.title = "Close menu";
  }
}
function _phoneMenuClose() {
  if (document.body.dataset.menu) delete document.body.dataset.menu;
  const btn = document.querySelector(".phone-menu-btn");
  if (btn) {
    btn.textContent = "☰";
    btn.setAttribute("aria-label", "Open menu");
    btn.title = "Menu";
  }
}
function _phoneMenuToggle() {
  if (document.body.dataset.menu === "open") _phoneMenuClose();
  else _phoneMenuOpen();
}
// v225eb (#615): clip title in the phone top bar. Sits between
// ☰ (left:52) and 📚 (right:196), truncated with ellipsis on
// narrow viewports. Painted on boot + every clip load + every
// rename. CSS hides the slot when no clip is loaded.
//
// Accepts an optional `clip` so callers that already have the
// resolved clip in scope (loadClip, saveClipEdit) don't depend on
// _currentClipId having been assigned yet. Bug seen in the
// initial implementation: loadClip called this BEFORE setting
// _currentClipId, so the function read the old/null value and
// painted nothing. Without a clip arg, falls back to the getClip
// path keyed on _currentClipId — used by boot.
function _phonePaintTopTitle(clip) {
  if (!_phoneMenuIsPhone()) return;
  // v225fl (#654): paints into the pull-up drawer's Listening slot
  // instead of the phone top bar. Name kept (paintTopTitle) so the
  // many call sites in loadClip / clearForNewClip / saveClipEdit
  // don't need to change. The title now lives one tap away (open the
  // drawer) and the top bar's right edge has room for the v225fk
  // Import icon + bookmark.
  const listening = document.querySelector('[data-state="listening"]');
  // Optional: also keep the phone-top-title in sync if it exists
  // (so cached DOM from older builds doesn't break — the CSS hides
  // the element, but we keep its content nullable for safety).
  const topTitle = document.querySelector(".phone-top-title");
  const apply = (c) => {
    const t = c ? ((c.title || "").trim() || "Untitled clip") : "";
    if (listening) {
      listening.textContent = t;
      if (t) listening.title = t; else listening.removeAttribute("title");
    }
    if (topTitle) {
      topTitle.textContent = "";
      topTitle.removeAttribute("title");
    }
  };
  if (clip) { apply(clip); return; }
  if (!_currentClipId) { apply(null); return; }
  getClip(_currentClipId).then(apply).catch(() => apply(null));
}

function _phoneMenuBoot() {
  if (!_phoneMenuIsPhone()) return;
  const app = document.querySelector(".app");
  if (!app) return;
  // Inject the ☰ button as the first child of .app if not already
  // present. It's fixed-positioned via CSS so its DOM location only
  // matters for stacking context (we want it inside .app).
  if (!app.querySelector(".phone-menu-btn")) {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "phone-menu-btn";
    btn.setAttribute("aria-label", "Open menu");
    btn.title = "Menu";
    btn.textContent = "☰";
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      _phoneMenuToggle();
    });
    app.insertBefore(btn, app.firstChild);
  }

  // v225fl (#654): no longer inject .phone-top-title — the clip
  // title moved back into the pull-up Listening slot to make room
  // for the v225fk Import icon at the top-right. _phonePaintTopTitle
  // now writes into [data-state="listening"] instead. The boot call
  // is kept so the slot's initial paint runs on first load.
  _phonePaintTopTitle();

  // v225fk (#653): quick-access Import icon at the top-right. Tester
  // reported the empty header (☰ on the left + centered books emoji,
  // nothing on the right) gave no signal about where to start. Import
  // sits where the bookmark button lives when a clip is loaded
  // (right:60px to clear the bookmark), and flushes right (right:12px)
  // when no clip is loaded — the bookmark button is hidden in that
  // state, so Import takes its slot. CSS handles both positions via
  // a body:has() gate. Tap fires the existing #import-btn handler so
  // the centered modal opens with no parallel state machine.
  if (!app.querySelector(".phone-import-btn")) {
    const imp = document.createElement("button");
    imp.type = "button";
    imp.className = "phone-import-btn";
    imp.setAttribute("aria-label", "Import a manuscript");
    imp.title = "Import a file, URL, or repo";
    imp.textContent = "📥";
    imp.addEventListener("click", (e) => {
      e.stopPropagation();
      const target = document.getElementById("import-btn");
      if (target) target.click();
      // v225fm (#655): first-tap hint. Phone title attrs aren't
      // surfaced on tap, so the only way the user learns what 📥
      // does is by seeing the dropdown after they tap it. Status
      // line says it explicitly once, then never again.
      if (typeof _fireChipHint === "function") {
        _fireChipHint(
          "narrative.hintSeen.import",
          "💡 Import pulls text from any URL, PDF/EPUB/DOCX file, GitHub repo, or Obsidian vault.",
        );
      }
    });
    app.appendChild(imp);
  }

  // v225fu (#663): ? Help icon to the LEFT of 📥 Import. Promoted
  // out of the ☰ menu so the manual is one tap away — same priority
  // as Library and Import. Dispatches to the existing #help-btn so
  // the manual-dialog wiring (showModal + iframe load + Esc handler)
  // stays the single source of truth.
  if (!app.querySelector(".phone-help-btn")) {
    const hlp = document.createElement("button");
    hlp.type = "button";
    hlp.className = "phone-help-btn";
    hlp.setAttribute("aria-label", "Open help and manual");
    hlp.title = "Help & manual";
    hlp.textContent = "?";
    hlp.addEventListener("click", (e) => {
      e.stopPropagation();
      const target = document.getElementById("help-btn");
      if (target) target.click();
    });
    app.appendChild(hlp);
  }

  // v225.tn42 (#519): quick-access bookmark button at top-right.
  // Mirror to the ☰ on the left. Tap fires the existing
  // #bookmark-add-btn handler (now living in the pull-up drawer's
  // Author section) so the addBookmarkAtCurrentTime flow + sync
  // pipeline keep their single source of truth. Brief flash
  // confirms the tap landed.
  if (!app.querySelector(".phone-bookmark-btn")) {
    const bm = document.createElement("button");
    bm.type = "button";
    bm.className = "phone-bookmark-btn";
    bm.setAttribute("aria-label", "Add bookmark at current time");
    bm.title = "Bookmark current time";
    bm.textContent = "🔖";
    bm.addEventListener("click", async (e) => {
      e.stopPropagation();
      // v225.tn61 (#534): tap 🔖 → save → open the pull-up to its
      // Bookmarks section → scroll to and briefly highlight the
      // just-added row so the author can immediately tap it to add
      // a note. Replaces the old fire-and-flash behavior — saving
      // a bookmark silently was leaving authors wondering where
      // it went, and the natural next action ("add a note while
      // the moment is fresh") was a deliberate detour through the
      // drawer.
      let newId = null;
      try {
        if (typeof addBookmarkAtCurrentTime === "function") {
          newId = await addBookmarkAtCurrentTime();
        } else {
          // Fallback: legacy dispatch (shouldn't be reachable).
          const target = document.getElementById("bookmark-add-btn");
          if (target) target.click();
        }
      } catch (err) {
        console.warn("[phone-bookmark] save failed:", err);
        setStatus("Bookmark failed.", true);
        return;
      }
      // Flash the 🔖 button itself so the tap registers visually
      // even before the drawer slides up.
      bm.classList.remove("flashed");
      void bm.offsetWidth;
      bm.classList.add("flashed");

      if (newId == null) return;

      // v225.tn64 (#546): open the centered floating editor instead
      // of the pull-up drawer. The drawer-open approach hit a
      // Chromium Android keyboard bug (#544/#545 didn't fully
      // resolve). The centered modal sidesteps the drawer's
      // position:fixed layout entirely — it stays above the
      // keyboard naturally as the visual viewport shrinks. The
      // bookmark is already saved by addBookmarkAtCurrentTime;
      // the editor just lets the author add a note while the
      // moment is fresh.
      //
      // v225fz (#668): pass isNew=true so the editor knows that a
      // cancel/dismiss should revert the just-added bookmark — the
      // 🔖 tap is provisional until they hit Done. Existing-bookmark
      // edits (the drawer note-row tap below in renderBookmarks)
      // omit the arg so it defaults to false.
      if (typeof _openBookmarkEditor === "function") {
        _openBookmarkEditor(newId, true);
      }
    });
    app.appendChild(bm);
  }

  // v587: 📚 Library button at top-right, left of the bookmark icon.
  // Moved out of the ☰ menu — Library is the most-used menu item
  // for revising authors, and always-on access (without opening
  // the menu) saves a tap on every navigation. Mirrors the
  // existing bookmark button's positioning + flash pattern; tap
  // dispatches click on the hidden hero #library-trigger so the
  // dialog, badge count, and any future hero-rail behavior stay
  // single-sourced. Visible whenever the phone shell is — no
  // "needs a clip" gate, because finding a clip IS the point.
  if (!app.querySelector(".phone-library-btn")) {
    const lib = document.createElement("button");
    lib.type = "button";
    lib.className = "phone-library-btn";
    lib.setAttribute("aria-label", "Open library");
    lib.title = "Library";
    lib.textContent = "📚";
    lib.addEventListener("click", (e) => {
      e.stopPropagation();
      const trigger = document.getElementById("library-trigger");
      if (trigger) trigger.click();
      lib.classList.remove("flashed");
      void lib.offsetWidth;
      lib.classList.add("flashed");
    });
    app.appendChild(lib);
  }

  // v225v3.60 (#793): 🎤 Voice button. Promoted into the phone header
  // because Voice was only reachable via the pull-up drawer AFTER
  // loading a clip — a user with no clip yet (just arrived, or just
  // hit "Start over") had no path to browse / change voices. Sits at
  // right:200px between 📚 Library (right:156) and 📥 Import
  // (right:248). Tap dispatches click on the hidden hero
  // #voice-trigger so the voice-dialog wiring stays single-sourced.
  if (!app.querySelector(".phone-voice-btn")) {
    const vc = document.createElement("button");
    vc.type = "button";
    vc.className = "phone-voice-btn";
    vc.setAttribute("aria-label", "Open voice picker");
    vc.title = "Voice";
    vc.textContent = "🎤";
    vc.addEventListener("click", (e) => {
      e.stopPropagation();
      const trigger = document.getElementById("voice-trigger");
      if (trigger) trigger.click();
      vc.classList.remove("flashed");
      void vc.offsetWidth;
      vc.classList.add("flashed");
    });
    app.appendChild(vc);
  }

  // v593: ✎ Edit text button. Sits between 📚 and 📖 — close enough
  // to thumb for frequent revising but not stealing 🔖's rightmost
  // slot. Dispatches click on the hidden #edit-text button so all
  // the v592 inline-edit + legacy exit-to-textarea logic stays
  // single-sourced. Clip-loaded gate: edit needs text in the view.
  if (!app.querySelector(".phone-edit-btn")) {
    const ed = document.createElement("button");
    ed.type = "button";
    ed.className = "phone-edit-btn";
    ed.setAttribute("aria-label", "Edit text");
    ed.title = "Edit selected sentence (or full text)";
    ed.textContent = "✎";
    ed.addEventListener("click", (e) => {
      e.stopPropagation();
      const trigger = document.getElementById("edit-text");
      if (trigger) trigger.click();
      ed.classList.remove("flashed");
      void ed.offsetWidth;
      ed.classList.add("flashed");
    });
    app.appendChild(ed);
  }

  // v588: 📖 / 📜 View-toggle button. Sits between 📚 and 🔖. State-
  // aware: shows 📖 when the reader is in audio view (tap → switch
  // to book), shows 📜 when in book view (tap → switch back). The
  // existing #book-view-toggle hero button (line ~11201) already
  // owns the entry/exit functions and updates its OWN textContent
  // on state change; we mirror that state by reading its
  // textContent post-click. Initial state is set from the same
  // signal. Tap dispatches to that hidden button so all the
  // wiring (enterBookView/exitBookView/scroll restoration/etc)
  // stays single-sourced. Gated on clip-loaded — book view
  // requires text loaded; the menu item was already gated this
  // way too.
  if (!app.querySelector(".phone-bookview-btn")) {
    const view = document.createElement("button");
    view.type = "button";
    view.className = "phone-bookview-btn";
    view.setAttribute("aria-label", "Switch view");
    view.title = "Switch view";
    // Read initial state from the hidden hero toggle. Its textContent
    // is "📖 Book view" when in audio mode, "▶ Audio view" when in
    // book mode (set by lines 14273 / 14601). We mirror just the
    // icon: 📖 in audio, 📜 in book.
    const _phoneBookviewSync = () => {
      const t = document.getElementById("book-view-toggle");
      if (!t) return;
      const inBook = (t.textContent || "").includes("Audio view");
      view.textContent = inBook ? "📜" : "📖";
      view.setAttribute(
        "aria-label",
        inBook ? "Switch to audio view" : "Switch to book view",
      );
      view.title = inBook ? "Audio view" : "Book view";
    };
    _phoneBookviewSync();
    // Sync after the toggle target's text changes (i.e. after any
    // tap, ours or another path). MutationObserver watches the
    // characterData inside the button.
    const t = document.getElementById("book-view-toggle");
    if (t && !t.dataset.phoneBookviewObserved) {
      t.dataset.phoneBookviewObserved = "1";
      const obs = new MutationObserver(_phoneBookviewSync);
      obs.observe(t, {
        characterData: true,
        childList: true,
        subtree: true,
      });
    }
    view.addEventListener("click", (e) => {
      e.stopPropagation();
      const trigger = document.getElementById("book-view-toggle");
      if (trigger) trigger.click();
      view.classList.remove("flashed");
      void view.offsetWidth;
      view.classList.add("flashed");
      // The observer above will fire when the trigger's textContent
      // flips. No manual re-sync needed here.
    });
    app.appendChild(view);
  }

  // v225.tn48 (#525): Generate audio bar — fixed bottom CTA on
  // phone when text is loaded but no audio exists yet. Replaces
  // the desktop-style Generate / Download / Queue silently row,
  // which ate ~250px below the chapter queue on phone. Download
  // moves into ☰; Queue silently rides along as a secondary link
  // here because it's the contextual alternative to Generate.
  if (!app.querySelector(".phone-generate-bar")) {
    const bar = document.createElement("div");
    bar.className = "phone-generate-bar";
    bar.hidden = true;
    // v225g4 (#693): added "📖 Ebook" as a peer option to Generate
    // audio so post-import phone users see both flows immediately
    // instead of having to dig through the ☰ menu (where #691 put
    // the entry). Author reported feeling stuck after EPUB import:
    // the textarea filled, the Generate bar dominated the bottom,
    // and the import-preview's "Read as ebook" chip was scrolled
    // off-screen by the time they got there. Putting both actions
    // in the same fixed-bottom strip means the choice is in their
    // face the moment the file lands.
    bar.innerHTML =
      '<button type="button" class="phone-generate-btn" aria-label="Generate audio from this text">' +
      '<span class="phone-generate-icon" aria-hidden="true">▶</span>' +
      '<span class="phone-generate-label">Generate audio</span>' +
      "</button>" +
      '<button type="button" class="phone-generate-ebook" aria-label="Save as ebook and open book view">' +
      "📖 Ebook" +
      "</button>" +
      '<button type="button" class="phone-generate-queue" aria-label="Queue silently in background">' +
      "Queue silently →" +
      "</button>";
    bar.querySelector(".phone-generate-btn").addEventListener("click", () => {
      const t = document.getElementById("generate");
      if (t) t.click();
    });
    bar.querySelector(".phone-generate-ebook").addEventListener("click", () => {
      if (typeof _openAsEbook === "function") {
        _openAsEbook().catch((err) => {
          console.error("[ebook] phone-generate-bar Ebook tap failed:", err);
          setStatus("Couldn't open as ebook — see console.", true);
        });
      }
    });
    bar.querySelector(".phone-generate-queue").addEventListener("click", () => {
      const t = document.getElementById("queue-silently");
      if (t) t.click();
    });
    app.appendChild(bar);

    // Visibility sync. Show when: phone width AND no player card AND
    // (textarea has text OR chapter queue active) AND generate button
    // is enabled (means the underlying state machine agrees we can).
    const _syncGenerateBar = () => {
      const isPhone = window.matchMedia("(max-width: 767px)").matches;
      if (!isPhone) {
        bar.hidden = true;
        return;
      }
      // v225g3 (#692): hide the bar when the loaded clip is an ebook.
      // The user explicitly chose "Open as ebook" — surfacing a giant
      // "Generate audio" prompt on top of that is the opposite signal.
      // They can still add audio later via ☰ → Open as ebook? no —
      // ☰ → tap the clip in library → Generate (which is in the
      // hidden hero, dispatchable from ☰). The "Add audio" path is
      // covered by the manual + "what's new" — the bar isn't the
      // right surface for it.
      if (_currentClipKind === "ebook" || document.body.dataset.clipKind === "ebook") {
        bar.hidden = true;
        delete document.body.dataset.phoneGenerateBar;
        return;
      }
      // v225g3 (#692): also hide when book view is open — the book
      // view is a takeover surface; the Generate bar peeking through
      // the bottom is visual noise and not actionable from inside
      // the book.
      const bv = document.getElementById("book-view");
      if (bv && !bv.hidden) {
        bar.hidden = true;
        delete document.body.dataset.phoneGenerateBar;
        return;
      }
      const playerCard = document.getElementById("player-card");
      const gen = document.getElementById("generate");
      const text = document.getElementById("text");
      const playerVisible = playerCard && !playerCard.hidden;
      const genUsable = gen && !gen.hidden && !gen.disabled;
      const hasText =
        (text && (text.value || "").trim().length > 0) ||
        !!document.querySelector("#chapter-queue-pill:not([hidden])");
      const shouldShow = !playerVisible && hasText && genUsable;
      bar.hidden = !shouldShow;
      // Body data attribute so CSS can shift the chapter-pill / reading
      // view's bottom padding to clear the bar without measuring it.
      if (shouldShow) document.body.dataset.phoneGenerateBar = "1";
      else delete document.body.dataset.phoneGenerateBar;
    };
    // v225g3 (#692): expose so _setCurrentClipKind and the book-view
    // toggle handlers can prod the bar at the right moments.
    window._syncPhoneGenerateBar = _syncGenerateBar;
    _syncGenerateBar();
    const playerCard = document.getElementById("player-card");
    const gen = document.getElementById("generate");
    const text = document.getElementById("text");
    const chapterPill = document.getElementById("chapter-queue-pill");
    if (playerCard) {
      new MutationObserver(_syncGenerateBar).observe(playerCard, {
        attributes: true,
        attributeFilter: ["hidden"],
      });
    }
    if (gen) {
      new MutationObserver(_syncGenerateBar).observe(gen, {
        attributes: true,
        attributeFilter: ["disabled", "hidden"],
      });
    }
    if (text) text.addEventListener("input", _syncGenerateBar);
    if (chapterPill) {
      new MutationObserver(_syncGenerateBar).observe(chapterPill, {
        attributes: true,
        attributeFilter: ["hidden"],
      });
    }
    // Resize → media query change can flip phone/desktop mode.
    window.addEventListener("resize", _syncGenerateBar, { passive: true });
  }

  // Wire menu items → dispatch click() on the corresponding hidden
  // hero button. The hero is display:none on phone but its buttons
  // are still in the DOM with their handlers attached.
  const menu = document.getElementById("phone-menu");
  if (menu && !menu.dataset.bound) {
    menu.dataset.bound = "1";
    const triggers = {
      library: "library-trigger",
      import: "import-btn",
      new: "clear-btn",
      // v225.tn47 (#524) → v593: Edit text + Book view were
      // consolidated into ☰ then promoted again to top-bar icons
      // (.phone-edit-btn, .phone-bookview-btn). Trigger entries
      // retained as fallbacks in case the dispatch is ever
      // re-pointed at the menu — harmless if the menu item is
      // absent.
      edit: "edit-text",
      bookview: "book-view-toggle",
      // v225.tn48 (#525): Download MP3 dispatch.
      download: "download",
      // v225g2 (#691): phone parity for ebook mode — dispatch to the
      // hidden Generate-row button. The button's click handler runs
      // _openAsEbook() the same way the desktop tap does.
      "open-as-ebook": "open-as-ebook",
      // v225dr: export notes dispatch — same id as the new chip.
      "export-notes": "export-notes-btn",
      settings: "settings-btn",
      help: "help-btn",
    };
    menu.addEventListener("click", (e) => {
      const item = e.target.closest(".phone-menu-item");
      if (!item) return;
      e.stopPropagation();
      const action = item.dataset.action;
      const targetId = triggers[action];
      // Close the sheet BEFORE firing the target — otherwise the
      // target's dialog opens with our scrim still up + can't be
      // dismissed by tap-outside (our scrim eats the clicks).
      _phoneMenuClose();
      if (!targetId) return;
      // v225g2 (#691): "📖 Open as ebook" menu item — the hero button
      // is disabled until text appears, so target.click() would be a
      // silent no-op. Route directly through _openAsEbook so the
      // user gets the "Type, paste, or import some text first" status
      // message instead of nothing happening.
      if (action === "open-as-ebook") {
        Promise.resolve().then(() => {
          if (typeof _openAsEbook === "function") {
            _openAsEbook().catch((err) => {
              console.error("[ebook] phone menu open-as-ebook failed:", err);
              setStatus("Couldn't open as ebook — see console.", true);
            });
          }
        });
        return;
      }
      const target = document.getElementById(targetId);
      if (target) {
        // Use a microtask so the sheet's close transition starts
        // before the target dialog fires its own open animation.
        Promise.resolve().then(() => target.click());
      }
    });
  }

  // Scrim click → close.
  const scrim = document.getElementById("phone-menu-scrim");
  if (scrim && !scrim.dataset.bound) {
    scrim.dataset.bound = "1";
    scrim.addEventListener("click", (e) => {
      e.stopPropagation();
      _phoneMenuClose();
    });
  }

  // Esc closes (in addition to the pull-up's existing Esc handler).
  if (!document.body.dataset.menuEscBound) {
    document.body.dataset.menuEscBound = "1";
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && document.body.dataset.menu === "open") {
        e.stopPropagation();
        _phoneMenuClose();
      }
    });
  }
}
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", _phoneMenuBoot);
} else {
  _phoneMenuBoot();
}
window.addEventListener("resize", () => {
  if (_phoneMenuIsPhone()) _phoneMenuBoot();
});

// v225er (#635): landscape immersive mode — auto-hide chrome on
// phones rotated to landscape, tap-to-reveal, 3s of no input → hide
// again. Same idiom video players use.
//
// State machine:
//   landscape entered → set data-landscape-immersive=1, chrome
//                       starts visible, start 3s timer
//   timer fires       → set data-landscape-hidden=1 (CSS slides
//                       chrome off-screen)
//   tap anywhere      → clear data-landscape-hidden, restart timer
//   landscape exited  → clear both attributes, kill timer
//
// Gates: while a modal dialog is open, while the bookmark editor or
// annotate palette is up, while recording a voice note — those flows
// need chrome reachable, so the auto-hide stalls until they close.
const _LANDSCAPE_IMMERSIVE_DELAY_MS = 3000;
const _landscapeImmersiveMQ = window.matchMedia(
  "(orientation: landscape) and (max-height: 500px)"
);
let _landscapeImmersiveTimer = null;

function _isLandscapeImmersiveBlocked() {
  // Modal dialogs: settings, voice, library, characters, picker,
  // bookmark editor (.bookmark-editor visible), TOC, etc.
  const anyDialogOpen = !!document.querySelector("dialog[open]");
  if (anyDialogOpen) return true;
  // Phone manual viewer up
  if (document.body.dataset.phoneManualOpen) return true;
  // Pull-up drawer expanded
  if (document.body.dataset.pullup === "open") return true;
  // Phone menu sheet expanded
  if (document.body.dataset.menu === "open") return true;
  // Voice note actively recording
  if (typeof _voiceIsRecording !== "undefined" && _voiceIsRecording) return true;
  // Annotate palette visible
  const palette = document.getElementById("annotate-palette");
  if (palette && !palette.hidden) return true;
  // Bookmark editor visible
  const bmEditor = document.getElementById("bookmark-editor");
  if (bmEditor && !bmEditor.hidden) return true;
  // Inline edit in progress
  if (typeof _inlineEditingIdx !== "undefined" && _inlineEditingIdx >= 0) return true;
  return false;
}

function _hideLandscapeChrome() {
  if (!_landscapeImmersiveMQ.matches) return;
  if (_isLandscapeImmersiveBlocked()) {
    // Modal / palette / recording in flight — try again after the
    // standard delay so we re-evaluate once it clears.
    _landscapeImmersiveTimer = setTimeout(
      _hideLandscapeChrome,
      _LANDSCAPE_IMMERSIVE_DELAY_MS,
    );
    return;
  }
  document.body.dataset.landscapeHidden = "1";
  _landscapeImmersiveTimer = null;
}

function _showLandscapeChrome() {
  delete document.body.dataset.landscapeHidden;
  _resetLandscapeImmersiveTimer();
}

function _resetLandscapeImmersiveTimer() {
  if (_landscapeImmersiveTimer) clearTimeout(_landscapeImmersiveTimer);
  if (!_landscapeImmersiveMQ.matches) {
    _landscapeImmersiveTimer = null;
    return;
  }
  _landscapeImmersiveTimer = setTimeout(
    _hideLandscapeChrome,
    _LANDSCAPE_IMMERSIVE_DELAY_MS,
  );
}

function _applyLandscapeImmersiveLayout() {
  if (_landscapeImmersiveMQ.matches) {
    document.body.dataset.landscapeImmersive = "1";
    // Show chrome initially, start the auto-hide timer.
    delete document.body.dataset.landscapeHidden;
    _resetLandscapeImmersiveTimer();
  } else {
    // Back to portrait / desktop — always show chrome, kill timer.
    delete document.body.dataset.landscapeImmersive;
    delete document.body.dataset.landscapeHidden;
    if (_landscapeImmersiveTimer) {
      clearTimeout(_landscapeImmersiveTimer);
      _landscapeImmersiveTimer = null;
    }
  }
}

// Wake chrome on any user input. pointerdown fires earliest in the
// event sequence (before click) so the chrome shows up before the
// user's tap on a button registers, meaning their tap can both wake
// the chrome AND hit a now-visible target.
//
// Capture phase so this fires before per-element pointerdown
// handlers that might stopPropagation. We don't stopPropagation
// here — the user's tap still travels to whatever they hit.
document.addEventListener(
  "pointerdown",
  () => {
    if (!_landscapeImmersiveMQ.matches) return;
    _showLandscapeChrome();
  },
  true,
);

// Respond to rotation + viewport change.
if (typeof _landscapeImmersiveMQ.addEventListener === "function") {
  _landscapeImmersiveMQ.addEventListener("change", _applyLandscapeImmersiveLayout);
} else if (typeof _landscapeImmersiveMQ.addListener === "function") {
  _landscapeImmersiveMQ.addListener(_applyLandscapeImmersiveLayout);
}
_applyLandscapeImmersiveLayout();

// v225.mobile / Phase B (#503): pull-up controls drawer.
//
// On phone widths (≤767px) the Spotify-style bottom bar carries only
// play / scrubber / skip. Everything else — voice swatch, speed,
// skip interval, A↔B, sleep, annotate, 🔖, 📝 — migrates into a
// pull-up drawer that slides up from the bottom. Tap a chevron in
// the player bar to open; tap the grip, the scrim, or Esc to close.
//
// Chip relocation: rather than duplicating markup + handlers, we
// MOVE the actual chip nodes from their original homes into the
// drawer's slots at boot. Event listeners stay attached because
// they're on the element, not its position in the tree. The Phase A
// hide-rule (`#player-card .player-actions > button:not(skip)`)
// stops matching once the chips move out of .player-actions, so
// they re-appear in their new home automatically.
function _phonePullupIsPhone() {
  return window.matchMedia("(max-width: 767px)").matches;
}
// v225.tn92 (#575): live state strip on the right side of each
// pull-up section. Replaces the empty space that used to sit beside
// the chip rows. Called on pull-up open (and on any setting change
// while the drawer is open). Cheap — just reads current values from
// the existing controls.
function _updatePullupState() {
  const playbackEl = document.querySelector('[data-state="playback"]');
  const listeningEl = document.querySelector('[data-state="listening"]');
  const authorEl = document.querySelector('[data-state="author"]');

  // Playback: raw wpm + volume. Skip interval was dropped — it's
  // already on the chip itself ("15s ↻ 15s") so showing it here
  // is duplicate. Rate format changed from "0.94×" multiplier to
  // "170 wpm" — multiplier was confusing because the user adjusts
  // the slider in wpm, not as a 1.0× baseline, and didn't see
  // 170 → 0.94× as the same number. Raw wpm matches the slider
  // value the user actually set.
  if (playbackEl && rateEl && volumeEl) {
    const rate = Number(rateEl.value) || 180;
    const vol = volumeEl.value;
    playbackEl.textContent = `${rate} wpm · ${vol}%`;
  }

  // Listening: clip title lives here (v225fl, #654 — moved back from
  // the phone top bar so that the v225fk Import icon has room). The
  // title is painted by _phonePaintTopTitle, which runs on every
  // clip load + edit. We re-paint here too so opening the drawer
  // mid-session reflects the current clip even if the chain ever
  // gets out of sync. If no clip is loaded the slot stays empty and
  // the :empty CSS rule collapses the row to just the chip strip.
  if (listeningEl) {
    if (!_currentClipId) {
      listeningEl.textContent = "";
      listeningEl.removeAttribute("title");
    } else {
      getClip(_currentClipId)
        .then((clip) => {
          const t = clip ? ((clip.title || "").trim() || "Untitled clip") : "";
          listeningEl.textContent = t;
          if (t) listeningEl.title = t;
          else listeningEl.removeAttribute("title");
        })
        .catch(() => {
          listeningEl.textContent = "";
        });
    }
  }

  // Author: annotation counts on the loaded clip. Skip silently if
  // no clip loaded — the state-strip is hidden via :empty.
  if (authorEl) {
    if (!_currentClipId || !Array.isArray(sentenceSpans)) {
      authorEl.textContent = "";
    } else {
      getClip(_currentClipId)
        .then((clip) => {
          if (!clip || !Array.isArray(clip.annotations)) {
            authorEl.textContent = "";
            return;
          }
          const live = clip.annotations.filter(
            (a) => a && !a.deletedAt && !a.tombstone,
          );
          const flags = live.filter((a) => !a.audio).length;
          const voices = live.filter((a) => a.audio).length;
          const parts = [];
          if (flags) parts.push(`${flags} flag${flags === 1 ? "" : "s"}`);
          if (voices) parts.push(`${voices} voice note${voices === 1 ? "" : "s"}`);
          if (Array.isArray(clip.bookmarks) && clip.bookmarks.length) {
            parts.push(
              `${clip.bookmarks.length} bookmark${
                clip.bookmarks.length === 1 ? "" : "s"
              }`,
            );
          }
          authorEl.textContent = parts.length ? parts.join(" · ") : "—";
        })
        .catch(() => {
          authorEl.textContent = "";
        });
    }
  }
}

function _phonePullupOpen() {
  document.body.dataset.pullup = "open";
  const toggle = document.querySelector(".phone-pullup-toggle");
  if (toggle) toggle.textContent = "⌄";
  // v225.tn92 (#575): refresh state strips on open.
  _updatePullupState();
}
function _phonePullupClose() {
  if (document.body.dataset.pullup) delete document.body.dataset.pullup;
  const toggle = document.querySelector(".phone-pullup-toggle");
  if (toggle) toggle.textContent = "⌃";
}
function _phonePullupToggle() {
  if (document.body.dataset.pullup === "open") _phonePullupClose();
  else _phonePullupOpen();
}
function _phonePullupRelocate() {
  // Only relocate on phone. On desktop the slots stay empty and the
  // drawer is display:none via @media (min-width: 768px).
  if (!_phonePullupIsPhone()) return;

  const playbackSlot = document.querySelector('[data-slot="playback"]');
  const listeningSlot = document.querySelector('[data-slot="listening"]');
  const authorSlot = document.querySelector('[data-slot="author"]');
  if (!playbackSlot || !listeningSlot || !authorSlot) return;

  // Helper: move a node by id into a slot. No-op on missing nodes
  // (so we don't crash if some optional control wasn't rendered).
  const move = (id, slot) => {
    const el = document.getElementById(id);
    if (el && slot && el.parentNode !== slot) slot.appendChild(el);
  };

  // Playback: voice swatch (from hero), speed cycle, skip-interval picker.
  move("voice-trigger", playbackSlot);
  move("speed-btn", playbackSlot);
  move("skip-interval-btn", playbackSlot);

  // Listening: A↔B start/end, sleep timer, repeat mode.
  // v225v4.12: repeat-btn was only in the hero chip strip; phone
  // bypasses the dual-strip pattern (v198), so without this move
  // the Repeat control was unreachable on phone. Slot it next to
  // A↔B + Sleep — they're all "how do I want this clip to keep
  // playing" affordances.
  move("ab-loop-btn", listeningSlot);
  move("ab-loop-clear-btn", listeningSlot);
  move("sleep-btn", listeningSlot);
  move("repeat-btn", listeningSlot);

  // v225.tn43 (#520): if a prior boot had moved annotate-mode-btn
  // or bookmark-add-btn into the Author slot, slide them back to
  // their original .player-actions home (which is hidden via Phase
  // A CSS). Without this, a stale cached client would still see
  // them sitting in the drawer until a hard reload rebuilt the DOM.
  const _legacyChipsToReturn = ["annotate-mode-btn", "bookmark-add-btn"];
  const _origHome = document.querySelector("#player-card .player-actions");
  for (const id of _legacyChipsToReturn) {
    const el = document.getElementById(id);
    if (el && _origHome && el.parentNode !== _origHome) {
      _origHome.appendChild(el);
    }
  }

  // v225.tn47 (#524): Document controls moved into ☰ menu (#524).
  // No relocation needed — the actual buttons stay in
  // .label-row-actions, hidden by CSS (.label-row height:0
  // overflow:hidden), and the ☰ menu dispatches click() on them.
  // .import-menu-wrap stays in its original DOM spot too so the
  // import-menu modal renders via position:fixed when opened.
  // Defensive cleanup: if a previous build relocated any of these
  // into the pull-up, return them home so the dispatch still finds
  // them in their original parent.
  const _origLabelRowActions = document.querySelector(
    "#player-card .card-text .label-row-actions, .card-text .label-row-actions"
  );
  if (_origLabelRowActions) {
    const _toReturn = ["clear-btn", "edit-text", "book-view-toggle"];
    for (const id of _toReturn) {
      const el = document.getElementById(id);
      if (el && el.parentNode !== _origLabelRowActions) {
        _origLabelRowActions.appendChild(el);
      }
    }
    const _importWrap = document.querySelector(".import-menu-wrap");
    if (_importWrap && _importWrap.parentNode !== _origLabelRowActions) {
      _origLabelRowActions.appendChild(_importWrap);
    }
  }

  // Author: just Notes now. (#520)
  //   • annotate-mode-btn removed — the arm-and-apply tag flow in
  //     the bottom tag row auto-enters annotate mode when a chip is
  //     armed, so the manual toggle is dead UI.
  //   • bookmark-add-btn removed — the top-right 🔖 button (#519)
  //     is the user-visible bookmark add now; this row chip
  //     was duplicated reach.
  //   Both buttons stay in their original .player-actions home
  //   (hidden via Phase A CSS); their click() handlers still fire
  //   when dispatched programmatically (the top-right 🔖 dispatches
  //   on #bookmark-add-btn, and arming a tag chip calls
  //   _setAnnotateMode(true) directly).
  move("notes-btn", authorSlot);

  // v225m (#508): Bookmarks slot — relocate #bookmarks-list (the
  // jump rows with [time][note][×]) into the pull-up so it has a
  // proper home instead of leaking into the player card flex row.
  const bookmarksSlot = document.querySelector('[data-slot="bookmarks"]');
  move("bookmarks-list", bookmarksSlot);
  // Re-paint so existing rows render at the new location.
  if (typeof renderBookmarks === "function") {
    renderBookmarks().catch(() => {});
  }

  // v225s (#513): peek handle tab removed per user feedback. The
  // chevron ⌃ button on the bottom player bar (injected below) is
  // the only open affordance; the in-drawer grip closes. Defensively
  // remove any tab left over from a stale cached app.js so a partial
  // SW swap doesn't leave the user with an orphan handle.
  const _staleTab = document.querySelector(".phone-pullup-tab");
  if (_staleTab) _staleTab.remove();

  // Inject the chevron toggle into the bottom player bar if not
  // already present. Tap to open/close the drawer. Placed at order:0
  // so it sits leftmost in the flex-row bar (before the skip-back
  // button at order:1).
  // v225.tn38 (#515): the chevron used to inject into the bottom
  // player bar so the user had a way to open the drawer. The new
  // tag row (#phone-tag-row) above the player has its own chevron
  // now — this injection is redundant. Defensively remove any
  // stale ⌃ left by a previous app.js so cached clients don't end
  // up with two chevrons.
  const playerCard = document.getElementById("player-card");
  const _stalePullToggle = playerCard
    ? playerCard.querySelector(".phone-pullup-toggle")
    : null;
  if (_stalePullToggle) _stalePullToggle.remove();

  // Tap the grip row to close (in addition to the scrim).
  const grip = document.querySelector(".phone-pullup-grip-row");
  if (grip && !grip.dataset.bound) {
    grip.dataset.bound = "1";
    grip.addEventListener("click", _phonePullupClose);
  }
  // v225j: explicit click handler on the real-element scrim. Replaces
  // the body-level document click handler for outside-tap (the scrim
  // now intercepts clicks while open via pointer-events: auto, so we
  // just close on its own click). The body-level handler is still
  // there as belt-and-suspenders but the scrim handler fires first.
  const scrim = document.getElementById("phone-pullup-scrim");
  if (scrim && !scrim.dataset.bound) {
    scrim.dataset.bound = "1";
    scrim.addEventListener("click", (e) => {
      e.stopPropagation();
      _phonePullupClose();
    });
  }
  // Tap on the scrim (the body::before) closes — the scrim is a
  // pseudo-element so we can't bind directly. Use a body-level click
  // that filters out clicks inside the drawer and bottom bar.
  if (!document.body.dataset.pullupScrimBound) {
    document.body.dataset.pullupScrimBound = "1";
    document.addEventListener("click", (e) => {
      if (document.body.dataset.pullup !== "open") return;
      // v225v4.17: walk the composed event path instead of using
      // .contains(e.target). Some chips inside the drawer mutate
      // their own innerHTML during their click handler (e.g.
      // _paintRepeatBtn swaps the SVG markup on every cycle).
      // That detaches the original click target from the DOM, so
      // .contains(e.target) returns false even though the click
      // genuinely happened inside the drawer — and we'd close it.
      // composedPath() snapshots the ancestor chain at event
      // dispatch time, before any mid-handler mutation, so it's
      // immune to innerHTML swaps. Reported: tapping the Repeat
      // chip in the pull-up Listening slot closed the drawer.
      const drawer = document.getElementById("phone-pullup");
      const player = document.getElementById("player-card");
      const path = typeof e.composedPath === "function" ? e.composedPath() : [];
      for (const el of path) {
        if (el === drawer || el === player) return;
      }
      // Fallback for environments without composedPath (very old
      // browsers): fall back to the original contains check.
      if (!path.length) {
        if (drawer && drawer.contains(e.target)) return;
        if (player && player.contains(e.target)) return;
      }
      _phonePullupClose();
    });
    // Esc closes too.
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape" && document.body.dataset.pullup === "open") {
        e.stopPropagation();
        _phonePullupClose();
      }
    });
  }
}
// Run after the DOM is ready + after the existing hero-controls
// migration has settled (v188 moves chips around at boot). app.js
// loads at the end of <body> without defer, so DOMContentLoaded
// has ALREADY fired by the time this script executes — registering
// a listener for it would never fire. Detect readyState and just
// run if the DOM is already parsed.
function _phonePullupBoot() {
  setTimeout(_phonePullupRelocate, 50);
}
if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", _phonePullupBoot);
} else {
  _phonePullupBoot();
}
// Re-relocate if the viewport crosses the phone threshold (e.g.,
// device rotation, devtools resize). Idempotent — the `parentNode`
// check inside `move()` skips already-relocated nodes.
window.addEventListener("resize", () => {
  if (_phonePullupIsPhone()) _phonePullupRelocate();
});

// v223.tn28 (#500): keep the Settings version stamp in sync with the
// actual SW cache name. Previously index.html hardcoded a string
// ("v221e") that drifted because we never updated it on each SW bump
// — testers ended up reporting bugs against stale versions. Reading
// caches.keys() at boot makes the stamp self-updating: whatever the
// currently-installed SW named its cache wins. Falls back to the
// static HTML value if no cache is installed yet (first load) or
// if the browser doesn't expose the Cache API.
async function _stampAppVersion() {
  // v225v4.23 (#828): also keep the hero #header-version-tag in sync —
  // it's the same string sourced from the same place (SW cache name),
  // shown in two surfaces (Settings + header) so the user can read it
  // off without opening a dialog.
  const els = [
    document.getElementById("settings-version-tag"),
    document.getElementById("header-version-tag"),
  ].filter(Boolean);
  if (!els.length) return;
  try {
    if (!("caches" in window)) return;
    const keys = await caches.keys();
    const ours = keys.find((k) => k.startsWith("narrative-shell-"));
    if (ours) {
      const tag = ours.replace("narrative-shell-", "");
      for (const el of els) {
        if (tag && tag !== el.textContent) el.textContent = tag;
      }
    }
  } catch (e) {
    console.info("[version] stamp failed:", e && e.message);
  }
}
// v4.78 (#880): tap-to-unlock on the version pill. 5 taps within 3 s
// flips _diagnosticsUnlocked true and reveals the Admin pane for the
// rest of the session (clears on reload — in-memory only). Matches the
// Android "tap build number to enable developer options" gesture.
// Targets the *parent* of #settings-version-tag (the <p#settings-version>)
// so the whole "Narrative v225v4.78" line is the hit area, not just the
// pill — easier on touch, especially on phone where the pill is small.
//
// Why session-scoped, not persistent: persisting would let a tester
// accidentally unlock during exploration and then have Force update +
// Push debug log forever in their Settings sidebar. The default state
// every reload is "tools hidden" — explicit each time.
(function _wireVersionTapToUnlock() {
  const versionRow = document.getElementById("settings-version");
  if (!versionRow) return;
  let taps = 0;
  let resetTimer = null;
  versionRow.addEventListener("click", () => {
    if (_diagnosticsUnlocked) return; // already unlocked, no-op
    taps += 1;
    if (resetTimer) clearTimeout(resetTimer);
    resetTimer = setTimeout(() => { taps = 0; }, 3000);
    if (taps >= 5) {
      _diagnosticsUnlocked = true;
      taps = 0;
      setStatus(
        "Diagnostics unlocked for this session. " +
        "Admin pane is in the sidebar — Force update, debug log push, and view live there.",
      );
      // Repaint sidebar + pane visibility now that the gate is true.
      // Fire and forget; the whoami fetch is cached so this is fast.
      _refreshAdminSectionsVisibility();
    }
  });
})();
// Run once at boot, then again ~3s later in case the SW installed
// asynchronously after the first read. Cheap (a single Cache API
// call) and means the stamp updates within a few seconds of a SW
// swap landing.
_stampAppVersion();
setTimeout(_stampAppVersion, 3000);
if ("serviceWorker" in navigator) {
  navigator.serviceWorker.addEventListener("controllerchange", _stampAppVersion);
}

// v225.tn31 (#505): "Switch key" button in Settings. The on-call
// scenario: two testers sharing one device (same PWA install) end
// up on the same tenant because the X-Narrative-Key persists in
// localStorage. The second tester opens the app and sees the
// first tester's library because both bearer keys → same tenant
// hash. The fix is to clear the key + clear the local library +
// reload — the next /api/ call 401s and the existing prompt
// flow asks for the new key.
const settingsSwitchKey = document.getElementById("settings-switch-key");
if (settingsSwitchKey) {
  settingsSwitchKey.addEventListener("click", async () => {
    if (settingsSwitchKey.disabled) return;
    const ok = window.confirm(
      "Switch key clears the current API key and wipes the local " +
      "library on this device, then reloads. You'll be prompted " +
      "to paste your own key. Continue?",
    );
    if (!ok) return;
    settingsSwitchKey.disabled = true;
    settingsSwitchKey.textContent = "Switching…";
    try {
      // Drop the bearer key so the next /api/ request triggers the
      // 401-prompt flow (the existing fetch wrapper handles this).
      setApiKey("");

      // Wipe the IndexedDB clips store so the previous tester's
      // library doesn't sit there and clobber the incoming user's
      // on next push. Annotations + voice notes live inside each
      // clip, so this catches them too.
      try {
        const db = await openDB();
        await new Promise((resolve, reject) => {
          const tx = db.transaction(STORE, "readwrite");
          const req = tx.objectStore(STORE).clear();
          req.onsuccess = resolve;
          req.onerror = () => reject(req.error);
          tx.onerror = () => reject(tx.error);
          tx.onabort = () => reject(tx.error);
        });
      } catch (e) {
        console.warn("[switch-key] IDB clear failed:", e);
      }
    } catch (e) {
      console.warn("[switch-key] sweep failed:", e);
    }
    location.reload();
  });
}

// v223.tn29 (#501): "Force update" button in Settings. Nukes every
// SW registration + every Cache API entry, then reloads. This is
// the escape hatch when a phone or installed PWA is stuck on a
// stale SW — common enough during active development that asking
// users to "open DevTools and unregister" wasn't workable. Wipes
// only the SW + caches; localStorage and IndexedDB (i.e. the user's
// library) survive untouched.
const settingsForceUpdate = document.getElementById("settings-force-update");
if (settingsForceUpdate) {
  settingsForceUpdate.addEventListener("click", async () => {
    if (settingsForceUpdate.disabled) return;
    const ok = window.confirm(
      "Force update will wipe the cached app code and reload. " +
      "Your library + annotations stay safe. Continue?",
    );
    if (!ok) return;
    settingsForceUpdate.disabled = true;
    settingsForceUpdate.textContent = "Updating…";
    try {
      // Unregister every SW registration we know about. Each one
      // gets its own waitable so a slow unregister doesn't lose
      // us the reload.
      if ("serviceWorker" in navigator) {
        const regs = await navigator.serviceWorker.getRegistrations();
        await Promise.all(regs.map((r) => r.unregister().catch(() => false)));
      }
      // Then drop every cache the browser knows about for this
      // origin. Don't filter by name — if there's something stale
      // we don't recognize, we want it gone too.
      if ("caches" in window) {
        const keys = await caches.keys();
        await Promise.all(keys.map((k) => caches.delete(k).catch(() => false)));
      }
    } catch (e) {
      console.warn("[force-update] sweep failed:", e);
    }
    // Hard reload — bypass the SW even if a residual controller is
    // still around for the current page lifecycle. `location.reload`
    // with no args is enough now that the SW + caches are gone.
    location.reload();
  });
}

// v225fa (#643): horizontal overflow detection.
//
// User reports being able to scroll right into dead space on desktop
// despite v225ez's overflow-x: clip + .app width override. Instead of
// guessing the cause, instrument it: when horizontal scroll happens
// OR when the document's scrollWidth exceeds clientWidth, walk the
// DOM and log every element whose own scrollWidth exceeds its
// clientWidth (i.e., elements that are wider than their visible box
// and therefore push the page's scrollWidth).
//
// One-shot per session — fires on the first horizontal scroll, then
// disarms so the log doesn't fill with duplicates as the user keeps
// scrolling. They can scroll into the dead space, send the debug
// log, and we'll see the actual culprit.
(() => {
  let armed = true;
  function _overflowSnapshot(trigger) {
    if (!armed) return;
    armed = false;
    try {
      const docEl = document.documentElement;
      const body = document.body;
      const baseline = {
        trigger,
        viewportWidth: window.innerWidth,
        viewportHeight: window.innerHeight,
        docScrollWidth: docEl.scrollWidth,
        docClientWidth: docEl.clientWidth,
        docScrollLeft: docEl.scrollLeft,
        bodyScrollWidth: body.scrollWidth,
        bodyClientWidth: body.clientWidth,
        bodyScrollLeft: body.scrollLeft,
        dpr: window.devicePixelRatio,
        multipane: {
          library: body.dataset.multipaneLibrary || "0",
          author: body.dataset.multipaneAuthor || "0",
        },
        appWidth: (() => {
          const app = document.querySelector(".app");
          if (!app) return null;
          const r = app.getBoundingClientRect();
          return { width: r.width, left: r.left, right: r.right };
        })(),
      };
      _dlog("overflow-x", "snapshot", baseline);

      // Walk the DOM. For each element, compare scrollWidth to clientWidth
      // and also check whether the element's right edge extends past the
      // viewport's right edge (which would push body's scrollWidth).
      const offenders = [];
      const viewportRight = window.innerWidth;
      const all = document.querySelectorAll("*");
      for (const el of all) {
        if (offenders.length > 30) break; // cap so the dlog stays usable
        let pushed = false;
        const reasons = [];
        if (el.scrollWidth > el.clientWidth + 1) {
          reasons.push(
            `scrollWidth=${el.scrollWidth} clientWidth=${el.clientWidth}`,
          );
          pushed = true;
        }
        const r = el.getBoundingClientRect();
        if (r.right > viewportRight + 1 && r.width > 0) {
          // Filter out fixed elements that legitimately use right:0 — they
          // can have right edges AT the viewport (within 1px) but not push
          // scroll. Anything substantially past the edge is suspicious.
          const cs = getComputedStyle(el);
          if (cs.position !== "fixed" || r.right > viewportRight + 4) {
            reasons.push(
              `right=${Math.round(r.right)} viewport=${viewportRight} pos=${cs.position}`,
            );
            pushed = true;
          }
        }
        if (pushed) {
          // Walk up to root to capture an identifier path. Short — the
          // dlog can't carry huge strings well.
          const idParts = [];
          let cur = el;
          while (cur && cur !== document.body && idParts.length < 4) {
            const tag = cur.tagName ? cur.tagName.toLowerCase() : "?";
            const id = cur.id ? `#${cur.id}` : "";
            const cls = cur.className && typeof cur.className === "string"
              ? "." + cur.className.split(/\s+/).slice(0, 2).join(".")
              : "";
            idParts.unshift(tag + id + cls);
            cur = cur.parentElement;
          }
          offenders.push({
            path: idParts.join(" > "),
            reasons,
            rect: {
              width: Math.round(r.width),
              left: Math.round(r.left),
              right: Math.round(r.right),
            },
          });
        }
      }
      _dlog("overflow-x", "offenders", {
        count: offenders.length,
        items: offenders,
      });
    } catch (e) {
      _dlog("overflow-x", "snapshot failed", { error: String(e) });
    }
  }

  // Re-arm helper exposed for manual re-trigger from devtools / chip taps.
  window.__narrativeOverflowDebug = () => {
    armed = true;
    _overflowSnapshot("manual");
  };

  // Auto-fire on first horizontal scroll. The scroll event is on window
  // for documentElement scrolls; both window scroll and body scroll cover
  // it. Use {passive: true} so we don't interfere with smooth scrolling.
  window.addEventListener(
    "scroll",
    () => {
      const sl = document.documentElement.scrollLeft || document.body.scrollLeft || 0;
      if (sl > 0) _overflowSnapshot("scroll");
    },
    { passive: true, capture: true },
  );
  // Also auto-fire at boot if the document already overflows horizontally —
  // this catches the case where the overflow exists before any scroll happens.
  // Delay a tick to let layout settle.
  setTimeout(() => {
    const docEl = document.documentElement;
    if (docEl.scrollWidth > docEl.clientWidth + 1) {
      _overflowSnapshot("boot-overflow");
    }
  }, 500);
})();
